function act(obs, mem) {
  var DEG = Math.PI / 180, RAD = 180 / Math.PI;
  var RAYA = [-80, -60, -40, -20, 0, 20, 40, 60, 80];
  var GN = 80, GC = 5, WB = 0.6, DT = 0.1;

  function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
  function wrap(a) { a = (a + 180) % 360; if (a < 0) a += 360; return a - 180; }
  function dd(x1, y1, x2, y2) { var dx = x2 - x1, dy = y2 - y1; return Math.sqrt(dx * dx + dy * dy); }
  function ci(v) { var c = Math.floor(v / GC); return c < 0 ? 0 : (c >= GN ? GN - 1 : c); }
  function cellOf(x, y) { return ci(y) * GN + ci(x); }

  /* =========================== INIT =========================== */
  if (!mem.init) {
    mem.init = 1;
    mem.clock = 0;
    mem.px = obs.x; mem.py = obs.y;
    mem.head = obs.heading;
    mem.lastGX = obs.x; mem.lastGY = obs.y;
    mem.lastPX = obs.x; mem.lastPY = obs.y;
    mem.gpsAge = 0;
    mem.gainL = 3.0; mem.gainR = 3.0;
    mem.biasL = 0; mem.biasR = 0;
    mem.wantL = 0; mem.wantR = 0;
    mem.lastVL = 0; mem.lastVR = 0;
    mem.dz = 0.08;
    mem.base = { x: obs.x, y: obs.y };
    mem.cap = 5;
    mem.sites = [];
    mem.grid = new Float32Array(GN * GN);
    mem.gseen = new Uint8Array(GN * GN);
    mem.eDrive = 0.0008;
    mem.eIdle = 0.0005;
    mem.eDrill = 0.004;
    mem.avgSpeed = 2.0;
    mem.battPrev = (typeof obs.battery === 'number') ? obs.battery : 1;
    mem.mode = 'plan';
    mem.trip = [];
    mem.path = null; mem.pathIdx = 0; mem.pathT = -999; mem.pathTX = 0; mem.pathTY = 0;
    mem.escape = 0; mem.escapeDir = 1;
    mem.winDist = 0; mem.winT = 0; mem.stuckN = 0;
    mem.search = null;
    mem.sampX = 0; mem.sampY = 0;
    mem.sampleRef = null;
    mem.drillHeld = 0; mem.lostT = 0;
    mem.sciMax = 1e-6;
    mem.minValue = 0.5;
    mem.slip = 0;
    mem.totDist = 0;
    mem.pending = null; mem.pendingE = 0; mem.pendingT = 0; mem.dockT = -999;
    mem.targetKind = 'base';
    mem.targetX = obs.x; mem.targetY = obs.y; mem.targetRad = 2.2;
    mem.targetRef = null;
    mem.exploreList = null; mem.exploreIdx = 0;
    if (obs.mission) {
      var M = obs.mission;
      if (M.base && typeof M.base.x === 'number') mem.base = { x: M.base.x, y: M.base.y };
      if (M.capacity) mem.cap = M.capacity;
      var hs = M.hints || [];
      for (var hi = 0; hi < hs.length; hi++) {
        if (typeof hs[hi].x !== 'number' || typeof hs[hi].y !== 'number') continue;
        mem.sites.push({
          x: hs[hi].x, y: hs[hi].y, ox: hs[hi].x, oy: hs[hi].y,
          est: (typeof hs[hi].estimate === 'number' && hs[hi].estimate > 0 ? hs[hi].estimate : 1),
          sampled: 0, dead: 0, found: 0, searched: 0
        });
      }
    }
  }

  /* =========================== SENSES =========================== */
  var wl = (typeof obs.wheelLeft === 'number' && isFinite(obs.wheelLeft)) ? obs.wheelLeft : 0;
  var wr = (typeof obs.wheelRight === 'number' && isFinite(obs.wheelRight)) ? obs.wheelRight : 0;
  var vMeas = (wl + wr) / 2;
  var wMeas = (wr - wl) / WB;
  var pitch = (typeof obs.pitch === 'number' && isFinite(obs.pitch)) ? obs.pitch : 0;
  var sci = (typeof obs.science === 'number' && isFinite(obs.science)) ? obs.science : 0;
  var battery = (typeof obs.battery === 'number' && isFinite(obs.battery)) ? obs.battery : mem.battPrev;
  var timeLeft = (typeof obs.timeLeft === 'number' && isFinite(obs.timeLeft)) ? obs.timeLeft : 1200;
  var carried = (typeof obs.carried === 'number') ? obs.carried : 0;
  var dsec = (typeof obs.drilling === 'number' && isFinite(obs.drilling)) ? obs.drilling : 0;
  mem.clock += DT;

  /* motor gain identification */
  if (Math.abs(mem.wantL) > 0.28 && Math.abs(wl) > 0.22 && mem.wantL * wl > 0) {
    var gl2 = Math.abs(wl / mem.wantL);
    if (gl2 > 0.1 && gl2 < 15) mem.gainL = clamp(mem.gainL * 0.98 + gl2 * 0.02, 0.12, 10);
  }
  if (Math.abs(mem.wantR) > 0.28 && Math.abs(wr) > 0.22 && mem.wantR * wr > 0) {
    var gr2 = Math.abs(wr / mem.wantR);
    if (gr2 > 0.1 && gr2 < 15) mem.gainR = clamp(mem.gainR * 0.98 + gr2 * 0.02, 0.12, 10);
  }

  /* heading estimate (compass + wheel gyro, jump guarded) */
  mem.head = wrap(mem.head + wMeas * DT * RAD);
  var hErr = wrap(obs.heading - mem.head);
  mem.head = wrap(mem.head + (Math.abs(hErr) < 30 ? 0.35 : 0.02) * hErr);

  /* position estimate (GPS when fresh, odometry otherwise) */
  var mg = dd(obs.x, obs.y, mem.lastGX, mem.lastGY);
  if (mg > 0.02 && mg < 30) {
    mem.px = obs.x; mem.py = obs.y;
    mem.lastGX = obs.x; mem.lastGY = obs.y;
    mem.gpsAge = 0;
  } else {
    mem.gpsAge += DT;
    mem.px += vMeas * DT * Math.cos(mem.head * DEG);
    mem.py += vMeas * DT * Math.sin(mem.head * DEG);
    if (mg > 0.0005) { mem.lastGX = obs.x; mem.lastGY = obs.y; mem.gpsAge = 0; }
  }
  var moved = dd(mem.px, mem.py, mem.lastPX, mem.lastPY);
  mem.lastPX = mem.px; mem.lastPY = mem.py;
  mem.totDist += moved;
  var instSpeed = moved / DT;
  mem.slip = clamp((Math.abs(vMeas) > 0.6 && instSpeed < 0.5 * Math.abs(vMeas)) ? mem.slip + 0.3 : mem.slip - 0.08, 0, 2);

  /* energy model identification */
  var dB = battery - mem.battPrev;
  var cons = ((typeof obs.solar === 'number' && isFinite(obs.solar)) ? obs.solar : 0) - dB / DT;
  if (cons > -0.05 && cons < 2) {
    if (moved > 0.02) {
      var epm = cons * DT / moved;
      if (epm > -0.002 && epm < 0.06) mem.eDrive = clamp(mem.eDrive * 0.97 + epm * 0.03, 0.00002, 0.02);
      mem.avgSpeed = clamp(mem.avgSpeed * 0.985 + instSpeed * 0.015, 0.25, 3.2);
    } else if (dsec > 0) {
      mem.eDrill = clamp(mem.eDrill * 0.985 + cons * 0.015, 0.0001, 0.1);
    } else {
      mem.eIdle = clamp(mem.eIdle * 0.99 + cons * 0.01, 0.00001, 0.1);
    }
  }
  mem.battPrev = battery;

  /* =========================== OCCUPANCY GRID =========================== */
  for (var gi = 0; gi < 9; gi++) {
    var rvv = (obs.rays && typeof obs.rays[gi] === 'number' && isFinite(obs.rays[gi])) ? obs.rays[gi] : -1;
    if (rvv < 0.3) continue;
    var ga = (obs.heading + RAYA[gi]) * DEG;
    var gcos = Math.cos(ga), gsin = Math.sin(ga);
    var glim = Math.min(rvv, 14.9);
    if (rvv < 14.7) {
      var gci = cellOf(mem.px + rvv * gcos, mem.py + rvv * gsin);
      mem.grid[gci] = Math.min(1, mem.grid[gci] + 0.22);
      mem.gseen[gci] = 1;
    }
    for (var gd = 3; gd < glim - 1.5; gd += 3) {
      var gci2 = cellOf(mem.px + gd * gcos, mem.py + gd * gsin);
      mem.grid[gci2] = Math.max(0, mem.grid[gci2] - 0.1);
      mem.gseen[gci2] = 1;
    }
  }
  if (obs.bumped) {
    var bci = cellOf(mem.px + 1.8 * Math.cos(mem.head * DEG), mem.py + 1.8 * Math.sin(mem.head * DEG));
    mem.grid[bci] = Math.min(1, mem.grid[bci] + 0.5);
    mem.gseen[bci] = 1;
    if (mem.escape < 0.8) mem.escape = 1.4;
    mem.path = null;
  }

  /* =========================== SITE BOOKKEEPING =========================== */
  function registerSite(x, y, val) {
    var i, s, d, best = null, bd = 14;
    for (i = 0; i < mem.sites.length; i++) {
      s = mem.sites[i];
      if (s.sampled || s.dead || !s.found) continue;
      d = dd(x, y, s.x, s.y);
      if (d < bd) { bd = d; best = s; }
    }
    if (!best) {
      bd = 27;
      for (i = 0; i < mem.sites.length; i++) {
        s = mem.sites[i];
        if (s.sampled || s.dead || s.found) continue;
        d = dd(x, y, s.ox, s.oy);
        if (d < bd) { bd = d; best = s; }
      }
    }
    if (best) {
      best.x = x; best.y = y; best.found = 1;
      if (typeof val === 'number' && val > 0) best.est = val;
    } else {
      best = { x: x, y: y, ox: x, oy: y, est: (typeof val === 'number' && val > 0 ? val : 1), sampled: 0, dead: 0, found: 1, searched: 0 };
      mem.sites.push(best);
    }
    return best;
  }

  var siteNow = null;
  if (obs.site && typeof obs.site.distance === 'number' && isFinite(obs.site.distance) && obs.site.distance < 8.5) {
    var sang = (mem.head + (typeof obs.site.bearing === 'number' ? obs.site.bearing : 0)) * DEG;
    var sx = mem.px + obs.site.distance * Math.cos(sang);
    var sy = mem.py + obs.site.distance * Math.sin(sang);
    siteNow = {
      x: sx, y: sy, d: obs.site.distance,
      v: (typeof obs.site.value === 'number' && isFinite(obs.site.value)) ? obs.site.value : 1
    };
    registerSite(sx, sy, siteNow.v);
  }
  if (sci > mem.sciMax) mem.sciMax = sci;
  var sciThr = Math.max(1e-9, mem.sciMax * 0.004);

  /* base position (beacon refines it) */
  var dBase = dd(mem.px, mem.py, mem.base.x, mem.base.y);
  var dBaseTrue = dBase;
  if (obs.beacon && typeof obs.beacon.distance === 'number' && isFinite(obs.beacon.distance) && obs.beacon.distance < 20) {
    var bang = (mem.head + (typeof obs.beacon.bearing === 'number' ? obs.beacon.bearing : 0)) * DEG;
    var bx = mem.px + obs.beacon.distance * Math.cos(bang);
    var by = mem.py + obs.beacon.distance * Math.sin(bang);
    mem.base.x += (bx - mem.base.x) * 0.012;
    mem.base.y += (by - mem.base.y) * 0.012;
    dBase = dd(mem.px, mem.py, mem.base.x, mem.base.y);
    dBaseTrue = obs.beacon.distance;
  }

  /* =========================== PLANNING =========================== */
  function tripLen(tr) {
    if (!tr || !tr.length) return 0;
    var d = dd(mem.px, mem.py, tr[0].x, tr[0].y);
    for (var i = 1; i < tr.length; i++) d += dd(tr[i - 1].x, tr[i - 1].y, tr[i].x, tr[i].y);
    d += dd(tr[tr.length - 1].x, tr[tr.length - 1].y, mem.base.x, mem.base.y);
    return d;
  }
  function tripTime(tr) {
    return tripLen(tr) / Math.max(0.55, mem.avgSpeed) * 1.15 + tr.length * 10 + 14;
  }
  function tripEnergy(tr) {
    return tripLen(tr) * mem.eDrive * 1.15 + tripTime(tr) * mem.eIdle + tr.length * 6.5 * mem.eDrill + 0.025;
  }
  function buildTrip() {
    var cands = [], i;
    for (i = 0; i < mem.sites.length; i++) {
      var s = mem.sites[i];
      if (s.sampled || s.dead) continue;
      cands.push(s);
    }
    if (!cands.length) { mem.minValue = 0.5; return []; }
    var spd = Math.max(0.55, mem.avgSpeed);
    var maxSites = mem.cap;
    var timeBudget = timeLeft - 35;
    var energyBudget = battery * 0.82;
    var trip = [], rem = cands.slice();
    while (trip.length < maxSites && rem.length) {
      var best = null, bestScore = -1;
      for (var a = 0; a < rem.length; a++) {
        var c = rem[a];
        for (var p = 0; p <= trip.length; p++) {
          var t2 = trip.slice(); t2.splice(p, 0, c);
          var d0 = tripLen(trip), d1 = tripLen(t2);
          var dT = (d1 - d0) / spd + 9.5;
          if (dT <= 0.5) continue;
          var score = c.est / dT;
          if (score > bestScore) { bestScore = score; best = { c: c, p: p, d1: d1, t2: t2 }; }
        }
      }
      if (!best) break;
      var tt = best.d1 / spd * 1.15 + 10 * best.t2.length + 14;
      var ee = best.d1 * mem.eDrive * 1.15 + tt * mem.eIdle + 6.5 * best.t2.length * mem.eDrill + 0.025;
      if (tt > timeBudget || ee > energyBudget) break;
      trip = best.t2;
      rem.splice(rem.indexOf(best.c), 1);
    }
    var sum = 0;
    for (var q = 0; q < trip.length; q++) sum += trip[q].est;
    mem.minValue = trip.length ? Math.max(0.25, 0.4 * sum / trip.length) : 0.5;
    return trip;
  }

  /* =========================== PATHING =========================== */
  function lineClear(x1, y1, x2, y2) {
    var d = dd(x1, y1, x2, y2);
    if (d < 4) return true;
    var n = Math.ceil(d / 3);
    var i0 = Math.max(1, Math.round(n * 4 / d));
    for (var i = i0; i <= n; i++) {
      var x = x1 + (x2 - x1) * i / n, y = y1 + (y2 - y1) * i / n;
      if (mem.grid[cellOf(x, y)] > 0.55) return false;
    }
    return true;
  }

  function astar(sx, sy, tx, ty) {
    var n = GN * GN;
    var gsc = new Float32Array(n);
    var came = new Int32Array(n);
    var cl = new Uint8Array(n);
    for (var i = 0; i < n; i++) { gsc[i] = 1e18; came[i] = -1; }
    var sN = cellOf(sx, sy), gN = cellOf(tx, ty);
    var gx0 = gN % GN, gy0 = (gN - gx0) / GN;
    var hp = [], hv = [], hn = 0;
    function push(nd, f) {
      var k = hn++;
      hp[k] = nd; hv[k] = f;
      while (k > 0) {
        var p = (k - 1) >> 1;
        if (hv[p] <= hv[k]) break;
        var tn = hp[p], tv = hv[p];
        hp[p] = hp[k]; hv[p] = hv[k];
        hp[k] = tn; hv[k] = tv;
        k = p;
      }
    }
    function pop() {
      var r = hp[0];
      hn--;
      if (hn > 0) {
        hp[0] = hp[hn]; hv[0] = hv[hn];
        var k = 0;
        for (; ;) {
          var l = 2 * k + 1, rr = l + 1, m = k;
          if (l < hn && hv[l] < hv[m]) m = l;
          if (rr < hn && hv[rr] < hv[m]) m = rr;
          if (m === k) break;
          var tn = hp[m], tv = hv[m];
          hp[m] = hp[k]; hv[m] = hv[k];
          hp[k] = tn; hv[k] = tv;
          k = m;
        }
      }
      return r;
    }
    function hcost(nd) {
      var nx = nd % GN, ny = (nd - nx) / GN;
      var ax = nx - gx0, ay = ny - gy0;
      return Math.sqrt(ax * ax + ay * ay);
    }
    gsc[sN] = 0;
    push(sN, hcost(sN));
    var found = false, iter = 0;
    while (hn > 0 && iter < 45000) {
      iter++;
      var cur = pop();
      if (cur === gN) { found = true; break; }
      if (cl[cur]) continue;
      cl[cur] = 1;
      var cxp = cur % GN, cyp = (cur - cxp) / GN;
      for (var dy = -1; dy <= 1; dy++) {
        for (var dx = -1; dx <= 1; dx++) {
          if (dx === 0 && dy === 0) continue;
          var nx2 = cxp + dx, ny2 = cyp + dy;
          if (nx2 < 0 || ny2 < 0 || nx2 >= GN || ny2 >= GN) continue;
          var nd = ny2 * GN + nx2;
          if (cl[nd]) continue;
          var step = (dx !== 0 && dy !== 0) ? 1.4142 : 1;
          var cc = 1 + 10 * mem.grid[nd] + (mem.gseen[nd] ? 0 : 0.3);
          var ng = gsc[cur] + step * cc;
          if (ng < gsc[nd]) {
            gsc[nd] = ng; came[nd] = cur;
            push(nd, ng + hcost(nd));
          }
        }
      }
    }
    if (!found) return null;
    var path = [];
    var c = gN, guard = 0;
    while (c !== -1 && guard++ < 20000) {
      var cx3 = c % GN, cy3 = (c - cx3) / GN;
      path.push({ x: cx3 * GC + GC / 2, y: cy3 * GC + GC / 2 });
      c = came[c];
    }
    path.reverse();
    if (path.length) path[path.length - 1] = { x: tx, y: ty };
    return path;
  }

  function computePath(tx, ty) {
    if (lineClear(mem.px, mem.py, tx, ty)) {
      mem.path = [{ x: tx, y: ty }]; mem.pathIdx = 0;
      return;
    }
    var p = astar(mem.px, mem.py, tx, ty);
    if (!p || p.length < 2) {
      mem.path = [{ x: tx, y: ty }]; mem.pathIdx = 0;
      return;
    }
    var simp = [p[0]];
    var i = 0, guard = 0;
    while (i < p.length - 1 && guard++ < 400) {
      var j = p.length - 1;
      while (j > i + 1 && !lineClear(p[i].x, p[i].y, p[j].x, p[j].y)) j--;
      simp.push(p[j]);
      i = j;
    }
    mem.path = simp; mem.pathIdx = 0;
  }

  /* =========================== ACTUATION =========================== */
  function setWheels(vL, vR) {
    var mm = Math.max(Math.abs(vL), Math.abs(vR));
    if (mm > 3.0) { vL *= 3.0 / mm; vR *= 3.0 / mm; }
    var gL = Math.max(0.12, mem.gainL), gR = Math.max(0.12, mem.gainR);
    if (Math.abs(vL - mem.lastVL) > 0.9) mem.biasL *= 0.55;
    if (Math.abs(vR - mem.lastVR) > 0.9) mem.biasR *= 0.55;
    mem.lastVL = vL; mem.lastVR = vR;
    var eL = vL - wl, eR = vR - wr;
    mem.biasL = clamp(mem.biasL + 0.022 * eL / gL, -0.45, 0.45);
    mem.biasR = clamp(mem.biasR + 0.022 * eR / gR, -0.45, 0.45);
    var cL = clamp(vL / gL + 0.55 * eL / gL + mem.biasL, -1, 1);
    var cR = clamp(vR / gR + 0.55 * eR / gR + mem.biasR, -1, 1);
    if (Math.abs(vL) > 0.18 && Math.abs(cL) < mem.dz) cL = (vL > 0 ? 1 : -1) * mem.dz;
    if (Math.abs(vR) > 0.18 && Math.abs(cR) < mem.dz) cR = (vR > 0 ? 1 : -1) * mem.dz;
    mem.wantL = cL; mem.wantR = cR;
    return [cL, cR];
  }

  function refOf(x, y) {
    var best = null, bd = 16;
    for (var i = 0; i < mem.sites.length; i++) {
      var s = mem.sites[i];
      if (s.sampled || s.dead) continue;
      var d = dd(x, y, s.x, s.y);
      if (d < bd) { bd = d; best = s; }
    }
    return best;
  }

  function beginSample(x, y, val) {
    var ref = registerSite(x, y, val);
    mem.sampX = x; mem.sampY = y;
    mem.sampleRef = ref;
    mem.mode = 'sample';
    mem.drillHeld = 0; mem.lostT = 0;
    mem.search = null; mem.path = null;
    mem.escape = 0;
  }

  function beginSearch() {
    var s = mem.targetRef || refOf(mem.targetX, mem.targetY);
    if (!s) {
      s = { x: mem.targetX, y: mem.targetY, ox: mem.targetX, oy: mem.targetY, est: 1, sampled: 0, dead: 0, found: 0, searched: 0 };
      mem.sites.push(s);
      mem.targetRef = s;
    }
    var wps = [{ x: s.ox, y: s.oy }];
    for (var k = 0; k < 8; k++) {
      var a = k * 45 * DEG;
      wps.push({ x: s.ox + 15 * Math.cos(a), y: s.oy + 15 * Math.sin(a) });
    }
    mem.search = { wps: wps, idx: 0, t0: mem.clock, s: s, ring2: 0 };
    mem.mode = 'search';
    mem.path = null;
  }

  /* =========================== STATE MACHINE =========================== */
  var vD = 0, wD = 0, drillCmd = false, handled = false;
  var mode = mem.mode;

  /* -------- SAMPLE -------- */
  if (mode === 'sample') {
    if (siteNow) {
      mem.sampX = siteNow.x; mem.sampY = siteNow.y;
      registerSite(siteNow.x, siteNow.y, siteNow.v);
      mem.lostT = 0;
    } else {
      mem.lostT += DT;
    }
    var sdx = mem.sampX - mem.px, sdy = mem.sampY - mem.py;
    var sdd = Math.sqrt(sdx * sdx + sdy * sdy);
    var sdist = siteNow ? siteNow.d : sdd;
    var sgh = Math.atan2(sdy, sdx) * RAD;
    var serr = wrap(sgh - mem.head);
    if (sdist > 1.15) {
      vD = clamp(0.5 * (sdist - 0.6), 0, 0.4);
      wD = clamp(0.05 * serr, -0.5, 0.5);
    } else {
      vD = clamp(0.3 * (sdd - 0.3), -0.09, 0.09);
      wD = clamp(0.03 * serr, -0.16, 0.16);
    }
    if (sdist < 1.45 && Math.abs(vMeas) < 0.11) {
      drillCmd = true;
      mem.drillHeld += DT;
    } else {
      mem.drillHeld = 0;
    }
    if (dsec >= 6.05 || mem.drillHeld >= 6.5) {
      if (mem.sampleRef) mem.sampleRef.sampled = 1;
      mem.sampleRef = null;
      mem.mode = 'plan'; mode = 'plan';
      mem.path = null; mem.search = null;
      drillCmd = false; vD = 0; wD = 0;
      mem.drillHeld = 0;
    } else if (mem.lostT > 8 && dsec < 0.35) {
      mem.mode = 'plan'; mode = 'plan';
      mem.sampleRef = null; mem.path = null;
      vD = 0; wD = 0;
    }
    handled = true;
  }

  if (!handled) {
    /* -------- return-home pressure -------- */
    var eToBase = dBase * mem.eDrive + 12 * mem.eIdle + 0.02;
    var tToBase = dBase / Math.max(0.55, mem.avgSpeed) * 1.35 + 15;
    var needReturn = false;
    if (battery < eToBase * 1.8 + 0.035) needReturn = true;
