        var dd = Math.sqrt((s.x-x)*(s.x-x) + (s.y-y)*(s.y-y));
        var dRet = Math.sqrt((s.x-mem.bx)*(s.x-mem.bx) + (s.y-mem.by)*(s.y-mem.by));
        if (dd/1.5 + (s.f ? 10 : 35) + dRet/1.5 + 35 > tl - 30) continue;
        var sc = s.v / (dd/1.5 + 8 + (s.f ? 0 : 20));
        if (sc > bs) { bs = sc; bi = i; }
      }
      if (bi >= 0 && ca < mem.cap) {
        mem.ti = bi; mem.tx = mem.sites[bi].x; mem.ty = mem.sites[bi].y;
        mem.st = 1; mem.gT = 0;
      } else if (ca > 0) {
        mem.st = 4; mem.tx = mem.bx; mem.ty = mem.by;
      } else if (tl > 150) {
        var ei = -1;
        for (var i = 0; i < mem.sites.length; i++) {
          if (!mem.sites[i].s && !mem.sites[i].d && !mem.sites[i].f) { ei = i; break; }
        }
        if (ei >= 0) {
          mem.ti = ei; mem.tx = mem.sites[ei].x; mem.ty = mem.sites[ei].y;
          mem.st = 7; mem.gT = 0;
        } else {
          var ang = mem.t * 0.12;
          var rad = Math.min(170, 50 + mem.t * 0.1);
          mem.tx = Math.max(15, Math.min(385, mem.bx + rad * Math.cos(ang)));
          mem.ty = Math.max(15, Math.min(385, mem.by + rad * Math.sin(ang)));
          mem.st = 7; mem.gT = 0;
        }
      } else {
        mem.st = 4; mem.tx = mem.bx; mem.ty = mem.by;
      }
      break;

    case 1:
      mem.gT += 0.1;
      var s = mem.sites[mem.ti];
      if (!s || s.s || s.d) { mem.st = 0; break; }
      if (s.f) {
        var sd = Math.sqrt((s.x-x)*(s.x-x) + (s.y-y)*(s.y-y));
        if (sd < 1.5 && Math.abs(vAct) < 0.15) { mem.st = 3; mem.smpT = 0; break; }
        mem.tx = s.x; mem.ty = s.y;
      } else {
        var sd = Math.sqrt((s.x-x)*(s.x-x) + (s.y-y)*(s.y-y));
        if (sd < 18) { mem.st = 2; mem.srchT = 0; break; }
      }
      if (mem.gT > 150) { s.a++; if (s.a >= 2) s.d = 1; mem.st = 0; }
      break;

    case 2:
      var s = mem.sites[mem.ti];
      if (!s) { mem.st = 0; break; }
      if (s.f) { mem.st = 1; break; }
      mem.srchT += 0.1;
      if (mem.srchT > 70) { s.a++; if (s.a >= 2) s.d = 1; mem.st = 0; break; }
      var ang = mem.srchT * 0.35;
      var rad = 3 + mem.srchT * 0.5;
      mem.tx = Math.max(10, Math.min(390, s.x + rad * Math.cos(ang)));
      mem.ty = Math.max(10, Math.min(390, s.y + rad * Math.sin(ang)));
      break;

    case 3:
      DR = true; mem.smpT += 0.1;
      var s = mem.sites[mem.ti];
      if (s && s.f) {
        var sd = Math.sqrt((s.x-x)*(s.x-x) + (s.y-y)*(s.y-y));
        if (sd > 1.3) { DR = false; mem.st = 1; break; }
        if (Math.abs(pitch) > 4) {
          if (pitch > 0) { L = DZ; R = DZ; }
          else { L = -DZ; R = -DZ; }
        }
      }
      if (drl >= 5.9) { if (s) s.s = 1; mem.st = 0; }
      else if (mem.smpT > 20) { mem.st = 0; }
      break;

    case 4:
      if (db < 3) { mem.st = 5; mem.dckT = 0; }
      break;

    case 5:
      mem.dckT += 0.1;
      if (ca === 0 && (bt > 0.5 || mem.dckT > 25 || tl < 60)) mem.st = 0;
      else if (mem.dckT > 35) mem.st = 0;
      break;

    case 6:
      mem.esc += 0.1;
      if (mem.esc < 3.5) { L = -1; R = -1; }
      else if (mem.esc < 6) {
        var dir = ((mem.escN % 2 === 0) ? 1 : -1) * (mem.escD || 1);
        if (dir > 0) { L = -0.7; R = 0.7; }
        else { L = 0.7; R = -0.7; }
      } else if (mem.esc < 9) { L = 0.85; R = 0.85; }
      else { mem.st = 0; }
      break;

    case 7:
      mem.gT += 0.1;
      if (ca < mem.cap) {
        for (var i = 0; i < mem.sites.length; i++) {
          var s = mem.sites[i];
          if (s.f && !s.s && !s.d) {
            var sd = Math.sqrt((s.x-x)*(s.x-x) + (s.y-y)*(s.y-y));
            if (sd < 25) {
              mem.ti = i; mem.tx = s.x; mem.ty = s.y;
              mem.st = 1; mem.gT = 0; break;
            }
          }
        }
        if (mem.st === 1) break;
      }
      var dd = Math.sqrt((mem.tx-x)*(mem.tx-x) + (mem.ty-y)*(mem.ty-y));
      if (dd < 18) { mem.st = 2; mem.srchT = 0; }
      if (mem.gT > 150) { mem.st = 0; }
      break;
  }

  // Navigation
  if (mem.st === 1 || mem.st === 2 || mem.st === 4 || mem.st === 7) {
    if (mem.st === 1 && mem.ti >= 0 && mem.ti < mem.sites.length) {
      var s = mem.sites[mem.ti];
      if (s) { mem.tx = s.x; mem.ty = s.y; }
    }
    var tx = (mem.st === 4) ? mem.bx : mem.tx;
    var ty = (mem.st === 4) ? mem.by : mem.ty;
    tx = Math.max(10, Math.min(390, tx));
    ty = Math.max(10, Math.min(390, ty));

    var dd = Math.sqrt((tx-x)*(tx-x) + (ty-y)*(ty-y));
    var dh = Math.atan2(ty-y, tx-x) * RD;
    var he = dh - h;
    while (he > 180) he -= 360;
    while (he < -180) he += 360;

    var handled = false;
    if (mem.st === 1 && mem.ti >= 0 && mem.ti < mem.sites.length) {
      var s = mem.sites[mem.ti];
      if (s && s.f) {
        var sd = Math.sqrt((s.x-x)*(s.x-x) + (s.y-y)*(s.y-y));
        if (sd < 3) {
          handled = true;
          if (sd < 1.5) {
            if (Math.abs(vAct) > 0.1) { L = -DZ; R = -DZ; }
            else { L = 0; R = 0; }
          } else {
            var dh2 = Math.atan2(s.y-y, s.x-x) * RD;
            var he2 = dh2 - h;
            while (he2 > 180) he2 -= 360;
            while (he2 < -180) he2 += 360;
            if (Math.abs(he2) > 30) {
              if (he2 > 0) { L = -DZ; R = DZ; }
              else { L = DZ; R = -DZ; }
            } else {
              var t2 = Math.max(-0.3, Math.min(0.3, he2 * 0.005));
              L = DZ - t2; R = DZ + t2;
              if (L < DZ) L = DZ;
              if (R < DZ) R = DZ;
            }
          }
        }
      }
    }

    if (!handled) {
      var fwdR = rays[4];
      var lS = rays[5]+rays[6]+rays[7]+rays[8];
      var rS = rays[0]+rays[1]+rays[2]+rays[3];
      var adjHe = he;
      if (fwdR < 6) {
        adjHe += (lS > rS ? 1 : -1) * 25 * (1 - fwdR/6);
      }
      if (mem.turnMode === 0 && Math.abs(adjHe) > 30) mem.turnMode = 1;
      else if (mem.turnMode === 1 && Math.abs(adjHe) < 10) mem.turnMode = 0;

      if (mem.turnMode === 1) {
        if (adjHe > 0) { L = -0.5; R = 0.5; }
        else { L = 0.5; R = -0.5; }
      } else {
        var fwd = 0.8;
        if (Math.abs(adjHe) > 15) fwd = 0.55;
        if (dd < 15) fwd = Math.min(fwd, DZ + dd * 0.03);
        if (dd < 3) fwd = DZ;
        if (fwdR < 5) fwd = Math.min(fwd, 0.55);
        if (fwdR < 2) fwd = DZ;
        var t = adjHe * 0.005;
        L = fwd - t;
        R = fwd + t;
      }
    }

    if (L > 0 && L < DZ) L = DZ;
    if (R > 0 && R < DZ) R = DZ;
    if (L < 0 && L > -DZ) L = -DZ;
    if (R < 0 && R > -DZ) R = -DZ;
  }

  L = Math.max(-1, Math.min(1, L));
  R = Math.max(-1, Math.min(1, R));
  return {left: L, right: R, drill: DR};
}

function act(obs, mem) {
  var D = Math.PI / 180, RD = 180 / Math.PI, WB = 0.6;

  function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
  function w180(a) { return ((a % 360) + 540) % 360 - 180; }
  function d2(x1, y1, x2, y2) { var dx = x2 - x1, dy = y2 - y1; return Math.sqrt(dx * dx + dy * dy); }

  // ===== INIT =====
  if (!mem.init) {
    mem.init = 1;
    mem.bx = isFinite(obs.x) ? obs.x : 200;
    mem.by = isFinite(obs.y) ? obs.y : 200;
    mem.cap = 5;
    mem.sites = [];
    mem.ph = 'cal';
    mem.ct = 0;
    mem.gL = 1.4;
    mem.gR = 1.0;
    mem.dzL = 0.3;
    mem.dzR = 0.3;
    mem.ti = -1;
    mem.goT = 0;
    mem.srchT = 0;
    mem.smpT = 0;
    mem.dckT = 0;
    mem.escT = 0;
    mem.escD = 1;
    mem.stuck = 0;
    mem.tick = 0;
    mem.hBias = 0;
    mem.px = mem.bx;
    mem.py = mem.by;
    mem.nTrip = 0;
    mem.drillOn = 0;
    if (obs.mission) {
      var M = obs.mission;
      if (M.base && isFinite(M.base.x)) { mem.bx = M.base.x; mem.by = M.base.y; }
      if (M.capacity) mem.cap = M.capacity;
      var hs = M.hints || [];
      for (var i = 0; i < hs.length; i++) {
        if (isFinite(hs[i].x) && isFinite(hs[i].y)) {
          mem.sites.push({
            x: hs[i].x, y: hs[i].y,
            v: hs[i].estimate > 0 ? hs[i].estimate : 1,
            f: 0, s: 0, d: 0, tr: 0
          });
        }
      }
    }
    return { left: 0, right: 0, drill: false };
  }

  // ===== READ OBS =====
  var x = isFinite(obs.x) ? obs.x : mem.px;
  var y = isFinite(obs.y) ? obs.y : mem.py;
  var h = isFinite(obs.heading) ? obs.heading : 0;
  var bt = isFinite(obs.battery) ? obs.battery : 1;
  var tl = isFinite(obs.timeLeft) ? obs.timeLeft : 1200;
  var ca = isFinite(obs.carried) ? obs.carried : 0;
  var drl = isFinite(obs.drilling) ? obs.drilling : 0;
  var wl = isFinite(obs.wheelLeft) ? obs.wheelLeft : 0;
  var wr = isFinite(obs.wheelRight) ? obs.wheelRight : 0;
  var pit = isFinite(obs.pitch) ? obs.pitch : 0;
  var rays = [];
  for (var i = 0; i < 9; i++) {
    rays.push((obs.rays && isFinite(obs.rays[i])) ? obs.rays[i] : 15);
  }
  var db = d2(x, y, mem.bx, mem.by);
  var vA = (wl + wr) / 2;

  // ===== TRACKING =====
  mem.tick++;
  var dp = d2(x, y, mem.px, mem.py);

  if (mem.tick % 20 === 0) {
    if (Math.abs(vA) > 0.4 && dp > 0.5) {
      var aDir = Math.atan2(y - mem.py, x - mem.px) * RD;
      var bias = w180(aDir - h);
      mem.hBias = mem.hBias * 0.85 + bias * 0.15;
      mem.hBias = clamp(mem.hBias, -35, 35);
    }
    mem.px = x;
    mem.py = y;
  }

  // ===== SITE SIGHTING =====
  if (obs.site && isFinite(obs.site.distance) && obs.site.distance >= 0 && obs.site.distance < 8.5) {
    var sa = (h + (obs.site.bearing || 0)) * D;
    var sx = x + obs.site.distance * Math.cos(sa);
    var sy = y + obs.site.distance * Math.sin(sa);
    var sv = (obs.site.value > 0) ? obs.site.value : 1;
    var mi = -1, md = 35;
    for (var i = 0; i < mem.sites.length; i++) {
      var s = mem.sites[i];
      if (s.s || s.d) continue;
      var dd = d2(sx, sy, s.x, s.y);
      if (dd < md) { md = dd; mi = i; }
    }
    if (mi >= 0) {
      mem.sites[mi].x = sx; mem.sites[mi].y = sy;
      mem.sites[mi].f = 1; mem.sites[mi].v = sv;
    } else {
      mem.sites.push({ x: sx, y: sy, v: sv, f: 1, s: 0, d: 0, tr: 0 });
    }
  }

  // ===== CALIBRATION =====
  if (mem.ph === 'cal') {
    mem.ct += 0.1;
    if (mem.ct <= 1.5) {
      if (!mem.c1) mem.c1 = { wl: 0, wr: 0, n: 0 };
      mem.c1.wl += wl; mem.c1.wr += wr; mem.c1.n++;
      return { left: 0.9, right: 0, drill: false };
    }
    if (mem.ct <= 3.0) {
      if (!mem.c2) mem.c2 = { wl: 0, wr: 0, n: 0 };
      mem.c2.wl += wl; mem.c2.wr += wr; mem.c2.n++;
      return { left: 0, right: 0.9, drill: false };
    }
    var n1 = Math.max(1, mem.c1 ? mem.c1.n : 1);
    var n2 = Math.max(1, mem.c2 ? mem.c2.n : 1);
    var wlL = mem.c1 ? mem.c1.wl / n1 : 0;
    var wrR = mem.c2 ? mem.c2.wr / n2 : 0;
    if (Math.abs(wlL) > 0.05) mem.gL = wlL / 0.9;
    if (Math.abs(wrR) > 0.05) mem.gR = wrR / 0.9;
    mem.dzL = Math.abs(wlL) < 0.1 ? 0.8 : (Math.abs(wlL) < 0.5 ? 0.4 : 0.25);
    mem.dzR = Math.abs(wrR) < 0.1 ? 0.8 : (Math.abs(wrR) < 0.5 ? 0.4 : 0.25);
    mem.ph = 'plan';
    return { left: 0, right: 0, drill: false };
  }

  // ===== MOTOR MODEL UPDATE =====
  if (mem.prevL !== undefined && Math.abs(mem.prevL) > 0.2 && Math.abs(wl) > 0.05) {
    var eg = wl / mem.prevL;
    if (isFinite(eg) && Math.abs(eg) > 0.05 && Math.abs(eg) < 10) {
      mem.gL = mem.gL * 0.92 + eg * 0.08;
    }
  }
  if (mem.prevR !== undefined && Math.abs(mem.prevR) > 0.2 && Math.abs(wr) > 0.05) {
    var eg = wr / mem.prevR;
    if (isFinite(eg) && Math.abs(eg) > 0.05 && Math.abs(eg) < 10) {
      mem.gR = mem.gR * 0.92 + eg * 0.08;
    }
  }

  // ===== MOTOR CMD HELPER =====
  function mc(wlD, wrD) {
    var c1 = wlD / (mem.gL || 1.4);
    var c2 = wrD / (mem.gR || 1.0);
    if (Math.abs(wlD) > 0.1) {
      if (c1 > 0 && c1 < mem.dzL) c1 = mem.dzL;
      if (c1 < 0 && c1 > -mem.dzL) c1 = -mem.dzL;
    }
    if (Math.abs(wrD) > 0.1) {
      if (c2 > 0 && c2 < mem.dzR) c2 = mem.dzR;
      if (c2 < 0 && c2 > -mem.dzR) c2 = -mem.dzR;
    }
    var e1 = wlD - wl, e2 = wrD - wr;
    if (Math.abs(e1) > 0.15 && Math.abs(mem.gL) > 0.1) c1 += 0.25 * e1 / Math.abs(mem.gL);
    if (Math.abs(e2) > 0.15 && Math.abs(mem.gR) > 0.1) c2 += 0.25 * e2 / Math.abs(mem.gR);
    return { l: clamp(c1, -1, 1), r: clamp(c2, -1, 1) };
  }

  // ===== NAV HELPER =====
  function nav(tx, ty, maxV) {
    tx = clamp(tx, 8, 392); ty = clamp(ty, 8, 392);
    var dx = tx - x, dy = ty - y;
    var d = Math.sqrt(dx * dx + dy * dy);
    if (d < 0.1) d = 0.1;
    var th = Math.atan2(dy, dx) * RD;
    var he = w180(th - h - mem.hBias);
    var vD = 0, omD = 0;
    if (Math.abs(he) > 45) {
      vD = 0;
      omD = clamp(he * D * 3, -1.5, 1.5);
    } else {
      vD = Math.min(maxV || 2, d * 0.4);
      if (Math.abs(he) > 20) vD = Math.min(vD, 1.0);
      if (d < 8) vD = Math.min(vD, Math.max(0.25, d * 0.35));
      omD = clamp(he * D * 2.5, -1.2, 1.2);
    }
    var fR = Math.min(rays[3], rays[4], rays[5]);
    var lS = rays[5] + rays[6] + rays[7] + rays[8];
    var rS = rays[0] + rays[1] + rays[2] + rays[3];
    if (fR < 1.0) {
      vD = 0;
      omD = (lS > rS) ? 1.5 : -1.5;
    } else if (fR < 5) {
      vD = Math.min(vD, 0.3 + fR * 0.3);
      omD += (lS > rS ? 1 : -1) * 0.6 * (1 - fR / 5);
    }
    if (rays[7] < 1.5) omD += 0.4;
    if (rays[1] < 1.5) omD -= 0.4;
    return mc(vD - omD * WB / 2, vD + omD * WB / 2);
  }

  // ===== BUMP / STUCK =====
  if (obs.bumped && mem.ph !== 'esc' && mem.ph !== 'smp' && mem.ph !== 'dock') {
    mem.ph = 'esc'; mem.escT = 0;
    mem.escD = (rays[5] + rays[6] + rays[7] + rays[8] > rays[0] + rays[1] + rays[2] + rays[3]) ? 1 : -1;
  }
  if (mem.ph === 'goto' || mem.ph === 'ret' || mem.ph === 'srch' || mem.ph === 'exp') {
    if (dp < 0.005 && (Math.abs(wl) > 0.1 || Math.abs(wr) > 0.1)) {
      mem.stuck++;
      if (mem.stuck > 30) { mem.ph = 'esc'; mem.escT = 0; mem.stuck = 0; }
    } else { mem.stuck = 0; }
  }

  // ===== STATE MACHINE =====
  var L = 0, R = 0, DR = false;

  switch (mem.ph) {
    case 'plan': {
      if (db < 3 && ca > 0) { mem.ph = 'dock'; mem.dckT = 0; break; }
      if (ca > 0 && (ca >= 3 || (ca >= 2 && db > 80) || tl < 250 || bt < 0.18)) { mem.ph = 'ret'; break; }
      if (tl < 80) { mem.ph = ca > 0 ? 'ret' : 'idle'; break; }
      if (bt < 0.1) { mem.ph = ca > 0 ? 'ret' : 'idle'; break; }
      var bi = -1, bs = -1;
      for (var i = 0; i < mem.sites.length; i++) {
        var s = mem.sites[i];
        if (s.s || s.d) continue;
        var sd = d2(x, y, s.x, s.y);
        var rt = sd * 1.5 + 30;
        if (rt > tl - 100) continue;
        var sc = s.v / rt;
        if (sc > bs) { bs = sc; bi = i; }
      }
      if (bi >= 0 && ca < mem.cap) { mem.ti = bi; mem.ph = 'goto'; mem.goT = 0; }
      else if (ca > 0) { mem.ph = 'ret'; }
      else if (tl > 250) { mem.ph = 'exp'; mem.goT = 0; }
      else { mem.ph = 'idle'; }
      break;
    }

    case 'goto': {
      var s = mem.ti >= 0 && mem.ti < mem.sites.length ? mem.sites[mem.ti] : null;
      if (!s || s.s || s.d) { mem.ph = 'plan'; break; }
      mem.goT += 0.1;
      if (mem.goT > 120) { s.tr++; if (s.tr >= 2) s.d = 1; mem.ph = 'plan'; break; }
      if (s.f) {
        var sd = d2(x, y, s.x, s.y);
        if (sd < 1.5 && Math.abs(vA) < 0.15) { mem.ph = 'smp'; mem.smpT = 0; mem.drillOn = 0; break; }
        if (sd < 3.5) {
          if (Math.abs(vA) > 0.1) {
            var m = mc(-wl * 1.5, -wr * 1.5); L = m.l; R = m.r;
          } else {
            var th2 = Math.atan2(s.y - y, s.x - x) * RD;
            var he2 = w180(th2 - h - mem.hBias);
            if (Math.abs(he2) > 25) {
              var om2 = clamp(he2 * D * 1.5, -0.5, 0.5);
              var m = mc(-om2 * WB / 2, om2 * WB / 2); L = m.l; R = m.r;
            } else {
              var v2 = clamp(sd * 0.25, 0.15, 0.5);
              var m = mc(v2, v2); L = m.l; R = m.r;
            }
          }
        } else {
          var m = nav(s.x, s.y, 2.2); L = m.l; R = m.r;
        }
      } else {
        var sd = d2(x, y, s.x, s.y);
        if (sd < 20) { mem.ph = 'srch'; mem.srchT = 0; break; }
        var m = nav(s.x, s.y, 2.2); L = m.l; R = m.r;
      }
      break;
    }

    case 'srch': {
      var s = mem.ti >= 0 && mem.ti < mem.sites.length ? mem.sites[mem.ti] : null;
      if (!s) { mem.ph = 'plan'; break; }
      if (s.f) { mem.ph = 'goto'; break; }
      mem.srchT += 0.1;
      if (mem.srchT > 45) { s.tr++; if (s.tr >= 2) s.d = 1; mem.ph = 'plan'; break; }
      var a = mem.srchT * 0.5, r = 5 + mem.srchT * 0.5;
      var m = nav(s.x + r * Math.cos(a * D), s.y + r * Math.sin(a * D), 1.5);
