      break;
    }

    case 'smp': {
      mem.smpT += 0.1;
      if (!mem.drillOn) {
        if (Math.abs(vA) > 0.08) {
          var m = mc(-wl * 2.0, -wr * 2.0); L = m.l; R = m.r;
        } else {
          mem.drillOn = 1;
        }
      }
      if (mem.drillOn) {
        DR = true;
        if (Math.abs(vA) > 0.08) {
          var m = mc(-wl * 1.5, -wr * 1.5); L = m.l; R = m.r;
        } else if (Math.abs(pit) > 1) {
          var holdV = clamp(pit * 0.05, -0.5, 0.5);
