        if (!s.sampled && s.found && s.tries < 2 && ca < mem.cap) {
          mem.tgt = i; mem.mode = 'goto'; mem.gotoT = 0; mem.turning = 0; break;
        }
      }
      if (mem.mode === 'goto') break;
      for (var i = 0; i < mem.sites.length; i++) {
        var s = mem.sites[i];
        if (!s.sampled && !s.found && s.tries < 1 && ca < mem.cap) {
          mem.tgt = i; mem.mode = 'goto'; mem.gotoT = 0; mem.turning = 0; break;
        }
      }
      if (mem.mode === 'goto') break;
      if (tl < 250) { mem.mode = ca > 0 ? 'return' : 'wait'; break; }
      var ang = mem.tick * 0.008;
      var rad = Math.min(180, 25 + mem.tick * 0.015);
      var ex = cl(mem.bx + rad * Math.cos(ang), 10, 390);
      var ey = cl(mem.by + rad * Math.sin(ang), 10, 390);
      var m = nav(ex, ey, 0.55); L = m.L; R = m.R;
      break;
    }

    case 'wait': {
      if (Math.abs(spd) > 0.08) { L = -0.38; R = -0.38; }
      break;
    }
  }

  return { left: cl(L, -1, 1), right: cl(R, -1, 1), drill: DR };
}

function act(obs, mem) {
  const o = obs || {};
  if (!mem || typeof mem !== "object") mem = {};

  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
  const num = (v, d) => {
    const n = Number(v);
    return Number.isFinite(n) ? n : d;
  };
  const wrap = (a) => {
    a = (a + 180) % 360;
    if (a < 0) a += 360;
    return a - 180;
  };
  const rad = (d) => d * Math.PI / 180;
  const deg = (r) => r * 180 / Math.PI;
  const distance = (x1, y1, x2, y2) => Math.hypot(x2 - x1, y2 - y1);

  const rawH = wrap(num(o.heading, 0));
  const rawX = num(o.x, 200);
  const rawY = num(o.y, 200);
  const wl = num(o.wheelLeft, 0);
  const wr = num(o.wheelRight, 0);
  const vWheel = (wl + wr) * 0.5;
  const tNow = num(o.t, 0);

  let dt = 0.1;
  if (Number.isFinite(mem.prevT)) {
    const d = tNow - mem.prevT;
    if (d > 0 && d <= 0.5) dt = d;
  }

  if (!mem._init) {
    const m = o.mission || {};
    const sz = m.size;
    let width = 400, height = 400;
    if (typeof sz === "number") {
      width = height = sz;
    } else if (Array.isArray(sz)) {
      width = num(sz[0], 400);
      height = num(sz[1], width);
    } else if (sz && typeof sz === "object") {
      width = num(sz.width, num(sz.w, num(sz.x, 400)));
      height = num(sz.height, num(sz.h, num(sz.y, width)));
    }
    const b = m.base || { x: width * 0.5, y: height * 0.5 };
    mem.width = Math.max(50, width);
    mem.height = Math.max(50, height);
    mem.baseX = num(b.x, width * 0.5);
    mem.baseY = num(b.y, height * 0.5);
    mem.seconds = num(m.seconds, 1200);
    mem.capacity = Math.max(1, Math.floor(num(m.capacity, 5)));
    mem.hints = [];
    const hints = Array.isArray(m.hints) ? m.hints : [];
    for (let i = 0; i < hints.length; i++) {
      const h = hints[i] || {};
      mem.hints.push({
        x: num(h.x, mem.baseX),
        y: num(h.y, mem.baseY),
        value: Math.max(0.1, num(h.estimate, num(h.value, 1))),
        status: 0,
        phase: "center",
        step: 0
      });
    }
    mem.globalPoints = [];
    const sx = mem.width <= 100 ? mem.width * 0.5 : 40;
    const sy = mem.height <= 100 ? mem.height * 0.5 : 40;
    const dx = mem.width <= 100 ? 1e9 : 80;
    const dy = mem.height <= 100 ? 1e9 : 80;
    for (let y = sy; y <= mem.height - sy + 0.01; y += dy) {
      for (let x = sx; x <= mem.width - sx + 0.01; x += dx) {
        mem.globalPoints.push({ x: x, y: y, done: false });
      }
    }
    mem.hintIndex = -1;
    mem.globalIndex = -1;
    mem.activeSite = null;
    mem.sampleActive = false;
    mem.pendingMeta = null;
    mem.holdReady = false;
    mem.stillTime = 0;
    mem.returning = false;
    mem.px = rawX;
    mem.py = rawY;
    mem.theta = rawH;
    mem.headingBias = 0;
    mem.prevRawH = rawH;
    mem.prevT = tNow;
    mem.lastGpsX = rawX;
    mem.lastGpsY = rawY;
    mem.gpsUnchanged = 0;
    mem.gpsTravelSinceChange = 0;
    mem.gpsFrozen = false;
    mem.cal = {
      x: rawX, y: rawY, sin: 0, cos: 0, n: 0, yaw: 0, forwardTime: 0
    };
    mem.eRate = 0.00065;
    mem.idleRate = 0.00002;
    mem.energyUse = 0;
    mem.energyDist = 0;
    mem.gains = [[2.7, 2.7], [2.7, 2.7]];
    mem.lastCmd = [0, 0];
    mem.rFilt = null;
    mem.rRaw = null;
    mem.rSame = [];
    mem.rTravel = [];
    mem.rBad = [];
    mem.allMaxTravel = 0;
    mem.rangeTrust = 1;
    mem.bumpTimer = 0;
    mem.prevBumped = false;
    mem.navKey = "";
    mem.navBest = 1e9;
    mem.navStuck = 0;
    mem.lastAim = 0;
    mem.avoidSign = 0;
    mem.samples = [];
    mem.prevCarried = Math.max(0, Math.floor(num(o.carried, 0)));
    mem.prevDelivered = num(o.delivered, 0);
    mem.prevBattery = num(o.battery, 1);
    mem._init = true;
  }

  const battery = clamp(num(o.battery, 1), 0, 1.2);
  const solar = Math.max(0, num(o.solar, 0));
  const carried = Math.max(0, Math.floor(num(o.carried, 0)));
  const timeLeft = Math.max(0, num(o.timeLeft, mem.seconds - tNow));
  const siteObs = o.site && typeof o.site === "object" ? o.site : null;
  const beacon = o.beacon && typeof o.beacon === "object" ? o.beacon : null;

  const prevTheta = mem.theta;
  const dYaw = deg(((wr - wl) / 0.6) * dt);
  const rawDeltaH = wrap(rawH - num(mem.prevRawH, rawH));
  let compassJump = false;
  const yawMismatch = wrap(rawDeltaH - dYaw);
  if (Math.abs(yawMismatch) > 48 && Math.abs(rawDeltaH) > 22) {
    mem.headingBias = wrap(num(mem.headingBias, 0) + yawMismatch);
    compassJump = true;
  }

  const gpsDelta = distance(rawX, rawY, num(mem.lastGpsX, rawX), num(mem.lastGpsY, rawY));
  const gpsJump = gpsDelta > 7.5 && dt < 0.5;
  if (gpsDelta < 0.035) {
    if (Math.abs(vWheel) > 0.22) {
      mem.gpsUnchanged = num(mem.gpsUnchanged, 0) + dt;
      mem.gpsTravelSinceChange = num(mem.gpsTravelSinceChange, 0) + Math.abs(vWheel) * dt;
    }
  } else if (gpsDelta > 0.08) {
    mem.gpsUnchanged = 0;
    mem.gpsTravelSinceChange = 0;
  }
  mem.gpsFrozen = mem.gpsUnchanged > 4.5 && mem.gpsTravelSinceChange > 3.0;

  if (!mem.cal) {
    mem.cal = { x: rawX, y: rawY, sin: 0, cos: 0, n: 0, yaw: 0, forwardTime: 0 };
  }
  if (!mem.gpsFrozen && !gpsJump && !compassJump) {
    const straightForward = vWheel > 0.35 && Math.abs(wr - wl) < 0.32;
    if (straightForward) {
      mem.cal.sin += Math.sin(rad(rawH));
      mem.cal.cos += Math.cos(rad(rawH));
      mem.cal.n += 1;
      mem.cal.yaw += dYaw;
      mem.cal.forwardTime += dt;
    }
    const calDist = distance(rawX, rawY, mem.cal.x, mem.cal.y);
    if (calDist >= 3.0) {
      if (mem.cal.n >= 5 && Math.abs(mem.cal.yaw) < 18 &&
          mem.cal.forwardTime > 0.5 && straightForward) {
        const course = deg(Math.atan2(rawY - mem.cal.y, rawX - mem.cal.x));
        const meanRaw = deg(Math.atan2(mem.cal.sin, mem.cal.cos));
        const biasEstimate = wrap(course - meanRaw);
        const biasError = wrap(biasEstimate - mem.headingBias);
        if (Math.abs(biasError) < 65) {
          mem.headingBias = wrap(mem.headingBias + clamp(biasError * 0.2, -6, 6));
        }
      }
      mem.cal = {
        x: rawX, y: rawY, sin: 0, cos: 0, n: 0, yaw: 0, forwardTime: 0
      };
    }
  }

  mem.theta = wrap(num(mem.theta, rawH) + dYaw);
  if (!compassJump) {
    const correctedCompass = wrap(rawH - num(mem.headingBias, 0));
    const residual = wrap(correctedCompass - mem.theta);
    mem.theta = wrap(mem.theta + clamp(residual * 0.12, -3, 3));
  }

  const midTheta = rad(wrap((prevTheta + mem.theta) * 0.5));
  let predX = mem.px + vWheel * dt * Math.cos(midTheta);
  let predY = mem.py + vWheel * dt * Math.sin(midTheta);
  const wasFrozen = mem.gpsFrozen;
  if (!mem.gpsFrozen && !gpsJump) {
    const residual = distance(rawX, rawY, predX, predY);
    let alpha = Math.abs(vWheel) > 0.25 ? 0.2 : 0.09;
    if (residual > 3.5) alpha = 0.45;
    if (wasFrozen) alpha = 0.32;
    if (residual < 14) {
      predX += (rawX - predX) * alpha;
      predY += (rawY - predY) * alpha;
    }
  }
  mem.px = predX;
  mem.py = predY;
  mem.lastGpsX = rawX;
  mem.lastGpsY = rawY;
  mem.prevRawH = rawH;
  const moveDist = Math.abs(vWheel) * dt;

  if (!Array.isArray(mem.gains)) mem.gains = [[2.7, 2.7], [2.7, 2.7]];
  if (!Array.isArray(mem.lastCmd)) mem.lastCmd = [0, 0];
  for (let s = 0; s < 2; s++) {
    const cmd = num(mem.lastCmd[s], 0);
    const actual = s === 0 ? wl : wr;
    if (Math.abs(cmd) > 0.18 && actual * cmd > 0.04 && Math.abs(actual) > 0.16) {
      const si = cmd < 0 ? 1 : 0;
      const ratio = Math.abs(actual / cmd);
      if (ratio > 0.55 && ratio < 5.2) {
        const old = num(mem.gains[s][si], 2.7);
        let a = 0.012;
        if (ratio < old * 0.72) a = 0.07;
        else if (ratio > old * 1.2) a = 0.05;
        mem.gains[s][si] = clamp(old + (ratio - old) * a, 0.8, 5.0);
      }
    }
  }

  if (Number.isFinite(mem.prevBattery) && !o.docked) {
    const drop = num(mem.prevBattery, battery) - battery;
    let gross = drop + solar * dt;
    if (battery > 0.99 && drop <= 0) gross = 0;
    gross = clamp(gross, 0, 0.03);
    mem.energyUse = num(mem.energyUse, 0) + gross;
    mem.energyDist = num(mem.energyDist, 0) + moveDist;
    if (Math.abs(vWheel) < 0.12 && !o.drilling && gross > 0) {
      const idleEstimate = gross / Math.max(0.05, dt);
      if (idleEstimate < 0.004) {
        mem.idleRate = clamp(num(mem.idleRate, 0.00002) * 0.94 + idleEstimate * 0.06, 0.000003, 0.001);
      }
    }
    if (mem.energyDist >= 7.0 && mem.energyUse > 0.0002) {
      const measured = clamp(mem.energyUse / Math.max(5, mem.energyDist), 0.00012, 0.012);
      const old = num(mem.eRate, 0.00065);
      const a = measured > old ? 0.38 : 0.08;
      mem.eRate = clamp(old + (measured - old) * a, 0.00012, 0.012);
      mem.energyUse = 0;
      mem.energyDist = 0;
    }
  }
  mem.prevBattery = battery;

  const rawRays = o.rays && typeof o.rays.length === "number" ? o.rays : null;
  if (!Array.isArray(mem.rFilt) || mem.rFilt.length !== 9) {
    mem.rFilt = [];
    mem.rRaw = [];
    mem.rSame = [];
    mem.rTravel = [];
    mem.rBad = [];
    for (let i = 0; i < 9; i++) {
      const r = rawRays ? clamp(num(rawRays[i], 15), 0, 15) : 15;
      mem.rFilt[i] = r;
      mem.rRaw[i] = r;
      mem.rSame[i] = 0;
      mem.rTravel[i] = 0;
      mem.rBad[i] = false;
    }
  }
  let allMax = true;
  let anyNearMax = false;
  for (let i = 0; i < 9; i++) {
    let r = rawRays ? clamp(num(rawRays[i], 15), 0, 15) : 15;
    if (r < 14.7) allMax = false;
    if (r < 14.2) anyNearMax = true;
    const last = num(mem.rRaw[i], r);
    if (Math.abs(r - last) < 0.025) {
      if (moveDist > 0.025 || Math.abs(dYaw) > 0.6) {
        mem.rSame[i] = num(mem.rSame[i], 0) + dt;
        mem.rTravel[i] = num(mem.rTravel[i], 0) + moveDist;
      }
    } else if (Math.abs(r - last) > 0.18) {
      mem.rSame[i] = 0;
      mem.rTravel[i] = 0;
      mem.rBad[i] = false;
    }
    if (mem.rSame[i] > 9 && mem.rTravel[i] > 4 && r < 14.7) mem.rBad[i] = true;
    let effective = r;
    if (mem.rBad[i]) effective = Math.max(effective, 7.5);
    let f = num(mem.rFilt[i], effective);
    if (effective < f) f = effective;
    else f += (effective - f) * 0.28;
    mem.rFilt[i] = clamp(f, 0, 15);
    mem.rRaw[i] = r;
  }
  if (allMax && moveDist > 0.02) mem.allMaxTravel = num(mem.allMaxTravel, 0) + moveDist;
  else if (anyNearMax) mem.allMaxTravel = Math.max(0, num(mem.allMaxTravel, 0) - moveDist * 1.5);
  mem.rangeTrust = mem.allMaxTravel > 9 ? 0.62 : 1;

  const capacity = Math.max(1, Math.floor(num(mem.capacity, 5)));
  const oldCarried = num(mem.prevCarried, carried);
  if (carried > oldCarried) {
    const meta = mem.pendingMeta || mem.activeSite || { x: mem.px, y: mem.py, value: 1 };
    const mx = num(meta.x, mem.px), my = num(meta.y, mem.py);
    mem.samples.push({ x: mx, y: my, value: num(meta.value, 1) });
    let associated = -1;
    const current = Math.floor(num(mem.hintIndex, -1));
    if (current >= 0 && current < mem.hints.length &&
        distance(mx, my, mem.hints[current].x, mem.hints[current].y) < 34) {
      associated = current;
    } else {
      let bestD = 25;
      for (let i = 0; i < mem.hints.length; i++) {
        if (mem.hints[i].status >= 2) continue;
        const d = distance(mx, my, mem.hints[i].x, mem.hints[i].y);
        if (d < bestD) {
          bestD = d;
          associated = i;
        }
      }
    }
    if (associated >= 0) {
      mem.hints[associated].status = 2;
      if (associated === mem.hintIndex) mem.hintIndex = -1;
    }
    for (let i = 0; i < mem.globalPoints.length; i++) {
      if (distance(mx, my, mem.globalPoints[i].x, mem.globalPoints[i].y) < 8) {
        mem.globalPoints[i].done = true;
      }
    }
    mem.sampleActive = false;
    mem.pendingMeta = null;
    mem.activeSite = null;
    mem.holdReady = false;
    mem.stillTime = 0;
  }
  mem.prevCarried = carried;
  mem.prevDelivered = num(o.delivered, mem.prevDelivered);

  if (siteObs && carried < capacity) {
    const sd = Math.max(0, num(siteObs.distance, 99));
    const sb = num(siteObs.bearing, 0);
    const wa = rad(mem.theta + sb);
    const sx = mem.px + sd * Math.cos(wa);
    const sy = mem.py + sd * Math.sin(wa);
    if (!mem.activeSite) {
      mem.activeSite = { x: sx, y: sy, value: Math.max(0.1, num(siteObs.value, 1)), lastSeen: tNow };
    } else {
      const gap = distance(mem.activeSite.x, mem.activeSite.y, sx, sy);
      if (gap > 12 && !mem.sampleActive) {
        mem.activeSite.x = sx;
        mem.activeSite.y = sy;
      } else {
        mem.activeSite.x = num(mem.activeSite.x, sx) * 0.62 + sx * 0.38;
        mem.activeSite.y = num(mem.activeSite.y, sy) * 0.62 + sy * 0.38;
      }
      mem.activeSite.value = Math.max(0.1, num(siteObs.value, mem.activeSite.value || 1));
      mem.activeSite.lastSeen = tNow;
    }
  }

  if (!mem.sampleActive && num(o.drilling, 0) > 0.05 && mem.activeSite) {
    mem.sampleActive = true;
    if (!mem.holdReady) {
      mem.holdX = mem.px;
      mem.holdY = mem.py;
      mem.holdHeading = mem.theta;
      mem.holdBias = 0;
      mem.holdReady = true;
    }
    mem.pendingMeta = {
      x: mem.activeSite.x, y: mem.activeSite.y, value: mem.activeSite.value
    };
  }

  const poseX = mem.px, poseY = mem.py;
  const baseDistGps = distance(poseX, poseY, mem.baseX, mem.baseY);
  const beaconDist = beacon ? Math.max(0, num(beacon.distance, 99)) : 99;
  const homeDist = beacon && beaconDist <= 20.5 ? beaconDist : baseDistGps;
  const atBase = !!o.docked || beaconDist <= 2.8 || baseDistGps <= 2.35;
  const science = num(o.science, 0);
  const sciencePresent = o.science !== undefined && o.science !== null &&
                         Number.isFinite(Number(o.science));

  function homeNeed(d, load) {
    const l = Math.max(0, load);
    const route = Math.max(0, d) * 1.38 + 12;
    return 0.085 + 0.004 * l +
      num(mem.eRate, 0.00065) * route * (1 + 0.14 * l) +
      num(mem.idleRate, 0.00002) * (Math.max(0, d) / 0.9 + 18);
  }

  function energyForPlan(outDist, homeDistPlan, extra, load) {
    const l = Math.max(0, load);
    const metres = Math.max(0, outDist) * 1.32 +
                   Math.max(0, homeDistPlan) * 1.38 +
                   Math.max(0, extra) * 1.0 + 20;
    return 0.105 + num(mem.eRate, 0.00065) * metres * (1 + 0.10 * l) +
           num(mem.idleRate, 0.00002) * (metres / 0.95 + 20) + 0.008;
  }

  const searchOffsets = [[-15.5, -15.5], [15.5, 15.5], [-15.5, 15.5], [15.5, -15.5]];
  function remainingSearch(h) {
    if (!h) return 0;
    if (h.phase === "search") return Math.max(8, (4 - Math.max(0, h.step)) * 29);
    return 78;
  }

  function bestHintIndex(px, py, tl) {
    let best = -1, bestScore = -1;
    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (!h || h.status >= 2) continue;
      const d = distance(px, py, h.x, h.y);
      const dh = distance(h.x, h.y, mem.baseX, mem.baseY);
      const extra = remainingSearch(h);
      const need = energyForPlan(d, dh, extra, 0);
      const tneed = (d + dh + extra) / 0.98 + 38;
      if (need > 1.035 || tneed > tl + 2) continue;
      let score = Math.pow(Math.max(0.1, h.value), 1.18) /
                  (65 + d + 0.58 * dh + 0.48 * extra);
      if (h.status === 1) score *= 1.08;
      if (i === mem.hintIndex) score *= 1.12;
      if (score > bestScore) {
        bestScore = score;
        best = i;
      }
    }
    return best;
  }

  function bestGlobalIndex(px, py, tl) {
    let best = -1, bestScore = -1;
    for (let i = 0; i < mem.globalPoints.length; i++) {
      const p = mem.globalPoints[i];
      if (!p || p.done) continue;
      const d = distance(px, py, p.x, p.y);
      const dh = distance(p.x, p.y, mem.baseX, mem.baseY);
      if (energyForPlan(d, dh, 0, 0) > 1.035) continue;
      if ((d + dh) / 0.98 + 30 > tl) continue;
      let score = 2.5 / (55 + d + 0.48 * dh);
      if (i === mem.globalIndex) score *= 1.12;
      if (score > bestScore) {
        bestScore = score;
        best = i;
      }
    }
    return best;
  }

  function taskInfo() {
    if (mem.activeSite && carried < capacity) {
      const ax = num(mem.activeSite.x, poseX);
      const ay = num(mem.activeSite.y, poseY);
      const d = siteObs ? Math.max(0, num(siteObs.distance, 99)) :
                distance(poseX, poseY, ax, ay);
      const e = siteObs ? num(siteObs.bearing, 0) :
                wrap(deg(Math.atan2(ay - poseY, ax - poseX)) - mem.theta);
      return {
        kind: "site", x: ax, y: ay, dist: d, error: e,
        value: num(mem.activeSite.value, 1), key: "site"
      };
    }

    for (let tries = 0; tries < 12; tries++) {
      let hi = Math.floor(num(mem.hintIndex, -1));
      if (hi < 0 || hi >= mem.hints.length || mem.hints[hi].status >= 2) {
        hi = bestHintIndex(poseX, poseY, timeLeft);
        mem.hintIndex = hi;
        if (hi >= 0 && mem.hints[hi].status === 0) {
          mem.hints[hi].status = 1;
          mem.hints[hi].phase = "center";
          mem.hints[hi].step = 0;
        }
      }
      if (hi >= 0 && hi < mem.hints.length) {
        const h = mem.hints[hi];
        if (!h.phase) h.phase = "center";
        if (h.phase === "center") {
          const d = distance(poseX, poseY, h.x, h.y);
          if (d <= 4.8) {
            if (science > 0 || !sciencePresent || siteObs) {
              h.phase = "search";
              h.step = 0;
            } else {
              h.status = 2;
              mem.hintIndex = -1;
              continue;
            }
          } else {
            return {
              kind: "hint", x: h.x, y: h.y, dist: d,
              error: wrap(deg(Math.atan2(h.y - poseY, h.x - poseX)) - mem.theta),
              hintIndex: hi, phase: "center", step: 0, extra: 78,
              key: "hc" + hi
            };
          }
        }
        if (h.phase === "search") {
          let step = Math.max(0, Math.floor(num(h.step, 0)));
          while (step < 4) {
            const off = searchOffsets[step];
            const tx = clamp(h.x + off[0], 3, mem.width - 3);
            const ty = clamp(h.y + off[1], 3, mem.height - 3);
            const d = distance(poseX, poseY, tx, ty);
            if (d <= 2.8) {
              step++;
              h.step = step;
              continue;
            }
            return {
              kind: "hint", x: tx, y: ty, dist: d,
              error: wrap(deg(Math.atan2(ty - poseY, tx - poseX)) - mem.theta),
              hintIndex: hi, phase: "search", step: step,
              extra: Math.max(8, (4 - step) * 29),
              key: "hs" + hi + ":" + step
            };
          }
          h.status = 2;
          mem.hintIndex = -1;
          continue;
        }
      }

      let gi = Math.floor(num(mem.globalIndex, -1));
      if (gi < 0 || gi >= mem.globalPoints.length || mem.globalPoints[gi].done) {
        gi = bestGlobalIndex(poseX, poseY, timeLeft);
        mem.globalIndex = gi;
      }
      if (gi >= 0 && gi < mem.globalPoints.length) {
        const p = mem.globalPoints[gi];
        const d = distance(poseX, poseY, p.x, p.y);
        if (d <= 4.2) {
          p.done = true;
          mem.globalIndex = -1;
          continue;
        }
        return {
          kind: "global", x: p.x, y: p.y, dist: d,
          error: wrap(deg(Math.atan2(p.y - poseY, p.x - poseX)) - mem.theta),
          globalIndex: gi, extra: 0, key: "g" + gi
        };
      }
      return null;
    }
    return null;
  }

  function gainFor(side, target) {
    const si = target < -0.02 ? 1 : 0;
    return clamp(num(mem.gains[side][si], 2.7), 0.8, 5.0);
  }

  function wheelPower(target, actual, side, hold) {
    const gain = gainFor(side, target);
    let u = target / gain + (hold ? 0.34 : 0.20) * (target - actual);
    if (!hold && Math.abs(target) > 0.12 &&
        Math.sign(target) === Math.sign(target - actual) &&
        Math.abs(u) < 0.17) {
      u = Math.sign(target) * 0.17;
    }
    return clamp(u, -1, 1);
  }

  function wheelCommands(v, omega, hold) {
    const leftTarget = clamp(v - 0.3 * omega, -2.7, 2.7);
    const rightTarget = clamp(v + 0.3 * omega, -2.7, 2.7);
    return {
      left: wheelPower(leftTarget, wl, 0, !!hold),
      right: wheelPower(rightTarget, wr, 1, !!hold)
    };
  }

  function rayAt(angle) {
    const a = clamp(angle, -80, 80);
    const q = (a + 80) / 20;
    const i = Math.floor(q);
    const f = q - i;
    const r0 = num(mem.rFilt[clamp(i, 0, 8)], 15);
    const r1 = num(mem.rFilt[clamp(i + 1, 0, 8)], 15);
    return r0 * (1 - f) + r1 * f;
  }

  function clearanceAt(angle) {
    const r0 = rayAt(angle);
    const side = Math.min(rayAt(angle - 20), rayAt(angle + 20));
    return Math.min(r0, r0 * 0.78 + side * 0.22);
  }

  function edgeDistance(angle) {
    const a = rad(wrap(mem.theta + angle));
    const dx = Math.cos(a), dy = Math.sin(a);
    const margin = 4;
    let d = 1e6;
    if (dx > 0.001) d = Math.min(d, (mem.width - margin - poseX) / dx);
    if (dx < -0.001) d = Math.min(d, (margin - poseX) / dx);
    if (dy > 0.001) d = Math.min(d, (mem.height - margin - poseY) / dy);
    if (dy < -0.001) d = Math.min(d, (margin - poseY) / dy);
    return Math.max(0, d);
  }

  function navCommands(goalError, maxV) {
    const goal = wrap(goalError);
    const vmax = Math.max(0, maxV);
    if (Math.abs(goal) > 84) {
      const s = Math.sign(goal) || 1;
      mem.lastAim = s * 90;
      return wheelCommands(0, s * 1.05, false);
    }

    const candidates = [-80, -60, -40, -20, 0, 20, 40, 60, 80,
                        clamp(goal, -80, 80)];
    let best = clamp(goal, -80, 80);
    let bestCost = 1e9;
    let bestClear = 15;
    const safe = 3.6 + vmax * 1.25;
    const front = rayAt(0);

    for (let i = 0; i < candidates.length; i++) {
      const a = candidates[i];
      const clear = clearanceAt(a);
      let cost = Math.abs(a - clamp(goal, -80, 80)) * 0.03;
      const hazard = Math.max(0, safe - clear);
      cost += hazard * hazard * 0.27;
      if (clear < 1.5) cost += 7;
      const e = edgeDistance(a);
      if (e < 2.5) cost += 14;
      else if (e < 8) cost += (8 - e) * 0.65;
      if (front < safe && Math.abs(a) > 10 && mem.avoidSign &&
          Math.sign(a) !== mem.avoidSign) cost += 0.18;
      if (front < safe) cost += Math.abs(a - num(mem.lastAim, a)) * 0.006;
      if (cost < bestCost) {
        bestCost = cost;
        best = a;
        bestClear = clear;
      }
    }

    if (front > safe + 1.5) mem.avoidSign = 0;
    else if (Math.abs(best) > 10) mem.avoidSign = Math.sign(best);
    mem.lastAim = best;

    let v = vmax;
    const scale = clamp((bestClear - 1.15) / Math.max(1.2, safe - 1.15), 0.18, 1);
    v *= scale;
    if (bestClear < 2.2) v = Math.min(v, 0.42);
    if (front < 1.35 && Math.abs(best) < 18) v = Math.min(v, 0.25);
    if (Math.abs(best) > 60) v = Math.min(v, 0.55);
    else if (Math.abs(best) > 38) v = Math.min(v, 0.9);

    const omega = clamp(2.05 * rad(best), -1.65, 1.65);
    return wheelCommands(v, omega, false);
  }

  function stopCommands() {
    return wheelCommands(0, 0, false);
  }

  function holdCommands() {
    if (!mem.holdReady) {
      mem.holdX = poseX;
      mem.holdY = poseY;
      mem.holdHeading = mem.theta;
      mem.holdBias = 0;
      mem.holdReady = true;
    }
    const a = rad(mem.theta);
    const dx = num(mem.holdX, poseX) - poseX;
    const dy = num(mem.holdY, poseY) - poseY;
    const along = dx * Math.cos(a) + dy * Math.sin(a);
    const avg = (wl + wr) * 0.5;
    let vDes = clamp(0.38 * along - 0.62 * avg, -0.25, 0.25);
    if (Math.abs(along) > 0.25) {
      mem.holdBias = clamp(num(mem.holdBias, 0) +
                           clamp(along * 0.002, -0.002, 0.002),
                           -0.12, 0.12);
    }
    const headingErr = wrap(num(mem.holdHeading, mem.theta) - mem.theta);
    const omega = clamp(0.9 * rad(headingErr), -0.32, 0.32);
    const c = wheelCommands(vDes, omega, true);
    const pitchFeed = clamp(num(o.pitch, 0) * 0.008, -0.10, 0.10);
    c.left = clamp(c.left + pitchFeed + num(mem.holdBias, 0), -1, 1);
    c.right = clamp(c.right + pitchFeed + num(mem.holdBias, 0), -1, 1);
    return c;
  }

  function emit(c, drill) {
    const left = clamp(num(c && c.left, 0), -1, 1);
    const right = clamp(num(c && c.right, 0), -1, 1);
    mem.lastCmd = [left, right];
    mem.prevT = tNow;
    mem.prevCarried = carried;
    return { left: left, right: right, drill: !!drill };
  }

  function recordProgress(key, d, info) {
    if (mem.navKey !== key) {
      mem.navKey = key;
      mem.navBest = d;
      mem.navStuck = 0;
      return;
    }
    if (d < num(mem.navBest, d) - 0.55) {
      mem.navBest = d;
      mem.navStuck = 0;
      return;
    }
    mem.navStuck = num(mem.navStuck, 0) + dt;
    if (mem.navStuck > 34) {
      mem.navStuck = 0;
      mem.navBest = d;
      mem.avoidSign = -num(mem.avoidSign, 1);
      mem.lastAim = 0;
      if (info && info.kind === "hint" && info.hintIndex >= 0) {
        const h = mem.hints[info.hintIndex];
        if (h) {
          if (h.phase === "center") {
            h.phase = "search";
            h.step = 0;
          } else if (h.phase === "search") {
            h.step = Math.min(4, Math.max(0, h.step) + 1);
          }
        }
      } else if (info && info.kind === "global" && info.globalIndex >= 0) {
        if (mem.globalPoints[info.globalIndex]) mem.globalPoints[info.globalIndex].done = true;
        mem.globalIndex = -1;
      }
    }
  }

  const homeEnergy = homeNeed(homeDist, carried);
  const homeTime = homeDist / 0.9 + 30 + (carried > 0 ? 6 : 0);
  const sampleCanFinish = mem.sampleActive &&
                          battery > homeEnergy + 0.012 &&
                          timeLeft > homeTime + 8;
  const returnForCapacity = carried >= capacity;
  const returnForEnergy = battery < homeEnergy + 0.006;
  const returnForTime = timeLeft < homeTime + 6;
  if (!atBase && !mem.returning && !sampleCanFinish &&
      (returnForCapacity || returnForEnergy || returnForTime || battery < 0.025)) {
    mem.returning = true;
  }

  if (mem.returning && atBase && carried === 0) {
    mem.returning = false;
    mem.sampleActive = false;
    mem.holdReady = false;
    mem.stillTime = 0;
  }

  if (o.bumped && !mem.prevBumped && !atBase && !mem.sampleActive) {
    let leftOpen = 0, rightOpen = 0;
    for (let i = 5; i < 9; i++) leftOpen += num(mem.rFilt[i], 15);
    for (let i = 0; i < 4; i++) rightOpen += num(mem.rFilt[i], 15);
    mem.bumpSign = leftOpen >= rightOpen ? 1 : -1;
    mem.bumpTimer = 1.45;
  }
  mem.prevBumped = !!o.bumped;

  if (!atBase && !mem.sampleActive && num(mem.bumpTimer, 0) > 0) {
    const remaining = num(mem.bumpTimer, 0);
    const s = num(mem.bumpSign, 1);
    let c;
    if (remaining > 0.73) c = wheelCommands(-0.42, s * 0.48, false);
    else c = wheelCommands(0, s * 1.0, false);
    mem.bumpTimer = Math.max(0, remaining - dt);
    return emit(c, false);
  }

  if (mem.returning) {
    if (atBase) {
      return emit(stopCommands(), false);
    }
    const bd = beacon ? Math.max(0, num(beacon.distance, 99)) : 99;
    if (bd <= 3.0 || baseDistGps <= 2.15) {
      return emit(stopCommands(), false);
    }
    let err, d;
    if (beacon && bd <= 20.5) {
      err = num(beacon.bearing, 0);
      d = bd;
    } else {
      err = wrap(deg(Math.atan2(mem.baseY - poseY, mem.baseX - poseX)) - mem.theta);
      d = baseDistGps;
    }
    recordProgress("base", d, null);
    const cruise = mem.rangeTrust < 0.7 ? 0.78 : 1.42;
    return emit(navCommands(err, cruise), false);
  }

  if (atBase && carried > 0) {
    return emit(stopCommands(), false);
  }

  function taskPlan(info) {
    if (!info) return { out: 0, home: 0, extra: 0 };
    if (info.kind === "site") {
      return {
        out: Math.max(0, num(info.dist, distance(poseX, poseY, info.x, info.y))),
        home: distance(info.x, info.y, mem.baseX, mem.baseY),
        extra: 0
      };
    }
    if (info.kind === "hint") {
      const h = mem.hints[info.hintIndex];
      return {
        out: distance(poseX, poseY, info.x, info.y),
        home: h ? distance(h.x, h.y, mem.baseX, mem.baseY) :
                  distance(info.x, info.y, mem.baseX, mem.baseY),
        extra: num(info.extra, 60)
      };
    }
    return {
      out: distance(poseX, poseY, info.x, info.y),
      home: distance(info.x, info.y, mem.baseX, mem.baseY),
      extra: 0
    };
  }

  let info = taskInfo();

  if (atBase && carried === 0) {
    if (!info) return emit(stopCommands(), false);
    const plan = taskPlan(info);
    const need = energyForPlan(plan.out, plan.home, plan.extra, 0);
    const requiredTime = (plan.out + plan.home + plan.extra) / 0.98 + 34;
    if (battery + 0.002 < need || timeLeft < requiredTime + 2) {
      return emit(stopCommands(), false);
    }
    if (Math.max(Math.abs(wl), Math.abs(wr)) > 0.22) {
      return emit(stopCommands(), false);
    }
  }

  if (mem.sampleActive) {
    let sd = 99;
    if (siteObs) sd = Math.max(0, num(siteObs.distance, 99));
    else if (mem.activeSite) sd = distance(poseX, poseY, mem.activeSite.x, mem.activeSite.y);
    if (sd <= 1.55) {
      const c = holdCommands();
      return emit(c, true);
    }
    mem.sampleActive = false;
    mem.stillTime = 0;
    mem.holdReady = false;
  }

  if (!info) info = taskInfo();
  if (!info) {
    if (!atBase && carried > 0) {
      mem.returning = true;
      const err = beacon && beaconDist <= 20.5 ? num(beacon.bearing, 0) :
        wrap(deg(Math.atan2(mem.baseY - poseY, mem.baseX - poseX)) - mem.theta);
      return emit(navCommands(err, mem.rangeTrust < 0.7 ? 0.78 : 1.35), false);
    }
    return emit(stopCommands(), false);
  }

  if (info.kind === "site") {
    const sd = siteObs ? Math.max(0, num(siteObs.distance, 99)) :
               distance(poseX, poseY, info.x, info.y);
    const se = siteObs ? num(siteObs.bearing, 0) :
               wrap(deg(Math.atan2(info.y - poseY, info.x - poseX)) - mem.theta);

    if (sd <= 1.28) {
      if (!mem.holdReady) {
        mem.holdX = poseX;
        mem.holdY = poseY;
        mem.holdHeading = mem.theta;
        mem.holdBias = 0;
        mem.holdReady = true;
      }
      const c = holdCommands();
      const still = Math.max(Math.abs(wl), Math.abs(wr)) < 0.145;
      if (still && sd <= 1.3) mem.stillTime = num(mem.stillTime, 0) + dt;
      else mem.stillTime = 0;

      if (!mem.sampleActive && mem.stillTime >= 0.38) {
        mem.sampleActive = true;
        mem.pendingMeta = {
          x: num(mem.activeSite && mem.activeSite.x, poseX),
          y: num(mem.activeSite && mem.activeSite.y, poseY),
          value: num(mem.activeSite && mem.activeSite.value, info.value)
        };
        return emit(c, true);
      }
      return emit(c, !!mem.sampleActive);
    }

    mem.holdReady = false;
    mem.stillTime = 0;
    const maxV = sd < 3 ? 0.62 : (sd < 6 ? 0.82 : 1.0);
    recordProgress("site", sd, info);
    return emit(navCommands(se, maxV), false);
  }

  recordProgress(info.key, info.dist, info);

  let maxV;
  if (info.kind === "global") maxV = mem.rangeTrust < 0.7 ? 0.82 : 1.28;
  else if (info.phase === "search") maxV = mem.rangeTrust < 0.7 ? 0.82 : 1.22;
  else maxV = mem.rangeTrust < 0.7 ? 0.88 : 1.42;

  return emit(navCommands(info.error, maxV), false);
}

function act(obs, mem) {
  const o = obs || {};
  if (!mem || typeof mem !== "object") mem = {};

  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
  const num = (v, d) => {
    const n = Number(v);
    return Number.isFinite(n) ? n : d;
  };
  const wrap = (a) => {
    a = (a + 180) % 360;
    if (a < 0) a += 360;
    return a - 180;
  };
  const rad = (d) => d * Math.PI / 180;
  const deg = (r) => r * 180 / Math.PI;
  const dist = (x1, y1, x2, y2) => Math.hypot(x2 - x1, y2 - y1);

  const tNow = num(o.t, 0);
  const rawH = wrap(num(o.heading, 0));
  let dt = 0.1;
  if (Number.isFinite(mem.prevT)) {
    const d = tNow - mem.prevT;
    if (d > 0 && d <= 0.5) dt = d;
  }
  if (dt < 0.03 || dt > 0.5) dt = 0.1;

  if (!mem._init) {
    const m = o.mission && typeof o.mission === "object" ? o.mission : {};
    const sz = m.size;
    let width = 400, height = 400;
    if (typeof sz === "number") {
      width = height = sz;
    } else if (Array.isArray(sz)) {
      width = num(sz[0], 400);
      height = num(sz[1], width);
    } else if (sz && typeof sz === "object") {
      width = num(sz.width, num(sz.w, num(sz.x, 400)));
      height = num(sz.height, num(sz.h, num(sz.y, width)));
    }
    width = Math.max(50, width);
    height = Math.max(50, height);

    const b = m.base && typeof m.base === "object"
      ? m.base
      : { x: width * 0.5, y: height * 0.5 };

    mem.width = width;
    mem.height = height;
    mem.baseX = num(b.x, width * 0.5);
    mem.baseY = num(b.y, height * 0.5);
    mem.seconds = num(m.seconds, 1200);
    mem.capacity = Math.max(1, Math.floor(num(m.capacity, 5)));

    mem.hints = [];
    const hints = Array.isArray(m.hints) ? m.hints : [];
    for (let i = 0; i < hints.length; i++) {
      const h = hints[i] || {};
      mem.hints.push({
        x: clamp(num(h.x, mem.baseX), 3, width - 3),
        y: clamp(num(h.y, mem.baseY), 3, height - 3),
        value: Math.max(0.1, num(h.estimate, num(h.value, 1))),
        status: 0,
        phase: "center",
        step: 0,
        retry: 0,
        angle: 0,
        bestScience: 0,
        bestX: num(h.x, mem.baseX),
        bestY: num(h.y, mem.baseY)
      });
