    const mx = Math.min(30, width * 0.18);
    const my = Math.min(30, height * 0.18);
    const nx = Math.min(12, Math.max(2, Math.ceil((width - 2 * mx) / 70) + 1));
    const ny = Math.min(12, Math.max(2, Math.ceil((height - 2 * my) / 70) + 1));
    for (let iy = 0; iy < ny; iy++) {
      const y = my + (height - 2 * my) * iy / Math.max(1, ny - 1);
      for (let ix = 0; ix < nx; ix++) {
