    mem.px = x0;
    mem.py = y0;
    mem.theta = rawH;
    mem.headingBias = 0;
    mem.prevRawH = rawH;
    mem.prevT = tNow;

    mem.lastGpsX = x0;
    mem.lastGpsY = y0;
    mem.gpsUnchanged = 0;
    mem.gpsTravelSinceChange = 0;
    mem.gpsFrozen = false;
    mem.gpsRecover = 0;
    mem.wasGpsFrozen = false;
    mem.compassHold = 0;

    mem.cal = {
