  const wasFrozen = !!mem.gpsFrozen;
  mem.gpsFrozen = mem.gpsUnchanged > 2.7 && mem.gpsTravelSinceChange > 1.7;
  if (wasFrozen && !mem.gpsFrozen) mem.gpsRecover = 1.2;
  else mem.gpsRecover = Math.max(0, num(mem.gpsRecover, 0) - dt);

  const midTheta = rad(wrap((prevTheta + theta) * 0.5));
  let predX = num(mem.px, rawX) + vWheel * dt * Math.cos(midTheta);
  let predY = num(mem.py, rawY) + vWheel * dt * Math.sin(midTheta);
  if (!mem.gpsFrozen && !gpsJump) {
    const residual = dist(rawX, rawY, predX, predY);
    if (residual < 15) {
      let alpha = Math.abs(vWheel) > 0.25 ? 0.065 : 0.025;
      if (mem.gpsRecover > 0) alpha = 0.13;
      predX += (rawX - predX) * alpha;
      predY += (rawY - predY) * alpha;
    }
  }
  mem.px = predX;
  mem.py = predY;
  mem.lastGpsX = rawX;
  mem.lastGpsY = rawY;
  mem.prevRawH = rawH;

  const straightForward = vWheel > 0.32 &&
    Math.abs(wr - wl) < 0.25 &&
    !mem.gpsFrozen && !gpsJump && !compassJump;
  if (straightForward) {
    if (!mem.cal || !mem.cal.active) {
      mem.cal = {
        active: true, x: rawX, y: rawY,
        sin: 0, cos: 0, n: 0
      };
    }
    mem.cal.sin += Math.sin(rad(rawH));
    mem.cal.cos += Math.cos(rad(rawH));
    mem.cal.n += 1;
    const calDist = dist(rawX, rawY, mem.cal.x, mem.cal.y);
    if (calDist >= 8 && mem.cal.n >= 10) {
      const course = deg(Math.atan2(rawY - mem.cal.y, rawX - mem.cal.x));
      const meanRaw = deg(Math.atan2(mem.cal.sin, mem.cal.cos));
      const biasEstimate = wrap(meanRaw - course);
      const biasError = wrap(biasEstimate - num(mem.headingBias, 0));
      if (Math.abs(biasError) < 65) {
        mem.headingBias = wrap(num(mem.headingBias, 0) +
          clamp(biasError * 0.18, -4, 4));
      }
      mem.cal = {
        active: true, x: rawX, y: rawY,
        sin: 0, cos: 0, n: 0
      };
    }
  } else if (mem.cal) {
    mem.cal.active = false;
    mem.cal.sin = 0;
    mem.cal.cos = 0;
    mem.cal.n = 0;
  }

  if (!Array.isArray(mem.gains) || mem.gains.length < 2) {
    mem.gains = [[2.8, 2.8], [2.8, 2.8]];
  }
  if (!Array.isArray(mem.lastCmd) || mem.lastCmd.length < 2) mem.lastCmd = [0, 0];
  for (let s = 0; s < 2; s++) {
    const cmd = num(mem.lastCmd[s], 0);
    const actual = s === 0 ? wl : wr;
    if (Math.abs(cmd) > 0.18 && actual * cmd > 0.012 && Math.abs(actual) > 0.035) {
      const dir = cmd < 0 ? 1 : 0;
      const ratio = Math.abs(actual / cmd);
      if (ratio > 0.20 && ratio < 5.8) {
        const old = num(mem.gains[s][dir], 2.8);
        const a = ratio < old * 0.65 ? 0.08 : 0.025;
        mem.gains[s][dir] = clamp(old + (ratio - old) * a, 0.65, 5.5);
      }
    }
  }

  const previousBattery = num(mem.prevBattery, battery);
  if (!o.docked && drillProgress < 0.05 && moveDist > 0.025) {
    const drop = previousBattery - battery;
    const estimatedUse = clamp(drop + solar * dt * 0.18, 0, 0.025);
    mem.energyUse = num(mem.energyUse, 0) + estimatedUse;
    mem.energyDist = num(mem.energyDist, 0) + moveDist;
    if (mem.energyDist >= 8) {
      const measured = clamp(mem.energyUse / Math.max(4, mem.energyDist), 0.00035, 0.006);
      const old = num(mem.eRate, 0.0012);
      const a = measured > old ? 0.32 : 0.10;
      mem.eRate = clamp(old + (measured - old) * a, 0.00035, 0.006);
      mem.energyUse = 0;
      mem.energyDist = 0;
    }
  }
  mem.prevBattery = battery;

  const rawRays = o.rays && typeof o.rays.length === "number" ? o.rays : null;
  if (!Array.isArray(mem.rFilt) || mem.rFilt.length !== 9) {
    mem.rFilt = [];
    mem.rRaw = [];
    mem.rSameTime = [];
    mem.rSameMotion = [];
    mem.rBad = [];
    for (let i = 0; i < 9; i++) {
      mem.rFilt[i] = 15;
      mem.rRaw[i] = 15;
      mem.rSameTime[i] = 0;
      mem.rSameMotion[i] = 0;
      mem.rBad[i] = false;
    }
  }
  let allMax = true;
  let anyNear = false;
  for (let i = 0; i < 9; i++) {
    const r = clamp(rawRays ? num(rawRays[i], 15) : 15, 0, 15);
    if (r < 14.8) allMax = false;
    if (r < 14.5) anyNear = true;

    const last = num(mem.rRaw[i], r);
    const diff = Math.abs(r - last);
    if (diff < 0.025) {
      if (moveDist > 0.02 || Math.abs(yawRad) > 0.015) {
        mem.rSameTime[i] = num(mem.rSameTime[i], 0) + dt;
        mem.rSameMotion[i] = num(mem.rSameMotion[i], 0) +
          moveDist + Math.abs(yawRad) * 1.05;
      }
    } else if (diff > 0.30) {
      mem.rSameTime[i] = 0;
      mem.rSameMotion[i] = 0;
      mem.rBad[i] = false;
    }
    if (mem.rSameTime[i] > 5 && mem.rSameMotion[i] > 3.2 && r < 14.5) {
      mem.rBad[i] = true;
    }

    const effective = mem.rBad[i] ? Math.max(r, 6.0) : r;
    let f = num(mem.rFilt[i], effective);
    if (effective < f) f += (effective - f) * 0.58;
    else f += (effective - f) * 0.32;
    mem.rFilt[i] = clamp(f, 0, 15);
    mem.rRaw[i] = r;
  }
  if (allMax && moveDist > 0.02) {
    mem.allMaxTravel = num(mem.allMaxTravel, 0) + moveDist;
  } else if (anyNear) {
    mem.allMaxTravel = Math.max(0, num(mem.allMaxTravel, 0) - moveDist * 1.2);
  }
  mem.rangeTrust = mem.allMaxTravel > 20 ? 0.76 : 1;

  const oldCarried = num(mem.prevCarried, carried);
  const oldDelivered = num(mem.prevDelivered, delivered);
  const oldCarriedValue = num(mem.prevCarriedValue, carriedValue);

  if (carried > oldCarried) {
    const meta = mem.pendingMeta || mem.siteLock || {
      x: mem.px, y: mem.py, value: 1
    };
    const mx = num(meta.x, mem.px);
    const my = num(meta.y, mem.py);
    let value = Math.max(0.1, num(meta.value, 1));
    const valueGain = carriedValue - oldCarriedValue;
    if (valueGain > 0.01) value = valueGain / Math.max(1, carried - oldCarried);
    mem.samples.push({ x: mx, y: my, value: value });

    let associated = -1;
    let bestAssociation = 32;
    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (!h || h.status >= 2) continue;
      const d = dist(mx, my, h.x, h.y);
      if (d < bestAssociation) {
        bestAssociation = d;
        associated = i;
      }
    }
    const currentHint = Math.floor(num(mem.currentHint, -1));
    if (currentHint >= 0 && currentHint < mem.hints.length &&
        mem.hints[currentHint].status < 2 &&
        dist(mx, my, mem.hints[currentHint].x, mem.hints[currentHint].y) < 36) {
      associated = currentHint;
    }
    if (associated >= 0) {
      mem.hints[associated].status = 2;
      if (associated === currentHint) mem.currentHint = -1;
    }
    for (let i = 0; i < mem.globalPoints.length; i++) {
      const p = mem.globalPoints[i];
      if (dist(mx, my, p.x, p.y) < 9) p.done = true;
    }
    if (mem.ambient && dist(mx, my, mem.ambient.x, mem.ambient.y) < 36) {
      mem.ambient = null;
    }
    mem.sampleActive = false;
    mem.pendingMeta = null;
    mem.siteLock = null;
    mem.holdReady = false;
    mem.stillTime = 0;
    mem.navKey = "";
  } else if (carried < oldCarried || delivered > oldDelivered) {
    mem.sampleActive = false;
    mem.pendingMeta = null;
    mem.siteLock = null;
    mem.holdReady = false;
    mem.stillTime = 0;
  }

  if (siteObs && carried < mem.capacity) {
    const sd = Math.max(0, num(siteObs.distance, 99));
    const sb = num(siteObs.bearing, 0);
    const a = rad(mem.theta + sb);
    const sx = mem.px + sd * Math.cos(a);
    const sy = mem.py + sd * Math.sin(a);
    const sv = Math.max(0.1, num(siteObs.value, 1));
    if (!mem.siteLock) {
      mem.siteLock = { x: sx, y: sy, value: sv, lastSeen: tNow };
    } else {
      const gap = dist(mem.siteLock.x, mem.siteLock.y, sx, sy);
      if (gap > 10) {
        mem.siteLock.x = sx;
        mem.siteLock.y = sy;
      } else {
        mem.siteLock.x = mem.siteLock.x * 0.70 + sx * 0.30;
        mem.siteLock.y = mem.siteLock.y * 0.70 + sy * 0.30;
      }
      mem.siteLock.value = sv;
      mem.siteLock.lastSeen = tNow;
    }
  }

  if (!mem.sampleActive && drillProgress > 0.05 && mem.siteLock) {
    mem.sampleActive = true;
    mem.sampleStart = tNow;
    if (!mem.holdReady) {
      mem.holdX = mem.px;
      mem.holdY = mem.py;
      mem.holdHeading = mem.theta;
      mem.holdReady = true;
    }
    mem.pendingMeta = {
      x: mem.siteLock.x, y: mem.siteLock.y, value: mem.siteLock.value
    };
  }

  const poseX = mem.px;
  const poseY = mem.py;
  const baseDist = dist(poseX, poseY, mem.baseX, mem.baseY);
  const beaconDist = beacon ? Math.max(0, num(beacon.distance, 99)) : 99;
  const beaconUsable = !!beacon && beaconDist <= 20.5;
  const maxWheelSpeed = Math.max(Math.abs(wl), Math.abs(wr));
  const atBase = !!o.docked ||
    (beacon && beaconDist <= 2.55) ||
    (!beaconUsable && baseDist <= 2.0 && maxWheelSpeed < 0.25);
  const homeDist = beaconUsable ? beaconDist : baseDist;

  function homeNeed(d, load) {
    const l = Math.max(0, load);
    return 0.12 +
      num(mem.eRate, 0.0012) *
        (Math.max(0, d) * 1.55 + 14) * (1 + 0.18 * l) +
      0.012 * l;
  }
  function homeSeconds(d, load) {
    return Math.max(0, d) / 0.62 + 40 + Math.max(0, load) * 4;
  }
  function routeEnergy(outDist, homeDistPlan, extra, load) {
    const l = Math.max(0, load);
    const metres = Math.max(0, outDist) * 1.35 +
      Math.max(0, homeDistPlan) * 1.55 +
      Math.max(0, extra) * 1.25 + 22;
    return 0.13 +
      num(mem.eRate, 0.0012) * metres * (1 + 0.17 * l) +
      0.014 * l;
  }
  function routeSeconds(outDist, homeDistPlan, extra, load) {
    return (Math.max(0, outDist) + Math.max(0, homeDistPlan) +
      Math.max(0, extra)) * 1.45 + 50 + Math.max(0, load) * 5;
  }

  if (delivered > oldDelivered && carried === 0 && atBase) {
    mem.returning = false;
  }
  if (mem.returning && atBase && carried === 0) {
    mem.returning = false;
    mem.sampleActive = false;
    mem.holdReady = false;
    mem.stillTime = 0;
  }

  const estimatedHomeNeed = homeNeed(homeDist, carried);
  const estimatedHomeTime = homeSeconds(homeDist, carried);
  if (!mem.returning) {
    if (carried >= mem.capacity && !mem.sampleActive) {
      mem.returning = true;
    } else if (carried > 0 && !mem.sampleActive &&
        (battery < estimatedHomeNeed + 0.075 ||
         timeLeft < estimatedHomeTime + 20)) {
      mem.returning = true;
    } else if (!atBase && carried === 0 && !mem.sampleActive &&
        (battery < estimatedHomeNeed + 0.04 ||
         timeLeft < estimatedHomeTime + 10)) {
      mem.returning = true;
    } else if (mem.sampleActive &&
        (battery < estimatedHomeNeed + 0.012 ||
         timeLeft < estimatedHomeTime + 5)) {
      mem.returning = true;
    }
  }

  function gainFor(side, target) {
    const dir = target < -0.02 ? 1 : 0;
    const row = mem.gains[side] || [2.8, 2.8];
    return clamp(num(row[dir], 2.8), 0.65, 5.5);
  }
  function wheelPower(target, actual, side, hold) {
    const gain = gainFor(side, target);
    const kp = hold ? 0.27 : 0.21;
    let u = target / gain + kp * (target - actual);
    if (Math.abs(target) < 0.04) {
      u = -actual * (hold ? 0.26 : 0.22);
    } else if (Math.abs(target) > 0.16 &&
        Math.abs(target - actual) > 0.16 && Math.abs(u) < 0.135) {
      u = Math.sign(target) * 0.135;
    }
    return clamp(u, -1, 1);
  }
  function wheelCommands(v, omega, hold) {
    const leftTarget = clamp(v - 0.3 * omega, -1.35, 1.35);
    const rightTarget = clamp(v + 0.3 * omega, -1.35, 1.35);
    return {
      left: wheelPower(leftTarget, wl, 0, !!hold),
      right: wheelPower(rightTarget, wr, 1, !!hold)
    };
  }
  function stopCommands() {
    return wheelCommands(0, 0, false);
  }

  function rayAt(angle) {
    const a = clamp(angle, -80, 80);
    const q = (a + 80) / 20;
    const i = Math.floor(q);
    const f = q - i;
    if (i >= 8) return num(mem.rFilt[8], 15);
    return num(mem.rFilt[i], 15) * (1 - f) +
      num(mem.rFilt[i + 1], 15) * f;
  }
  function clearanceAt(angle) {
    const center = rayAt(angle);
    const side = Math.min(rayAt(angle - 20), rayAt(angle + 20));
    return Math.min(center, center * 0.74 + side * 0.26);
  }
  function edgeDistance(angle) {
    const a = rad(wrap(mem.theta + angle));
    const dx = Math.cos(a), dy = Math.sin(a);
    const margin = 5;
    let d = 1e6;
    if (dx > 0.001) d = Math.min(d, (mem.width - margin - poseX) / dx);
    if (dx < -0.001) d = Math.min(d, (margin - poseX) / dx);
    if (dy > 0.001) d = Math.min(d, (mem.height - margin - poseY) / dy);
    if (dy < -0.001) d = Math.min(d, (margin - poseY) / dy);
    return Math.max(0, d);
  }

  function navCommands(goalError, maxV) {
    const goal = wrap(num(goalError, 0));
    const vmax = clamp(num(maxV, 0.75), 0, 0.95);

    if (Math.abs(goal) > 102) {
      const s = Math.sign(goal) || 1;
      mem.lastAim = s * 90;
      return wheelCommands(0, s * 0.72, false);
    }

    const clippedGoal = clamp(goal, -80, 80);
    const candidates = [-80, -60, -40, -20, 0, 20, 40, 60, 80, clippedGoal];
    const safe = 2.75 + 0.45 * vmax;
    const front = clearanceAt(0);
    let best = clippedGoal;
    let bestCost = 1e9;
    let bestClear = 15;

    for (let i = 0; i < candidates.length; i++) {
      const a = candidates[i];
      const clear = clearanceAt(a);
      let cost = Math.abs(wrap(a - clippedGoal)) * 0.026;
      const hazard = Math.max(0, safe - clear);
      cost += hazard * hazard * 1.9;
      if (clear < 1.25) cost += 12;
      if (clear < 0.75) cost += 24;

      const e = edgeDistance(a);
      if (e < 2.5) cost += 16;
      else if (e < 8) cost += (8 - e) * 0.75;

      if (front < safe && Math.abs(a) > 10 && mem.avoidSign &&
          Math.sign(a) !== Math.sign(mem.avoidSign)) {
        cost += 0.22;
      }
      if (front < safe) {
        cost += Math.abs(a - num(mem.lastAim, a)) * 0.004;
      }

      if (cost < bestCost) {
        bestCost = cost;
        best = a;
        bestClear = clear;
      }
    }

    if (front > safe + 1.5) mem.avoidSign = 0;
    else if (Math.abs(best) > 10) mem.avoidSign = Math.sign(best);
    mem.lastAim = best;

    let v = vmax;
    const scale = clamp((bestClear - 0.8) / Math.max(1.0, safe - 0.8), 0.12, 1);
    v *= scale;
    if (bestClear < 1.2) v = Math.min(v, 0.14);
    if (front < 1.0 && Math.abs(best) < 18) v = Math.min(v, 0.10);

    if (Math.abs(best) > 60) v = Math.min(v, 0.22);
    else if (Math.abs(best) > 42) v = Math.min(v, 0.42);
    else if (Math.abs(best) > 27) v = Math.min(v, 0.65);

    if (mem.rangeTrust < 0.8) v = Math.min(v, 0.70);

    const omega = clamp(1.35 * rad(best), -0.78, 0.78);
    return wheelCommands(v, omega, false);
  }

  function holdCommands() {
    if (!mem.holdReady) {
      mem.holdX = poseX;
      mem.holdY = poseY;
      mem.holdHeading = mem.theta;
      mem.holdReady = true;
    }
    const a = rad(mem.theta);
    const dx = num(mem.holdX, poseX) - poseX;
    const dy = num(mem.holdY, poseY) - poseY;
    const along = dx * Math.cos(a) + dy * Math.sin(a);
    const cross = -dx * Math.sin(a) + dy * Math.cos(a);
    const avg = (wl + wr) * 0.5;
    const limit = mem.sampleActive ? 0.085 : 0.18;
    const vDes = clamp(0.55 * along - 0.70 * avg, -limit, limit);
    const headingErr = wrap(num(mem.holdHeading, mem.theta) - mem.theta);
    const omega = clamp(1.0 * rad(headingErr) +
      clamp(cross * 0.06, -0.07, 0.07),
      mem.sampleActive ? -0.16 : -0.32,
      mem.sampleActive ? 0.16 : 0.32);
    const c = wheelCommands(vDes, omega, true);
    const pitchFeed = clamp(num(o.pitch, 0) * 0.007, -0.09, 0.09);
    c.left = clamp(c.left + pitchFeed, -1, 1);
    c.right = clamp(c.right + pitchFeed, -1, 1);
    return c;
  }

  function emit(c, drill) {
    const left = clamp(num(c && c.left, 0), -1, 1);
    const right = clamp(num(c && c.right, 0), -1, 1);
    mem.lastCmd = [left, right];
    mem.prevT = tNow;
    mem.prevCarried = carried;
    mem.prevCarriedValue = carriedValue;
    mem.prevDelivered = delivered;
    return { left: left, right: right, drill: !!drill };
  }

  function openSide() {
    let leftOpen = 0, rightOpen = 0;
    for (let i = 5; i < 9; i++) leftOpen += num(mem.rFilt[i], 15);
    for (let i = 0; i < 4; i++) rightOpen += num(mem.rFilt[i], 15);
    return leftOpen >= rightOpen ? 1 : -1;
  }

  function recoveryAction() {
    const rem = Math.max(0, num(mem.recoverTimer, 0));
    const s = num(mem.recoverSign, 1);
    let c;
    const reverseTime = mem.recoverMode === 1 ? 0.72 : 0.62;
    if (rem > reverseTime) c = wheelCommands(-0.28, s * 0.44, false);
    else c = wheelCommands(0, s * 0.70, false);
    mem.recoverTimer = Math.max(0, rem - dt);
    if (mem.recoverTimer <= 0) mem.recoverMode = 0;
    return emit(c, false);
  }

  function skipStalledTarget(info) {
    if (!info) return;
    if (info.kind === "hint" && info.index >= 0 && info.index < mem.hints.length) {
      const h = mem.hints[info.index];
      if (h) {
        if (info.phase === "center") {
          h.phase = "ring";
          h.step = 0;
          h.bestScience = Math.max(num(h.bestScience, 0), science);
        } else {
          h.step = Math.min(16, Math.max(0, Math.floor(num(h.step, 0))) + 1);
        }
      }
    } else if (info.kind === "ambient" && mem.ambient) {
      mem.ambient.step = Math.min(24, mem.ambient.step + 1);
    } else if (info.kind === "global" && info.index >= 0 &&
        info.index < mem.globalPoints.length) {
      mem.globalPoints[info.index].done = true;
      mem.globalIndex = -1;
    }
  }

  function updateProgress(key, d, info) {
    if (mem.navKey !== key) {
      mem.navKey = key;
      mem.navBest = d;
      mem.navStuck = 0;
      mem.stuckCount = 0;
      return false;
    }
    if (d < num(mem.navBest, d) - 0.65) {
      mem.navBest = d;
      mem.navStuck = 0;
      mem.stuckCount = 0;
      return false;
    }
    mem.navStuck = num(mem.navStuck, 0) + dt;
    if (mem.navStuck > 19) {
      mem.navStuck = 0;
      mem.navBest = d;
      mem.stuckCount = num(mem.stuckCount, 0) + 1;
      mem.recoverSign = openSide();
      if (mem.avoidSign) mem.recoverSign = -mem.avoidSign;
      mem.avoidSign = mem.recoverSign;
      mem.recoverTimer = 1.75;
      mem.recoverMode = 2;
      if (mem.stuckCount >= 3) {
        skipStalledTarget(info);
        mem.navKey = "";
        mem.stuckCount = 0;
      }
      return true;
    }
    return false;
  }

  function goHome() {
    if (atBase || homeDist <= 2.25) return emit(stopCommands(), false);
    let err;
    if (beaconUsable) err = num(beacon.bearing, 0);
    else err = wrap(deg(Math.atan2(mem.baseY - poseY, mem.baseX - poseX)) - mem.theta);
    if (updateProgress("base", homeDist, { kind: "base" })) {
      return recoveryAction();
    }
    const speed = homeDist > 18 ? 0.84 : (homeDist > 7 ? 0.55 : 0.32);
    return emit(navCommands(err, speed), false);
  }

  if (o.bumped && !mem.prevBumped && !mem.sampleActive && !atBase) {
    mem.recoverSign = openSide();
    mem.recoverTimer = 1.42;
    mem.recoverMode = 1;
  }
  mem.prevBumped = !!o.bumped;

  if (mem.returning && atBase && carried === 0) {
    mem.returning = false;
    mem.sampleActive = false;
    mem.holdReady = false;
    mem.stillTime = 0;
  }

  if (atBase && carried > 0) {
    return emit(stopCommands(), false);
  }

  if (mem.recoverTimer > 0 && !atBase && !mem.sampleActive) {
    return recoveryAction();
  }

  if (mem.returning && !atBase) {
    return goHome();
  }

  if (mem.sampleActive) {
    const sd = siteObs
      ? Math.max(0, num(siteObs.distance, 99))
      : (mem.siteLock
        ? dist(poseX, poseY, mem.siteLock.x, mem.siteLock.y)
        : 99);

    if (tNow - num(mem.sampleStart, tNow) > 22 &&
        drillProgress < 5.5 && carried === oldCarried) {
      mem.sampleActive = false;
      mem.sampleFailures = num(mem.sampleFailures, 0) + 1;
      mem.holdReady = false;
      mem.stillTime = 0;
    } else if ((siteObs && sd > 1.70) || (!siteObs && sd > 2.15)) {
      mem.sampleActive = false;
      mem.holdReady = false;
      mem.stillTime = 0;
    } else {
      if (!mem.holdReady) {
        mem.holdX = poseX;
        mem.holdY = poseY;
        mem.holdHeading = mem.theta;
        mem.holdReady = true;
      }
      return emit(holdCommands(), true);
    }
  }

  if (siteObs && carried < mem.capacity && !mem.returning) {
    const sd = Math.max(0, num(siteObs.distance, 99));
    const sb = num(siteObs.bearing, 0);

    if (sd <= 1.35) {
      if (!mem.holdReady) {
        mem.holdX = poseX;
        mem.holdY = poseY;
        mem.holdHeading = mem.theta;
        mem.holdReady = true;
      }
      const c = holdCommands();
      const still = Math.max(Math.abs(wl), Math.abs(wr)) < 0.13;
      if (still && sd <= 1.43) mem.stillTime = num(mem.stillTime, 0) + dt;
      else mem.stillTime = 0;

      let drill = false;
      if (mem.stillTime >= 0.32) {
        mem.sampleActive = true;
        mem.sampleStart = tNow;
        mem.pendingMeta = mem.siteLock
          ? { x: mem.siteLock.x, y: mem.siteLock.y, value: mem.siteLock.value }
          : { x: poseX, y: poseY, value: num(siteObs.value, 1) };
        drill = true;
      }
      return emit(c, drill);
    }

    mem.holdReady = false;
    mem.stillTime = 0;
    if (updateProgress("site", sd, { kind: "site" })) return recoveryAction();
    const speed = sd > 6 ? 0.82 : (sd > 3 ? 0.55 : 0.30);
    return emit(navCommands(sb, speed), false);
  }

  if (atBase && carried === 0 && maxWheelSpeed > 0.24) {
    return emit(stopCommands(), false);
  }

  function remainingHintSearch(h) {
    if (!h) return 0;
    if (h.phase === "ring") {
      return Math.max(0, 16 - Math.max(0, Math.floor(num(h.step, 0)))) * 5.8;
    }
    return 103;
  }

  function chooseHint() {
    let best = -1;
    let bestScore = -1;
    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (!h || h.status >= 2) continue;
      const d = dist(poseX, poseY, h.x, h.y);
      const home = dist(h.x, h.y, mem.baseX, mem.baseY);
      const extra = remainingHintSearch(h);
      const need = routeEnergy(d, home, extra, carried);
      const tneed = routeSeconds(d, home, extra, carried);
      if (need > battery - 0.015 || tneed > timeLeft - 8) continue;
      let score = Math.pow(Math.max(0.1, h.value), 1.14) /
        (55 + d + 0.72 * home + 0.48 * extra + 9 * carried);
      if (h.status === 1) score *= 1.06;
      if (i === Math.floor(num(mem.currentHint, -1))) score *= 1.05;
      if (score > bestScore) {
        bestScore = score;
        best = i;
      }
    }
    return best;
  }

  function ringPoint(cx, cy, step, count, radius, offset) {
    const a = num(offset, 0) + 2 * Math.PI * step / count;
    return {
      x: clamp(cx + radius * Math.cos(a), 3, mem.width - 3),
      y: clamp(cy + radius * Math.sin(a), 3, mem.height - 3)
    };
  }

  function getTask() {
    for (let tries = 0; tries < 30; tries++) {
      let hi = Math.floor(num(mem.currentHint, -1));
      if (hi >= 0 && hi < mem.hints.length && mem.hints[hi].status < 2) {
        const h = mem.hints[hi];

        if (h.phase === "center") {
          const d = dist(poseX, poseY, h.x, h.y);
          if (d <= 3.8) {
            h.phase = "ring";
            h.step = 0;
            h.bestScience = science;
            h.bestX = poseX;
            h.bestY = poseY;
            continue;
          }
          return {
            kind: "hint", index: hi, phase: "center",
            x: h.x, y: h.y, dist: d,
            home: dist(h.x, h.y, mem.baseX, mem.baseY),
            extra: 103, key: "hc:" + hi
          };
        }

        if (h.phase === "ring") {
          if (science > num(h.bestScience, 0)) {
            h.bestScience = science;
            h.bestX = poseX;
            h.bestY = poseY;
          }
          let step = Math.max(0, Math.floor(num(h.step, 0)));
          while (step < 16) {
            const p = ringPoint(h.x, h.y, step, 16, 14, h.angle);
            const d = dist(poseX, poseY, p.x, p.y);
            if (d <= 2.4) {
              step++;
              h.step = step;
              continue;
            }
            return {
              kind: "hint", index: hi, phase: "ring", step: step,
              x: p.x, y: p.y, dist: d,
              home: dist(h.x, h.y, mem.baseX, mem.baseY),
              extra: Math.max(0, (16 - step) * 5.8),
              key: "hr:" + hi + ":" + step
            };
          }

          if (num(h.bestScience, 0) > 1.45 && !h.retry &&
              dist(h.bestX, h.bestY, h.x, h.y) > 3) {
            h.retry = 1;
            h.x = clamp(num(h.bestX, h.x), 3, mem.width - 3);
            h.y = clamp(num(h.bestY, h.y), 3, mem.height - 3);
            h.phase = "center";
            h.step = 0;
            h.bestScience = 0;
            continue;
          }

          h.status = 2;
          mem.currentHint = -1;
          continue;
        }

        h.phase = "center";
        continue;
      }

      mem.currentHint = -1;
      const nextHint = chooseHint();
      if (nextHint >= 0) {
        mem.currentHint = nextHint;
        mem.hints[nextHint].status = 1;
        continue;
      }
      break;
    }

    if (mem.currentHint >= 0) return null;

    if (!mem.ambient && science > 1.0 &&
        dist(poseX, poseY, num(mem.ambientLastX, -1e9),
          num(mem.ambientLastY, -1e9)) > 35) {
      mem.ambient = {
        x: poseX, y: poseY, step: 0,
        bestScience: science
      };
    }

    if (mem.ambient) {
      const a = mem.ambient;
      if (science > num(a.bestScience, 0)) a.bestScience = science;
      let step = Math.max(0, Math.floor(num(a.step, 0)));
      while (step < 24) {
        const p = ringPoint(a.x, a.y, step, 24, 22, 0);
        const d = dist(poseX, poseY, p.x, p.y);
        if (d <= 2.4) {
          step++;
          a.step = step;
          continue;
        }
        return {
          kind: "ambient", index: step,
          x: p.x, y: p.y, dist: d,
          home: dist(a.x, a.y, mem.baseX, mem.baseY),
          extra: Math.max(0, (24 - step) * 5.75),
          key: "a:" + step
        };
      }
      mem.ambientLastX = a.x;
      mem.ambientLastY = a.y;
      mem.ambient = null;
    }

    let gi = Math.floor(num(mem.globalIndex, -1));
    if (gi >= 0 && gi < mem.globalPoints.length &&
        mem.globalPoints[gi].done) {
      gi = -1;
      mem.globalIndex = -1;
    }
    if (gi < 0 || gi >= mem.globalPoints.length) {
      let best = -1;
      let bestScore = -1;
      for (let i = 0; i < mem.globalPoints.length; i++) {
        const p = mem.globalPoints[i];
        if (!p || p.done) continue;
        const d = dist(poseX, poseY, p.x, p.y);
        const home = dist(p.x, p.y, mem.baseX, mem.baseY);
        if (routeEnergy(d, home, 0, carried) > battery - 0.015) continue;
        if (routeSeconds(d, home, 0, carried) > timeLeft - 8) continue;
        const score = 1.4 / (42 + d + 0.55 * home + 8 * carried);
        if (score > bestScore) {
          bestScore = score;
          best = i;
        }
      }
      gi = best;
      mem.globalIndex = gi;
    }
    if (gi >= 0 && gi < mem.globalPoints.length) {
      const p = mem.globalPoints[gi];
      const d = dist(poseX, poseY, p.x, p.y);
      if (d <= 3.5) {
        p.done = true;
        mem.globalIndex = -1;
        return getTask();
      }
      return {
        kind: "global", index: gi,
        x: p.x, y: p.y, dist: d,
        home: dist(p.x, p.y, mem.baseX, mem.baseY),
        extra: 0, key: "g:" + gi
      };
    }
    return null;
  }

  let info = getTask();

  if (!info) {
    if (carried > 0) {
      mem.returning = true;
      return goHome();
    }
    if (!atBase && battery < homeNeed(homeDist, 0) + 0.04) {
      mem.returning = true;
      return goHome();
    }
    return emit(stopCommands(), false);
  }

  const planNeed = routeEnergy(info.dist, info.home, info.extra, carried);
  const planTime = routeSeconds(info.dist, info.home, info.extra, carried);
  if (planNeed > battery - 0.01 || planTime > timeLeft - 4) {
    if (atBase) return emit(stopCommands(), false);
    mem.returning = true;
    return goHome();
  }

  if (updateProgress(info.key, info.dist, info)) {
    return recoveryAction();
  }

  const goalBearing = deg(Math.atan2(info.y - poseY, info.x - poseX));
  const goalError = wrap(goalBearing - mem.theta);
  let maxV = 0.82;
  if (info.kind === "hint" && info.phase === "center") {
    maxV = info.dist > 35 ? 0.90 : (info.dist > 10 ? 0.78 : 0.58);
  } else if (info.kind === "hint") {
    maxV = info.dist > 9 ? 0.76 : (info.dist > 4 ? 0.56 : 0.36);
  } else if (info.kind === "ambient") {
    maxV = info.dist > 8 ? 0.72 : (info.dist > 3.5 ? 0.52 : 0.34);
  } else {
    maxV = info.dist > 12 ? 0.84 : (info.dist > 5 ? 0.62 : 0.38);
  }

  return emit(navCommands(goalError, maxV), false);
}

function act(obs, mem) {
  const o = obs || {};
  if (!mem || typeof mem !== "object") mem = {};

  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
  const num = (v, d) => {
    const n = Number(v);
    return Number.isFinite(n) ? n : d;
  };
  const wrap = (a) => {
    a = (a + 180) % 360;
    if (a < 0) a += 360;
    return a - 180;
  };
  const rad = (d) => d * Math.PI / 180;
  const deg = (r) => r * 180 / Math.PI;
  const dist = (x1, y1, x2, y2) => Math.hypot(x2 - x1, y2 - y1);

  const tNow = num(o.t, 0);
  let dt = 0.1;
  if (mem && Number.isFinite(mem.prevT)) {
    const d = tNow - mem.prevT;
    if (d > 0.02 && d <= 0.55) dt = d;
  }

  const rawH = wrap(num(o.heading, 0));

  if (!mem._init) {
    const m = o.mission && typeof o.mission === "object" ? o.mission : {};
    const sz = m.size;
    let width = 400, height = 400;
    if (typeof sz === "number") {
      width = height = sz;
    } else if (Array.isArray(sz)) {
      width = num(sz[0], 400);
      height = num(sz[1], width);
    } else if (sz && typeof sz === "object") {
      width = num(sz.width, num(sz.w, num(sz.x, 400)));
      height = num(sz.height, num(sz.h, num(sz.y, width)));
    }
    width = Math.max(50, width);
    height = Math.max(50, height);

    const b = m.base && typeof m.base === "object"
      ? m.base
      : { x: width * 0.5, y: height * 0.5 };

    mem.width = width;
    mem.height = height;
    mem.baseX = num(b.x, width * 0.5);
    mem.baseY = num(b.y, height * 0.5);
    mem.seconds = num(m.seconds, 1200);
    mem.capacity = Math.max(1, Math.floor(num(m.capacity, 5)));

    mem.hints = [];
    const hints = Array.isArray(m.hints) ? m.hints : [];
    for (let i = 0; i < hints.length; i++) {
      const h = hints[i] || {};
      mem.hints.push({
        x: clamp(num(h.x, mem.baseX), 3, width - 3),
        y: clamp(num(h.y, mem.baseY), 3, height - 3),
        value: Math.max(0.1, num(h.estimate, num(h.value, 1))),
        status: 0,
        phase: "center",
        step: 0,
        retry: 0,
        bestScience: 0,
        startScience: 0,
        bestX: num(h.x, mem.baseX),
        bestY: num(h.y, mem.baseY),
        angle: 0
      });
    }

    mem.globalPoints = [];
    const nx = Math.min(9, Math.max(4, Math.ceil((width - 40) / 55) + 1));
    const ny = Math.min(9, Math.max(4, Math.ceil((height - 40) / 55) + 1));
    for (let iy = 0; iy < ny; iy++) {
      const y = 20 + (height - 40) * iy / Math.max(1, ny - 1);
      for (let ix = 0; ix < nx; ix++) {
        const x = 20 + (width - 40) * ix / Math.max(1, nx - 1);
        mem.globalPoints.push({ x: x, y: y, done: false });
      }
    }

    const x0 = num(o.x, width * 0.5);
    const y0 = num(o.y, height * 0.5);
    const batt0 = clamp(num(o.battery, 1), 0, 1.5);

    mem.px = x0;
    mem.py = y0;
    mem.theta = rawH;
    mem.headingBias = 0;
    mem.prevRawH = rawH;
    mem.prevT = tNow;
    mem.lastGpsX = x0;
    mem.lastGpsY = y0;
    mem.gpsUnchanged = 0;
    mem.gpsTravelSinceChange = 0;
    mem.gpsFrozen = false;
    mem.gpsRecover = 0;
    mem.compassHold = 0;
    mem.cal = { active: false, x: x0, y: y0, sin: 0, cos: 0, n: 0 };

    mem.eRate = 0.00078;
    mem.energyUse = 0;
    mem.energyDist = 0;
    mem.prevBattery = batt0;

    mem.gains = [[2.7, 2.7], [2.7, 2.7]];
    mem.dead = [[0.21, 0.21], [0.21, 0.21]];
    mem.noResponse = [0, 0];
    mem.lastCmd = [0, 0];
    mem.lastTarget = [0, 0];

    mem.rFilt = [];
    mem.rRaw = [];
    mem.rSameTime = [];
    mem.rSameMotion = [];
    mem.rBad = [];
    for (let i = 0; i < 9; i++) {
      mem.rFilt[i] = 15;
      mem.rRaw[i] = 15;
      mem.rSameTime[i] = 0;
      mem.rSameMotion[i] = 0;
      mem.rBad[i] = false;
    }
    mem.allMaxTravel = 0;
    mem.rangeTrust = 1;

    mem.currentHint = -1;
    mem.globalIndex = -1;
    mem.ambient = null;
    mem.ambientLastX = -1e9;
    mem.ambientLastY = -1e9;

    mem.siteLock = null;
    mem.pendingMeta = null;
    mem.sampleActive = false;
    mem.sampleStart = 0;
    mem.stillTime = 0;
    mem.holdReady = false;
    mem.returning = false;

    mem.navKey = "";
    mem.navBest = 1e9;
    mem.navStuck = 0;
    mem.stuckCount = 0;
    mem.lastAim = 0;
    mem.avoidSign = 0;
    mem.recoverTimer = 0;
    mem.recoverSign = 1;
    mem.recoverMode = 0;
    mem.prevBumped = false;

    mem.samples = [];
    mem.prevCarried = Math.max(0, Math.floor(num(o.carried, 0)));
    mem.prevCarriedValue = num(o.carriedValue, 0);
    mem.prevDelivered = num(o.delivered, 0);
    mem.dockWaitStart = null;
    mem._init = true;
  }

  const width = num(mem.width, 400);
  const height = num(mem.height, 400);
  const rawX = num(o.x, num(mem.px, width * 0.5));
  const rawY = num(o.y, num(mem.py, height * 0.5));
  const wl = num(o.wheelLeft, 0);
  const wr = num(o.wheelRight, 0);
  const vWheel = (wl + wr) * 0.5;
  const moveDist = Math.abs(vWheel) * dt;
  const yawRad = ((wr - wl) / 0.6) * dt;
  const yawDeg = deg(yawRad);

  const battery = clamp(num(o.battery, mem.prevBattery), 0, 1.5);
  const solar = Math.max(0, num(o.solar, 0));
  const carried = Math.max(0, Math.floor(num(o.carried, 0)));
  const carriedValue = num(o.carriedValue, mem.prevCarriedValue);
  const delivered = num(o.delivered, mem.prevDelivered);
  const timeLeft = Math.max(0, num(o.timeLeft, mem.seconds - tNow));
  const drillProgress = Math.max(0, num(o.drilling, 0));
  const science = Math.max(0, num(o.science, 0));
  const siteObs = o.site && typeof o.site === "object" ? o.site : null;
  const beacon = o.beacon && typeof o.beacon === "object" ? o.beacon : null;

  const oldCarried = num(mem.prevCarried, carried);
  const oldCarriedValue = num(mem.prevCarriedValue, carriedValue);
  const oldDelivered = num(mem.prevDelivered, delivered);

  const rawRays = o.rays && typeof o.rays.length === "number" ? o.rays : null;
  let minRawRay = 15;
  for (let i = 0; i < 9; i++) {
    minRawRay = Math.min(minRawRay, clamp(rawRays ? num(rawRays[i], 15) : 15, 0, 15));
  }

  const prevTheta = num(mem.theta, rawH);
  const rawDeltaH = wrap(rawH - num(mem.prevRawH, rawH));
  const compassJump = Math.abs(rawDeltaH) > 65 && Math.abs(yawDeg) < 25;
  if (compassJump) mem.compassHold = 1.8;
  else mem.compassHold = Math.max(0, num(mem.compassHold, 0) - dt);

  let theta = wrap(prevTheta + yawDeg);
  if (!compassJump && mem.compassHold <= 0) {
    const correctedCompass = wrap(rawH - num(mem.headingBias, 0));
    const residual = wrap(correctedCompass - theta);
    if (Math.abs(residual) < 75) {
      theta = wrap(theta + clamp(residual * 0.16, -4, 4));
    }
  }
  mem.theta = theta;

  const gpsDelta = dist(rawX, rawY, num(mem.lastGpsX, rawX), num(mem.lastGpsY, rawY));
  const gpsJump = gpsDelta > 8.5 && dt <= 0.55;
  if (gpsDelta < 0.025 && moveDist > 0.02) {
    mem.gpsUnchanged = num(mem.gpsUnchanged, 0) + dt;
    mem.gpsTravelSinceChange = num(mem.gpsTravelSinceChange, 0) + moveDist;
  } else if (gpsDelta > 0.08) {
    mem.gpsUnchanged = 0;
    mem.gpsTravelSinceChange = 0;
  }

  const wasGpsFrozen = !!mem.gpsFrozen;
  mem.gpsFrozen = mem.gpsUnchanged > 3.0 && mem.gpsTravelSinceChange > 2.0;
  if (wasGpsFrozen && !mem.gpsFrozen) mem.gpsRecover = 1.1;
  else mem.gpsRecover = Math.max(0, num(mem.gpsRecover, 0) - dt);

  const midTheta = rad(wrap((prevTheta + theta) * 0.5));
  let predX = num(mem.px, rawX) + vWheel * dt * Math.cos(midTheta);
  let predY = num(mem.py, rawY) + vWheel * dt * Math.sin(midTheta);
  if (!mem.gpsFrozen && !gpsJump) {
    const dx = rawX - predX;
    const dy = rawY - predY;
    const residual = Math.hypot(dx, dy);
    if (residual < 18) {
      let alpha = Math.abs(vWheel) > 0.25 ? 0.11 : 0.035;
      if (mem.gpsRecover > 0) alpha = 0.22;
      const limit = mem.gpsRecover > 0 ? 3.0 : (Math.abs(vWheel) > 0.25 ? 1.5 : 1.0);
      const scale = residual > limit ? limit / residual : 1;
      predX += dx * scale * alpha;
      predY += dy * scale * alpha;
    }
  }
  mem.px = predX;
  mem.py = predY;
  mem.lastGpsX = rawX;
  mem.lastGpsY = rawY;
  mem.prevRawH = rawH;

  const straightForward = vWheel > 0.34 &&
    Math.abs(wr - wl) < 0.24 &&
    !mem.gpsFrozen && !gpsJump && !compassJump;
  if (!mem.cal || typeof mem.cal !== "object") {
    mem.cal = { active: false, x: rawX, y: rawY, sin: 0, cos: 0, n: 0 };
  }
  if (straightForward) {
    if (!mem.cal.active) {
      mem.cal.active = true;
      mem.cal.x = rawX;
      mem.cal.y = rawY;
      mem.cal.sin = 0;
      mem.cal.cos = 0;
      mem.cal.n = 0;
    }
    mem.cal.sin += Math.sin(rad(rawH));
    mem.cal.cos += Math.cos(rad(rawH));
    mem.cal.n += 1;
    if (dist(rawX, rawY, mem.cal.x, mem.cal.y) >= 9 && mem.cal.n >= 8) {
      const course = deg(Math.atan2(rawY - mem.cal.y, rawX - mem.cal.x));
      const meanRaw = deg(Math.atan2(mem.cal.sin, mem.cal.cos));
      const estimate = wrap(meanRaw - course);
      const err = wrap(estimate - num(mem.headingBias, 0));
      if (Math.abs(err) < 60) {
        mem.headingBias = wrap(num(mem.headingBias, 0) + clamp(err * 0.16, -3, 3));
      }
      mem.cal.x = rawX;
      mem.cal.y = rawY;
      mem.cal.sin = 0;
      mem.cal.cos = 0;
      mem.cal.n = 0;
    }
  } else if (mem.cal) {
    mem.cal.active = false;
    mem.cal.sin = 0;
    mem.cal.cos = 0;
    mem.cal.n = 0;
  }

  if (!Array.isArray(mem.gains) || mem.gains.length < 2) {
    mem.gains = [[2.7, 2.7], [2.7, 2.7]];
  }
  if (!Array.isArray(mem.dead) || mem.dead.length < 2) {
    mem.dead = [[0.21, 0.21], [0.21, 0.21]];
  }
  if (!Array.isArray(mem.lastCmd) || mem.lastCmd.length < 2) mem.lastCmd = [0, 0];
  if (!Array.isArray(mem.lastTarget) || mem.lastTarget.length < 2) mem.lastTarget = [0, 0];
  if (!Array.isArray(mem.noResponse) || mem.noResponse.length < 2) mem.noResponse = [0, 0];

  for (let s = 0; s < 2; s++) {
    if (!Array.isArray(mem.gains[s])) mem.gains[s] = [2.7, 2.7];
    if (!Array.isArray(mem.dead[s])) mem.dead[s] = [0.21, 0.21];
    const cmd = num(mem.lastCmd[s], 0);
    const target = num(mem.lastTarget[s], 0);
    const actual = s === 0 ? wl : wr;

    if (Math.abs(cmd) > 0.24 && Math.abs(actual) > 0.12 && actual * cmd > 0) {
      const direction = cmd < 0 ? 1 : 0;
      const ratio = Math.abs(actual / cmd);
      if (ratio > 0.35 && ratio < 5.8) {
        const old = num(mem.gains[s][direction], 2.7);
        const a = ratio < old * 0.70 ? 0.045 : 0.012;
        mem.gains[s][direction] = clamp(old + (ratio - old) * a, 0.65, 5.5);
      }
    }

    const direction = target < 0 ? 1 : 0;
    if (Math.abs(target) > 0.30 && Math.abs(cmd) > 0.19 &&
        Math.abs(actual) < 0.075 && !o.bumped && minRawRay > 1.35) {
      mem.noResponse[s] = num(mem.noResponse[s], 0) + dt;
      if (mem.noResponse[s] > 0.85) {
        mem.dead[s][direction] = clamp(num(mem.dead[s][direction], 0.21) + 0.012, 0.18, 0.40);
      }
    } else {
      mem.noResponse[s] = 0;
      if (Math.abs(actual) > 0.22) {
        mem.dead[s][direction] = Math.max(0.18, num(mem.dead[s][direction], 0.21) - 0.001);
      }
    }
  }

  const previousBattery = num(mem.prevBattery, battery);
  if (!o.docked && drillProgress < 0.05 && moveDist > 0.02) {
    const drop = previousBattery - battery;
    if (drop > 0) {
      mem.energyUse = num(mem.energyUse, 0) + drop + Math.min(0.002, solar * dt * 0.15);
    }
    mem.energyDist = num(mem.energyDist, 0) + moveDist;
    if (mem.energyDist >= 12) {
      if (mem.energyUse > 0.002) {
        const measured = clamp(mem.energyUse / Math.max(6, mem.energyDist), 0.00025, 0.012);
        const old = num(mem.eRate, 0.00078);
        const a = measured > old ? 0.28 : 0.055;
        mem.eRate = clamp(old + (measured - old) * a, 0.00025, 0.012);
      }
      mem.energyUse = 0;
      mem.energyDist = 0;
    }
  }
  mem.prevBattery = battery;

  if (!Array.isArray(mem.rFilt) || mem.rFilt.length !== 9) {
    mem.rFilt = [];
    mem.rRaw = [];
    mem.rSameTime = [];
    mem.rSameMotion = [];
    mem.rBad = [];
    for (let i = 0; i < 9; i++) {
      mem.rFilt[i] = 15;
      mem.rRaw[i] = 15;
      mem.rSameTime[i] = 0;
      mem.rSameMotion[i] = 0;
      mem.rBad[i] = false;
    }
  }

  let allMax = true;
  let anyNear = false;
  for (let i = 0; i < 9; i++) {
    const r = clamp(rawRays ? num(rawRays[i], 15) : 15, 0, 15);
    if (r < 14.8) allMax = false;
    if (r < 14.4) anyNear = true;

    const last = num(mem.rRaw[i], r);
    const diff = Math.abs(r - last);
    if (diff < 0.03) {
      if (moveDist > 0.02 || Math.abs(yawRad) > 0.015) {
        mem.rSameTime[i] = num(mem.rSameTime[i], 0) + dt;
        mem.rSameMotion[i] = num(mem.rSameMotion[i], 0) +
          moveDist + Math.abs(yawRad) * 0.9;
      }
    } else if (diff > 0.30) {
      mem.rSameTime[i] = 0;
      mem.rSameMotion[i] = 0;
      mem.rBad[i] = false;
    }
    if (mem.rSameTime[i] > 10 && mem.rSameMotion[i] > 4.0 && r < 14.4) {
      mem.rBad[i] = true;
    }

    const effective = mem.rBad[i] ? Math.max(r, 5.5) : r;
    let f = num(mem.rFilt[i], effective);
    const a = effective < f ? 0.62 : 0.30;
    f += (effective - f) * a;
    mem.rFilt[i] = clamp(f, 0, 15);
    mem.rRaw[i] = r;
  }

  if (allMax && moveDist > 0.02) {
    mem.allMaxTravel = num(mem.allMaxTravel, 0) + moveDist;
  } else if (anyNear) {
    mem.allMaxTravel = Math.max(0, num(mem.allMaxTravel, 0) - moveDist * 1.3);
  }
  mem.rangeTrust = mem.allMaxTravel > 20 ? 0.82 : 1;

  if (carried > oldCarried) {
    const meta = mem.pendingMeta || mem.siteLock || { x: mem.px, y: mem.py, value: 1 };
    const mx = num(meta.x, mem.px);
    const my = num(meta.y, mem.py);
    let value = Math.max(0.1, num(meta.value, 1));
    const valueGain = carriedValue - oldCarriedValue;
    if (valueGain > 0.01) value = valueGain / Math.max(1, carried - oldCarried);
    mem.samples.push({ x: mx, y: my, value: value });

    let associated = -1;
    const current = Math.floor(num(mem.currentHint, -1));
    if (current >= 0 && current < mem.hints.length &&
        mem.hints[current].status < 2 &&
        dist(mx, my, mem.hints[current].x, mem.hints[current].y) < 45) {
      associated = current;
    } else {
      let bestD = 32;
      for (let i = 0; i < mem.hints.length; i++) {
        const h = mem.hints[i];
        if (!h || h.status >= 2) continue;
        const d = dist(mx, my, h.x, h.y);
        if (d < bestD) {
          bestD = d;
          associated = i;
        }
      }
    }
    if (associated >= 0) {
      mem.hints[associated].status = 2;
      if (associated === current) mem.currentHint = -1;
    }

    for (let i = 0; i < mem.globalPoints.length; i++) {
      const p = mem.globalPoints[i];
      if (p && dist(mx, my, p.x, p.y) < 10) p.done = true;
    }
    if (mem.ambient && dist(mx, my, mem.ambient.x, mem.ambient.y) < 35) {
      mem.ambient = null;
    }

    mem.sampleActive = false;
    mem.pendingMeta = null;
    mem.siteLock = null;
    mem.holdReady = false;
    mem.stillTime = 0;
    mem.navKey = "";
  } else if (carried < oldCarried || delivered > oldDelivered) {
    mem.sampleActive = false;
    mem.pendingMeta = null;
    mem.siteLock = null;
    mem.holdReady = false;
    mem.stillTime = 0;
  }

  if (siteObs && carried < num(mem.capacity, 5)) {
    const sd = Math.max(0, num(siteObs.distance, 99));
    const sb = num(siteObs.bearing, 0);
    const a = rad(mem.theta + sb);
    const sx = mem.px + sd * Math.cos(a);
    const sy = mem.py + sd * Math.sin(a);
    const sv = Math.max(0.1, num(siteObs.value, 1));
    if (!mem.siteLock) {
      mem.siteLock = { x: sx, y: sy, value: sv, lastSeen: tNow };
    } else {
      const gap = dist(mem.siteLock.x, mem.siteLock.y, sx, sy);
      if (gap > 12) {
        mem.siteLock.x = sx;
        mem.siteLock.y = sy;
      } else {
        mem.siteLock.x = mem.siteLock.x * 0.68 + sx * 0.32;
        mem.siteLock.y = mem.siteLock.y * 0.68 + sy * 0.32;
      }
      mem.siteLock.value = sv;
      mem.siteLock.lastSeen = tNow;
    }
  }

  if (!mem.sampleActive && drillProgress > 0.05 && mem.siteLock) {
    mem.sampleActive = true;
    mem.sampleStart = tNow - drillProgress;
    if (!mem.holdReady) {
      mem.holdX = mem.px;
      mem.holdY = mem.py;
      mem.holdHeading = mem.theta;
      mem.holdReady = true;
    }
    mem.pendingMeta = {
      x: mem.siteLock.x,
      y: mem.siteLock.y,
      value: mem.siteLock.value
    };
  }

  const poseX = mem.px;
  const poseY = mem.py;
  const baseDist = dist(poseX, poseY, mem.baseX, mem.baseY);
  const beaconDist = beacon ? Math.max(0, num(beacon.distance, 99)) : 99;
  const beaconUsable = !!beacon && beaconDist <= 20.5;
  const maxWheelSpeed = Math.max(Math.abs(wl), Math.abs(wr));
  const atBase = !!o.docked ||
    (beacon && beaconDist <= 2.9) ||
    (baseDist <= 2.35 && maxWheelSpeed < 0.24);
  const homeDist = beaconUsable ? beaconDist : baseDist;

  function homeNeed(d, load) {
    const l = Math.max(0, load);
    return 0.12 +
      num(mem.eRate, 0.00078) * (Math.max(0, d) * 1.65 + 25) *
        (1 + 0.16 * l) +
      0.02 * l;
  }

  function routeEnergy(outDist, homeDistPlan, extra, loadAfter) {
    const l = Math.max(0, loadAfter);
    const metres = Math.max(0, outDist) * 1.35 +
      Math.max(0, homeDistPlan) * 1.50 +
      Math.max(0, extra) * 1.20 + 26;
    return 0.12 +
      num(mem.eRate, 0.00078) * metres * (1 + 0.18 * l) +
      0.018 * l;
  }

  function routeSeconds(outDist, homeDistPlan, extra, loadAfter) {
    const l = Math.max(0, loadAfter);
    return (Math.max(0, outDist) + Math.max(0, homeDistPlan) +
      Math.max(0, extra)) * 1.52 / 0.78 + 52 + 6 * l;
  }

  function homeSeconds(d, load) {
    return Math.max(0, d) * 1.55 / 0.78 + 44 + 6 * Math.max(0, load);
  }

  const homeEnergyNow = homeNeed(homeDist, carried);
  const homeTimeNow = homeSeconds(homeDist, carried);

  if (delivered > oldDelivered && carried === 0 && atBase) {
    mem.returning = false;
  }
  if (mem.returning && atBase && carried === 0) {
    mem.returning = false;
    mem.sampleActive = false;
    mem.holdReady = false;
    mem.stillTime = 0;
  }
  if (!mem.returning && !atBase && !mem.sampleActive) {
    if (carried >= mem.capacity ||
        battery < homeEnergyNow + 0.075 ||
        timeLeft < homeTimeNow + 32 ||
        battery < 0.025) {
      mem.returning = true;
    }
  }

  function gainFor(side, target) {
    const direction = target < -0.02 ? 1 : 0;
    return clamp(num(mem.gains[side][direction], 2.7), 0.65, 5.5);
  }

  function motorPower(target, actual, side, hold) {
    const direction = target < -0.02 ? 1 : 0;
    const gain = gainFor(side, target);
    const kp = hold ? 0.34 : 0.29;
    let u;

    if (Math.abs(target) < 0.025) {
      u = -actual * (hold ? 0.42 : 0.48);
      if (!hold && Math.abs(actual) > 0.26 && Math.abs(u) < 0.20) {
        u = -Math.sign(actual) * num(mem.dead[side][direction], 0.21);
      }
    } else {
      u = target / gain + kp * (target - actual);
      if (!hold && Math.abs(target) > 0.12 &&
          Math.abs(u) < num(mem.dead[side][direction], 0.21)) {
        const overspeed = target * actual > 0 &&
          Math.abs(actual) > Math.abs(target) + 0.07;
        if (!overspeed) {
          u = Math.sign(target) * num(mem.dead[side][direction], 0.21);
        }
      }
    }
    return clamp(u, -1, 1);
  }

  function wheelCommands(v, omega, hold) {
    const lt = clamp(v - 0.3 * omega, -1.45, 1.45);
    const rt = clamp(v + 0.3 * omega, -1.45, 1.45);
    return {
      left: motorPower(lt, wl, 0, !!hold),
      right: motorPower(rt, wr, 1, !!hold),
      tl: lt,
      tr: rt
    };
  }

  function stopCommands() {
    return wheelCommands(0, 0, true);
  }

  function emit(c, drill) {
    const left = clamp(num(c && c.left, 0), -1, 1);
    const right = clamp(num(c && c.right, 0), -1, 1);
    mem.lastCmd = [left, right];
    mem.lastTarget = [num(c && c.tl, 0), num(c && c.tr, 0)];
    mem.prevT = tNow;
    mem.prevCarried = carried;
    mem.prevCarriedValue = carriedValue;
    mem.prevDelivered = delivered;
    return { left: left, right: right, drill: !!drill };
  }

  function rayAt(angle) {
    const a = clamp(angle, -80, 80);
    const q = (a + 80) / 20;
    const i = Math.floor(q);
    const f = q - i;
    if (i >= 8) return num(mem.rFilt[8], 15);
    return num(mem.rFilt[i], 15) * (1 - f) + num(mem.rFilt[i + 1], 15) * f;
  }

  function clearanceAt(angle) {
    const center = rayAt(angle);
    const side = Math.min(rayAt(angle - 20), rayAt(angle + 20));
    return Math.min(center, center * 0.76 + side * 0.24);
  }

  function edgeDistance(angle) {
    const a = rad(wrap(mem.theta + angle));
    const dx = Math.cos(a);
    const dy = Math.sin(a);
    const margin = 5;
    let d = 1e6;
    if (dx > 0.001) d = Math.min(d, (width - margin - poseX) / dx);
    if (dx < -0.001) d = Math.min(d, (margin - poseX) / dx);
    if (dy > 0.001) d = Math.min(d, (height - margin - poseY) / dy);
    if (dy < -0.001) d = Math.min(d, (margin - poseY) / dy);
    return Math.max(0, d);
  }

  function navCommands(goalError, maxV) {
    const goal = wrap(num(goalError, 0));
    const vmax = clamp(num(maxV, 0.75), 0, 0.95);

    if (Math.abs(goal) > 78) {
      const s = Math.sign(goal) || 1;
      mem.lastAim = s * 90;
      return wheelCommands(0, s * 1.45, false);
    }

    const clippedGoal = clamp(goal, -80, 80);
    const candidates = [-80, -60, -40, -20, 0, 20, 40, 60, 80, clippedGoal];
    const safe = 2.8 + vmax * 1.05;
    const front = clearanceAt(0);
    let best = clippedGoal;
    let bestCost = 1e9;
    let bestClear = 15;

    for (let i = 0; i < candidates.length; i++) {
      const a = candidates[i];
      const clear = clearanceAt(a);
      let cost = Math.abs(wrap(a - clippedGoal)) * 0.027;
      const hazard = Math.max(0, safe - clear);
      cost += hazard * hazard * 1.75;
      if (clear < 1.25) cost += 11;
      if (clear < 0.70) cost += 22;

      const edge = edgeDistance(a);
      if (edge < 2.5) cost += 17;
      else if (edge < 8) cost += (8 - edge) * 0.72;

      if (front < safe && Math.abs(a) > 10 && mem.avoidSign &&
          Math.sign(a) !== Math.sign(mem.avoidSign)) {
        cost += 0.20;
      }
      if (front < safe) {
        cost += Math.abs(a - num(mem.lastAim, a)) * 0.004;
      }

      if (cost < bestCost) {
        bestCost = cost;
        best = a;
        bestClear = clear;
      }
    }

    if (front > safe + 1.4) mem.avoidSign = 0;
    else if (Math.abs(best) > 10) mem.avoidSign = Math.sign(best);
    mem.lastAim = best;

    let v = vmax;
    const scale = clamp((bestClear - 0.85) / Math.max(1.1, safe - 0.85), 0.14, 1);
    v *= scale;
    if (bestClear < 1.25) v = Math.min(v, 0.18);
    if (front < 1.05 && Math.abs(best) < 18) v = Math.min(v, 0.13);
    if (Math.abs(best) > 60) v = Math.min(v, 0.38);
    else if (Math.abs(best) > 42) v = Math.min(v, 0.58);
    else if (Math.abs(best) > 26) v = Math.min(v, 0.72);
    if (mem.rangeTrust < 0.85) v = Math.min(v, 0.78);

    if (Math.abs(best) > 72) {
      return wheelCommands(0, Math.sign(best) * 1.35, false);
    }
    const omega = clamp(1.65 * rad(best), -1.4, 1.4);
    return wheelCommands(v, omega, false);
  }

  function holdCommands() {
    if (!mem.holdReady) {
      mem.holdX = poseX;
      mem.holdY = poseY;
      mem.holdHeading = mem.theta;
      mem.holdReady = true;
    }

    const a = rad(mem.theta);
    const dx = num(mem.holdX, poseX) - poseX;
    const dy = num(mem.holdY, poseY) - poseY;
    const along = dx * Math.cos(a) + dy * Math.sin(a);
    const cross = -dx * Math.sin(a) + dy * Math.cos(a);
    const avg = (wl + wr) * 0.5;

    let positionCorrection = 0;
    if (Math.abs(along) > 0.32) positionCorrection = 0.55 * along;
    const vDes = clamp(positionCorrection - 0.72 * avg, -0.12, 0.12);
    const headingErr = wrap(num(mem.holdHeading, mem.theta) - mem.theta);
    const omega = clamp(0.85 * rad(headingErr) +
      clamp(cross * 0.035, -0.055, 0.055), -0.18, 0.18);

    const c = wheelCommands(vDes, omega, true);
    const pitchFeed = clamp(num(o.pitch, 0) * 0.008, -0.12, 0.12);
    c.left = clamp(c.left + pitchFeed, -1, 1);
    c.right = clamp(c.right + pitchFeed, -1, 1);
    return c;
  }

  function openSide() {
    let leftOpen = 0, rightOpen = 0;
    for (let i = 5; i < 9; i++) leftOpen += num(mem.rFilt[i], 15);
    for (let i = 0; i < 4; i++) rightOpen += num(mem.rFilt[i], 15);
    if (Math.abs(leftOpen - rightOpen) < 0.5) {
      return mem.avoidSign ? -mem.avoidSign : 1;
    }
    return leftOpen >= rightOpen ? 1 : -1;
  }

  function recoveryAction() {
    const rem = Math.max(0, num(mem.recoverTimer, 0));
    const s = num(mem.recoverSign, 1);
    let c;
    if (rem > 0.68) {
      c = wheelCommands(-0.32, s * 0.76, false);
    } else {
      c = wheelCommands(0, s * 1.20, false);
    }
    mem.recoverTimer = Math.max(0, rem - dt);
    if (mem.recoverTimer <= 0) mem.recoverMode = 0;
    return emit(c, false);
  }

  function skipTarget(info) {
    if (!info) return;
    if (info.kind === "hint" && info.index >= 0 && info.index < mem.hints.length) {
      const h = mem.hints[info.index];
      if (!h) return;
      if (info.phase === "center") {
        h.phase = "ring";
        h.step = 0;
        h.startScience = science;
        h.bestScience = science;
        h.bestX = poseX;
        h.bestY = poseY;
      } else {
        h.step = Math.min(info.phase === "refine" ? 8 : 16,
          Math.max(0, Math.floor(num(h.step, 0))) + 1);
      }
    } else if (info.kind === "ambient" && mem.ambient) {
      mem.ambient.step = Math.min(mem.ambient.count,
        Math.max(0, Math.floor(num(mem.ambient.step, 0))) + 1);
    } else if (info.kind === "global" && info.index >= 0 &&
        info.index < mem.globalPoints.length) {
      mem.globalPoints[info.index].done = true;
      mem.globalIndex = -1;
    } else if (info.kind === "site") {
      mem.siteLock = null;
      mem.holdReady = false;
    }
  }

  function updateProgress(key, d, info) {
    if (mem.navKey !== key) {
      mem.navKey = key;
      mem.navBest = d;
      mem.navStuck = 0;
      mem.stuckCount = 0;
      return false;
    }
    if (d < num(mem.navBest, d) - 0.65) {
      mem.navBest = d;
      mem.navStuck = 0;
      mem.stuckCount = 0;
      return false;
    }

    mem.navStuck = num(mem.navStuck, 0) + dt;
    if (mem.navStuck > 23) {
      mem.navStuck = 0;
      mem.navBest = d;
      mem.stuckCount = num(mem.stuckCount, 0) + 1;
      mem.recoverSign = mem.avoidSign ? -mem.avoidSign : openSide();
      mem.avoidSign = mem.recoverSign;
      mem.recoverTimer = 1.45;
      mem.recoverMode = 2;
      if (mem.stuckCount >= 3) {
        skipTarget(info);
        mem.navKey = "";
        mem.stuckCount = 0;
      }
      return true;
    }
    return false;
  }

  function ringPoint(cx, cy, step, count, radius, offset) {
    const a = num(offset, 0) + 2 * Math.PI * step / count;
    return {
      x: clamp(cx + radius * Math.cos(a), 3, width - 3),
      y: clamp(cy + radius * Math.sin(a), 3, height - 3)
    };
  }

  function hintRoute(h) {
    const phase = h.phase || "center";
    if (phase === "center") {
      const r = 15.5;
      return {
        x: h.x,
        y: h.y,
        dist: dist(poseX, poseY, h.x, h.y),
        home: dist(h.x, h.y, mem.baseX, mem.baseY) + 20,
        extra: r + 2 * Math.PI * r,
        phase: "center"
      };
    }

    const count = phase === "refine" ? 8 : 16;
    const radius = phase === "refine" ? 8.2 : 15.5;
    const step = Math.max(0, Math.floor(num(h.step, 0)));
    const p = ringPoint(h.x, h.y, step, count, radius, num(h.angle, 0));
    const arc = 2 * Math.PI * radius / count;
    return {
      x: p.x,
      y: p.y,
      dist: dist(poseX, poseY, p.x, p.y),
      home: dist(h.x, h.y, mem.baseX, mem.baseY) + 20,
      extra: Math.max(0, count - step - 1) * arc,
      phase: phase
    };
  }

  function routeFeasible(plan, loadAfter) {
    const need = routeEnergy(plan.dist, plan.home, plan.extra, loadAfter);
    const seconds = routeSeconds(plan.dist, plan.home, plan.extra, loadAfter);
    return need <= battery - 0.035 && seconds <= timeLeft - 8;
  }

  function chooseHint() {
    let best = -1;
    let bestScore = -1;
    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (!h || h.status >= 2) continue;
      const plan = hintRoute(h);
      if (!routeFeasible(plan, carried + 1)) continue;

      let score = Math.pow(Math.max(0.1, h.value), 1.13) /
        (58 + plan.dist + 0.63 * plan.home + 0.48 * plan.extra + 9 * carried);
      if (h.status === 1) score *= 1.06;
      if (i === Math.floor(num(mem.currentHint, -1))) score *= 1.12;
      if (score > bestScore) {
        bestScore = score;
        best = i;
      }
    }
    return best;
  }

  function finishHint(h, index) {
    if (h.phase !== "refine" && !h.retry &&
        num(h.bestScience, 0) > num(h.startScience, 0) + 0.28 &&
        num(h.bestScience, 0) > 0.75 &&
        dist(num(h.bestX, h.x), num(h.bestY, h.y), h.x, h.y) > 3.5) {
      h.x = clamp(num(h.bestX, h.x), 3, width - 3);
      h.y = clamp(num(h.bestY, h.y), 3, height - 3);
      h.phase = "refine";
      h.step = 0;
      h.retry = 1;
      h.startScience = num(h.bestScience, science);
      h.bestScience = num(h.startScience, science);
      h.bestX = poseX;
      h.bestY = poseY;
      return;
    }
    h.status = 2;
    if (Math.floor(num(mem.currentHint, -1)) === index) mem.currentHint = -1;
  }

  function updateHintScience(h) {
    if (science > num(h.bestScience, 0)) {
      h.bestScience = science;
      h.bestX = poseX;
      h.bestY = poseY;
    }
  }

  function getTask() {
    for (let tries = 0; tries < 48; tries++) {
      let hi = Math.floor(num(mem.currentHint, -1));
      if (hi < 0 || hi >= mem.hints.length ||
          !mem.hints[hi] || mem.hints[hi].status >= 2 ||
          !routeFeasible(hintRoute(mem.hints[hi]), carried + 1)) {
        hi = chooseHint();
        mem.currentHint = hi;
        if (hi >= 0) mem.hints[hi].status = 1;
      }

      if (hi >= 0 && hi < mem.hints.length) {
        const h = mem.hints[hi];
        if (!h.phase) h.phase = "center";
        updateHintScience(h);

        if (h.phase === "center") {
          const d = dist(poseX, poseY, h.x, h.y);
          if (d <= 4.2) {
            h.phase = "ring";
            h.step = 0;
            h.startScience = science;
            h.bestScience = science;
            h.bestX = poseX;
            h.bestY = poseY;
            continue;
          }
          return {
            kind: "hint",
            index: hi,
            phase: "center",
            x: h.x,
            y: h.y,
            dist: d,
            home: dist(h.x, h.y, mem.baseX, mem.baseY) + 20,
            extra: 15.5 + 2 * Math.PI * 15.5,
            key: "hc:" + hi,
            error: wrap(deg(Math.atan2(h.y - poseY, h.x - poseX)) - mem.theta)
          };
        }

        const count = h.phase === "refine" ? 8 : 16;
        const radius = h.phase === "refine" ? 8.2 : 15.5;
        let step = Math.max(0, Math.floor(num(h.step, 0)));
        while (step < count) {
          const p = ringPoint(h.x, h.y, step, count, radius, num(h.angle, 0));
          const d = dist(poseX, poseY, p.x, p.y);
          if (d <= 3.0) {
            step++;
            h.step = step;
            continue;
          }
          const arc = 2 * Math.PI * radius / count;
          return {
            kind: "hint",
            index: hi,
            phase: h.phase,
            step: step,
            x: p.x,
            y: p.y,
            dist: d,
            home: dist(h.x, h.y, mem.baseX, mem.baseY) + 20,
            extra: Math.max(0, count - step - 1) * arc,
            key: "hr:" + hi + ":" + h.phase + ":" + step,
            error: wrap(deg(Math.atan2(p.y - poseY, p.x - poseX)) - mem.theta)
          };
        }

        finishHint(h, hi);
        continue;
      }

      if (!mem.ambient && science > 1.0 &&
          dist(poseX, poseY, num(mem.ambientLastX, -1e9),
            num(mem.ambientLastY, -1e9)) > 27) {
        mem.ambient = {
          x: poseX,
          y: poseY,
          step: 0,
          count: 12,
          radius: 14,
          retry: 0,
          startScience: science,
          bestScience: science,
          bestX: poseX,
          bestY: poseY
        };
      }

      if (mem.ambient) {
        const a = mem.ambient;
        if (science > num(a.bestScience, 0)) {
          a.bestScience = science;
          a.bestX = poseX;
          a.bestY = poseY;
        }

        const count = Math.max(1, Math.floor(num(a.count, 12)));
        const step = Math.max(0, Math.floor(num(a.step, 0)));
        if (step >= count) {
          if (!a.retry &&
              num(a.bestScience, 0) > num(a.startScience, 0) + 0.28 &&
              dist(a.bestX, a.bestY, a.x, a.y) > 3.5) {
            a.x = clamp(num(a.bestX, a.x), 3, width - 3);
            a.y = clamp(num(a.bestY, a.y), 3, height - 3);
            a.step = 0;
            a.count = 8;
            a.radius = 8;
            a.retry = 1;
            a.startScience = num(a.bestScience, science);
            a.bestScience = num(a.startScience, science);
            a.bestX = poseX;
            a.bestY = poseY;
            continue;
          }
          mem.ambientLastX = a.x;
          mem.ambientLastY = a.y;
          mem.ambient = null;
          continue;
        }

        const radius = Math.max(5, num(a.radius, 14));
        const p = ringPoint(a.x, a.y, step, count, radius, 0);
        const d = dist(poseX, poseY, p.x, p.y);
        if (d <= 3.0) {
          a.step++;
          continue;
        }
        const arc = 2 * Math.PI * radius / count;
        const extra = Math.max(0, count - step - 1) * arc;
        const plan = {
          dist: d,
          home: dist(a.x, a.y, mem.baseX, mem.baseY) + 15,
          extra: extra
        };
        if (routeFeasible(plan, carried + 1)) {
          return {
            kind: "ambient",
            index: step,
            x: p.x,
            y: p.y,
            dist: d,
            home: plan.home,
            extra: extra,
            key: "a:" + step,
            error: wrap(deg(Math.atan2(p.y - poseY, p.x - poseX)) - mem.theta)
          };
        }
        mem.ambientLastX = a.x;
        mem.ambientLastY = a.y;
        mem.ambient = null;
        continue;
      }

      let gi = Math.floor(num(mem.globalIndex, -1));
      if (gi >= 0 && gi < mem.globalPoints.length &&
          mem.globalPoints[gi] && mem.globalPoints[gi].done) {
        gi = -1;
        mem.globalIndex = -1;
      }

      function chooseGlobal() {
        let best = -1;
        let scoreBest = -1;
        for (let i = 0; i < mem.globalPoints.length; i++) {
          const p = mem.globalPoints[i];
          if (!p || p.done) continue;
          const d = dist(poseX, poseY, p.x, p.y);
          const home = dist(p.x, p.y, mem.baseX, mem.baseY) + 18;
          const plan = { dist: d, home: home, extra: 0 };
          if (!routeFeasible(plan, carried + 1)) continue;
          const score = 1 / (42 + d + 0.58 * home + 8 * carried);
          if (score > scoreBest) {
            scoreBest = score;
            best = i;
          }
        }
        return best;
      }

      if (gi < 0 || gi >= mem.globalPoints.length) {
        gi = chooseGlobal();
        mem.globalIndex = gi;
      }
      if (gi >= 0 && gi < mem.globalPoints.length) {
        const p = mem.globalPoints[gi];
        const d = dist(poseX, poseY, p.x, p.y);
        if (d <= 3.4) {
          p.done = true;
          mem.globalIndex = -1;
          continue;
        }
        return {
          kind: "global",
          index: gi,
          x: p.x,
          y: p.y,
          dist: d,
          home: dist(p.x, p.y, mem.baseX, mem.baseY) + 18,
          extra: 0,
          key: "g:" + gi,
          error: wrap(deg(Math.atan2(p.y - poseY, p.x - poseX)) - mem.theta)
        };
      }
      return null;
    }
    return null;
  }

  function goHome() {
    if (atBase || homeDist <= 2.4) return emit(stopCommands(), false);

    let err;
    if (beaconUsable) {
      err = num(beacon.bearing, 0);
    } else {
      err = wrap(deg(Math.atan2(mem.baseY - poseY, mem.baseX - poseX)) - mem.theta);
    }

    if (updateProgress("base", homeDist, { kind: "base" })) {
      return recoveryAction();
    }

    let speed = homeDist > 25 ? 0.90 : (homeDist > 8 ? 0.68 : 0.40);
    if (timeLeft < homeTimeNow + 15) speed = 0.95;
    return emit(navCommands(err, speed), false);
  }

  if (o.bumped && !mem.prevBumped && !mem.sampleActive && !atBase) {
    mem.recoverSign = openSide();
    mem.recoverTimer = 1.35;
    mem.recoverMode = 1;
    mem.avoidSign = mem.recoverSign;
  }
  mem.prevBumped = !!o.bumped;

  if (atBase && carried > 0) {
    return emit(stopCommands(), false);
  }

  if (mem.recoverTimer > 0 && !mem.sampleActive && !atBase) {
    return recoveryAction();
  }

  if (mem.sampleActive) {
    let sd = 99;
    if (siteObs) {
      sd = Math.max(0, num(siteObs.distance, 99));
    } else if (mem.siteLock) {
      sd = dist(poseX, poseY, mem.siteLock.x, mem.siteLock.y);
    }

    if (tNow - num(mem.sampleStart, tNow) > 19 &&
        drillProgress < 5.8 && carried === oldCarried) {
      mem.sampleActive = false;
      mem.pendingMeta = null;
      mem.holdReady = false;
      mem.stillTime = 0;
    } else if ((siteObs && sd > 1.75 && drillProgress < 0.2) ||
               (!siteObs && drillProgress < 0.2 &&
                tNow - num(mem.sampleStart, tNow) > 2.2)) {
      mem.sampleActive = false;
      mem.pendingMeta = null;
      mem.holdReady = false;
      mem.stillTime = 0;
    } else {
      if (!mem.holdReady) {
        mem.holdX = poseX;
        mem.holdY = poseY;
        mem.holdHeading = mem.theta;
        mem.holdReady = true;
      }
      const c = holdCommands();
      const still = Math.max(Math.abs(wl), Math.abs(wr)) < 0.14;
      const inRange = (siteObs && sd <= 1.52) ||
        (!siteObs && drillProgress > 0.05) ||
        (!siteObs && mem.siteLock && sd <= 1.45);
      const drill = !!(still && inRange);
      if (drill && mem.siteLock) {
        mem.pendingMeta = {
          x: mem.siteLock.x,
          y: mem.siteLock.y,
          value: mem.siteLock.value
        };
      }
      return emit(c, drill);
    }
  }

  if (mem.returning && !atBase) {
    return goHome();
  }

  if (siteObs && carried < mem.capacity && !mem.returning) {
    const sd = Math.max(0, num(siteObs.distance, 99));
    const sb = num(siteObs.bearing, 0);
    const a = rad(mem.theta + sb);
    const sx = poseX + sd * Math.cos(a);
    const sy = poseY + sd * Math.sin(a);
    const homeFromSite = dist(sx, sy, mem.baseX, mem.baseY);
    const siteNeed = routeEnergy(sd, homeFromSite, 0, carried + 1);
    const siteTime = routeSeconds(sd, homeFromSite, 0, carried + 1);

    if (siteNeed > battery - 0.025 || siteTime > timeLeft - 5) {
      if (!atBase) {
        mem.returning = true;
        return goHome();
      }
      return emit(stopCommands(), false);
    }

    if (sd <= 1.28) {
      if (!mem.holdReady) {
        mem.holdX = poseX;
        mem.holdY = poseY;
        mem.holdHeading = mem.theta;
        mem.holdReady = true;
      }
      const c = holdCommands();
      const still = Math.max(Math.abs(wl), Math.abs(wr)) < 0.13;
      if (still && sd <= 1.43) {
        mem.stillTime = num(mem.stillTime, 0) + dt;
      } else {
        mem.stillTime = 0;
      }

      let drill = false;
      if (mem.stillTime >= 0.35 && still && sd <= 1.43) {
        mem.sampleActive = true;
        mem.sampleStart = tNow;
        mem.pendingMeta = mem.siteLock
          ? { x: mem.siteLock.x, y: mem.siteLock.y, value: mem.siteLock.value }
          : { x: sx, y: sy, value: Math.max(0.1, num(siteObs.value, 1)) };
        drill = true;
      }
      return emit(c, drill);
    }

    mem.holdReady = false;
    mem.stillTime = 0;
    if (updateProgress("site", sd, { kind: "site" })) {
      return recoveryAction();
    }
    const speed = sd > 5 ? 0.82 : (sd > 2.4 ? 0.56 : 0.32);
    return emit(navCommands(sb, speed), false);
  }

  if (atBase && carried === 0 && maxWheelSpeed > 0.25) {
    return emit(stopCommands(), false);
  }

  const info = getTask();

  if (!info) {
    if (carried > 0 && !atBase) {
      mem.returning = true;
      return goHome();
    }
    if (!atBase && (battery < homeNeed(homeDist, carried) + 0.06 ||
        timeLeft < homeSeconds(homeDist, carried) + 12)) {
      mem.returning = true;
      return goHome();
    }
    return emit(stopCommands(), false);
  }

  const planNeed = routeEnergy(info.dist, info.home, info.extra, carried + 1);
  const planTime = routeSeconds(info.dist, info.home, info.extra, carried + 1);
  if (planNeed > battery - 0.035 || planTime > timeLeft - 8) {
    if (!atBase) {
      mem.returning = true;
      return goHome();
    }
    return emit(stopCommands(), false);
  }

  if (atBase && !!o.docked && battery < Math.min(1.04, planNeed + 0.07) &&
      timeLeft > planTime + 110) {
    if (!Number.isFinite(mem.dockWaitStart)) mem.dockWaitStart = tNow;
    if (tNow - mem.dockWaitStart < 24) {
      return emit(stopCommands(), false);
    }
  } else {
    mem.dockWaitStart = null;
  }

  if (updateProgress(info.key, info.dist, info)) {
    return recoveryAction();
  }

  let maxV;
  if (info.kind === "hint" && info.phase === "center") {
    maxV = info.dist > 35 ? 0.88 : (info.dist > 10 ? 0.74 : 0.52);
  } else if (info.kind === "hint") {
    maxV = info.dist > 8 ? 0.76 : (info.dist > 3.5 ? 0.55 : 0.36);
  } else if (info.kind === "ambient") {
    maxV = info.dist > 8 ? 0.72 : (info.dist > 3.5 ? 0.52 : 0.34);
  } else {
    maxV = info.dist > 12 ? 0.84 : (info.dist > 5 ? 0.62 : 0.38);
  }

  return emit(navCommands(info.error, maxV), false);
}

function act(obs, mem) {
  const o = obs || {};
  if (!mem || typeof mem !== "object") mem = {};

  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
  const num = (v, d) => {
    const n = Number(v);
    return Number.isFinite(n) ? n : d;
  };
  const wrap = (a) => {
    a = (a + 180) % 360;
    if (a < 0) a += 360;
    return a - 180;
  };
  const rad = (d) => d * Math.PI / 180;
  const deg = (r) => r * 180 / Math.PI;
  const dist = (x1, y1, x2, y2) => Math.hypot(x2 - x1, y2 - y1);

  const tNow = num(o.t, 0);
  const rawH = wrap(num(o.heading, 0));

  if (!mem._init) {
    const m = o.mission && typeof o.mission === "object" ? o.mission : {};
    const sz = m.size;
    let width = 400;
    let height = 400;
    if (typeof sz === "number") {
      width = height = sz;
    } else if (Array.isArray(sz)) {
      width = num(sz[0], 400);
      height = num(sz[1], width);
    } else if (sz && typeof sz === "object") {
      width = num(sz.width, num(sz.w, num(sz.x, 400)));
      height = num(sz.height, num(sz.h, num(sz.y, width)));
    }
    width = Math.max(50, width);
    height = Math.max(50, height);

    const b = m.base && typeof m.base === "object"
      ? m.base
      : { x: width * 0.5, y: height * 0.5 };

    mem.width = width;
    mem.height = height;
    mem.baseX = num(b.x, width * 0.5);
    mem.baseY = num(b.y, height * 0.5);
    mem.seconds = num(m.seconds, 1200);
    mem.capacity = Math.max(1, Math.floor(num(m.capacity, 5)));

    mem.hints = [];
    const hints = Array.isArray(m.hints) ? m.hints : [];
    for (let i = 0; i < hints.length; i++) {
      const h = hints[i] || {};
      mem.hints.push({
        x: clamp(num(h.x, mem.baseX), 3, width - 3),
        y: clamp(num(h.y, mem.baseY), 3, height - 3),
        value: Math.max(0.1, num(h.estimate, num(h.value, 1))),
        status: 0,
        phase: 0,
        step: 0,
        retry: 0,
        angle: (i * 0.57) % (2 * Math.PI),
        startScience: 0,
        bestScience: 0,
        bestX: num(h.x, mem.baseX),
        bestY: num(h.y, mem.baseY)
      });
    }

    mem.globalPoints = [];
    const nx = Math.min(9, Math.max(5, Math.floor((width - 50) / 55) + 1));
    const ny = Math.min(9, Math.max(5, Math.floor((height - 50) / 55) + 1));
    for (let iy = 0; iy < ny; iy++) {
      const y = 25 + (height - 50) * iy / Math.max(1, ny - 1);
      for (let ix = 0; ix < nx; ix++) {
        const x = 25 + (width - 50) * ix / Math.max(1, nx - 1);
        mem.globalPoints.push({ x: x, y: y, done: false });
      }
    }

    const x0 = num(o.x, width * 0.5);
    const y0 = num(o.y, height * 0.5);
    const batt0 = clamp(num(o.battery, 1), 0, 1.6);

    mem.px = x0;
    mem.py = y0;
    mem.theta = rawH;
    mem.headingBias = 0;
    mem.prevRawH = rawH;
    mem.prevT = tNow;
    mem.lastGpsX = x0;
    mem.lastGpsY = y0;
    mem.gpsUnchanged = 0;
    mem.gpsTravelSinceChange = 0;
    mem.gpsFrozen = false;
    mem.gpsRecover = 0;
    mem.compassHold = 0;
    mem.cal = { active: false, x: x0, y: y0, sin: 0, cos: 0, n: 0 };

    mem.eRate = 0.0018;
    mem.energyUse = 0;
    mem.energyDist = 0;
    mem.prevBattery = batt0;

    mem.gains = [[2.2, 2.2], [2.2, 2.2]];
    mem.dead = [[0.17, 0.17], [0.17, 0.17]];
    mem.noResponse = [0, 0];
    mem.lastCmd = [0, 0];
    mem.lastTarget = [0, 0];

    mem.rFilt = [];
    mem.rRaw = [];
    mem.rSameTime = [];
    mem.rSameMotion = [];
    mem.rBad = [];
    for (let i = 0; i < 9; i++) {
      mem.rFilt[i] = 15;
      mem.rRaw[i] = 15;
      mem.rSameTime[i] = 0;
      mem.rSameMotion[i] = 0;
      mem.rBad[i] = false;
    }
