    mem.navKey = "";
    mem.navBest = 1e9;
    mem.navStuck = 0;
    mem.stuckCount = 0;
    mem.lastAim = 0;
    mem.avoidSign = 0;
    mem.recoverTimer = 0;
    mem.recoverSign = 1;
    mem.prevBumped = false;
    mem.siteIgnoreUntil = 0;

    mem.samples = [];
    mem.prevCarried = Math.max(0, Math.floor(num(o.carried, 0)));
    mem.prevCarriedValue = num(o.carriedValue, 0);
    mem.prevDelivered = num(o.delivered, 0);
    mem.beaconBad = false;
    mem.beaconSameTime = 0;
    mem.beaconSameMotion = 0;
    mem.prevBeacon = null;
    mem.scienceEma = null;
    mem._init = true;
  }

  let dt = 0.1;
  if (Number.isFinite(mem.prevT)) {
    const d = tNow - mem.prevT;
    if (d > 0.02 && d <= 0.55) dt = d;
  }
  const width = num(mem.width, 400);
  const height = num(mem.height, 400);
  const rawX = num(o.x, num(mem.px, width * 0.5));
  const rawY = num(o.y, num(mem.py, height * 0.5));
  const wl = num(o.wheelLeft, 0);
  const wr = num(o.wheelRight, 0);
  const vWheel = (wl + wr) * 0.5;
  const wheelTravel = (Math.abs(wl) + Math.abs(wr)) * 0.5 * dt;
  const moveDist = Math.abs(vWheel) * dt;
  const yawRad = ((wr - wl) / 0.6) * dt;
  const yawDeg = deg(yawRad);

  const battery = clamp(num(o.battery, mem.prevBattery), 0, 1.6);
  const solar = Math.max(0, num(o.solar, 0));
  const carried = Math.max(0, Math.floor(num(o.carried, 0)));
  const carriedValue = num(o.carriedValue, mem.prevCarriedValue);
  const delivered = num(o.delivered, mem.prevDelivered);
  const timeLeft = Math.max(0, num(o.timeLeft, mem.seconds - tNow));
  const drillProgress = Math.max(0, num(o.drilling, 0));
  const science = Math.max(0, num(o.science, 0));
  const siteObs = o.site && typeof o.site === "object" ? o.site : null;
  const beacon = o.beacon && typeof o.beacon === "object" ? o.beacon : null;

  const oldCarried = num(mem.prevCarried, carried);
  const oldCarriedValue = num(mem.prevCarriedValue, carriedValue);
  const oldDelivered = num(mem.prevDelivered, delivered);
  const sampleCompleted = carried > oldCarried;

  if (mem.scienceEma === null || !Number.isFinite(mem.scienceEma)) {
    mem.scienceEma = science;
  } else {
    mem.scienceEma = num(mem.scienceEma, science) * 0.78 + science * 0.22;
  }

  const prevTheta = num(mem.theta, rawH);
  const rawDeltaH = wrap(rawH - num(mem.prevRawH, rawH));
  const compassJump =
    Math.abs(wrap(rawDeltaH - yawDeg)) > 75 && Math.abs(yawDeg) < 48;
  if (compassJump) mem.compassHold = 1.5;
  else mem.compassHold = Math.max(0, num(mem.compassHold, 0) - dt);

  let theta = wrap(prevTheta + yawDeg);
  if (!compassJump && mem.compassHold <= 0) {
    const correctedCompass = wrap(rawH - num(mem.headingBias, 0));
    const residual = wrap(correctedCompass - theta);
    if (Math.abs(residual) < 85) {
      theta = wrap(theta + clamp(residual * 0.04, -0.8, 0.8));
    }
  }
  mem.theta = theta;

  const gpsDelta = dist(rawX, rawY, num(mem.lastGpsX, rawX), num(mem.lastGpsY, rawY));
  const gpsJump = gpsDelta > 10 && dt <= 0.55;
  if (gpsDelta < 0.025 && wheelTravel > 0.025) {
    mem.gpsUnchanged = num(mem.gpsUnchanged, 0) + dt;
    mem.gpsTravelSinceChange = num(mem.gpsTravelSinceChange, 0) + wheelTravel;
  } else if (gpsDelta > 0.08) {
    mem.gpsUnchanged = 0;
    mem.gpsTravelSinceChange = 0;
  }

  const wasGpsFrozen = !!mem.gpsFrozen;
  mem.gpsFrozen =
    num(mem.gpsUnchanged, 0) > 2.6 &&
    num(mem.gpsTravelSinceChange, 0) > 1.6;
  if (wasGpsFrozen && !mem.gpsFrozen) mem.gpsRecover = 1.2;
  else mem.gpsRecover = Math.max(0, num(mem.gpsRecover, 0) - dt);

  const midTheta = rad(wrap((prevTheta + theta) * 0.5));
  let predX = num(mem.px, rawX) + vWheel * dt * Math.cos(midTheta);
  let predY = num(mem.py, rawY) + vWheel * dt * Math.sin(midTheta);
  if (!mem.gpsFrozen && !gpsJump) {
    const dx = rawX - predX;
    const dy = rawY - predY;
    const residual = Math.hypot(dx, dy);
    if (residual < 20) {
      let alpha = Math.abs(vWheel) > 0.18 ? 0.085 : 0.008;
      if (mem.gpsRecover > 0) alpha = 0.16;
      const limit = mem.gpsRecover > 0 ? 2.0 :
        (Math.abs(vWheel) > 0.18 ? 1.6 : 0.5);
      const scale = residual > limit ? limit / residual : 1;
      predX += dx * scale * alpha;
      predY += dy * scale * alpha;
    }
  }
  mem.px = predX;
  mem.py = predY;
  mem.lastGpsX = rawX;
  mem.lastGpsY = rawY;
  mem.prevRawH = rawH;

  if (!mem.cal || typeof mem.cal !== "object") {
    mem.cal = { active: false, x: rawX, y: rawY, sin: 0, cos: 0, n: 0 };
  }
  const straightForward =
    vWheel > 0.34 &&
    Math.abs(wr - wl) < 0.22 &&
    !mem.gpsFrozen &&
    !gpsJump &&
    !compassJump;
  if (straightForward) {
    if (!mem.cal.active) {
      mem.cal.active = true;
      mem.cal.x = rawX;
      mem.cal.y = rawY;
      mem.cal.sin = 0;
      mem.cal.cos = 0;
      mem.cal.n = 0;
    }
    mem.cal.sin += Math.sin(rad(rawH));
    mem.cal.cos += Math.cos(rad(rawH));
    mem.cal.n += 1;
    if (dist(rawX, rawY, mem.cal.x, mem.cal.y) >= 12 && mem.cal.n >= 12) {
      const course = deg(Math.atan2(rawY - mem.cal.y, rawX - mem.cal.x));
      const meanRaw = deg(Math.atan2(mem.cal.sin, mem.cal.cos));
      const estimate = wrap(meanRaw - course);
      const err = wrap(estimate - num(mem.headingBias, 0));
      if (Math.abs(err) < 55) {
        mem.headingBias = wrap(num(mem.headingBias, 0) + clamp(err * 0.10, -2, 2));
      }
      mem.cal.x = rawX;
      mem.cal.y = rawY;
      mem.cal.sin = 0;
      mem.cal.cos = 0;
      mem.cal.n = 0;
    }
  } else if (mem.cal) {
    mem.cal.active = false;
    mem.cal.sin = 0;
    mem.cal.cos = 0;
    mem.cal.n = 0;
  }

  if (!Array.isArray(mem.gains) || mem.gains.length < 2) {
    mem.gains = [[2.2, 2.2], [2.2, 2.2]];
  }
  if (!Array.isArray(mem.dead) || mem.dead.length < 2) {
    mem.dead = [[0.17, 0.17], [0.17, 0.17]];
  }
  if (!Array.isArray(mem.lastCmd) || mem.lastCmd.length < 2) mem.lastCmd = [0, 0];
  if (!Array.isArray(mem.lastTarget) || mem.lastTarget.length < 2) mem.lastTarget = [0, 0];
  if (!Array.isArray(mem.noResponse) || mem.noResponse.length < 2) mem.noResponse = [0, 0];

  for (let s = 0; s < 2; s++) {
    if (!Array.isArray(mem.gains[s])) mem.gains[s] = [2.2, 2.2];
    if (!Array.isArray(mem.dead[s])) mem.dead[s] = [0.17, 0.17];

    const cmd = num(mem.lastCmd[s], 0);
    const target = num(mem.lastTarget[s], 0);
    const actual = s === 0 ? wl : wr;
    const direction = target < 0 ? 1 : 0;
    const dead = clamp(num(mem.dead[s][direction], 0.17), 0.10, 0.42);

    if (Math.abs(cmd) > dead + 0.09 && actual * cmd > 0 && Math.abs(actual) > 0.08) {
      const ratio = Math.abs(actual) / Math.max(0.06, Math.abs(cmd) - dead);
      if (ratio > 0.45 && ratio < 5.5) {
        const old = num(mem.gains[s][direction], 2.2);
        mem.gains[s][direction] = clamp(old + (ratio - old) * 0.018, 0.65, 5.2);
      }
    }

    if (Math.abs(target) > 0.22 &&
        Math.abs(cmd) > 0.20 &&
        Math.abs(actual) < 0.06 &&
        !o.bumped) {
      mem.noResponse[s] = num(mem.noResponse[s], 0) + dt;
      if (mem.noResponse[s] > 0.75) {
        mem.dead[s][direction] = clamp(
          num(mem.dead[s][direction], 0.17) + 0.008, 0.12, 0.40
        );
      }
    } else {
      mem.noResponse[s] = 0;
      if (Math.abs(actual) > 0.18 && Math.abs(cmd) > 0.23) {
        mem.dead[s][direction] = Math.max(
          0.11, num(mem.dead[s][direction], 0.17) - 0.0003
        );
      }
    }
  }

  const previousBattery = num(mem.prevBattery, battery);
  if (!o.docked && (wheelTravel > 0.014 || drillProgress > 0.05)) {
    const gross = clamp(
      previousBattery - battery + solar * dt * 0.075,
      0,
      0.02
    );
    mem.energyUse = num(mem.energyUse, 0) + gross;
    mem.energyDist = num(mem.energyDist, 0) +
      Math.max(wheelTravel, drillProgress > 0.05 ? dt * 0.12 : 0);
    if (mem.energyDist >= 10) {
      const loadFactor = 1 + 0.16 * carried;
      const measured = clamp(
        mem.energyUse / Math.max(5, mem.energyDist) / loadFactor,
        0.00045,
        0.0055
      );
      const old = num(mem.eRate, 0.0018);
      const alpha = measured > old ? 0.24 : 0.075;
      mem.eRate = clamp(old + (measured - old) * alpha, 0.00055, 0.0055);
      mem.energyUse = 0;
      mem.energyDist = 0;
    }
  }
  mem.prevBattery = battery;

  const rawRays = o.rays && typeof o.rays.length === "number" ? o.rays : null;
  if (!Array.isArray(mem.rFilt) || mem.rFilt.length !== 9) {
    mem.rFilt = [];
    mem.rRaw = [];
    mem.rSameTime = [];
    mem.rSameMotion = [];
    mem.rBad = [];
    for (let i = 0; i < 9; i++) {
      mem.rFilt[i] = 15;
      mem.rRaw[i] = 15;
      mem.rSameTime[i] = 0;
      mem.rSameMotion[i] = 0;
      mem.rBad[i] = false;
    }
  }

  let allMax = true;
  let anyNear = false;
  for (let i = 0; i < 9; i++) {
    const r = clamp(rawRays ? num(rawRays[i], 15) : 15, 0, 15);
    const last = num(mem.rRaw[i], r);
    const diff = Math.abs(r - last);

    if (diff < 0.025) {
      if (wheelTravel > 0.02 || Math.abs(yawRad) > 0.015) {
        mem.rSameTime[i] = num(mem.rSameTime[i], 0) + dt;
        mem.rSameMotion[i] = num(mem.rSameMotion[i], 0) +
          wheelTravel + Math.abs(yawRad) * 0.55;
      }
    } else if (diff > 0.32) {
      mem.rSameTime[i] = 0;
      mem.rSameMotion[i] = 0;
      mem.rBad[i] = false;
    }

    if (mem.rSameTime[i] > 4.5 &&
        mem.rSameMotion[i] > 2.8 &&
        r < 14.5) {
      mem.rBad[i] = true;
    }

    const effective = mem.rBad[i] ? 15 : r;
    if (effective < 14.8) allMax = false;
    if (effective < 14.4) anyNear = true;

    let f = num(mem.rFilt[i], effective);
    const a = effective < f ? 0.62 : 0.36;
    f += (effective - f) * a;
    mem.rFilt[i] = clamp(f, 0, 15);
    mem.rRaw[i] = r;
  }

  if (allMax && wheelTravel > 0.02) {
    mem.allMaxTravel = num(mem.allMaxTravel, 0) + wheelTravel;
  } else if (anyNear) {
    mem.allMaxTravel = Math.max(0, num(mem.allMaxTravel, 0) - wheelTravel * 1.2);
  }
  mem.rangeTrust = mem.allMaxTravel > 25 ? 0.78 : 1;

  if (beacon) {
    const bd = Math.max(0, num(beacon.distance, 99));
    const bb = num(beacon.bearing, 0);
    const pb = mem.prevBeacon;
    if (pb &&
        Math.abs(bd - num(pb.d, bd)) < 0.015 &&
        Math.abs(wrap(bb - num(pb.b, bb))) < 0.20 &&
        (wheelTravel > 0.02 || Math.abs(yawRad) > 0.015)) {
      mem.beaconSameTime = num(mem.beaconSameTime, 0) + dt;
      mem.beaconSameMotion = num(mem.beaconSameMotion, 0) +
        wheelTravel + Math.abs(yawRad) * 0.6;
      if (mem.beaconSameTime > 6 && mem.beaconSameMotion > 2.8) {
        mem.beaconBad = true;
      }
    } else if (Math.abs(bd - num(pb && pb.d, bd)) > 0.08 ||
               Math.abs(wrap(bb - num(pb && pb.b, bb))) > 1) {
      mem.beaconSameTime = 0;
      mem.beaconSameMotion = 0;
      mem.beaconBad = false;
    }
    mem.prevBeacon = { d: bd, b: bb };
  } else {
    mem.prevBeacon = null;
    mem.beaconSameTime = 0;
    mem.beaconSameMotion = 0;
  }

  if (sampleCompleted) {
    const meta = mem.pendingMeta || mem.siteLock || {
      x: mem.px, y: mem.py, value: 1
    };
    const mx = num(meta.x, mem.px);
    const my = num(meta.y, mem.py);
    let value = Math.max(0.1, num(meta.value, 1));
    const valueGain = carriedValue - oldCarriedValue;
    if (valueGain > 0.01) value = valueGain / Math.max(1, carried - oldCarried);
    mem.samples.push({ x: mx, y: my, value: value });

    let associated = -1;
    let bestAssociation = 40;
    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (!h || h.status >= 2) continue;
      const d = dist(mx, my, h.x, h.y);
      if (d < bestAssociation) {
        bestAssociation = d;
        associated = i;
      }
    }
    const currentHint = Math.floor(num(mem.currentHint, -1));
    if (currentHint >= 0 && currentHint < mem.hints.length &&
        mem.hints[currentHint].status < 2 &&
        dist(mx, my, mem.hints[currentHint].x, mem.hints[currentHint].y) < 48) {
      associated = currentHint;
    }
    if (associated >= 0) {
      mem.hints[associated].status = 2;
      if (associated === currentHint) mem.currentHint = -1;
    }

    for (let i = 0; i < mem.globalPoints.length; i++) {
      const p = mem.globalPoints[i];
      if (p && dist(mx, my, p.x, p.y) < 12) p.done = true;
    }
    if (mem.ambient && dist(mx, my, mem.ambient.x, mem.ambient.y) < 32) {
      mem.ambient = null;
    }

    mem.sampleActive = false;
    mem.pendingMeta = null;
    mem.siteLock = null;
    mem.holdReady = false;
    mem.stillTime = 0;
    mem.navKey = "";
  } else if (carried < oldCarried || delivered > oldDelivered) {
    mem.sampleActive = false;
    mem.pendingMeta = null;
    mem.siteLock = null;
    mem.holdReady = false;
    mem.stillTime = 0;
  }

  if (siteObs && carried < mem.capacity) {
    const sd = Math.max(0, num(siteObs.distance, 99));
    const sb = num(siteObs.bearing, 0);
    const a = rad(mem.theta + sb);
    const sx = mem.px + sd * Math.cos(a);
    const sy = mem.py + sd * Math.sin(a);
    const sv = Math.max(0.1, num(siteObs.value, 1));
    if (!mem.siteLock) {
      mem.siteLock = { x: sx, y: sy, value: sv, lastSeen: tNow };
    } else {
      const gap = dist(mem.siteLock.x, mem.siteLock.y, sx, sy);
      if (gap > 11) {
        mem.siteLock.x = sx;
        mem.siteLock.y = sy;
      } else {
        mem.siteLock.x = mem.siteLock.x * 0.70 + sx * 0.30;
        mem.siteLock.y = mem.siteLock.y * 0.70 + sy * 0.30;
      }
      mem.siteLock.value = sv;
      mem.siteLock.lastSeen = tNow;
    }
  } else if (mem.siteLock &&
             !mem.sampleActive &&
             tNow - num(mem.siteLock.lastSeen, tNow) > 18) {
    mem.siteLock = null;
  }

  if (!sampleCompleted && !mem.sampleActive && drillProgress > 0.05) {
    mem.sampleActive = true;
    mem.sampleStart = tNow - drillProgress;
    if (!mem.holdReady) {
      mem.holdX = mem.px;
      mem.holdY = mem.py;
      mem.holdHeading = mem.theta;
      mem.holdReady = true;
    }
    if (mem.siteLock) {
      mem.pendingMeta = {
        x: mem.siteLock.x,
        y: mem.siteLock.y,
        value: mem.siteLock.value
      };
    }
  }

  const poseX = num(mem.px, rawX);
  const poseY = num(mem.py, rawY);
  const baseX = num(mem.baseX, width * 0.5);
  const baseY = num(mem.baseY, height * 0.5);
  const baseDist = dist(poseX, poseY, baseX, baseY);
  const beaconDist = beacon ? Math.max(0, num(beacon.distance, 99)) : 99;
  const beaconUsable = !!beacon && !mem.beaconBad && beaconDist <= 20.5;
  const maxWheelSpeed = Math.max(Math.abs(wl), Math.abs(wr));
  const atBase = !!o.docked ||
    (beaconUsable && beaconDist <= 2.8) ||
    (baseDist <= 2.5 && maxWheelSpeed < 0.22);
  const homeDist = beaconUsable ? beaconDist : baseDist;

  function travelNeed(d, load) {
    const l = Math.max(0, load);
    return 0.015 +
      Math.max(0, d) * num(mem.eRate, 0.0018) * (1.18 + 0.16 * l);
  }

  function homeNeed(d, load) {
    const l = Math.max(0, load);
    return 0.055 + 0.014 * l +
      Math.max(0, d) * num(mem.eRate, 0.0018) * (1.28 + 0.20 * l);
  }

  function homeSeconds(d, load) {
    return Math.max(0, d) / 0.46 + 38 + 6 * Math.max(0, load);
  }

  function canPlan(info, loadAfter) {
    if (!info) return false;
    const l = Math.max(carried, loadAfter);
    const need = travelNeed(info.dist, carried) +
      homeNeed(info.home, l) + 0.045 + 0.085;
    const seconds = Math.max(0, info.dist) / 0.52 +
      Math.max(0, info.home) / 0.46 + 43 + 7 * l;
    return need <= battery && seconds <= timeLeft - 5;
  }

  const homeEnergyNow = homeNeed(homeDist, carried);
  const homeTimeNow = homeSeconds(homeDist, carried);

  if (delivered > oldDelivered && carried === 0) {
    mem.returning = false;
  }
  if (mem.returning && atBase && carried === 0) {
    mem.returning = false;
    mem.sampleActive = false;
    mem.holdReady = false;
    mem.stillTime = 0;
  }
  if (!mem.returning && !mem.sampleActive) {
    if (carried >= mem.capacity) {
      mem.returning = true;
    } else if (!atBase &&
        battery < homeEnergyNow + (carried > 0 ? 0.12 : 0.08)) {
      mem.returning = true;
    } else if (carried > 0 && timeLeft < homeTimeNow + 45) {
      mem.returning = true;
    } else if (carried === 0 && !atBase && battery < 0.045) {
      mem.returning = true;
    }
  }

  function gainFor(side, target) {
    const direction = target < -0.015 ? 1 : 0;
    return clamp(num(mem.gains[side][direction], 2.2), 0.65, 5.2);
  }

  function motorPower(target, actual, side, hold) {
    if (Math.abs(target) < 0.025) {
      if (Math.abs(actual) < 0.045) return 0;
      const commandDir = actual > 0 ? 1 : 0;
      const gain = clamp(num(mem.gains[side][commandDir], 2.2), 0.65, 5.2);
      const dead = clamp(num(mem.dead[side][commandDir], 0.17), 0.10, 0.42);
      const brake = dead + Math.min(0.25, Math.abs(actual) / gain * 0.55);
      return clamp(-Math.sign(actual) * brake, -1, 1);
    }

    const direction = target < 0 ? 1 : 0;
    const gain = gainFor(side, target);
    const dead = clamp(num(mem.dead[side][direction], 0.17), 0.10, 0.42);
    const kp = hold ? 0.48 : 0.55;
    let u = Math.sign(target) * (dead + Math.abs(target) / gain) +
      kp * (target - actual);

    if (Math.abs(actual) > 0.93 &&
        Math.abs(actual) > Math.abs(target) + 0.04) {
      u = -Math.sign(actual) *
        (dead + Math.min(0.28, Math.abs(actual) / gain * 0.5));
    } else if (Math.abs(target) > 0.06 &&
        u * target > 0 &&
        Math.abs(u) < dead + 0.018 &&
        !(actual * target > 0 &&
          Math.abs(actual) > Math.abs(target) + 0.08)) {
      u = Math.sign(target) * (dead + 0.018);
    }
    return clamp(u, -1, 1);
  }

  function wheelCommands(v, omega, hold) {
    const leftTarget = clamp(v - 0.3 * omega, -0.85, 0.85);
    const rightTarget = clamp(v + 0.3 * omega, -0.85, 0.85);
    return {
      left: motorPower(leftTarget, wl, 0, !!hold),
      right: motorPower(rightTarget, wr, 1, !!hold),
      tl: leftTarget,
      tr: rightTarget
    };
  }

  function stopCommands() {
    return wheelCommands(0, 0, false);
  }

  function emit(c, drill) {
    const left = clamp(num(c && c.left, 0), -1, 1);
    const right = clamp(num(c && c.right, 0), -1, 1);
    mem.lastCmd = [left, right];
    mem.lastTarget = [num(c && c.tl, 0), num(c && c.tr, 0)];
    mem.prevT = tNow;
    mem.prevBattery = battery;
    mem.prevCarried = carried;
    mem.prevCarriedValue = carriedValue;
    mem.prevDelivered = delivered;
    return { left: left, right: right, drill: !!drill };
  }

  function rayAt(angle) {
    const a = clamp(angle, -80, 80);
    const q = (a + 80) / 20;
    const i = Math.floor(q);
    const f = q - i;
    if (i >= 8) return num(mem.rFilt[8], 15);
    return num(mem.rFilt[i], 15) * (1 - f) +
      num(mem.rFilt[i + 1], 15) * f;
  }

  function clearanceAt(angle) {
    const center = rayAt(angle);
    const side = Math.min(rayAt(angle - 20), rayAt(angle + 20));
    return Math.min(center, center * 0.75 + side * 0.25);
  }

  function edgeDistance(angle) {
    const a = rad(wrap(mem.theta + angle));
    const dx = Math.cos(a);
    const dy = Math.sin(a);
    const margin = 5;
    let d = 1e6;
    if (dx > 0.001) d = Math.min(d, (width - margin - poseX) / dx);
    if (dx < -0.001) d = Math.min(d, (margin - poseX) / dx);
    if (dy > 0.001) d = Math.min(d, (height - margin - poseY) / dy);
    if (dy < -0.001) d = Math.min(d, (margin - poseY) / dy);
    return Math.max(0, d);
  }

  function navCommands(goalError, maxV) {
    const goal = wrap(num(goalError, 0));
    const vmax = clamp(num(maxV, 0.62), 0, 0.74);

    if (Math.abs(goal) > 96) {
      const s = Math.sign(goal) || 1;
      mem.lastAim = s * 90;
      return wheelCommands(0, s * 0.55, false);
    }

    const clippedGoal = clamp(goal, -80, 80);
    const candidates = [
      -80, -60, -40, -20, 0, 20, 40, 60, 80,
      clippedGoal,
      clamp(goal * 0.65, -80, 80)
    ];
    const safe = 2.15 + vmax * 1.25;
    const front = clearanceAt(0);
    let best = clippedGoal;
    let bestCost = 1e9;
    let bestClear = 15;

    for (let i = 0; i < candidates.length; i++) {
      const a = candidates[i];
      const clear = clearanceAt(a);
      let cost = Math.abs(wrap(a - clippedGoal)) * 0.024;
      const hazard = Math.max(0, safe - clear);
      cost += hazard * hazard * 1.7;
      if (clear < 1.15) cost += 10;
      if (clear < 0.70) cost += 22;

      const edge = edgeDistance(a);
      if (edge < 2.5) cost += 18;
      else if (edge < 8) cost += (8 - edge) * 0.8;

      if (front < safe && Math.abs(a) > 10 && mem.avoidSign &&
          Math.sign(a) !== Math.sign(mem.avoidSign)) {
        cost += 0.22;
      }
      if (front < safe) {
        cost += Math.abs(a - num(mem.lastAim, a)) * 0.004;
      }

      if (cost < bestCost) {
        bestCost = cost;
        best = a;
        bestClear = clear;
      }
    }

    if (front > safe + 1.4) mem.avoidSign = 0;
    else if (Math.abs(best) > 10) mem.avoidSign = Math.sign(best);
    mem.lastAim = best;

    let v = vmax;
    v *= clamp((bestClear - 0.65) / Math.max(1, safe - 0.65), 0.12, 1);
    if (bestClear < 1.15) v = Math.min(v, 0.11);
    if (front < 0.9 && Math.abs(best) < 18) v = Math.min(v, 0.09);
    if (Math.abs(best) > 60) v = Math.min(v, 0.27);
    else if (Math.abs(best) > 42) v = Math.min(v, 0.43);
    else if (Math.abs(best) > 27) v = Math.min(v, 0.58);
    if (mem.rangeTrust < 0.85) v = Math.min(v, 0.55);

    const omega = clamp(1.20 * rad(best), -0.72, 0.72);
    return wheelCommands(v, omega, false);
  }

  function holdCommands() {
    if (!mem.holdReady) {
      mem.holdX = poseX;
      mem.holdY = poseY;
      mem.holdHeading = mem.theta;
      mem.holdReady = true;
    }

    const a = rad(mem.theta);
    const dx = num(mem.holdX, poseX) - poseX;
    const dy = num(mem.holdY, poseY) - poseY;
    const along = dx * Math.cos(a) + dy * Math.sin(a);
    const avg = (wl + wr) * 0.5;
    const positionCorrection =
      Math.abs(along) > 0.45 ? clamp(0.28 * along, -0.07, 0.07) : 0;
    const pitchFeed = clamp(num(o.pitch, 0) * 0.004, -0.10, 0.10);
    const vDes = clamp(positionCorrection - 0.85 * avg + pitchFeed, -0.12, 0.12);
    const headingErr = wrap(num(mem.holdHeading, mem.theta) - mem.theta);
    const omega = clamp(1.1 * rad(headingErr), -0.18, 0.18);
    return wheelCommands(vDes, omega, true);
  }

  function openSide() {
    let leftOpen = 0;
    let rightOpen = 0;
    for (let i = 5; i < 9; i++) leftOpen += num(mem.rFilt[i], 15);
    for (let i = 0; i < 4; i++) rightOpen += num(mem.rFilt[i], 15);
    if (Math.abs(leftOpen - rightOpen) < 0.5) {
      return mem.avoidSign ? -mem.avoidSign : 1;
    }
    return leftOpen >= rightOpen ? 1 : -1;
  }

  function recoveryAction() {
    const rem = Math.max(0, num(mem.recoverTimer, 0));
    const s = num(mem.recoverSign, 1);
    let c;
    if (rem > 0.65) c = wheelCommands(-0.22, s * 0.45, false);
    else c = wheelCommands(0, s * 0.52, false);
    mem.recoverTimer = Math.max(0, rem - dt);
    if (mem.recoverTimer <= 0) mem.recoverMode = 0;
    return emit(c, false);
  }

  function skipTarget(info) {
    if (!info) return;
    if (info.kind === "hint" &&
        info.index >= 0 && info.index < mem.hints.length) {
      const h = mem.hints[info.index];
      if (h) {
        if (info.phase === 0) {
          h.phase = 1;
          h.step = 0;
          h.startScience = num(mem.scienceEma, science);
          h.bestScience = Math.max(num(h.bestScience, 0), science);
        } else {
          const count = info.phase === 2 ? 6 : 8;
          h.step = Math.min(count, Math.max(0, Math.floor(num(h.step, 0))) + 1);
        }
      }
    } else if (info.kind === "ambient" && mem.ambient) {
      mem.ambient.step = Math.min(
        mem.ambient.count,
        Math.max(0, Math.floor(num(mem.ambient.step, 0))) + 1
      );
    } else if (info.kind === "global" &&
        info.index >= 0 && info.index < mem.globalPoints.length) {
      mem.globalPoints[info.index].done = true;
      mem.globalIndex = -1;
    } else if (info.kind === "site") {
      mem.siteLock = null;
      mem.siteIgnoreUntil = tNow + 18;
    }
  }

  function updateProgress(key, d, info) {
    if (mem.navKey !== key) {
      mem.navKey = key;
      mem.navBest = d;
      mem.navStuck = 0;
      mem.stuckCount = 0;
      return false;
    }
    if (d < num(mem.navBest, d) - 0.55) {
      mem.navBest = d;
      mem.navStuck = 0;
      mem.stuckCount = 0;
      return false;
    }
    mem.navStuck = num(mem.navStuck, 0) + dt;
    if (mem.navStuck > 26) {
      mem.navStuck = 0;
      mem.navBest = d;
      mem.stuckCount = num(mem.stuckCount, 0) + 1;
      mem.recoverSign = mem.avoidSign ? -mem.avoidSign : openSide();
      mem.avoidSign = mem.recoverSign;
      mem.recoverTimer = 1.35;
      mem.recoverMode = 1;
      if (mem.stuckCount >= 3) {
        skipTarget(info);
        mem.navKey = "";
        mem.stuckCount = 0;
      }
      return true;
    }
    return false;
  }

  function ringPoint(cx, cy, step, count, radius, offset) {
    const a = num(offset, 0) + 2 * Math.PI * step / count;
    return {
      x: clamp(cx + radius * Math.cos(a), 4, width - 4),
      y: clamp(cy + radius * Math.sin(a), 4, height - 4)
    };
  }

  function finishHint(h, index) {
    if (h.phase === 1 &&
        !h.retry &&
        num(h.bestScience, 0) > num(h.startScience, 0) + 0.26 &&
        num(h.bestScience, 0) > 0.95 &&
        dist(num(h.bestX, h.x), num(h.bestY, h.y), h.x, h.y) > 2.5) {
      h.x = clamp(num(h.bestX, h.x), 4, width - 4);
      h.y = clamp(num(h.bestY, h.y), 4, height - 4);
      h.phase = 2;
      h.step = 0;
      h.retry = 1;
      h.startScience = num(h.bestScience, science);
      h.bestScience = num(h.startScience, science);
      h.bestX = poseX;
      h.bestY = poseY;
      return;
    }
    h.status = 2;
    if (Math.floor(num(mem.currentHint, -1)) === index) mem.currentHint = -1;
  }

  function hintInfo(index) {
    const h = mem.hints[index];
    if (!h || h.status >= 2) return null;

    const dFromHint = dist(poseX, poseY, h.x, h.y);
    if ((dFromHint < 48 || index === Math.floor(num(mem.currentHint, -1))) &&
        science > num(h.bestScience, 0) + 0.035) {
      h.bestScience = science;
      h.bestX = poseX;
      h.bestY = poseY;
    }

    for (let tries = 0; tries < 8; tries++) {
      if (h.phase === 0) {
        const d = dist(poseX, poseY, h.x, h.y);
        if (d <= 3.8) {
          h.phase = 1;
          h.step = 0;
          h.startScience = num(mem.scienceEma, science);
          if (num(h.bestScience, 0) < h.startScience) {
            h.bestScience = h.startScience;
            h.bestX = poseX;
            h.bestY = poseY;
          }
          continue;
        }
        return {
          kind: "hint",
          index: index,
          phase: 0,
          x: h.x,
          y: h.y,
          dist: d,
          home: dist(h.x, h.y, baseX, baseY),
          key: "hc:" + index
        };
      }

      const count = h.phase === 2 ? 6 : 8;
      const radius = h.phase === 2 ? 6.5 : 14.5;
      let step = Math.max(0, Math.floor(num(h.step, 0)));
      while (step < count) {
        const p = ringPoint(h.x, h.y, step, count, radius, h.angle);
        const d = dist(poseX, poseY, p.x, p.y);
        if (d <= 3.4) {
          h.step = ++step;
          continue;
        }
        return {
          kind: "hint",
          index: index,
          phase: h.phase,
          step: step,
          x: p.x,
          y: p.y,
          dist: d,
          home: dist(p.x, p.y, baseX, baseY),
          key: "hr:" + index + ":" + h.phase + ":" + step
        };
      }

      finishHint(h, index);
      if (h.status >= 2) return null;
    }
    return null;
  }

  function makeAmbientInfo() {
    const a = mem.ambient;
    if (!a) return null;

    if (science > num(a.bestScience, 0) + 0.035) {
      a.bestScience = science;
      a.bestX = poseX;
      a.bestY = poseY;
    }

    for (let tries = 0; tries < 8; tries++) {
      if (a.step >= a.count) {
        if (!a.retry &&
            num(a.bestScience, 0) > num(a.startScience, 0) + 0.24 &&
            num(a.bestScience, 0) > 0.95 &&
            dist(a.bestX, a.bestY, a.x, a.y) > 2.5) {
          a.x = clamp(num(a.bestX, a.x), 4, width - 4);
          a.y = clamp(num(a.bestY, a.y), 4, height - 4);
          a.step = 0;
          a.count = 6;
          a.radius = 5.8;
          a.retry = 1;
          a.startScience = a.bestScience;
          a.bestScience = a.startScience;
          a.bestX = poseX;
          a.bestY = poseY;
          continue;
        }
        mem.ambientLastX = a.x;
        mem.ambientLastY = a.y;
        mem.ambient = null;
        return null;
      }

      const p = ringPoint(a.x, a.y, a.step, a.count, a.radius, 0);
      const d = dist(poseX, poseY, p.x, p.y);
      if (d <= 3.2) {
        a.step++;
        continue;
      }
      return {
        kind: "ambient",
        index: a.step,
        x: p.x,
        y: p.y,
        dist: d,
        home: dist(p.x, p.y, baseX, baseY),
        key: "a:" + a.step
      };
    }
    return null;
  }

  function globalInfo(index) {
    const p = mem.globalPoints[index];
    if (!p || p.done) return null;
    const d = dist(poseX, poseY, p.x, p.y);
    if (d <= 3.8) {
      p.done = true;
      if (Math.floor(num(mem.globalIndex, -1)) === index) mem.globalIndex = -1;
      return null;
    }
    return {
      kind: "global",
      index: index,
      x: p.x,
      y: p.y,
      dist: d,
      home: dist(p.x, p.y, baseX, baseY),
      key: "g:" + index
    };
  }

  function chooseHint() {
    let best = -1;
    let bestScore = -1;
    let bestInfo = null;
    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (!h || h.status >= 2) continue;
      const info = hintInfo(i);
      if (!info || !canPlan(info, Math.min(mem.capacity, carried + 1))) continue;
      const searchCost = info.phase === 0 ? 65 :
        Math.max(0, (info.phase === 2 ? 6 : 8) - num(info.step, 0)) * 8;
      let score = Math.pow(Math.max(0.1, num(h.value, 1)), 1.16) /
        (48 + info.dist + 0.72 * info.home + 0.32 * searchCost + 8 * carried);
      if (h.status === 1) score *= 1.08;
      if (i === Math.floor(num(mem.currentHint, -1))) score *= 1.08;
      if (score > bestScore) {
        bestScore = score;
        best = i;
        bestInfo = info;
      }
    }
    if (best >= 0) {
      mem.currentHint = best;
      mem.hints[best].status = 1;
      return bestInfo;
    }
    return null;
  }

  function chooseGlobal() {
    const old = Math.floor(num(mem.globalIndex, -1));
    if (old >= 0 && old < mem.globalPoints.length) {
      const info = globalInfo(old);
      if (info && canPlan(info, Math.min(mem.capacity, carried + 1))) return info;
      mem.globalIndex = -1;
    }

    let best = -1;
    let bestScore = -1;
    let bestInfo = null;
    for (let i = 0; i < mem.globalPoints.length; i++) {
      const info = globalInfo(i);
      if (!info || !canPlan(info, Math.min(mem.capacity, carried + 1))) continue;
      const score = 1 / (38 + info.dist + 0.52 * info.home + 7 * carried);
      if (score > bestScore) {
        bestScore = score;
        best = i;
        bestInfo = info;
      }
    }
    mem.globalIndex = best;
    return bestInfo;
  }

  function getTask() {
    const current = Math.floor(num(mem.currentHint, -1));
    if (current >= 0 && current < mem.hints.length &&
        mem.hints[current] && mem.hints[current].status < 2) {
      const info = hintInfo(current);
      if (info && canPlan(info, Math.min(mem.capacity, carried + 1))) {
        return info;
      }
      mem.currentHint = -1;
    }

    const hint = chooseHint();
    if (hint) return hint;

    if (!mem.ambient &&
        science > 1.12 &&
        dist(poseX, poseY,
          num(mem.ambientLastX, -1e9),
          num(mem.ambientLastY, -1e9)) > 28) {
      mem.ambient = {
        x: poseX,
        y: poseY,
        step: 0,
        count: 8,
        radius: 9,
        retry: 0,
        startScience: num(mem.scienceEma, science),
        bestScience: num(mem.scienceEma, science),
        bestX: poseX,
        bestY: poseY
      };
    }

    if (mem.ambient) {
      const ainfo = makeAmbientInfo();
      if (ainfo && canPlan(ainfo, Math.min(mem.capacity, carried + 1))) {
        return ainfo;
      }
    }
    return chooseGlobal();
  }

  function goHome() {
    if (atBase || homeDist <= 2.35) return emit(stopCommands(), false);

    let err;
    if (beaconUsable) {
      err = num(beacon.bearing, 0);
    } else {
      err = wrap(
        deg(Math.atan2(baseY - poseY, baseX - poseX)) - mem.theta
      );
    }

    if (updateProgress("base", homeDist, { kind: "base" })) {
      return recoveryAction();
    }

    const speed = homeDist > 30 ? 0.68 : (homeDist > 8 ? 0.54 : 0.38);
    return emit(navCommands(err, speed), false);
  }

  if (o.bumped && !mem.prevBumped && !mem.sampleActive && !atBase) {
    mem.recoverSign = openSide();
    mem.recoverTimer = 1.25;
    mem.recoverMode = 1;
    mem.avoidSign = mem.recoverSign;
  }
  mem.prevBumped = !!o.bumped;

  if (mem.sampleActive) {
    const elapsed = tNow - num(mem.sampleStart, tNow);
    const sd = siteObs
      ? Math.max(0, num(siteObs.distance, 99))
      : (mem.siteLock
        ? dist(poseX, poseY, mem.siteLock.x, mem.siteLock.y)
        : 99);

    const timedOut =
      (elapsed > 19 && drillProgress < 5.7) ||
      (elapsed > 25 && carried === oldCarried);
    const lostSite =
      siteObs && sd > 1.95 && drillProgress < 0.2 && elapsed > 2.2;

    if (timedOut || lostSite) {
      mem.sampleActive = false;
      mem.pendingMeta = null;
      mem.holdReady = false;
      mem.stillTime = 0;
      mem.sampleFailures = num(mem.sampleFailures, 0) + 1;
    } else {
      if (!mem.holdReady) {
        mem.holdX = poseX;
        mem.holdY = poseY;
        mem.holdHeading = mem.theta;
        mem.holdReady = true;
      }
      if (mem.siteLock) {
        mem.pendingMeta = {
          x: mem.siteLock.x,
          y: mem.siteLock.y,
          value: mem.siteLock.value
        };
      }
      return emit(holdCommands(), true);
    }
  }

  if (atBase && carried > 0) {
    return emit(stopCommands(), false);
  }

  if (mem.recoverTimer > 0 && !atBase) {
    return recoveryAction();
  }

  if (mem.returning && !atBase) {
    return goHome();
  }

  if (atBase && carried === 0 && maxWheelSpeed > 0.30) {
    return emit(stopCommands(), false);
  }

  if (siteObs &&
      carried < mem.capacity &&
      !mem.returning &&
      tNow >= num(mem.siteIgnoreUntil, 0)) {
    const sd = Math.max(0, num(siteObs.distance, 99));
    const sb = num(siteObs.bearing, 0);
    const siteAngle = rad(mem.theta + sb);
    const sx = poseX + sd * Math.cos(siteAngle);
    const sy = poseY + sd * Math.sin(siteAngle);
    const siteHome = dist(sx, sy, baseX, baseY);
    const sitePlan = {
      kind: "site",
      dist: sd,
      home: siteHome
    };

    if (!canPlan(sitePlan, Math.min(mem.capacity, carried + 1))) {
      mem.returning = true;
      if (atBase) return emit(stopCommands(), false);
      return goHome();
    }

    if (sd <= 1.36) {
      if (!mem.holdReady) {
        mem.holdX = poseX;
        mem.holdY = poseY;
        mem.holdHeading = mem.theta;
        mem.holdReady = true;
      }
      const c = holdCommands();
      const still = Math.max(Math.abs(wl), Math.abs(wr)) < 0.12;
      if (still && sd <= 1.44) {
        mem.stillTime = num(mem.stillTime, 0) + dt;
      } else {
        mem.stillTime = 0;
      }

      let drill = false;
      if (mem.stillTime >= 0.35 && still && sd <= 1.44) {
        mem.sampleActive = true;
        mem.sampleStart = tNow;
        mem.pendingMeta = mem.siteLock
          ? {
              x: mem.siteLock.x,
              y: mem.siteLock.y,
              value: mem.siteLock.value
            }
          : {
              x: sx,
              y: sy,
              value: Math.max(0.1, num(siteObs.value, 1))
            };
        drill = true;
      }
      return emit(c, drill);
    }

    mem.holdReady = false;
    mem.stillTime = 0;
    if (updateProgress("site", sd, { kind: "site" })) {
      return recoveryAction();
    }
    const speed = sd > 5 ? 0.58 : (sd > 2.5 ? 0.42 : 0.28);
    return emit(navCommands(sb, speed), false);
  }

  const info = getTask();

  if (!info) {
    if (carried > 0 || !atBase) {
      mem.returning = true;
      return goHome();
    }
    return emit(stopCommands(), false);
  }

  if (!canPlan(info, Math.min(mem.capacity, carried + 1))) {
    if (carried > 0 || !atBase) {
      mem.returning = true;
      return goHome();
    }
    return emit(stopCommands(), false);
  }

  if (updateProgress(info.key, info.dist, info)) {
    return recoveryAction();
  }

  const goalBearing = deg(Math.atan2(info.y - poseY, info.x - poseX));
  const goalError = wrap(goalBearing - mem.theta);
  let maxV;
  if (info.kind === "hint" && info.phase === 0) {
    maxV = info.dist > 40 ? 0.70 : (info.dist > 10 ? 0.59 : 0.43);
  } else if (info.kind === "hint") {
    maxV = info.dist > 8 ? 0.62 : (info.dist > 3.5 ? 0.48 : 0.34);
  } else if (info.kind === "ambient") {
    maxV = info.dist > 7 ? 0.56 : (info.dist > 3 ? 0.43 : 0.32);
  } else {
    maxV = info.dist > 15 ? 0.69 : (info.dist > 5 ? 0.54 : 0.36);
  }

  return emit(navCommands(goalError, maxV), false);
}

function act(obs, mem) {
  const o = obs || {};
  if (!mem || typeof mem !== "object") mem = {};

  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
  const num = (v, d) => {
    const n = Number(v);
    return Number.isFinite(n) ? n : d;
  };
  const wrap = (a) => {
    a = (a + 180) % 360;
    if (a < 0) a += 360;
    return a - 180;
  };
  const rad = (d) => d * Math.PI / 180;
  const deg = (r) => r * 180 / Math.PI;
  const dist = (x1, y1, x2, y2) => Math.hypot(x2 - x1, y2 - y1);

  const tNow = num(o.t, 0);
  const rawH = wrap(num(o.heading, 0));

  if (!mem._init) {
    const m = o.mission && typeof o.mission === "object" ? o.mission : {};
    const sz = m.size;
    let width = 400, height = 400;
    if (typeof sz === "number") {
      width = height = sz;
    } else if (Array.isArray(sz)) {
      width = num(sz[0], 400);
      height = num(sz[1], width);
    } else if (sz && typeof sz === "object") {
      width = num(sz.width, num(sz.w, num(sz.x, 400)));
      height = num(sz.height, num(sz.h, num(sz.y, width)));
    }
    width = Math.max(50, width);
    height = Math.max(50, height);

    const b = m.base && typeof m.base === "object"
      ? m.base
      : { x: width * 0.5, y: height * 0.5 };

    mem.width = width;
    mem.height = height;
    mem.baseX = num(b.x, width * 0.5);
    mem.baseY = num(b.y, height * 0.5);
    mem.seconds = num(m.seconds, 1200);
    mem.capacity = Math.max(1, Math.floor(num(m.capacity, 5)));

    mem.hints = [];
    const hs = Array.isArray(m.hints) ? m.hints : [];
    for (let i = 0; i < hs.length; i++) {
      const h = hs[i] || {};
      const hx = clamp(num(h.x, mem.baseX), 4, width - 4);
      const hy = clamp(num(h.y, mem.baseY), 4, height - 4);
      mem.hints.push({
        x: hx,
        y: hy,
        value: Math.max(0.1, num(h.estimate, num(h.value, 1))),
        status: 0,
        phase: 0,
        step: 0,
        retry: 0,
        angle: (i * 0.57) % (2 * Math.PI),
        startScience: 0,
        bestScience: 0,
        bestX: hx,
        bestY: hy
      });
    }

    mem.globalPoints = [];
    for (let iy = 0; iy < 10; iy++) {
      for (let ix = 0; ix < 10; ix++) {
        mem.globalPoints.push({
          x: 20 + (width - 40) * ix / 9,
          y: 20 + (height - 40) * iy / 9,
          done: false
        });
      }
    }

    const x0 = num(o.x, width * 0.5);
    const y0 = num(o.y, height * 0.5);
    mem.px = x0;
    mem.py = y0;
    mem.theta = rawH;
    mem.headingBias = 0;
    mem.prevRawH = rawH;
    mem.prevT = tNow;
    mem.lastGpsX = x0;
    mem.lastGpsY = y0;
    mem.gpsUnchanged = 0;
    mem.gpsTravelSinceChange = 0;
    mem.gpsFrozen = false;
    mem.gpsRecover = 0;
    mem.compassHold = 0;
    mem.cal = { active: false, x: x0, y: y0, sin: 0, cos: 0, n: 0 };

    mem.gain = [[3.2, 3.2], [3.2, 3.2]];
    mem.dead = [[0.20, 0.20], [0.20, 0.20]];
    mem.noResponse = [0, 0];
    mem.lastCmd = [0, 0];
    mem.lastTarget = [0, 0];

    mem.rFilt = [];
    for (let i = 0; i < 9; i++) mem.rFilt[i] = 15;
    mem.rangeTravel = 0;
    mem.rangeTrust = 1;

    mem.energyRate = 0.00065;
    mem.energyUse = 0;
    mem.energyDist = 0;
    mem.prevBattery = clamp(num(o.battery, 1), 0, 1.8);

    mem.currentHint = -1;
    mem.globalIndex = -1;
    mem.ambient = null;
    mem.ambientLastX = -1e9;
    mem.ambientLastY = -1e9;

    mem.siteLock = null;
    mem.pendingMeta = null;
    mem.sampleActive = false;
    mem.sampleStart = 0;
    mem.stillTime = 0;
    mem.holdReady = false;

    mem.returning = false;
    mem.navKey = "";
    mem.navBest = 1e9;
    mem.navStuck = 0;
    mem.stuckCount = 0;
    mem.lastAim = 0;
    mem.avoidSign = 0;
    mem.recoverTimer = 0;
    mem.recoverSign = 1;
    mem.prevBumped = false;
    mem.siteIgnoreUntil = 0;

    mem.prevCarried = Math.max(0, Math.floor(num(o.carried, 0)));
    mem.prevCarriedValue = num(o.carriedValue, 0);
    mem.prevDelivered = num(o.delivered, 0);
    mem.prevBeacon = null;
    mem.beaconSameTime = 0;
    mem.beaconSameMotion = 0;
    mem.beaconBad = false;
    mem.scienceEma = Math.max(0, num(o.science, 0));
    mem.samples = [];
    mem._init = true;
  }

  let dt = 0.1;
  if (Number.isFinite(mem.prevT)) {
    const d = tNow - mem.prevT;
    if (d > 0.02 && d <= 0.55) dt = d;
  }

  const width = num(mem.width, 400);
  const height = num(mem.height, 400);
  const rawX = num(o.x, num(mem.px, width * 0.5));
  const rawY = num(o.y, num(mem.py, height * 0.5));
  const wl = num(o.wheelLeft, 0);
  const wr = num(o.wheelRight, 0);
  const vWheel = (wl + wr) * 0.5;
  const wheelTravel = (Math.abs(wl) + Math.abs(wr)) * 0.5 * dt;
  const moveDist = Math.abs(vWheel) * dt;
  const yawRad = ((wr - wl) / 0.6) * dt;
  const yawDeg = deg(yawRad);

  const battery = clamp(num(o.battery, mem.prevBattery), 0, 1.8);
  const solar = Math.max(0, num(o.solar, 0));
  const carried = Math.max(0, Math.floor(num(o.carried, 0)));
  const carriedValue = num(o.carriedValue, mem.prevCarriedValue);
  const delivered = num(o.delivered, mem.prevDelivered);
  const timeLeft = Math.max(0, num(o.timeLeft, mem.seconds - tNow));
  const drillProgress = Math.max(0, num(o.drilling, 0));
  const science = Math.max(0, num(o.science, 0));
  const siteObs = o.site && typeof o.site === "object" ? o.site : null;
  const beacon = o.beacon && typeof o.beacon === "object" ? o.beacon : null;

  const oldCarried = num(mem.prevCarried, carried);
  const oldCarriedValue = num(mem.prevCarriedValue, carriedValue);
  const oldDelivered = num(mem.prevDelivered, delivered);
  const sampleCompleted = carried > oldCarried;

  mem.scienceEma = num(mem.scienceEma, science) * 0.78 + science * 0.22;

  const prevTheta = num(mem.theta, rawH);
  const rawDeltaH = wrap(rawH - num(mem.prevRawH, rawH));
  const compassJump =
    Math.abs(wrap(rawDeltaH - yawDeg)) > 72 && Math.abs(yawDeg) < 48;
  if (compassJump) mem.compassHold = 1.5;
  else mem.compassHold = Math.max(0, num(mem.compassHold, 0) - dt);

  let theta = wrap(prevTheta + yawDeg);
  if (!compassJump && mem.compassHold <= 0) {
    const corrected = wrap(rawH - num(mem.headingBias, 0));
    const residual = wrap(corrected - theta);
    if (Math.abs(residual) < 85) {
      theta = wrap(theta + clamp(residual * 0.12, -2.0, 2.0));
    }
  }
  mem.theta = theta;

  const gpsDelta = dist(rawX, rawY, num(mem.lastGpsX, rawX), num(mem.lastGpsY, rawY));
  const gpsJump = gpsDelta > 10 && dt <= 0.55;
  if (gpsDelta < 0.025 && wheelTravel > 0.025) {
    mem.gpsUnchanged = num(mem.gpsUnchanged, 0) + dt;
    mem.gpsTravelSinceChange = num(mem.gpsTravelSinceChange, 0) + wheelTravel;
  } else if (gpsDelta > 0.08) {
    mem.gpsUnchanged = 0;
    mem.gpsTravelSinceChange = 0;
  }

  const wasFrozen = !!mem.gpsFrozen;
  mem.gpsFrozen =
    num(mem.gpsUnchanged, 0) > 2.5 &&
    num(mem.gpsTravelSinceChange, 0) > 1.5;
  if (wasFrozen && !mem.gpsFrozen) mem.gpsRecover = 1.2;
  else mem.gpsRecover = Math.max(0, num(mem.gpsRecover, 0) - dt);

  const midTheta = rad(wrap((prevTheta + theta) * 0.5));
  let px = num(mem.px, rawX) + vWheel * dt * Math.cos(midTheta);
  let py = num(mem.py, rawY) + vWheel * dt * Math.sin(midTheta);
  if (!mem.gpsFrozen && !gpsJump) {
    const dx = rawX - px;
    const dy = rawY - py;
    const residual = Math.hypot(dx, dy);
    if (residual < 20) {
      let alpha = Math.abs(vWheel) > 0.20 ? 0.36 : 0.25;
      if (mem.gpsRecover > 0) alpha = 0.50;
      const limit = mem.gpsRecover > 0 ? 3 : 2;
      const scale = residual > limit ? limit / residual : 1;
      px += dx * scale * alpha;
      py += dy * scale * alpha;
    }
  }
  mem.px = px;
  mem.py = py;
  mem.lastGpsX = rawX;
  mem.lastGpsY = rawY;
  mem.prevRawH = rawH;

  if (!mem.cal || typeof mem.cal !== "object") {
    mem.cal = { active: false, x: rawX, y: rawY, sin: 0, cos: 0, n: 0 };
  }
  const straight =
    vWheel > 0.32 &&
    Math.abs(wr - wl) < 0.22 &&
    !mem.gpsFrozen &&
    !gpsJump &&
    !compassJump;
  if (straight) {
    if (!mem.cal.active) {
      mem.cal.active = true;
      mem.cal.x = rawX;
      mem.cal.y = rawY;
      mem.cal.sin = 0;
      mem.cal.cos = 0;
      mem.cal.n = 0;
    }
    mem.cal.sin += Math.sin(rad(rawH));
    mem.cal.cos += Math.cos(rad(rawH));
    mem.cal.n += 1;
    if (dist(rawX, rawY, mem.cal.x, mem.cal.y) >= 8 && mem.cal.n >= 12) {
      const course = deg(Math.atan2(rawY - mem.cal.y, rawX - mem.cal.x));
      const meanRaw = deg(Math.atan2(mem.cal.sin, mem.cal.cos));
      const estimate = wrap(meanRaw - course);
      const err = wrap(estimate - num(mem.headingBias, 0));
      if (Math.abs(err) < 60) {
        mem.headingBias = wrap(num(mem.headingBias, 0) + clamp(err * 0.14, -2, 2));
      }
      mem.cal.x = rawX;
      mem.cal.y = rawY;
      mem.cal.sin = 0;
      mem.cal.cos = 0;
      mem.cal.n = 0;
    }
  } else if (mem.cal) {
    mem.cal.active = false;
    mem.cal.sin = 0;
    mem.cal.cos = 0;
    mem.cal.n = 0;
  }

  if (!Array.isArray(mem.gain) || mem.gain.length < 2) {
    mem.gain = [[3.2, 3.2], [3.2, 3.2]];
  }
  if (!Array.isArray(mem.dead) || mem.dead.length < 2) {
    mem.dead = [[0.20, 0.20], [0.20, 0.20]];
  }
  if (!Array.isArray(mem.lastCmd) || mem.lastCmd.length < 2) mem.lastCmd = [0, 0];
  if (!Array.isArray(mem.lastTarget) || mem.lastTarget.length < 2) mem.lastTarget = [0, 0];
  if (!Array.isArray(mem.noResponse) || mem.noResponse.length < 2) mem.noResponse = [0, 0];

  for (let s = 0; s < 2; s++) {
    if (!Array.isArray(mem.gain[s])) mem.gain[s] = [3.2, 3.2];
    if (!Array.isArray(mem.dead[s])) mem.dead[s] = [0.20, 0.20];
    const cmd = num(mem.lastCmd[s], 0);
    const target = num(mem.lastTarget[s], 0);
    const actual = s === 0 ? wl : wr;
    const direction = target < 0 ? 1 : 0;
    const dead = clamp(num(mem.dead[s][direction], 0.20), 0.10, 0.42);

    if (Math.abs(cmd) > dead + 0.10 &&
        Math.abs(actual) > 0.10 &&
        actual * cmd > 0 &&
        target * actual > 0) {
      const ratio = Math.abs(actual / cmd);
      if (ratio > 0.45 && ratio < 5.8) {
        const old = num(mem.gain[s][direction], 3.2);
        mem.gain[s][direction] = clamp(old + (ratio - old) * 0.018, 0.8, 5.8);
      }
    }

    if (Math.abs(target) > 0.20 &&
        Math.abs(cmd) > dead + 0.04 &&
        Math.abs(actual) < 0.07 &&
        !o.bumped) {
      mem.noResponse[s] = num(mem.noResponse[s], 0) + dt;
      if (mem.noResponse[s] > 0.8) {
        mem.dead[s][direction] = clamp(
          num(mem.dead[s][direction], 0.20) + 0.008, 0.12, 0.42
        );
      }
    } else {
      mem.noResponse[s] = 0;
      if (Math.abs(actual) > 0.22 && Math.abs(target) > 0.15) {
        mem.dead[s][direction] = Math.max(
          0.12, num(mem.dead[s][direction], 0.20) - 0.0004
        );
      }
    }
  }

  const oldBattery = num(mem.prevBattery, battery);
  if (!o.docked && (wheelTravel > 0.014 || drillProgress > 0.05)) {
    const use = clamp(oldBattery - battery + solar * dt * 0.35, 0, 0.02);
    mem.energyUse = num(mem.energyUse, 0) + use;
    mem.energyDist = num(mem.energyDist, 0) +
      Math.max(wheelTravel, drillProgress > 0.05 ? dt * 0.10 : 0);
    if (mem.energyDist >= 18) {
      const load = 1 + 0.16 * carried;
      const measured = clamp(
        mem.energyUse / Math.max(6, mem.energyDist) / load,
        0.00025, 0.008
      );
      const old = num(mem.energyRate, 0.00065);
      const a = measured > old ? 0.25 : 0.07;
      mem.energyRate = clamp(old + (measured - old) * a, 0.00025, 0.008);
      mem.energyUse = 0;
      mem.energyDist = 0;
    }
  }

  const rawRays = o.rays && typeof o.rays.length === "number" ? o.rays : null;
  if (!Array.isArray(mem.rFilt) || mem.rFilt.length !== 9) {
    mem.rFilt = [];
    for (let i = 0; i < 9; i++) mem.rFilt[i] = 15;
  }
  let allMax = true;
  for (let i = 0; i < 9; i++) {
    const r = clamp(rawRays ? num(rawRays[i], 15) : 15, 0, 15);
    if (r < 14.8) allMax = false;
    let f = num(mem.rFilt[i], 15);
    const a = r < f ? 0.68 : 0.32;
    f += (r - f) * a;
    mem.rFilt[i] = clamp(f, 0, 15);
  }
  if (allMax && wheelTravel > 0.02) mem.rangeTravel += wheelTravel;
  else if (!allMax) mem.rangeTravel = Math.max(0, num(mem.rangeTravel, 0) - wheelTravel);
  mem.rangeTrust = mem.rangeTravel > 25 ? 0.88 : 1;

  if (beacon) {
    const bd = Math.max(0, num(beacon.distance, 99));
    const bb = num(beacon.bearing, 0);
    const pb = mem.prevBeacon;
    if (pb && wheelTravel > 0.02 &&
        Math.abs(bd - num(pb.d, bd)) < 0.015 &&
        Math.abs(wrap(bb - num(pb.b, bb))) < 0.20) {
      mem.beaconSameTime = num(mem.beaconSameTime, 0) + dt;
      mem.beaconSameMotion = num(mem.beaconSameMotion, 0) + wheelTravel;
      if (mem.beaconSameTime > 6 && mem.beaconSameMotion > 2.5) {
        mem.beaconBad = true;
      }
    } else if (!pb ||
               Math.abs(bd - num(pb.d, bd)) > 0.08 ||
               Math.abs(wrap(bb - num(pb.b, bb))) > 1) {
      mem.beaconSameTime = 0;
      mem.beaconSameMotion = 0;
      mem.beaconBad = false;
    }
    mem.prevBeacon = { d: bd, b: bb };
  } else {
    mem.prevBeacon = null;
    mem.beaconSameTime = 0;
    mem.beaconSameMotion = 0;
  }

  if (sampleCompleted) {
    const meta = mem.pendingMeta || mem.siteLock || { x: mem.px, y: mem.py, value: 1 };
    const mx = num(meta.x, mem.px);
    const my = num(meta.y, mem.py);
    let value = Math.max(0.1, num(meta.value, 1));
    const valueGain = carriedValue - oldCarriedValue;
    if (valueGain > 0.01) value = valueGain / Math.max(1, carried - oldCarried);
    mem.samples.push({ x: mx, y: my, value: value });

    let nearest = -1;
    let nearestD = 36;
    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (!h || h.status >= 2) continue;
      const d = dist(mx, my, h.x, h.y);
      if (d < nearestD) {
        nearestD = d;
        nearest = i;
      }
    }
    const ci = Math.floor(num(mem.currentHint, -1));
    if (ci >= 0 && ci < mem.hints.length &&
        mem.hints[ci].status < 2 &&
        dist(mx, my, mem.hints[ci].x, mem.hints[ci].y) < 40) {
      nearest = ci;
    }
    if (nearest >= 0) {
      mem.hints[nearest].status = 2;
      if (nearest === ci) mem.currentHint = -1;
    }
    for (let i = 0; i < mem.globalPoints.length; i++) {
      const p = mem.globalPoints[i];
      if (p && dist(mx, my, p.x, p.y) < 12) p.done = true;
    }
    if (mem.ambient && dist(mx, my, mem.ambient.x, mem.ambient.y) < 30) {
      mem.ambient = null;
    }

    mem.sampleActive = false;
    mem.pendingMeta = null;
    mem.siteLock = null;
    mem.holdReady = false;
    mem.stillTime = 0;
    mem.navKey = "";
  } else if (carried < oldCarried || delivered > oldDelivered) {
    mem.sampleActive = false;
    mem.pendingMeta = null;
    mem.siteLock = null;
    mem.holdReady = false;
    mem.stillTime = 0;
  }

  const poseX = num(mem.px, rawX);
  const poseY = num(mem.py, rawY);

  if (siteObs && carried < mem.capacity) {
    const sd = Math.max(0, num(siteObs.distance, 99));
    const sb = num(siteObs.bearing, 0);
    const a = rad(mem.theta + sb);
    const sx = poseX + sd * Math.cos(a);
    const sy = poseY + sd * Math.sin(a);
    const sv = Math.max(0.1, num(siteObs.value, 1));
    if (!mem.siteLock) {
      mem.siteLock = { x: sx, y: sy, value: sv, lastSeen: tNow };
    } else {
      const gap = dist(mem.siteLock.x, mem.siteLock.y, sx, sy);
      if (gap > 10) {
        mem.siteLock.x = sx;
        mem.siteLock.y = sy;
      } else {
        mem.siteLock.x = mem.siteLock.x * 0.70 + sx * 0.30;
        mem.siteLock.y = mem.siteLock.y * 0.70 + sy * 0.30;
      }
      mem.siteLock.value = sv;
      mem.siteLock.lastSeen = tNow;
    }
  } else if (mem.siteLock && !mem.sampleActive &&
             tNow - num(mem.siteLock.lastSeen, tNow) > 14) {
    mem.siteLock = null;
  }

  if (!sampleCompleted && !mem.sampleActive && drillProgress > 0.05) {
    mem.sampleActive = true;
    mem.sampleStart = tNow - drillProgress;
    if (!mem.holdReady) {
      mem.holdX = poseX;
      mem.holdY = poseY;
      mem.holdHeading = mem.theta;
      mem.holdReady = true;
    }
    if (mem.siteLock) {
      mem.pendingMeta = {
        x: mem.siteLock.x,
        y: mem.siteLock.y,
        value: mem.siteLock.value
      };
    }
  }

  const baseX = num(mem.baseX, width * 0.5);
  const baseY = num(mem.baseY, height * 0.5);
  const baseDist = dist(poseX, poseY, baseX, baseY);
  const beaconDist = beacon ? Math.max(0, num(beacon.distance, 99)) : 99;
  const beaconUsable = !!beacon && !mem.beaconBad && beaconDist <= 20.5;
  const maxWheel = Math.max(Math.abs(wl), Math.abs(wr));
  const atBase = !!o.docked ||
    (beaconUsable && beaconDist <= 2.8) ||
    (baseDist <= 2.4 && maxWheel < 0.24);
  const homeDist = beaconUsable ? beaconDist : baseDist;

  function homeNeed(d, load) {
    const l = Math.max(0, load);
    return 0.09 +
      Math.max(0, d + 16) * num(mem.energyRate, 0.00065) * (1 + 0.18 * l) +
      0.018 * l;
  }

  function homeSeconds(d, load) {
    return Math.max(0, d) * 1.9 + 42 + 6 * Math.max(0, load);
  }

  function routeFeasible(out, home, extra, load) {
    const l = Math.max(0, load);
    const metres = Math.max(0, out) + Math.max(0, home) +
      Math.max(0, extra) + 16;
    const need = 0.09 +
      metres * num(mem.energyRate, 0.00065) * (1 + 0.18 * l) +
      0.018 * l;
    const seconds = metres * 1.9 + 44 + 6 * l;
    return need <= battery - 0.025 && seconds <= timeLeft - 8;
  }

  function motorPower(target, actual, side, hold) {
    const direction = target < -0.015 ? 1 : 0;
    const gain = clamp(num(mem.gain[side][direction], 3.2), 0.8, 5.8);
    const dead = clamp(num(mem.dead[side][direction], 0.20), 0.10, 0.42);

    if (Math.abs(target) < 0.025) {
      if (Math.abs(actual) < 0.045) return 0;
      if (Math.abs(actual) < 0.12) return -actual * 0.55;
      const brake = clamp(dead + Math.abs(actual) / gain * 0.50, dead, 0.55);
      return clamp(-Math.sign(actual) * brake, -1, 1);
    }

    let u = Math.sign(target) * (dead + Math.abs(target) / gain) +
      (hold ? 0.12 : 0.07) * (target - actual);

    const overspeed = actual * target > 0 &&
      Math.abs(actual) > Math.abs(target) + 0.16;
    if (overspeed || Math.abs(actual) > 1.05) {
      const amount = Math.max(0, Math.abs(actual) - Math.abs(target));
      u = -Math.sign(actual) * clamp(dead + amount / gain * 0.55, dead, 0.58);
    } else if (Math.abs(target) > 0.08 &&
               u * target > 0 &&
               Math.abs(u) < dead + 0.025) {
      u = Math.sign(target) * (dead + 0.025);
    }
    return clamp(u, -1, 1);
  }

  function wheelCommands(v, omega, hold) {
    const lt = clamp(v - 0.3 * omega, -0.72, 0.72);
    const rt = clamp(v + 0.3 * omega, -0.72, 0.72);
    return {
      left: motorPower(lt, wl, 0, !!hold),
      right: motorPower(rt, wr, 1, !!hold),
      tl: lt,
      tr: rt
    };
  }

  function stopCommands() {
    return wheelCommands(0, 0, false);
  }

  function holdCommands() {
    if (!mem.holdReady) {
      mem.holdX = poseX;
      mem.holdY = poseY;
      mem.holdHeading = mem.theta;
      mem.holdReady = true;
    }

    const a = rad(mem.theta);
    const dx = num(mem.holdX, poseX) - poseX;
    const dy = num(mem.holdY, poseY) - poseY;
    const along = dx * Math.cos(a) + dy * Math.sin(a);
    const cross = -dx * Math.sin(a) + dy * Math.cos(a);
    const avg = (wl + wr) * 0.5;
    let position = 0;
    if (Math.abs(along) > 0.45) position = clamp(along * 0.16, -0.08, 0.08);
    const v = clamp(position - 0.45 * avg, -0.11, 0.11);
    const headingErr = wrap(num(mem.holdHeading, mem.theta) - mem.theta);
    const omega = clamp(0.75 * rad(headingErr) +
      clamp(cross * 0.025, -0.04, 0.04), -0.13, 0.13);
    const c = wheelCommands(v, omega, true);
    const feed = clamp(num(o.pitch, 0) * 0.006, -0.10, 0.10);
    c.left = clamp(c.left + feed, -1, 1);
    c.right = clamp(c.right + feed, -1, 1);
    return c;
  }

  function emit(c, drill) {
    const left = clamp(num(c && c.left, 0), -1, 1);
    const right = clamp(num(c && c.right, 0), -1, 1);
    mem.lastCmd = [left, right];
    mem.lastTarget = [num(c && c.tl, 0), num(c && c.tr, 0)];
    mem.prevT = tNow;
    mem.prevBattery = battery;
    mem.prevCarried = carried;
    mem.prevCarriedValue = carriedValue;
    mem.prevDelivered = delivered;
    return { left: left, right: right, drill: !!drill };
  }

  function rayAt(angle) {
    const a = clamp(angle, -80, 80);
    const q = (a + 80) / 20;
    const i = Math.floor(q);
    const f = q - i;
    if (i >= 8) return num(mem.rFilt[8], 15);
    return num(mem.rFilt[i], 15) * (1 - f) + num(mem.rFilt[i + 1], 15) * f;
  }

  function clearanceAt(angle) {
    const center = rayAt(angle);
    const side = Math.min(rayAt(angle - 20), rayAt(angle + 20));
    return Math.min(center, center * 0.76 + side * 0.24);
  }

  function edgeDistance(angle) {
    const a = rad(wrap(mem.theta + angle));
    const dx = Math.cos(a);
    const dy = Math.sin(a);
    const margin = 6;
    let d = 1e6;
    if (dx > 0.001) d = Math.min(d, (width - margin - poseX) / dx);
    if (dx < -0.001) d = Math.min(d, (margin - poseX) / dx);
    if (dy > 0.001) d = Math.min(d, (height - margin - poseY) / dy);
    if (dy < -0.001) d = Math.min(d, (margin - poseY) / dy);
    return Math.max(0, d);
  }

  function navCommands(goalError, maxV) {
    const goal = wrap(num(goalError, 0));
    let vmax = clamp(num(maxV, 0.55), 0, 0.64);
    if (mem.rangeTrust < 0.9) vmax = Math.min(vmax, 0.55);
    if (maxWheel > 0.85) vmax = Math.min(vmax, 0.28);

    if (Math.abs(goal) > 112) {
      return wheelCommands(0, Math.sign(goal) * 0.68, false);
    }

    const clipped = clamp(goal, -80, 80);
    const candidates = [-80, -60, -40, -20, 0, 20, 40, 60, 80, clipped,
      clamp(goal * 0.65, -80, 80)];
    const safe = 2.25 + vmax * 0.75;
    const front = clearanceAt(0);
    let best = clipped;
    let bestClear = clearanceAt(clipped);
    let bestCost = 1e9;

    for (let i = 0; i < candidates.length; i++) {
      const a = candidates[i];
      const clear = clearanceAt(a);
      let cost = Math.abs(wrap(a - clipped)) * 0.032;
      const hazard = Math.max(0, safe - clear);
      cost += hazard * hazard * 2.1;
      if (clear < 1.25) cost += 9;
      if (clear < 0.75) cost += 18;

      const edge = edgeDistance(a);
      if (edge < 2.5) cost += 18;
      else if (edge < 8) cost += (8 - edge) * 0.75;

      if (front < safe && Math.abs(a) > 12 && mem.avoidSign &&
          Math.sign(a) !== Math.sign(mem.avoidSign)) {
        cost += 0.18;
      }
      if (front < safe) {
        cost += Math.abs(a - num(mem.lastAim, a)) * 0.003;
      }

      if (cost < bestCost) {
        bestCost = cost;
        best = a;
        bestClear = clear;
      }
    }

    if (front > safe + 1.2) mem.avoidSign = 0;
    else if (Math.abs(best) > 10) mem.avoidSign = Math.sign(best);
    mem.lastAim = best;

    if (Math.abs(best) > 56) {
      return wheelCommands(0, Math.sign(best) * 0.62, false);
    }

    let v = vmax * clamp(Math.cos(rad(best)), 0.35, 1);
    v *= clamp((bestClear - 0.75) / Math.max(1.0, safe - 0.75), 0.15, 1);
    if (bestClear < 1.2) v = Math.min(v, 0.12);
    if (front < 1.05 && Math.abs(best) < 18) v = Math.min(v, 0.10);
    const omega = clamp(1.45 * rad(best), -0.82, 0.82);
    return wheelCommands(v, omega, false);
  }

  function openSide() {
    let left = 0, right = 0;
    for (let i = 5; i < 9; i++) left += num(mem.rFilt[i], 15);
    for (let i = 0; i < 4; i++) right += num(mem.rFilt[i], 15);
    if (Math.abs(left - right) < 0.5) return mem.avoidSign ? -mem.avoidSign : 1;
    return left >= right ? 1 : -1;
  }

  function recoveryAction() {
    const rem = Math.max(0, num(mem.recoverTimer, 0));
    const s = num(mem.recoverSign, 1);
    let c;
    if (rem > 0.52) c = wheelCommands(-0.18, s * 0.48, false);
    else c = wheelCommands(0, s * 0.62, false);
    mem.recoverTimer = Math.max(0, rem - dt);
    return emit(c, false);
  }

  function ringPoint(cx, cy, step, count, radius, offset) {
    const a = num(offset, 0) + 2 * Math.PI * step / count;
    return {
      x: clamp(cx + radius * Math.cos(a), 4, width - 4),
      y: clamp(cy + radius * Math.sin(a), 4, height - 4)
    };
  }

  function searchRemaining(h) {
    const phase = Math.floor(num(h.phase, 0));
    const step = Math.max(0, Math.floor(num(h.step, 0)));
    if (phase === 0) return 65;
    if (phase === 1) {
      const outer = num(h.bestScience, 0) > 0.10 ? 100 : 34;
      return Math.max(0, 8 - step) * (2 * Math.PI * 8 / 8) + outer;
    }
    if (phase === 2) return Math.max(0, 12 - step) * (2 * Math.PI * 16 / 12);
    return Math.max(0, 6 - step) * (2 * Math.PI * 6 / 6);
  }

  function hintInfo(index) {
    const h = mem.hints[index];
    if (!h || h.status >= 2) return null;

    if (dist(poseX, poseY, h.x, h.y) < 45 &&
        science > num(h.bestScience, 0) + 0.02) {
      h.bestScience = science;
      h.bestX = poseX;
      h.bestY = poseY;
    }

    for (let tries = 0; tries < 8; tries++) {
      const phase = Math.floor(num(h.phase, 0));
      const step = Math.max(0, Math.floor(num(h.step, 0)));

      if (phase === 0) {
        const d = dist(poseX, poseY, h.x, h.y);
        if (d <= 3.8) {
          h.phase = 1;
          h.step = 0;
          h.startScience = num(mem.scienceEma, science);
          h.bestScience = Math.max(num(h.bestScience, 0), science);
          h.bestX = poseX;
          h.bestY = poseY;
          continue;
        }
        return {
          kind: "hint", index: index, phase: 0, step: 0,
          x: h.x, y: h.y, dist: d,
          home: dist(h.x, h.y, baseX, baseY) + 16,
          extra: 65, key: "hc:" + index
        };
      }

      if (phase === 1) {
        if (step >= 8) {
          if (num(h.bestScience, 0) > 0.10 ||
              num(h.startScience, 0) > 0.10) {
            h.phase = 2;
            h.step = 0;
          } else {
            h.status = 2;
            if (Math.floor(num(mem.currentHint, -1)) === index) mem.currentHint = -1;
            return null;
          }
          continue;
        }
        const p = ringPoint(h.x, h.y, step, 8, 8, h.angle);
        const d = dist(poseX, poseY, p.x, p.y);
        if (d <= 2.8) {
          h.step++;
          continue;
        }
        return {
          kind: "hint", index: index, phase: 1, step: step,
          x: p.x, y: p.y, dist: d,
          home: dist(h.x, h.y, baseX, baseY) + 16,
          extra: Math.max(0, 7 - step) * (2 * Math.PI * 8 / 8) +
            (num(h.bestScience, 0) > 0.10 ? 100 : 34),
          key: "hr:" + index + ":1:" + step
        };
      }

      if (phase === 2) {
        if (step >= 12) {
          if (!h.retry &&
              num(h.bestScience, 0) > num(h.startScience, 0) + 0.18 &&
              num(h.bestScience, 0) > 0.25 &&
              dist(h.bestX, h.bestY, h.x, h.y) > 3.2) {
            h.x = clamp(num(h.bestX, h.x), 4, width - 4);
            h.y = clamp(num(h.bestY, h.y), 4, height - 4);
            h.phase = 3;
            h.step = 0;
            h.retry = 1;
            h.startScience = num(h.bestScience, science);
            h.bestScience = num(h.startScience, science);
            h.bestX = poseX;
            h.bestY = poseY;
            continue;
          }
          h.status = 2;
          if (Math.floor(num(mem.currentHint, -1)) === index) mem.currentHint = -1;
          return null;
        }
        const p = ringPoint(h.x, h.y, step, 12, 16, h.angle);
        const d = dist(poseX, poseY, p.x, p.y);
        if (d <= 2.8) {
          h.step++;
          continue;
        }
        return {
          kind: "hint", index: index, phase: 2, step: step,
          x: p.x, y: p.y, dist: d,
          home: dist(h.x, h.y, baseX, baseY) + 18,
          extra: Math.max(0, 11 - step) * (2 * Math.PI * 16 / 12),
          key: "hr:" + index + ":2:" + step
        };
      }

      if (phase === 3) {
        if (step >= 6) {
          h.status = 2;
          if (Math.floor(num(mem.currentHint, -1)) === index) mem.currentHint = -1;
          return null;
        }
        const p = ringPoint(h.x, h.y, step, 6, 6, h.angle);
        const d = dist(poseX, poseY, p.x, p.y);
        if (d <= 2.8) {
          h.step++;
          continue;
        }
        return {
          kind: "hint", index: index, phase: 3, step: step,
          x: p.x, y: p.y, dist: d,
          home: dist(h.x, h.y, baseX, baseY) + 8,
          extra: Math.max(0, 5 - step) * (2 * Math.PI * 6 / 6),
          key: "hr:" + index + ":3:" + step
        };
      }

      h.status = 2;
      return null;
    }
    return null;
  }

  function skipTarget(info) {
    if (!info) return;
    if (info.kind === "hint" &&
        info.index >= 0 && info.index < mem.hints.length) {
      const h = mem.hints[info.index];
      if (!h) return;
      if (info.phase === 0) {
        h.phase = 1;
        h.step = 0;
      } else {
        h.step = Math.max(0, Math.floor(num(h.step, 0))) + 1;
      }
    } else if (info.kind === "ambient" && mem.ambient) {
      mem.ambient.step = Math.max(0, Math.floor(num(mem.ambient.step, 0))) + 1;
    } else if (info.kind === "global" &&
               info.index >= 0 && info.index < mem.globalPoints.length) {
      mem.globalPoints[info.index].done = true;
      mem.globalIndex = -1;
    } else if (info.kind === "site") {
      mem.siteIgnoreUntil = tNow + 10;
      mem.siteLock = null;
    }
  }

  function updateProgress(key, d, info) {
    if (mem.navKey !== key) {
      mem.navKey = key;
      mem.navBest = d;
      mem.navStuck = 0;
      mem.stuckCount = 0;
      return false;
    }
    if (d < num(mem.navBest, d) - 0.50) {
      mem.navBest = d;
      mem.navStuck = 0;
      mem.stuckCount = 0;
      return false;
    }

    mem.navStuck = num(mem.navStuck, 0) + dt;
    if (mem.navStuck > 22) {
      mem.navStuck = 0;
      mem.navBest = d;
      mem.stuckCount = num(mem.stuckCount, 0) + 1;
      mem.recoverSign = mem.avoidSign ? -mem.avoidSign : openSide();
      mem.avoidSign = mem.recoverSign;
      mem.recoverTimer = 1.15;
      if (mem.stuckCount >= 3) {
        skipTarget(info);
        mem.navKey = "";
        mem.stuckCount = 0;
      }
      return true;
    }
    return false;
  }

  function makeAmbientInfo() {
    const a = mem.ambient;
    if (!a) return null;
    if (science > num(a.bestScience, 0) + 0.03) {
      a.bestScience = science;
      a.bestX = poseX;
      a.bestY = poseY;
    }

    for (let tries = 0; tries < 8; tries++) {
      if (a.phase === 0 && a.step >= 8) {
        if (num(a.bestScience, 0) > num(a.startScience, 0) + 0.10 ||
            num(a.startScience, 0) > 0.60) {
          a.phase = 1;
          a.step = 0;
          continue;
        }
        mem.ambientLastX = a.x;
        mem.ambientLastY = a.y;
        mem.ambient = null;
        return null;
      }
      if (a.phase === 1 && a.step >= 12) {
        mem.ambientLastX = a.x;
        mem.ambientLastY = a.y;
        mem.ambient = null;
        return null;
      }

      const count = a.phase === 0 ? 8 : 12;
      const radius = a.phase === 0 ? 10 : 20;
      const step = Math.max(0, Math.floor(num(a.step, 0)));
      const p = ringPoint(a.x, a.y, step, count, radius, 0);
      const d = dist(poseX, poseY, p.x, p.y);
      if (d <= 2.8) {
        a.step++;
        continue;
      }
      const arc = 2 * Math.PI * radius / count;
      const extra = Math.max(0, count - step - 1) * arc;
      return {
        kind: "ambient", index: step, x: p.x, y: p.y, dist: d,
        home: dist(a.x, a.y, baseX, baseY) + radius,
        extra: extra, key: "a:" + a.phase + ":" + step
      };
    }
    return null;
  }

  function chooseHint() {
    let best = -1;
    let bestScore = -1;
    let bestInfo = null;
    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (!h || h.status >= 2) continue;
      const info = hintInfo(i);
      if (!info || !routeFeasible(info.dist, info.home, info.extra, carried + 1)) continue;
      let score = Math.pow(Math.max(0.1, h.value), 1.12) /
        (68 + info.dist + 0.78 * info.home + 0.52 * info.extra + 8 * carried);
      if (h.status === 1) score *= 1.08;
      if (i === Math.floor(num(mem.currentHint, -1))) score *= 1.12;
      if (score > bestScore) {
        bestScore = score;
        best = i;
        bestInfo = info;
      }
    }
    if (best >= 0) {
      mem.currentHint = best;
      mem.hints[best].status = 1;
      return bestInfo;
    }
    return null;
  }

  function chooseGlobal() {
    let old = Math.floor(num(mem.globalIndex, -1));
    if (old >= 0 && old < mem.globalPoints.length) {
      const p = mem.globalPoints[old];
      if (p && !p.done) {
        const d = dist(poseX, poseY, p.x, p.y);
        if (d <= 3.8) {
          p.done = true;
          mem.globalIndex = -1;
        } else if (routeFeasible(d, dist(p.x, p.y, baseX, baseY) + 4, 0, carried + 1)) {
          return {
            kind: "global", index: old, x: p.x, y: p.y, dist: d,
            home: dist(p.x, p.y, baseX, baseY) + 4,
            extra: 0, key: "g:" + old
          };
        } else {
          mem.globalIndex = -1;
        }
      } else {
        mem.globalIndex = -1;
      }
    }

    let best = -1;
    let bestScore = -1;
    let bestInfo = null;
    for (let i = 0; i < mem.globalPoints.length; i++) {
      const p = mem.globalPoints[i];
      if (!p || p.done) continue;
      const d = dist(poseX, poseY, p.x, p.y);
      const home = dist(p.x, p.y, baseX, baseY) + 4;
      if (d <= 3.8) {
        p.done = true;
        continue;
      }
      if (!routeFeasible(d, home, 0, carried + 1)) continue;
      const score = 1 / (38 + d + 0.56 * home + 7 * carried);
      if (score > bestScore) {
        bestScore = score;
        best = i;
        bestInfo = {
          kind: "global", index: i, x: p.x, y: p.y, dist: d,
          home: home, extra: 0, key: "g:" + i
        };
      }
    }
    mem.globalIndex = best;
    return bestInfo;
  }

  function getTask() {
    let ci = Math.floor(num(mem.currentHint, -1));
    if (ci >= 0 && ci < mem.hints.length &&
        mem.hints[ci] && mem.hints[ci].status < 2) {
      const info = hintInfo(ci);
      if (info && routeFeasible(info.dist, info.home, info.extra, carried + 1)) {
        return info;
      }
      mem.currentHint = -1;
    }

    const hi = chooseHint();
    if (hi) return hi;

    if (!mem.ambient && science > 0.65 &&
        dist(poseX, poseY,
          num(mem.ambientLastX, -1e9),
          num(mem.ambientLastY, -1e9)) > 26) {
      mem.ambient = {
        x: poseX,
        y: poseY,
        phase: 0,
        step: 0,
        startScience: num(mem.scienceEma, science),
        bestScience: science,
        bestX: poseX,
        bestY: poseY
      };
    }

    if (mem.ambient) {
      const ai = makeAmbientInfo();
      if (ai && routeFeasible(ai.dist, ai.home, ai.extra, carried + 1)) return ai;
    }
    return chooseGlobal();
  }

  function goHome() {
    if (atBase) return emit(stopCommands(), false);
    const err = beaconUsable
      ? num(beacon.bearing, 0)
      : wrap(deg(Math.atan2(baseY - poseY, baseX - poseX)) - mem.theta);

    if (updateProgress("home", homeDist, { kind: "home" })) {
      return recoveryAction();
    }

    let speed = homeDist > 28 ? 0.60 : (homeDist > 8 ? 0.46 : 0.30);
    if (timeLeft < homeSeconds(homeDist, carried) + 18) speed = 0.64;
    return emit(navCommands(err, speed), false);
  }

  if (delivered > oldDelivered && carried === 0) mem.returning = false;
  if (mem.returning && atBase && carried === 0) {
    mem.returning = false;
    mem.sampleActive = false;
    mem.holdReady = false;
    mem.stillTime = 0;
  }
  if (!mem.returning && !mem.sampleActive) {
    if (carried >= mem.capacity) {
      mem.returning = true;
    } else if (!atBase &&
               battery < homeNeed(homeDist, carried) +
                 (carried > 0 ? 0.09 : 0.14)) {
      mem.returning = true;
    } else if (!atBase && timeLeft < homeSeconds(homeDist, carried) + 24) {
      mem.returning = true;
    }
  }

  if (o.bumped && !mem.prevBumped && !mem.sampleActive && !atBase) {
    mem.recoverSign = openSide();
    mem.recoverTimer = 1.05;
    mem.avoidSign = mem.recoverSign;
  }
  mem.prevBumped = !!o.bumped;

  if (mem.sampleActive) {
    const elapsed = tNow - num(mem.sampleStart, tNow);
    const sd = siteObs
      ? Math.max(0, num(siteObs.distance, 99))
      : (mem.siteLock
        ? dist(poseX, poseY, mem.siteLock.x, mem.siteLock.y)
        : 99);

    const timedOut = elapsed > 18 && drillProgress < 5.8 &&
      carried === oldCarried;
    const lostSite = siteObs && sd > 1.75 &&
      drillProgress < 0.20 && elapsed > 1.5;

    if (timedOut || lostSite) {
      mem.sampleActive = false;
      mem.pendingMeta = null;
      mem.holdReady = false;
      mem.stillTime = 0;
    } else {
      if (!mem.holdReady) {
        mem.holdX = poseX;
        mem.holdY = poseY;
        mem.holdHeading = mem.theta;
        mem.holdReady = true;
      }
      const c = holdCommands();
      const still = Math.max(Math.abs(wl), Math.abs(wr)) < 0.13;
      const inRange = sd <= 1.48;
      const drill = !!(still && inRange);
      if (drill && mem.siteLock) {
        mem.pendingMeta = {
          x: mem.siteLock.x,
          y: mem.siteLock.y,
          value: mem.siteLock.value
        };
      }
      return emit(c, drill);
    }
  }

  if (atBase && carried > 0) {
    return emit(stopCommands(), false);
  }

  if (mem.recoverTimer > 0 && !mem.sampleActive && !atBase) {
    return recoveryAction();
  }

  if (mem.returning && !atBase) return goHome();

  if (atBase && carried === 0 && maxWheel > 0.27) {
    return emit(stopCommands(), false);
  }

  if (siteObs && carried < mem.capacity &&
      !mem.returning && tNow >= num(mem.siteIgnoreUntil, 0)) {
    const sd = Math.max(0, num(siteObs.distance, 99));
    const sb = num(siteObs.bearing, 0);
    const ang = rad(mem.theta + sb);
    const sx = poseX + sd * Math.cos(ang);
    const sy = poseY + sd * Math.sin(ang);
    const home = dist(sx, sy, baseX, baseY);

    if (!routeFeasible(sd, home, 5, carried + 1)) {
      if (!atBase) {
        mem.returning = true;
        return goHome();
      }
    } else {
      if (sd <= 1.55) {
        if (!mem.holdReady) {
          mem.holdX = poseX;
          mem.holdY = poseY;
          mem.holdHeading = mem.theta;
          mem.holdReady = true;
        }
        const c = holdCommands();
        const still = Math.max(Math.abs(wl), Math.abs(wr)) < 0.13;
        if (still && sd <= 1.45) mem.stillTime = num(mem.stillTime, 0) + dt;
        else mem.stillTime = 0;

        let drill = false;
        if (mem.stillTime >= 0.35 && still && sd <= 1.45) {
          mem.sampleActive = true;
          mem.sampleStart = tNow;
          mem.pendingMeta = mem.siteLock
            ? { x: mem.siteLock.x, y: mem.siteLock.y, value: mem.siteLock.value }
            : { x: sx, y: sy, value: Math.max(0.1, num(siteObs.value, 1)) };
          drill = true;
        }
        return emit(c, drill);
      }

      mem.holdReady = false;
      mem.stillTime = 0;
      if (updateProgress("site", sd, { kind: "site" })) {
        return recoveryAction();
      }
      const speed = sd > 5 ? 0.48 : (sd > 2.3 ? 0.32 : 0.15);
      return emit(navCommands(sb, speed), false);
    }
  }

  if (atBase && carried === 0 && maxWheel < 0.27) {
    /* Staying docked here also gives a low battery time to recharge. */
  }

  const info = getTask();
  if (!info) {
    if (carried > 0 || !atBase) {
      mem.returning = true;
      return goHome();
    }
    return emit(stopCommands(), false);
  }

  if (!routeFeasible(info.dist, info.home, info.extra, carried + 1)) {
    if (carried > 0 || !atBase) {
      mem.returning = true;
      return goHome();
    }
    return emit(stopCommands(), false);
  }

  if (updateProgress(info.key, info.dist, info)) {
    return recoveryAction();
  }

  const bearing = deg(Math.atan2(info.y - poseY, info.x - poseX));
  const error = wrap(bearing - mem.theta);
  let speed;
  if (info.kind === "hint" && info.phase === 0) {
    speed = info.dist > 35 ? 0.58 : (info.dist > 10 ? 0.46 : 0.34);
  } else if (info.kind === "hint") {
    speed = info.dist > 8 ? 0.48 : (info.dist > 3.2 ? 0.37 : 0.27);
  } else if (info.kind === "ambient") {
    speed = info.dist > 8 ? 0.44 : 0.34;
  } else {
    speed = info.dist > 15 ? 0.55 : (info.dist > 5 ? 0.42 : 0.30);
  }

  return emit(navCommands(error, speed), false);
}

function act(obs, mem) {
  const o = obs || {};
  if (!mem || typeof mem !== "object") mem = {};

  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
  const num = (v, d) => {
    if (v === null || v === undefined) return d;
    const n = Number(v);
    return Number.isFinite(n) ? n : d;
  };
  const wrap = (a) => {
    a = (a + 180) % 360;
    if (a < 0) a += 360;
    return a - 180;
  };
  const rad = (d) => d * Math.PI / 180;
  const deg = (r) => r * 180 / Math.PI;
  const dist = (x1, y1, x2, y2) => Math.hypot(x2 - x1, y2 - y1);

  const tNow = num(o.t, 0);
  const rawH = wrap(num(o.heading, 0));

  if (!mem._init) {
    const m = o.mission && typeof o.mission === "object" ? o.mission : {};
    const sz = m.size;
    let width = 400;
    let height = 400;

    if (typeof sz === "number") {
      width = height = sz;
    } else if (Array.isArray(sz)) {
      width = num(sz[0], 400);
      height = num(sz[1], width);
    } else if (sz && typeof sz === "object") {
      width = num(sz.width, num(sz.w, num(sz.x, 400)));
      height = num(sz.height, num(sz.h, num(sz.y, width)));
    }

    width = Math.max(50, width);
    height = Math.max(50, height);

    const b = m.base && typeof m.base === "object"
      ? m.base
      : { x: width * 0.5, y: height * 0.5 };

    mem.width = width;
    mem.height = height;
    mem.baseX = num(b.x, width * 0.5);
    mem.baseY = num(b.y, height * 0.5);
    mem.seconds = num(m.seconds, 1200);
    mem.capacity = Math.max(1, Math.floor(num(m.capacity, 5)));

    mem.hints = [];
    const hints = Array.isArray(m.hints) ? m.hints : [];
    for (let i = 0; i < hints.length; i++) {
      const h = hints[i] || {};
      const hx = clamp(num(h.x, mem.baseX), 4, width - 4);
      const hy = clamp(num(h.y, mem.baseY), 4, height - 4);
      mem.hints.push({
        x: hx,
        y: hy,
        value: Math.max(0.1, num(h.estimate, num(h.value, 1))),
        status: 0,
        phase: 0,
        step: 0,
        angle: (i * 0.57) % (2 * Math.PI),
        centerScience: 0,
        phaseStartScience: 0,
        bestScience: 0,
        bestX: hx,
        bestY: hy,
        anchorX: hx,
        anchorY: hy,
        anchorScience: 0,
        localScience: 0,
        localX: hx,
        localY: hy,
        loops: 0,
        outerTried: 0
      });
    }

    mem.globalPoints = [];
    const nx = 9;
    const ny = 9;
    for (let iy = 0; iy < ny; iy++) {
      for (let ix = 0; ix < nx; ix++) {
        mem.globalPoints.push({
          x: 20 + (width - 40) * ix / (nx - 1),
          y: 20 + (height - 40) * iy / (ny - 1),
          done: false
        });
      }
    }

    const x0 = num(o.x, width * 0.5);
    const y0 = num(o.y, height * 0.5);
    const batt0 = clamp(num(o.battery, 1), 0, 1.8);

    mem.px = x0;
    mem.py = y0;
    mem.theta = rawH;
    mem.headingBias = 0;
    mem.prevRawH = rawH;
    mem.prevT = tNow;
    mem.lastGpsX = x0;
    mem.lastGpsY = y0;
    mem.gpsUnchanged = 0;
    mem.gpsTravelSinceChange = 0;
    mem.gpsFrozen = false;
    mem.gpsRecover = 0;
    mem.compassHold = 0;
    mem.cal = { active: false, x: x0, y: y0, sin: 0, cos: 0, n: 0 };

    mem.gain = [[2.8, 2.8], [2.8, 2.8]];
    mem.dead = [[0.18, 0.18], [0.18, 0.18]];
    mem.noResponse = [0, 0];
    mem.motorStable = [0, 0];
    mem.motorStableTarget = [0, 0];
    mem.motorStableCmd = [0, 0];
    mem.lastCmd = [0, 0];
    mem.lastTarget = [0, 0];

    mem.rFilt = [];
    mem.rRaw = [];
    mem.rSameTime = [];
    mem.rSameMotion = [];
    mem.rBad = [];
    for (let i = 0; i < 9; i++) {
      mem.rFilt[i] = 15;
      mem.rRaw[i] = 15;
      mem.rSameTime[i] = 0;
      mem.rSameMotion[i] = 0;
      mem.rBad[i] = false;
    }
    mem.allMaxTravel = 0;
    mem.rangeTrust = 1;

    mem.energyRate = 0.0015;
    mem.energyUse = 0;
    mem.energyDist = 0;
    mem.prevBattery = batt0;

    mem.currentHint = -1;
    mem.globalIndex = -1;
    mem.ambient = null;
    mem.ambientLastX = -1e9;
    mem.ambientLastY = -1e9;

    mem.siteLock = null;
    mem.pendingMeta = null;
    mem.sampleActive = false;
    mem.sampleStart = 0;
    mem.sampleFailures = 0;
    mem.stillTime = 0;
    mem.holdI = [0, 0];
    mem.lastDrillProgress = 0;
    mem.lastDrillProgressT = tNow;

    mem.returning = false;
    mem.navKey = "";
    mem.navBest = 1e9;
    mem.navStuck = 0;
    mem.stuckCount = 0;
    mem.lastAim = 0;
    mem.avoidSign = 0;
    mem.recoverTimer = 0;
    mem.recoverSign = 1;
    mem.prevBumped = false;
    mem.siteIgnoreUntil = 0;

    mem.prevCarried = Math.max(0, Math.floor(num(o.carried, 0)));
    mem.prevCarriedValue = num(o.carriedValue, 0);
    mem.prevDelivered = num(o.delivered, 0);
    mem.prevBeacon = null;
    mem.beaconSameTime = 0;
    mem.beaconSameMotion = 0;
    mem.beaconBad = false;
    mem.scienceEma = Math.max(0, num(o.science, 0));
    mem.samples = [];
    mem._init = true;
  }

  let dt = 0.1;
  if (Number.isFinite(mem.prevT)) {
    const d = tNow - mem.prevT;
    if (d > 0.02 && d <= 0.55) dt = d;
  }

  const width = num(mem.width, 400);
  const height = num(mem.height, 400);
  const rawX = num(o.x, num(mem.px, width * 0.5));
  const rawY = num(o.y, num(mem.py, height * 0.5));
  const wl = num(o.wheelLeft, 0);
  const wr = num(o.wheelRight, 0);
  const vWheel = (wl + wr) * 0.5;
  const wheelTravel = (Math.abs(wl) + Math.abs(wr)) * 0.5 * dt;
  const yawRad = ((wr - wl) / 0.6) * dt;
  const yawDeg = deg(yawRad);

  const battery = clamp(num(o.battery, mem.prevBattery), 0, 1.8);
  const solar = Math.max(0, num(o.solar, 0));
  const carried = Math.max(0, Math.floor(num(o.carried, 0)));
  const carriedValue = num(o.carriedValue, mem.prevCarriedValue);
  const delivered = num(o.delivered, mem.prevDelivered);
  const timeLeft = Math.max(0, num(o.timeLeft, mem.seconds - tNow));
  const drillProgress = Math.max(0, num(o.drilling, 0));
  const science = Math.max(0, num(o.science, 0));
  const siteObs = o.site && typeof o.site === "object" ? o.site : null;
  const beacon = o.beacon && typeof o.beacon === "object" ? o.beacon : null;

  const oldCarried = num(mem.prevCarried, carried);
  const oldCarriedValue = num(mem.prevCarriedValue, carriedValue);
  const oldDelivered = num(mem.prevDelivered, delivered);
  const sampleCompleted = carried > oldCarried;

  mem.scienceEma = num(mem.scienceEma, science) * 0.76 + science * 0.24;

  const rawRays = o.rays && typeof o.rays.length === "number" ? o.rays : null;
  let minRawRay = 15;
  if (rawRays) {
    for (let i = 0; i < 9; i++) {
      minRawRay = Math.min(minRawRay, clamp(num(rawRays[i], 15), 0, 15));
    }
  }

  const prevTheta = num(mem.theta, rawH);
  const rawDeltaH = wrap(rawH - num(mem.prevRawH, rawH));
  const compassJump =
    Math.abs(wrap(rawDeltaH - yawDeg)) > 72 && Math.abs(yawDeg) < 55;

  if (compassJump) mem.compassHold = 1.3;
  else mem.compassHold = Math.max(0, num(mem.compassHold, 0) - dt);

  let theta = wrap(prevTheta + yawDeg);
  if (!compassJump && mem.compassHold <= 0) {
    const corrected = wrap(rawH - num(mem.headingBias, 0));
    const residual = wrap(corrected - theta);
    if (Math.abs(residual) < 100) {
      theta = wrap(theta + clamp(residual * 0.06, -1.2, 1.2));
    }
  }
  mem.theta = theta;

  const gpsDelta = dist(
    rawX, rawY,
    num(mem.lastGpsX, rawX),
    num(mem.lastGpsY, rawY)
  );
  const gpsJump = gpsDelta > 12 && dt <= 0.55;

  if (gpsDelta < 0.025 && wheelTravel > 0.02) {
    mem.gpsUnchanged = num(mem.gpsUnchanged, 0) + dt;
    mem.gpsTravelSinceChange = num(mem.gpsTravelSinceChange, 0) + wheelTravel;
  } else if (gpsDelta > 0.08) {
    mem.gpsUnchanged = 0;
    mem.gpsTravelSinceChange = 0;
  }

  const wasGpsFrozen = !!mem.gpsFrozen;
  mem.gpsFrozen =
    num(mem.gpsUnchanged, 0) > 2.4 &&
    num(mem.gpsTravelSinceChange, 0) > 1.2;

  if (wasGpsFrozen && !mem.gpsFrozen) mem.gpsRecover = 1.5;
  else mem.gpsRecover = Math.max(0, num(mem.gpsRecover, 0) - dt);

  const midTheta = rad(wrap((prevTheta + theta) * 0.5));
  let motionScale = 1;
  if (mem.gpsFrozen && minRawRay < 1.35) motionScale = 0.10;

  let px = num(mem.px, rawX) +
    vWheel * dt * Math.cos(midTheta) * motionScale;
  let py = num(mem.py, rawY) +
    vWheel * dt * Math.sin(midTheta) * motionScale;

  if (!mem.gpsFrozen && !gpsJump) {
    const dx = rawX - px;
    const dy = rawY - py;
    const residual = Math.hypot(dx, dy);
    if (residual < 25) {
      let alpha = Math.abs(vWheel) > 0.18 ? 0.30 : 0.12;
      if (gpsDelta > 0.35) alpha = 0.42;
      const limit = Math.abs(vWheel) > 0.18 ? 1.8 : 0.65;
      const scale = residual > limit ? limit / residual : 1;
      px += dx * scale * alpha;
      py += dy * scale * alpha;
    }
  } else if (mem.gpsRecover > 0) {
    const dx = rawX - px;
    const dy = rawY - py;
    const residual = Math.hypot(dx, dy);
    if (residual < 35) {
      const limit = residual > 5 ? 5 / residual : 1;
      px += dx * limit * 0.40;
      py += dy * limit * 0.40;
    }
  }

  mem.px = px;
  mem.py = py;
  mem.lastGpsX = rawX;
  mem.lastGpsY = rawY;
  mem.prevRawH = rawH;

  if (!mem.cal || typeof mem.cal !== "object") {
    mem.cal = { active: false, x: rawX, y: rawY, sin: 0, cos: 0, n: 0 };
  }
  const straightForward =
    vWheel > 0.28 &&
    Math.abs(wr - wl) < 0.22 &&
    !mem.gpsFrozen &&
    !gpsJump &&
    !compassJump;

  if (straightForward) {
    if (!mem.cal.active) {
      mem.cal.active = true;
      mem.cal.x = rawX;
      mem.cal.y = rawY;
      mem.cal.sin = 0;
      mem.cal.cos = 0;
      mem.cal.n = 0;
    }
    mem.cal.sin += Math.sin(rad(rawH));
    mem.cal.cos += Math.cos(rad(rawH));
    mem.cal.n += 1;

    if (dist(rawX, rawY, mem.cal.x, mem.cal.y) >= 8 && mem.cal.n >= 12) {
      const course = deg(Math.atan2(rawY - mem.cal.y, rawX - mem.cal.x));
      const meanRaw = deg(Math.atan2(mem.cal.sin, mem.cal.cos));
      const estimate = wrap(meanRaw - course);
      const err = wrap(estimate - num(mem.headingBias, 0));
      if (Math.abs(err) < 60) {
        mem.headingBias = wrap(
          num(mem.headingBias, 0) + clamp(err * 0.06, -1, 1)
        );
      }
      mem.cal.x = rawX;
      mem.cal.y = rawY;
      mem.cal.sin = 0;
      mem.cal.cos = 0;
      mem.cal.n = 0;
    }
  } else {
    mem.cal.active = false;
    mem.cal.sin = 0;
    mem.cal.cos = 0;
    mem.cal.n = 0;
  }

  if (!Array.isArray(mem.gain) || mem.gain.length < 2) {
    mem.gain = [[2.8, 2.8], [2.8, 2.8]];
  }
  if (!Array.isArray(mem.dead) || mem.dead.length < 2) {
    mem.dead = [[0.18, 0.18], [0.18, 0.18]];
  }
  if (!Array.isArray(mem.lastCmd) || mem.lastCmd.length < 2) mem.lastCmd = [0, 0];
  if (!Array.isArray(mem.lastTarget) || mem.lastTarget.length < 2) mem.lastTarget = [0, 0];
  if (!Array.isArray(mem.noResponse) || mem.noResponse.length < 2) mem.noResponse = [0, 0];
  if (!Array.isArray(mem.motorStable) || mem.motorStable.length < 2) mem.motorStable = [0, 0];
  if (!Array.isArray(mem.motorStableTarget) || mem.motorStableTarget.length < 2) {
    mem.motorStableTarget = [0, 0];
  }
  if (!Array.isArray(mem.motorStableCmd) || mem.motorStableCmd.length < 2) {
    mem.motorStableCmd = [0, 0];
  }

  for (let s = 0; s < 2; s++) {
    if (!Array.isArray(mem.gain[s])) mem.gain[s] = [2.8, 2.8];
    if (!Array.isArray(mem.dead[s])) mem.dead[s] = [0.18, 0.18];

    const lastCmd = num(mem.lastCmd[s], 0);
    const lastTarget = num(mem.lastTarget[s], 0);
    const actual = s === 0 ? wl : wr;
    const direction = lastTarget < 0 ? 1 : 0;
    const dead = clamp(num(mem.dead[s][direction], 0.18), 0.10, 0.48);

    const stableTarget = num(mem.motorStableTarget[s], lastTarget);
    const stableCmd = num(mem.motorStableCmd[s], lastCmd);
    const consistent =
      Math.abs(lastTarget) > 0.13 &&
      Math.abs(lastCmd) > dead + 0.04 &&
      Math.sign(stableTarget) === Math.sign(lastTarget) &&
      Math.abs(lastTarget - stableTarget) < 0.11 &&
      Math.abs(lastCmd - stableCmd) < 0.09;

    if (consistent) mem.motorStable[s] = num(mem.motorStable[s], 0) + dt;
    else mem.motorStable[s] = 0;

    if (mem.motorStable[s] > 0.45) {
      if (actual * lastTarget > 0 && Math.abs(actual) > 0.08) {
        const ratio = Math.abs(actual) /
          Math.max(0.08, Math.abs(lastCmd) - dead);
        if (ratio > 0.45 && ratio < 6.0) {
          const old = num(mem.gain[s][direction], 2.8);
          mem.gain[s][direction] = clamp(old + (ratio - old) * 0.015, 0.75, 5.8);
        }
      }

      if (Math.abs(actual) < 0.045 && Math.abs(lastCmd) > dead + 0.04) {
        mem.noResponse[s] = num(mem.noResponse[s], 0) + dt;
        if (mem.noResponse[s] > 0.8) {
          mem.dead[s][direction] = clamp(
            num(mem.dead[s][direction], 0.18) + 0.006,
            0.12,
            0.45
          );
        }
      } else {
        mem.noResponse[s] = 0;
      }
    } else {
      mem.noResponse[s] = 0;
    }

    if (Math.abs(actual) > 0.22 && Math.abs(lastCmd) > dead + 0.02) {
      mem.dead[s][direction] = Math.max(
        0.11,
        num(mem.dead[s][direction], 0.18) - 0.00015
      );
    }

    mem.motorStableTarget[s] = lastTarget;
    mem.motorStableCmd[s] = lastCmd;
  }

  const prevBattery = num(mem.prevBattery, battery);
  if (!o.docked && (wheelTravel > 0.012 || drillProgress > 0.05)) {
    const gross = clamp(
      prevBattery - battery + solar * dt * 0.20,
      0,
      0.025
    );
    mem.energyUse = num(mem.energyUse, 0) + gross;
    mem.energyDist = num(mem.energyDist, 0) +
      wheelTravel +
      (drillProgress > 0.05 ? dt * 0.06 : 0);

    if (mem.energyDist >= 18) {
      const loadFactor = 1 + 0.15 * carried;
      const measured = clamp(
        mem.energyUse / Math.max(6, mem.energyDist) / loadFactor,
        0.00045,
        0.006
      );
      const oldRate = num(mem.energyRate, 0.0015);
      const alpha = measured > oldRate ? 0.20 : 0.045;
      mem.energyRate = clamp(oldRate + (measured - oldRate) * alpha, 0.00055, 0.006);
      mem.energyUse = 0;
      mem.energyDist = 0;
    }
  }

  if (!Array.isArray(mem.rFilt) || mem.rFilt.length !== 9) {
    mem.rFilt = [];
    mem.rRaw = [];
    mem.rSameTime = [];
    mem.rSameMotion = [];
    mem.rBad = [];
    for (let i = 0; i < 9; i++) {
      mem.rFilt[i] = 15;
      mem.rRaw[i] = 15;
      mem.rSameTime[i] = 0;
      mem.rSameMotion[i] = 0;
      mem.rBad[i] = false;
    }
  }

  let allMax = true;
  let anyNear = false;
  for (let i = 0; i < 9; i++) {
    const r = clamp(rawRays ? num(rawRays[i], 15) : 15, 0, 15);
    const last = num(mem.rRaw[i], r);
    const diff = Math.abs(r - last);

    if (diff < 0.025) {
      if (wheelTravel > 0.02 || Math.abs(yawRad) > 0.015) {
        mem.rSameTime[i] = num(mem.rSameTime[i], 0) + dt;
        mem.rSameMotion[i] = num(mem.rSameMotion[i], 0) +
          wheelTravel + Math.abs(yawRad) * 0.5;
      }
    } else if (diff > 0.30) {
      mem.rSameTime[i] = 0;
      mem.rSameMotion[i] = 0;
      mem.rBad[i] = false;
    }

    if (mem.rSameTime[i] > 8 &&
        mem.rSameMotion[i] > 4 &&
        r < 14.5) {
      mem.rBad[i] = true;
    }

    const effective = mem.rBad[i] ? 15 : r;
    if (effective < 14.8) allMax = false;
    if (effective < 14.3) anyNear = true;

    let f = num(mem.rFilt[i], effective);
    const a = effective < f ? 0.66 : 0.31;
    f += (effective - f) * a;
    mem.rFilt[i] = clamp(f, 0, 15);
    mem.rRaw[i] = r;
  }

  if (allMax && wheelTravel > 0.02) {
    mem.allMaxTravel = num(mem.allMaxTravel, 0) + wheelTravel;
  } else if (anyNear) {
    mem.allMaxTravel = Math.max(
      0,
      num(mem.allMaxTravel, 0) - wheelTravel * 1.2
    );
  }
  mem.rangeTrust = mem.allMaxTravel > 30 ? 0.78 : 1;

  if (beacon) {
    const bd = Math.max(0, num(beacon.distance, 99));
    const bb = num(beacon.bearing, 0);
    const pb = mem.prevBeacon;

    if (pb &&
        (wheelTravel > 0.02 || Math.abs(yawRad) > 0.015) &&
        Math.abs(bd - num(pb.d, bd)) < 0.018 &&
        Math.abs(wrap(bb - num(pb.b, bb))) < 0.22) {
      mem.beaconSameTime = num(mem.beaconSameTime, 0) + dt;
      mem.beaconSameMotion = num(mem.beaconSameMotion, 0) +
        wheelTravel + Math.abs(yawRad) * 0.5;
      if (mem.beaconSameTime > 6 && mem.beaconSameMotion > 2.8) {
        mem.beaconBad = true;
      }
    } else if (!pb ||
               Math.abs(bd - num(pb.d, bd)) > 0.08 ||
               Math.abs(wrap(bb - num(pb.b, bb))) > 1) {
      mem.beaconSameTime = 0;
      mem.beaconSameMotion = 0;
      mem.beaconBad = false;
    }

    mem.prevBeacon = { d: bd, b: bb };
  } else {
    mem.prevBeacon = null;
    mem.beaconSameTime = 0;
    mem.beaconSameMotion = 0;
  }

  const poseX = num(mem.px, rawX);
  const poseY = num(mem.py, rawY);

  if (sampleCompleted) {
    const meta = mem.pendingMeta || mem.siteLock || {
      x: poseX,
      y: poseY,
      value: 1
    };
    const mx = num(meta.x, poseX);
    const my = num(meta.y, poseY);
    let value = Math.max(0.1, num(meta.value, 1));
    const valueGain = carriedValue - oldCarriedValue;
    if (valueGain > 0.01) {
      value = valueGain / Math.max(1, carried - oldCarried);
    }
    mem.samples.push({ x: mx, y: my, value: value });

    let associated = -1;
    let nearestD = 38;
    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (!h || h.status >= 2) continue;
      const d = dist(mx, my, h.x, h.y);
      if (d < nearestD) {
        nearestD = d;
        associated = i;
      }
    }

    const currentHint = Math.floor(num(mem.currentHint, -1));
    if (currentHint >= 0 &&
        currentHint < mem.hints.length &&
        mem.hints[currentHint] &&
        mem.hints[currentHint].status < 2 &&
        dist(mx, my, mem.hints[currentHint].x, mem.hints[currentHint].y) < 42) {
      associated = currentHint;
    }

    if (associated >= 0) {
      mem.hints[associated].status = 2;
      if (associated === currentHint) mem.currentHint = -1;
    }

    for (let i = 0; i < mem.globalPoints.length; i++) {
      const p = mem.globalPoints[i];
      if (p && dist(mx, my, p.x, p.y) < 12) p.done = true;
    }

    if (mem.ambient && dist(mx, my, mem.ambient.x, mem.ambient.y) < 30) {
      mem.ambient = null;
    }

    mem.sampleActive = false;
    mem.pendingMeta = null;
    mem.siteLock = null;
    mem.stillTime = 0;
    mem.holdI = [0, 0];
    mem.navKey = "";
    mem.lastDrillProgress = 0;
    mem.lastDrillProgressT = tNow;
  } else if (carried < oldCarried || delivered > oldDelivered) {
    mem.sampleActive = false;
    mem.pendingMeta = null;
    mem.siteLock = null;
    mem.stillTime = 0;
    mem.holdI = [0, 0];
  }

  if (siteObs && carried < mem.capacity) {
    const sd = Math.max(0, num(siteObs.distance, 99));
    const sb = num(siteObs.bearing, 0);
    const a = rad(mem.theta + sb);
    const sx = poseX + sd * Math.cos(a);
    const sy = poseY + sd * Math.sin(a);
    const sv = Math.max(0.1, num(siteObs.value, 1));

    if (!mem.siteLock) {
      mem.siteLock = { x: sx, y: sy, value: sv, lastSeen: tNow };
    } else {
      const gap = dist(mem.siteLock.x, mem.siteLock.y, sx, sy);
      if (gap > 9) {
        mem.siteLock.x = sx;
        mem.siteLock.y = sy;
      } else {
        mem.siteLock.x = mem.siteLock.x * 0.68 + sx * 0.32;
        mem.siteLock.y = mem.siteLock.y * 0.68 + sy * 0.32;
      }
      mem.siteLock.value = sv;
      mem.siteLock.lastSeen = tNow;
    }
  } else if (mem.siteLock &&
             !mem.sampleActive &&
             tNow - num(mem.siteLock.lastSeen, tNow) > 14) {
    mem.siteLock = null;
  }

  if (!sampleCompleted && !mem.sampleActive && drillProgress > 0.05) {
    mem.sampleActive = true;
    mem.sampleStart = tNow - drillProgress;
    mem.lastDrillProgress = drillProgress;
    mem.lastDrillProgressT = tNow;
    if (mem.siteLock) {
      mem.pendingMeta = {
        x: mem.siteLock.x,
        y: mem.siteLock.y,
        value: mem.siteLock.value
      };
    }
  }

  const baseX = num(mem.baseX, width * 0.5);
  const baseY = num(mem.baseY, height * 0.5);
  const baseDist = dist(poseX, poseY, baseX, baseY);
  const beaconDistRaw = beacon ? Math.max(0, num(beacon.distance, 99)) : 99;
  const beaconUsable = !!beacon && !mem.beaconBad && beaconDistRaw <= 20.5;
  const beaconDist = beaconUsable ? beaconDistRaw : 99;
  const maxWheel = Math.max(Math.abs(wl), Math.abs(wr));
  const atBase = !!o.docked ||
    (beaconUsable && beaconDist <= 2.55) ||
    (baseDist <= 2.45 && maxWheel < 0.22);
  const homeDist = beaconUsable ? beaconDist : baseDist;

  const scienceNow = Math.max(0, num(o.science, 0));

  function routeFeasible(out, home, load) {
    const l = Math.max(0, load);
    const route = Math.max(0, out) + Math.max(0, home) + 8;
    const energy =
      0.14 +
      route * num(mem.energyRate, 0.0015) * (1 + 0.18 * l) * 1.20 +
      0.025 * l;
    const seconds = route * 2.45 + 30 + 6 * l;
    return energy <= battery - 0.015 && seconds <= timeLeft - 5;
  }

  function homeNeed(d, load) {
    const l = Math.max(0, load);
    return 0.11 +
      Math.max(0, d + 5) * num(mem.energyRate, 0.0015) *
        (1 + 0.18 * l) * 1.22 +
      0.025 * l;
  }

  function homeSeconds(d, load) {
    return Math.max(0, d) * 2.55 + 26 + 5 * Math.max(0, load);
  }

  const homeEnergyNow = homeNeed(homeDist, carried);
  const homeTimeNow = homeSeconds(homeDist, carried);

  function emit(c, drill) {
    const left = clamp(num(c && c.left, 0), -1, 1);
    const right = clamp(num(c && c.right, 0), -1, 1);
    mem.lastCmd = [left, right];
    mem.lastTarget = [
      num(c && c.tl, 0),
      num(c && c.tr, 0)
    ];
    mem.prevT = tNow;
    mem.prevBattery = battery;
    mem.prevCarried = carried;
    mem.prevCarriedValue = carriedValue;
    mem.prevDelivered = delivered;
    return { left: left, right: right, drill: !!drill };
  }

  function motorPower(target, actual, side) {
    const t = clamp(target, -0.52, 0.52);
    const a = num(actual, 0);
    const absT = Math.abs(t);
    const absA = Math.abs(a);
    const tDir = t < 0 ? 1 : 0;
    const aDir = a < 0 ? 1 : 0;
    const gain = clamp(num(mem.gain[side][tDir], 2.8), 0.75, 5.8);
    const dead = clamp(num(mem.dead[side][tDir], 0.18), 0.10, 0.48);

    if (absT < 0.055) {
      if (absA < 0.12) return 0;
      let brake = dead + Math.max(0, absA - 0.14) / gain * 0.22;
      if (absA > 0.75) brake = Math.max(brake, 0.34);
      return clamp(-Math.sign(a) * brake, -0.60, 0.60);
    }

    if ((a * t > 0 && absA > absT + 0.28) || absA > 0.98) {
      const excess = Math.max(0, absA - absT);
      const brake = clamp(dead + excess / gain * 0.35, dead, 0.62);
      return clamp(-Math.sign(a) * brake, -0.68, 0.68);
    }

    const feed = Math.sign(t) * (dead + absT / gain);
    const u = feed + 0.22 * (t - a);
    return clamp(u, -0.72, 0.72);
  }

  function wheelCommands(v, omega) {
    const lt = clamp(v - 0.3 * omega, -0.52, 0.52);
    const rt = clamp(v + 0.3 * omega, -0.52, 0.52);
    return {
      left: motorPower(lt, wl, 0),
      right: motorPower(rt, wr, 1),
      tl: lt,
      tr: rt
    };
  }

  function stopCommands() {
    return wheelCommands(0, 0);
  }

  function holdCommands() {
    if (!Array.isArray(mem.holdI) || mem.holdI.length < 2) mem.holdI = [0, 0];

    const pitch = num(o.pitch, 0);
    const pitchFeed = clamp(pitch * 0.004, -0.12, 0.12);
    const actuals = [wl, wr];
    const out = [];

    for (let i = 0; i < 2; i++) {
      const actual = actuals[i];
      let integral = num(mem.holdI[i], 0);

      if (Math.abs(actual) > 0.045) {
        integral = clamp(integral - actual * 1.6 * dt, -0.46, 0.46);
      } else if (Math.abs(pitch) < 2.5) {
        integral *= 0.45;
        if (Math.abs(integral) < 0.12) integral = 0;
      } else {
        integral *= 0.985;
      }

      let u = integral - 0.82 * actual + pitchFeed;
      if (Math.abs(actual) < 0.04 && Math.abs(pitch) < 2.5) {
        integral = 0;
        u = 0;
      }

      mem.holdI[i] = integral;
      out[i] = clamp(u, -0.48, 0.48);
    }

    return { left: out[0], right: out[1], tl: 0, tr: 0 };
  }

  function rayAt(angle) {
    const a = clamp(angle, -80, 80);
    const q = (a + 80) / 20;
    const i = Math.floor(q);
    const f = q - i;
    if (i >= 8) return num(mem.rFilt[8], 15);
    return num(mem.rFilt[i], 15) * (1 - f) +
      num(mem.rFilt[i + 1], 15) * f;
  }

  function clearanceAt(angle) {
    const center = rayAt(angle);
    const side = Math.min(rayAt(angle - 20), rayAt(angle + 20));
    return Math.min(center, center * 0.72 + side * 0.28);
  }

  function edgeDistance(angle) {
    const a = rad(wrap(mem.theta + angle));
    const dx = Math.cos(a);
    const dy = Math.sin(a);
    const margin = 5;
    let d = 1e6;

    if (dx > 0.001) d = Math.min(d, (width - margin - poseX) / dx);
    if (dx < -0.001) d = Math.min(d, (margin - poseX) / dx);
    if (dy > 0.001) d = Math.min(d, (height - margin - poseY) / dy);
    if (dy < -0.001) d = Math.min(d, (margin - poseY) / dy);

    return Math.max(0, d);
  }

  function navCommands(goalError, maxV) {
    const goal = wrap(num(goalError, 0));
    let vmax = clamp(num(maxV, 0.38), 0, 0.48);
    if (mem.rangeTrust < 0.9) vmax = Math.min(vmax, 0.35);
    if (maxWheel > 0.65) vmax = Math.min(vmax, 0.16);
    if (maxWheel > 0.84) vmax = 0.02;

    const front = clearanceAt(0);
    const safe = 1.65 + vmax * 0.75;

    if (Math.abs(goal) > 82 && front > 1.30) {
      return wheelCommands(0, Math.sign(goal) * 0.46);
    }

    const clippedGoal = clamp(goal, -80, 80);
    const candidates = [
      -80, -60, -40, -20, 0, 20, 40, 60, 80,
      clippedGoal,
      clamp(goal * 0.65, -80, 80)
    ];

    let best = clippedGoal;
    let bestCost = 1e9;
    let bestClear = clearanceAt(clippedGoal);

    for (let i = 0; i < candidates.length; i++) {
      const a = candidates[i];
      const clear = clearanceAt(a);
      let cost = Math.abs(wrap(a - clippedGoal)) * 0.035;

      const hazard = Math.max(0, safe - clear);
      cost += hazard * hazard * 2.3;
      if (clear < 1.10) cost += 8;
      if (clear < 0.72) cost += 16;

      const edge = edgeDistance(a);
      if (edge < 1.5) cost += 16;
      else if (edge < 7) cost += (7 - edge) * 0.85;

      if (front < safe &&
          Math.abs(a) > 10 &&
          mem.avoidSign &&
          Math.sign(a) !== Math.sign(mem.avoidSign)) {
        cost += 0.25;
      }
      if (front < safe) {
        cost += Math.abs(a - num(mem.lastAim, a)) * 0.004;
      }

      if (cost < bestCost) {
        bestCost = cost;
        best = a;
        bestClear = clear;
      }
    }

    if (front > safe + 1.3) mem.avoidSign = 0;
    else if (Math.abs(best) > 10) mem.avoidSign = Math.sign(best);
    mem.lastAim = best;

    let v = vmax * Math.max(0.22, Math.cos(rad(best)));
    v *= clamp(
      (bestClear - 0.55) / Math.max(0.8, safe - 0.55),
      0.10,
      1
    );

    if (bestClear < 0.95) v = Math.min(v, 0.07);
    if (front < 0.80 && Math.abs(best) < 18) v = 0;
    if (Math.abs(best) > 58) v = 0;
    if (maxWheel > 0.84) v = 0;

    const omega = clamp(1.25 * rad(best), -0.65, 0.65);
    return wheelCommands(v, omega);
  }

  function openSide() {
    let leftOpen = 0;
    let rightOpen = 0;
    for (let i = 5; i < 9; i++) leftOpen += num(mem.rFilt[i], 15);
    for (let i = 0; i < 4; i++) rightOpen += num(mem.rFilt[i], 15);
    if (Math.abs(leftOpen - rightOpen) < 0.5) {
      return mem.avoidSign ? -mem.avoidSign : 1;
    }
    return leftOpen >= rightOpen ? 1 : -1;
  }

  function recoveryAction() {
    const rem = Math.max(0, num(mem.recoverTimer, 0));
    const s = num(mem.recoverSign, 1);
    let c;

    if (rem > 0.58) c = wheelCommands(-0.15, s * 0.42);
    else c = wheelCommands(0, s * 0.48);

    mem.recoverTimer = Math.max(0, rem - dt);
    return emit(c, false);
  }

  function ringPoint(cx, cy, step, count, radius, offset) {
    const a = num(offset, 0) + 2 * Math.PI * step / count;
    return {
      x: clamp(cx + radius * Math.cos(a), 4, width - 4),
      y: clamp(cy + radius * Math.sin(a), 4, height - 4)
    };
  }

  function finishSearch(s, index, kind) {
    if (kind === "hint") {
      s.status = 2;
      if (Math.floor(num(mem.currentHint, -1)) === index) {
        mem.currentHint = -1;
      }
    } else {
      mem.ambientLastX = s.x;
      mem.ambientLastY = s.y;
      mem.ambient = null;
    }
  }

  function beginClimb(s) {
    s.phase = 3;
    s.step = 0;
    s.anchorX = num(s.bestX, s.x);
    s.anchorY = num(s.bestY, s.y);
    s.anchorScience = num(s.bestScience, 0);
    s.localScience = s.anchorScience;
    s.localX = s.anchorX;
    s.localY = s.anchorY;
    s.loops = 0;
  }

  function searchInfo(s, index, kind) {
    if (!s) return null;
    if (kind === "hint" && s.status >= 2) return null;

    for (let tries = 0; tries < 12; tries++) {
      if (s.phase === 0) {
        const d = dist(poseX, poseY, s.x, s.y);
        if (d > 3.2) {
          return {
            kind: kind,
            index: index,
            phase: 0,
            step: 0,
            x: s.x,
            y: s.y,
            dist: d,
            home: dist(s.x, s.y, baseX, baseY) + 6,
            key: kind + ":c:" + index
          };
        }

        s.phase = 1;
        s.step = 0;
        s.centerScience = num(mem.scienceEma, scienceNow);
        s.phaseStartScience = s.centerScience;
        s.bestScience = s.centerScience;
        s.bestX = poseX;
        s.bestY = poseY;
        s.anchorX = poseX;
        s.anchorY = poseY;
        s.anchorScience = s.centerScience;
        s.localScience = s.centerScience;
        s.localX = poseX;
        s.localY = poseY;
        s.loops = 0;
        s.outerTried = 0;
        continue;
      }

      const centerDistance = dist(poseX, poseY, s.x, s.y);
      if (centerDistance < 34 &&
          scienceNow > num(s.bestScience, 0) + 0.035) {
        s.bestScience = scienceNow;
        s.bestX = poseX;
        s.bestY = poseY;
      }

      if (s.phase === 3 &&
          dist(poseX, poseY, s.anchorX, s.anchorY) < 12 &&
          scienceNow > num(s.localScience, 0) + 0.035) {
        s.localScience = scienceNow;
        s.localX = poseX;
        s.localY = poseY;
      }

      let count;
      let radius;
      let cx;
      let cy;

      if (s.phase === 1) {
        count = 8;
        radius = 8;
        cx = s.x;
        cy = s.y;
      } else if (s.phase === 2) {
        count = 8;
        radius = 16;
        cx = s.x;
        cy = s.y;
      } else {
        count = 4;
        radius = 6;
        cx = s.anchorX;
        cy = s.anchorY;
      }

      let step = Math.max(0, Math.floor(num(s.step, 0)));
      if (step >= count) {
        if (s.phase === 1) {
          if (num(s.bestScience, 0) >
                num(s.centerScience, 0) + 0.055 &&
              dist(s.bestX, s.bestY, s.x, s.y) > 2.5) {
            beginClimb(s);
          } else {
            s.phase = 2;
            s.step = 0;
            s.outerTried = 1;
            s.phaseStartScience = num(s.bestScience, 0);
          }
          continue;
        }

        if (s.phase === 2) {
          if (num(s.bestScience, 0) >
                num(s.phaseStartScience, 0) + 0.055 &&
              dist(s.bestX, s.bestY, s.x, s.y) > 2.8) {
            beginClimb(s);
          } else {
            finishSearch(s, index, kind);
            return null;
          }
          continue;
        }

        if (num(s.localScience, 0) >
              num(s.anchorScience, 0) + 0.04 &&
            dist(s.localX, s.localY, s.anchorX, s.anchorY) > 2 &&
            num(s.loops, 0) < 3) {
          s.anchorX = s.localX;
          s.anchorY = s.localY;
          s.anchorScience = s.localScience;
          s.localScience = s.anchorScience;
          s.localX = s.anchorX;
          s.localY = s.anchorY;
          s.loops = num(s.loops, 0) + 1;
          s.step = 0;
          continue;
        }

        if (!s.outerTried) {
          s.phase = 2;
          s.step = 0;
          s.outerTried = 1;
          s.phaseStartScience = num(s.bestScience, 0);
          continue;
        }

        finishSearch(s, index, kind);
        return null;
      }

      const p = ringPoint(cx, cy, step, count, radius, s.angle);
      const d = dist(poseX, poseY, p.x, p.y);

      if (d <= 3.0) {
        s.step = step + 1;
        continue;
      }

      return {
        kind: kind,
        index: index,
        phase: s.phase,
        step: step,
        x: p.x,
        y: p.y,
        dist: d,
        home: dist(p.x, p.y, baseX, baseY) + 6,
        key: kind + ":r:" + index + ":" + s.phase + ":" + step
      };
    }

    return null;
  }

  function skipTarget(info) {
    if (!info) return;

    if (info.kind === "hint" &&
        info.index >= 0 &&
        info.index < mem.hints.length) {
      const h = mem.hints[info.index];
      if (!h) return;

      if (h.phase === 0) {
        h.phase = 1;
        h.step = 0;
        h.centerScience = num(mem.scienceEma, scienceNow);
        h.bestScience = h.centerScience;
        h.bestX = poseX;
        h.bestY = poseY;
        h.anchorX = poseX;
        h.anchorY = poseY;
        h.anchorScience = h.centerScience;
        h.outerTried = 0;
      } else {
        h.step = Math.max(0, Math.floor(num(h.step, 0))) + 1;
      }
    } else if (info.kind === "ambient" && mem.ambient) {
      mem.ambient.step = Math.max(
        0,
        Math.floor(num(mem.ambient.step, 0))
      ) + 1;
    } else if (info.kind === "global" &&
               info.index >= 0 &&
               info.index < mem.globalPoints.length) {
      mem.globalPoints[info.index].done = true;
      mem.globalIndex = -1;
    } else if (info.kind === "site") {
      mem.siteLock = null;
      mem.siteIgnoreUntil = tNow + 8;
    }
  }

  function updateProgress(key, d, info) {
    if (mem.navKey !== key) {
      mem.navKey = key;
      mem.navBest = d;
      mem.navStuck = 0;
      mem.stuckCount = 0;
      return false;
    }

    if (d < num(mem.navBest, d) - 0.42) {
      mem.navBest = d;
      mem.navStuck = 0;
      mem.stuckCount = 0;
      return false;
    }

    const stuckScale =
      mem.gpsFrozen && minRawRay < 1.45 ? 1.8 : 1;
    mem.navStuck = num(mem.navStuck, 0) + dt * stuckScale;

    if (mem.navStuck > 14) {
      mem.navStuck = 0;
      mem.navBest = d;
      mem.stuckCount = num(mem.stuckCount, 0) + 1;
      mem.recoverSign = mem.avoidSign ? -mem.avoidSign : openSide();
      mem.avoidSign = mem.recoverSign;
      mem.recoverTimer = 1.15;

      if (mem.stuckCount >= 2) {
        skipTarget(info);
        mem.navKey = "";
        mem.stuckCount = 0;
      }
      return true;
    }

    return false;
  }

  function hintInfo(index) {
    const h = mem.hints[index];
    if (!h || h.status >= 2) return null;
    return searchInfo(h, index, "hint");
  }

  function chooseHint() {
    let best = -1;
    let bestScore = -1;
    let bestInfo = null;

    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (!h || h.status >= 2) continue;

      const info = hintInfo(i);
      if (!info || !routeFeasible(info.dist, info.home, carried + 1)) continue;

      let score = Math.pow(Math.max(0.1, num(h.value, 1)), 1.14) /
        (52 + info.dist + 0.58 * info.home + 12 * carried);

      if (h.status === 1) score *= 1.04;
      if (i === Math.floor(num(mem.currentHint, -1))) score *= 1.06;

      if (score > bestScore) {
        bestScore = score;
        best = i;
        bestInfo = info;
      }
    }

    if (best >= 0) {
      mem.currentHint = best;
      mem.hints[best].status = 1;
      return bestInfo;
    }

    return null;
  }

  function globalInfo(index) {
    const p = mem.globalPoints[index];
    if (!p || p.done) return null;

    const d = dist(poseX, poseY, p.x, p.y);
    if (d <= 3.2) {
      p.done = true;
      if (Math.floor(num(mem.globalIndex, -1)) === index) {
        mem.globalIndex = -1;
      }
      return null;
    }

    return {
      kind: "global",
      index: index,
      x: p.x,
      y: p.y,
      dist: d,
      home: dist(p.x, p.y, baseX, baseY) + 6,
      key: "g:" + index
    };
  }

  function chooseGlobal() {
    const old = Math.floor(num(mem.globalIndex, -1));
    if (old >= 0 && old < mem.globalPoints.length) {
      const info = globalInfo(old);
      if (info && routeFeasible(info.dist, info.home, carried + 1)) {
        return info;
      }
      mem.globalIndex = -1;
    }

    let best = -1;
    let bestScore = -1;
    let bestInfo = null;

    for (let i = 0; i < mem.globalPoints.length; i++) {
      const info = globalInfo(i);
      if (!info || !routeFeasible(info.dist, info.home, carried + 1)) continue;

      const score = 1 / (40 + info.dist + 0.55 * info.home + 8 * carried);
      if (score > bestScore) {
        bestScore = score;
        best = i;
        bestInfo = info;
      }
    }

    mem.globalIndex = best;
    return bestInfo;
  }

  function getTask() {
    let current = Math.floor(num(mem.currentHint, -1));

    if (current >= 0 &&
        current < mem.hints.length &&
        mem.hints[current] &&
        mem.hints[current].status < 2) {
      const info = hintInfo(current);
      if (info && routeFeasible(info.dist, info.home, carried + 1)) {
        return info;
      }
      mem.currentHint = -1;
    } else {
      mem.currentHint = -1;
    }

    const hinfo = chooseHint();
    if (hinfo) return hinfo;

    if (!mem.ambient &&
        scienceNow > 0.52 &&
        dist(
          poseX,
          poseY,
          num(mem.ambientLastX, -1e9),
          num(mem.ambientLastY, -1e9)
        ) > 24) {
      mem.ambient = {
        x: poseX,
        y: poseY,
        phase: 1,
        step: 0,
        angle: 0,
        centerScience: num(mem.scienceEma, scienceNow),
        phaseStartScience: num(mem.scienceEma, scienceNow),
        bestScience: num(mem.scienceEma, scienceNow),
        bestX: poseX,
        bestY: poseY,
        anchorX: poseX,
        anchorY: poseY,
        anchorScience: num(mem.scienceEma, scienceNow),
        localScience: num(mem.scienceEma, scienceNow),
        localX: poseX,
        localY: poseY,
        loops: 0,
        outerTried: 0
      };
    }

    if (mem.ambient) {
      const ainfo = searchInfo(mem.ambient, 0, "ambient");
      if (ainfo && routeFeasible(ainfo.dist, ainfo.home, carried + 1)) {
        return ainfo;
      }
    }

    return chooseGlobal();
  }

  function siteDistanceNow() {
    if (siteObs) return Math.max(0, num(siteObs.distance, 99));
    if (mem.siteLock) {
      return dist(poseX, poseY, mem.siteLock.x, mem.siteLock.y);
    }
    return 99;
  }

  function goHome() {
    if (atBase || homeDist <= 2.25) {
      return emit(stopCommands(), false);
    }

    const error = beaconUsable
      ? num(beacon.bearing, 0)
      : wrap(
          deg(Math.atan2(baseY - poseY, baseX - poseX)) - mem.theta
        );

    if (updateProgress("home", homeDist, null)) {
      return recoveryAction();
    }

    let speed = homeDist > 35 ? 0.44 : (homeDist > 8 ? 0.34 : 0.22);
    if (timeLeft < homeTimeNow + 22) speed = 0.47;
    return emit(navCommands(error, speed), false);
  }

  if (delivered > oldDelivered && carried === 0) {
    mem.returning = false;
  }
  if (mem.returning && atBase && carried === 0) {
    mem.returning = false;
    mem.sampleActive = false;
    mem.stillTime = 0;
    mem.holdI = [0, 0];
  }

  if (!mem.returning && !mem.sampleActive) {
    if (carried >= mem.capacity) {
      mem.returning = true;
    } else if (!atBase &&
               battery < homeEnergyNow + (carried > 0 ? 0.12 : 0.14)) {
      mem.returning = true;
    } else if (!atBase && timeLeft < homeTimeNow + 28) {
      mem.returning = true;
    }
  }

  if (o.bumped && !mem.prevBumped && !mem.sampleActive && !atBase) {
    mem.recoverSign = openSide();
    mem.recoverTimer = 1.0;
    mem.avoidSign = mem.recoverSign;
  }
  mem.prevBumped = !!o.bumped;

  if (mem.sampleActive) {
    const elapsed = tNow - num(mem.sampleStart, tNow);
    const sd = siteDistanceNow();

    if (drillProgress > num(mem.lastDrillProgress, 0) + 0.04) {
      mem.lastDrillProgress = drillProgress;
      mem.lastDrillProgressT = tNow;
    }

    const noProgressTime = tNow - num(mem.lastDrillProgressT, tNow);
    const timedOut =
      (elapsed > 32 && noProgressTime > 11 && drillProgress < 5.8) ||
      elapsed > 46;

    if (timedOut && carried === oldCarried) {
      mem.sampleActive = false;
      mem.pendingMeta = null;
      mem.siteLock = null;
      mem.stillTime = 0;
      mem.sampleFailures = num(mem.sampleFailures, 0) + 1;
      mem.siteIgnoreUntil = tNow + 7;
      mem.holdI = [0, 0];
    } else {
      if (mem.siteLock && !mem.pendingMeta) {
        mem.pendingMeta = {
          x: mem.siteLock.x,
          y: mem.siteLock.y,
          value: mem.siteLock.value
        };
      }

      const c = holdCommands();
      const still = Math.max(Math.abs(wl), Math.abs(wr)) < 0.14;
      const inRange = sd <= 1.47 || drillProgress > 0.05;
      const drill = still && inRange;
      return emit(c, drill);
    }
  }

  if (atBase && carried > 0) {
    return emit(stopCommands(), false);
  }

  if (mem.recoverTimer > 0 && !atBase) {
    return recoveryAction();
  }

  if (mem.returning && !atBase) {
    return goHome();
  }

  if (atBase && carried === 0 && maxWheel > 0.28) {
    return emit(stopCommands(), false);
  }

  if (atBase && carried === 0 && battery < 0.46 && timeLeft > 50) {
    return emit(stopCommands(), false);
  }

  if (siteObs &&
      carried < mem.capacity &&
      !mem.returning &&
      tNow >= num(mem.siteIgnoreUntil, 0)) {
    const sd = Math.max(0, num(siteObs.distance, 99));
    const sb = num(siteObs.bearing, 0);
    const a = rad(mem.theta + sb);
    const sx = poseX + sd * Math.cos(a);
    const sy = poseY + sd * Math.sin(a);
    const siteHome = dist(sx, sy, baseX, baseY);

    if (!routeFeasible(sd, siteHome + 6, carried + 1)) {
      if (!atBase) {
        mem.returning = true;
        return goHome();
      }
      return emit(stopCommands(), false);
    }

    if (sd <= 1.30) {
      const c = holdCommands();
      const still = Math.max(Math.abs(wl), Math.abs(wr)) < 0.13;

      if (still && sd <= 1.40) {
        mem.stillTime = num(mem.stillTime, 0) + dt;
      } else {
        mem.stillTime = 0;
      }

      let drill = false;
      if (mem.stillTime >= 0.22 && still && sd <= 1.43) {
        mem.sampleActive = true;
        mem.sampleStart = tNow;
        mem.lastDrillProgress = 0;
        mem.lastDrillProgressT = tNow;
        mem.pendingMeta = mem.siteLock
          ? {
              x: mem.siteLock.x,
              y: mem.siteLock.y,
              value: mem.siteLock.value
            }
          : {
              x: sx,
              y: sy,
              value: Math.max(0.1, num(siteObs.value, 1))
            };
        drill = true;
      }

      return emit(c, drill);
    }

    mem.stillTime = 0;
    if (updateProgress("site", sd, { kind: "site" })) {
      return recoveryAction();
    }

    const speed = clamp((sd - 0.78) * 0.20, 0.08, 0.40);
    return emit(navCommands(sb, speed), false);
  }

  if (atBase && carried === 0 && maxWheel < 0.28) {
    /* Staying still here allows fast charging while a task is selected. */
  }

  const info = getTask();
  if (!info) {
    if (carried > 0 || !atBase) {
      mem.returning = true;
      return goHome();
    }
    return emit(stopCommands(), false);
  }

  if (!routeFeasible(info.dist, info.home, carried + 1)) {
    if (carried > 0 || !atBase) {
      mem.returning = true;
      return goHome();
    }
    return emit(stopCommands(), false);
  }

  if (updateProgress(info.key, info.dist, info)) {
    return recoveryAction();
  }

  const bearing = deg(Math.atan2(info.y - poseY, info.x - poseX));
  const error = wrap(bearing - mem.theta);

  let speed;
  if (info.kind === "hint" && info.phase === 0) {
    speed = info.dist > 35 ? 0.42 : (info.dist > 10 ? 0.34 : 0.24);
  } else if (info.kind === "hint") {
    speed = info.dist > 9 ? 0.34 : 0.23;
  } else if (info.kind === "ambient") {
    speed = info.dist > 8 ? 0.33 : 0.22;
  } else {
    speed = info.dist > 18 ? 0.42 : (info.dist > 5 ? 0.32 : 0.22);
  }

  return emit(navCommands(error, speed), false);
}

function act(obs, mem) {
  const o = obs || {};
  if (!mem || typeof mem !== "object") mem = {};

  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
  const num = (v, d) => {
    if (v === null || v === undefined) return d;
    const n = Number(v);
    return Number.isFinite(n) ? n : d;
  };
  const wrap = (a) => {
    a = (a + 180) % 360;
    if (a < 0) a += 360;
    return a - 180;
  };
  const rad = (d) => d * Math.PI / 180;
  const deg = (r) => r * 180 / Math.PI;
  const dist = (x1, y1, x2, y2) => Math.hypot(x2 - x1, y2 - y1);

  const tNow = num(o.t, 0);
  const rawH = wrap(num(o.heading, 0));

  if (!mem._init) {
    const m = o.mission && typeof o.mission === "object" ? o.mission : {};
    const sz = m.size;
    let width = 400;
    let height = 400;

    if (typeof sz === "number") {
      width = height = sz;
    } else if (Array.isArray(sz)) {
      width = num(sz[0], 400);
      height = num(sz[1], width);
    } else if (sz && typeof sz === "object") {
      width = num(sz.width, num(sz.w, num(sz.x, 400)));
      height = num(sz.height, num(sz.h, num(sz.y, width)));
    }

    width = Math.max(50, width);
    height = Math.max(50, height);
    const base = m.base && typeof m.base === "object"
      ? m.base
      : { x: width * 0.5, y: height * 0.5 };

    mem.width = width;
    mem.height = height;
    mem.baseX = num(base.x, width * 0.5);
    mem.baseY = num(base.y, height * 0.5);
    mem.seconds = num(m.seconds, 1200);
    mem.capacity = Math.max(1, Math.floor(num(m.capacity, 5)));

    mem.hints = [];
    const hints = Array.isArray(m.hints) ? m.hints : [];
    for (let i = 0; i < hints.length; i++) {
      const h = hints[i] || {};
      const hx = clamp(num(h.x, mem.baseX), 4, width - 4);
      const hy = clamp(num(h.y, mem.baseY), 4, height - 4);
      mem.hints.push({
        x: hx,
        y: hy,
        value: Math.max(0.1, num(h.estimate, num(h.value, 1))),
        status: 0,
        phase: 0,
        step: 0,
        angle: (i * 0.57) % (2 * Math.PI),
        centerScience: 0,
        phaseStartScience: 0,
        bestScience: 0,
        bestX: hx,
        bestY: hy,
        anchorX: hx,
        anchorY: hy,
        anchorScience: 0,
        localScience: 0,
        localX: hx,
        localY: hy,
        loops: 0,
        outerTried: 0
      });
    }

    mem.globalPoints = [];
    for (let iy = 0; iy < 10; iy++) {
      for (let ix = 0; ix < 10; ix++) {
        mem.globalPoints.push({
          x: 18 + (width - 36) * ix / 9,
          y: 18 + (height - 36) * iy / 9,
          done: false
        });
      }
    }

    const x0 = num(o.x, width * 0.5);
    const y0 = num(o.y, height * 0.5);
    mem.px = x0;
    mem.py = y0;
    mem.theta = rawH;
    mem.headingBias = 0;
    mem.prevRawH = rawH;
    mem.prevT = tNow;
    mem.lastGpsX = x0;
    mem.lastGpsY = y0;
    mem.gpsUnchanged = 0;
    mem.gpsTravelSinceChange = 0;
    mem.gpsFrozen = false;
    mem.gpsRecover = 0;
    mem.compassHold = 0;
    mem.cal = { active: false, x: x0, y: y0, sin: 0, cos: 0, n: 0 };

    mem.gain = [[2.8, 2.8], [2.8, 2.8]];
    mem.dead = [[0.18, 0.18], [0.18, 0.18]];
    mem.noResponse = [0, 0];
    mem.motorStable = [0, 0];
    mem.motorStableTarget = [0, 0];
    mem.motorStableCmd = [0, 0];
    mem.lastCmd = [0, 0];
    mem.lastTarget = [0, 0];

    mem.rFilt = [];
    mem.rRaw = [];
    mem.rSameTime = [];
    mem.rSameMotion = [];
    mem.rBad = [];
    for (let i = 0; i < 9; i++) {
      mem.rFilt[i] = 15;
      mem.rRaw[i] = 15;
      mem.rSameTime[i] = 0;
      mem.rSameMotion[i] = 0;
      mem.rBad[i] = false;
    }
    mem.allMaxTravel = 0;
    mem.rangeTrust = 1;

    mem.energyRate = 0.0011;
    mem.energyUse = 0;
    mem.energyDist = 0;
    mem.prevBattery = clamp(num(o.battery, 1), 0, 1.8);

    mem.currentHint = -1;
    mem.globalIndex = -1;
    mem.ambient = null;
    mem.ambientLastX = -1e9;
    mem.ambientLastY = -1e9;

    mem.siteLock = null;
    mem.pendingMeta = null;
    mem.sampleActive = false;
    mem.sampleStart = 0;
    mem.sampleFailures = 0;
    mem.stillTime = 0;
    mem.holdI = [0, 0];
    mem.lastDrillProgress = 0;
    mem.lastDrillProgressT = tNow;

    mem.returning = false;
    mem.navKey = "";
    mem.navBest = 1e9;
    mem.navStuck = 0;
    mem.stuckCount = 0;
    mem.lastAim = 0;
    mem.avoidSign = 0;
    mem.avoidClearTime = 0;
    mem.recoverTimer = 0;
    mem.recoverSign = 1;
    mem.escapeUntil = 0;
    mem.escapeSign = 1;
    mem.prevBumped = false;
    mem.siteIgnoreUntil = 0;

    mem.prevCarried = Math.max(0, Math.floor(num(o.carried, 0)));
    mem.prevCarriedValue = num(o.carriedValue, 0);
    mem.prevDelivered = num(o.delivered, 0);
    mem.prevBeacon = null;
    mem.beaconSameTime = 0;
    mem.beaconSameMotion = 0;
    mem.beaconBad = false;
    mem.scienceEma = Math.max(0, num(o.science, 0));
    mem.samples = [];
    mem._init = true;
  }

  let dt = 0.1;
  if (Number.isFinite(mem.prevT)) {
    const d = tNow - mem.prevT;
    if (d > 0.02 && d <= 0.55) dt = d;
  }

  const width = num(mem.width, 400);
  const height = num(mem.height, 400);
  const rawX = num(o.x, num(mem.px, width * 0.5));
  const rawY = num(o.y, num(mem.py, height * 0.5));
  const wl = num(o.wheelLeft, 0);
  const wr = num(o.wheelRight, 0);
  const vWheel = (wl + wr) * 0.5;
  const wheelTravel = (Math.abs(wl) + Math.abs(wr)) * 0.5 * dt;
  const yawRad = ((wr - wl) / 0.6) * dt;
  const yawDeg = deg(yawRad);

  const battery = clamp(num(o.battery, mem.prevBattery), 0, 1.8);
  const solar = Math.max(0, num(o.solar, 0));
  const carried = Math.max(0, Math.floor(num(o.carried, 0)));
  const carriedValue = num(o.carriedValue, mem.prevCarriedValue);
  const delivered = num(o.delivered, mem.prevDelivered);
  const timeLeft = Math.max(0, num(o.timeLeft, mem.seconds - tNow));
  const drillProgress = Math.max(0, num(o.drilling, 0));
  const science = Math.max(0, num(o.science, 0));
  const siteObs = o.site && typeof o.site === "object" ? o.site : null;
  const beacon = o.beacon && typeof o.beacon === "object" ? o.beacon : null;

  const oldCarried = num(mem.prevCarried, carried);
  const oldCarriedValue = num(mem.prevCarriedValue, carriedValue);
  const oldDelivered = num(mem.prevDelivered, delivered);
  const sampleCompleted = carried > oldCarried;

  mem.scienceEma = num(mem.scienceEma, science) * 0.76 + science * 0.24;

  const rawRays = o.rays && typeof o.rays.length === "number" ? o.rays : null;
  let minRawRay = 15;
  if (rawRays) {
    for (let i = 0; i < 9; i++) {
      minRawRay = Math.min(minRawRay, clamp(num(rawRays[i], 15), 0, 15));
    }
  }

  const prevTheta = num(mem.theta, rawH);
  const rawDeltaH = wrap(rawH - num(mem.prevRawH, rawH));
  const compassJump =
    Math.abs(wrap(rawDeltaH - yawDeg)) > 72 && Math.abs(yawDeg) < 55;

  if (compassJump) mem.compassHold = 1.3;
  else mem.compassHold = Math.max(0, num(mem.compassHold, 0) - dt);

  let theta = wrap(prevTheta + yawDeg);
  if (!compassJump && mem.compassHold <= 0) {
    const corrected = wrap(rawH - num(mem.headingBias, 0));
    const residual = wrap(corrected - theta);
    if (Math.abs(residual) < 95) {
      theta = wrap(theta + clamp(residual * 0.075, -1.4, 1.4));
    }
  }
  mem.theta = theta;

  const gpsDelta = dist(
    rawX, rawY,
    num(mem.lastGpsX, rawX),
    num(mem.lastGpsY, rawY)
  );
  const gpsJump = gpsDelta > 12 && dt <= 0.55;

  if (gpsDelta < 0.025 && wheelTravel > 0.02) {
    mem.gpsUnchanged = num(mem.gpsUnchanged, 0) + dt;
    mem.gpsTravelSinceChange = num(mem.gpsTravelSinceChange, 0) + wheelTravel;
  } else if (gpsDelta > 0.08) {
    mem.gpsUnchanged = 0;
    mem.gpsTravelSinceChange = 0;
  }

  const wasGpsFrozen = !!mem.gpsFrozen;
  mem.gpsFrozen =
    num(mem.gpsUnchanged, 0) > 2.4 &&
    num(mem.gpsTravelSinceChange, 0) > 1.2;

  if (wasGpsFrozen && !mem.gpsFrozen) mem.gpsRecover = 1.4;
  else mem.gpsRecover = Math.max(0, num(mem.gpsRecover, 0) - dt);

  const midTheta = rad(wrap((prevTheta + theta) * 0.5));
  let motionScale = 1;
  if (mem.gpsFrozen && minRawRay < 1.35 && Math.abs(vWheel) > 0.13) {
    motionScale = 0.12;
  }

  let px = num(mem.px, rawX) +
    vWheel * dt * Math.cos(midTheta) * motionScale;
  let py = num(mem.py, rawY) +
    vWheel * dt * Math.sin(midTheta) * motionScale;

  if (!mem.gpsFrozen && !gpsJump) {
    const dx = rawX - px;
    const dy = rawY - py;
    const residual = Math.hypot(dx, dy);
    if (residual < 25) {
      let alpha = Math.abs(vWheel) > 0.18 ? 0.32 : 0.16;
      if (gpsDelta > 0.4) alpha = 0.40;
      const limit = Math.abs(vWheel) > 0.18 ? 1.7 : 0.7;
      const scale = residual > limit ? limit / residual : 1;
      px += dx * scale * alpha;
      py += dy * scale * alpha;
    }
  } else if (mem.gpsRecover > 0) {
    const dx = rawX - px;
    const dy = rawY - py;
    const residual = Math.hypot(dx, dy);
    if (residual < 35) {
      const limit = residual > 5 ? 5 / residual : 1;
      px += dx * limit * 0.40;
      py += dy * limit * 0.40;
    }
  }

  mem.px = px;
  mem.py = py;
  mem.lastGpsX = rawX;
  mem.lastGpsY = rawY;
  mem.prevRawH = rawH;

  if (!mem.cal || typeof mem.cal !== "object") {
    mem.cal = { active: false, x: rawX, y: rawY, sin: 0, cos: 0, n: 0 };
  }
  const straightForward =
    vWheel > 0.30 &&
    Math.abs(wr - wl) < 0.24 &&
    !mem.gpsFrozen &&
    !gpsJump &&
    !compassJump;

  if (straightForward) {
    if (!mem.cal.active) {
      mem.cal.active = true;
      mem.cal.x = rawX;
      mem.cal.y = rawY;
      mem.cal.sin = 0;
      mem.cal.cos = 0;
      mem.cal.n = 0;
    }

    mem.cal.sin += Math.sin(rad(rawH));
    mem.cal.cos += Math.cos(rad(rawH));
    mem.cal.n += 1;

    if (dist(rawX, rawY, mem.cal.x, mem.cal.y) >= 9 && mem.cal.n >= 12) {
      const course = deg(Math.atan2(rawY - mem.cal.y, rawX - mem.cal.x));
      const meanRaw = deg(Math.atan2(mem.cal.sin, mem.cal.cos));
      const estimate = wrap(meanRaw - course);
      const err = wrap(estimate - num(mem.headingBias, 0));
      if (Math.abs(err) < 60) {
        mem.headingBias = wrap(
          num(mem.headingBias, 0) + clamp(err * 0.07, -1.2, 1.2)
        );
      }
      mem.cal.x = rawX;
      mem.cal.y = rawY;
      mem.cal.sin = 0;
      mem.cal.cos = 0;
      mem.cal.n = 0;
    }
  } else {
    mem.cal.active = false;
    mem.cal.sin = 0;
    mem.cal.cos = 0;
    mem.cal.n = 0;
  }

  if (!Array.isArray(mem.gain) || mem.gain.length < 2) {
    mem.gain = [[2.8, 2.8], [2.8, 2.8]];
  }
  if (!Array.isArray(mem.dead) || mem.dead.length < 2) {
    mem.dead = [[0.18, 0.18], [0.18, 0.18]];
  }
  if (!Array.isArray(mem.lastCmd) || mem.lastCmd.length < 2) mem.lastCmd = [0, 0];
  if (!Array.isArray(mem.lastTarget) || mem.lastTarget.length < 2) mem.lastTarget = [0, 0];
  if (!Array.isArray(mem.noResponse) || mem.noResponse.length < 2) mem.noResponse = [0, 0];
  if (!Array.isArray(mem.motorStable) || mem.motorStable.length < 2) mem.motorStable = [0, 0];
  if (!Array.isArray(mem.motorStableTarget) || mem.motorStableTarget.length < 2) {
    mem.motorStableTarget = [0, 0];
  }
  if (!Array.isArray(mem.motorStableCmd) || mem.motorStableCmd.length < 2) {
    mem.motorStableCmd = [0, 0];
  }

  for (let s = 0; s < 2; s++) {
    if (!Array.isArray(mem.gain[s])) mem.gain[s] = [2.8, 2.8];
    if (!Array.isArray(mem.dead[s])) mem.dead[s] = [0.18, 0.18];

    const lastCmd = num(mem.lastCmd[s], 0);
    const lastTarget = num(mem.lastTarget[s], 0);
    const actual = s === 0 ? wl : wr;
    const direction = lastTarget < 0 ? 1 : 0;
    const dead = clamp(num(mem.dead[s][direction], 0.18), 0.10, 0.46);

    const stableTarget = num(mem.motorStableTarget[s], lastTarget);
    const stableCmd = num(mem.motorStableCmd[s], lastCmd);
    const consistent =
      Math.abs(lastTarget) > 0.13 &&
      Math.abs(lastCmd) > dead + 0.04 &&
      Math.sign(stableTarget) === Math.sign(lastTarget) &&
      Math.abs(lastTarget - stableTarget) < 0.10 &&
      Math.abs(lastCmd - stableCmd) < 0.09;

    if (consistent) mem.motorStable[s] = num(mem.motorStable[s], 0) + dt;
    else mem.motorStable[s] = 0;

    if (mem.motorStable[s] > 0.45) {
      if (actual * lastTarget > 0 && Math.abs(actual) > 0.07) {
        const ratio = Math.abs(actual) /
          Math.max(0.08, Math.abs(lastCmd) - dead);
        if (ratio > 0.45 && ratio < 6.0) {
          const old = num(mem.gain[s][direction], 2.8);
          mem.gain[s][direction] = clamp(old + (ratio - old) * 0.016, 0.75, 5.8);
        }
      }

      if (Math.abs(actual) < 0.045 && Math.abs(lastCmd) > dead + 0.04) {
        mem.noResponse[s] = num(mem.noResponse[s], 0) + dt;
        if (mem.noResponse[s] > 0.8) {
          mem.dead[s][direction] = clamp(
            num(mem.dead[s][direction], 0.18) + 0.006,
            0.12,
            0.46
          );
        }
      } else {
        mem.noResponse[s] = 0;
      }
    } else {
      mem.noResponse[s] = 0;
    }

    if (Math.abs(actual) > 0.22 &&
        Math.abs(lastCmd) > dead + 0.02 &&
        actual * lastTarget > 0) {
      mem.dead[s][direction] = Math.max(
        0.11,
        num(mem.dead[s][direction], 0.18) - 0.00015
      );
    }

    mem.motorStableTarget[s] = lastTarget;
    mem.motorStableCmd[s] = lastCmd;
  }

  const prevBattery = num(mem.prevBattery, battery);
  if (!o.docked && (wheelTravel > 0.012 || drillProgress > 0.05)) {
    const gross = clamp(
      prevBattery - battery + solar * dt * 0.18,
      0,
      0.025
    );
    mem.energyUse = num(mem.energyUse, 0) + gross;
    mem.energyDist = num(mem.energyDist, 0) +
      wheelTravel +
      (drillProgress > 0.05 ? dt * 0.06 : 0);

    if (mem.energyDist >= 18) {
      const loadFactor = 1 + 0.15 * carried;
      const measured = clamp(
        mem.energyUse / Math.max(6, mem.energyDist) / loadFactor,
        0.00035,
        0.007
      );
      const oldRate = num(mem.energyRate, 0.0011);
      const alpha = measured > oldRate ? 0.19 : 0.045;
      mem.energyRate = clamp(oldRate + (measured - oldRate) * alpha, 0.00045, 0.007);
      mem.energyUse = 0;
      mem.energyDist = 0;
    }
  }

  if (!Array.isArray(mem.rFilt) || mem.rFilt.length !== 9) {
    mem.rFilt = [];
    mem.rRaw = [];
    mem.rSameTime = [];
    mem.rSameMotion = [];
    mem.rBad = [];
    for (let i = 0; i < 9; i++) {
      mem.rFilt[i] = 15;
      mem.rRaw[i] = 15;
      mem.rSameTime[i] = 0;
      mem.rSameMotion[i] = 0;
      mem.rBad[i] = false;
    }
  }

  let allMax = true;
  let anyNear = false;
  let minEffectiveRay = 15;
  const sensorMotion = wheelTravel + Math.abs(yawRad) * 0.35;

  for (let i = 0; i < 9; i++) {
    const r = clamp(rawRays ? num(rawRays[i], 15) : 15, 0, 15);
    const last = num(mem.rRaw[i], r);
    const diff = Math.abs(r - last);

    if (diff < 0.025) {
      if (sensorMotion > 0.025) {
        mem.rSameTime[i] = num(mem.rSameTime[i], 0) + dt;
        mem.rSameMotion[i] = num(mem.rSameMotion[i], 0) + sensorMotion;
      }
    } else if (diff > 0.25) {
      mem.rSameTime[i] = 0;
      mem.rSameMotion[i] = 0;
      mem.rBad[i] = false;
    }

    if (mem.rSameTime[i] > 9 &&
        mem.rSameMotion[i] > 5 &&
        r < 14.5) {
      mem.rBad[i] = true;
    }

    const effective = mem.rBad[i] ? 15 : r;
    minEffectiveRay = Math.min(minEffectiveRay, effective);
    if (effective < 14.8) allMax = false;
    if (effective < 14.2) anyNear = true;

    let f = num(mem.rFilt[i], 15);
    const a = effective < f ? 0.70 : 0.30;
    f += (effective - f) * a;
    mem.rFilt[i] = clamp(f, 0, 15);
    mem.rRaw[i] = r;
  }

  if (allMax && wheelTravel > 0.02) {
    mem.allMaxTravel = num(mem.allMaxTravel, 0) + wheelTravel;
  } else if (anyNear) {
    mem.allMaxTravel = Math.max(
      0,
      num(mem.allMaxTravel, 0) - wheelTravel * 1.1
    );
  }
  mem.rangeTrust = mem.allMaxTravel > 22 ? 0.76 : 1;

  if (beacon) {
    const bd = Math.max(0, num(beacon.distance, 99));
    const bb = num(beacon.bearing, 0);
    const pb = mem.prevBeacon;

    if (pb &&
        sensorMotion > 0.02 &&
        Math.abs(bd - num(pb.d, bd)) < 0.018 &&
        Math.abs(wrap(bb - num(pb.b, bb))) < 0.22) {
      mem.beaconSameTime = num(mem.beaconSameTime, 0) + dt;
      mem.beaconSameMotion = num(mem.beaconSameMotion, 0) + sensorMotion;
      if (mem.beaconSameTime > 6 && mem.beaconSameMotion > 2.7) {
        mem.beaconBad = true;
      }
    } else if (!pb ||
               Math.abs(bd - num(pb.d, bd)) > 0.08 ||
               Math.abs(wrap(bb - num(pb.b, bb))) > 1) {
      mem.beaconSameTime = 0;
      mem.beaconSameMotion = 0;
      mem.beaconBad = false;
    }

    mem.prevBeacon = { d: bd, b: bb };
  } else {
    mem.prevBeacon = null;
    mem.beaconSameTime = 0;
    mem.beaconSameMotion = 0;
  }

  const poseX = num(mem.px, rawX);
  const poseY = num(mem.py, rawY);

  if (sampleCompleted) {
    const meta = mem.pendingMeta || mem.siteLock || {
      x: poseX,
      y: poseY,
      value: 1
    };
    const mx = num(meta.x, poseX);
    const my = num(meta.y, poseY);
    let value = Math.max(0.1, num(meta.value, 1));
    const valueGain = carriedValue - oldCarriedValue;
    if (valueGain > 0.01) {
      value = valueGain / Math.max(1, carried - oldCarried);
    }
    mem.samples.push({ x: mx, y: my, value: value });

    let associated = -1;
    let nearestD = 40;
    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (!h || h.status >= 2) continue;
      const d = dist(mx, my, h.x, h.y);
      if (d < nearestD) {
        nearestD = d;
        associated = i;
      }
    }

    const currentHint = Math.floor(num(mem.currentHint, -1));
    if (currentHint >= 0 &&
        currentHint < mem.hints.length &&
        mem.hints[currentHint] &&
        mem.hints[currentHint].status < 2 &&
        dist(mx, my, mem.hints[currentHint].x, mem.hints[currentHint].y) < 43) {
      associated = currentHint;
    }

    if (associated >= 0) {
      mem.hints[associated].status = 2;
      if (associated === currentHint) mem.currentHint = -1;
    }

    for (let i = 0; i < mem.globalPoints.length; i++) {
      const p = mem.globalPoints[i];
      if (p && dist(mx, my, p.x, p.y) < 14) p.done = true;
    }

    if (mem.ambient && dist(mx, my, mem.ambient.x, mem.ambient.y) < 30) {
      mem.ambient = null;
    }

    mem.sampleActive = false;
    mem.pendingMeta = null;
    mem.siteLock = null;
    mem.stillTime = 0;
    mem.holdI = [0, 0];
    mem.navKey = "";
    mem.lastDrillProgress = 0;
    mem.lastDrillProgressT = tNow;
  } else if (carried < oldCarried || delivered > oldDelivered) {
    mem.sampleActive = false;
    mem.pendingMeta = null;
    mem.siteLock = null;
    mem.stillTime = 0;
    mem.holdI = [0, 0];
  }

  if (siteObs && carried < mem.capacity) {
    const sd = Math.max(0, num(siteObs.distance, 99));
    const sb = num(siteObs.bearing, 0);
    const a = rad(mem.theta + sb);
    const sx = poseX + sd * Math.cos(a);
    const sy = poseY + sd * Math.sin(a);
    const sv = Math.max(0.1, num(siteObs.value, 1));

    if (!mem.siteLock) {
      mem.siteLock = { x: sx, y: sy, value: sv, lastSeen: tNow };
    } else {
      const gap = dist(mem.siteLock.x, mem.siteLock.y, sx, sy);
      if (gap > 9) {
        mem.siteLock.x = sx;
        mem.siteLock.y = sy;
      } else {
        mem.siteLock.x = mem.siteLock.x * 0.68 + sx * 0.32;
        mem.siteLock.y = mem.siteLock.y * 0.68 + sy * 0.32;
      }
      mem.siteLock.value = sv;
      mem.siteLock.lastSeen = tNow;
    }
  } else if (mem.siteLock &&
             !mem.sampleActive &&
             tNow - num(mem.siteLock.lastSeen, tNow) > 13) {
    mem.siteLock = null;
  }

  if (!sampleCompleted && !mem.sampleActive && drillProgress > 0.05) {
    mem.sampleActive = true;
    mem.sampleStart = tNow - drillProgress;
    mem.lastDrillProgress = drillProgress;
    mem.lastDrillProgressT = tNow;
    if (mem.siteLock) {
      mem.pendingMeta = {
        x: mem.siteLock.x,
        y: mem.siteLock.y,
        value: mem.siteLock.value
      };
    }
  }

  const baseX = num(mem.baseX, width * 0.5);
  const baseY = num(mem.baseY, height * 0.5);
  const baseDist = dist(poseX, poseY, baseX, baseY);
  const beaconDistRaw = beacon ? Math.max(0, num(beacon.distance, 99)) : 99;
  const beaconUsable = !!beacon && !mem.beaconBad && beaconDistRaw <= 20.5;
  const beaconDist = beaconUsable ? beaconDistRaw : 99;
  const maxWheel = Math.max(Math.abs(wl), Math.abs(wr));
  const atBase = !!o.docked ||
    (beaconUsable && beaconDist <= 2.65) ||
    (baseDist <= 2.5 && maxWheel < 0.23);
  const homeDist = beaconUsable ? beaconDist : baseDist;
  const scienceNow = science;

  function routeFeasible(out, home, load) {
    const l = Math.max(0, load);
    const route = Math.max(0, out) + Math.max(0, home) + 12;
    const need =
      0.12 +
      route * num(mem.energyRate, 0.0011) * (1 + 0.16 * l) * 1.34 +
      0.02 * l;
    const seconds = route * 3.15 + 38 + 6 * l;
    return need <= battery - 0.025 && seconds <= timeLeft - 8;
  }

  function homeNeed(d, load) {
    const l = Math.max(0, load);
    return 0.11 +
      Math.max(0, d + 8) * num(mem.energyRate, 0.0011) *
        (1 + 0.16 * l) * 1.45 +
      0.02 * l;
  }

  function homeSeconds(d, load) {
    return Math.max(0, d) * 3.2 + 35 + 7 * Math.max(0, load);
  }

  function emit(c, drill) {
    const left = clamp(num(c && c.left, 0), -1, 1);
    const right = clamp(num(c && c.right, 0), -1, 1);
    mem.lastCmd = [left, right];
    mem.lastTarget = [num(c && c.tl, 0), num(c && c.tr, 0)];
    mem.prevT = tNow;
    mem.prevBattery = battery;
    mem.prevCarried = carried;
    mem.prevCarriedValue = carriedValue;
    mem.prevDelivered = delivered;
    return { left: left, right: right, drill: !!drill };
  }

  function motorPower(target, actual, side) {
    const t = clamp(target, -0.45, 0.45);
    const a = num(actual, 0);
    const absT = Math.abs(t);
    const absA = Math.abs(a);
    const direction = t < -0.015 ? 1 : 0;
    const gain = clamp(num(mem.gain[side][direction], 2.8), 0.75, 5.8);
    const dead = clamp(num(mem.dead[side][direction], 0.18), 0.10, 0.46);

    if (absT < 0.035) {
      if (absA < 0.065) return 0;
      let brake = dead + absA / gain * 0.60;
      if (absA > 0.70) brake = Math.max(brake, 0.34);
      return clamp(-Math.sign(a) * brake, -0.58, 0.58);
    }

    if (a * t > 0 && absA > absT + 0.11) {
      const excess = Math.max(0, absA - absT);
      const brake = clamp(dead + excess / gain * 0.62, dead, 0.46);
      return clamp(-Math.sign(a) * brake, -0.58, 0.58);
    }

    if (absA > 0.86) {
      return clamp(-Math.sign(a) * Math.max(0.34, dead + absA / gain * 0.48), -0.58, 0.58);
    }

    const error = t - a;
    let u = Math.sign(t) * (dead + absT / gain) +
      clamp(error * 0.36 / gain, -0.12, 0.12);

    if (u * t > 0 && Math.abs(u) < dead + 0.02) {
      u = Math.sign(t) * (dead + 0.02);
    }
    return clamp(u, -0.62, 0.62);
  }

  function wheelCommands(v, omega) {
    const lt = clamp(v - 0.3 * omega, -0.45, 0.45);
    const rt = clamp(v + 0.3 * omega, -0.45, 0.45);
    return {
      left: motorPower(lt, wl, 0),
      right: motorPower(rt, wr, 1),
      tl: lt,
      tr: rt
    };
  }

  function stopCommands() {
    return wheelCommands(0, 0);
  }

  function holdCommands() {
    if (!Array.isArray(mem.holdI) || mem.holdI.length < 2) mem.holdI = [0, 0];

    const pitch = num(o.pitch, 0);
    const actuals = [wl, wr];
    const out = [];
    const meanDead =
      (num(mem.dead[0][0], 0.18) + num(mem.dead[1][0], 0.18)) * 0.5;
    let pitchFeed = 0;
    if (Math.abs(pitch) > 1.1) {
      pitchFeed = Math.sign(pitch) *
        (meanDead + Math.min(0.14, Math.abs(pitch) * 0.008));
    }

    for (let i = 0; i < 2; i++) {
      const actual = actuals[i];
      let integral = num(mem.holdI[i], 0);

      if (Math.abs(actual) > 0.04) {
        integral = clamp(integral - actual * 1.45 * dt, -0.48, 0.48);
      } else if (Math.abs(pitch) < 2.3) {
        integral *= 0.45;
        if (Math.abs(integral) < 0.10) integral = 0;
      } else {
        integral *= 0.99;
      }

      let u = integral - 0.82 * actual + pitchFeed;
      if (Math.abs(actual) < 0.035 && Math.abs(pitch) < 2.3) {
        integral = 0;
        u = 0;
      }

      mem.holdI[i] = integral;
      out[i] = clamp(u, -0.50, 0.50);
    }

    return { left: out[0], right: out[1], tl: 0, tr: 0 };
  }

  function rayAt(angle) {
    const a = clamp(angle, -80, 80);
    const q = (a + 80) / 20;
    const i = Math.floor(q);
    const f = q - i;
    if (i >= 8) return num(mem.rFilt[8], 15);
    return num(mem.rFilt[i], 15) * (1 - f) + num(mem.rFilt[i + 1], 15) * f;
  }

  function clearanceAt(angle) {
    const center = rayAt(angle);
    const side = Math.min(rayAt(angle - 20), rayAt(angle + 20));
    return Math.min(center, center * 0.76 + side * 0.24);
  }

  function edgeDistance(angle) {
    const a = rad(wrap(mem.theta + angle));
    const dx = Math.cos(a);
    const dy = Math.sin(a);
    const margin = 4;
    let d = 1e6;

    if (dx > 0.001) d = Math.min(d, (width - margin - poseX) / dx);
    if (dx < -0.001) d = Math.min(d, (margin - poseX) / dx);
    if (dy > 0.001) d = Math.min(d, (height - margin - poseY) / dy);
    if (dy < -0.001) d = Math.min(d, (margin - poseY) / dy);

    return Math.max(0, d);
  }

  function openSide() {
    let leftOpen = 0;
    let rightOpen = 0;
    for (let i = 5; i < 9; i++) leftOpen += num(mem.rFilt[i], 15);
    for (let i = 0; i < 4; i++) rightOpen += num(mem.rFilt[i], 15);
    if (Math.abs(leftOpen - rightOpen) < 0.5) {
      return mem.avoidSign ? -mem.avoidSign : 1;
    }
    return leftOpen >= rightOpen ? 1 : -1;
  }

  function navCommands(goalError, maxV) {
    const goal = wrap(num(goalError, 0));
    let vmax = clamp(num(maxV, 0.34), 0, 0.40);
    if (mem.rangeTrust < 0.9) vmax = Math.min(vmax, 0.27);
    if (maxWheel > 0.72) vmax = Math.min(vmax, 0.14);
    if (maxWheel > 0.94) vmax = 0.025;

    const front = clearanceAt(0);
    const safe = 1.55 + vmax * 0.70;

    if (front < 0.38 && tNow >= num(mem.escapeUntil, 0)) {
      mem.escapeSign = openSide();
      mem.escapeUntil = tNow + 1.25;
    }
    if (tNow < num(mem.escapeUntil, 0)) {
      const rem = mem.escapeUntil - tNow;
      const s = num(mem.escapeSign, 1);
      if (rem > 0.58) return wheelCommands(-0.16, s * 0.50);
      return wheelCommands(0, s * 0.60);
    }

    if (Math.abs(goal) > 128) {
      return wheelCommands(0, Math.sign(goal) * 0.58);
    }

    if (front > safe + 0.9 && mem.avoidSign) {
      mem.avoidClearTime = num(mem.avoidClearTime, 0) + dt;
      if (mem.avoidClearTime > 1.25) {
        mem.avoidSign = 0;
        mem.avoidClearTime = 0;
      }
    } else if (front < safe) {
      mem.avoidClearTime = 0;
      if (!mem.avoidSign) mem.avoidSign = openSide();
    }

    let aimGoal = clamp(goal, -80, 80);
    if (mem.avoidSign && front < safe + 0.8) {
      const offset = front < safe ? 52 : 30;
      aimGoal = clamp(goal + num(mem.avoidSign, 1) * offset, -80, 80);
    }

    const candidates = [];
    for (let a = -80; a <= 80; a += 10) candidates.push(a);
    candidates.push(clamp(goal, -80, 80), aimGoal);

    let best = aimGoal;
    let bestClear = clearanceAt(best);
    let bestCost = 1e9;

    for (let i = 0; i < candidates.length; i++) {
      const a = candidates[i];
      const clear = clearanceAt(a);
      let cost = Math.abs(wrap(a - aimGoal)) * 0.027;

      const hazard = Math.max(0, safe - clear);
      cost += hazard * hazard * 3.1;
      if (clear < 0.92) cost += 6;
      if (clear < 0.58) cost += 16;

      const edge = edgeDistance(a);
      if (edge < 1.8) cost += 17;
      else if (edge < 7) cost += (7 - edge) * 0.90;

      if (front < safe && mem.avoidSign &&
          a * mem.avoidSign < -12) {
        cost += 0.28;
      }
      if (front < safe + 0.6) {
        cost += Math.abs(a - num(mem.lastAim, a)) * 0.003;
      }

      if (cost < bestCost) {
        bestCost = cost;
        best = a;
        bestClear = clear;
      }
    }

    if (front < safe && Math.abs(best) > 12) {
      mem.avoidSign = Math.sign(best);
      mem.avoidClearTime = 0;
    }
    mem.lastAim = best;

    let v = vmax * Math.max(0.38, Math.cos(rad(best)));
    const clearScale = clamp(
      (bestClear - 0.50) / Math.max(0.85, safe - 0.50),
      0.12,
      1
    );
    v *= clearScale;

    if (front < 1.35) v = Math.min(v, 0.14);
    if (bestClear < 1.0) v = Math.min(v, 0.09);
    if (front < 0.72 && Math.abs(best) < 22) v = 0;
    if (Math.abs(best) > 56) v = 0;

    const omega = clamp(1.50 * rad(best), -0.82, 0.82);
    return wheelCommands(v, omega);
  }

  function recoveryAction() {
    const rem = Math.max(0, num(mem.recoverTimer, 0));
    const s = num(mem.recoverSign, 1);
    let c;
    if (rem > 0.68) c = wheelCommands(-0.19, s * 0.52);
    else c = wheelCommands(0, s * 0.60);
    mem.recoverTimer = Math.max(0, rem - dt);
    return emit(c, false);
  }

  function ringPoint(cx, cy, step, count, radius, offset) {
    const a = num(offset, 0) + 2 * Math.PI * step / count;
    return {
      x: clamp(cx + radius * Math.cos(a), 4, width - 4),
      y: clamp(cy + radius * Math.sin(a), 4, height - 4)
    };
  }

  function finishSearch(s, index, kind) {
    if (kind === "hint") {
      s.status = 2;
      if (Math.floor(num(mem.currentHint, -1)) === index) mem.currentHint = -1;
    } else {
      mem.ambientLastX = s.x;
      mem.ambientLastY = s.y;
      mem.ambient = null;
    }
  }

  function beginClimb(s) {
    s.phase = 3;
    s.step = 0;
    s.anchorX = num(s.bestX, s.x);
    s.anchorY = num(s.bestY, s.y);
    s.anchorScience = num(s.bestScience, 0);
    s.localScience = s.anchorScience;
    s.localX = s.anchorX;
    s.localY = s.anchorY;
    s.loops = 0;
  }

  function searchInfo(s, index, kind) {
    if (!s) return null;
    if (kind === "hint" && s.status >= 2) return null;

    for (let tries = 0; tries < 12; tries++) {
      if (Math.floor(num(s.phase, 0)) === 0) {
        const d = dist(poseX, poseY, s.x, s.y);
        if (d > 3.4) {
          return {
            kind: kind,
            index: index,
            phase: 0,
            step: 0,
            x: s.x,
            y: s.y,
            dist: d,
            home: dist(s.x, s.y, baseX, baseY) + 6,
            extra: 42,
            key: kind + ":c:" + index
          };
        }

        s.phase = 1;
        s.step = 0;
        s.centerScience = num(mem.scienceEma, scienceNow);
        s.phaseStartScience = s.centerScience;
        s.bestScience = Math.max(num(s.bestScience, 0), scienceNow);
        s.bestX = poseX;
        s.bestY = poseY;
        s.anchorX = poseX;
        s.anchorY = poseY;
        s.anchorScience = s.centerScience;
        s.localScience = s.centerScience;
        s.localX = poseX;
        s.localY = poseY;
        s.loops = 0;
        s.outerTried = 0;
        continue;
      }

      const centerDistance = dist(poseX, poseY, s.x, s.y);
      if (centerDistance < 40 &&
          scienceNow > num(s.bestScience, 0) + 0.03) {
        s.bestScience = scienceNow;
        s.bestX = poseX;
        s.bestY = poseY;
      }

      if (Math.floor(num(s.phase, 0)) === 3 &&
          dist(poseX, poseY, s.anchorX, s.anchorY) < 12 &&
          scienceNow > num(s.localScience, 0) + 0.03) {
        s.localScience = scienceNow;
        s.localX = poseX;
        s.localY = poseY;
      }

      let count;
      let radius;
      let cx;
      let cy;
      const phase = Math.floor(num(s.phase, 0));

      if (phase === 1) {
        count = 8;
        radius = 7.5;
        cx = s.x;
        cy = s.y;
      } else if (phase === 2) {
        count = 12;
        radius = 16;
        cx = s.x;
        cy = s.y;
      } else {
        count = 6;
        radius = 5;
        cx = s.anchorX;
        cy = s.anchorY;
      }

      let step = Math.max(0, Math.floor(num(s.step, 0)));
      if (step >= count) {
        if (phase === 1) {
          if (num(s.bestScience, 0) >
                num(s.centerScience, 0) + 0.045 &&
              dist(s.bestX, s.bestY, s.x, s.y) > 2.5) {
            beginClimb(s);
          } else {
            s.phase = 2;
            s.step = 0;
            s.outerTried = 1;
            s.phaseStartScience = num(s.bestScience, 0);
          }
          continue;
        }

        if (phase === 2) {
          if (num(s.bestScience, 0) >
                num(s.phaseStartScience, 0) + 0.045 &&
              dist(s.bestX, s.bestY, s.x, s.y) > 2.7) {
            beginClimb(s);
          } else {
            finishSearch(s, index, kind);
            return null;
          }
          continue;
        }

        if (num(s.localScience, 0) >
              num(s.anchorScience, 0) + 0.035 &&
            dist(s.localX, s.localY, s.anchorX, s.anchorY) > 1.8 &&
            num(s.loops, 0) < 3) {
          s.anchorX = s.localX;
          s.anchorY = s.localY;
          s.anchorScience = s.localScience;
          s.localScience = s.anchorScience;
          s.localX = s.anchorX;
          s.localY = s.anchorY;
          s.loops = num(s.loops, 0) + 1;
          s.step = 0;
          continue;
        }

        if (!s.outerTried) {
          s.phase = 2;
          s.step = 0;
          s.outerTried = 1;
          s.phaseStartScience = num(s.bestScience, 0);
          continue;
        }

        finishSearch(s, index, kind);
        return null;
      }

      const p = ringPoint(cx, cy, step, count, radius, s.angle);
      const d = dist(poseX, poseY, p.x, p.y);

      if (d <= 2.8) {
        s.step = step + 1;
        continue;
      }

      const arc = 2 * Math.PI * radius / count;
      const extra = Math.max(0, count - step - 1) * arc;
      return {
        kind: kind,
        index: index,
        phase: phase,
        step: step,
        x: p.x,
        y: p.y,
        dist: d,
        home: dist(p.x, p.y, baseX, baseY) + 6,
        extra: extra,
        key: kind + ":r:" + index + ":" + phase + ":" + step
      };
    }

    return null;
  }

  function skipTarget(info) {
    if (!info) return;

    if (info.kind === "hint" &&
        info.index >= 0 &&
        info.index < mem.hints.length) {
      const h = mem.hints[info.index];
      if (!h) return;

      if (Math.floor(num(h.phase, 0)) === 0) {
        h.phase = 1;
        h.step = 0;
        h.centerScience = num(mem.scienceEma, scienceNow);
        h.bestScience = h.centerScience;
        h.bestX = poseX;
        h.bestY = poseY;
        h.anchorX = poseX;
        h.anchorY = poseY;
        h.outerTried = 0;
      } else {
        h.step = Math.max(0, Math.floor(num(h.step, 0))) + 1;
      }
    } else if (info.kind === "ambient" && mem.ambient) {
      mem.ambient.step =
        Math.max(0, Math.floor(num(mem.ambient.step, 0))) + 1;
    } else if (info.kind === "global" &&
               info.index >= 0 &&
               info.index < mem.globalPoints.length) {
      mem.globalPoints[info.index].done = true;
      mem.globalIndex = -1;
    } else if (info.kind === "site") {
      mem.siteLock = null;
      mem.siteIgnoreUntil = tNow + 8;
    }
  }

  function updateProgress(key, d, info) {
    if (mem.navKey !== key) {
      mem.navKey = key;
      mem.navBest = d;
      mem.navStuck = 0;
      mem.stuckCount = 0;
      return false;
    }

    if (d < num(mem.navBest, d) - 0.38) {
      mem.navBest = d;
      mem.navStuck = 0;
      mem.stuckCount = 0;
      return false;
    }

    const stuckScale =
      mem.gpsFrozen && minEffectiveRay < 1.45 ? 1.35 : 1;
    mem.navStuck = num(mem.navStuck, 0) + dt * stuckScale;

    if (mem.navStuck > 11.5) {
      mem.navStuck = 0;
      mem.navBest = d;
      mem.stuckCount = num(mem.stuckCount, 0) + 1;
      mem.recoverSign = mem.avoidSign ? -mem.avoidSign : openSide();
      mem.avoidSign = mem.recoverSign;
      mem.avoidClearTime = 0;
      mem.recoverTimer = 1.75;

      if (mem.stuckCount >= 2) {
        skipTarget(info);
        mem.navKey = "";
        mem.stuckCount = 0;
      }
      return true;
    }

    return false;
  }

  function hintInfo(index) {
    const h = mem.hints[index];
    if (!h || h.status >= 2) return null;
    return searchInfo(h, index, "hint");
  }

  function chooseHint() {
    let best = -1;
    let bestScore = -1;
    let bestInfo = null;

    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (!h || h.status >= 2) continue;

      const info = hintInfo(i);
      if (!info || !routeFeasible(info.dist, info.home, carried + 1)) continue;

      let score = Math.pow(Math.max(0.1, num(h.value, 1)), 1.16) /
        (45 + info.dist + 0.52 * info.home + 0.30 * info.extra + 9 * carried);
      if (h.status === 1) score *= 1.06;
      if (i === Math.floor(num(mem.currentHint, -1))) score *= 1.08;

      if (score > bestScore) {
        bestScore = score;
        best = i;
        bestInfo = info;
      }
    }

    if (best >= 0) {
      mem.currentHint = best;
      mem.hints[best].status = 1;
      return bestInfo;
    }

    return null;
  }

  function globalInfo(index) {
    const p = mem.globalPoints[index];
    if (!p || p.done) return null;

    const d = dist(poseX, poseY, p.x, p.y);
    if (d <= 3.3) {
      p.done = true;
      if (Math.floor(num(mem.globalIndex, -1)) === index) {
        mem.globalIndex = -1;
      }
      return null;
    }

    return {
      kind: "global",
      index: index,
      x: p.x,
      y: p.y,
      dist: d,
      home: dist(p.x, p.y, baseX, baseY) + 6,
      extra: 0,
      key: "g:" + index
    };
  }

  function chooseGlobal() {
    const old = Math.floor(num(mem.globalIndex, -1));
    if (old >= 0 && old < mem.globalPoints.length) {
      const info = globalInfo(old);
      if (info && routeFeasible(info.dist, info.home, carried + 1)) {
        return info;
      }
      mem.globalIndex = -1;
    }

    let best = -1;
    let bestScore = -1;
    let bestInfo = null;

    for (let i = 0; i < mem.globalPoints.length; i++) {
      const info = globalInfo(i);
      if (!info || !routeFeasible(info.dist, info.home, carried + 1)) continue;

      const score = 1 / (42 + info.dist + 0.52 * info.home + 8 * carried);
      if (score > bestScore) {
        bestScore = score;
        best = i;
        bestInfo = info;
      }
    }

    mem.globalIndex = best;
    return bestInfo;
  }

  function maybeStartAmbient() {
    if (mem.ambient || scienceNow < 0.67) return;

    const lastD = dist(
      poseX, poseY,
      num(mem.ambientLastX, -1e9),
      num(mem.ambientLastY, -1e9)
    );
    if (lastD <= 24) return;

    const ci = Math.floor(num(mem.currentHint, -1));
    let nearCurrent = false;
    if (ci >= 0 && ci < mem.hints.length && mem.hints[ci] &&
        mem.hints[ci].status < 2) {
      nearCurrent = dist(poseX, poseY, mem.hints[ci].x, mem.hints[ci].y) < 30;
    }
    if (nearCurrent && scienceNow < 1.45) return;

    mem.ambient = {
      x: poseX,
      y: poseY,
      phase: 1,
      step: 0,
      angle: 0,
      centerScience: num(mem.scienceEma, scienceNow),
      phaseStartScience: num(mem.scienceEma, scienceNow),
      bestScience: scienceNow,
      bestX: poseX,
      bestY: poseY,
      anchorX: poseX,
      anchorY: poseY,
      anchorScience: num(mem.scienceEma, scienceNow),
      localScience: num(mem.scienceEma, scienceNow),
      localX: poseX,
      localY: poseY,
      loops: 0,
      outerTried: 0
    };
  }

  function getTask() {
    maybeStartAmbient();

    let current = Math.floor(num(mem.currentHint, -1));
    if (current >= 0 &&
        current < mem.hints.length &&
        mem.hints[current] &&
        mem.hints[current].status < 2) {
      const info = hintInfo(current);
      if (info && routeFeasible(info.dist, info.home, carried + 1)) {
        return info;
      }
      mem.currentHint = -1;
    } else {
      mem.currentHint = -1;
    }

    const hinfo = chooseHint();
    if (hinfo) return hinfo;

    if (mem.ambient) {
      const ainfo = searchInfo(mem.ambient, 0, "ambient");
      if (ainfo && routeFeasible(ainfo.dist, ainfo.home, carried + 1)) {
        return ainfo;
      }
    }

    return chooseGlobal();
  }

  function siteDistanceNow() {
    if (siteObs) return Math.max(0, num(siteObs.distance, 99));
    if (mem.siteLock) {
      return dist(poseX, poseY, mem.siteLock.x, mem.siteLock.y);
    }
    return 99;
  }

  function goHome() {
    if (atBase || homeDist <= 2.2) {
      return emit(stopCommands(), false);
    }

    const error = beaconUsable
      ? num(beacon.bearing, 0)
      : wrap(
          deg(Math.atan2(baseY - poseY, baseX - poseX)) - mem.theta
        );

    if (updateProgress("home", homeDist, null)) {
      return recoveryAction();
    }

    let speed = homeDist > 34 ? 0.39 : (homeDist > 8 ? 0.30 : 0.20);
    if (timeLeft < homeSeconds(homeDist, carried) + 20) speed = 0.40;
    return emit(navCommands(error, speed), false);
  }

  if (sampleCompleted) {
    mem.returning = false;
  }
  if (delivered > oldDelivered && carried === 0) {
    mem.returning = false;
  }
  if (mem.returning && atBase && carried === 0) {
    mem.returning = false;
    mem.sampleActive = false;
    mem.stillTime = 0;
    mem.holdI = [0, 0];
  }

  if (mem.sampleActive) {
    if (drillProgress > num(mem.lastDrillProgress, 0) + 0.035) {
      mem.lastDrillProgress = drillProgress;
      mem.lastDrillProgressT = tNow;
    }

    const elapsed = tNow - num(mem.sampleStart, tNow);
    const sd = siteDistanceNow();
    const noProgressTime = tNow - num(mem.lastDrillProgressT, tNow);
    const timedOut =
      (elapsed > 34 && noProgressTime > 12 && drillProgress < 5.8) ||
      elapsed > 48;
    const lostSite = sd > 2.4 &&
      drillProgress < 0.20 &&
      elapsed > 3.5;

    if ((timedOut || lostSite) && carried === oldCarried) {
      mem.sampleActive = false;
      mem.pendingMeta = null;
      mem.siteLock = null;
      mem.stillTime = 0;
      mem.sampleFailures = num(mem.sampleFailures, 0) + 1;
      mem.siteIgnoreUntil = tNow + 8;
      mem.holdI = [0, 0];
    } else {
      if (mem.siteLock && !mem.pendingMeta) {
        mem.pendingMeta = {
          x: mem.siteLock.x,
          y: mem.siteLock.y,
          value: mem.siteLock.value
        };
      }

      const c = holdCommands();
      const still = Math.max(Math.abs(wl), Math.abs(wr)) < 0.14;
      const inRange = sd <= 1.55 || drillProgress > 0.05 || elapsed < 0.8;
      const drill = still && inRange && drillProgress < 6.25;
      return emit(c, drill);
    }
  }

  if (!mem.returning && !mem.sampleActive) {
    if (carried >= mem.capacity) {
      mem.returning = true;
    } else if (!atBase &&
               battery < homeNeed(homeDist, carried) +
                 (carried > 0 ? 0.12 : 0.14)) {
      mem.returning = true;
    } else if (!atBase &&
               timeLeft < homeSeconds(homeDist, carried) + 25) {
      mem.returning = true;
    }
  }

  if (o.bumped && !mem.prevBumped && !mem.sampleActive && !atBase) {
    mem.recoverSign = openSide();
    mem.recoverTimer = 1.8;
    mem.avoidSign = mem.recoverSign;
    mem.avoidClearTime = 0;
  }
  mem.prevBumped = !!o.bumped;

  if (atBase && carried > 0) {
    return emit(stopCommands(), false);
  }

  if (mem.recoverTimer > 0 && !mem.sampleActive && !atBase) {
    return recoveryAction();
  }

  if (mem.returning && !atBase) {
    return goHome();
  }

  if (atBase && carried === 0 && maxWheel > 0.28) {
    return emit(stopCommands(), false);
  }

  if (atBase && carried === 0 && battery < 0.48 && timeLeft > 65) {
    return emit(stopCommands(), false);
  }

  if (siteObs &&
      carried < mem.capacity &&
      !mem.returning &&
      tNow >= num(mem.siteIgnoreUntil, 0)) {
    const sd = Math.max(0, num(siteObs.distance, 99));
    const sb = num(siteObs.bearing, 0);
    const a = rad(mem.theta + sb);
    const sx = poseX + sd * Math.cos(a);
    const sy = poseY + sd * Math.sin(a);
    const siteHome = dist(sx, sy, baseX, baseY);

    if (!routeFeasible(sd, siteHome + 8, carried + 1)) {
      if (!atBase) {
        mem.returning = true;
        return goHome();
      }
      return emit(stopCommands(), false);
    }

    if (sd <= 1.32) {
      const c = holdCommands();
      const still = Math.max(Math.abs(wl), Math.abs(wr)) < 0.14;

      if (still && sd <= 1.44) {
        mem.stillTime = num(mem.stillTime, 0) + dt;
      } else {
        mem.stillTime = 0;
      }

      let drill = false;
      if (mem.stillTime >= 0.25 && still && sd <= 1.44) {
        mem.sampleActive = true;
        mem.sampleStart = tNow;
        mem.lastDrillProgress = 0;
        mem.lastDrillProgressT = tNow;
        mem.holdI = [0, 0];
        mem.pendingMeta = mem.siteLock
          ? {
              x: mem.siteLock.x,
              y: mem.siteLock.y,
              value: mem.siteLock.value
            }
          : {
              x: sx,
              y: sy,
              value: Math.max(0.1, num(siteObs.value, 1))
            };
        drill = true;
      }

      return emit(c, drill);
    }

    mem.stillTime = 0;
    if (updateProgress("site", sd, { kind: "site" })) {
      return recoveryAction();
    }

    const speed = clamp((sd - 0.85) * 0.22, 0.10, 0.39);
    return emit(navCommands(sb, speed), false);
  }

  if (atBase && carried === 0) {
    /* Remaining still while a task is selected permits docking and charging. */
  }

  const info = getTask();
  if (!info) {
    if (carried > 0 || !atBase) {
      mem.returning = true;
      return goHome();
    }
    return emit(stopCommands(), false);
  }

  if (!routeFeasible(info.dist, info.home, carried + 1)) {
    if (carried > 0 || !atBase) {
      mem.returning = true;
      return goHome();
    }
    return emit(stopCommands(), false);
  }

  if (updateProgress(info.key, info.dist, info)) {
    return recoveryAction();
  }

  const bearing = deg(Math.atan2(info.y - poseY, info.x - poseX));
  const error = wrap(bearing - mem.theta);

  let speed;
  if (info.kind === "hint" && info.phase === 0) {
    speed = info.dist > 35 ? 0.39 : (info.dist > 10 ? 0.32 : 0.24);
  } else if (info.kind === "hint") {
    speed = info.dist > 9 ? 0.32 : 0.23;
  } else if (info.kind === "ambient") {
    speed = info.dist > 8 ? 0.30 : 0.22;
  } else {
    speed = info.dist > 18 ? 0.39 : (info.dist > 5 ? 0.30 : 0.22);
  }

  return emit(navCommands(error, speed), false);
}

function act(obs, mem) {
  const o = obs || {};
  if (!mem || typeof mem !== "object") mem = {};

  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
  const num = (v, d) => {
    if (v === null || v === undefined) return d;
    const n = Number(v);
    return Number.isFinite(n) ? n : d;
  };
  const wrap = (a) => {
    a = (a + 180) % 360;
    if (a < 0) a += 360;
    return a - 180;
  };
  const rad = (d) => d * Math.PI / 180;
  const deg = (r) => r * 180 / Math.PI;
  const dist = (x1, y1, x2, y2) => Math.hypot(x2 - x1, y2 - y1);

  const tNow = num(o.t, 0);
  const rawH = wrap(num(o.heading, 0));

  if (!mem._init) {
    const m = o.mission && typeof o.mission === "object" ? o.mission : {};
    const sz = m.size;
    let width = 400;
    let height = 400;

    if (typeof sz === "number") {
      width = height = sz;
    } else if (Array.isArray(sz)) {
      width = num(sz[0], 400);
      height = num(sz[1], width);
    } else if (sz && typeof sz === "object") {
      width = num(sz.width, num(sz.w, num(sz.x, 400)));
      height = num(sz.height, num(sz.h, num(sz.y, width)));
    }
    width = Math.max(50, width);
    height = Math.max(50, height);

    const base = m.base && typeof m.base === "object"
      ? m.base
      : { x: width * 0.5, y: height * 0.5 };

    mem.width = width;
    mem.height = height;
    mem.baseX = num(base.x, width * 0.5);
    mem.baseY = num(base.y, height * 0.5);
    mem.seconds = num(m.seconds, 1200);
    mem.capacity = Math.max(1, Math.floor(num(m.capacity, 5)));

    mem.hints = [];
    const hints = Array.isArray(m.hints) ? m.hints : [];
    for (let i = 0; i < hints.length; i++) {
      const h = hints[i] || {};
      const hx = clamp(num(h.x, mem.baseX), 4, width - 4);
      const hy = clamp(num(h.y, mem.baseY), 4, height - 4);
      mem.hints.push({
        x: hx,
        y: hy,
        value: Math.max(0.1, num(h.estimate, num(h.value, 1))),
        status: 0,
        phase: 0,
        step: 0,
        angle: (i * 0.57) % (2 * Math.PI),
        centerScience: 0,
        phaseStartScience: 0,
        bestScience: 0,
        bestX: hx,
        bestY: hy,
        anchorX: hx,
        anchorY: hy,
        anchorScience: 0,
        localScience: 0,
        localX: hx,
        localY: hy,
        loops: 0,
        outerTried: 0
      });
    }

    mem.globalPoints = [];
    for (let iy = 0; iy < 10; iy++) {
      for (let ix = 0; ix < 10; ix++) {
        mem.globalPoints.push({
          x: 18 + (width - 36) * ix / 9,
          y: 18 + (height - 36) * iy / 9,
          done: false
        });
      }
    }

    const x0 = num(o.x, width * 0.5);
    const y0 = num(o.y, height * 0.5);
    mem.px = x0;
    mem.py = y0;
    mem.theta = rawH;
    mem.headingBias = 0;
    mem.prevRawH = rawH;
    mem.prevT = tNow;
    mem.lastGpsX = x0;
    mem.lastGpsY = y0;
    mem.gpsUnchanged = 0;
    mem.gpsTravelSinceChange = 0;
    mem.gpsFrozen = false;
    mem.gpsRecover = 0;
    mem.compassHold = 0;
    mem.cal = { active: false, x: x0, y: y0, sin: 0, cos: 0, n: 0 };

    mem.gain = [[2.8, 2.8], [2.8, 2.8]];
    mem.dead = [[0.18, 0.18], [0.18, 0.18]];
    mem.noResponse = [0, 0];
    mem.motorStable = [0, 0];
    mem.motorStableTarget = [0, 0];
    mem.motorStableCmd = [0, 0];
    mem.lastCmd = [0, 0];
    mem.lastTarget = [0, 0];

    mem.rFilt = [];
    mem.rRaw = [];
    mem.rSameTime = [];
    mem.rSameMotion = [];
    mem.rBad = [];
    for (let i = 0; i < 9; i++) {
      mem.rFilt[i] = 15;
      mem.rRaw[i] = 15;
      mem.rSameTime[i] = 0;
      mem.rSameMotion[i] = 0;
      mem.rBad[i] = false;
    }
    mem.allMaxTravel = 0;
    mem.rangeTrust = 1;

    mem.energyRate = 0.0011;
    mem.energyUse = 0;
    mem.energyDist = 0;
    mem.prevBattery = clamp(num(o.battery, 1), 0, 1.8);

    mem.currentHint = -1;
    mem.globalIndex = -1;
    mem.globalResetAt = -1000;
    mem.ambient = null;
    mem.ambientLastX = -1e9;
    mem.ambientLastY = -1e9;

    mem.siteLock = null;
    mem.pendingMeta = null;
    mem.sampleActive = false;
    mem.sampleStart = 0;
    mem.sampleFailures = 0;
    mem.stillTime = 0;
    mem.holdI = [0, 0];
    mem.lastDrillProgress = 0;
    mem.lastDrillProgressT = tNow;

    mem.returning = false;
    mem.navKey = "";
    mem.navBest = 1e9;
    mem.navStuck = 0;
    mem.stuckCount = 0;
    mem.lastAim = 0;
    mem.avoidSign = 0;
    mem.avoidClearTime = 0;
    mem.recoverTimer = 0;
    mem.recoverSign = 1;
    mem.escapeUntil = 0;
    mem.escapeSign = 1;
    mem.lastFrozenEscape = -1000;
    mem.prevBumped = false;
    mem.siteIgnoreUntil = 0;

    mem.prevCarried = Math.max(0, Math.floor(num(o.carried, 0)));
    mem.prevCarriedValue = num(o.carriedValue, 0);
    mem.prevDelivered = num(o.delivered, 0);
    mem.prevBeacon = null;
    mem.beaconSameTime = 0;
    mem.beaconSameMotion = 0;
    mem.beaconBad = false;
    mem.scienceEma = Math.max(0, num(o.science, 0));
    mem.samples = [];
    mem._init = true;
  }

  let dt = 0.1;
  if (Number.isFinite(mem.prevT)) {
    const d = tNow - mem.prevT;
    if (d > 0.02 && d <= 0.55) dt = d;
  }

  const width = num(mem.width, 400);
  const height = num(mem.height, 400);
  const rawX = num(o.x, num(mem.px, width * 0.5));
  const rawY = num(o.y, num(mem.py, height * 0.5));
  const wl = num(o.wheelLeft, 0);
  const wr = num(o.wheelRight, 0);
  const vWheel = (wl + wr) * 0.5;
  const wheelTravel = (Math.abs(wl) + Math.abs(wr)) * 0.5 * dt;
  const yawRad = ((wr - wl) / 0.6) * dt;
  const yawDeg = deg(yawRad);

  const battery = clamp(num(o.battery, mem.prevBattery), 0, 1.8);
  const solar = Math.max(0, num(o.solar, 0));
  const carried = Math.max(0, Math.floor(num(o.carried, 0)));
  const carriedValue = num(o.carriedValue, mem.prevCarriedValue);
  const delivered = num(o.delivered, mem.prevDelivered);
  const timeLeft = Math.max(0, num(o.timeLeft, mem.seconds - tNow));
  const drillProgress = Math.max(0, num(o.drilling, 0));
  const science = Math.max(0, num(o.science, 0));
  const siteObs = o.site && typeof o.site === "object" ? o.site : null;
  const beacon = o.beacon && typeof o.beacon === "object" ? o.beacon : null;

  const rawRays = o.rays && typeof o.rays.length === "number" ? o.rays : null;
  let minRawRay = 15;
  if (rawRays) {
    for (let i = 0; i < 9; i++) {
      minRawRay = Math.min(minRawRay, clamp(num(rawRays[i], 15), 0, 15));
    }
  }

  const prevTheta = num(mem.theta, rawH);
  const rawDeltaH = wrap(rawH - num(mem.prevRawH, rawH));
  const compassJump =
    Math.abs(wrap(rawDeltaH - yawDeg)) > 72 && Math.abs(yawDeg) < 55;

  if (compassJump) mem.compassHold = 1.4;
  else mem.compassHold = Math.max(0, num(mem.compassHold, 0) - dt);

  let theta = wrap(prevTheta + yawDeg);
  if (!compassJump && mem.compassHold <= 0) {
    const corrected = wrap(rawH - num(mem.headingBias, 0));
    const residual = wrap(corrected - theta);
    if (Math.abs(residual) < 100) {
      theta = wrap(theta + clamp(residual * 0.075, -1.5, 1.5));
    }
  }
  mem.theta = theta;

  const gpsDelta = dist(
    rawX, rawY,
    num(mem.lastGpsX, rawX),
    num(mem.lastGpsY, rawY)
  );
  const gpsJump = gpsDelta > 12 && dt <= 0.55;

  if (gpsDelta < 0.035 && wheelTravel > 0.018) {
    mem.gpsUnchanged = num(mem.gpsUnchanged, 0) + dt;
    mem.gpsTravelSinceChange = num(mem.gpsTravelSinceChange, 0) + wheelTravel;
  } else if (gpsDelta > 0.10) {
    mem.gpsUnchanged = 0;
    mem.gpsTravelSinceChange = 0;
  }

  const wasGpsFrozen = !!mem.gpsFrozen;
  mem.gpsFrozen =
    num(mem.gpsUnchanged, 0) > 2.3 &&
    num(mem.gpsTravelSinceChange, 0) > 1.0;

  if (wasGpsFrozen && !mem.gpsFrozen) mem.gpsRecover = 1.5;
  else mem.gpsRecover = Math.max(0, num(mem.gpsRecover, 0) - dt);

  const midTheta = rad(wrap((prevTheta + theta) * 0.5));
  let motionScale = 1;
  if (mem.gpsFrozen) motionScale = minRawRay < 1.4 ? 0.35 : 0.72;

  let px = num(mem.px, rawX) +
    vWheel * dt * Math.cos(midTheta) * motionScale;
  let py = num(mem.py, rawY) +
    vWheel * dt * Math.sin(midTheta) * motionScale;

  if (!mem.gpsFrozen && !gpsJump) {
    const dx = rawX - px;
    const dy = rawY - py;
    const residual = Math.hypot(dx, dy);
    if (residual < 25) {
      let alpha = Math.abs(vWheel) > 0.18 ? 0.27 : 0.12;
      if (gpsDelta > 0.45) alpha = 0.34;
      alpha *= clamp(1 - num(mem.gpsUnchanged, 0) / 3.0, 0.18, 1);
      const limit = Math.abs(vWheel) > 0.18 ? 1.6 : 0.60;
      const scale = residual > limit ? limit / residual : 1;
      px += dx * scale * alpha;
      py += dy * scale * alpha;
    }
  } else if (mem.gpsRecover > 0) {
    const dx = rawX - px;
    const dy = rawY - py;
    const residual = Math.hypot(dx, dy);
    if (residual < 35) {
      const limit = residual > 5 ? 5 / residual : 1;
      px += dx * limit * 0.38;
      py += dy * limit * 0.38;
    }
  }

  px = clamp(px, 1, width - 1);
  py = clamp(py, 1, height - 1);
  mem.px = px;
  mem.py = py;
  mem.lastGpsX = rawX;
  mem.lastGpsY = rawY;
  mem.prevRawH = rawH;

  if (!mem.cal || typeof mem.cal !== "object") {
    mem.cal = { active: false, x: rawX, y: rawY, sin: 0, cos: 0, n: 0 };
  }
  const straightForward =
    vWheel > 0.30 &&
    Math.abs(wr - wl) < 0.22 &&
    !mem.gpsFrozen &&
    !gpsJump &&
    !compassJump;

  if (straightForward) {
    if (!mem.cal.active) {
      mem.cal.active = true;
      mem.cal.x = rawX;
      mem.cal.y = rawY;
      mem.cal.sin = 0;
      mem.cal.cos = 0;
      mem.cal.n = 0;
    }
    mem.cal.sin += Math.sin(rad(rawH));
    mem.cal.cos += Math.cos(rad(rawH));
    mem.cal.n += 1;

    if (dist(rawX, rawY, mem.cal.x, mem.cal.y) >= 8 &&
        mem.cal.n >= 12) {
      const course = deg(Math.atan2(rawY - mem.cal.y, rawX - mem.cal.x));
      const meanRaw = deg(Math.atan2(mem.cal.sin, mem.cal.cos));
      const estimate = wrap(meanRaw - course);
      const err = wrap(estimate - num(mem.headingBias, 0));
      if (Math.abs(err) < 60) {
        mem.headingBias = wrap(
          num(mem.headingBias, 0) + clamp(err * 0.06, -1.0, 1.0)
        );
      }
      mem.cal.x = rawX;
      mem.cal.y = rawY;
      mem.cal.sin = 0;
      mem.cal.cos = 0;
      mem.cal.n = 0;
    }
  } else {
    mem.cal.active = false;
    mem.cal.sin = 0;
    mem.cal.cos = 0;
    mem.cal.n = 0;
  }

  if (!Array.isArray(mem.gain) || mem.gain.length < 2) {
    mem.gain = [[2.8, 2.8], [2.8, 2.8]];
  }
  if (!Array.isArray(mem.dead) || mem.dead.length < 2) {
    mem.dead = [[0.18, 0.18], [0.18, 0.18]];
  }
  if (!Array.isArray(mem.lastCmd) || mem.lastCmd.length < 2) mem.lastCmd = [0, 0];
  if (!Array.isArray(mem.lastTarget) || mem.lastTarget.length < 2) mem.lastTarget = [0, 0];
  if (!Array.isArray(mem.noResponse) || mem.noResponse.length < 2) mem.noResponse = [0, 0];
  if (!Array.isArray(mem.motorStable) || mem.motorStable.length < 2) mem.motorStable = [0, 0];
  if (!Array.isArray(mem.motorStableTarget) || mem.motorStableTarget.length < 2) {
    mem.motorStableTarget = [0, 0];
  }
  if (!Array.isArray(mem.motorStableCmd) || mem.motorStableCmd.length < 2) {
    mem.motorStableCmd = [0, 0];
  }

  for (let s = 0; s < 2; s++) {
    if (!Array.isArray(mem.gain[s])) mem.gain[s] = [2.8, 2.8];
    if (!Array.isArray(mem.dead[s])) mem.dead[s] = [0.18, 0.18];

    const lastCmd = num(mem.lastCmd[s], 0);
    const lastTarget = num(mem.lastTarget[s], 0);
    const actual = s === 0 ? wl : wr;
    const direction = lastTarget < -0.015 ? 1 : 0;
    const dead = clamp(num(mem.dead[s][direction], 0.18), 0.10, 0.46);

    const stableTarget = num(mem.motorStableTarget[s], lastTarget);
    const stableCmd = num(mem.motorStableCmd[s], lastCmd);
    const consistent =
      Math.abs(lastTarget) > 0.13 &&
      Math.abs(lastCmd) > dead + 0.04 &&
      Math.sign(stableTarget) === Math.sign(lastTarget) &&
      Math.abs(lastTarget - stableTarget) < 0.10 &&
      Math.abs(lastCmd - stableCmd) < 0.09;

    if (consistent) mem.motorStable[s] = num(mem.motorStable[s], 0) + dt;
    else mem.motorStable[s] = 0;

    if (mem.motorStable[s] > 0.45) {
      if (actual * lastTarget > 0 && Math.abs(actual) > 0.07) {
        const ratio = Math.abs(actual) /
          Math.max(0.08, Math.abs(lastCmd) - dead);
        if (ratio > 0.45 && ratio < 6.0) {
          const old = num(mem.gain[s][direction], 2.8);
          mem.gain[s][direction] = clamp(old + (ratio - old) * 0.015, 0.75, 5.8);
        }
      }

      if (Math.abs(actual) < 0.045 &&
          Math.abs(lastCmd) > dead + 0.04) {
        mem.noResponse[s] = num(mem.noResponse[s], 0) + dt;
        if (mem.noResponse[s] > 0.8) {
          mem.dead[s][direction] = clamp(
            num(mem.dead[s][direction], 0.18) + 0.005,
            0.12,
            0.46
          );
        }
      } else {
        mem.noResponse[s] = 0;
      }
    } else {
      mem.noResponse[s] = 0;
    }

    if (Math.abs(actual) > 0.22 &&
        Math.abs(lastCmd) > dead + 0.02 &&
        actual * lastTarget > 0) {
      mem.dead[s][direction] = Math.max(
        0.11,
        num(mem.dead[s][direction], 0.18) - 0.00015
      );
    }

    mem.motorStableTarget[s] = lastTarget;
    mem.motorStableCmd[s] = lastCmd;
  }

  const prevBattery = num(mem.prevBattery, battery);
  if (!o.docked && (wheelTravel > 0.012 || drillProgress > 0.05)) {
    const gross = clamp(
      prevBattery - battery + solar * dt * 0.18,
      0,
      0.025
    );
    mem.energyUse = num(mem.energyUse, 0) + gross;
    mem.energyDist = num(mem.energyDist, 0) +
      wheelTravel +
      (drillProgress > 0.05 ? dt * 0.06 : 0);

    if (mem.energyDist >= 20) {
      const loadFactor = 1 + 0.15 * carried;
      const measured = clamp(
        mem.energyUse / Math.max(7, mem.energyDist) / loadFactor,
        0.0004,
        0.007
      );
      const oldRate = num(mem.energyRate, 0.0011);
      const alpha = measured > oldRate ? 0.18 : 0.045;
      mem.energyRate = clamp(oldRate + (measured - oldRate) * alpha, 0.00045, 0.007);
      mem.energyUse = 0;
      mem.energyDist = 0;
    }
  }

  if (!Array.isArray(mem.rFilt) || mem.rFilt.length !== 9) {
    mem.rFilt = [];
    mem.rRaw = [];
    mem.rSameTime = [];
    mem.rSameMotion = [];
    mem.rBad = [];
    for (let i = 0; i < 9; i++) {
      mem.rFilt[i] = 15;
      mem.rRaw[i] = 15;
      mem.rSameTime[i] = 0;
      mem.rSameMotion[i] = 0;
      mem.rBad[i] = false;
    }
  }

  const sensorMotion = wheelTravel + Math.abs(yawRad) * 0.4;
  let allMax = true;
  let anyNear = false;
  let minEffectiveRay = 15;

  for (let i = 0; i < 9; i++) {
    const r = clamp(rawRays ? num(rawRays[i], 15) : 15, 0, 15);
    const last = num(mem.rRaw[i], r);
    const diff = Math.abs(r - last);

    if (diff < 0.025) {
      if (sensorMotion > 0.025) {
        mem.rSameTime[i] = num(mem.rSameTime[i], 0) + dt;
        mem.rSameMotion[i] = num(mem.rSameMotion[i], 0) + sensorMotion;
      }
    } else if (diff > 0.30) {
      mem.rSameTime[i] = 0;
      mem.rSameMotion[i] = 0;
      mem.rBad[i] = false;
    }

    if (mem.rSameTime[i] > 6 &&
        mem.rSameMotion[i] > 2.5 &&
        r < 14.5) {
      mem.rBad[i] = true;
    }

    const effective = mem.rBad[i] ? 15 : r;
    minEffectiveRay = Math.min(minEffectiveRay, effective);
    if (effective < 14.8) allMax = false;
    if (effective < 14.2) anyNear = true;

    let f = num(mem.rFilt[i], 15);
    const a = effective < f ? 0.68 : 0.30;
    f += (effective - f) * a;
    mem.rFilt[i] = clamp(f, 0, 15);
    mem.rRaw[i] = r;
  }

  if (allMax && wheelTravel > 0.02) {
    mem.allMaxTravel = num(mem.allMaxTravel, 0) + wheelTravel;
  } else if (anyNear) {
    mem.allMaxTravel = Math.max(
      0,
      num(mem.allMaxTravel, 0) - wheelTravel
    );
  }
  mem.rangeTrust = mem.allMaxTravel > 22 ? 0.76 : 1;

  if (beacon) {
    const bd = Math.max(0, num(beacon.distance, 99));
    const bb = num(beacon.bearing, 0);
    const pb = mem.prevBeacon;

    if (pb &&
        sensorMotion > 0.02 &&
        Math.abs(bd - num(pb.d, bd)) < 0.018 &&
        Math.abs(wrap(bb - num(pb.b, bb))) < 0.22) {
      mem.beaconSameTime = num(mem.beaconSameTime, 0) + dt;
      mem.beaconSameMotion = num(mem.beaconSameMotion, 0) + sensorMotion;
      if (mem.beaconSameTime > 6 && mem.beaconSameMotion > 2.7) {
        mem.beaconBad = true;
      }
    } else if (!pb ||
               Math.abs(bd - num(pb.d, bd)) > 0.08 ||
               Math.abs(wrap(bb - num(pb.b, bb))) > 1) {
      mem.beaconSameTime = 0;
      mem.beaconSameMotion = 0;
      mem.beaconBad = false;
    }

    mem.prevBeacon = { d: bd, b: bb };
  } else {
    mem.prevBeacon = null;
    mem.beaconSameTime = 0;
    mem.beaconSameMotion = 0;
    mem.beaconBad = false;
  }

  const poseX = num(mem.px, rawX);
  const poseY = num(mem.py, rawY);
  const oldCarried = num(mem.prevCarried, carried);
  const oldCarriedValue = num(mem.prevCarriedValue, carriedValue);
  const oldDelivered = num(mem.prevDelivered, delivered);
  const sampleCompleted = carried > oldCarried;

  mem.scienceEma =
    num(mem.scienceEma, science) * 0.80 + science * 0.20;

  if (sampleCompleted) {
    const meta = mem.pendingMeta || mem.siteLock || {
      x: poseX,
      y: poseY,
      value: 1
    };
    const mx = num(meta.x, poseX);
    const my = num(meta.y, poseY);
    let value = Math.max(0.1, num(meta.value, 1));
    const valueGain = carriedValue - oldCarriedValue;
    if (valueGain > 0.01) {
      value = valueGain / Math.max(1, carried - oldCarried);
    }
    mem.samples.push({ x: mx, y: my, value: value });

    let associated = -1;
    let nearestD = 43;
    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (!h || h.status >= 2) continue;
      const d = dist(mx, my, h.x, h.y);
      if (d < nearestD) {
        nearestD = d;
        associated = i;
      }
    }

    const currentHint = Math.floor(num(mem.currentHint, -1));
    if (currentHint >= 0 &&
        currentHint < mem.hints.length &&
        mem.hints[currentHint] &&
        mem.hints[currentHint].status < 2 &&
        dist(mx, my, mem.hints[currentHint].x, mem.hints[currentHint].y) < 45) {
      associated = currentHint;
    }

    if (associated >= 0) {
      mem.hints[associated].status = 2;
      if (associated === currentHint) mem.currentHint = -1;
    }

    for (let i = 0; i < mem.globalPoints.length; i++) {
      const p = mem.globalPoints[i];
      if (p && dist(mx, my, p.x, p.y) < 14) p.done = true;
    }

    if (mem.ambient && dist(mx, my, mem.ambient.x, mem.ambient.y) < 30) {
      mem.ambient = null;
    }

    mem.sampleActive = false;
    mem.pendingMeta = null;
    mem.siteLock = null;
    mem.stillTime = 0;
    mem.holdI = [0, 0];
    mem.navKey = "";
    mem.lastDrillProgress = 0;
    mem.lastDrillProgressT = tNow;
    mem.returning = false;
  } else if (carried < oldCarried || delivered > oldDelivered) {
    mem.sampleActive = false;
    mem.pendingMeta = null;
    mem.siteLock = null;
    mem.stillTime = 0;
    mem.holdI = [0, 0];
  }

  if (siteObs && carried < mem.capacity && !sampleCompleted) {
    const sd = Math.max(0, num(siteObs.distance, 99));
    const sb = num(siteObs.bearing, 0);
    const a = rad(mem.theta + sb);
    const sx = poseX + sd * Math.cos(a);
    const sy = poseY + sd * Math.sin(a);
    const sv = Math.max(0.1, num(siteObs.value, 1));

    if (!mem.siteLock) {
      mem.siteLock = { x: sx, y: sy, value: sv, lastSeen: tNow };
    } else {
      const gap = dist(mem.siteLock.x, mem.siteLock.y, sx, sy);
      if (gap > 9) {
        mem.siteLock.x = sx;
        mem.siteLock.y = sy;
      } else {
        mem.siteLock.x = mem.siteLock.x * 0.68 + sx * 0.32;
        mem.siteLock.y = mem.siteLock.y * 0.68 + sy * 0.32;
      }
      mem.siteLock.value = sv;
      mem.siteLock.lastSeen = tNow;
    }
  } else if (mem.siteLock &&
             !mem.sampleActive &&
             tNow - num(mem.siteLock.lastSeen, tNow) > 12) {
    mem.siteLock = null;
  }

  if (!sampleCompleted && !mem.sampleActive && drillProgress > 0.05) {
    mem.sampleActive = true;
    mem.sampleStart = tNow - drillProgress;
    mem.lastDrillProgress = drillProgress;
    mem.lastDrillProgressT = tNow;
    if (mem.siteLock) {
      mem.pendingMeta = {
        x: mem.siteLock.x,
        y: mem.siteLock.y,
        value: mem.siteLock.value
      };
    }
  }

  const baseX = num(mem.baseX, width * 0.5);
  const baseY = num(mem.baseY, height * 0.5);
  const baseDist = dist(poseX, poseY, baseX, baseY);
  const beaconDistRaw = beacon ? Math.max(0, num(beacon.distance, 99)) : 99;
  const beaconUsable = !!beacon && !mem.beaconBad && beaconDistRaw <= 20.5;
  const beaconDist = beaconUsable ? beaconDistRaw : 99;
  const maxWheel = Math.max(Math.abs(wl), Math.abs(wr));
  const atBase = !!o.docked ||
    (beaconUsable && beaconDist <= 2.75) ||
    (baseDist <= 2.5 && maxWheel < 0.23);
  const homeDist = beaconUsable ? beaconDist : baseDist;
  const scienceNow = science;

  function routeFeasible(out, home, load, extra) {
    const l = Math.max(0, load);
    const e = Math.max(0, num(extra, 0));
    const route = Math.max(0, out) + Math.max(0, home) + 10 + e * 0.32;
    const rate = Math.max(0.0006, num(mem.energyRate, 0.0011));
    const need =
      0.12 +
      route * rate * (1 + 0.18 * l) * 1.32 +
      0.022 * l;
    const seconds =
      (Math.max(0, out) + Math.max(0, home) + 10 + e * 0.40) * 2.8 +
      34 + 7 * l;
    return need <= battery - 0.025 && seconds <= timeLeft - 7;
  }

  function homeNeed(d, load) {
    const l = Math.max(0, load);
    const rate = Math.max(0.0006, num(mem.energyRate, 0.0011));
    return 0.12 +
      Math.max(0, d + 8) * rate * (1 + 0.18 * l) * 1.42 +
      0.022 * l;
  }

  function homeSeconds(d, load) {
    return Math.max(0, d) * 2.85 + 32 + 6 * Math.max(0, load);
  }

  function emit(c, drill) {
    const left = clamp(num(c && c.left, 0), -1, 1);
    const right = clamp(num(c && c.right, 0), -1, 1);
    mem.lastCmd = [left, right];
    mem.lastTarget = [
      num(c && c.tl, 0),
      num(c && c.tr, 0)
    ];
    mem.prevT = tNow;
    mem.prevBattery = battery;
    mem.prevCarried = carried;
    mem.prevCarriedValue = carriedValue;
    mem.prevDelivered = delivered;
    return { left: left, right: right, drill: !!drill };
  }

  function motorPower(target, actual, side) {
    const t = clamp(target, -0.43, 0.43);
    const a = num(actual, 0);
    const absT = Math.abs(t);
    const absA = Math.abs(a);
    const direction = t < -0.015 ? 1 : 0;
    const gain = clamp(num(mem.gain[side][direction], 2.8), 0.75, 5.8);
    const dead = clamp(num(mem.dead[side][direction], 0.18), 0.10, 0.46);

    if (absT < 0.035) {
      if (absA < 0.07) return 0;
      const brake = clamp(dead + absA / gain * 0.60, dead, 0.58);
      return clamp(-Math.sign(a) * brake, -0.60, 0.60);
    }

    if (a * t > 0 && absA > absT + 0.14) {
      const brake = clamp(dead + (absA - absT) / gain * 0.60, dead, 0.50);
      return clamp(-Math.sign(a) * brake, -0.60, 0.60);
    }

    if (absA > 0.95) {
      return clamp(-Math.sign(a) * Math.max(0.34, dead + absA / gain * 0.45), -0.60, 0.60);
    }

    const error = t - a;
    let u = Math.sign(t) * (dead + absT / gain) +
      clamp(error * 0.42 / gain, -0.14, 0.14);

    if (u * t > 0 && Math.abs(u) < dead + 0.02) {
      u = Math.sign(t) * (dead + 0.02);
    }
    return clamp(u, -0.65, 0.65);
  }

  function wheelCommands(v, omega) {
    const lt = clamp(v - 0.3 * omega, -0.43, 0.43);
    const rt = clamp(v + 0.3 * omega, -0.43, 0.43);
    return {
      left: motorPower(lt, wl, 0),
      right: motorPower(rt, wr, 1),
      tl: lt,
      tr: rt
    };
  }

  function stopCommands() {
    return wheelCommands(0, 0);
  }

  function holdCommands() {
    if (!Array.isArray(mem.holdI) || mem.holdI.length < 2) mem.holdI = [0, 0];

    const pitch = num(o.pitch, 0);
    const actuals = [wl, wr];
    const out = [];
    const meanDead =
      (num(mem.dead[0][0], 0.18) + num(mem.dead[1][0], 0.18)) * 0.5;
    let pitchFeed = 0;
    if (Math.abs(pitch) > 1.0) {
      pitchFeed = Math.sign(pitch) *
        (meanDead + Math.min(0.13, Math.abs(pitch) * 0.0075));
    }

    for (let i = 0; i < 2; i++) {
      const actual = actuals[i];
      let integral = num(mem.holdI[i], 0);

      if (Math.abs(actual) > 0.04) {
        integral = clamp(integral - actual * 1.45 * dt, -0.48, 0.48);
      } else if (Math.abs(pitch) < 2.3) {
        integral *= 0.45;
        if (Math.abs(integral) < 0.10) integral = 0;
      } else {
        integral *= 0.99;
      }

      let u = integral - 0.82 * actual + pitchFeed;
      if (Math.abs(actual) < 0.035 && Math.abs(pitch) < 2.3) {
        integral = 0;
        u = 0;
      }

      mem.holdI[i] = integral;
      out[i] = clamp(u, -0.50, 0.50);
    }

    return { left: out[0], right: out[1], tl: 0, tr: 0 };
  }

  function rayAt(angle) {
    const a = clamp(angle, -80, 80);
    const q = (a + 80) / 20;
    const i = Math.floor(q);
    const f = q - i;
    if (i >= 8) return num(mem.rFilt[8], 15);
    return num(mem.rFilt[i], 15) * (1 - f) +
      num(mem.rFilt[i + 1], 15) * f;
  }

  function clearanceAt(angle) {
    const center = rayAt(angle);
    const side = Math.min(rayAt(angle - 20), rayAt(angle + 20));
    return Math.min(center, center * 0.76 + side * 0.24);
  }

  function edgeDistance(angle) {
    const a = rad(wrap(mem.theta + angle));
    const dx = Math.cos(a);
    const dy = Math.sin(a);
    const margin = 5;
    let d = 1e6;

    if (dx > 0.001) d = Math.min(d, (width - margin - poseX) / dx);
    if (dx < -0.001) d = Math.min(d, (margin - poseX) / dx);
    if (dy > 0.001) d = Math.min(d, (height - margin - poseY) / dy);
    if (dy < -0.001) d = Math.min(d, (margin - poseY) / dy);

    return Math.max(0, d);
  }

  function openSide() {
    let leftOpen = 0;
    let rightOpen = 0;
    for (let i = 5; i < 9; i++) leftOpen += num(mem.rFilt[i], 15);
    for (let i = 0; i < 4; i++) rightOpen += num(mem.rFilt[i], 15);
    if (Math.abs(leftOpen - rightOpen) < 0.5) {
      return mem.avoidSign ? -mem.avoidSign : 1;
    }
    return leftOpen >= rightOpen ? 1 : -1;
  }

  function navCommands(goalError, maxV) {
    const goal = wrap(num(goalError, 0));
    let vmax = clamp(num(maxV, 0.32), 0, 0.38);
    if (mem.rangeTrust < 0.9) vmax = Math.min(vmax, 0.27);
    if (maxWheel > 0.72) vmax = Math.min(vmax, 0.13);
    if (maxWheel > 0.94) vmax = 0.02;

    const front = clearanceAt(0);
    const safe = 1.65 + vmax * 0.75;

    if (front < 0.42 && tNow >= num(mem.escapeUntil, 0)) {
      mem.escapeSign = openSide();
      mem.escapeUntil = tNow + 1.45;
    }
    if (tNow < num(mem.escapeUntil, 0)) {
      const rem = mem.escapeUntil - tNow;
      const s = num(mem.escapeSign, 1);
      if (rem > 0.78) return wheelCommands(-0.16, s * 0.46);
      return wheelCommands(0, s * 0.56);
    }

    if (Math.abs(goal) > 115 && front > 1.0) {
      return wheelCommands(0, Math.sign(goal) * 0.58);
    }

    if (front < safe) {
      mem.avoidClearTime = 0;
      if (!mem.avoidSign) mem.avoidSign = openSide();
    } else if (front > safe + 1.1 && mem.avoidSign) {
      mem.avoidClearTime = num(mem.avoidClearTime, 0) + dt;
      if (mem.avoidClearTime > 1.3) {
        mem.avoidSign = 0;
        mem.avoidClearTime = 0;
      }
    }

    let aimGoal = clamp(goal, -80, 80);
    if (mem.avoidSign && front < safe + 0.75) {
      const offset = front < safe ? 42 : 25;
      aimGoal = clamp(goal + num(mem.avoidSign, 1) * offset, -80, 80);
    }

    const candidates = [];
    for (let a = -80; a <= 80; a += 10) candidates.push(a);
    candidates.push(clamp(goal, -80, 80), aimGoal);

    let best = aimGoal;
    let bestClear = clearanceAt(best);
    let bestCost = 1e9;

    for (let i = 0; i < candidates.length; i++) {
      const a = candidates[i];
      const clear = clearanceAt(a);
      let cost = Math.abs(wrap(a - aimGoal)) * 0.027;

      const hazard = Math.max(0, safe - clear);
      cost += hazard * hazard * 3.2;
      if (clear < 0.85) cost += 7;
      if (clear < 0.55) cost += 16;

      const edge = edgeDistance(a);
      if (edge < 1.7) cost += 17;
      else if (edge < 7) cost += (7 - edge) * 0.88;

      if (front < safe && mem.avoidSign && a * mem.avoidSign < -12) {
        cost += 0.30;
      }
      if (front < safe + 0.5) {
        cost += Math.abs(a - num(mem.lastAim, a)) * 0.003;
      }

      if (cost < bestCost) {
        bestCost = cost;
        best = a;
        bestClear = clear;
      }
    }

    if (front < safe && Math.abs(best) > 12) {
      mem.avoidSign = Math.sign(best);
      mem.avoidClearTime = 0;
    }
    mem.lastAim = best;

    let v = vmax * Math.max(0.34, Math.cos(rad(best)));
    v *= clamp(
      (bestClear - 0.50) / Math.max(0.85, safe - 0.50),
      0.10,
      1
    );

    if (front < 1.35) v = Math.min(v, 0.13);
    if (bestClear < 0.95) v = Math.min(v, 0.07);
    if (front < 0.72 && Math.abs(best) < 22) v = 0;
    if (Math.abs(best) > 56) v = 0;
    if (maxWheel > 0.94) v = 0;

    const omega = clamp(1.40 * rad(best), -0.74, 0.74);
    return wheelCommands(v, omega);
  }

  function recoveryAction() {
    const rem = Math.max(0, num(mem.recoverTimer, 0));
    const s = num(mem.recoverSign, 1);
    const c = rem > 0.78
      ? wheelCommands(-0.16, s * 0.46)
      : wheelCommands(0, s * 0.56);
    mem.recoverTimer = Math.max(0, rem - dt);
    return emit(c, false);
  }

  function ringPoint(cx, cy, step, count, radius, offset) {
    const a = num(offset, 0) + 2 * Math.PI * step / count;
    return {
      x: clamp(cx + radius * Math.cos(a), 4, width - 4),
      y: clamp(cy + radius * Math.sin(a), 4, height - 4)
    };
  }

  function finishSearch(s, index, kind) {
    if (kind === "hint") {
      s.status = 2;
      if (Math.floor(num(mem.currentHint, -1)) === index) {
        mem.currentHint = -1;
      }
    } else {
      mem.ambientLastX = s.x;
      mem.ambientLastY = s.y;
      mem.ambient = null;
    }
  }

  function beginClimb(s) {
    s.phase = 3;
    s.step = 0;
    s.anchorX = num(s.bestX, s.x);
    s.anchorY = num(s.bestY, s.y);
    s.anchorScience = num(s.bestScience, 0);
    s.localScience = s.anchorScience;
    s.localX = s.anchorX;
    s.localY = s.anchorY;
    s.loops = 0;
  }

  function searchInfo(s, index, kind) {
    if (!s) return null;
    if (kind === "hint" && s.status >= 2) return null;

    for (let tries = 0; tries < 12; tries++) {
      if (Math.floor(num(s.phase, 0)) === 0) {
        const d = dist(poseX, poseY, s.x, s.y);
        if (d > 3.4) {
          return {
            kind: kind,
            index: index,
            phase: 0,
            step: 0,
            x: s.x,
            y: s.y,
            dist: d,
            home: dist(s.x, s.y, baseX, baseY) + 6,
            extra: 44,
            key: kind + ":c:" + index
          };
        }

        s.phase = 1;
        s.step = 0;
        s.centerScience = num(mem.scienceEma, scienceNow);
        s.phaseStartScience = s.centerScience;
        s.bestScience = s.centerScience;
        s.bestX = poseX;
        s.bestY = poseY;
        s.anchorX = poseX;
        s.anchorY = poseY;
        s.anchorScience = s.centerScience;
        s.localScience = s.centerScience;
        s.localX = poseX;
        s.localY = poseY;
        s.loops = 0;
        s.outerTried = 0;
        continue;
      }

      const centerDistance = dist(poseX, poseY, s.x, s.y);
      if (centerDistance < 40 &&
          scienceNow > num(s.bestScience, 0) + 0.03) {
        s.bestScience = scienceNow;
        s.bestX = poseX;
        s.bestY = poseY;
      }

      if (Math.floor(num(s.phase, 0)) === 3 &&
          dist(poseX, poseY, s.anchorX, s.anchorY) < 12 &&
          scienceNow > num(s.localScience, 0) + 0.03) {
        s.localScience = scienceNow;
        s.localX = poseX;
        s.localY = poseY;
      }

      const phase = Math.floor(num(s.phase, 0));
      let count;
      let radius;
      let cx;
      let cy;

      if (phase === 1) {
        count = 8;
        radius = 8;
        cx = s.x;
        cy = s.y;
      } else if (phase === 2) {
        count = 12;
        radius = 16.5;
        cx = s.x;
        cy = s.y;
      } else {
        count = 6;
        radius = 5;
        cx = s.anchorX;
        cy = s.anchorY;
      }

      const step = Math.max(0, Math.floor(num(s.step, 0)));
      if (step >= count) {
        if (phase === 1) {
          if (num(s.bestScience, 0) >
                num(s.centerScience, 0) + 0.045 &&
              dist(s.bestX, s.bestY, s.x, s.y) > 2.5) {
            beginClimb(s);
          } else {
            s.phase = 2;
            s.step = 0;
            s.outerTried = 1;
            s.phaseStartScience = num(s.bestScience, 0);
          }
          continue;
        }

        if (phase === 2) {
          if (num(s.bestScience, 0) >
                num(s.phaseStartScience, 0) + 0.045 &&
              dist(s.bestX, s.bestY, s.x, s.y) > 2.7) {
            beginClimb(s);
          } else {
            finishSearch(s, index, kind);
            return null;
          }
          continue;
        }

        if (num(s.localScience, 0) >
              num(s.anchorScience, 0) + 0.035 &&
            dist(s.localX, s.localY, s.anchorX, s.anchorY) > 1.8 &&
            num(s.loops, 0) < 2) {
          s.anchorX = s.localX;
          s.anchorY = s.localY;
          s.anchorScience = s.localScience;
          s.localScience = s.anchorScience;
          s.localX = s.anchorX;
          s.localY = s.anchorY;
          s.loops = num(s.loops, 0) + 1;
          s.step = 0;
          continue;
        }

        if (!s.outerTried) {
          s.phase = 2;
          s.step = 0;
          s.outerTried = 1;
          s.phaseStartScience = num(s.bestScience, 0);
          continue;
        }

        finishSearch(s, index, kind);
        return null;
      }

      const p = ringPoint(cx, cy, step, count, radius, s.angle);
      const d = dist(poseX, poseY, p.x, p.y);
      if (d <= 2.8) {
        s.step = step + 1;
        continue;
      }

      const arc = 2 * Math.PI * radius / count;
      const extra = Math.max(0, count - step - 1) * arc;
      return {
        kind: kind,
        index: index,
        phase: phase,
        step: step,
        x: p.x,
        y: p.y,
        dist: d,
        home: dist(p.x, p.y, baseX, baseY) + 6,
        extra: extra,
        key: kind + ":r:" + index + ":" + phase + ":" + step
      };
    }

    return null;
  }

  function skipTarget(info) {
    if (!info) return;

    if (info.kind === "hint" &&
        info.index >= 0 &&
        info.index < mem.hints.length) {
      const h = mem.hints[info.index];
      if (!h) return;

      if (Math.floor(num(h.phase, 0)) === 0) {
        h.phase = 1;
        h.step = 0;
        h.centerScience = num(mem.scienceEma, scienceNow);
        h.bestScience = h.centerScience;
        h.bestX = poseX;
        h.bestY = poseY;
        h.anchorX = poseX;
        h.anchorY = poseY;
        h.outerTried = 0;
      } else {
        h.step = Math.max(0, Math.floor(num(h.step, 0))) + 1;
      }
    } else if (info.kind === "ambient" && mem.ambient) {
      mem.ambient.step =
        Math.max(0, Math.floor(num(mem.ambient.step, 0))) + 1;
    } else if (info.kind === "global" &&
               info.index >= 0 &&
               info.index < mem.globalPoints.length) {
      mem.globalPoints[info.index].done = true;
      mem.globalIndex = -1;
    } else if (info.kind === "site") {
      mem.siteLock = null;
      mem.siteIgnoreUntil = tNow + 10;
    }
  }

  function updateProgress(key, d, info) {
    if (mem.navKey !== key) {
      mem.navKey = key;
      mem.navBest = d;
      mem.navStuck = 0;
      mem.stuckCount = 0;
      return false;
    }

    if (d < num(mem.navBest, d) - 0.42) {
      mem.navBest = d;
      mem.navStuck = 0;
      mem.stuckCount = 0;
      return false;
    }

    const stuckScale =
      mem.gpsFrozen && minRawRay < 1.5 ? 1.2 : 1;
    mem.navStuck = num(mem.navStuck, 0) + dt * stuckScale;

    if (mem.navStuck > 8.5) {
      mem.navStuck = 0;
      mem.navBest = d;
      mem.stuckCount = num(mem.stuckCount, 0) + 1;
      mem.recoverSign = mem.avoidSign ? -mem.avoidSign : openSide();
      mem.avoidSign = mem.recoverSign;
      mem.avoidClearTime = 0;
      mem.recoverTimer = 1.65;

      if (mem.stuckCount >= 2) {
        skipTarget(info);
        mem.navKey = "";
        mem.stuckCount = 0;
      }
      return true;
    }

    return false;
  }

  function hintInfo(index) {
    const h = mem.hints[index];
    if (!h || h.status >= 2) return null;
    return searchInfo(h, index, "hint");
  }

  function chooseHint() {
    let best = -1;
    let bestScore = -1;
    let bestInfo = null;

    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (!h || h.status >= 2) continue;

      const info = hintInfo(i);
      if (!info ||
          !routeFeasible(info.dist, info.home, carried + 1, info.extra)) {
        continue;
      }

      let score = Math.pow(Math.max(0.1, num(h.value, 1)), 1.18) /
        (48 + info.dist + 0.58 * info.home + 0.27 * info.extra + 9 * carried);
      if (h.status === 1) score *= 1.05;
      if (i === Math.floor(num(mem.currentHint, -1))) score *= 1.07;

      if (score > bestScore) {
        bestScore = score;
        best = i;
        bestInfo = info;
      }
    }

    if (best >= 0) {
      mem.currentHint = best;
      mem.hints[best].status = 1;
      return bestInfo;
    }
    return null;
  }

  function globalInfo(index) {
    const p = mem.globalPoints[index];
    if (!p || p.done) return null;

    const d = dist(poseX, poseY, p.x, p.y);
    if (d <= 3.6) {
      p.done = true;
      if (Math.floor(num(mem.globalIndex, -1)) === index) {
        mem.globalIndex = -1;
      }
      return null;
    }

    return {
      kind: "global",
      index: index,
      x: p.x,
      y: p.y,
      dist: d,
      home: dist(p.x, p.y, baseX, baseY) + 6,
      extra: 0,
      key: "g:" + index
    };
  }

  function chooseGlobal() {
    const old = Math.floor(num(mem.globalIndex, -1));
    if (old >= 0 && old < mem.globalPoints.length) {
      const info = globalInfo(old);
      if (info && routeFeasible(info.dist, info.home, carried + 1, 0)) {
        return info;
      }
      mem.globalIndex = -1;
    }

    let best = -1;
    let bestScore = -1;
    let bestInfo = null;

    for (let i = 0; i < mem.globalPoints.length; i++) {
      const info = globalInfo(i);
      if (!info ||
          !routeFeasible(info.dist, info.home, carried + 1, 0)) {
        continue;
      }

      const score = 1 / (42 + info.dist + 0.54 * info.home + 8 * carried);
      if (score > bestScore) {
        bestScore = score;
        best = i;
        bestInfo = info;
      }
    }

    if (best >= 0) {
      mem.globalIndex = best;
      return bestInfo;
    }

    let anyUndone = false;
    for (let i = 0; i < mem.globalPoints.length; i++) {
      if (mem.globalPoints[i] && !mem.globalPoints[i].done) {
        anyUndone = true;
        break;
      }
    }

    if (!anyUndone &&
        timeLeft > 130 &&
        battery > 0.38 &&
        tNow - num(mem.globalResetAt, -1000) > 10) {
      mem.globalResetAt = tNow;
      for (let i = 0; i < mem.globalPoints.length; i++) {
        const p = mem.globalPoints[i];
        p.done = dist(poseX, poseY, p.x, p.y) < 18;
      }
      mem.globalIndex = -1;

      for (let i = 0; i < mem.globalPoints.length; i++) {
        const info = globalInfo(i);
        if (!info ||
            !routeFeasible(info.dist, info.home, carried + 1, 0)) {
          continue;
        }
        const score = 1 / (42 + info.dist + 0.54 * info.home + 8 * carried);
        if (score > bestScore) {
          bestScore = score;
          best = i;
          bestInfo = info;
        }
      }
      if (best >= 0) {
        mem.globalIndex = best;
        return bestInfo;
      }
    }

    return null;
  }

  function maybeStartAmbient() {
    if (mem.ambient || scienceNow < 0.72) return;

    const lastD = dist(
      poseX, poseY,
      num(mem.ambientLastX, -1e9),
      num(mem.ambientLastY, -1e9)
    );
    if (lastD <= 24) return;

    let nearHint = false;
    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (h && h.status < 2 &&
          dist(poseX, poseY, h.x, h.y) < 27) {
        nearHint = true;
        break;
      }
    }
    if (nearHint && scienceNow < 1.4) return;

    mem.ambient = {
      x: poseX,
      y: poseY,
      phase: 1,
      step: 0,
      angle: 0,
      centerScience: num(mem.scienceEma, scienceNow),
      phaseStartScience: num(mem.scienceEma, scienceNow),
      bestScience: num(mem.scienceEma, scienceNow),
      bestX: poseX,
      bestY: poseY,
      anchorX: poseX,
      anchorY: poseY,
      anchorScience: num(mem.scienceEma, scienceNow),
      localScience: num(mem.scienceEma, scienceNow),
      localX: poseX,
      localY: poseY,
      loops: 0,
      outerTried: 0
    };
  }

  function getTask() {
    maybeStartAmbient();

    let current = Math.floor(num(mem.currentHint, -1));
    if (current >= 0 &&
        current < mem.hints.length &&
        mem.hints[current] &&
        mem.hints[current].status < 2) {
      const info = hintInfo(current);
      if (info &&
          routeFeasible(info.dist, info.home, carried + 1, info.extra)) {
        return info;
      }
      mem.currentHint = -1;
    } else {
      mem.currentHint = -1;
    }

    const hinfo = chooseHint();
    if (hinfo) return hinfo;

    if (mem.ambient) {
      const ainfo = searchInfo(mem.ambient, 0, "ambient");
      if (ainfo &&
          routeFeasible(ainfo.dist, ainfo.home, carried + 1, ainfo.extra)) {
        return ainfo;
      }
    }

    return chooseGlobal();
  }

  function siteDistanceNow() {
    if (siteObs) return Math.max(0, num(siteObs.distance, 99));
    if (mem.siteLock) {
      return dist(poseX, poseY, mem.siteLock.x, mem.siteLock.y);
    }
    return 99;
  }

  function goHome() {
    if (atBase || homeDist <= 2.2) {
      return emit(stopCommands(), false);
    }

    const error = beaconUsable
      ? num(beacon.bearing, 0)
      : wrap(
          deg(Math.atan2(baseY - poseY, baseX - poseX)) - mem.theta
        );

    if (updateProgress("home", homeDist, null)) {
      return recoveryAction();
    }

    let speed = homeDist > 34 ? 0.38 : (homeDist > 8 ? 0.29 : 0.19);
    if (timeLeft < homeSeconds(homeDist, carried) + 18) speed = 0.39;
    return emit(navCommands(error, speed), false);
  }

  if (delivered > oldDelivered && carried === 0) {
    mem.returning = false;
    mem.sampleActive = false;
    mem.stillTime = 0;
    mem.holdI = [0, 0];
  }
  if (mem.returning && atBase && carried === 0) {
    mem.returning = false;
    mem.sampleActive = false;
    mem.stillTime = 0;
    mem.holdI = [0, 0];
  }

  if (mem.sampleActive) {
    if (drillProgress > num(mem.lastDrillProgress, 0) + 0.035) {
      mem.lastDrillProgress = drillProgress;
      mem.lastDrillProgressT = tNow;
    }

    const elapsed = tNow - num(mem.sampleStart, tNow);
    const sd = siteDistanceNow();
    const noProgressTime = tNow - num(mem.lastDrillProgressT, tNow);
    const timedOut =
      (elapsed > 34 && noProgressTime > 12 && drillProgress < 5.8) ||
      elapsed > 48;
    const lostSite = !!siteObs &&
      sd > 3.2 &&
      drillProgress < 0.20 &&
      elapsed > 4.0;

    if ((timedOut || lostSite) && carried === oldCarried) {
      mem.sampleActive = false;
      mem.pendingMeta = null;
      mem.siteLock = null;
      mem.stillTime = 0;
      mem.sampleFailures = num(mem.sampleFailures, 0) + 1;
      mem.siteIgnoreUntil = tNow + 8;
      mem.holdI = [0, 0];
    } else {
      if (mem.siteLock && !mem.pendingMeta) {
        mem.pendingMeta = {
          x: mem.siteLock.x,
          y: mem.siteLock.y,
          value: mem.siteLock.value
        };
      }

      const c = holdCommands();
      const still = Math.max(Math.abs(wl), Math.abs(wr)) < 0.14;
      const inRange = sd <= 1.55 || drillProgress > 0.05 || elapsed < 0.8;
      const drill = still && inRange && drillProgress < 6.25;
      return emit(c, drill);
    }
  }

  if (!mem.returning && !mem.sampleActive) {
    if (carried >= mem.capacity) {
      mem.returning = true;
    } else if (!atBase &&
               battery < homeNeed(homeDist, carried) +
                 (carried > 0 ? 0.11 : 0.14)) {
      mem.returning = true;
    } else if (!atBase &&
               timeLeft < homeSeconds(homeDist, carried) +
                 (carried > 0 ? 16 : 24)) {
      mem.returning = true;
    }
  }

  if (o.bumped && !mem.prevBumped && !mem.sampleActive && !atBase) {
    mem.recoverSign = openSide();
    mem.recoverTimer = 1.75;
    mem.avoidSign = mem.recoverSign;
    mem.avoidClearTime = 0;
  }
  mem.prevBumped = !!o.bumped;

  if (mem.gpsFrozen &&
      minRawRay < 1.45 &&
      !mem.sampleActive &&
      !atBase &&
      tNow - num(mem.lastFrozenEscape, -1000) > 8) {
    mem.lastFrozenEscape = tNow;
    mem.recoverSign = mem.avoidSign ? -mem.avoidSign : openSide();
    mem.recoverTimer = Math.max(num(mem.recoverTimer, 0), 1.55);
    mem.avoidSign = mem.recoverSign;
  }

  if (atBase && carried > 0) {
    return emit(stopCommands(), false);
  }

  if (mem.recoverTimer > 0 && !mem.sampleActive && !atBase) {
    return recoveryAction();
  }

  if (mem.returning && !atBase) {
    return goHome();
  }

  if (atBase && carried === 0 && maxWheel > 0.28) {
    return emit(stopCommands(), false);
  }

  if (atBase && carried === 0 && battery < 0.46 && timeLeft > 85) {
    return emit(stopCommands(), false);
  }

  if (siteObs &&
      carried < mem.capacity &&
      !mem.returning &&
      tNow >= num(mem.siteIgnoreUntil, 0)) {
    const sd = Math.max(0, num(siteObs.distance, 99));
    const sb = num(siteObs.bearing, 0);
    const a = rad(mem.theta + sb);
    const sx = poseX + sd * Math.cos(a);
    const sy = poseY + sd * Math.sin(a);
    const siteHome = dist(sx, sy, baseX, baseY);

    if (!routeFeasible(sd, siteHome + 6, carried + 1, 0)) {
      if (!atBase) {
        mem.returning = true;
        return goHome();
      }
      mem.siteIgnoreUntil = tNow + 30;
    } else if (sd <= 1.32) {
      const c = holdCommands();
      const still = Math.max(Math.abs(wl), Math.abs(wr)) < 0.14;

      if (still && sd <= 1.44) {
        mem.stillTime = num(mem.stillTime, 0) + dt;
      } else {
        mem.stillTime = 0;
      }

      let drill = false;
      if (mem.stillTime >= 0.25 && still && sd <= 1.44) {
        mem.sampleActive = true;
        mem.sampleStart = tNow;
        mem.lastDrillProgress = 0;
        mem.lastDrillProgressT = tNow;
        mem.holdI = [0, 0];
        mem.pendingMeta = mem.siteLock
          ? {
              x: mem.siteLock.x,
              y: mem.siteLock.y,
              value: mem.siteLock.value
            }
          : {
              x: sx,
              y: sy,
              value: Math.max(0.1, num(siteObs.value, 1))
            };
        drill = true;
      }

      return emit(c, drill);
    } else if (tNow >= num(mem.siteIgnoreUntil, 0)) {
      mem.stillTime = 0;
      if (updateProgress("site", sd, { kind: "site" })) {
        return recoveryAction();
      }
      const speed = clamp((sd - 0.80) * 0.21, 0.09, 0.36);
      return emit(navCommands(sb, speed), false);
    }
  }

  const info = getTask();
  if (!info) {
    if (carried > 0 || !atBase) {
      mem.returning = true;
      return goHome();
    }
    return emit(stopCommands(), false);
  }

  if (!routeFeasible(info.dist, info.home, carried + 1, info.extra)) {
    if (carried > 0 || !atBase) {
      mem.returning = true;
      return goHome();
    }
    return emit(stopCommands(), false);
  }

  if (updateProgress(info.key, info.dist, info)) {
    return recoveryAction();
  }

  const bearing = deg(Math.atan2(info.y - poseY, info.x - poseX));
  const error = wrap(bearing - mem.theta);

  let speed;
  if (info.kind === "hint" && info.phase === 0) {
    speed = info.dist > 35 ? 0.38 : (info.dist > 10 ? 0.31 : 0.23);
  } else if (info.kind === "hint") {
    speed = info.dist > 9 ? 0.30 : 0.21;
  } else if (info.kind === "ambient") {
    speed = info.dist > 8 ? 0.29 : 0.21;
  } else {
    speed = info.dist > 18 ? 0.37 : (info.dist > 5 ? 0.29 : 0.21);
  }

  return emit(navCommands(error, speed), false);
}

function act(obs, mem) {
  const PI = Math.PI;
  const D2R = PI / 180;
  const R2D = 180 / PI;

  function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
  function wrap(a) {
    a = a % 360;
    if (a > 180) a -= 360;
    if (a < -180) a += 360;
    return a;
  }
  function dist(x1, y1, x2, y2) {
    let dx = x1 - x2, dy = y1 - y2;
    return Math.sqrt(dx * dx + dy * dy);
  }
  function countCarried(o) {
    let c = o.carried;
    if (typeof c === "number") return c;
    if (Array.isArray(c)) return c.length;
    if (c && typeof c.length === "number") return c.length;
    return c ? 1 : 0;
  }

  let t = (obs.t != null ? obs.t : 0);

  if (!mem.init) {
    mem.init = true;
    mem.mode = "choose";
    let m = obs.mission || {};
    let sz = m.size;
    if (typeof sz === "number") {
      mem.sizeX = sz;
      mem.sizeY = sz;
    } else if (sz && typeof sz === "object") {
      mem.sizeX = Number(sz.x != null ? sz.x : (sz.w != null ? sz.w : 400));
      mem.sizeY = Number(sz.y != null ? sz.y : (sz.h != null ? sz.h : 400));
    } else {
      mem.sizeX = 400;
      mem.sizeY = 400;
    }
    if (!(mem.sizeX > 10)) mem.sizeX = 400;
    if (!(mem.sizeY > 10)) mem.sizeY = 400;

    let mb = m.base;
    mem.base = {
      x: (mb && isFinite(mb.x)) ? Number(mb.x) : Number(obs.x),
      y: (mb && isFinite(mb.y)) ? Number(mb.y) : Number(obs.y)
    };
    mem.capacity = Number(m.capacity || 5);
    if (!(mem.capacity >= 1)) mem.capacity = 5;
    mem.seconds = Number(m.seconds || 1200);

    mem.hints = [];
    let hs = (m.hints && m.hints.length) ? m.hints : [];
    for (let i = 0; i < hs.length; i++) {
      let h = hs[i] || {};
      let hx = Number(h.x);
      let hy = Number(h.y);
      let hv = Number(h.estimate);
      if (!isFinite(hx) || !isFinite(hy)) continue;
      if (!isFinite(hv) || hv < 0) hv = 1;
      mem.hints.push({
        id: mem.hints.length,
        x: hx,
        y: hy,
        val: hv,
        status: 0,
        attempts: 0,
        lastTry: -1
      });
    }
    let vals = [];
    for (let i = 0; i < mem.hints.length; i++) vals.push(mem.hints[i].val);
    vals.sort(function (a, b) { return a - b; });
    mem.valMed = vals.length ? vals[Math.floor(vals.length / 2)] : 1;
    if (!(mem.valMed > 0)) mem.valMed = 1;
    mem.valMax = 0;
    for (let i = 0; i < vals.length; i++) if (vals[i] > mem.valMax) mem.valMax = vals[i];
    if (!(mem.valMax > 0)) mem.valMax = mem.valMed;

