    mem.gpsHist = [];
    mem.gpsJumpTime = 0;

    mem.raysClean = [15, 15, 15, 15, 15, 15, 15, 15, 15];
    mem.rawRays = [15, 15, 15, 15, 15, 15, 15, 15, 15];
    mem.rayLast = [null, null, null, null, null, null, null, null, null];
    mem.rayStill = [0, 0, 0, 0, 0, 0, 0, 0, 0];
