    mem.currentSample = null;
    mem.holdPos = null;
    mem.siteReturn = null;
    mem.siteLostT = 0;
    mem.targetStart = -1;
    mem.targetStartDist = 0;
    mem.returnReason = "";
    mem.chargeStart = -1;
    mem.localCooldown = 0;

    mem.explorePts = null;
    mem.exploreStep = 0;

    mem.escapeUntil = 0;
    mem.escapeSide = 1;
    mem.bumpCount = 0;
    mem.stuck = 0;
    mem.lastStuckCheckT = t;
    mem.lastStuckPos = { x: mem.pos.x, y: mem.pos.y };

    mem.sandFlag = false;
    mem.drillCmd = false;
    mem.lastT = null;
    mem.lastHeadEst = mem.headEst;
  }

  let dt = 0.1;
  if (mem.lastT != null) {
    dt = t - mem.lastT;
    if (!(dt > 0.001 && dt < 1.0)) dt = 0.1;
  }

  let wl = Number(obs.wheelLeft || 0);
  let wr = Number(obs.wheelRight || 0);
  let vLin = (wl + wr) / 2;

  let oldPos = { x: mem.pos.x, y: mem.pos.y };

  let rawH = Number(obs.heading);
  if (!isFinite(rawH)) rawH = mem.headEst;
  let wheelYaw = ((wr - wl) / 0.6) * dt * R2D;
  let predH = wrap(mem.headEst + wheelYaw);

  let rawDiff = (mem.lastRawH != null) ? wrap(rawH - mem.lastRawH) : 0;
  let correctedRaw = wrap(rawH - (mem.hBias || 0));
  let jump = false;
  if (Math.abs(rawDiff) > 32 && Math.abs(wheelYaw) < 12) jump = true;

  if (jump) {
    mem.headEst = predH;
    mem.compassFaultUntil = Math.max(mem.compassFaultUntil || 0, t + 1.0);
  } else {
    let diff = wrap(correctedRaw - predH);
    if (Math.abs(diff) > 35 && t < (mem.compassFaultUntil || 0)) {
      mem.headEst = predH;
    } else if (Math.abs(diff) > 50) {
      mem.badHeadingTime = (mem.badHeadingTime || 0) + dt;
      if (mem.badHeadingTime > 1.0) {
        mem.headEst = correctedRaw;
        mem.badHeadingTime = 0;
      } else {
        mem.headEst = wrap(predH + diff * 0.25);
      }
    } else {
      mem.badHeadingTime = 0;
      if (Math.abs(vLin) < 0.04) {
        mem.headEst = correctedRaw;
      } else {
        let w = Math.abs(diff) > 10 ? 0.45 : 0.82;
        mem.headEst = wrap(predH + diff * w);
      }
    }
  }
  mem.lastRawH = rawH;

  let vx = vLin * Math.cos(mem.headEst * D2R);
  let vy = vLin * Math.sin(mem.headEst * D2R);
  let prX = mem.pos.x + vx * dt;
  let prY = mem.pos.y + vy * dt;

  let rawX = Number(obs.x);
  let rawY = Number(obs.y);
  if (!isFinite(rawX)) rawX = mem.lastGPS.x;
  if (!isFinite(rawY)) rawY = mem.lastGPS.y;

  let rawMoved = dist(rawX, rawY, mem.lastGPS.x, mem.lastGPS.y);
  let rawChanged = rawMoved > 0.02;

  if (rawChanged) {
    mem.freezeTime = 0;
  } else if (Math.abs(vLin) > 0.12) {
    mem.freezeTime = (mem.freezeTime || 0) + dt;
  }
  if ((mem.freezeTime || 0) > 2.0) mem.gpsFrozen = true;

  if (mem.gpsFrozen && rawChanged) {
    mem.pos.x = rawX;
    mem.pos.y = rawY;
    mem.gpsFrozen = false;
    mem.freezeTime = 0;
    mem.gpsJumpTime = 0;
  } else if (!mem.gpsFrozen) {
    if (rawChanged) {
      let dPred = dist(rawX, rawY, prX, prY);
      if (dPred < 6) {
        mem.pos.x = rawX * 0.75 + prX * 0.25;
        mem.pos.y = rawY * 0.75 + prY * 0.25;
        mem.gpsJumpTime = 0;
      } else if (dPred < 22) {
        mem.pos.x = rawX * 0.30 + prX * 0.70;
        mem.pos.y = rawY * 0.30 + prY * 0.70;
        mem.gpsJumpTime = 0;
      } else {
        mem.pos.x = prX;
        mem.pos.y = prY;
        mem.gpsJumpTime = (mem.gpsJumpTime || 0) + dt;
        if (mem.gpsJumpTime > 2.0) {
          mem.pos.x = rawX;
          mem.pos.y = rawY;
          mem.gpsJumpTime = 0;
        }
      }
    } else {
      mem.pos.x = prX;
      mem.pos.y = prY;
    }
  } else {
    mem.pos.x = prX;
    mem.pos.y = prY;
  }
  if (!isFinite(mem.pos.x)) mem.pos.x = oldPos.x;
  if (!isFinite(mem.pos.y)) mem.pos.y = oldPos.y;
  mem.lastGPS = { x: rawX, y: rawY };

  if (obs.beacon && isFinite(obs.beacon.distance) && isFinite(obs.beacon.bearing)) {
    let absB = (mem.headEst + Number(obs.beacon.bearing)) * D2R;
    let bd = Number(obs.beacon.distance);
    let bx = mem.base.x - Math.cos(absB) * bd;
    let by = mem.base.y - Math.sin(absB) * bd;
    let dbx = dist(bx, by, mem.pos.x, mem.pos.y);
    let wb = mem.gpsFrozen ? 0.20 : 0.035;
    if (dbx < 60) {
