  }

  if (!mem.gpsFrozen && rawChanged) {
    mem.gpsHist.push({ t: t, x: rawX, y: rawY, h: rawH });
    while (mem.gpsHist.length > 25) mem.gpsHist.shift();
  } else if (mem.gpsFrozen) {
    mem.gpsHist.length = 0;
  }

  if (mem.gpsHist.length >= 10 && Math.abs(vLin) > 0.25) {
    let a = mem.gpsHist[0];
    let b = mem.gpsHist[mem.gpsHist.length - 1];
    let gd = dist(a.x, a.y, b.x, b.y);
    let gt = b.t - a.t;
    if (gd > 1.2 && gt > 0.7) {
      let meanH = 0;
      let maxDev = 0;
      for (let i = 0; i < mem.gpsHist.length; i++) meanH += mem.gpsHist[i].h;
      meanH /= mem.gpsHist.length;
      for (let i = 0; i < mem.gpsHist.length; i++) {
        let dv = Math.abs(wrap(mem.gpsHist[i].h - meanH));
        if (dv > maxDev) maxDev = dv;
      }
      if (maxDev < 8 && Math.abs(wr - wl) < 0.35) {
        let course = Math.atan2(b.y - a.y, b.x - a.x) * R2D;
        let biasObs = wrap(meanH - course);
        let delta = wrap(biasObs - mem.hBias);
        if (Math.abs(delta) < 30) {
          let newBias = wrap(mem.hBias + delta * 0.08);
          let applied = wrap(newBias - mem.hBias);
          mem.hBias = newBias;
          mem.headEst = wrap(mem.headEst - applied);
          mem.hBiasUpdates++;
        }
      }
    }
  }

  let movedGeo = dist(oldPos.x, oldPos.y, mem.pos.x, mem.pos.y);
  let movedOdo = Math.abs(vLin) * dt;
  let turnedAbs = Math.abs(wrap(mem.headEst - (mem.lastHeadEst || mem.headEst)));
  mem.lastHeadEst = mem.headEst;

  let rawVals = [15, 15, 15, 15, 15, 15, 15, 15, 15];
  if (obs.rays && obs.rays.length) {
    for (let i = 0; i < 9; i++) {
      let vv = Number(obs.rays[i]);
      if (!isFinite(vv) || vv < 0) vv = 15;
      if (vv > 15) vv = 15;
      rawVals[i] = vv;
    }
  }

  let maxRawRay = 0;
  let minRawRay = 20;
  for (let i = 0; i < 9; i++) {
    let vv = rawVals[i];
    if (vv > maxRawRay) maxRawRay = vv;
    if (vv < minRawRay) minRawRay = vv;
    if (mem.rayLast[i] == null) mem.rayLast[i] = vv;
    let same = Math.abs(vv - mem.rayLast[i]) < 0.03;
    let shouldChange = (movedOdo > 0.05 || turnedAbs > 1.0 || Math.abs(wheelYaw) > 1.0);
    if (same && shouldChange) {
      mem.rayStill[i] += dt;
    } else if (!same) {
      mem.rayStill[i] = 0;
    }
    if (mem.rayStill[i] > 3.2) {
      mem.rayBad[i] = true;
    } else if (!same) {
      mem.rayBad[i] = false;
    }
    if (vv < 0.15 && mem.rayStill[i] > 1.0) mem.rayBad[i] = true;
    mem.rayLast[i] = vv;
  }
  mem.visibility = maxRawRay;

  for (let i = 0; i < 9; i++) {
    let vv = rawVals[i];
    if (vv < 0.02) vv = 0.02;
    if (vv > 15) vv = 15;
    if (mem.rayBad[i] && vv < 14.5) vv = 15;
    mem.raysClean[i] = vv;
  }

  mem.rayBadFront = 0;
  if (mem.rayBad[1] || mem.rayBad[2] || mem.rayBad[3] || mem.rayBad[4] || mem.rayBad[5]) {
    mem.rayBadFront = 1;
  }

  if (Math.abs(vLin) > 0.10) {
    let av = Math.abs(vLin);
    mem.avgSpeed = mem.avgSpeed * 0.995 + av * 0.005;
    if (!(mem.avgSpeed > 0.25)) mem.avgSpeed = 0.25;
  }

  let battery = Number(obs.battery);
  if (!isFinite(battery)) battery = mem.lastBattery;
  let solar = Number(obs.solar || 0);
  let consumption = solar * dt - (battery - mem.lastBattery);

  if (!obs.docked && Math.abs(vLin) > 0.03) {
    let capProg = Math.abs(vLin) * dt * 2.0 + 0.05;
    let dProg = mem.gpsFrozen ? Math.abs(vLin) * dt : Math.min(movedGeo, capProg);
    if (dProg > 0.008) {
      if (consumption > 0) {
        mem.energyDrain += consumption;
        mem.energyDist += dProg;
      }
      if (mem.energyDist > 35) {
        let cst = mem.energyDrain / mem.energyDist;
        if (cst > 0.00002 && cst < 0.02) {
          mem.costPerM = mem.costPerM * 0.80 + cst * 0.20;
        }
        mem.energyDrain = 0;
        mem.energyDist = 0;
      }
    }
  }
  if (movedOdo > 0.02 && !mem.gpsFrozen) {
    let slipRatio = movedGeo / movedOdo;
    if (slipRatio < 0.55) {
      mem.sandFlag = true;
    } else if (slipRatio > 0.85) {
      mem.sandFlag = false;
    }
  }
  mem.lastBattery = battery;

  function setTargets(a, b) {
    if (!isFinite(a)) a = 0;
    if (!isFinite(b)) b = 0;
    mem.targetL = clamp(a, -2.8, 2.8);
    mem.targetR = clamp(b, -2.8, 2.8);
    mem.lastTargetV = (mem.targetL + mem.targetR) / 2;
  }

  function rayAt(rel) {
    let a = clamp(rel, -80, 80);
    let idx = (a + 80) / 20;
    let i = Math.floor(idx);
    if (i < 0) i = 0;
    if (i > 7) i = 7;
    let f = idx - i;
    if (f < 0) f = 0;
    if (f > 1) f = 1;
    let d1 = mem.raysClean[i];
    let d2 = mem.raysClean[i + 1];
    if (!isFinite(d1)) d1 = 15;
    if (!isFinite(d2)) d2 = 15;
    return d1 * (1 - f) + d2 * f;
  }

  function boundaryClear(rel) {
    let ang = (mem.headEst + rel) * D2R;
    let dx = Math.cos(ang);
    let dy = Math.sin(ang);
    let margin = 1.0;
    let tx = 1e9, ty = 1e9;
    if (dx > 0.0001) tx = (mem.sizeX - margin - mem.pos.x) / dx;
    else if (dx < -0.0001) tx = (margin - mem.pos.x) / dx;
    if (dy > 0.0001) ty = (mem.sizeY - margin - mem.pos.y) / dy;
    else if (dy < -0.0001) ty = (margin - mem.pos.y) / dy;
    let d = 1e9;
    if (tx > 0) d = Math.min(d, tx);
    if (ty > 0) d = Math.min(d, ty);
    if (!(d > 0)) d = 0;
    return Math.min(d, 15);
  }

  function activateAvoid() {
    let left = rayAt(20) + 0.7 * rayAt(40) + 0.4 * rayAt(60);
    let right = rayAt(-20) + 0.7 * rayAt(-40) + 0.4 * rayAt(-60);
    mem.avoidSide = left >= right ? 1 : -1;
    mem.avoidActive = true;
    mem.avoidStart = t;
  }

  function controlHeading(desiredAbs, vDes) {
    let goalRel = wrap(desiredAbs - mem.headEst);
    let front = Math.min(rayAt(-25), rayAt(0), rayAt(25));
    let direct = rayAt(clamp(goalRel, -80, 80));

    if (front < 3.0 || direct < 2.6) {
      if (!mem.avoidActive) activateAvoid();
      else if (!mem.avoidSide) mem.avoidSide = 1;
      mem.clearTime = 0;
    } else {
      mem.clearTime += dt;
      if (mem.avoidActive && mem.clearTime > 1.2) {
        mem.avoidActive = false;
        mem.avoidSide = 0;
      }
    }

    let bestScore = -1e100;
    let bestB = 0;
    let bestClear = 0;

    function evalB(b) {
      let cl = rayAt(b);
      let bc = boundaryClear(b);
      if (bc < cl) cl = bc;
      let eff = cl - 0.75;
      if (eff < 0) eff = 0;
      let align = Math.cos((b - goalRel) * D2R);
      let sc = Math.min(eff, 6) * 1.8 + align * 5.0 - Math.abs(b) * 0.002;
      if (mem.avoidActive) sc += (mem.avoidSide || 0) * b * 0.028;
      if (cl < 1.1) sc -= 14;
      else if (cl < 1.6) sc -= 4;
      return [sc, cl];
    }

    for (let b = -80; b <= 80; b += 8) {
      let r = evalB(b);
      if (r[0] > bestScore) {
        bestScore = r[0];
        bestB = b;
        bestClear = r[1];
      }
    }
    if (goalRel >= -80 && goalRel <= 80) {
      let r = evalB(goalRel);
      if (r[0] > bestScore + 0.001) {
        bestScore = r[0];
        bestB = goalRel;
        bestClear = r[1];
      }
    }

    let sp = vDes;
    if (Math.abs(bestB) > 75) sp = Math.min(sp, 0.12);
    else if (Math.abs(bestB) > 50) sp = Math.min(sp, 0.45);
    else if (Math.abs(bestB) > 30) sp = Math.min(sp, 0.80);

    if (bestClear < 1.2) sp = 0;
    else if (bestClear < 2.2) sp = Math.min(sp, Math.max(0, (bestClear - 0.9) * 0.60));
    else if (bestClear < 4.0) sp = Math.min(sp, 1.10);
    else if (bestClear < 6.0) sp = Math.min(sp, 1.40);

    if (mem.visibility < 11) sp = Math.min(sp, 1.05);
    if (mem.visibility < 8) sp = Math.min(sp, 0.68);
    if (mem.visibility < 5) sp = Math.min(sp, 0.45);
    if (mem.rayBadFront) sp = Math.min(sp, 1.00);
    if (t < (mem.compassFaultUntil || 0)) sp = Math.min(sp, 0.80);
    if (mem.gpsFrozen) sp = Math.min(sp, 1.00);
    if (sp < 0) sp = 0;

    let omega = clamp(bestB * D2R * 2.2, -2.7, 2.7);
    if (Math.abs(bestB) < 2) omega = bestB * D2R * 2.0;

    let half = 0.3;
    setTargets(sp - omega * half, sp + omega * half);
  }

  function controlRelative(bearingDeg, speed) {
    controlHeading(mem.headEst + Number(bearingDeg), speed);
  }

  function navigateTo(gx, gy, speed, stopDist) {
    let dx = gx - mem.pos.x;
    let dy = gy - mem.pos.y;
    let d = Math.sqrt(dx * dx + dy * dy);
    if (d <= stopDist) {
      setTargets(0, 0);
      return d;
    }
    let ang = Math.atan2(dy, dx) * R2D;
    let sp = speed;
    if (d < stopDist + 2) sp = Math.min(sp, 0.35);
    else if (d < stopDist + 6) sp = Math.min(sp, 0.70);
    controlHeading(ang, sp);
    return d;
  }

  function desiredCharge(o) {
    let dc = 0.93;
    if (o.timeLeft < 500) dc = 0.85;
    if (o.timeLeft < 320) dc = 0.72;
    if (o.timeLeft < 180) dc = 0.52;
    if (o.timeLeft < 80) dc = 0.30;
    return dc;
  }

  function shouldReturn(o, cN) {
    let db = dist(mem.pos.x, mem.pos.y, mem.base.x, mem.base.y);
    if (o.beacon && isFinite(o.beacon.distance)) {
      db = Math.min(db, Number(o.beacon.distance));
    }
    let b = Number(o.battery);
    let cost = mem.costPerM || 0.0009;
    if (!(cost > 0.00001)) cost = 0.0009;
    let factor = 1 + 0.28 * cN;
    let reserve = 0.035 + cost * factor * db * 1.8;
    if (mem.sandFlag) reserve += 0.025;

    if (cN > 0 && b < reserve + 0.01) return true;
    if (b < 0.12) return true;
    if (cN > 0 && b < 0.22) return true;
    if (b < 0.18 && db > 10) return true;

    let spd = Math.max(0.55, Math.min(1.4, mem.avgSpeed || 0.9));
    let timeNeed = db / spd + 25 + cN * 2;
    if (cN > 0 && o.timeLeft < timeNeed + 15) return true;
    if (cN > 0 && o.timeLeft < 90) return true;

    return false;
  }

  function markSample(x, y, prefHint) {
    if (prefHint && dist(x, y, prefHint.x, prefHint.y) < 40) {
      prefHint.status = 1;
      return;
    }
    let best = null;
    let bd = 36;
    for (let i = 0; i < mem.hints.length; i++) {
      let h = mem.hints[i];
      let d = dist(x, y, h.x, h.y);
      if (d < bd) {
        bd = d;
        best = h;
      }
    }
    if (best) best.status = 1;
  }

  function startSearchAt(h, o, now, fixedR) {
    let med = mem.valMed || 1;
    let R = fixedR || 0;
    if (!R) {
      let val = (h && h.val) ? h.val : med;
      let ratio = Math.max(0.15, val / med);
      R = 18 + Math.min(6, 5 * Math.sqrt(ratio));
      if (val >= (mem.valMax || 0) * 0.8) R = Math.max(R, 22);
      if (o.timeLeft < 350) R = Math.min(R, 20);
      if (o.battery < 0.35) R = Math.min(R, 17);
      R = clamp(R, 13, 27);
    } else {
      R = clamp(R, 8, 40);
    }
    let spacing = 12;
    let a = spacing / (2 * PI);
    let maxDist = R * R / (2 * a) + 15;
    mem.search = {
      hint: h,
      center: { x: h.x, y: h.y },
      dist: 4.0,
      a: a,
      spacing: spacing,
      phi: 0,
      maxR: R,
      maxDist: maxDist,
      start: now,
      noSci: 0,
      lastX: mem.pos.x,
      lastY: mem.pos.y
    };
    mem.mode = "search";
    mem.targetStart = mem.targetStart || now;
  }

  function abortSite(forceReturn, cN, now) {
    let ret = mem.siteReturn;
    mem.currentSample = null;
    mem.holdPos = null;
    mem.drillCmd = false;
    mem.siteLostT = 0;
    mem.siteReturn = null;

    if (forceReturn) {
      mem.mode = "return";
      mem.returnReason = "battery";
      mem.target = null;
      mem.search = null;
      return;
    }
    if (ret && ret.mode === "return") {
      mem.mode = "return";
      mem.returnReason = ret.returnReason || "deliver";
      mem.target = null;
      mem.search = null;
      return;
    }
    if (ret && ret.target && cN < mem.capacity &&
      (!ret.target.h || ret.target.h.status === 0)) {
      mem.target = ret.target;
      mem.targetStart = ret.targetStart || now;
      mem.targetStartDist = ret.targetStartDist || dist(mem.pos.x, mem.pos.y, ret.target.x, ret.target.y);
      if (ret.mode === "search" && ret.search &&
        (!ret.search.hint || ret.search.hint.status === 0)) {
        mem.search = ret.search;
        mem.mode = "search";
      } else if (ret.mode === "toTarget") {
        mem.search = null;
        mem.mode = "toTarget";
      } else {
        mem.mode = "choose";
      }
    } else {
      mem.mode = "choose";
    }
  }

  function getExplorePoint(o) {
    if (!mem.explorePts) {
      mem.explorePts = [];
      let step = Math.max(45, Math.min(mem.sizeX, mem.sizeY) / 6);
      if (!(step > 20)) step = 60;
      mem.exploreStep = step;
      for (let x = step * 0.5; x < mem.sizeX - 10; x += step) {
        for (let y = step * 0.5; y < mem.sizeY - 10; y += step) {
          mem.explorePts.push({ x: x, y: y, done: false });
        }
      }
      if (mem.explorePts.length === 0) {
        mem.explorePts.push({ x: mem.sizeX * 0.5, y: mem.sizeY * 0.5, done: false });
      }
    }
    for (let i = 0; i < mem.explorePts.length; i++) {
      let p = mem.explorePts[i];
      if (!p.done && dist(mem.pos.x, mem.pos.y, p.x, p.y) < 16) p.done = true;
    }
    let best = null;
    let bd = 1e100;
    for (let i = 0; i < mem.explorePts.length; i++) {
      let p = mem.explorePts[i];
      if (p.done) continue;
      let d = dist(mem.pos.x, mem.pos.y, p.x, p.y);
      if (d < bd) {
        bd = d;
        best = p;
      }
    }
    return best;
  }

  function chooseNext(o, now) {
    let cN = countCarried(o);
    if (cN >= mem.capacity) {
      mem.mode = "return";
      mem.returnReason = "full";
      return;
    }

    let db = dist(mem.pos.x, mem.pos.y, mem.base.x, mem.base.y);
    if (o.beacon && isFinite(o.beacon.distance)) {
      db = Math.min(db, Number(o.beacon.distance));
    }

    if (cN > 0 && (o.docked || db < 3.0)) {
      mem.mode = "return";
      mem.returnReason = "deliver";
      return;
    }

    let atBase = (db < 3.0 || o.docked);
    let dc = desiredCharge(o);
    if (atBase && cN === 0 && o.battery < dc && o.timeLeft > 60) {
      mem.mode = "charge";
      mem.chargeStart = now;
      return;
    }

    if (shouldReturn(o, cN)) {
      if (cN > 0) {
        mem.mode = "return";
        mem.returnReason = "battery/time";
      } else if (atBase) {
        mem.mode = "charge";
        mem.chargeStart = now;
      } else {
        mem.mode = "return";
        mem.returnReason = "battery";
      }
      return;
    }

    let count0 = 0;
    for (let i = 0; i < mem.hints.length; i++) {
      if (mem.hints[i].status === 0) count0++;
    }
    let considerDeferred = (count0 === 0);

    let best = null;
    let bestScore = -1e100;
    let bestD = 0;
    let bestDb = 0;

    for (let i = 0; i < mem.hints.length; i++) {
      let h = mem.hints[i];
      let ok = false;
      if (h.status === 0) ok = true;
      else if (considerDeferred && h.status === 3 && h.attempts < 3) ok = true;
      if (!ok) continue;

      let val = h.val > 0 ? h.val : (mem.valMed * 0.1);
      let d = dist(mem.pos.x, mem.pos.y, h.x, h.y);
      let hdb = dist(h.x, h.y, mem.base.x, mem.base.y);
      let searchCost = 25 + Math.min(80, 25 * Math.sqrt(Math.max(0, val / (mem.valMed || 1))));
      let cost;
      if (cN > 0) cost = d + 0.55 * hdb + searchCost;
      else cost = d + 0.30 * hdb + searchCost;

      let score = (val + 0.03 * (mem.valMed || 1)) /
        Math.pow(cost + 30, 1.20);
      score *= Math.pow(0.5 + val / (mem.valMed || 1), 0.35);
      if (o.timeLeft < 350) {
        score *= Math.pow(250 / (hdb + 80), 0.25);
      }
      if (h.attempts > 0) score *= 0.82;

      if (score > bestScore) {
        bestScore = score;
        best = h;
        bestD = d;
        bestDb = hdb;
      }
    }

    if (best) {
      best.attempts++;
      best.lastTry = now;
      mem.target = {
        x: best.x,
        y: best.y,
        val: best.val,
        h: best,
        kind: "hint"
      };
      mem.mode = "toTarget";
      mem.targetStart = now;
      mem.targetStartDist = bestD;
      mem.search = null;
      return;
    }

    if (cN > 0) {
      mem.mode = "return";
      mem.returnReason = "deliver";
      return;
    }

    if (o.science > 0.0000001 && now > (mem.localCooldown || 0) &&
      o.timeLeft > 100 && cN < mem.capacity) {
      let h = {
        x: mem.pos.x,
        y: mem.pos.y,
        val: Math.max(mem.valMed * 2, 1),
        status: 0,
        attempts: 0,
        local: true
      };
      startSearchAt(h, o, now, 34);
      mem.localCooldown = now + 150;
      return;
    }

    let p = getExplorePoint(o);
    if (p) {
      mem.target = {
        x: p.x,
        y: p.y,
        val: 0.1,
        h: null,
        kind: "explore",
        point: p
      };
      mem.mode = "toTarget";
      mem.targetStart = now;
      mem.targetStartDist = dist(mem.pos.x, mem.pos.y, p.x, p.y);
      mem.search = null;
      return;
    }

    if (atBase) {
      mem.mode = "charge";
      mem.chargeStart = now;
    } else {
      mem.mode = "return";
      mem.returnReason = "idle";
    }
  }

  function wheelPid(target, actual, st) {
    let e = target - actual;
    if (Math.abs(e) > 1e-6) {
      st.i += e * dt * 0.95;
      if (st.i > 1.5) st.i = 1.5;
      if (st.i < -1.5) st.i = -1.5;
    }
    let kp = Math.abs(target) < 0.06 ? 0.90 : 0.16;
    let ff = target * 0.30;
    let u = ff + kp * e + st.i;
    if (Math.abs(target) > 0.05 && Math.abs(u) < 0.06 && Math.abs(e) > 0.03) {
      u += u >= 0 ? 0.04 : -0.04;
    }
    if (Math.abs(target) < 0.05 && Math.abs(actual) < 0.02) u *= 0.5;
    return clamp(u, -1, 1);
  }

  let cN = countCarried(obs);

  if (cN > mem.lastCarried) {
    if (mem.currentSample) {
      markSample(mem.currentSample.x, mem.currentSample.y, mem.currentSample.fromHint);
    }
    let ret = mem.siteReturn;
    mem.lastCarried = cN;
    mem.currentSample = null;
    mem.holdPos = null;
    mem.drillCmd = false;
    mem.siteLostT = 0;
    mem.siteReturn = null;

    if (cN >= mem.capacity) {
      mem.mode = "return";
      mem.returnReason = "full";
      mem.target = null;
      mem.search = null;
    } else if (ret && ret.mode === "return" && cN < mem.capacity) {
      mem.mode = "return";
      mem.returnReason = "deliver";
      mem.target = null;
      mem.search = null;
    } else if (ret && ret.target && cN < mem.capacity &&
      (!ret.target.h || ret.target.h.status === 0) &&
      !shouldReturn(obs, cN)) {
      mem.target = ret.target;
      mem.targetStart = ret.targetStart || t;
      mem.targetStartDist = ret.targetStartDist ||
        dist(mem.pos.x, mem.pos.y, ret.target.x, ret.target.y);
      if (ret.mode === "search" && ret.search &&
        (!ret.search.hint || ret.search.hint.status === 0)) {
        mem.search = ret.search;
        mem.mode = "search";
      } else if (ret.mode === "toTarget") {
        mem.search = null;
        mem.mode = "toTarget";
      } else {
        mem.mode = "choose";
      }
    } else {
      mem.mode = "choose";
    }
  } else if (cN < mem.lastCarried) {
    mem.lastCarried = cN;
    mem.mode = "charge";
    mem.chargeStart = t;
    mem.target = null;
    mem.search = null;
    mem.currentSample = null;
    mem.holdPos = null;
    mem.drillCmd = false;
    mem.siteReturn = null;
  } else {
    mem.lastCarried = cN;
  }

  if (obs.bumped) {
    mem.bumpCount++;
    let leftC = rayAt(20) + 0.7 * rayAt(40) + 0.4 * rayAt(60);
    let rightC = rayAt(-20) + 0.7 * rayAt(-40) + 0.4 * rayAt(-60);
    let side = leftC >= rightC ? 1 : -1;
    mem.escapeSide = side;
    mem.escapeUntil = Math.max(mem.escapeUntil || 0, t + 1.4);
    mem.avoidActive = true;
    mem.avoidSide = side;
    mem.clearTime = 0;
    mem.drillCmd = false;
  }

  if (t - (mem.lastStuckCheckT || t) > 2.0) {
    let dd = dist(mem.pos.x, mem.pos.y,
      mem.lastStuckPos.x, mem.lastStuckPos.y);
    let desiredMove = Math.abs(mem.lastTargetV || 0);
    if (mem.mode !== "site" && mem.mode !== "charge" &&
      !obs.docked && dd < 0.25 && desiredMove > 0.25) {
      mem.stuck++;
      mem.escapeUntil = Math.max(mem.escapeUntil || 0, t + 1.1);
      let oldSide = mem.avoidSide || 1;
      mem.avoidSide = -oldSide;
      mem.escapeSide = mem.avoidSide;
      mem.avoidActive = true;
      mem.clearTime = 0;
      if (mem.stuck > 4 && mem.mode === "toTarget" && mem.target) {
        if (mem.target.h && mem.target.h.status === 0) {
          mem.target.h.status = 3;
        }
        mem.target = null;
        mem.mode = "choose";
      }
    } else {
      mem.stuck = 0;
    }
    mem.lastStuckCheckT = t;
    mem.lastStuckPos = { x: mem.pos.x, y: mem.pos.y };
  }

  let escapeActive = t < (mem.escapeUntil || 0);

  let needRet = shouldReturn(obs, cN);
  if ((cN >= mem.capacity || needRet) &&
    mem.mode !== "site" && mem.mode !== "charge" && mem.mode !== "return") {
    mem.mode = "return";
    mem.returnReason = cN >= mem.capacity ? "full" : (obs.battery < 0.25 ? "battery" : "time");
    mem.search = null;
    mem.target = null;
    mem.drillCmd = false;
  }

  if (!needRet && cN < mem.capacity && !escapeActive &&
    mem.mode !== "site" && mem.mode !== "charge" && mem.mode !== "return" &&
    obs.site && isFinite(obs.site.distance) && isFinite(obs.site.bearing)) {
    let sDist = Number(obs.site.distance);
    let sBear = Number(obs.site.bearing);
    let sAng = (mem.headEst + sBear) * D2R;
    let sx = mem.pos.x + Math.cos(sAng) * sDist;
    let sy = mem.pos.y + Math.sin(sAng) * sDist;
    let allow = false;

    if (mem.mode === "search") {
      allow = true;
    } else if (mem.mode === "toTarget" && mem.target) {
      let td = dist(sx, sy, mem.target.x, mem.target.y);
      if (mem.target.h && td < 34) allow = true;
      else if (sDist < 1.45) allow = true;
      else {
        let tv = mem.target.val || mem.valMed;
        if (obs.site.value > Math.max(tv * 0.65, (mem.valMed || 1) * 0.80)) allow = true;
        else if (cN < mem.capacity - 1 &&
          obs.site.value > (mem.valMed || 1) * 0.45 && sDist < 4.5) allow = true;
        else if (mem.target.kind === "explore" && sDist < 4.0) allow = true;
      }
    } else if (mem.mode === "choose") {
      allow = sDist < 6.0;
    }

    if (allow) {
      let ret = {
        mode: mem.mode,
        target: mem.target,
        search: mem.search,
        targetStart: mem.targetStart,
        targetStartDist: mem.targetStartDist,
        returnReason: mem.returnReason
      };
      let fromHint = null;
      if (mem.target && mem.target.h &&
        dist(sx, sy, mem.target.x, mem.target.y) < 40) {
        fromHint = mem.target.h;
      } else {
        let bd = 30;
        for (let i = 0; i < mem.hints.length; i++) {
          let h = mem.hints[i];
          if (h.status === 1) continue;
          let hd = dist(sx, sy, h.x, h.y);
          if (hd < bd) {
            bd = hd;
            fromHint = h;
          }
        }
      }
      mem.siteReturn = ret;
      mem.currentSample = {
        x: sx,
        y: sy,
        value: Number(obs.site.value || 0),
        start: t,
        fromHint: fromHint
      };
      mem.mode = "site";
      mem.holdPos = null;
      mem.siteLostT = 0;
      mem.drillCmd = false;
    }
  }

  mem.drillCmd = false;
  setTargets(0, 0);

  if (mem.mode === "choose") {
    chooseNext(obs, mem, t);
  }

  if (mem.mode === "toTarget") {
    if (!mem.target) {
      mem.mode = "choose";
    } else if (mem.target.h && mem.target.h.status !== 0 && mem.target.kind === "hint") {
      mem.mode = "choose";
    } else {
      let d = dist(mem.pos.x, mem.pos.y, mem.target.x, mem.target.y);

      if (mem.target.kind === "explore") {
        if (d < 4.0) {
          if (mem.target.point) mem.target.point.done = true;
          mem.mode = "choose";
        } else {
          let sp = 1.60;
          if (d < 30) sp = 1.15;
          if (d < 10) sp = 0.75;
          navigateTo(mem.target.x, mem.target.y, sp, 3.0);
          if (t - mem.targetStart > 420) {
            if (mem.target.point) mem.target.point.done = true;
            mem.mode = "choose";
          }
        }
      } else {
        if (d < 3.5) {
          let h = mem.target.h;
          if (!h) {
            h = {
              x: mem.target.x,
              y: mem.target.y,
              val: mem.target.val || 1,
              status: 0,
              attempts: 0
            };
            mem.target.h = h;
          }
          startSearchAt(h, obs, t, 0);
        } else {
          let sp = 1.72;
          if (d < 30) sp = 1.20;
          if (d < 10) sp = 0.80;
          if (obs.timeLeft < 80 && cN > 0) sp = 1.9;
          navigateTo(mem.target.x, mem.target.y, sp, 2.8);

          let startDist = mem.targetStartDist || d;
          let limit = Math.max(100, Math.min(600, startDist / 0.40 + 100));
          if (t - mem.targetStart > limit) {
            if (mem.target.h) {
              if (mem.target.h.status === 0) mem.target.h.status = 3;
              else if (mem.target.h.status === 3 && mem.target.h.attempts >= 2) {
                mem.target.h.status = 2;
              }
            }
            mem.mode = "choose";
          }
        }
      }
    }
  }

  if (mem.mode === "search") {
    let s = mem.search;
    if (!s || !s.hint) {
      mem.mode = "choose";
      mem.search = null;
    } else {
      let h = s.hint;
      if (h.status === 1) {
        mem.search = null;
        mem.mode = "choose";
      } else {
        if (!obs.site && obs.science <= 0.000000001) {
          s.noSci += dt;
        } else {
          s.noSci = 0;
        }

        if (s.noSci > 1.2 && s.dist < 12) {
          if (h.status === 0) h.status = 2;
          mem.search = null;
          mem.mode = "choose";
        } else {
          s.dist += Math.min(0.50, Math.max(0, movedOdo));
          let theta = Math.sqrt(2 * Math.max(0, s.dist) / s.a);
          let r = s.a * theta;

          if (r > s.maxR + 0.4 || s.dist > s.maxDist ||
            t - s.start > s.maxDist / 0.22 + 60) {
            if (h.status === 0) h.status = 2;
            mem.search = null;
            mem.mode = "choose";
          } else {
            let tx = s.center.x + r * Math.cos(theta + s.phi);
            let ty = s.center.y + r * Math.sin(theta + s.phi);
            tx = clamp(tx, 2.0, mem.sizeX - 2.0);
            ty = clamp(ty, 2.0, mem.sizeY - 2.0);
            let sp = 1.05;
            if (r < 4) sp = 0.70;
            if (obs.timeLeft < 100) sp = 1.20;
            navigateTo(tx, ty, sp, 0.25);
          }
        }
      }
    }
  }

  if (mem.mode === "site") {
    let cs = mem.currentSample;
    let s = obs.site;

    if (!cs) {
      mem.mode = "choose";
    } else if (s && isFinite(s.distance) && isFinite(s.bearing)) {
      let sd = Number(s.distance);
      let sb = Number(s.bearing);
      let sang = (mem.headEst + sb) * D2R;
      let sx = mem.pos.x + Math.cos(sang) * sd;
      let sy = mem.pos.y + Math.sin(sang) * sd;
      cs.x = sx;
      cs.y = sy;
      cs.value = Number(s.value || cs.value || 0);

      if (sd > 1.25) {
        let sp = 1.10;
        if (sd > 5) sp = 1.05;
        else if (sd > 3) sp = 0.80;
        else if (sd > 2) sp = 0.50;
        else sp = 0.32;

        if ((obs.battery < 0.10 || obs.timeLeft < 8) && sd > 1.8) {
          abortSite(true, cN, t);
          setTargets(0, 0);
        } else if (needRet && sd > 4.0) {
          abortSite(true, cN, t);
          setTargets(0, 0);
        } else {
          mem.holdPos = null;
          controlHeading(mem.headEst + sb, sp);
        }
      } else {
        if (!mem.holdPos) {
          mem.holdPos = { x: mem.pos.x, y: mem.pos.y, t: t };
        }
        let spdNow = Math.abs((wl + wr) / 2);
        let drift = dist(mem.pos.x, mem.pos.y, mem.holdPos.x, mem.holdPos.y);

        if (drift > 0.45 && sd > 1.0 && spdNow < 0.15) {
          let ang = Math.atan2(mem.holdPos.y - mem.pos.y,
            mem.holdPos.x - mem.pos.x) * R2D;
          controlHeading(ang, 0.10);
          mem.drillCmd = (sd < 1.45 && spdNow < 0.14);
        } else {
          setTargets(0, 0);
          mem.drillCmd = (sd < 1.45 && spdNow < 0.14);
        }
      }
    } else {
      if (mem.holdPos && t - mem.holdPos.t < 12 &&
        ((obs.drilling || 0) > 0 || mem.drillCmd)) {
        setTargets(0, 0);
        mem.drillCmd = true;
      } else {
        if (!mem.siteLostT) mem.siteLostT = t;
        if (t - mem.siteLostT > 1.2 || t - cs.start > 30) {
          abortSite(false, cN, t);
        } else {
          setTargets(0, 0);
          mem.drillCmd = false;
        }
      }
    }
  }

  if (mem.mode === "return") {
    let db = dist(mem.pos.x, mem.pos.y, mem.base.x, mem.base.y);
    let bd = db;
    if (obs.beacon && isFinite(obs.beacon.distance)) {
      bd = Math.min(bd, Number(obs.beacon.distance));
    }

    if ((bd < 2.8 || obs.docked) && cN <= 0) {
      setTargets(0, 0);
      mem.drillCmd = false;
      let dc = desiredCharge(obs);
      if (obs.battery < dc && obs.timeLeft > 25) {
        mem.mode = "charge";
        mem.chargeStart = t;
      } else {
        mem.mode = "choose";
      }
    } else if (cN > 0 && (bd < 2.8 || obs.docked)) {
      setTargets(0, 0);
      mem.drillCmd = false;
    } else {
      let sp = 1.75;
      if (bd < 12) sp = Math.min(sp, 1.00);
      if (bd < 6) sp = Math.min(sp, 0.60);
      if (bd < 3) sp = Math.min(sp, 0.30);
      if (obs.timeLeft < 70 && cN > 0) sp = 1.95;
      if (obs.battery < 0.16) sp = Math.min(sp, 1.10);

      if (obs.beacon && isFinite(obs.beacon.distance) && bd < 20) {
        if (bd > 1.0) controlRelative(obs.beacon.bearing, sp);
        else setTargets(0, 0);
      } else {
        navigateTo(mem.base.x, mem.base.y, sp, 1.2);
      }
    }
  }

  if (mem.mode === "charge") {
    let db = dist(mem.pos.x, mem.pos.y, mem.base.x, mem.base.y);
    if (obs.beacon && isFinite(obs.beacon.distance)) {
      db = Math.min(db, Number(obs.beacon.distance));
    }

    if (cN > 0 && db >= 3.0 && !obs.docked) {
      let sp = 1.2;
      if (db < 6) sp = 0.55;
      if (obs.beacon && isFinite(obs.beacon.bearing) && db < 20) {
        controlRelative(obs.beacon.bearing, sp);
      } else {
        navigateTo(mem.base.x, mem.base.y, sp, 1.2);
      }
    } else if (db > 3.0 && !obs.docked && cN === 0) {
      let sp = 1.25;
      if (db < 8) sp = 0.60;
      if (obs.beacon && isFinite(obs.beacon.bearing) && db < 20) {
        controlRelative(obs.beacon.bearing, sp);
      } else {
        navigateTo(mem.base.x, mem.base.y, sp, 1.2);
      }
    } else {
      setTargets(0, 0);
      mem.drillCmd = false;
      let dc = desiredCharge(obs);
      if (obs.timeLeft < 20) {
        setTargets(0, 0);
      } else if (obs.battery >= dc || obs.timeLeft < 35) {
        mem.mode = "choose";
      }
    }
  }

  if (escapeActive) {
    let side = mem.escapeSide || 1;
    let v = -0.55;
    let omega = 1.40 * side;
    let half = 0.3;
    setTargets(v - omega * half, v + omega * half);
    mem.drillCmd = false;
  }

  let uL = wheelPid(mem.targetL, wl, mem.pidL);
  let uR = wheelPid(mem.targetR, wr, mem.pidR);

  mem.lastT = t;

  return {
    left: clamp(uL, -1, 1),
    right: clamp(uR, -1, 1),
    drill: !!mem.drillCmd && !escapeActive
  };
}

function act(obs, mem) {
  const PI = Math.PI;
  const D2R = PI / 180;
  const R2D = 180 / PI;

  function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
  function wrap(a) {
    a = a % 360;
    if (a > 180) a -= 360;
    if (a < -180) a += 360;
    return a;
  }
  function dist(ax, ay, bx, by) {
    let dx = ax - bx, dy = ay - by;
    return Math.sqrt(dx * dx + dy * dy);
  }
  function angleTo(x1, y1, x2, y2) {
    return Math.atan2(y2 - y1, x2 - x1) * R2D;
  }
  function countCarried(o) {
    let c = o.carried;
    if (typeof c === "number") return c;
    if (Array.isArray(c)) return c.length;
    if (c && typeof c.length === "number") return c.length;
    return c ? 1 : 0;
  }

  let t = isFinite(obs.t) ? Number(obs.t) : 0;

  if (!mem.init) {
    mem.init = true;
    let m = obs.mission || {};
    let sx = m.size, sy = m.size;
    if (sx && typeof sx === "object") {
      sy = Number(sx.y != null ? sx.y : (sx.h != null ? sx.h : 400));
      sx = Number(sx.x != null ? sx.x : (sx.w != null ? sx.w : 400));
    }
    sx = Number(sx); sy = Number(sy);
    if (!(sx > 10)) sx = 400;
    if (!(sy > 10)) sy = 400;
    mem.sizeX = sx;
    mem.sizeY = sy;

    let b = m.base || { x: obs.x, y: obs.y };
    mem.base = { x: Number(b.x), y: Number(b.y) };
    if (!isFinite(mem.base.x)) mem.base.x = Number(obs.x);
    if (!isFinite(mem.base.y)) mem.base.y = Number(obs.y);

    mem.capacity = Number(m.capacity || 5);
    if (!(mem.capacity >= 1)) mem.capacity = 5;
    mem.seconds = Number(m.seconds || 1200);

    mem.hints = [];
    let hs = m.hints || [];
    for (let i = 0; i < hs.length; i++) {
      let h = hs[i] || {};
      let hx = Number(h.x), hy = Number(h.y), hv = Number(h.estimate);
      if (!isFinite(hx) || !isFinite(hy)) continue;
      if (!isFinite(hv) || hv < 0) hv = 1;
      mem.hints.push({ x: hx, y: hy, val: hv, status: 0, attempts: 0, id: mem.hints.length });
    }

    let vals = [];
    for (let i = 0; i < mem.hints.length; i++) vals.push(mem.hints[i].val);
    vals.sort(function (a, b) { return a - b; });
    mem.medValue = vals.length ? vals[Math.floor(vals.length / 2)] : 1;
    if (!(mem.medValue > 0)) mem.medValue = 1;
    mem.maxValue = 0;
    for (let i = 0; i < vals.length; i++) if (vals[i] > mem.maxValue) mem.maxValue = vals[i];
    if (!(mem.maxValue > 0)) mem.maxValue = mem.medValue;

    mem.mode = "choose";
    mem.target = null;
    mem.search = null;
    mem.site = null;
    mem.drillSite = null;
    mem.holdPos = null;
    mem.drillStart = null;
    mem.drillOn = false;

    mem.carried = countCarried(obs);
    mem.lastCarried = mem.carried;
    let bat = Number(obs.battery);
    if (!isFinite(bat)) bat = 1;
    mem.battery = bat;
    mem.lastBattery = bat;
    mem.avgSpeed = 0.8;
    mem.sandFactor = 1.0;

    mem.pos = { x: Number(obs.x), y: Number(obs.y) };
    if (!isFinite(mem.pos.x)) mem.pos.x = mem.base.x;
    if (!isFinite(mem.pos.y)) mem.pos.y = mem.base.y;
    mem.lastGPS = { x: mem.pos.x, y: mem.pos.y };
    mem.gpsStill = 0;
    mem.gpsFrozen = false;
    mem.gpsJumpCount = 0;
    mem.gpsHist = [];

    let rh = Number(obs.heading);
    if (!isFinite(rh)) rh = 0;
    mem.head = rh;
    mem.lastRawH = rh;
    mem.biasEst = 0;
    mem.biasInit = true;
    mem.turnSign = 1;

    mem.rayLast = [null, null, null, null, null, null, null, null, null];
    mem.rayStill = [0, 0, 0, 0, 0, 0, 0, 0, 0];
    mem.rayBad = [false, false, false, false, false, false, false, false, false];

    mem.escapeUntil = 0;
    mem.escapeSide = 1;
    mem.bumpCount = 0;
    mem.stuckCount = 0;
    mem.stuckCheckT = t;
    mem.stuckPos = { x: mem.pos.x, y: mem.pos.y };
    mem.explorePts = null;
    mem.cmdL = 0;
    mem.cmdR = 0;
    mem.lastT = t;
  }

  let dt = 0.1;
  if (mem.lastT != null) {
    dt = t - mem.lastT;
    if (!(dt > 0.001 && dt < 1.0)) dt = 0.1;
  }
  mem.lastT = t;

  let rawX = Number(obs.x), rawY = Number(obs.y);
  if (!isFinite(rawX)) rawX = mem.lastGPS.x;
  if (!isFinite(rawY)) rawY = mem.lastGPS.y;
  let rawH = Number(obs.heading);
  if (!isFinite(rawH)) rawH = mem.lastRawH;
  let wl = Number(obs.wheelLeft); if (!isFinite(wl)) wl = 0;
  let wr = Number(obs.wheelRight); if (!isFinite(wr)) wr = 0;
  let speedNow = (wl + wr) / 2;
  let carriedNow = countCarried(obs);
  let battery = Number(obs.battery);
  if (!isFinite(battery)) battery = mem.lastBattery;
  let timeLeft = Number(obs.timeLeft);
  if (!isFinite(timeLeft)) timeLeft = mem.seconds - t;
  if (timeLeft < 0) timeLeft = 0;
  let science = Number(obs.science);
  if (!isFinite(science)) science = 0;
  let site = obs.site || null;
  let beacon = obs.beacon || null;

  // Heading filter / jump rejection
  let wheelYaw = (wr - wl) / 0.6 * dt * R2D;
  let dRaw = wrap(rawH - mem.lastRawH);
  let jump = (Math.abs(dRaw) > 45 && Math.abs(wheelYaw) < 15);
  let expected = wrap(mem.head + wheelYaw);
  if (jump) {
    mem.head = expected;
  } else {
    let diff = wrap(rawH - expected);
    if (Math.abs(diff) > 50) mem.head = wrap(expected + diff * 0.3);
    else mem.head = wrap(expected + diff * 0.8);
  }
  mem.lastRawH = rawH;

  let controlHead = wrap(mem.head - mem.biasEst);

  // Beacon-based compass-bias correction
  if (beacon && isFinite(beacon.distance) && isFinite(beacon.bearing) &&
      beacon.distance > 2.0 && beacon.distance < 25) {
    let btrue = angleTo(mem.pos.x, mem.pos.y, mem.base.x, mem.base.y);
    let bObs = wrap(rawH + Number(beacon.bearing) - btrue);
    if (Math.abs(bObs) < 100) {
      mem.biasEst = wrap(mem.biasEst + wrap(bObs - mem.biasEst) * 0.05);
    }
  }

  // Position estimate
  let oldPos = { x: mem.pos.x, y: mem.pos.y };
  let vx = speedNow * Math.cos(controlHead * D2R);
  let vy = speedNow * Math.sin(controlHead * D2R);
  let predX = mem.pos.x + vx * dt;
  let predY = mem.pos.y + vy * dt;
  let rawDist = dist(rawX, rawY, mem.lastGPS.x, mem.lastGPS.y);
  if (rawDist > 0.02) mem.gpsStill = 0;
  else mem.gpsStill += dt;
  if (mem.gpsStill > 2.0 && Math.abs(speedNow) > 0.12) mem.gpsFrozen = true;
  else if (rawDist > 0.1) mem.gpsFrozen = false;

  if (mem.gpsFrozen) {
    mem.pos.x = predX;
    mem.pos.y = predY;
    if (rawDist > 0.5) {
      mem.pos.x = rawX;
      mem.pos.y = rawY;
      mem.gpsFrozen = false;
      mem.gpsStill = 0;
    }
  } else {
    let pd = dist(rawX, rawY, predX, predY);
    if (pd < 8) {
      mem.pos.x = rawX;
      mem.pos.y = rawY;
      mem.gpsJumpCount = 0;
    } else if (pd < 25) {
      mem.pos.x = predX * 0.6 + rawX * 0.4;
      mem.pos.y = predY * 0.6 + rawY * 0.4;
    } else {
      mem.pos.x = predX;
      mem.pos.y = predY;
      mem.gpsJumpCount = (mem.gpsJumpCount || 0) + 1;
      if (mem.gpsJumpCount > 15) {
        mem.pos.x = rawX;
        mem.pos.y = rawY;
        mem.gpsJumpCount = 0;
      }
    }
  }

  // Beacon position correction
  if (beacon && isFinite(beacon.distance) && isFinite(beacon.bearing) && !mem.gpsFrozen) {
    let absB = (controlHead + Number(beacon.bearing)) * D2R;
    let bx = mem.base.x - Number(beacon.distance) * Math.cos(absB);
    let by = mem.base.y - Number(beacon.distance) * Math.sin(absB);
    let dd = dist(bx, by, mem.pos.x, mem.pos.y);
    if (dd < 15) {
      mem.pos.x = mem.pos.x * 0.95 + bx * 0.05;
      mem.pos.y = mem.pos.y * 0.95 + by * 0.05;
    }
  }
  mem.lastGPS = { x: rawX, y: rawY };

  // GPS history and straight-line heading-bias estimate
  if (!mem.gpsFrozen && (rawDist > 0.02 || mem.gpsHist.length === 0)) {
    mem.gpsHist.push({ x: rawX, y: rawY, t: t });
    while (mem.gpsHist.length > 25) mem.gpsHist.shift();
  } else if (mem.gpsFrozen) {
    if (mem.gpsHist.length > 0 && t - mem.gpsHist[mem.gpsHist.length - 1].t > 1.0) mem.gpsHist = [];
  }
  if (mem.gpsHist.length >= 12 && Math.abs(speedNow) > 0.4 && Math.abs(wl - wr) < 0.35) {
    let a = mem.gpsHist[0];
    let b = mem.gpsHist[mem.gpsHist.length - 1];
    let gd = dist(a.x, a.y, b.x, b.y);
    let gt = b.t - a.t;
    if (gd > 1.0 && gt > 0.8) {
      let course = Math.atan2(b.y - a.y, b.x - a.x) * R2D;
      let desiredBias = wrap(mem.head - course);
      if (Math.abs(desiredBias - mem.biasEst) < 80) {
        mem.biasEst = wrap(mem.biasEst + wrap(desiredBias - mem.biasEst) * 0.03);
      }
    }
  }

  // Rays
  let rawRays = [15, 15, 15, 15, 15, 15, 15, 15, 15];
  if (obs.rays && obs.rays.length) {
    for (let i = 0; i < 9; i++) {
      let v = Number(obs.rays[i]);
      if (!isFinite(v) || v < 0) v = 15;
      if (v > 15) v = 15;
      rawRays[i] = v;
    }
  }
  let rays = [15, 15, 15, 15, 15, 15, 15, 15, 15];
  for (let i = 0; i < 9; i++) {
    let v = rawRays[i];
    if (mem.rayLast[i] == null) mem.rayLast[i] = v;
    let d = Math.abs(v - mem.rayLast[i]);
    if (d < 0.02) mem.rayStill[i] += dt;
    else {
      mem.rayStill[i] = 0;
      if (v > 1.5) mem.rayBad[i] = false;
    }
    if (mem.rayStill[i] > 5.0 && Math.abs(speedNow) > 0.15 && v > 2.0) mem.rayBad[i] = true;
    mem.rayLast[i] = v;
    rays[i] = (mem.rayBad[i] && v > 2.0) ? 15 : v;
  }

  // Helpers
  function findHintNear(m, x, y) {
    let best = null, bd = 35;
    for (let i = 0; i < m.hints.length; i++) {
      let h = m.hints[i];
      if (h.status === 1) continue;
      let d = dist(x, y, h.x, h.y);
      if (d < bd) { bd = d; best = h; }
    }
    return best;
  }

  function markHintSampled(m, x, y) {
    let h = findHintNear(m, x, y);
    if (h) h.status = 1;
  }

  function chooseNextTarget(m, now, tl, bat, carry) {
    let curBase = dist(m.pos.x, m.pos.y, m.base.x, m.base.y);
    let best = null, bestScore = -1e100;
    let med = m.medValue || 1;
    for (let i = 0; i < m.hints.length; i++) {
      let h = m.hints[i];
      if (h.status !== 0) continue;
      let d = dist(m.pos.x, m.pos.y, h.x, h.y);
      let dh = dist(h.x, h.y, m.base.x, m.base.y);
      let timeNeed = (d + dh) / 0.9 + 35;
      if (tl < timeNeed + 20) continue;
      let batNeed = 0.04 + 0.0012 * (d + dh);
      if (bat < batNeed + 0.06) continue;

      let searchCost = 18 + Math.min(35, 20 * Math.sqrt(Math.max(0.1, h.val / med)));
      let cost;
      if (carry === 0) {
        cost = d + dh * 0.9 + searchCost;
      } else {
        cost = d + dh - curBase + searchCost;
        if (cost < 8) cost = 8;
      }
      let score = h.val / Math.pow(cost + 30, 1.15);
      if (tl < 250) score *= Math.pow(120 / (dh + 60), 0.2);
      if (d < 25) score *= 1.15;
      if (h.attempts > 0) score *= 0.85;

      if (score > bestScore) {
        bestScore = score;
        let R = 15 + clamp(5 * Math.sqrt(Math.max(0.05, h.val / med)) - 3, -5, 8);
        if (h.val >= m.maxValue * 0.8) R = Math.max(R, 20);
        if (tl < 250) R = Math.min(R, 16);
        if (bat < 0.4) R = Math.min(R, 15);
        R = clamp(R, 10, 24);
        best = { x: h.x, y: h.y, val: h.val, hint: h, searchR: R, startT: now };
      }
    }
    if (best && best.hint) best.hint.attempts++;
    return best;
  }

  function initSearch(tg, m, now, sci) {
    let cx = tg.x, cy = tg.y;
    let R = tg.searchR || 16;
    let spacing = 9.0;
    let pts = [];
    pts.push({ x: clamp(cx, 2, m.sizeX - 2), y: clamp(cy, 2, m.sizeY - 2) });
    for (let gx = -R; gx <= R; gx += spacing) {
      for (let gy = -R; gy <= R; gy += spacing) {
        if (gx * gx + gy * gy <= R * R + 0.1) {
          if (Math.abs(gx) < 0.1 && Math.abs(gy) < 0.1) continue;
          pts.push({
            x: clamp(cx + gx, 2, m.sizeX - 2),
            y: clamp(cy + gy, 2, m.sizeY - 2)
          });
        }
      }
    }
    let visited = [];
    for (let i = 0; i < pts.length; i++) visited.push(false);
    return {
      center: { x: cx, y: cy },
      points: pts,
      visited: visited,
      visitedCount: 0,
      startT: now,
      maxTime: 25 + pts.length * 8.0,
      hint: tg.hint || null,
      lastSci: sci,
      sciMax: sci
    };
  }

  function chooseExplorePoint(m) {
    if (!m.explorePts) {
      m.explorePts = [];
      let step = Math.max(45, Math.min(m.sizeX, m.sizeY) / 6);
      for (let x = step * 0.5; x < m.sizeX - 10; x += step) {
        for (let y = step * 0.5; y < m.sizeY - 10; y += step) {
          m.explorePts.push({ x: x, y: y, done: false });
        }
      }
      if (m.explorePts.length === 0) {
        m.explorePts.push({ x: m.sizeX * 0.5, y: m.sizeY * 0.5, done: false });
      }
    }
    for (let i = 0; i < m.explorePts.length; i++) {
      let p = m.explorePts[i];
      if (!p.done && dist(m.pos.x, m.pos.y, p.x, p.y) < 12) p.done = true;
    }
    let best = null, bd = 1e100;
    for (let i = 0; i < m.explorePts.length; i++) {
      let p = m.explorePts[i];
      if (p.done) continue;
      let d = dist(m.pos.x, m.pos.y, p.x, p.y);
      if (d < bd) { bd = d; best = p; }
    }
    return best;
  }

  function driveHeadingError(err, speed) {
    let v = speed;
    let absErr = Math.abs(err);
    if (absErr > 90) v = 0;
    else if (absErr > 60) v *= 0.25;
    else if (absErr > 35) v *= 0.55;
    else if (absErr > 15) v *= 0.8;

    if (absErr > 90) {
      let tC = clamp(err * 0.018, -0.6, 0.6);
      return { left: -tC, right: tC };
    }
    let vCmd = v / 3.0;
    let turnCmd = clamp(err * 0.012, -0.55, 0.55);
    let l = vCmd - turnCmd;
    let r = vCmd + turnCmd;
    if (l > 0 && l < 0.04) l = 0.04;
    if (l < 0 && l > -0.04) l = -0.04;
    if (r > 0 && r < 0.04) r = 0.04;
    if (r < 0 && r > -0.04) r = -0.04;
    return { left: l, right: r };
  }

  function driveToPoint(tx, ty, speed, stopDist, heading) {
    tx = clamp(tx, 3, mem.sizeX - 3);
    ty = clamp(ty, 3, mem.sizeY - 3);
    let dx = tx - mem.pos.x, dy = ty - mem.pos.y;
    let d = Math.sqrt(dx * dx + dy * dy);
    if (d <= stopDist) return { left: 0, right: 0, d: d };
    let ang = Math.atan2(dy, dx) * R2D;
    let err = wrap(ang - heading);
    let res = driveHeadingError(err, speed);
    res.d = d;
    return res;
  }

  function driveRelative(bearing, speed, distance, stopDist) {
    if (distance <= stopDist) return { left: 0, right: 0 };
    let err = wrap(bearing);
    return driveHeadingError(err, speed);
  }

  // Carried changes
  let prevCarried = mem.lastCarried;
  mem.lastCarried = carriedNow;
  mem.battery = battery;
  if (carriedNow > prevCarried) {
    if (mem.drillSite || mem.site) {
      let s0 = mem.drillSite || mem.site;
      markHintSampled(mem, s0.x, s0.y);
    }
    mem.mode = "choose";
    mem.site = null;
    mem.drillSite = null;
    mem.drillOn = false;
    mem.holdPos = null;
  } else if (carriedNow < prevCarried) {
    mem.mode = "choose";
    mem.site = null;
    mem.drillSite = null;
    mem.drillOn = false;
    mem.holdPos = null;
  }

  let distBase = dist(mem.pos.x, mem.pos.y, mem.base.x, mem.base.y);
  if (beacon && isFinite(beacon.distance)) distBase = Number(beacon.distance);

  // Return need
  let returnNeeded = false, returnReason = "";
  if (carriedNow >= mem.capacity) {
    returnNeeded = true;
    returnReason = "full";
  }
  let toBaseTime = distBase / Math.max(0.6, mem.avgSpeed) + 12 + carriedNow * 2;
  if (carriedNow > 0 && timeLeft < toBaseTime) {
    returnNeeded = true;
    returnReason = "time";
  }
  if (carriedNow > 0 && battery < 0.18) {
    returnNeeded = true;
    returnReason = "battery";
  }
  if (battery < 0.08) {
    returnNeeded = true;
    returnReason = "battery";
  }
  if (carriedNow > 0 && distBase < 3.0 && t > 5) returnNeeded = true;

  if (returnNeeded && mem.mode !== "return") {
    mem.mode = "return";
    mem.site = null;
    mem.drillSite = null;
    mem.drillOn = false;
    mem.search = null;
    mem.target = null;
  }

  // Choose new task
  if (!returnNeeded && (mem.mode === "choose" || mem.mode === "idle")) {
    if (distBase < 3.0 && carriedNow === 0 && battery < 0.85 && timeLeft > 40) {
      mem.mode = "charge";
    } else if (site && carriedNow < mem.capacity) {
      let sd = Number(site.distance), sb = Number(site.bearing), sv = Number(site.value);
      if (isFinite(sd) && isFinite(sb) && sd < 8.0) {
        let absB = (controlHead + sb) * D2R;
        let sx = mem.pos.x + Math.cos(absB) * sd;
        let sy = mem.pos.y + Math.sin(absB) * sd;
        mem.mode = "toSite";
        mem.site = { x: sx, y: sy, val: sv, detectT: t, bearing: sb, distance: sd, hint: findHintNear(mem, sx, sy) };
      }
    }

    if (mem.mode === "choose") {
      let chosen = chooseNextTarget(mem, t, timeLeft, battery, carriedNow);
      if (chosen) {
        mem.mode = "toHint";
        mem.target = chosen;
      } else {
        let p = chooseExplorePoint(mem);
        if (p) {
          mem.mode = "explore";
          mem.explorePoint = p;
        } else if (distBase > 3.0) {
          mem.mode = "return";
        } else {
          mem.mode = "charge";
        }
      }
    }
  }

  let cmdL = 0, cmdR = 0, drillCmd = false;
  let mode = mem.mode;

  if (mode === "return") {
    let sp = 1.2;
    if (distBase < 12) sp = 0.8;
    if (distBase < 4) sp = 0.45;
    if (battery < 0.25) sp = Math.min(sp, 0.7);
    if (beacon && isFinite(beacon.distance) && isFinite(beacon.bearing) && beacon.distance < 20) {
      let res = driveRelative(Number(beacon.bearing), sp, Number(beacon.distance), 1.2);
      cmdL = res.left; cmdR = res.right;
    } else {
      let res = driveToPoint(mem.base.x, mem.base.y, sp, 1.2, controlHead);
      cmdL = res.left; cmdR = res.right;
    }
    if (distBase < 2.8) {
      cmdL = 0; cmdR = 0;
      if (carriedNow === 0) {
        if (battery < 0.85 && timeLeft > 30) mem.mode = "charge";
        else mem.mode = "choose";
      }
    }
  } else if (mode === "toSite") {
    let s = mem.site;
    if (!s) {
      mem.mode = "choose";
    } else {
      let sd = site ? Number(site.distance) : NaN;
      let sb = site ? Number(site.bearing) : NaN;
      if (isFinite(sd) && isFinite(sb) && sd < 8.5) {
        let absB = (controlHead + sb) * D2R;
        let nx = mem.pos.x + Math.cos(absB) * sd;
        let ny = mem.pos.y + Math.sin(absB) * sd;
        if (dist(nx, ny, s.x, s.y) < 12 || !s.seen) {
          s.x = nx; s.y = ny;
          s.val = Number(site.value || s.val || 0);
          s.seen = true;
        }
        s.distance = sd;
        s.bearing = sb;
      }
      let d = dist(mem.pos.x, mem.pos.y, s.x, s.y);
      if (isFinite(s.distance)) d = Math.min(d, s.distance);
      if (d > 1.25) {
        let sp = 0.9;
        if (d > 8) sp = 1.1;
        if (d < 3) sp = 0.55;
        if (d < 1.8) sp = 0.3;
        if (isFinite(sd) && isFinite(sb) && sd < 8.0) {
          let res = driveRelative(sb, sp, sd, 1.1);
          cmdL = res.left; cmdR = res.right;
        } else {
          let res = driveToPoint(s.x, s.y, sp, 1.1, controlHead);
          cmdL = res.left; cmdR = res.right;
        }
      } else {
        mem.mode = "drill";
        mem.drillSite = s;
        mem.holdPos = { x: mem.pos.x, y: mem.pos.y };
        mem.drillStart = t;
        mem.drillOn = false;
        cmdL = 0; cmdR = 0; drillCmd = false;
      }
      if (!site && t - (s.detectT || t) > 5) {
        mem.mode = "choose";
        mem.site = null;
      }
    }
  } else if (mode === "drill") {
    let s = mem.drillSite;
    if (!s) {
      mem.mode = "choose";
    } else {
      let d = dist(mem.pos.x, mem.pos.y, s.x, s.y);
      let sd = site ? Number(site.distance) : NaN;
      let sb = site ? Number(site.bearing) : NaN;
      if (isFinite(sd) && isFinite(sb)) {
        d = Math.min(d, sd);
        if (sd < 8.5) {
          let absB = (controlHead + sb) * D2R;
          let nx = mem.pos.x + Math.cos(absB) * sd;
          let ny = mem.pos.y + Math.sin(absB) * sd;
          if (dist(nx, ny, s.x, s.y) < 10) { s.x = nx; s.y = ny; }
        }
      }
      let hold = mem.holdPos || { x: mem.pos.x, y: mem.pos.y };
      let hd = dist(mem.pos.x, mem.pos.y, hold.x, hold.y);

      if (d > 1.48 && (!isFinite(sd) || sd > 1.48)) {
        mem.mode = "toSite";
      } else {
        let spdNow = Math.abs((wl + wr) / 2);
        let brakeL = clamp(-wl * 1.8, -0.35, 0.35);
        let brakeR = clamp(-wr * 1.8, -0.35, 0.35);
        if (hd > 0.15 && spdNow < 0.15) {
          let angHold = Math.atan2(hold.y - mem.pos.y, hold.x - mem.pos.x) * R2D;
          let errHold = wrap(angHold - controlHead);
          let fwd = Math.min(0.08, hd * 0.4);
          let turn = clamp(errHold * 0.01, -0.08, 0.08);
          brakeL += fwd - turn;
          brakeR += fwd + turn;
        }
        cmdL = clamp(brakeL, -0.4, 0.4);
        cmdR = clamp(brakeR, -0.4, 0.4);
        if (d < 1.45 && spdNow < 0.15) {
          drillCmd = true;
          if (!mem.drillOn) {
            mem.drillOn = true;
            mem.drillStart = t;
          }
        } else {
          drillCmd = false;
          mem.drillOn = false;
        }
      }
      if (mem.drillOn && t - mem.drillStart > 18) {
        if (d > 1.4) mem.mode = "toSite";
        else {
          mem.mode = "choose";
          mem.site = null;
          mem.drillSite = null;
        }
      }
    }
  } else if (mode === "toHint") {
    let tg = mem.target;
    if (!tg) {
      mem.mode = "choose";
    } else if (site && Number(site.distance) < 8 && carriedNow < mem.capacity) {
      let sd = Number(site.distance), sb = Number(site.bearing);
      let absB = (controlHead + sb) * D2R;
      let sx = mem.pos.x + Math.cos(absB) * sd;
      let sy = mem.pos.y + Math.sin(absB) * sd;
      mem.mode = "toSite";
      mem.site = { x: sx, y: sy, val: site.value, detectT: t, bearing: sb, distance: sd, hint: findHintNear(mem, sx, sy) };
    } else {
      let d = dist(mem.pos.x, mem.pos.y, tg.x, tg.y);
      if (d < Math.max(6, (tg.searchR || 16) * 0.8)) {
        mem.mode = "search";
        mem.search = initSearch(tg, mem, t, science);
      } else {
        let sp = 1.2;
        if (d < 20) sp = 1.0;
        if (d < 8) sp = 0.7;
        if (timeLeft < 100) sp = 1.4;
        let res = driveToPoint(tg.x, tg.y, sp, 0.5, controlHead);
        cmdL = res.left; cmdR = res.right;
        if (tg.startT && t - tg.startT > 400) {
          if (tg.hint) tg.hint.status = 2;
          mem.mode = "choose";
        }
      }
    }
  } else if (mode === "search") {
    let s = mem.search;
    if (!s) {
      mem.mode = "choose";
    } else {
      if (science > s.sciMax) s.sciMax = science;
      if (site && carriedNow < mem.capacity && Number(site.distance) < 8) {
        let sd = Number(site.distance), sb = Number(site.bearing);
        let absB = (controlHead + sb) * D2R;
        let sx = mem.pos.x + Math.cos(absB) * sd;
        let sy = mem.pos.y + Math.sin(absB) * sd;
        mem.mode = "toSite";
        mem.site = { x: sx, y: sy, val: site.value, detectT: t, bearing: sb, distance: sd, hint: findHintNear(mem, sx, sy) };
      } else if (t - s.startT > s.maxTime || s.visitedCount >= s.points.length) {
        if (s.hint && s.hint.status === 0) s.hint.status = 2;
        mem.mode = "choose";
        mem.search = null;
      } else {
        let best = -1, bd = 1e9;
        for (let i = 0; i < s.points.length; i++) {
          if (!s.visited[i]) {
            let dd = dist(mem.pos.x, mem.pos.y, s.points[i].x, s.points[i].y);
            if (dd < bd) { bd = dd; best = i; }
          }
        }
        if (best < 0) {
          if (s.hint && s.hint.status === 0) s.hint.status = 2;
          mem.mode = "choose";
          mem.search = null;
        } else {
          let p = s.points[best];
          let dd = dist(mem.pos.x, mem.pos.y, p.x, p.y);
          if (dd < 1.8) {
            s.visited[best] = true;
            s.visitedCount++;
          } else {
            let sp = 1.05;
            if (dd < 5) sp = 0.65;
            let res = driveToPoint(p.x, p.y, sp, 0.2, controlHead);
            cmdL = res.left; cmdR = res.right;
          }
        }
      }
    }
  } else if (mode === "explore") {
    let p = mem.explorePoint;
    if (!p) {
      mem.mode = "choose";
    } else {
      let d = dist(mem.pos.x, mem.pos.y, p.x, p.y);
      if (d < 4) {
        p.done = true;
        mem.mode = "choose";
      } else {
        let sp = 1.2;
        if (d < 10) sp = 0.9;
        let res = driveToPoint(p.x, p.y, sp, 1.0, controlHead);
        cmdL = res.left; cmdR = res.right;
      }
      if (site && carriedNow < mem.capacity && Number(site.distance) < 8) {
        let sd = Number(site.distance), sb = Number(site.bearing);
        let absB = (controlHead + sb) * D2R;
        let sx = mem.pos.x + Math.cos(absB) * sd;
        let sy = mem.pos.y + Math.sin(absB) * sd;
        mem.mode = "toSite";
        mem.site = { x: sx, y: sy, val: site.value, detectT: t, bearing: sb, distance: sd, hint: findHintNear(mem, sx, sy) };
      }
    }
  } else if (mode === "charge") {
    cmdL = 0; cmdR = 0; drillCmd = false;
    if (battery > 0.95 || timeLeft < 25 || carriedNow > 0) {
      mem.mode = "choose";
    } else if (distBase > 3.0) {
      let sp = 0.9;
      if (beacon && isFinite(beacon.distance) && isFinite(beacon.bearing) && beacon.distance < 20) {
        let res = driveRelative(Number(beacon.bearing), sp, Number(beacon.distance), 1.0);
        cmdL = res.left; cmdR = res.right;
      } else {
        let res = driveToPoint(mem.base.x, mem.base.y, sp, 1.0, controlHead);
        cmdL = res.left; cmdR = res.right;
      }
    }
  }

  // Boundary guard
  if (mem.mode !== "drill") {
    if (mem.pos.x < 3 || mem.pos.x > mem.sizeX - 3 || mem.pos.y < 3 || mem.pos.y > mem.sizeY - 3) {
      let cx = mem.sizeX / 2, cy = mem.sizeY / 2;
      let res = driveToPoint(cx, cy, 0.7, 0, controlHead);
      cmdL = res.left; cmdR = res.right;
    }
  }

  let minCenter = Math.min(rays[3], rays[4], rays[5]);
  let minFront = Math.min(rays[2], rays[3], rays[4], rays[5], rays[6]);
  let spdNowAbs = Math.abs((wl + wr) / 2);

  // Forward-speed cap based on closeness
  let avgCmd = (cmdL + cmdR) / 2;
  let diffCmd = (cmdR - cmdL) / 2;
  let maxAvg = 1.0;
  if (minFront < 4.0) maxAvg = 0.50;
  if (minFront < 3.0) maxAvg = 0.34;
  if (minFront < 2.0) maxAvg = 0.15;
  if (minFront < 1.2) maxAvg = 0.0;
  if (avgCmd > maxAvg) {
    avgCmd = maxAvg;
    cmdL = avgCmd - diffCmd;
    cmdR = avgCmd + diffCmd;
  }

  // Steering away from side/front obstacles
  if (mem.mode !== "drill" && mem.mode !== "charge") {
    let leftScore = 0, rightScore = 0;
    for (let i = 0; i < 9; i++) {
      let a = (i - 4) * 20;
      let d = rays[i];
      if (d < 4.0) {
        let w = (4.0 - d) / 4.0;
        if (a > 0) leftScore += w * (a / 80);
        else if (a < 0) rightScore += w * ((-a) / 80);
      }
    }
    let turnAdj = clamp((leftScore - rightScore) * 0.6, -0.4, 0.4);
    cmdL += turnAdj;
    cmdR -= turnAdj;
  }

  // Emergency reverse/steer
  if (mem.mode !== "drill" || spdNowAbs > 0.3) {
    if (minCenter < 1.2 || (minFront < 0.8 && spdNowAbs > 0.4)) {
      cmdL = -0.35; cmdR = -0.35;
      drillCmd = false;
      let lc = rays[7] + rays[8] + rays[6];
      let rc = rays[0] + rays[1] + rays[2];
      if (lc > rc) { cmdL = -0.2; cmdR = 0.3; }
      else { cmdL = 0.3; cmdR = -0.2; }
      mem.escapeUntil = Math.max(mem.escapeUntil || 0, t + 0.6);
    }
  }

  // Stuck detection / escape
  if (mem.mode === "toHint" || mem.mode === "toSite" || mem.mode === "search" ||
      mem.mode === "explore" || mem.mode === "return") {
    if (t - (mem.stuckCheckT || t) > 2.0) {
      let moved = dist(mem.pos.x, mem.pos.y, mem.stuckPos.x, mem.stuckPos.y);
      let want = Math.abs(cmdL) + Math.abs(cmdR);
      if (moved < 0.2 && want > 0.2 && spdNowAbs < 0.12) {
        mem.stuckCount = (mem.stuckCount || 0) + 1;
        mem.escapeUntil = t + 1.2;
        mem.escapeSide = -(mem.escapeSide || 1);
        if (mem.stuckCount > 3) {
          if (mem.target && mem.target.hint) mem.target.hint.status = 3;
          if (mem.search && mem.search.hint && mem.search.hint.status === 0) mem.search.hint.status = 3;
          mem.mode = "choose";
          mem.site = null;
          mem.target = null;
          mem.search = null;
          mem.stuckCount = 0;
        }
      } else {
        mem.stuckCount = 0;
      }
      mem.stuckCheckT = t;
      mem.stuckPos = { x: mem.pos.x, y: mem.pos.y };
    }
    if (t < (mem.escapeUntil || 0)) {
      let side = mem.escapeSide || 1;
      cmdL = -0.30 - 0.20 * side;
      cmdR = -0.30 + 0.20 * side;
      drillCmd = false;
    }
  }

  // Bump reaction
  if (obs.bumped) {
    mem.escapeUntil = Math.max(mem.escapeUntil || 0, t + 0.8);
    mem.escapeSide = -(mem.escapeSide || 1);
    mem.bumpCount = (mem.bumpCount || 0) + 1;
    drillCmd = false;
  }

  // Command smoothing
  let smooth = (mem.mode === "drill") ? 0.7 : 0.55;
  if (t > (mem.escapeUntil || 0)) {
    cmdL = mem.cmdL * (1 - smooth) + cmdL * smooth;
    cmdR = mem.cmdR * (1 - smooth) + cmdR * smooth;
  } else {
    cmdL = mem.cmdL * 0.2 + cmdL * 0.8;
    cmdR = mem.cmdR * 0.2 + cmdR * 0.8;
  }
  mem.cmdL = cmdL;
  mem.cmdR = cmdR;

  cmdL = clamp(cmdL, -1, 1);
  cmdR = clamp(cmdR, -1, 1);
  if (!isFinite(cmdL)) cmdL = 0;
  if (!isFinite(cmdR)) cmdR = 0;

  mem.carried = carriedNow;
  mem.lastBattery = battery;
  mem.avgSpeed = mem.avgSpeed * 0.99 + Math.abs(speedNow) * 0.01;
  if (!(mem.avgSpeed > 0.3)) mem.avgSpeed = 0.3;

  return { left: cmdL, right: cmdR, drill: !!drillCmd };
}

function act(obs, mem) {
  const PI = Math.PI;
  const D2R = PI / 180;
  const R2D = 180 / PI;

  function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
  function wrap(a) {
    a = a % 360;
    if (a > 180) a -= 360;
    if (a < -180) a += 360;
    return a;
  }
  function dist(ax, ay, bx, by) {
    const dx = ax - bx, dy = ay - by;
    return Math.sqrt(dx * dx + dy * dy);
  }
  function angleTo(x1, y1, x2, y2) {
    return Math.atan2(y2 - y1, x2 - x1) * R2D;
  }
  function countCarried(o) {
    const c = o.carried;
    if (typeof c === "number") return c;
    if (Array.isArray(c)) return c.length;
    if (c && typeof c.length === "number") return c.length;
    return c ? 1 : 0;
  }

  let t = Number(obs.t);
  if (!isFinite(t)) t = 0;

  if (!mem.init) {
    mem.init = true;

    const m = obs.mission || {};
    let sx = m.size, sy = m.size;
    if (sx && typeof sx === "object") {
      sy = Number(sx.y != null ? sx.y : (sx.h != null ? sx.h : 400));
      sx = Number(sx.x != null ? sx.x : (sx.w != null ? sx.w : 400));
    }
    sx = Number(sx); sy = Number(sy);
    if (!(sx > 10)) sx = 400;
    if (!(sy > 10)) sy = 400;
    mem.sizeX = sx;
    mem.sizeY = sy;

    const mb = m.base || {};
    mem.base = {
      x: isFinite(Number(mb.x)) ? Number(mb.x) : Number(obs.x),
      y: isFinite(Number(mb.y)) ? Number(mb.y) : Number(obs.y)
    };
    if (!isFinite(mem.base.x)) mem.base.x = Number(obs.x) || 0;
    if (!isFinite(mem.base.y)) mem.base.y = Number(obs.y) || 0;

    mem.capacity = Number(m.capacity || 5);
    if (!(mem.capacity >= 1)) mem.capacity = 5;
    mem.seconds = Number(m.seconds || 1200);

    mem.hints = [];
    const hs = m.hints || [];
    for (let i = 0; i < hs.length; i++) {
      const h = hs[i] || {};
      const hx = Number(h.x), hy = Number(h.y);
      let hv = Number(h.estimate);
      if (!isFinite(hx) || !isFinite(hy)) continue;
      if (!isFinite(hv) || hv < 0) hv = 1;
      mem.hints.push({
        id: mem.hints.length,
        x: hx,
        y: hy,
        val: hv,
        status: 0,
        attempts: 0
      });
    }

    const vals = [];
    for (let i = 0; i < mem.hints.length; i++) vals.push(mem.hints[i].val);
    vals.sort(function(a, b) { return a - b; });
    mem.medValue = vals.length ? vals[Math.floor(vals.length / 2)] : 1;
    if (!(mem.medValue > 0)) mem.medValue = 1;
    mem.maxValue = 0;
    for (let i = 0; i < vals.length; i++) if (vals[i] > mem.maxValue) mem.maxValue = vals[i];
    if (!(mem.maxValue > 0)) mem.maxValue = mem.medValue;

    mem.pos = { x: Number(obs.x), y: Number(obs.y) };
    if (!isFinite(mem.pos.x)) mem.pos.x = mem.base.x;
    if (!isFinite(mem.pos.y)) mem.pos.y = mem.base.y;

    let rh = Number(obs.heading);
    if (!isFinite(rh)) rh = 0;
    mem.head = rh;
    mem.bias = 0;
    mem.lastRawH = rh;

    mem.lastGPS = { x: mem.pos.x, y: mem.pos.y };
    mem.gpsFrozen = false;
    mem.freezeT = 0;
    mem.gpsJumpT = 0;
    mem.gpsHist = [];

    mem.rayLast = [null, null, null, null, null, null, null, null, null];
    mem.rayStill = [0, 0, 0, 0, 0, 0, 0, 0, 0];
    mem.rayBad = [false, false, false, false, false, false, false, false, false];
    mem.visibility = 15;

    mem.mode = "choose";
    mem.targetHint = null;
    mem.search = null;
    mem.site = null;
    mem.hold = null;
    mem.drillOn = false;
    mem.drillStart = 0;
    mem.arriveBaseT = 0;
    mem.chargeStart = 0;
    mem.chargeStartBat = 0;
    mem.chargeTarget = 0.8;

    mem.carried = countCarried(obs);
    mem.lastCarried = mem.carried;
    mem.deliveredCount = 0;
    mem.totalSampleCount = 0;

    mem.prevBumped = false;
    mem.lastBumpT = -100;
    mem.bumpTimes = [];
    mem.severeBumpT = -100;

    mem.escapeUntil = 0;
    mem.escapeCooldown = 0;
    mem.escapeSide = 1;

    mem.avoid = { active: false, side: 1, start: 0, clearT: 0 };

    mem.stuckCheckT = t;
    mem.stuckPos = { x: mem.pos.x, y: mem.pos.y };
    mem.stuckHead = mem.head;
    mem.stuckCount = 0;

    mem.cmdL = 0;
    mem.cmdR = 0;
    mem.pidL = { i: 0, lastTarget: 0, gain: 0.42, lastGainT: 0 };
    mem.pidR = { i: 0, lastTarget: 0, gain: 0.42, lastGainT: 0 };

    mem.lastWantSpeed = 0;
    mem.lastT = t;

    mem.costPerM = 0.0010;
    mem.energyDrain = 0;
    mem.energyDist = 0;
    mem.slip = 1.0;
    mem.sandFlag = false;

    mem.explorePts = null;
    mem.explorePoint = null;

    mem.lastDelivered = Number(obs.delivered);
    if (!isFinite(mem.lastDelivered)) mem.lastDelivered = 0;
    mem.initialBattery = Number(obs.battery);
    if (!isFinite(mem.initialBattery)) mem.initialBattery = 1;

    if (mem.carried > 0) mem.mode = "return";
  }

  let dt = 0.1;
  if (mem.lastT != null) {
    dt = t - mem.lastT;
    if (!(dt > 0.001 && dt < 1.0)) dt = 0.1;
  }
  mem.lastT = t;

  let wl = Number(obs.wheelLeft);
  let wr = Number(obs.wheelRight);
  if (!isFinite(wl)) wl = 0;
  if (!isFinite(wr)) wr = 0;
  const vLin = (wl + wr) / 2;

  let battery = Number(obs.battery);
  if (!isFinite(battery)) battery = mem.initialBattery;
  mem.battery = battery;

  let timeLeft = Number(obs.timeLeft);
  if (!isFinite(timeLeft)) timeLeft = mem.seconds - t;
  if (timeLeft < 0) timeLeft = 0;

  let science = Number(obs.science);
  if (!isFinite(science)) science = 0;

  const siteObs = obs.site || null;
  const beacon = obs.beacon || null;

  let cN = countCarried(obs);
  const oldPos = { x: mem.pos.x, y: mem.pos.y };

  // Heading estimation: observed heading is treated as true plus slowly learned bias.
  let rawH = Number(obs.heading);
  if (!isFinite(rawH)) rawH = mem.lastRawH;
  const wheelYaw = ((wr - wl) / 0.6) * dt * R2D;
  const predHead = wrap(mem.head + wheelYaw);
  const dRawH = wrap(rawH - mem.lastRawH);
  const jumpH = Math.abs(dRawH) > 55 && Math.abs(wheelYaw) < 18;

  if (jumpH) {
    mem.head = predHead;
  } else {
    const diff = wrap(rawH - mem.bias - predHead);
    if (Math.abs(diff) > 65) {
      if (Math.abs(vLin) < 0.05) mem.head = wrap(rawH - mem.bias);
      else mem.head = predHead;
    } else {
      const alpha = Math.abs(vLin) < 0.06 ? 0.35 : 0.72;
      mem.head = wrap(predHead + diff * alpha);
    }
  }
  mem.lastRawH = rawH;

  let controlHead = wrap(mem.head);

  // Position estimation, with frozen-GPS dead reckoning.
  let rawX = Number(obs.x), rawY = Number(obs.y);
  if (!isFinite(rawX)) rawX = mem.lastGPS.x;
  if (!isFinite(rawY)) rawY = mem.lastGPS.y;

  const predX = mem.pos.x + vLin * Math.cos(controlHead * D2R) * dt;
  const predY = mem.pos.y + vLin * Math.sin(controlHead * D2R) * dt;

  const rawMoved = dist(rawX, rawY, mem.lastGPS.x, mem.lastGPS.y);
  if (rawMoved > 0.015) mem.freezeT = 0;
  else mem.freezeT += dt;

  if (mem.freezeT > 2.0 && Math.abs(vLin) > 0.10) mem.gpsFrozen = true;

  if (mem.gpsFrozen) {
    mem.pos.x = predX;
    mem.pos.y = predY;
    if (rawMoved > 0.10) {
      mem.gpsFrozen = false;
      mem.freezeT = 0;
      mem.pos.x = rawX;
      mem.pos.y = rawY;
    }
  } else {
    const dp = dist(rawX, rawY, predX, predY);
    if (dp < 7) {
      mem.pos.x = rawX * 0.72 + predX * 0.28;
      mem.pos.y = rawY * 0.72 + predY * 0.28;
      mem.gpsJumpT = 0;
    } else if (dp < 22) {
      mem.pos.x = rawX * 0.35 + predX * 0.65;
      mem.pos.y = rawY * 0.35 + predY * 0.65;
      mem.gpsJumpT = 0;
    } else {
      mem.pos.x = predX;
      mem.pos.y = predY;
      mem.gpsJumpT += dt;
      if (mem.gpsJumpT > 2.0) {
