  }
  if (!isFinite(mem.pos.x)) mem.pos.x = oldPos.x;
  if (!isFinite(mem.pos.y)) mem.pos.y = oldPos.y;

  // Beacon position correction and heading-bias estimation.
  if (beacon && isFinite(beacon.distance) && isFinite(beacon.bearing)) {
    const bd = Number(beacon.distance);
    const bb = Number(beacon.bearing);
    if (bd > 2.0 && bd < 20.0) {
      const absTrue = angleTo(mem.pos.x, mem.pos.y, mem.base.x, mem.base.y);
      const biasObs = wrap(rawH + bb - absTrue);
      if (Math.abs(biasObs) < 75) {
        mem.bias = wrap(mem.bias + wrap(biasObs - mem.bias) * 0.035);
      }

      const absB = (controlHead + bb) * D2R;
      const cx = mem.base.x - bd * Math.cos(absB);
      const cy = mem.base.y - bd * Math.sin(absB);
      const cd = dist(cx, cy, mem.pos.x, mem.pos.y);
      if (cd < 10) {
        const w = mem.gpsFrozen ? 0.12 : 0.035;
        mem.pos.x = mem.pos.x * (1 - w) + cx * w;
        mem.pos.y = mem.pos.y * (1 - w) + cy * w;
      }
    }
  }
  mem.lastGPS = { x: rawX, y: rawY };

  // GPS course heading-bias estimation while driving nearly straight.
  if (!mem.gpsFrozen && Math.abs(vLin) > 0.35 && Math.abs(wl - wr) < 0.28) {
    if (mem.gpsHist.length === 0 ||
        dist(rawX, rawY, mem.gpsHist[mem.gpsHist.length - 1].x,
             mem.gpsHist[mem.gpsHist.length - 1].y) > 0.25) {
      mem.gpsHist.push({ x: rawX, y: rawY, t: t, h: rawH });
      while (mem.gpsHist.length > 24) mem.gpsHist.shift();
    }
  } else if (mem.gpsFrozen) {
    mem.gpsHist.length = 0;
  }

  if (mem.gpsHist.length >= 12 && Math.abs(vLin) > 0.4) {
    const a = mem.gpsHist[0];
    const b = mem.gpsHist[mem.gpsHist.length - 1];
    const gd = dist(a.x, a.y, b.x, b.y);
    const gt = b.t - a.t;
    if (gd > 1.2 && gt > 0.8) {
      let meanH = 0;
      let maxDev = 0;
      for (let i = 0; i < mem.gpsHist.length; i++) meanH += mem.gpsHist[i].h;
      meanH /= mem.gpsHist.length;
      for (let i = 0; i < mem.gpsHist.length; i++) {
        const dv = Math.abs(wrap(mem.gpsHist[i].h - meanH));
        if (dv > maxDev) maxDev = dv;
      }
      if (maxDev < 9) {
        const course = angleTo(a.x, a.y, b.x, b.y);
        const biasObs = wrap(meanH - course);
        if (Math.abs(biasObs) < 75) {
          mem.bias = wrap(mem.bias + wrap(biasObs - mem.bias) * 0.018);
        }
      }
    }
  }

  // Range sensors.
  const rawRays = [15, 15, 15, 15, 15, 15, 15, 15, 15];
  if (obs.rays && obs.rays.length) {
    for (let i = 0; i < 9; i++) {
      let v = Number(obs.rays[i]);
      if (!isFinite(v) || v < 0) v = 15;
      if (v > 15) v = 15;
      rawRays[i] = v;
    }
  }

  const rays = [15, 15, 15, 15, 15, 15, 15, 15, 15];
  let maxRay = 0;
  for (let i = 0; i < 9; i++) {
    const rv = rawRays[i];
    if (rv > maxRay) maxRay = rv;

    if (mem.rayLast[i] == null) mem.rayLast[i] = rv;
    const same = Math.abs(rv - mem.rayLast[i]) < 0.035;
    if (same) {
      mem.rayStill[i] += dt;
    } else {
      mem.rayStill[i] = 0;
      if (rv > 1.0) mem.rayBad[i] = false;
    }

    if (mem.rayStill[i] > 7.0 && Math.abs(vLin) > 0.14 && rv > 2.5) {
      mem.rayBad[i] = true;
    }
    if (mem.rayStill[i] > 8.5 && Math.abs(vLin) > 0.14 && rv < 2.5 &&
        t - mem.lastBumpT > 4.0) {
      mem.rayBad[i] = true;
    }

    mem.rayLast[i] = rv;

    let cv = rv;
    if (mem.rayBad[i]) cv = 15;
    if (cv < 0.02) cv = 0.02;
    if (cv > 15) cv = 15;
    rays[i] = cv;
  }
  mem.visibility = maxRay;

  function rayAt(rel) {
    const a = clamp(rel, -80, 80);
    const idx = (a + 80) / 20;
    let i = Math.floor(idx);
    if (i < 0) i = 0;
    if (i > 7) i = 7;
    let f = idx - i;
    if (f < 0) f = 0;
    if (f > 1) f = 1;
    let d1 = rays[i], d2 = rays[i + 1];
    if (!isFinite(d1)) d1 = 15;
    if (!isFinite(d2)) d2 = 15;
    return d1 * (1 - f) + d2 * f;
  }

  function boundaryClear(rel) {
    const ang = (controlHead + rel) * D2R;
    const dx = Math.cos(ang);
    const dy = Math.sin(ang);
    const margin = 1.1;
    let tx = 1e9, ty = 1e9;
    if (dx > 0.0001) tx = (mem.sizeX - margin - mem.pos.x) / dx;
    else if (dx < -0.0001) tx = (margin - mem.pos.x) / dx;
    if (dy > 0.0001) ty = (mem.sizeY - margin - mem.pos.y) / dy;
    else if (dy < -0.0001) ty = (margin - mem.pos.y) / dy;
    let d = 1e9;
    if (tx > 0) d = Math.min(d, tx);
    if (ty > 0) d = Math.min(d, ty);
    if (!(d > 0)) d = 0;
    return Math.min(d, 15);
  }

  function clearAt(rel) {
    return Math.min(rayAt(rel), boundaryClear(rel));
  }

  function computeDB() {
    let db = dist(mem.pos.x, mem.pos.y, mem.base.x, mem.base.y);
    if (beacon && isFinite(beacon.distance)) db = Math.min(db, Number(beacon.distance));
    return db;
  }

  function findHintNear(x, y, radius) {
    let best = null, bd = radius;
    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (h.status !== 0) continue;
      const d = dist(x, y, h.x, h.y);
      if (d < bd) {
        bd = d;
        best = h;
      }
    }
    return best;
  }

  function markSampled() {
    let px = mem.pos.x, py = mem.pos.y;
    if (mem.site) {
      px = mem.site.x;
      py = mem.site.y;
    }
    let h = findHintNear(px, py, 48);
    if (!h && mem.targetHint && mem.targetHint.status === 0) h = mem.targetHint;
    if (!h) h = findHintNear(mem.pos.x, mem.pos.y, 35);
    if (h) h.status = 1;
  }

  function failHint(h) {
    if (h && h.status === 0) h.status = 2;
    if (mem.targetHint === h) mem.targetHint = null;
    mem.search = null;
    mem.mode = "choose";
  }

  function chooseAvoidSide() {
    const left = clearAt(20) + 0.8 * clearAt(40) + 0.6 * clearAt(60) + 0.4 * clearAt(80);
    const right = clearAt(-20) + 0.8 * clearAt(-40) + 0.6 * clearAt(-60) + 0.4 * clearAt(-80);
    return left >= right ? 1 : -1;
  }

  function beginApproach(sd, sb, sv) {
    const ang = (controlHead + sb) * D2R;
    const sx = mem.pos.x + Math.cos(ang) * sd;
    const sy = mem.pos.y + Math.sin(ang) * sd;
    mem.site = {
      x: sx,
      y: sy,
      value: sv,
      start: t,
      lastSeen: t,
      fromMode: mem.mode,
      savedSearch: mem.search,
      savedHint: mem.targetHint
    };
    mem.mode = "approach";
    mem.drillOn = false;
    mem.hold = null;
    mem.arriveBaseT = 0;
  }

  function abortApproach() {
    const s = mem.site;
    if (s) {
      const h = findHintNear(s.x, s.y, 45);
      if (h) h.status = 2;
    }
    mem.site = null;
    mem.search = null;
    mem.targetHint = null;
    mem.mode = "choose";
  }

  function radiusForHint(h) {
    const med = mem.medValue || 1;
    const ratio = Math.max(0.1, (h.val || med) / med);
    let R = 20 + clamp(4 * (Math.sqrt(ratio) - 1), -4, 5);
    if (timeLeft < 350) R = Math.min(R, 18);
    if (timeLeft < 220) R = Math.min(R, 15);
    return clamp(R, 13, 26);
  }

  function startSearchFor(h) {
    const R = radiusForHint(h);
    const spacing = 10;
    const pts = [];
    const n = Math.ceil(R / spacing);
    for (let gx = -n * spacing; gx <= n * spacing; gx += spacing) {
      for (let gy = -n * spacing; gy <= n * spacing; gy += spacing) {
        if (gx * gx + gy * gy <= R * R + 0.1) {
          pts.push({
            x: clamp(h.x + gx, 2.0, mem.sizeX - 2.0),
            y: clamp(h.y + gy, 2.0, mem.sizeY - 2.0),
            visited: false
          });
        }
      }
    }
    if (pts.length === 0) {
      pts.push({ x: clamp(h.x, 2, mem.sizeX - 2), y: clamp(h.y, 2, mem.sizeY - 2), visited: false });
    }
    mem.search = {
      h: h,
      points: pts,
      start: t,
      maxTime: Math.min(220, 45 + pts.length * 9),
      extended: false,
      current: null,
      curStart: t,
      visitedCount: 0,
      blocked: 0
    };
    mem.targetHint = h;
    mem.mode = "search";
    mem.site = null;
    mem.stuckCount = 0;
  }

  function endSearch() {
    if (mem.search && mem.search.h && mem.search.h.status === 0) {
      mem.search.h.status = 2;
    }
    mem.search = null;
    mem.targetHint = null;
    mem.mode = "choose";
  }

  function initExplorePts() {
    if (mem.explorePts) return;
    mem.explorePts = [];
    const step = 55;
    for (let x = step * 0.45; x < mem.sizeX - 12; x += step) {
      for (let y = step * 0.45; y < mem.sizeY - 12; y += step) {
        mem.explorePts.push({ x: x, y: y, done: false });
      }
    }
    if (mem.explorePts.length === 0) {
      mem.explorePts.push({ x: mem.sizeX * 0.5, y: mem.sizeY * 0.5, done: false });
    }
  }

  function chooseExplorePoint() {
    initExplorePts();
    for (let i = 0; i < mem.explorePts.length; i++) {
      const p = mem.explorePts[i];
      if (!p.done && dist(mem.pos.x, mem.pos.y, p.x, p.y) < 12) p.done = true;
    }
    let best = null, bestScore = 1e99;
    for (let i = 0; i < mem.explorePts.length; i++) {
      const p = mem.explorePts[i];
      if (p.done) continue;
      const d = dist(mem.pos.x, mem.pos.y, p.x, p.y);
      const dB = dist(p.x, p.y, mem.base.x, mem.base.y);
      const need = (d + dB) / 0.50 + 25;
      if (timeLeft < need + 15) continue;
      if (battery < mem.costPerM * (d + dB) * 1.4 + 0.10) continue;
      const score = d + 0.35 * dB;
      if (score < bestScore) {
        bestScore = score;
        best = p;
      }
    }
    return best;
  }

  function chooseNext() {
    const db = computeDB();
    const atBaseNow = db < 3.0 || !!obs.docked;

    if (mem.carried > 0) {
      mem.mode = "return";
      return;
    }

    if (atBaseNow && battery < 0.65 && timeLeft > 120) {
      mem.mode = "charge";
      mem.chargeStart = t;
      mem.chargeStartBat = battery;
      mem.chargeTarget = battery < 0.40 ? 0.92 : (battery < 0.60 ? 0.82 : 0.73);
      return;
    }

    if (timeLeft < 18) {
      mem.mode = "idle";
      return;
    }

    if (!atBaseNow && battery < 0.18) {
      mem.mode = "return";
      return;
    }

    let best = null;
    let bestScore = -1e99;
    let bestD = 0;

    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (h.status !== 0) continue;

      const d = dist(mem.pos.x, mem.pos.y, h.x, h.y);
      const dh = dist(h.x, h.y, mem.base.x, mem.base.y);
      const R = radiusForHint(h);
      const approxPts = Math.max(5, Math.round(Math.PI * R * R / 100));
      const searchEst = 45 + approxPts * 8;
      const total = d + dh;

      const needTime = total / 0.55 + searchEst + 25;
      if (timeLeft < needTime + 10) continue;

      const energyNeed = 0.04 + mem.costPerM * (total * 1.5 + 60);
      if (battery < energyNeed && total > 18) continue;

      const val = h.val > 0 ? h.val : mem.medValue;
      let score;
      if (mem.deliveredCount === 0 && mem.totalSampleCount === 0) {
        score = 10000 / (d + 15) + 0.15 * val / (mem.medValue + 0.0001);
      } else {
        score = (val + 0.25 * mem.medValue) /
          Math.pow(total + 0.8 * searchEst + 35, 1.05);
        if (timeLeft < 350) score *= Math.pow(220 / (dh + 100), 0.30);
      }

      if (score > bestScore) {
        bestScore = score;
        best = h;
        bestD = d;
      }
    }

    if (best) {
      best.attempts++;
      mem.targetHint = best;
      mem.hintStart = t;
      mem.hintStartDist = bestD;
      mem.hintMaxTravel = Math.min(650, 110 + bestD / 0.35);
      mem.search = null;
      mem.site = null;
      mem.mode = "gotoHint";
      mem.stuckCount = 0;
      return;
    }

    const p = chooseExplorePoint();
    if (p) {
      mem.explorePoint = p;
      mem.targetHint = null;
      mem.search = null;
      mem.site = null;
      mem.mode = "explore";
      mem.stuckCount = 0;
      return;
    }

    if (atBaseNow) {
      if (battery < 0.78 && timeLeft > 35) {
        mem.mode = "charge";
        mem.chargeStart = t;
        mem.chargeStartBat = battery;
        mem.chargeTarget = Math.min(0.95, Math.max(0.72, battery + 0.20));
      } else {
        mem.mode = "idle";
      }
    } else {
      mem.mode = "return";
    }
  }

  // Handle carried changes before choosing a mode.
  if (cN > mem.carried) {
    const dC = cN - mem.carried;
    markSampled();
    mem.totalSampleCount += dC;
    mem.mode = "return";
    mem.targetHint = null;
    mem.search = null;
    mem.site = null;
    mem.hold = null;
    mem.drillOn = false;
    mem.arriveBaseT = 0;
  } else if (cN < mem.carried) {
    const dC = mem.carried - cN;
    if (dC > 0) mem.deliveredCount += dC;
    mem.mode = "choose";
    mem.site = null;
    mem.search = null;
    mem.targetHint = null;
    mem.hold = null;
    mem.drillOn = false;
    mem.arriveBaseT = 0;
  }
  mem.carried = cN;
  mem.lastCarried = cN;

  if (cN > 0 && mem.mode !== "return" && mem.mode !== "idle") {
    mem.mode = "return";
    mem.targetHint = null;
    mem.search = null;
    mem.site = null;
    mem.hold = null;
    mem.drillOn = false;
    mem.arriveBaseT = 0;
  }

  // Bump edge detection and persistent stuck/escape handling.
  const bumped = !!obs.bumped;
  if (bumped) {
    mem.lastBumpT = t;
    if (!mem.prevBumped) {
      mem.bumpTimes.push(t);
      while (mem.bumpTimes.length && t - mem.bumpTimes[0] > 15) mem.bumpTimes.shift();

      if (t > mem.escapeUntil + 0.15) {
        const side = chooseAvoidSide();
        mem.escapeSide = side;
        mem.escapeUntil = t + 1.6;
        mem.escapeCooldown = t + 1.8;
        mem.avoid.active = true;
        mem.avoid.side = side;
        mem.avoid.start = t;
        mem.avoid.clearT = 0;
      }

      if (mem.bumpTimes.length >= 6 && t > mem.severeBumpT + 6) {
        mem.severeBumpT = t;
        if (mem.carried > 0) {
          mem.avoid.side = -(mem.avoid.side || 1);
          mem.avoid.active = true;
          mem.avoid.start = t;
          mem.avoid.clearT = 0;
          mem.escapeSide = mem.avoid.side;
          mem.escapeUntil = t + 2.2;
        } else if (mem.mode === "search") {
          if (mem.search && mem.search.current) {
            mem.search.current.visited = true;
            mem.search.current = null;
            mem.search.blocked++;
            if (mem.search.blocked >= 3) endSearch();
          }
        } else if (mem.mode === "gotoHint" && mem.targetHint) {
          failHint(mem.targetHint);
        } else if (mem.mode === "approach") {
          abortApproach();
        } else if (mem.mode === "explore") {
          if (mem.explorePoint) mem.explorePoint.done = true;
          mem.mode = "choose";
        } else {
          mem.avoid.active = true;
          mem.escapeUntil = t + 2.2;
          mem.escapeSide = mem.avoid.side;
        }
        mem.bumpTimes.length = 0;
      }
    }
    for (let i = 0; i < 9; i++) {
      mem.rayBad[i] = false;
      mem.rayStill[i] = 0;
    }
  }
  mem.prevBumped = bumped;

  // Avoidance mode with hysteresis.
  const frontAvoid = Math.min(clearAt(-25), clearAt(-10), clearAt(0), clearAt(10), clearAt(25));
  if (!mem.avoid.active && frontAvoid < 2.2 &&
      mem.mode !== "drill" && mem.mode !== "charge" && mem.mode !== "idle") {
    const side = chooseAvoidSide();
    mem.avoid.active = true;
    mem.avoid.side = side;
    mem.avoid.start = t;
    mem.avoid.clearT = 0;
  } else if (mem.avoid.active) {
    if (frontAvoid > 3.2) {
      mem.avoid.clearT += dt;
      if (mem.avoid.clearT > 1.2) mem.avoid.active = false;
    } else {
      mem.avoid.clearT = 0;
    }
    if (t - mem.avoid.start > 16 && frontAvoid > 2.6) mem.avoid.active = false;
  }

  // Very close obstacle: force a short reverse even if path scoring would stop us.
  if (frontAvoid < 0.75 && t > mem.escapeUntil + 0.55 &&
      t > mem.escapeCooldown && mem.mode !== "drill" &&
      mem.mode !== "charge" && mem.mode !== "idle") {
    const side = chooseAvoidSide();
    mem.escapeSide = side;
    mem.escapeUntil = t + 1.0;
    mem.escapeCooldown = t + 1.6;
    mem.avoid.active = true;
    mem.avoid.side = side;
    mem.avoid.start = t;
    mem.avoid.clearT = 0;
  }

  // Opportunistically approach a real site whenever it is visible and we are not returning.
  if (siteObs && isFinite(siteObs.distance) && isFinite(siteObs.bearing) &&
      mem.mode !== "return" && mem.mode !== "charge" &&
      mem.mode !== "idle" && mem.mode !== "drill" &&
      mem.mode !== "approach" && cN < mem.capacity &&
      Number(siteObs.distance) < 8.5) {
    beginApproach(Number(siteObs.distance), Number(siteObs.bearing), Number(siteObs.value || 0));
  }

  if (mem.mode === "choose") chooseNext();

  let vLcmd = 0;
  let vRcmd = 0;
  let drillCmd = false;
  let didMotion = false;

  mem.lastWantSpeed = 0;

  function setMotion(a, b) {
    if (!isFinite(a)) a = 0;
    if (!isFinite(b)) b = 0;
    vLcmd = clamp(a, -1.25, 1.25);
    vRcmd = clamp(b, -1.25, 1.25);
    didMotion = true;
  }

  function stopMotion() {
    vLcmd = 0;
    vRcmd = 0;
    didMotion = true;
    mem.lastWantSpeed = 0;
  }

  function useSteer(errRel, speedWant) {
    errRel = wrap(errRel);
    if (!(speedWant > 0)) speedWant = 0;
    mem.lastWantSpeed = speedWant;

    let bestD = clamp(errRel, -80, 80);
    let bestScore = -1e99;
    let bestClear = 15;

    function evalDir(d) {
      const c = clearAt(d);
      const cSide = Math.min(clearAt(d - 22) + 0.35, clearAt(d + 22) + 0.35);
      const width = Math.min(c, cSide);
      const align = Math.cos(wrap(d - errRel) * D2R);
      let sc = Math.min(c, 7) * 1.7 + Math.min(width, 5) * 0.9 + align * 4.0;
      if (c < 1.0) sc -= 100;
      else if (c < 1.5) sc -= 12;
      if (width < 0.85) sc -= 20;
      if (mem.avoid.active) sc += mem.avoid.side * d * 0.030;
      if (sc > bestScore) {
        bestScore = sc;
        bestD = d;
        bestClear = c;
      }
    }

    for (let d = -80; d <= 80; d += 10) evalDir(d);
    if (errRel >= -80 && errRel <= 80) evalDir(errRel);

    const absErr = Math.abs(wrap(errRel));
    const absD = Math.abs(bestD);

    let v = speedWant;

    if (absErr > 100) v = Math.min(v, 0.05);
    else if (absErr > 70) v = Math.min(v, 0.18);
    else if (absErr > 45) v = Math.min(v, 0.42);
    else if (absErr > 25) v = Math.min(v, 0.65);

    if (absD > 72) v = Math.min(v, 0.18);
    else if (absD > 50) v = Math.min(v, 0.40);
    else if (absD > 30) v = Math.min(v, 0.62);

    if (frontAvoid < 0.90) v = 0;
    else if (frontAvoid < 1.45) v = Math.min(v, 0.10);
    else if (frontAvoid < 2.1) v = Math.min(v, 0.26);
    else if (frontAvoid < 3.0) v = Math.min(v, 0.48);

    if (bestClear < 1.0) v = 0;
    else if (bestClear < 1.6) v = Math.min(v, 0.12);
    else if (bestClear < 2.2) v = Math.min(v, 0.30);
    else if (bestClear < 3.1) v = Math.min(v, 0.55);

    if (mem.visibility < 10) v = Math.min(v, 0.62);
    if (mem.visibility < 6) v = Math.min(v, 0.42);
    if (mem.visibility < 3.5) v = Math.min(v, 0.24);
    if (mem.slip < 0.55) v = Math.min(v, 0.55);

    let omega;
    if (v < 0.05) omega = clamp(bestD * 0.022, -0.9, 0.9);
    else omega = clamp(bestD * 0.016, -0.75, 0.75);

    if (Math.abs(bestD) < 3) omega *= 0.55;

    const vl = v - omega * 0.3;
    const vr = v + omega * 0.3;

    setMotion(clamp(vl, -1.1, 1.1), clamp(vr, -1.1, 1.1));
  }

  function abortDrillToApproach() {
    mem.mode = "approach";
    mem.drillOn = false;
    if (mem.site) mem.site.start = t;
  }

  // Mode execution.
  if (mem.mode === "gotoHint") {
    const h = mem.targetHint;
    if (!h || h.status !== 0) {
      mem.mode = "choose";
      stopMotion();
    } else {
      const d = dist(mem.pos.x, mem.pos.y, h.x, h.y);
      const dh = dist(h.x, h.y, mem.base.x, mem.base.y);

      if (d < 6.0) {
        startSearchFor(h);
        stopMotion();
      } else if (t - mem.hintStart > mem.hintMaxTravel && d > 15) {
        failHint(h);
        stopMotion();
      } else if (timeLeft < (d + dh) / 0.42 + 30) {
        mem.mode = "return";
        stopMotion();
      } else {
        let sp = 0.82;
        if (d < 25) sp = 0.62;
        if (d < 12) sp = 0.45;
        if (timeLeft < 220) sp = Math.min(0.92, sp + 0.08);
        useSteer(wrap(angleTo(mem.pos.x, mem.pos.y, h.x, h.y) - controlHead), sp);
      }
    }
  } else if (mem.mode === "search") {
    const s = mem.search;
    if (!s || !s.h) {
      mem.mode = "choose";
      stopMotion();
    } else if (t - s.start > s.maxTime) {
      if (!s.extended && science > 0.12 && s.h.val >= mem.medValue * 0.75 && timeLeft > 160) {
        s.extended = true;
        s.maxTime += 55;
      } else {
        endSearch();
        stopMotion();
      }
    }

    if (mem.mode === "search" && mem.search) {
      const s2 = mem.search;
      if (!s2.current) {
        let bi = -1, bd = 1e99;
        for (let i = 0; i < s2.points.length; i++) {
          const p = s2.points[i];
          if (p.visited) continue;
          const dd = dist(mem.pos.x, mem.pos.y, p.x, p.y);
          if (dd < bd) {
            bd = dd;
            bi = i;
          }
        }
        if (bi < 0) {
          endSearch();
        } else {
          s2.current = s2.points[bi];
          s2.curStart = t;
        }
      }

      if (mem.mode === "search" && mem.search && mem.search.current) {
        const s3 = mem.search;
        const p = s3.current;
        const dd = dist(mem.pos.x, mem.pos.y, p.x, p.y);

        if (dd < 2.25) {
          p.visited = true;
          s3.visitedCount++;
          s3.current = null;
          stopMotion();
        } else if (t - s3.curStart > 16) {
          p.visited = true;
          s3.visitedCount++;
          s3.blocked++;
          s3.current = null;
          if (s3.blocked >= 3) endSearch();
          stopMotion();
        } else {
          let sp = 0.70;
          if (dd < 6) sp = 0.48;
          if (s3.visitedCount < 2) sp = Math.min(sp, 0.55);
          useSteer(wrap(angleTo(mem.pos.x, mem.pos.y, p.x, p.y) - controlHead), sp);
        }
      }
    }
  } else if (mem.mode === "approach") {
    const s = mem.site;
    if (!s) {
      mem.mode = "choose";
      stopMotion();
    } else {
      let vis = false;
      let sd = 1e9;
      let sb = 0;

      if (siteObs && isFinite(siteObs.distance) && isFinite(siteObs.bearing) &&
          Number(siteObs.distance) < 8.5) {
        vis = true;
        sd = Number(siteObs.distance);
        sb = Number(siteObs.bearing);
        const ang = (controlHead + sb) * D2R;
        s.x = mem.pos.x + Math.cos(ang) * sd;
        s.y = mem.pos.y + Math.sin(ang) * sd;
        s.value = Number(siteObs.value || s.value || 0);
        s.lastSeen = t;
      }

      let d = vis ? sd : dist(mem.pos.x, mem.pos.y, s.x, s.y);
      const db = computeDB();

      if (timeLeft < db / 0.45 + 16 && d > 1.3) {
        mem.mode = "return";
        mem.site = null;
        stopMotion();
      } else if (timeLeft < 12 && d > 1.3) {
        mem.mode = "choose";
        mem.site = null;
        stopMotion();
      } else if (d <= 1.55) {
        stopMotion();
        if (Math.abs(vLin) < 0.15) {
          mem.mode = "drill";
          mem.hold = { x: mem.pos.x, y: mem.pos.y };
          mem.drillStart = t;
          mem.drillOn = false;
        }
      } else if (!vis && t - s.lastSeen > 1.6) {
        if (d < 1.55 && Math.abs(vLin) < 0.20) {
          mem.mode = "drill";
          mem.hold = { x: mem.pos.x, y: mem.pos.y };
          mem.drillStart = t;
          mem.drillOn = false;
          stopMotion();
        } else if (t - s.start > 65) {
          abortApproach();
          stopMotion();
        } else {
          useSteer(wrap(angleTo(mem.pos.x, mem.pos.y, s.x, s.y) - controlHead), 0.28);
        }
      } else if (t - s.start > 80) {
        abortApproach();
        stopMotion();
      } else {
        let sp;
        if (d > 5.0) sp = 0.72;
        else if (d > 3.0) sp = 0.52;
        else if (d > 2.0) sp = 0.32;
        else if (d > 1.55) sp = 0.16;
        else sp = 0.08;

        if (Math.abs(vLin) > 0.30 && d < 2.1) sp = 0.04;

        const err = vis ? sb :
          wrap(angleTo(mem.pos.x, mem.pos.y, s.x, s.y) - controlHead);
        useSteer(err, sp);
      }
    }
  } else if (mem.mode === "drill") {
    const s = mem.site;
    if (!s) {
      mem.mode = "choose";
      stopMotion();
    } else {
      let vis = false;
      let sd = 1e9;
      if (siteObs && isFinite(siteObs.distance) && isFinite(siteObs.bearing)) {
        sd = Number(siteObs.distance);
        if (sd < 8.5) {
          vis = true;
          const ang = (controlHead + Number(siteObs.bearing)) * D2R;
          s.x = mem.pos.x + Math.cos(ang) * sd;
          s.y = mem.pos.y + Math.sin(ang) * sd;
          s.lastSeen = t;
        }
      }

      const d = vis ? sd : dist(mem.pos.x, mem.pos.y, s.x, s.y);
      const spd = Math.abs(vLin);

      stopMotion();

      if (d <= 1.55 && spd < 0.18) {
        drillCmd = true;
        if (!mem.drillOn) {
          mem.drillOn = true;
          mem.drillStart = t;
        }
      } else {
        drillCmd = false;
        mem.drillOn = false;
      }

      if (d > 1.65 && spd < 0.10) {
        abortDrillToApproach();
        drillCmd = false;
      } else if (t - mem.drillStart > 15) {
        drillCmd = false;
        mem.drillOn = false;
        if (mem.search) {
          mem.mode = "search";
        } else {
          mem.mode = "choose";
        }
      } else if (!vis && t - s.lastSeen > 9) {
        drillCmd = false;
        mem.mode = "choose";
      }
    }
  } else if (mem.mode === "return") {
    const db = computeDB();
    const cNow = mem.carried;

    if (db < 2.65 || obs.docked) {
      stopMotion();
      drillCmd = false;
      if (!mem.arriveBaseT) mem.arriveBaseT = t;

      if (cNow === 0) {
        if (battery < 0.68 && timeLeft > 120) {
          mem.mode = "charge";
          mem.chargeStart = t;
          mem.chargeStartBat = battery;
          mem.chargeTarget = battery < 0.40 ? 0.92 : (battery < 0.60 ? 0.82 : 0.74);
        } else {
          mem.mode = "choose";
        }
      } else {
        if (t - mem.arriveBaseT > 2.0 && db > 0.85) {
          let err;
          if (beacon && isFinite(beacon.bearing)) err = Number(beacon.bearing);
          else err = wrap(angleTo(mem.pos.x, mem.pos.y, mem.base.x, mem.base.y) - controlHead);
          useSteer(err, 0.12);
        }
      }
    } else {
      let err;
      if (beacon && isFinite(beacon.bearing) && isFinite(beacon.distance) &&
          Number(beacon.distance) < 20) {
        err = Number(beacon.bearing);
      } else {
        err = wrap(angleTo(mem.pos.x, mem.pos.y, mem.base.x, mem.base.y) - controlHead);
      }

      let sp = 0.86;
      if (db < 10) sp = 0.58;
      if (db < 5) sp = 0.34;
      if (db < 3) sp = 0.18;
      if (timeLeft < db / 0.45 + 14 && cNow > 0) sp = 0.96;
      if (battery < 0.14) sp = Math.min(sp, 0.58);

      useSteer(err, sp);
    }
  } else if (mem.mode === "charge") {
    stopMotion();
    drillCmd = false;
    const db = computeDB();
    if (db > 3.2 && !obs.docked) {
      mem.mode = "return";
    } else if (battery >= mem.chargeTarget || timeLeft < 35) {
      mem.mode = "choose";
    } else if (t - mem.chargeStart > 55 &&
               battery < mem.chargeStartBat + 0.012) {
      mem.mode = "choose";
    }
  } else if (mem.mode === "explore") {
    const p = mem.explorePoint;
    if (!p || p.done) {
      mem.mode = "choose";
      stopMotion();
    } else {
      const d = dist(mem.pos.x, mem.pos.y, p.x, p.y);
      const dB = dist(p.x, p.y, mem.base.x, mem.base.y);
      if (d < 4.0) {
        p.done = true;
        mem.mode = "choose";
        stopMotion();
      } else if (timeLeft < (d + dB) / 0.42 + 25) {
        p.done = true;
        mem.mode = "choose";
        stopMotion();
      } else {
        let sp = 0.82;
        if (d < 12) sp = 0.58;
        useSteer(wrap(angleTo(mem.pos.x, mem.pos.y, p.x, p.y) - controlHead), sp);
      }
    }
  } else if (mem.mode === "idle") {
    stopMotion();
    drillCmd = false;
  } else {
    stopMotion();
  }

  // Escape override: back away from whatever stopped us.
  if (t < mem.escapeUntil) {
    const side = mem.escapeSide || 1;
    const v = -0.34;
    const omega = 0.86 * side;
    const vl = v - omega * 0.3;
    const vr = v + omega * 0.3;
    setMotion(vl, vr);
    drillCmd = false;
    mem.lastWantSpeed = -0.34;
  }

  // Debounced stuck detection.
  if (t - mem.stuckCheckT > 2.0) {
    const moved = dist(mem.pos.x, mem.pos.y, mem.stuckPos.x, mem.stuckPos.y);
    const turned = Math.abs(wrap(mem.head - mem.stuckHead));
    const movingMode = (mem.mode === "gotoHint" || mem.mode === "search" ||
                        mem.mode === "approach" || mem.mode === "return" ||
                        mem.mode === "explore");

    const stuckCond = movingMode && t >= mem.escapeUntil &&
      mem.lastWantSpeed > 0.18 && moved < 0.18 && turned < 12 &&
      Math.abs(vLin) < 0.16;

    if (stuckCond) {
      mem.stuckCount++;
      if (t > mem.escapeUntil + 0.2) {
        const side = chooseAvoidSide();
        mem.escapeSide = side;
        mem.escapeUntil = t + 1.5;
        mem.escapeCooldown = t + 1.8;
        mem.avoid.active = true;
        mem.avoid.side = side;
        mem.avoid.start = t;
        mem.avoid.clearT = 0;
      }

      if (mem.stuckCount >= 4) {
        if (mem.mode === "search" && mem.search) {
          if (mem.search.current) {
            mem.search.current.visited = true;
            mem.search.current = null;
            mem.search.blocked++;
          }
          if (mem.search.blocked >= 3) endSearch();
        } else if (mem.mode === "gotoHint" && mem.targetHint) {
          failHint(mem.targetHint);
        } else if (mem.mode === "approach") {
          abortApproach();
        } else if (mem.mode === "explore") {
          if (mem.explorePoint) mem.explorePoint.done = true;
          mem.mode = "choose";
        } else if (mem.mode === "return") {
          mem.avoid.side = -(mem.avoid.side || 1);
          mem.avoid.active = true;
          mem.avoid.start = t;
          mem.avoid.clearT = 0;
          mem.escapeSide = mem.avoid.side;
          mem.escapeUntil = t + 2.0;
        }
        mem.stuckCount = 0;
      }
    } else {
      mem.stuckCount = Math.max(0, mem.stuckCount - 1);
    }

    mem.stuckPos = { x: mem.pos.x, y: mem.pos.y };
    mem.stuckHead = mem.head;
    mem.stuckCheckT = t;
  }

  // Wheel-speed feedback.
  function wheelCmd(target, actual, st, isHold) {
    if (!isFinite(target)) target = 0;
    if (!isFinite(actual)) actual = 0;

    if (isHold || Math.abs(target) < 0.025) {
      let u = -1.15 * actual;
      if (Math.abs(actual) > 0.008) u += (u >= 0 ? 0.035 : -0.035);
      st.i *= 0.65;
      st.lastTarget = target;
      return clamp(u, -0.85, 0.85);
    }

    const err = target - actual;
    st.i += err * dt * 0.13;
    st.i = clamp(st.i, -0.22, 0.22);

    if (st.lastTarget != null && target * st.lastTarget < 0) st.i *= 0.35;

    const gain = st.gain || 0.42;
    let u = gain * target + 0.34 * err + st.i;

    if (Math.abs(target) > 0.04) u += (u >= 0 ? 0.03 : -0.03);

    if (Math.abs(target) > 0.18 && actual * target > 0 && t - (st.lastGainT || 0) > 2.0) {
      const ratio = Math.abs(actual) / Math.abs(target);
      if (ratio < 0.62) st.gain = Math.min(0.66, gain * 1.035);
      else if (ratio > 1.55) st.gain = Math.max(0.24, gain * 0.965);
      st.lastGainT = t;
    }

    st.lastTarget = target;
    return clamp(u, -0.92, 0.92);
  }

  const holdL = Math.abs(vLcmd) < 0.03;
  const holdR = Math.abs(vRcmd) < 0.03;

  let uL = wheelCmd(vLcmd, wl, mem.pidL, holdL);
  let uR = wheelCmd(vRcmd, wr, mem.pidR, holdR);

  // Absolute speed governor for unknown motor strength.
  const avgWheel = (wl + wr) / 2;
  if (avgWheel > 0.86) {
    const brake = -(avgWheel - 0.86) * 1.8;
    if (uL > brake) uL = Math.min(uL, brake);
    if (uR > brake) uR = Math.min(uR, brake);
  }
  if (avgWheel < -0.95) {
    const brake = (Math.abs(avgWheel) - 0.95) * -1.8;
    if (uL < brake) uL = Math.max(uL, brake);
    if (uR < brake) uR = Math.max(uR, brake);
  }

  // Energy cost estimation.
  const movedGeo = dist(oldPos.x, oldPos.y, mem.pos.x, mem.pos.y);
  const solar = Number(obs.solar || 0);
  const consumption = solar * dt - (battery - mem.lastBattery);
  if (!obs.docked && Math.abs(vLin) > 0.04) {
    const dProg = Math.min(movedGeo, Math.abs(vLin) * dt * 1.8 + 0.05);
    if (dProg > 0.008 && consumption > 0) {
      mem.energyDrain += consumption;
      mem.energyDist += dProg;
      if (mem.energyDist > 25) {
        const cpm = mem.energyDrain / mem.energyDist;
        if (cpm > 0.00002 && cpm < 0.02) {
          mem.costPerM = mem.costPerM * 0.82 + cpm * 0.18;
        }
        mem.energyDrain = 0;
        mem.energyDist = 0;
      }
    }
  }
  mem.lastBattery = battery;

  if (!mem.gpsFrozen && Math.abs(vLin) > 0.05 && movedGeo > 0.01) {
    const ratio = movedGeo / (Math.abs(vLin) * dt + 0.0001);
    mem.slip = mem.slip * 0.985 + ratio * 0.015;
    if (mem.slip < 0.58) mem.sandFlag = true;
    else if (mem.slip > 0.82) mem.sandFlag = false;
  }

  mem.cmdL = uL;
  mem.cmdR = uR;
  mem.lastWantSpeed = mem.lastWantSpeed || 0;

  if (t < mem.escapeUntil) drillCmd = false;

  return {
    left: clamp(uL, -1, 1),
    right: clamp(uR, -1, 1),
    drill: !!drillCmd
  };
}

function act(obs, mem) {
  const PI = Math.PI;
  const D2R = PI / 180;
  const R2D = 180 / PI;

  function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
  function wrap(a) {
    a = a % 360;
    if (a > 180) a -= 360;
    if (a < -180) a += 360;
    return a;
  }
  function dist(ax, ay, bx, by) {
    const dx = ax - bx, dy = ay - by;
    return Math.sqrt(dx * dx + dy * dy);
  }
  function angleTo(x1, y1, x2, y2) {
    return Math.atan2(y2 - y1, x2 - x1) * R2D;
  }
  function countCarried(o) {
    const c = o.carried;
    if (typeof c === "number") return c;
    if (Array.isArray(c)) return c.length;
    if (c && typeof c.length === "number") return c.length;
    return c ? 1 : 0;
  }

  let t = Number(obs.t);
  if (!isFinite(t)) t = 0;

  if (!mem.init) {
    mem.init = true;

    const mission = obs.mission || {};
    let sx = mission.size, sy = mission.size;
    if (sx && typeof sx === "object") {
      sy = Number(sx.y != null ? sx.y : (sx.h != null ? sx.h : 400));
      sx = Number(sx.x != null ? sx.x : (sx.w != null ? sx.w : 400));
    }
    sx = Number(sx); sy = Number(sy);
    if (!(sx > 10)) sx = 400;
    if (!(sy > 10)) sy = 400;
    mem.sizeX = sx;
    mem.sizeY = sy;

    const mb = mission.base || {};
    mem.base = {
      x: isFinite(Number(mb.x)) ? Number(mb.x) : (Number(obs.x) || 200),
      y: isFinite(Number(mb.y)) ? Number(mb.y) : (Number(obs.y) || 200)
    };
    if (!isFinite(mem.base.x)) mem.base.x = Number(obs.x) || 0;
    if (!isFinite(mem.base.y)) mem.base.y = Number(obs.y) || 0;

    mem.capacity = Number(mission.capacity || 5);
    if (!(mem.capacity >= 1)) mem.capacity = 5;
    mem.seconds = Number(mission.seconds || 1200);
    if (!(mem.seconds > 0)) mem.seconds = 1200;

    mem.hints = [];
    const hs = mission.hints || [];
    for (let i = 0; i < hs.length; i++) {
      const h = hs[i] || {};
      const hx = Number(h.x), hy = Number(h.y);
      let hv = Number(h.estimate);
      if (!isFinite(hx) || !isFinite(hy)) continue;
      if (!isFinite(hv) || hv < 0) hv = 1;
      mem.hints.push({
        id: mem.hints.length,
        x: hx,
        y: hy,
        val: hv,
        status: 0,
        attempts: 0
      });
    }

    const vals = [];
    for (let i = 0; i < mem.hints.length; i++) vals.push(mem.hints[i].val);
    vals.sort(function(a, b) { return a - b; });
    mem.medValue = vals.length ? vals[Math.floor(vals.length / 2)] : 1;
    if (!(mem.medValue > 0)) mem.medValue = 1;
    mem.maxValue = 0;
    for (let i = 0; i < vals.length; i++) if (vals[i] > mem.maxValue) mem.maxValue = vals[i];
    if (!(mem.maxValue > 0)) mem.maxValue = mem.medValue;

    let px = Number(obs.x), py = Number(obs.y);
    if (!isFinite(px)) px = mem.base.x;
    if (!isFinite(py)) py = mem.base.y;
    mem.pos = { x: px, y: py };
    mem.lastRawPos = { x: px, y: py };

    let rh = Number(obs.heading);
    if (!isFinite(rh)) rh = 0;
    mem.headEst = rh;
    mem.lastRawH = rh;
    mem.bias = 0;
    mem.lastT = t;

    mem.lastCarried = countCarried(obs);
    mem.lastDelivered = Number(obs.delivered);
    if (!isFinite(mem.lastDelivered)) mem.lastDelivered = 0;
    mem.totalSamples = 0;
    mem.totalDelivered = 0;

    mem.state = "choose";
    mem.targetHint = null;
    mem.search = null;
    mem.approach = null;
    mem.explorePts = null;
    mem.exploreTarget = null;
    mem.hintStart = t;

    mem.drillStart = 0;
    mem.drillSite = null;

    mem.prevBumped = false;
    mem.recoverUntil = -1;
    mem.recoverStart = -1;
    mem.recoverSide = 1;
    mem.stuckStrikes = 0;
    mem.stuckTotal = 0;
    mem.progressT = t;
    mem.progressPos = { x: px, y: py };

    mem.avoidSide = 1;
    mem.avoidUntil = -1;

    mem.mpsPerCmd = 2.2;
    mem.deadzone = 0.035;
    mem.cmdL = 0;
    mem.cmdR = 0;

    mem.freezeTimer = 0;
    mem.gpsFrozen = false;
    mem.gpsJumpT = 0;
    mem.gpsHist = [];

    mem.chargeStart = t;
    mem.chargeStartBat = Number(obs.battery);
    if (!isFinite(mem.chargeStartBat)) mem.chargeStartBat = 1;
    mem.chargeTarget = 0.8;
    mem.returnReason = "";
    mem.returnStart = t;

    mem.lastScience = Number(obs.science) || 0;
  }

  let dt = 0.1;
  if (mem.lastT != null) {
    const dd = t - mem.lastT;
    if (dd > 0.001 && dd < 1.0) dt = dd;
  }
  mem.lastT = t;

  let wl = Number(obs.wheelLeft);
  let wr = Number(obs.wheelRight);
  if (!isFinite(wl)) wl = 0;
  if (!isFinite(wr)) wr = 0;
  const speedActual = (wl + wr) / 2;

  let battery = Number(obs.battery);
  if (!isFinite(battery)) battery = 1;

  let timeLeft = Number(obs.timeLeft);
  if (!isFinite(timeLeft)) timeLeft = mem.seconds - t;
  if (timeLeft < 0) timeLeft = 0;

  let science = Number(obs.science);
  if (!isFinite(science)) science = 0;
  mem.lastScience = science;

  const c = countCarried(obs);

  let rawH = Number(obs.heading);
  if (!isFinite(rawH)) rawH = mem.lastRawH;

  const wheelYaw = ((wr - wl) / 0.6) * dt * R2D;
  const predHead = wrap(mem.headEst + wheelYaw);
  const dRawH = wrap(rawH - mem.lastRawH);
  const headingJump = Math.abs(dRawH) > 50 && Math.abs(wheelYaw) < 12;
  const rawActual = wrap(rawH - mem.bias);

  if (headingJump) {
    mem.headEst = predHead;
  } else {
    const diff = wrap(rawActual - predHead);
    if (Math.abs(diff) > 60) {
      if (Math.abs(speedActual) < 0.05) mem.headEst = rawActual;
      else mem.headEst = predHead;
    } else {
      mem.headEst = wrap(predHead + diff * 0.55);
    }
  }
  mem.lastRawH = rawH;

  let rawX = Number(obs.x), rawY = Number(obs.y);
  if (!isFinite(rawX)) rawX = mem.lastRawPos.x;
  if (!isFinite(rawY)) rawY = mem.lastRawPos.y;

  const predX = mem.pos.x + speedActual * Math.cos(mem.headEst * D2R) * dt;
  const predY = mem.pos.y + speedActual * Math.sin(mem.headEst * D2R) * dt;
  const rawMoved = dist(rawX, rawY, mem.lastRawPos.x, mem.lastRawPos.y);

  if (Math.abs(speedActual) > 0.15 && rawMoved < 0.006) mem.freezeTimer += dt;
  else if (rawMoved > 0.025) mem.freezeTimer = 0;

  if (mem.freezeTimer > 2.0) mem.gpsFrozen = true;
  if (mem.gpsFrozen && rawMoved > 0.08) {
    mem.gpsFrozen = false;
    mem.freezeTimer = 0;
  }

  if (mem.gpsFrozen) {
    mem.pos.x = predX;
    mem.pos.y = predY;
  } else {
    const dp = dist(rawX, rawY, predX, predY);
    if (dp < 2.5) {
      mem.pos.x = rawX * 0.82 + predX * 0.18;
      mem.pos.y = rawY * 0.82 + predY * 0.18;
      mem.gpsJumpT = 0;
    } else if (dp < 9) {
      mem.pos.x = rawX * 0.55 + predX * 0.45;
      mem.pos.y = rawY * 0.55 + predY * 0.45;
      mem.gpsJumpT = 0;
    } else {
      mem.pos.x = predX;
      mem.pos.y = predY;
      mem.gpsJumpT += dt;
      if (mem.gpsJumpT > 1.5) {
        mem.pos.x = rawX;
        mem.pos.y = rawY;
        mem.gpsJumpT = 0;
      }
    }
  }
  if (!isFinite(mem.pos.x)) mem.pos.x = predX;
  if (!isFinite(mem.pos.y)) mem.pos.y = predY;
  mem.lastRawPos = { x: rawX, y: rawY };

  const rawRays = [15, 15, 15, 15, 15, 15, 15, 15, 15];
  if (obs.rays && obs.rays.length) {
    for (let i = 0; i < 9; i++) {
      let v = Number(obs.rays[i]);
      if (!isFinite(v) || v < 0) v = 15;
      if (v > 15) v = 15;
      if (v < 0.02) v = 0.02;
      rawRays[i] = v;
    }
  }
  const rays = rawRays;

  function rayAt(rel) {
    const a = clamp(rel, -80, 80);
    const idx = (a + 80) / 20;
    let i = Math.floor(idx);
    if (i < 0) i = 0;
    if (i > 7) i = 7;
    let f = idx - i;
    if (f < 0) f = 0;
    if (f > 1) f = 1;
    let d1 = rays[i], d2 = rays[i + 1];
    if (!isFinite(d1)) d1 = 15;
    if (!isFinite(d2)) d2 = 15;
    return d1 * (1 - f) + d2 * f;
  }

  function boundaryClear(rel) {
    const ang = (mem.headEst + rel) * D2R;
    const dx = Math.cos(ang);
    const dy = Math.sin(ang);
    const margin = 2.0;
    let tx = 1e9, ty = 1e9;
    if (dx > 0.000001) tx = (mem.sizeX - margin - mem.pos.x) / dx;
    else if (dx < -0.000001) tx = (margin - mem.pos.x) / dx;
    if (dy > 0.000001) ty = (mem.sizeY - margin - mem.pos.y) / dy;
    else if (dy < -0.000001) ty = (margin - mem.pos.y) / dy;
    let d = 1e9;
    if (tx > 0) d = Math.min(d, tx);
    if (ty > 0) d = Math.min(d, ty);
    if (!(d > 0)) d = 0;
    return Math.min(d, 15);
  }

  function clearAt(rel) {
    return Math.min(rayAt(rel), boundaryClear(rel));
  }

  function chooseOpenSide() {
    let left = 0, right = 0;
    for (let i = 0; i < 9; i++) {
      const rel = (i - 4) * 20;
      const d = Math.min(rays[i], 6);
      if (rel > 0) left += d;
      else if (rel < 0) right += d;
    }
    if (Math.abs(left - right) < 0.25) {
      return (mem.avoidSide || 1) >= 0 ? 1 : -1;
    }
    return left >= right ? 1 : -1;
  }

  const beacon = obs.beacon || null;
  const siteO = obs.site || null;

  if (beacon && isFinite(Number(beacon.distance)) && isFinite(Number(beacon.bearing))) {
    const bd = Number(beacon.distance);
    const bb = Number(beacon.bearing);
    const trueAng = angleTo(mem.pos.x, mem.pos.y, mem.base.x, mem.base.y);

    if (bd > 2.5 && bd < 20) {
      const biasObs = wrap(rawH + bb - trueAng);
      const diffBias = wrap(biasObs - mem.bias);
      if (Math.abs(diffBias) < 45) {
        mem.bias = wrap(mem.bias + diffBias * 0.03);
      }
    }

    if (bd < 20) {
      const absAng = (mem.headEst + bb) * D2R;
      const bx = mem.base.x - bd * Math.cos(absAng);
      const by = mem.base.y - bd * Math.sin(absAng);
      const dd = dist(bx, by, mem.pos.x, mem.pos.y);
      if (dd < 8) {
        const wgt = mem.gpsFrozen ? 0.05 : 0.025;
        mem.pos.x = mem.pos.x * (1 - wgt) + bx * wgt;
        mem.pos.y = mem.pos.y * (1 - wgt) + by * wgt;
      }
    }
  }

  if (!mem.gpsFrozen && Math.abs(speedActual) > 0.3 && Math.abs(wl - wr) < 0.2) {
    if (mem.gpsHist.length === 0 ||
        dist(rawX, rawY, mem.gpsHist[mem.gpsHist.length - 1].x,
             mem.gpsHist[mem.gpsHist.length - 1].y) > 0.5) {
      mem.gpsHist.push({ x: rawX, y: rawY, t: t, h: rawH });
      while (mem.gpsHist.length > 14) mem.gpsHist.shift();
    }
  } else if (mem.gpsFrozen) {
    mem.gpsHist.length = 0;
  }

  if (mem.gpsHist.length >= 8) {
    const a = mem.gpsHist[0];
    const b = mem.gpsHist[mem.gpsHist.length - 1];
    const gd = dist(a.x, a.y, b.x, b.y);
    const gt = b.t - a.t;
    if (gd > 1.5 && gt > 1.0) {
      let sxh = 0, syh = 0;
      for (let i = 0; i < mem.gpsHist.length; i++) {
        const hh = mem.gpsHist[i].h * D2R;
        sxh += Math.cos(hh);
        syh += Math.sin(hh);
      }
      const meanH = Math.atan2(syh, sxh) * R2D;
      const course = angleTo(a.x, a.y, b.x, b.y);
      const biasObs = wrap(meanH - course);
      const diffBias = wrap(biasObs - mem.bias);
      if (Math.abs(diffBias) < 35) {
        mem.bias = wrap(mem.bias + diffBias * 0.01);
      }
    }
  }

  let dB = dist(mem.pos.x, mem.pos.y, mem.base.x, mem.base.y);
  if (beacon && isFinite(Number(beacon.distance)) && Number(beacon.distance) < 25) {
    dB = Math.min(dB, Number(beacon.distance));
  }

  function markHintSampled(px, py) {
    let best = null, bd = 45;
    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (h.status !== 0) continue;
      const d = dist(px, py, h.x, h.y);
      if (d < bd) {
        bd = d;
        best = h;
      }
    }
    if (!best && mem.targetHint && mem.targetHint.status === 0) best = mem.targetHint;
    if (best) best.status = 1;
  }

  function failHint(h) {
    if (h && h.status === 0) h.status = 2;
  }

  function beginApproach(sd, sb, sv) {
    sd = Number(sd);
    sb = Number(sb);
    sv = Number(sv);
    if (!isFinite(sd) || !isFinite(sb)) return;
    const ab = (mem.headEst + sb) * D2R;
    mem.approach = {
      x: mem.pos.x + Math.cos(ab) * sd,
      y: mem.pos.y + Math.sin(ab) * sd,
      value: isFinite(sv) ? sv : 0,
      lastSeen: t,
      start: t,
      hint: mem.targetHint || null
    };
    mem.state = "approach";
    mem.drillSite = null;
    mem.drillStart = 0;
  }

  function abortApproach() {
    if (mem.targetHint && mem.targetHint.status === 0) mem.targetHint.status = 2;
    mem.approach = null;
    if (mem.search) mem.state = "search";
    else mem.state = "choose";
  }

  function startSearch(h) {
    let R = 22;
    if (timeLeft < 300) R = 18;
    if (timeLeft < 180) R = 15;
    const step = 7.5;
    const pts = [];
    const r2 = R * R + 0.5;
    for (let gx = -R; gx <= R + 0.01; gx += step) {
      for (let gy = -R; gy <= R + 0.01; gy += step) {
        if (gx * gx + gy * gy <= r2) {
          const x = h.x + gx;
          const y = h.y + gy;
          if (x < 3 || x > mem.sizeX - 3 || y < 3 || y > mem.sizeY - 3) continue;
          pts.push({ x: x, y: y, visited: false, blockCount: 0 });
        }
      }
    }
    if (pts.length === 0) {
      pts.push({
        x: clamp(h.x, 3, mem.sizeX - 3),
        y: clamp(h.y, 3, mem.sizeY - 3),
        visited: false,
        blockCount: 0
      });
    }
    pts.sort(function(a, b) {
      return dist(mem.pos.x, mem.pos.y, a.x, a.y) -
             dist(mem.pos.x, mem.pos.y, b.x, b.y);
    });

    mem.search = {
      h: h,
      points: pts,
      start: t,
      current: null,
      curStart: t,
      maxTime: 95,
      extended: false,
      blocked: 0,
      visited: 0,
      sciMax: science,
      sciPos: { x: mem.pos.x, y: mem.pos.y }
    };
    mem.targetHint = h;
    mem.state = "search";
    mem.approach = null;
  }

  function finishSearch(success) {
    const h = (mem.search && mem.search.h) || mem.targetHint;
    if (h && h.status === 0) h.status = success ? 1 : 2;
    mem.search = null;
    mem.state = "choose";
  }

  function initExplore() {
    if (mem.explorePts) return;
    mem.explorePts = [];
    const step = 55;
    for (let x = step * 0.45; x < mem.sizeX - 12; x += step) {
      for (let y = step * 0.45; y < mem.sizeY - 12; y += step) {
        mem.explorePts.push({ x: x, y: y, done: false });
      }
    }
    if (mem.explorePts.length === 0) {
      mem.explorePts.push({ x: mem.sizeX * 0.5, y: mem.sizeY * 0.5, done: false });
    }
  }

  function chooseExplorePoint() {
    initExplore();
    for (let i = 0; i < mem.explorePts.length; i++) {
      const p = mem.explorePts[i];
      if (!p.done && dist(mem.pos.x, mem.pos.y, p.x, p.y) < 12) p.done = true;
    }
    let best = null, bd = 1e99;
    for (let i = 0; i < mem.explorePts.length; i++) {
      const p = mem.explorePts[i];
      if (p.done) continue;
      const d = dist(mem.pos.x, mem.pos.y, p.x, p.y);
      const dh = dist(p.x, p.y, mem.base.x, mem.base.y);
      const need = (d + dh) / 0.35 + 35;
      if (timeLeft < need) {
        p.done = true;
        continue;
      }
      if (d < bd) {
        bd = d;
        best = p;
      }
    }
    return best;
  }

  function chooseHint() {
    let best = null, bestScore = -1e99;
    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (h.status !== 0) continue;

      const d = dist(mem.pos.x, mem.pos.y, h.x, h.y);
      const dh = dist(h.x, h.y, mem.base.x, mem.base.y);
      const searchCost = 55;
      const need = (d + searchCost + dh) / 0.35 + 55;
      if (timeLeft < need) continue;

      const val = h.val > 0 ? h.val : mem.medValue;
      let score;
      if (mem.totalSamples === 0) {
        score = (val + 1) / (d + 25);
      } else {
        score = Math.sqrt(val + 0.5) / (d + 0.35 * dh + 30);
      }
      if (h.attempts > 0) score *= 0.72;
      if (d < 30) score *= 1.15;

      const energyNeed = 0.03 + (d + dh) * 0.0016 + 0.04;
      if (battery < energyNeed && d > 18) continue;

      if (score > bestScore) {
        bestScore = score;
        best = h;
      }
    }
    return best;
  }

  // Carried changes / deliveries.
  if (c > mem.lastCarried) {
    const added = c - mem.lastCarried;
    mem.totalSamples += added;
    let px = mem.approach ? mem.approach.x : mem.pos.x;
    let py = mem.approach ? mem.approach.y : mem.pos.y;
    markHintSampled(px, py);
    mem.state = "return";
    mem.returnReason = "sample";
    mem.returnStart = t;
    mem.search = null;
    mem.approach = null;
    mem.drillSite = null;
    mem.drillStart = 0;
  } else if (c < mem.lastCarried) {
    const delivered = mem.lastCarried - c;
    mem.totalDelivered += delivered;
    mem.state = "choose";
    mem.returnReason = "";
    mem.chargeStart = t;
    mem.chargeStartBat = battery;
    mem.chargeTarget = Math.min(0.92, Math.max(0.72, battery + 0.22));
  }
  mem.lastCarried = c;

  if (c > 0) {
    if (mem.state !== "return") {
      mem.state = "return";
      mem.returnReason = "sample";
      mem.returnStart = t;
      mem.search = null;
      mem.approach = null;
      mem.drillSite = null;
      mem.drillStart = 0;
    }
  }

  const bumped = !!obs.bumped;
  if (bumped && !mem.prevBumped) {
    mem.recoverUntil = t + 1.15;
    mem.recoverStart = t;
    mem.recoverSide = chooseOpenSide();
    mem.avoidSide = mem.recoverSide;
    mem.avoidUntil = t + 1.0;
    mem.stuckStrikes = 0;

    if (mem.state === "search" && mem.search && mem.search.current) {
      mem.search.current.blockCount = (mem.search.current.blockCount || 0) + 1;
      if (mem.search.current.blockCount >= 2) {
        mem.search.current.visited = true;
        mem.search.current = null;
        mem.search.blocked++;
      }
    }
  }
  mem.prevBumped = bumped;

  // Opportunistically grab a visible site while not returning.
  if (siteO && c === 0 &&
      isFinite(Number(siteO.distance)) && isFinite(Number(siteO.bearing)) &&
      Number(siteO.distance) < 8.5 &&
      mem.state !== "drill" && mem.state !== "return" &&
      mem.state !== "charge" && mem.state !== "approach" &&
      t >= mem.recoverUntil) {
    beginApproach(Number(siteO.distance), Number(siteO.bearing), Number(siteO.value || 0));
  }

  let targetL = 0;
  let targetR = 0;
  let drillCmd = false;

  function setNav(errIn, vWant) {
    let err = wrap(errIn);
    if (!(vWant > 0)) vWant = 0;

    const front = Math.min(clearAt(-25), clearAt(0), clearAt(25));
    let v = vWant;

    if (front < 1.0) v = 0;
    else if (front < 1.8) v = Math.min(v, 0.10);
    else if (front < 2.8) v = Math.min(v, 0.28);

    const absE = Math.abs(err);
    if (absE > 100) v = 0;
    else if (absE > 60) v = Math.min(v, 0.05);
    else if (absE > 30) v = Math.min(v, 0.25);
    else if (absE > 15) v = Math.min(v, 0.50);

    let omega = clamp(err * 0.020, -1.25, 1.25);

    let avoid = 0;
    for (let i = 0; i < 9; i++) {
      const rel = (i - 4) * 20;
      const d = rays[i];
      if (d < 2.2 && Math.abs(rel) >= 10 && Math.abs(rel) <= 70) {
        const away = rel > 0 ? -1 : 1;
        const w = (2.2 - d) / 2.2;
        avoid += away * w * (1 - Math.abs(rel) / 100);
      }
    }
    omega += clamp(avoid * 0.8, -0.6, 0.6);

    if (front < 1.0) {
      if (t > mem.avoidUntil) {
        mem.avoidSide = chooseOpenSide();
        mem.avoidUntil = t + 1.0;
      }
      omega = (mem.avoidSide || 1) * 0.9;
      v = 0;
      err = 0;
    }

    const bf = boundaryClear(0);
    if (bf < 2.5) {
      const inward = angleTo(mem.pos.x, mem.pos.y, mem.sizeX * 0.5, mem.sizeY * 0.5);
      const inErr = wrap(inward - mem.headEst);
      omega = clamp(omega * 0.35 + inErr * 0.035, -1.25, 1.25);
      v = Math.min(v, 0.18);
    }
    if (bf < 1.2) v = 0;

    omega = clamp(omega, -1.3, 1.3);

    let maxW = 0.68;
    if (front < 2.8) maxW = 0.40;
    if (front < 1.5) maxW = 0.25;

    let vl = v - omega * 0.3;
    let vr = v + omega * 0.3;

    targetL = clamp(vl, -maxW, maxW);
    targetR = clamp(vr, -maxW, maxW);
