    if (cNow > 0 && dB < 2.7) {
      targetL = 0;
      targetR = 0;
      drillCmd = false;
    } else if (cNow === 0 && dB < 2.7) {
      targetL = 0;
      targetR = 0;
      drillCmd = false;
      if ((mem.returnReason === "battery" || battery < 0.55) && timeLeft > 120) {
        mem.state = "charge";
        mem.chargeStart = t;
        mem.chargeStartBat = battery;
        mem.chargeTarget = Math.min(0.9, Math.max(0.72, battery + 0.22));
      } else {
        mem.state = "choose";
      }
    } else {
      let err;
      if (beacon && isFinite(Number(beacon.distance)) && isFinite(Number(beacon.bearing)) &&
          Number(beacon.distance) < 20) {
        err = Number(beacon.bearing);
      } else {
        err = wrap(angleTo(mem.pos.x, mem.pos.y, mem.base.x, mem.base.y) - mem.headEst);
      }

      let v = 0.65;
      if (dB < 12) v = 0.45;
      if (dB < 6) v = 0.30;
      if (dB < 4) v = 0.15;
      if (timeLeft < dB / 0.55 + 18) v = 0.72;
      if (battery < 0.15) v = Math.min(v, 0.50);

