    if (!ap) {
      mem.state = "choose";
    } else {
      let vis = false;
      let sd = 1e9;

      if (siteO && isFinite(Number(siteO.distance)) && isFinite(Number(siteO.bearing)) &&
          Number(siteO.distance) < 8.5) {
        vis = true;
        sd = Number(siteO.distance);
        const sb = Number(siteO.bearing);
        const ab = (mem.headEst + sb) * D2R;
        ap.x = mem.pos.x + Math.cos(ab) * sd;
        ap.y = mem.pos.y + Math.sin(ab) * sd;
        ap.value = Number(siteO.value || ap.value || 0);
        ap.lastSeen = t;
      }

      const d = vis ? sd : dist(mem.pos.x, mem.pos.y, ap.x, ap.y);
      const sp = Math.abs(speedActual);

      targetL = 0;
      targetR = 0;

      if (d <= 1.50 && sp < 0.15) {
        drillCmd = true;
      } else {
        drillCmd = false;
      }

      if (d > 1.65 && sp < 0.10) {
        mem.state = "approach";
      } else if (t - mem.drillStart > 15 && c === 0) {
        drillCmd = false;
        ap = mem.approach;
        if (ap && ap.hint && ap.hint.status === 0) ap.hint.status = 2;
        mem.approach = null;
        mem.state = mem.search ? "search" : "choose";
      } else if (!vis && t - ap.lastSeen > 8 && c === 0) {
        drillCmd = false;
        mem.approach = null;
        mem.state = mem.search ? "search" : "choose";
      }
    }
  } else if (mem.state === "approach") {
    let ap = mem.approach;
    if (!ap) {
      mem.state = "choose";
    } else {
      let vis = false;
      let sd = 1e9;
      let sb = 0;

      if (siteO && isFinite(Number(siteO.distance)) && isFinite(Number(siteO.bearing)) &&
          Number(siteO.distance) < 8.5) {
        vis = true;
        sd = Number(siteO.distance);
        sb = Number(siteO.bearing);
        const ab = (mem.headEst + sb) * D2R;
        ap.x = mem.pos.x + Math.cos(ab) * sd;
        ap.y = mem.pos.y + Math.sin(ab) * sd;
        ap.value = Number(siteO.value || ap.value || 0);
        ap.lastSeen = t;
      }

      const d = vis ? sd : dist(mem.pos.x, mem.pos.y, ap.x, ap.y);
      const sp = Math.abs(speedActual);

      if (d <= 1.45 && sp < 0.16) {
        mem.state = "drill";
        mem.drillStart = t;
        mem.drillSite = ap;
        targetL = 0;
        targetR = 0;
        drillCmd = sp < 0.15;
      } else if (d <= 1.55 && sp >= 0.16) {
        targetL = 0;
        targetR = 0;
        drillCmd = false;
      } else {
        const err = vis ? sb : wrap(angleTo(mem.pos.x, mem.pos.y, ap.x, ap.y) - mem.headEst);
        let vWant;
        if (d > 6) vWant = 0.65;
        else if (d > 3) vWant = 0.45;
        else if (d > 2) vWant = 0.28;
