            const d = dist(mem.pos.x, mem.pos.y, p.x, p.y);
            if (d < bd) {
              bd = d;
              bestP = p;
            }
          }
          if (!bestP) {
            if (!s2.extended && (science > 0.15 || s2.sciMax > 0.35) && timeLeft > 150) {
