              s2.maxTime += 45;
              s2.blocked = 0;
              const cx = s2.sciPos.x, cy = s2.sciPos.y;
              const step2 = 6.0;
              for (let gx = -12; gx <= 12.01; gx += step2) {
                for (let gy = -12; gy <= 12.01; gy += step2) {
                  const xx = cx + gx, yy = cy + gy;
                  if (xx < 3 || xx > mem.sizeX - 3 || yy < 3 || yy > mem.sizeY - 3) continue;
                  s2.points.push({ x: xx, y: yy, visited: false, blockCount: 0 });
                }
              }
              s2.current = null;
              s2.curStart = t;
            } else {
              finishSearch(false);
            }
          } else {
            s2.current = bestP;
            s2.curStart = t;
          }
        }

        if (mem.state === "search" && mem.search && mem.search.current) {
          const s3 = mem.search;
          const p = s3.current;
          const d = dist(mem.pos.x, mem.pos.y, p.x, p.y);

          if (d < 1.6) {
            p.visited = true;
            s3.visited++;
            s3.current = null;
            targetL = 0;
            targetR = 0;
          } else if (t - s3.curStart > 14) {
            p.visited = true;
            s3.blocked++;
            s3.current = null;
            targetL = 0;
            targetR = 0;
            if (s3.blocked >= 4) finishSearch(false);
          } else {
            const err = wrap(angleTo(mem.pos.x, mem.pos.y, p.x, p.y) - mem.headEst);
            let vWant = d > 8 ? 0.60 : (d > 4 ? 0.45 : 0.30);
            setNav(err, vWant);
          }
        }
      }
    }
  } else if (mem.state === "gotoHint") {
    const h = mem.targetHint;
    if (!h || h.status !== 0) {
      mem.state = "choose";
    } else {
      const d = dist(mem.pos.x, mem.pos.y, h.x, h.y);
      const dh = dist(h.x, h.y, mem.base.x, mem.base.y);

      if (d < 7.0) {
        startSearch(h);
      } else if (timeLeft < (d + dh) / 0.35 + 65) {
        h.status = 2;
        mem.targetHint = null;
        mem.state = "choose";
      } else {
        const err = wrap(angleTo(mem.pos.x, mem.pos.y, h.x, h.y) - mem.headEst);
        let vWant = 0.64;
        if (d < 22) vWant = 0.52;
        if (d < 12) vWant = 0.40;
        if (d < 8) vWant = 0.30;
        setNav(err, vWant);
      }
    }
  } else if (mem.state === "explore") {
    const p = mem.exploreTarget;
    if (!p || p.done) {
      mem.state = "choose";
    } else {
      const d = dist(mem.pos.x, mem.pos.y, p.x, p.y);
      const dh = dist(p.x, p.y, mem.base.x, mem.base.y);
      if (d < 4.0) {
        p.done = true;
        mem.state = "choose";
      } else if (timeLeft < (d + dh) / 0.35 + 45) {
        p.done = true;
        mem.state = "choose";
      } else {
        const err = wrap(angleTo(mem.pos.x, mem.pos.y, p.x, p.y) - mem.headEst);
        let vWant = 0.62;
        if (d < 12) vWant = 0.42;
        setNav(err, vWant);
      }
    }
  } else if (mem.state === "choose" || !mem.state) {
    targetL = 0;
    targetR = 0;
    drillCmd = false;

    if (c > 0) {
      mem.state = "return";
    } else if (timeLeft < 15) {
      mem.state = "idle";
    } else if (dB < 3.0 && battery < 0.55 && timeLeft > 130) {
      mem.state = "charge";
      mem.chargeStart = t;
      mem.chargeStartBat = battery;
      mem.chargeTarget = Math.min(0.9, Math.max(0.72, battery + 0.22));
    } else if (battery < 0.20 && dB > 15) {
      mem.state = "return";
      mem.returnReason = "battery";
      mem.returnStart = t;
    } else {
      const h = chooseHint();
      if (h) {
        h.attempts++;
        mem.targetHint = h;
        mem.search = null;
        mem.approach = null;
        mem.hintStart = t;
        mem.state = "gotoHint";
      } else {
        const p = chooseExplorePoint();
        if (p) {
          mem.exploreTarget = p;
          mem.targetHint = null;
          mem.search = null;
          mem.approach = null;
          mem.state = "explore";
        } else if (dB > 3.0) {
          mem.state = "return";
          mem.returnReason = "none";
          mem.returnStart = t;
        } else {
          mem.state = "idle";
        }
      }
    }
  } else if (mem.state === "idle") {
    targetL = 0;
    targetR = 0;
    drillCmd = false;
  } else {
    targetL = 0;
    targetR = 0;
    drillCmd = false;
  }

  // Stuck detection: only on commanded motion with too little displacement.
  const movingState = mem.state === "gotoHint" || mem.state === "search" ||
                      mem.state === "approach" || mem.state === "return" ||
                      mem.state === "explore";
  const frontForStuck = Math.min(clearAt(-20), clearAt(0), clearAt(20));
  const cmdMag = Math.max(Math.abs(targetL), Math.abs(targetR));

  if (t - mem.progressT > 2.0) {
    const moved = dist(mem.pos.x, mem.pos.y, mem.progressPos.x, mem.progressPos.y);
    const observed = moved > 0.12 || (mem.gpsFrozen && Math.abs(speedActual) > 0.10);

    if (movingState && cmdMag > 0.12 && t > mem.recoverUntil &&
        frontForStuck > 0.90 && !observed && Math.abs(speedActual) < 0.08) {
      mem.stuckStrikes++;
      if (mem.stuckStrikes >= 1) {
        mem.stuckStrikes = 0;
        mem.stuckTotal++;
        mem.recoverUntil = t + 1.2;
        mem.recoverStart = t;
        mem.recoverSide = chooseOpenSide();
        mem.avoidSide = mem.recoverSide;
        mem.avoidUntil = t + 1.0;

        if (mem.stuckTotal % 3 === 0) {
          if (mem.state === "search" && mem.search && mem.search.current) {
            mem.search.current.visited = true;
            mem.search.current = null;
            mem.search.blocked++;
          } else if (mem.state === "gotoHint" && mem.targetHint) {
            mem.targetHint.status = 2;
            mem.targetHint = null;
            mem.state = "choose";
          } else if (mem.state === "explore" && mem.exploreTarget) {
            mem.exploreTarget.done = true;
            mem.state = "choose";
          }
        }
      }
    } else {
      mem.stuckStrikes = 0;
    }

    mem.progressPos = { x: mem.pos.x, y: mem.pos.y };
    mem.progressT = t;
  }

  // Recovery override: back briefly, then turn toward the clearer side.
  if (t < mem.recoverUntil && mem.state !== "drill") {
    const elapsed = t - mem.recoverStart;
    const side = mem.recoverSide || 1;
    if (elapsed < 0.32) {
      targetL = -0.12;
      targetR = -0.12;
    } else {
      const om = 0.88 * side;
      targetL = -om * 0.3;
      targetR = om * 0.3;
