    if (!isFinite(actual)) actual = 0;

    if (Math.abs(target) < 0.01) {
      let u = -actual * 1.10;
      const pitch = Number(obs.pitch);
      const slope = isFinite(pitch) ? Math.sin(pitch * D2R) : 0;
      u += clamp(slope * 0.06, -0.12, 0.12);
      if (Math.abs(actual) < 0.02 && Math.abs(slope) < 0.02) u = 0;
      return clamp(u, -0.5, 0.5);
    }

    const mpc = mem.mpsPerCmd || 2.2;
    let uff = target / mpc;
    const dz = mem.deadzone || 0.035;
    uff += (target > 0 ? 1 : -1) * dz;

    const err = target - actual;
    let u = uff + err * 0.28;

    if (target * actual < -0.02) u += (target > 0 ? 0.08 : -0.08);

    if (target > 0 && actual > 0.85) u -= (actual - 0.85) * 1.5;
    if (target < 0 && actual < -0.85) u += (-actual - 0.85) * 1.5;

    u = clamp(u, -0.9, 0.9);

    if (Math.abs(u) > 0.12 && Math.abs(actual) > 0.08 && target * u > 0) {
      const ratio = actual / u;
      if (ratio > 0.5 && ratio < 5.0) {
        mem.mpsPerCmd = clamp(mpc * 0.997 + ratio * 0.003, 1.0, 4.0);
      }
    }

    return u;
  }

  let uL = wheelCmd(targetL, wl, 0);
  let uR = wheelCmd(targetR, wr, 1);

  // Absolute low-speed governor: stay well below destructive impact speed.
  let hardCap = 0.85;
  const nearFront = Math.min(clearAt(-15), clearAt(0), clearAt(15));
  if (nearFront < 2.0) hardCap = 0.42;
  if (nearFront < 1.2) hardCap = 0.25;

  if (speedActual > hardCap) {
    const brake = (speedActual - hardCap) * 1.8;
    uL -= brake;
    uR -= brake;
  }
  if (wl > 0.95) uL -= (wl - 0.95) * 1.8;
  if (wr > 0.95) uR -= (wr - 0.95) * 1.8;
  if (wl < -0.75) uL += (-wl - 0.75) * 1.4;
  if (wr < -0.75) uR += (-wr - 0.75) * 1.4;

  function rateLimit(u, prev) {
    if (!isFinite(u)) u = 0;
    if (u > prev) u = Math.min(u, prev + 0.25);
    else if (u < prev) u = Math.max(u, prev - 0.50);
    return u;
  }

  uL = rateLimit(uL, mem.cmdL);
  uR = rateLimit(uR, mem.cmdR);

  uL = clamp(uL, -1, 1);
  uR = clamp(uR, -1, 1);
  if (!isFinite(uL)) uL = 0;
  if (!isFinite(uR)) uR = 0;

  mem.cmdL = uL;
  mem.cmdR = uR;

  return {
    left: uL,
    right: uR,
    drill: !!drillCmd
  };
}

function act(obs, mem) {
