    let sx = m.size, sy = m.size;
    if (sx && typeof sx === "object") {
      sy = Number(sx.y != null ? sx.y : (sx.h != null ? sx.h : 400));
      sx = Number(sx.x != null ? sx.x : (sx.w != null ? sx.w : 400));
    }
    sx = Number(sx); sy = Number(sy);
    if (!(sx > 10)) sx = 400;
    if (!(sy > 10)) sy = 400;
    mem.sizeX = sx;
    mem.sizeY = sy;

    const mb = m.base || {};
    mem.base = {
      x: isFinite(Number(mb.x)) ? Number(mb.x) : (Number(obs.x) || 200),
      y: isFinite(Number(mb.y)) ? Number(mb.y) : (Number(obs.y) || 200)
    };
    if (!isFinite(mem.base.x)) mem.base.x = 0;
    if (!isFinite(mem.base.y)) mem.base.y = 0;

    mem.capacity = Number(m.capacity || 5);
    if (!(mem.capacity >= 1)) mem.capacity = 5;
    mem.seconds = Number(m.seconds || 1200);
    if (!(mem.seconds > 0)) mem.seconds = 1200;

    mem.hints = [];
    const hs = m.hints || [];
    for (let i = 0; i < hs.length; i++) {
      const h = hs[i] || {};
      const hx = Number(h.x), hy = Number(h.y);
      let hv = Number(h.estimate);
      if (!isFinite(hx) || !isFinite(hy)) continue;
      if (!isFinite(hv) || hv < 0) hv = 1;
      mem.hints.push({
        id: mem.hints.length,
        x: hx, y: hy, val: hv,
        status: 0, attempts: 0
      });
    }

    let px = Number(obs.x), py = Number(obs.y);
    if (!isFinite(px)) px = mem.base.x;
    if (!isFinite(py)) py = mem.base.y;
    mem.pos = { x: px, y: py };
    mem.lastRawPos = { x: px, y: py };
    mem.freezeTimer = 0;
    mem.gpsFrozen = false;

    let rh = Number(obs.heading);
    if (!isFinite(rh)) rh = 0;
    mem.head = rh;
    mem.lastRawH = rh;

    mem.mode = "choose";
    mem.targetHint = null;
    mem.search = null;
    mem.approach = null;
    mem.explorePts = null;
    mem.exploreTarget = null;

    mem.lastCarried = countCarried(obs);
    mem.lastDeliveredVal = Number(obs.delivered);
    if (!isFinite(mem.lastDeliveredVal)) mem.lastDeliveredVal = 0;
    mem.totalSamples = 0;
    mem.totalDelivered = 0;

    mem.drillStart = 0;
    mem.arriveBaseT = 0;
    mem.chargeStart = 0;
    mem.chargeStartBat = 0;
    mem.chargeTarget = 0.75;

    mem.prevBumped = false;
    mem.recoverUntil = -1;
    mem.recoverStart = -1;
    mem.recoverSide = 1;
    mem.lastRecoveryT = -100;
    mem.stuckStrikes = 0;
    mem.progressT = t;
    mem.progressPos = { x: px, y: py };
    mem.lastWantSpeed = 0;

    mem.ignoreRaysUntil = -1;
    mem.lowClearStart = 0;

    mem.targetL = 0;
    mem.targetR = 0;
    mem.wheelL = { u: 0, i: 0, gain: 1.5, dz: 0.045, lastU: 0 };
    mem.wheelR = { u: 0, i: 0, gain: 1.5, dz: 0.045, lastU: 0 };

    mem.lastT = t;
    mem.lastBattery = Number(obs.battery);
    if (!isFinite(mem.lastBattery)) mem.lastBattery = 1;
  }

  let dt = 0.1;
  if (mem.lastT != null) {
    const dd = t - mem.lastT;
    if (dd > 0.001 && dd < 1.0) dt = dd;
  }
  mem.lastT = t;

  let wl = Number(obs.wheelLeft);
  let wr = Number(obs.wheelRight);
  if (!isFinite(wl)) wl = 0;
  if (!isFinite(wr)) wr = 0;
  const vAvg = (wl + wr) / 2;
  const speedAbs = Math.abs(vAvg);

  let battery = Number(obs.battery);
  if (!isFinite(battery)) battery = 1;

  let timeLeft = Number(obs.timeLeft);
  if (!isFinite(timeLeft)) timeLeft = mem.seconds - t;
  if (timeLeft < 0) timeLeft = 0;

  let science = Number(obs.science);
  if (!isFinite(science)) science = 0;

  let c = countCarried(obs);

  const siteO = obs.site || null;
  const beacon = obs.beacon || null;

  let rawH = Number(obs.heading);
  if (!isFinite(rawH)) rawH = mem.lastRawH;

  let rawX = Number(obs.x), rawY = Number(obs.y);
  if (!isFinite(rawX)) rawX = mem.lastRawPos.x;
  if (!isFinite(rawY)) rawY = mem.lastRawPos.y;

  const rawMoved = dist(rawX, rawY, mem.lastRawPos.x, mem.lastRawPos.y);

  if (Math.abs(vAvg) > 0.12 && rawMoved < 0.006) mem.freezeTimer += dt;
  else if (rawMoved > 0.02) mem.freezeTimer = 0;

  if (mem.freezeTimer > 1.8) mem.gpsFrozen = true;
  if (mem.gpsFrozen && rawMoved > 0.06) {
    mem.gpsFrozen = false;
    mem.freezeTimer = 0;
  }

  const predX = mem.pos.x + vAvg * Math.cos(mem.head * D2R) * dt;
  const predY = mem.pos.y + vAvg * Math.sin(mem.head * D2R) * dt;

  if (mem.gpsFrozen) {
    mem.pos.x = predX;
    mem.pos.y = predY;
  } else {
    const dp = dist(rawX, rawY, predX, predY);
    let a = 0.55;
    if (dp > 12) a = 0.10;
    else if (dp > 5) a = 0.25;
    mem.pos.x = mem.pos.x * (1 - a) + rawX * a;
    mem.pos.y = mem.pos.y * (1 - a) + rawY * a;
  }
  if (!isFinite(mem.pos.x)) mem.pos.x = predX;
  if (!isFinite(mem.pos.y)) mem.pos.y = predY;
  mem.lastRawPos = { x: rawX, y: rawY };

  const wheelYaw = ((wr - wl) / 0.6) * dt * R2D;
  const predHead = wrap(mem.head + wheelYaw);
  const dRaw = wrap(rawH - predHead);
  if (Math.abs(wl) + Math.abs(wr) < 0.04) {
    mem.head = wrap(mem.head + wrap(rawH - mem.head) * 0.55);
  } else if (Math.abs(dRaw) < 35) {
    mem.head = wrap(predHead + dRaw * 0.45);
  } else if (Math.abs(dRaw) > 70 && Math.abs(wl) + Math.abs(wr) < 0.12) {
    mem.head = rawH;
  } else {
    mem.head = predHead;
  }
  mem.lastRawH = rawH;

  const rays = [15, 15, 15, 15, 15, 15, 15, 15, 15];
  if (obs.rays && obs.rays.length) {
    for (let i = 0; i < 9; i++) {
      let v = Number(obs.rays[i]);
      if (!isFinite(v) || v < 0) v = 15;
      if (v > 15) v = 15;
      if (v < 0.02) v = 0.02;
      rays[i] = v;
    }
  }

  function rayAt(rel) {
    if (t < mem.ignoreRaysUntil) return 15;
    const a = clamp(rel, -80, 80);
    const idx = (a + 80) / 20;
    let i = Math.floor(idx);
    if (i < 0) i = 0;
    if (i > 7) i = 7;
    let f = idx - i;
    if (f < 0) f = 0;
    if (f > 1) f = 1;
    let d1 = rays[i], d2 = rays[i + 1];
    if (!isFinite(d1)) d1 = 15;
    if (!isFinite(d2)) d2 = 15;
    return d1 * (1 - f) + d2 * f;
  }

  function boundaryClear(rel) {
    const ang = (mem.head + rel) * D2R;
    const dx = Math.cos(ang), dy = Math.sin(ang);
    const margin = 1.8;
    let tx = 1e9, ty = 1e9;
    if (dx > 0.000001) tx = (mem.sizeX - margin - mem.pos.x) / dx;
    else if (dx < -0.000001) tx = (margin - mem.pos.x) / dx;
    if (dy > 0.000001) ty = (mem.sizeY - margin - mem.pos.y) / dy;
    else if (dy < -0.000001) ty = (margin - mem.pos.y) / dy;
    let d = 1e9;
    if (tx > 0) d = Math.min(d, tx);
    if (ty > 0) d = Math.min(d, ty);
    if (!(d > 0)) d = 0;
    return Math.min(d, 15);
  }

  function frontClear() {
    let fc = 15;
    fc = Math.min(fc, rayAt(-30), rayAt(-18), rayAt(0), rayAt(18), rayAt(30));
    fc = Math.min(fc, boundaryClear(-20), boundaryClear(0), boundaryClear(20));
    return fc;
  }

  function chooseAvoidSide() {
    let left = 0, right = 0;
    for (let i = 0; i < 9; i++) {
      const rel = (i - 4) * 20;
      let d = rayAt(rel);
      if (d > 8) d = 8;
      if (rel > 0) left += d;
      else if (rel < 0) right += d;
    }
    if (Math.abs(left - right) < 0.25) return mem.recoverSide || 1;
    return left >= right ? 1 : -1;
  }

  function setDrive(v, omega) {
    v = clamp(v, -0.40, 0.40);
    omega = clamp(omega, -1.0, 1.0);
    let vl = v - omega * 0.30;
    let vr = v + omega * 0.30;
    mem.targetL = clamp(vl, -0.45, 0.45);
    mem.targetR = clamp(vr, -0.45, 0.45);
  }

  function drivePoint(tx, ty, maxV) {
    const dx = tx - mem.pos.x, dy = ty - mem.pos.y;
    const d = Math.sqrt(dx * dx + dy * dy);
    if (d < 0.05) {
      setDrive(0, 0);
      return d;
    }

    const err = wrap(angleTo(mem.pos.x, mem.pos.y, tx, ty) - mem.head);
    const absErr = Math.abs(err);
    let desired = maxV;

    if (d < 2.0) desired *= clamp(d / 2.0, 0.18, 1.0);
    else if (d < 5.0) desired *= 0.65;

    if (absErr > 70) desired = 0;
    else if (absErr > 45) desired = Math.min(desired, 0.08);
    else if (absErr > 25) desired = Math.min(desired, 0.18);
    else if (absErr > 12) desired = Math.min(desired, 0.30);

    const fc = frontClear();
    if (fc < 1.0) desired = 0;
    else if (fc < 1.6) desired = Math.min(desired, 0.07);
    else if (fc < 2.5) desired = Math.min(desired, 0.18);
    else if (fc < 4.0) desired = Math.min(desired, 0.30);

    let omega = clamp(err * 0.024, -0.90, 0.90);

    let avoid = 0;
    for (let i = 0; i < 9; i++) {
      const rel = (i - 4) * 20;
      const dRay = rayAt(rel);
      if (dRay < 2.2 && Math.abs(rel) > 8) {
        const away = rel > 0 ? -1 : 1;
        const w = (2.2 - dRay) / 2.2;
        avoid += away * w * (1 - Math.abs(rel) / 120);
      }
    }
    omega += clamp(avoid * 0.85, -0.75, 0.75);

    if (desired < 0.025 && absErr > 18) {
      omega = (err >= 0 ? 1 : -1) * 0.55;
    }

    const bc = boundaryClear(0);
    if (bc < 1.4) {
      const inward = wrap(angleTo(mem.pos.x, mem.pos.y, mem.sizeX * 0.5, mem.sizeY * 0.5) - mem.head);
      omega = clamp(omega * 0.25 + inward * 0.020, -0.9, 0.9);
      desired = Math.min(desired, 0.08);
    }
    if (fc < 0.95) {
      desired = 0;
      omega = chooseAvoidSide() * 0.65;
    }

    setDrive(desired, omega);
    return d;
  }

  function driveRelative(errIn, d, maxV) {
    const err = wrap(errIn);
    const absErr = Math.abs(err);
    let desired = maxV;

    if (d < 2.0) desired *= clamp((d - 0.8) / 1.2, 0.10, 1.0);
    else if (d < 5.0) desired *= 0.70;

    if (absErr > 70) desired = 0;
    else if (absErr > 45) desired = Math.min(desired, 0.07);
    else if (absErr > 25) desired = Math.min(desired, 0.16);
    else if (absErr > 12) desired = Math.min(desired, 0.27);

    const fc = frontClear();
    if (fc < 1.0) desired = 0;
    else if (fc < 1.6) desired = Math.min(desired, 0.06);
    else if (fc < 2.5) desired = Math.min(desired, 0.17);
    else if (fc < 4.0) desired = Math.min(desired, 0.28);

    let omega = clamp(err * 0.024, -0.85, 0.85);

    if (desired < 0.025 && absErr > 18) {
      omega = (err >= 0 ? 1 : -1) * 0.50;
    }

    if (fc < 0.95) {
      desired = 0;
      omega = chooseAvoidSide() * 0.60;
    }

    setDrive(desired, omega);
  }

  function chooseHint() {
    let best = null, bestScore = -1e99;
    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (h.status !== 0) continue;

      const d = dist(mem.pos.x, mem.pos.y, h.x, h.y);
      const dh = dist(h.x, h.y, mem.base.x, mem.base.y);
      const searchCost = h.attempts > 0 ? 130 : 175;
      const estTime = (d + dh) / 0.38 + searchCost + 35;
      if (timeLeft < estTime + 15) continue;

      const val = h.val > 0 ? h.val : 1;
      let score;
      if (mem.totalSamples === 0) {
        score = 1.0 / (d + 18) * (1 + 0.12 * Math.min(val, 6));
      } else {
        score = (val + 0.5) / (d + 0.35 * dh + 35 + 0.4 * searchCost);
      }
      if (h.attempts > 0) score *= 0.72;
      if (timeLeft < 420) score *= 1.0 / (1 + dh / 220);

      if (score > bestScore) {
        bestScore = score;
        best = h;
      }
    }
    return best;
  }

  function initExplore() {
    if (mem.explorePts) return;
    mem.explorePts = [];
    const step = 55;
    for (let x = 25; x < mem.sizeX - 15; x += step) {
      for (let y = 25; y < mem.sizeY - 15; y += step) {
        mem.explorePts.push({ x: x, y: y, done: false });
      }
    }
    if (mem.explorePts.length === 0) {
      mem.explorePts.push({ x: mem.sizeX / 2, y: mem.sizeY / 2, done: false });
    }
  }

  function chooseExplore() {
    initExplore();
    for (let i = 0; i < mem.explorePts.length; i++) {
      const p = mem.explorePts[i];
      if (!p.done && dist(mem.pos.x, mem.pos.y, p.x, p.y) < 11) p.done = true;
    }
    let best = null, bestD = 1e99;
    for (let i = 0; i < mem.explorePts.length; i++) {
      const p = mem.explorePts[i];
      if (p.done) continue;
      const d = dist(mem.pos.x, mem.pos.y, p.x, p.y);
      const dh = dist(p.x, p.y, mem.base.x, mem.base.y);
      if (timeLeft < (d + dh) / 0.38 + 50) {
        p.done = true;
        continue;
      }
      if (d < bestD) {
        bestD = d;
        best = p;
      }
    }
    return best;
  }

  function startSearch(h) {
    let R = 20, step = 10;
    if (timeLeft < 320) { R = 16; step = 8; }
    if (timeLeft < 180) { R = 13; step = 7; }

    const pts = [];
    for (let gy = -R; gy <= R + 0.01; gy += step) {
      for (let gx = -R; gx <= R + 0.01; gx += step) {
        if (gx * gx + gy * gy <= R * R + 0.1) {
          const px = h.x + gx;
          const py = h.y + gy;
          if (px > 3 && px < mem.sizeX - 3 && py > 3 && py < mem.sizeY - 3) {
            pts.push({ x: px, y: py, visited: false });
          }
        }
      }
    }
    if (pts.length === 0) {
      pts.push({
        x: clamp(h.x, 3, mem.sizeX - 3),
        y: clamp(h.y, 3, mem.sizeY - 3),
        visited: false
      });
    }

    mem.search = {
      h: h,
      points: pts,
      start: t,
      maxTime: Math.min(260, 75 + pts.length * 11),
      current: null,
      curStart: t,
      blocked: 0,
      visited: 0,
      small: R < 20
    };
    mem.targetHint = h;
    mem.mode = "search";
    mem.approach = null;
    mem.drillStart = 0;
    mem.stuckStrikes = 0;
  }

  function finishSearch(ok) {
    if (mem.search && mem.search.h && mem.search.h.status === 0) {
      mem.search.h.status = ok ? 1 : 2;
    }
    mem.search = null;
    mem.targetHint = null;
    mem.approach = null;
    mem.drillStart = 0;
    mem.mode = "choose";
  }

  function failApproach() {
    if (mem.targetHint && mem.targetHint.status === 0) mem.targetHint.status = 2;
    if (mem.search && mem.search.h && mem.search.h.status === 0) mem.search.h.status = 2;
    mem.search = null;
    mem.approach = null;
    mem.drillStart = 0;
    mem.mode = "choose";
  }

  function failCurrentTarget() {
    if (mem.mode === "gotoHint" && mem.targetHint) {
      mem.targetHint.status = 2;
      mem.targetHint = null;
      mem.mode = "choose";
    } else if (mem.mode === "search" && mem.search) {
      if (mem.search.current) {
        mem.search.current.visited = true;
        mem.search.current = null;
      }
      mem.search.blocked = (mem.search.blocked || 0) + 1;
      if (mem.search.blocked >= 5) finishSearch(false);
    } else if (mem.mode === "approach") {
      failApproach();
    } else if (mem.mode === "explore") {
      if (mem.exploreTarget) mem.exploreTarget.done = true;
      mem.mode = "choose";
    }
  }

  function startRecovery() {
    mem.recoverStart = t;
    mem.recoverUntil = t + 1.35;
    mem.recoverSide = chooseAvoidSide();
    mem.lastRecoveryT = t;
  }

  let db = dist(mem.pos.x, mem.pos.y, mem.base.x, mem.base.y);
  if (beacon && isFinite(Number(beacon.distance)) && Number(beacon.distance) < 25) {
    db = Math.min(db, Number(beacon.distance));
  }

  // Update heading estimate using the beacon when it is visible.
  if (beacon && isFinite(Number(beacon.distance)) && isFinite(Number(beacon.bearing))) {
    const bd0 = Number(beacon.distance);
    const bb0 = Number(beacon.bearing);
    if (bd0 > 2.0 && bd0 < 20) {
      const trueAng = angleTo(mem.pos.x, mem.pos.y, mem.base.x, mem.base.y);
      const hb = wrap(trueAng - bb0);
      const dh = wrap(hb - mem.head);
      if (Math.abs(dh) < 45) mem.head = wrap(mem.head + dh * 0.035);
    }
  }

  let siteValid = false;
  let siteD = 1e9, siteB = 0, siteV = 0;
  if (siteO && isFinite(Number(siteO.distance)) && isFinite(Number(siteO.bearing))) {
    siteD = Number(siteO.distance);
    siteB = Number(siteO.bearing);
    siteV = Number(siteO.value);
    if (!isFinite(siteV)) siteV = 0;
    if (siteD >= 0 && siteD < 8.5) siteValid = true;
  }

  // Carried-sample and delivery bookkeeping.
  if (c > mem.lastCarried) {
    const added = c - mem.lastCarried;
    mem.totalSamples += added;
    if (mem.targetHint && mem.targetHint.status === 0) mem.targetHint.status = 1;
    if (mem.search && mem.search.h && mem.search.h.status === 0) mem.search.h.status = 1;
    mem.mode = "return";
    mem.search = null;
    mem.approach = null;
    mem.targetHint = null;
    mem.drillStart = 0;
    mem.arriveBaseT = 0;
  } else if (c < mem.lastCarried) {
    const delivered = mem.lastCarried - c;
    if (delivered > 0) mem.totalDelivered += delivered;
    mem.mode = "choose";
    mem.search = null;
    mem.approach = null;
    mem.targetHint = null;
    mem.drillStart = 0;
    mem.arriveBaseT = 0;
  }
  mem.lastCarried = c;

  if (c > 0 && mem.mode !== "return" && mem.mode !== "drill" && mem.mode !== "charge") {
    mem.mode = "return";
    mem.search = null;
    mem.approach = null;
    mem.targetHint = null;
    mem.drillStart = 0;
    mem.arriveBaseT = 0;
  }

  const bumped = !!obs.bumped;
  if (bumped && !mem.prevBumped) {
    if (mem.mode !== "drill" && mem.mode !== "charge") {
      startRecovery();
      mem.stuckStrikes++;
      if (mem.stuckStrikes >= 4) {
        mem.stuckStrikes = 0;
        failCurrentTarget();
      }
    }
  }
  mem.prevBumped = bumped;

  // Low-clearance sensor fault escape.
  const fcNow = frontClear();
  if (fcNow < 0.55 && t > mem.recoverUntil && mem.mode !== "drill") {
    if (!mem.lowClearStart) mem.lowClearStart = t;
    if (t - mem.lowClearStart > 5.5) {
      mem.ignoreRaysUntil = t + 3.5;
      mem.lowClearStart = 0;
      startRecovery();
    }
  } else if (fcNow > 0.9) {
    mem.lowClearStart = 0;
  }

  // Stuck detection based on previous commanded motion.
  if (t - mem.progressT > 2.0) {
    const moved = dist(mem.pos.x, mem.pos.y, mem.progressPos.x, mem.progressPos.y);
    const movingMode = (mem.mode === "gotoHint" || mem.mode === "search" ||
                        mem.mode === "approach" || mem.mode === "return" ||
                        mem.mode === "explore");
    const cmd = mem.lastWantSpeed || 0;
    const av = Math.abs(vAvg);

    if (movingMode && t > mem.recoverUntil && cmd > 0.08 &&
        ((moved < 0.12 && av < 0.06) || (moved < 0.05 && av > 0.18))) {
      mem.stuckStrikes++;
      startRecovery();
      if (mem.stuckStrikes >= 3) {
        mem.stuckStrikes = 0;
        failCurrentTarget();
      }
    } else {
      mem.stuckStrikes = Math.max(0, mem.stuckStrikes - 0.35);
    }

    mem.progressT = t;
    mem.progressPos = { x: mem.pos.x, y: mem.pos.y };
  }

  // Opportunistically chase any visible site when not returning or charging.
  if (siteValid && c < mem.capacity &&
      mem.mode !== "return" && mem.mode !== "charge" && mem.mode !== "idle" &&
      mem.mode !== "drill") {
    if (mem.mode !== "approach" || !mem.approach) {
      const ang = (mem.head + siteB) * D2R;
      const sx = mem.pos.x + Math.cos(ang) * siteD;
      const sy = mem.pos.y + Math.sin(ang) * siteD;
      mem.approach = {
        x: sx, y: sy, value: siteV,
        start: t, lastSeen: t,
        hint: mem.targetHint || null,
        fromMode: mem.mode
      };
      mem.mode = "approach";
      mem.drillStart = 0;
    }
  }

  let drillCmd = false;
  mem.targetL = 0;
  mem.targetR = 0;

  if (mem.mode === "choose") {
    setDrive(0, 0);

    if (c > 0) {
      mem.mode = "return";
    } else if (timeLeft < 22) {
      mem.mode = "idle";
    } else if (db < 3.0 && battery < 0.52 && timeLeft > 120) {
      mem.mode = "charge";
      mem.chargeStart = t;
      mem.chargeStartBat = battery;
      mem.chargeTarget = Math.min(0.92, Math.max(0.72, battery + 0.24));
    } else if (battery < 0.16 && db > 12) {
