  if (wr > 0.82) uR = Math.min(uR, -0.48);
  if (wl < -0.82) uL = Math.max(uL, 0.48);
  if (wr < -0.82) uR = Math.max(uR, 0.48);

  if (vAvg > 0.68) {
    uL = Math.min(uL, -0.18);
    uR = Math.min(uR, -0.18);
  } else if (vAvg < -0.68) {
