    const a = mem.gpsHist[0];
    const b = mem.gpsHist[mem.gpsHist.length - 1];
    const gd = dist(a.x, a.y, b.x, b.y);
    const gt = b.t - a.t;
    if (gd > 2.0 && gt > 1.5) {
      let sxh = 0, syh = 0;
      for (let i = 0; i < mem.gpsHist.length; i++) {
        const hh = mem.gpsHist[i].h * D2R;
        sxh += Math.cos(hh);
        syh += Math.sin(hh);
      }
      const meanRaw = Math.atan2(syh, sxh) * R2D;
      const course = angleTo(a.x, a.y, b.x, b.y);
      const bObs = wrap(meanRaw - course);
      const bd2 = wrap(bObs - mem.headBias);
      if (Math.abs(bd2) < 38) mem.headBias = wrap(mem.headBias + bd2 * 0.012);
    }
  }

  const rays = [15, 15, 15, 15, 15, 15, 15, 15, 15];
  if (obs.rays && obs.rays.length) {
    for (let i = 0; i < 9; i++) {
      let v = Number(obs.rays[i]);
      if (!isFinite(v) || v < 0.02) v = 15;
      if (v > 15) v = 15;
      rays[i] = v;
    }
  }

  const rawFront = Math.min(rays[2], rays[3], rays[4], rays[5], rays[6]);
  if (rawFront < 0.62) {
    if (!mem.lowClearStart) mem.lowClearStart = t;
    else if (t - mem.lowClearStart > 5.5) {
      mem.ignoreRaysUntil = t + 3.0;
      mem.lowClearStart = t;
    }
  } else {
    mem.lowClearStart = 0;
  }
  const ignoreRays = (t < (mem.ignoreRaysUntil || -1));

  function boundaryClear(rel) {
    const ang = (mem.head + rel) * D2R;
    const dx = Math.cos(ang), dy = Math.sin(ang);
    const margin = 1.8;
    let tx = 1e9, ty = 1e9;
    if (dx > 1e-6) tx = (mem.sizeX - margin - mem.pos.x) / dx;
    else if (dx < -1e-6) tx = (margin - mem.pos.x) / dx;
    if (dy > 1e-6) ty = (mem.sizeY - margin - mem.pos.y) / dy;
    else if (dy < -1e-6) ty = (margin - mem.pos.y) / dy;
    let d = 1e9;
    if (tx > 0) d = Math.min(d, tx);
    if (ty > 0) d = Math.min(d, ty);
    if (!(d > 0)) d = 0;
    return Math.min(d, 15);
  }

  function frontClear() {
    let d = Math.min(
      boundaryClear(-35), boundaryClear(-20), boundaryClear(0),
      boundaryClear(20), boundaryClear(35)
    );
    if (!ignoreRays) {
      d = Math.min(d, rays[2], rays[3], rays[4], rays[5], rays[6]);
    }
    return d;
  }

  function chooseSide() {
    let left = 0, right = 0;
    for (let i = 0; i < 9; i++) {
      const rel = (i - 4) * 20;
      let d = rays[i];
      if (!isFinite(d)) d = 15;
      if (rel > 0) left += Math.min(d, 8);
      else if (rel < 0) right += Math.min(d, 8);
    }
    left += Math.min(boundaryClear(90), 8) * 1.6;
    right += Math.min(boundaryClear(-90), 8) * 1.6;
    let side;
    if (Math.abs(left - right) < 0.35) side = mem.lastSide || 1;
    else side = left >= right ? 1 : -1;
    mem.lastSide = side;
    return side;
  }

  function obstacleAvoid() {
    if (ignoreRays) return 0;
    let av = 0;
    for (let i = 0; i < 9; i++) {
      const rel = (i - 4) * 20;
      const d = rays[i];
      if (d < 2.7 && rel >= -65 && rel <= 65) {
        const w = (2.7 - d) / 2.7;
        if (rel > 8) av -= w * 0.85;
        else if (rel < -8) av += w * 0.85;
        else if (d < 2.0) av += chooseSide() * w * 0.65;
      }
    }
    return clamp(av, -1.15, 1.15);
  }

  function setDrive(v, omega) {
    v = clamp(Number(v), -0.62, 0.62);
    if (!isFinite(v)) v = 0;
    omega = clamp(Number(omega), -1.05, 1.05);
    if (!isFinite(omega)) omega = 0;
    let l = v - omega * 0.30;
    let r = v + omega * 0.30;
    wantL = clamp(l, -0.58, 0.58);
    wantR = clamp(r, -0.58, 0.58);
  }

  let wantL = 0, wantR = 0, drillCmd = false;

  function driveErr(errIn, d, vmax) {
    let err = wrap(errIn);
    const absE = Math.abs(err);
    let v = vmax;
    if (!(v > 0)) v = 0;

    if (absE > 110) v = 0;
    else if (absE > 70) v = Math.min(v, 0.055);
    else if (absE > 40) v = Math.min(v, 0.14);
    else if (absE > 22) v = Math.min(v, 0.26);

    if (d < 2.2) v *= clamp((d - 0.35) / 1.85, 0.18, 1.0);
    else if (d < 5.0) v *= 0.82;

    let omega;
    if (absE > 100) omega = (err >= 0 ? 1 : -1) * 0.72;
    else if (absE > 60) omega = (err >= 0 ? 1 : -1) * 0.62;
    else if (absE > 30) omega = clamp(err * 0.030, -0.72, 0.72);
    else omega = clamp(err * 0.036, -0.66, 0.66);

    const fc = frontClear();
    if (fc < 3.0) v *= clamp((fc - 0.55) / 2.45, 0, 1);
    if (fc < 1.05 && absE < 105) {
      v = 0;
      omega = chooseSide() * 0.78;
    } else if (fc < 1.8) {
      omega = clamp(omega + chooseSide() * ((1.8 - fc) / 1.8) * 0.62, -1.0, 1.0);
      v = Math.min(v, 0.12);
    }

    omega += obstacleAvoid();

    const bd = Math.min(mem.pos.x, mem.sizeX - mem.pos.x, mem.pos.y, mem.sizeY - mem.pos.y);
    if (bd < 4.0) {
      const inward = angleTo(mem.pos.x, mem.pos.y, mem.sizeX * 0.5, mem.sizeY * 0.5);
      const inErr = wrap(inward - mem.head);
      omega = clamp(omega * 0.55 + inErr * 0.020, -1.0, 1.0);
      v = Math.min(v, 0.14 + Math.max(0, (bd - 1.0) / 3.0) * 0.22);
    }

    if (!(v > 0)) v = 0;
    if (v > 0.60) v = 0.60;
    setDrive(v, omega);
  }

  function driveToPoint(tx, ty, vmax) {
    const d = dist(mem.pos.x, mem.pos.y, tx, ty);
    const ang = angleTo(mem.pos.x, mem.pos.y, tx, ty);
    const err = wrap(ang - mem.head);
    let v = vmax;
    if (d < 2.5) v *= clamp((d - 0.25) / 2.25, 0.20, 1.0);
    driveErr(err, d, v);
    return d;
  }

  function startApproach(sd, sb, sv) {
    const aa = (mem.head + sb) * D2R;
    mem.approach = {
      x: mem.pos.x + Math.cos(aa) * sd,
      y: mem.pos.y + Math.sin(aa) * sd,
      d: sd, value: sv, start: t, lastSeen: t
    };
    mem.state = "approach";
    mem.drillStart = 0;
  }

  function startSearch(h) {
    const dx = mem.pos.x - h.x, dy = mem.pos.y - h.y;
    let a0 = Math.atan2(dy, dx);
    if (dist(mem.pos.x, mem.pos.y, h.x, h.y) < 1.0) a0 = mem.head * D2R;
    mem.search = {
      h: h,
      radius: 8.5,
      n: 12,
      idx: 0,
      phase: 0,
      angle0: a0,
      phaseStart: t,
      phaseTime: 175,
      current: null,
      curStart: t,
      sciMax: science,
      blocked: 0
    };
    mem.curHint = h;
    mem.approach = null;
    mem.drillStart = 0;
    mem.state = "search";
  }

  function failSearch() {
    if (mem.search && mem.search.h && mem.search.h.status === 0) {
      mem.search.h.status = 2;
    }
    mem.search = null;
    mem.curHint = null;
    mem.approach = null;
    mem.drillStart = 0;
    mem.state = "choose";
  }

  function failApproach() {
    mem.approach = null;
    mem.drillStart = 0;
    if (mem.search) mem.state = "search";
    else if (mem.curHint && mem.curHint.status === 0) mem.state = "goto";
    else mem.state = "choose";
  }

  function markSampleSuccess() {
    let best = null, bd = 50;
    if (mem.curHint && mem.curHint.status === 0) {
      const d = dist(mem.pos.x, mem.pos.y, mem.curHint.x, mem.curHint.y);
      if (d < 22) {
        best = mem.curHint;
        bd = d;
      }
    }
    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (h.status !== 0) continue;
      const d = dist(mem.pos.x, mem.pos.y, h.x, h.y);
      if (d < bd) {
        bd = d;
        best = h;
      }
    }
    if (best && best.status === 0) best.status = 1;
    mem.curHint = null;
    mem.search = null;
    mem.approach = null;
  }

  function chooseHint() {
    let best = null, bestScore = -1e99;
    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (h.status !== 0) continue;

      const d = dist(mem.pos.x, mem.pos.y, h.x, h.y);
      const dh = dist(h.x, h.y, mem.base.x, mem.base.y);
      const val = h.val > 0 ? h.val : 1;

      if (battery < 0.09 && d > 20) continue;

      if (mem.totalDeliveredSamples === 0) {
        if (timeLeft < d / 0.32 + 75) continue;
      } else {
        if (timeLeft < (d + 0.55 * dh + 30) / 0.32 + 115) continue;
      }

      let score;
      if (mem.totalDeliveredSamples === 0) {
        score = 1.0 / (14 + d + 0.22 * dh);
        score *= (1 + Math.min(val, 6) * 0.045);
      } else {
        score = (val + 0.5) / (20 + d + 0.28 * dh + 38);
      }
      if (h.attempts > 0) score *= 0.58;
      if (timeLeft < 300) score *= 1.0 / (1.0 + dh / 260);

      if (score > bestScore) {
        bestScore = score;
        best = h;
      }
    }
    return best;
  }

  // Sample acquisition / delivery bookkeeping
  if (c > mem.lastCarried) {
    const added = c - mem.lastCarried;
    mem.sampleCount += added;
    markSampleSuccess();
    mem.state = "return";
    mem.curHint = null;
    mem.search = null;
    mem.approach = null;
    mem.drillStart = 0;
    mem.dockStart = 0;
  } else if (c < mem.lastCarried) {
    const delivered = mem.lastCarried - c;
    if (delivered > 0) mem.totalDeliveredSamples += delivered;
    mem.state = "choose";
    mem.curHint = null;
    mem.search = null;
    mem.approach = null;
    mem.drillStart = 0;
    mem.dockStart = 0;
    mem.chargeStart = 0;
  }
  mem.lastCarried = c;

  if (c > 0 && mem.state !== "return" && mem.state !== "charge" && mem.state !== "drill") {
    mem.state = "return";
    mem.curHint = null;
    mem.search = null;
    mem.approach = null;
    mem.drillStart = 0;
    mem.dockStart = 0;
  }

  const bumped = !!obs.bumped;
  if (bumped && !mem.prevBumped) {
    mem.bumpCount++;
    if (mem.state !== "charge" && !(c > 0 && distToBase < 2.6)) {
      mem.recoverStart = t;
      mem.recoverUntil = t + 1.4;
      mem.recoverSide = chooseSide();
      if (mem.state === "search" && mem.search) {
        mem.search.current = null;
        mem.search.idx++;
        mem.search.blocked++;
      }
      if (mem.state === "approach" && mem.bumpCount >= 5) {
        failApproach();
      }
    }
  }
  mem.prevBumped = bumped;

  // Stuck detection
  if (t - mem.progressT > 2.2) {
    const moved = dist(mem.pos.x, mem.pos.y, mem.progressPos.x, mem.progressPos.y);
    const movingState =
      mem.state === "goto" || mem.state === "search" ||
      mem.state === "approach" || mem.state === "return" ||
      mem.state === "choose";
    const cmd = mem.lastCmdMag || 0;

    if (movingState && t > mem.recoverUntil && cmd > 0.08 &&
        (Math.abs(vAvg) > 0.035 || Math.abs(wl) + Math.abs(wr) > 0.10) &&
        moved < 0.12) {
      mem.stuckCount++;
      mem.recoverStart = t;
      mem.recoverUntil = t + 1.25;
      mem.recoverSide = chooseSide();

      if (mem.state === "search" && mem.search && mem.search.current) {
        mem.search.current = null;
        mem.search.idx++;
        mem.search.blocked++;
      }

      if (mem.stuckCount >= 3) {
        mem.stuckCount = 0;
        if (mem.state === "goto" && mem.curHint) {
          mem.curHint.status = 2;
          mem.curHint = null;
          mem.state = "choose";
        } else if (mem.state === "approach") {
          failApproach();
        } else if (mem.state === "search" && mem.search) {
          if (mem.search.blocked > 4) failSearch();
        }
      }
    } else if (moved > 0.22) {
      mem.stuckCount = Math.max(0, mem.stuckCount - 1);
    }

    mem.progressT = t;
    mem.progressPos = { x: mem.pos.x, y: mem.pos.y };
  }

  // Opportunistic real site while not returning or charging.
  if (siteValid && c < mem.capacity && t >= mem.recoverUntil &&
      mem.state !== "return" && mem.state !== "charge" && mem.state !== "drill" &&
      mem.state !== "idle") {
    if (mem.state !== "approach" || !mem.approach) {
      startApproach(siteD, siteB, siteV);
    } else {
      mem.approach.lastSeen = t;
      mem.approach.d = siteD;
      mem.approach.value = siteV;
      const aa = (mem.head + siteB) * D2R;
      mem.approach.x = mem.pos.x + Math.cos(aa) * siteD;
      mem.approach.y = mem.pos.y + Math.sin(aa) * siteD;
    }
  }

  if (mem.state === "choose") {
    wantL = 0; wantR = 0; drillCmd = false;

    if (c > 0) {
      mem.state = "return";
    } else if (timeLeft < 28) {
      mem.state = "idle";
    } else if (battery < 0.12) {
      if (distToBase < 3.5) {
        mem.state = "charge";
        mem.chargeStart = t;
        mem.chargeTarget = Math.min(0.78, battery + 0.25);
      } else {
        mem.state = "return";
      }
    } else if (distToBase < 3.0 && battery < 0.47 && timeLeft > 120) {
      mem.state = "charge";
      mem.chargeStart = t;
      mem.chargeTarget = Math.min(0.86, Math.max(0.72, battery + 0.24));
    } else {
      const h = chooseHint();
      if (h) {
        h.attempts++;
        mem.curHint = h;
        mem.search = null;
        mem.approach = null;
        mem.drillStart = 0;
        mem.state = "goto";
        mem.stuckCount = 0;
      } else {
        if (!mem.exploreDone && timeLeft > 75 && battery > 0.28) {
          mem.exploreDone = true;
          const eh = {
            id: 100000, x: mem.pos.x, y: mem.pos.y, val: 1,
            status: 0, attempts: 0, synthetic: true
          };
          startSearch(eh);
          mem.curHint = eh;
        } else if (distToBase > 4.0 && battery < 0.45) {
          mem.state = "return";
        } else {
          mem.state = "idle";
        }
      }
    }
  }

  if (mem.state === "goto") {
    const h = mem.curHint;
    if (!h || h.status !== 0) {
      mem.state = "choose";
    } else {
      const d = dist(mem.pos.x, mem.pos.y, h.x, h.y);
      const dh = dist(h.x, h.y, mem.base.x, mem.base.y);

      if (d < 8.5) {
        startSearch(h);
      } else if (timeLeft < d / 0.30 + 45) {
        if (h.status === 0) h.status = 2;
        mem.curHint = null;
        mem.state = "choose";
      } else {
        let v = 0.56;
        if (d < 25) v = 0.48;
        if (d < 14) v = 0.38;
        if (d < 9) v = 0.30;
        if (battery < 0.20) v = Math.min(v, 0.38);
        if (timeLeft < 250) v = Math.min(0.52, v + 0.03);
        driveToPoint(h.x, h.y, v);
      }
    }
  }

  if (mem.state === "search") {
    const s = mem.search;
    if (!s) {
      mem.state = "choose";
    } else {
      if (t - s.phaseStart > s.phaseTime) {
        if (s.phase === 0 && timeLeft > 230 && battery > 0.24 &&
            (s.sciMax > 0.45 || s.h.val > mem.medVal * 1.25 || mem.totalDeliveredSamples === 0)) {
          s.phase = 1;
          s.radius = 15.5;
          s.n = 20;
          s.idx = 0;
          s.angle0 += 0.23;
          s.phaseStart = t;
          s.phaseTime = 240;
          s.current = null;
          s.blocked = 0;
        } else {
          failSearch();
        }
      }

      if (mem.state === "search") {
        const s2 = mem.search;
        if (s2) {
          if (s2.idx >= s2.n) {
            if (s2.phase === 0 && timeLeft > 230 && battery > 0.24 &&
                (s2.sciMax > 0.45 || s2.h.val > mem.medVal * 1.25 || mem.totalDeliveredSamples === 0)) {
              s2.phase = 1;
              s2.radius = 15.5;
              s2.n = 20;
              s2.idx = 0;
              s2.angle0 += 0.23;
              s2.phaseStart = t;
              s2.phaseTime = 240;
              s2.current = null;
              s2.blocked = 0;
            } else {
              failSearch();
            }
          }

          if (mem.state === "search" && mem.search) {
            const s3 = mem.search;
            if (!s3.current) {
              const a = s3.angle0 + (s3.idx / s3.n) * 2 * PI;
              s3.current = {
                x: s3.h.x + s3.radius * Math.cos(a),
                y: s3.h.y + s3.radius * Math.sin(a)
              };
              s3.curStart = t;
            }

            if (s3.current) {
              if (science > s3.sciMax) s3.sciMax = science;
              const d = dist(mem.pos.x, mem.pos.y, s3.current.x, s3.current.y);
              if (d < 1.35 || t - s3.curStart > 22) {
                if (d < 1.35) s3.sciMax = Math.max(s3.sciMax, science);
                else s3.blocked++;
                s3.idx++;
                s3.current = null;
                wantL = 0; wantR = 0;
                if (s3.blocked > 7) failSearch();
              } else {
                let v = 0.50;
                if (d < 4.0) v = 0.36;
                driveToPoint(s3.current.x, s3.current.y, v);
              }
            }
          }
        }
      }
    }
  }

  if (mem.state === "approach") {
    const ap = mem.approach;
    if (!ap) {
      mem.state = mem.search ? "search" : (mem.curHint ? "goto" : "choose");
    } else {
      let vis = false;
      let d = 1e9;
      let err = 0;

      if (siteValid) {
        vis = true;
        d = siteD;
        err = siteB;
        ap.lastSeen = t;
        ap.d = siteD;
        ap.value = siteV;
        const aa = (mem.head + siteB) * D2R;
        ap.x = mem.pos.x + Math.cos(aa) * siteD;
        ap.y = mem.pos.y + Math.sin(aa) * siteD;
      } else {
        d = dist(mem.pos.x, mem.pos.y, ap.x, ap.y);
        err = wrap(angleTo(mem.pos.x, mem.pos.y, ap.x, ap.y) - mem.head);
      }

      const sp = Math.abs(vAvg);

      if (d <= 1.45 && sp < 0.145) {
        mem.state = "drill";
        mem.drillStart = t;
        mem.approach = ap;
        wantL = 0; wantR = 0;
        drillCmd = true;
      } else if (d <= 1.62) {
        wantL = 0; wantR = 0;
        drillCmd = false;
        if (sp < 0.055 && d > 1.38) {
          driveErr(vis ? siteB : err, d, 0.105);
        }
      } else {
        let vmax = 0.50;
        if (d < 5.0) vmax = 0.35;
        if (d < 2.6) vmax = 0.20;
        driveErr(vis ? siteB : err, d, vmax);
      }

      if (!vis && t - ap.lastSeen > 7.0 && d > 2.2) {
        failApproach();
      } else if (t - ap.start > 95) {
        failApproach();
      }
    }
  }

  if (mem.state === "drill") {
    const ap = mem.approach;
    let vis = false;
    let d = 1e9;

    if (siteValid) {
      vis = true;
      d = siteD;
      if (ap) {
        ap.lastSeen = t;
        ap.d = siteD;
        ap.value = siteV;
        const aa = (mem.head + siteB) * D2R;
        ap.x = mem.pos.x + Math.cos(aa) * siteD;
        ap.y = mem.pos.y + Math.sin(aa) * siteD;
      }
    } else if (ap) {
      d = dist(mem.pos.x, mem.pos.y, ap.x, ap.y);
    }

    const sp = Math.abs(vAvg);
    wantL = 0; wantR = 0;

    if (d <= 1.48) drillCmd = true;
    else drillCmd = false;

    if (d > 1.72 && t - mem.drillStart < 18) {
      mem.state = "approach";
      drillCmd = false;
    } else if (t - mem.drillStart > 20 && c === mem.lastCarried) {
      if (ap) ap.lastSeen = Math.min(ap.lastSeen, t - 5);
      drillCmd = false;
      mem.state = mem.search ? "search" : (mem.curHint && mem.curHint.status === 0 ? "goto" : "choose");
      mem.approach = null;
      mem.drillStart = 0;
    }
  }

  if (mem.state === "return") {
    drillCmd = false;
    const bd = distToBase;

    if (c > 0) {
      if (bd < 2.45 || obs.docked) {
        wantL = 0; wantR = 0;
        if (!mem.dockStart) mem.dockStart = t;

        if (bd > 1.75 && t - mem.dockStart > 4.0 && !obs.docked) {
          let err;
          let dd = bd;
          if (beaconValid && beaconD < 20) {
            err = beaconB;
            dd = beaconD;
          } else {
            err = wrap(angleTo(mem.pos.x, mem.pos.y, mem.base.x, mem.base.y) - mem.head);
          }
          driveErr(err, dd, 0.115);
        }
      } else {
        mem.dockStart = 0;
        let err;
        let dd = bd;
        if (beaconValid && beaconD < 20) {
          err = beaconB;
          dd = beaconD;
        } else {
          err = wrap(angleTo(mem.pos.x, mem.pos.y, mem.base.x, mem.base.y) - mem.head);
        }

        let v = 0.55;
        if (dd < 14) v = 0.42;
        if (dd < 7) v = 0.28;
        if (dd < 3.6) v = 0.14;
        if (battery < 0.16) v = Math.min(v, 0.32);
        driveErr(err, dd, v);
      }
    } else {
      if (bd < 3.2) {
        wantL = 0; wantR = 0;
        if (battery < 0.82 && timeLeft > 50) {
          mem.state = "charge";
          mem.chargeStart = t;
          mem.chargeTarget = Math.min(0.88, Math.max(0.70, battery + 0.24));
        } else {
          mem.state = "choose";
        }
      } else {
        let err;
        let dd = bd;
        if (beaconValid && beaconD < 20) {
          err = beaconB;
          dd = beaconD;
        } else {
          err = wrap(angleTo(mem.pos.x, mem.pos.y, mem.base.x, mem.base.y) - mem.head);
        }
        let v = 0.50;
        if (dd < 14) v = 0.40;
        if (dd < 7) v = 0.26;
        if (dd < 3.5) v = 0.14;
        driveErr(err, dd, v);
      }
    }
  }

  if (mem.state === "charge") {
    wantL = 0; wantR = 0; drillCmd = false;
    if (!mem.chargeStart) mem.chargeStart = t;
    if (distToBase > 3.5 && !obs.docked) {
      mem.state = "return";
    } else if (battery >= mem.chargeTarget || timeLeft < 35 || t - mem.chargeStart > 55) {
      mem.state = "choose";
    }
  }

  if (mem.state === "idle") {
    wantL = 0; wantR = 0; drillCmd = false;
    if (c > 0) mem.state = "return";
    else if (timeLeft > 60 && battery > 0.55 && mem.totalDeliveredSamples > 0) {
      mem.state = "choose";
    }
  }

  if (t < mem.recoverUntil &&
      mem.state !== "charge" && mem.state !== "drill" &&
      !(c > 0 && distToBase < 2.6)) {
    const elapsed = t - mem.recoverStart;
    drillCmd = false;
    if (elapsed < 0.48) {
      setDrive(-0.13, 0);
    } else {
      setDrive(0, (mem.recoverSide || 1) * 0.58);
    }
  }

  function motorCtrl(target, actual, st, pitchDeg) {
    target = clamp(Number(target), -0.62, 0.62);
    if (!isFinite(target)) target = 0;
    actual = Number(actual);
    if (!isFinite(actual)) actual = 0;

    if (!isFinite(st.gain) || st.gain < 0.7) st.gain = 2.0;
    if (!isFinite(st.dz)) st.dz = 0.045;
    if (!isFinite(st.bias)) st.bias = 0;
    if (!isFinite(st.u)) st.u = 0;
    if (!isFinite(st.lastSpeed)) st.lastSpeed = 0;
    if (!isFinite(st.lastCmd)) st.lastCmd = 0;

    const prev = st.u;
    const acc = (actual - st.lastSpeed) / Math.max(dt, 0.01);
    st.lastSpeed = actual;

    if (Math.abs(prev) > 0.08 && Math.abs(actual) > 0.04 && prev * actual > 0) {
      const eff = Math.abs(actual) / Math.max(0.02, Math.abs(prev) - st.dz);
      if (eff > 0.25 && eff < 8.0) st.gain = clamp(st.gain * 0.98 + eff * 0.02, 0.75, 5.0);
    }

    if (actual > 0.96) {
      st.u = Math.max(st.u - 0.35, -0.9);
      st.lastCmd = st.u;
      return -0.60;
    }
    if (actual < -0.96) {
      st.u = Math.min(st.u + 0.35, 0.9);
      st.lastCmd = st.u;
      return 0.60;
    }

    const err = target - actual;
    const dir = target > 0.012 ? 1 : (target < -0.012 ? -1 : 0);
    const slope = Math.sin((Number(pitchDeg) || 0) * D2R) * 0.105;

    st.bias += clamp(err, -0.35, 0.35) * 0.055 * dt;
    st.bias = clamp(st.bias, -0.25, 0.25);

    let u;
    if (dir === 0) {
      u = st.bias * 0.70 + slope * 0.80 - actual * 1.10;
    } else {
      const ff = dir * st.dz + target / st.gain;
      u = ff + st.bias + slope + err * 0.55 - clamp(acc, -3.0, 3.0) * 0.040;
    }

    if (Math.abs(target) < 0.012 && Math.abs(actual) < 0.02) {
      u = st.bias * 0.55 + slope * 0.80;
    }

    let maxStep = 0.045;
    if (Math.abs(u) < Math.abs(prev) || (u * prev < 0 && Math.abs(u) > 0.005)) maxStep = 0.115;
    if (Math.abs(actual) > Math.abs(target) + 0.16 && Math.abs(actual) > 0.10) maxStep = 0.20;

    let du = u - prev;
    if (du > maxStep) u = prev + maxStep;
    if (du < -maxStep) u = prev - maxStep;

    u = clamp(u, -0.85, 0.85);

    if (actual > 0.82 && u > 0) u *= 0.35;
    if (actual < -0.82 && u < 0) u *= 0.35;

    st.u = u;
    st.lastCmd = u;
    return u;
  }

  let uL = motorCtrl(wantL, wl, mem.wheelL, obs.pitch);
  let uR = motorCtrl(wantR, wr, mem.wheelR, obs.pitch);

  if (vAvg > 0.86) {
    uL = Math.min(uL, -0.26);
    uR = Math.min(uR, -0.26);
  } else if (vAvg < -0.86) {
    uL = Math.max(uL, 0.26);
    uR = Math.max(uR, 0.26);
  }

  if (wl > 0.92) uL = Math.min(uL, -0.48);
  if (wr > 0.92) uR = Math.min(uR, -0.48);
  if (wl < -0.92) uL = Math.max(uL, 0.48);
  if (wr < -0.92) uR = Math.max(uR, 0.48);

  if (!isFinite(uL)) uL = 0;
  if (!isFinite(uR)) uR = 0;

  mem.lastCmdMag = Math.max(Math.abs(wantL), Math.abs(wantR));

  return {
    left: clamp(uL, -1, 1),
    right: clamp(uR, -1, 1),
    drill: !!drillCmd
  };
}

function act(obs, mem) {
  const PI = Math.PI, D2R = PI / 180, R2D = 180 / PI;

  function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
  function wrap(a) {
    a = Number(a);
    if (!isFinite(a)) return 0;
    a = a % 360;
    if (a > 180) a -= 360;
    if (a < -180) a += 360;
    return a;
  }
  function dist(ax, ay, bx, by) {
    const dx = ax - bx, dy = ay - by;
    return Math.sqrt(dx * dx + dy * dy);
  }
  function angleTo(x1, y1, x2, y2) {
    return Math.atan2(y2 - y1, x2 - x1) * R2D;
  }
  function countCarried(o) {
    const c = o.carried;
    if (typeof c === "number") return c;
    if (Array.isArray(c)) return c.length;
    if (c && typeof c.length === "number") return c.length;
    return c ? 1 : 0;
  }

  let t = Number(obs.t);
  if (!isFinite(t)) t = 0;

  if (!mem.init) {
    mem.init = true;

    const m = obs.mission || {};
    let sx = m.size, sy = m.size;
    if (sx && typeof sx === "object") {
      sy = Number(sx.y != null ? sx.y : (sx.h != null ? sx.h : 400));
      sx = Number(sx.x != null ? sx.x : (sx.w != null ? sx.w : 400));
    }
    sx = Number(sx); sy = Number(sy);
    if (!(sx > 10)) sx = 400;
    if (!(sy > 10)) sy = 400;
    mem.sizeX = sx;
    mem.sizeY = sy;

    const mb = m.base || {};
    mem.base = {
      x: isFinite(Number(mb.x)) ? Number(mb.x) : (Number(obs.x) || 200),
      y: isFinite(Number(mb.y)) ? Number(mb.y) : (Number(obs.y) || 200)
    };
    if (!isFinite(mem.base.x)) mem.base.x = 200;
    if (!isFinite(mem.base.y)) mem.base.y = 200;

    mem.capacity = Number(m.capacity || 5);
    if (!(mem.capacity >= 1)) mem.capacity = 5;
    mem.seconds = Number(m.seconds || 1200);
    if (!(mem.seconds > 0)) mem.seconds = 1200;

    mem.hints = [];
    const hs = m.hints || [];
    for (let i = 0; i < hs.length; i++) {
      const h = hs[i] || {};
      const hx = Number(h.x), hy = Number(h.y);
      if (!isFinite(hx) || !isFinite(hy)) continue;
      let hv = Number(h.estimate);
      if (!isFinite(hv) || hv < 0) hv = 1;
      mem.hints.push({
        id: mem.hints.length,
        x: hx, y: hy, val: hv,
        status: 0, attempts: 0
      });
    }

    let ix = Number(obs.x), iy = Number(obs.y);
    if (!isFinite(ix)) ix = mem.base.x;
    if (!isFinite(iy)) iy = mem.base.y;
    mem.pos = { x: ix, y: iy };

    let rh = Number(obs.heading);
    if (!isFinite(rh)) rh = 0;
    mem.head = wrap(rh);
    mem.headBias = 0;

    mem.lastRawX = ix;
    mem.lastRawY = iy;
    mem.lastRawH = rh;
    mem.lastT = t - 0.1;

    mem.state = "choose";
    mem.targetHint = null;
    mem.search = null;
    mem.approach = null;
    mem.drillStart = 0;

    mem.lastCarried = countCarried(obs);
    mem.sampleCount = 0;
    mem.deliveredSamples = 0;

    mem.prevBumped = false;
    mem.bumpCount = 0;
    mem.recoverUntil = -1;
    mem.recoverStart = -10;
    mem.recoverSide = 1;
    mem.avoidUntil = 0;
    mem.avoidSide = 1;

    mem.stuckCount = 0;
    mem.progressT = t;
    mem.progressPos = { x: ix, y: iy };
    mem.rawProgressX = ix;
    mem.rawProgressY = iy;
    mem.rawStuckTimer = 0;
    mem.rawStuckCount = 0;

    mem.gpsFrozen = false;
    mem.freezeTimer = 0;

    mem.ignoreRaysUntil = -1;
    mem.lowClearStart = 0;

    mem.wheelL = { cmd: 0, gain: 1.2, intg: 0, dz: 0.04 };
    mem.wheelR = { cmd: 0, gain: 1.2, intg: 0, dz: 0.04 };
    mem.lastCmdMag = 0;

    mem.chargeStart = 0;
    mem.chargeTarget = 0.9;
    mem.deliveryWaitT = 0;

    mem.bestSci = -1;
    mem.bestSciPos = null;

    mem.explorePts = null;
    mem.exploreTarget = null;
    mem.exploreCounter = 0;

    mem.returnDetourUntil = 0;
  }

  let dt = t - mem.lastT;
  if (!(dt > 0 && dt < 1.0)) dt = 0.1;
  mem.lastT = t;

  let wl = Number(obs.wheelLeft);
  let wr = Number(obs.wheelRight);
  if (!isFinite(wl)) wl = 0;
  if (!isFinite(wr)) wr = 0;
  const vAvg = (wl + wr) / 2;

  let battery = Number(obs.battery);
  if (!isFinite(battery)) battery = 1;
  let timeLeft = Number(obs.timeLeft);
  if (!isFinite(timeLeft)) timeLeft = mem.seconds - t;
  if (timeLeft < 0) timeLeft = 0;
  let science = Number(obs.science);
  if (!isFinite(science)) science = 0;
  let pitch = Number(obs.pitch);
  if (!isFinite(pitch)) pitch = 0;

  let carried = countCarried(obs);

  const siteO = obs.site || null;
  let siteValid = false;
  let siteD = 1e9, siteB = 0, siteV = 0;
  if (siteO && isFinite(Number(siteO.distance)) && isFinite(Number(siteO.bearing))) {
    siteD = Number(siteO.distance);
    siteB = Number(siteO.bearing);
    siteV = Number(siteO.value);
    if (!isFinite(siteV)) siteV = 0;
    if (siteD >= 0 && siteD < 8.5) siteValid = true;
  }

  const beaconO = obs.beacon || null;
  let beaconValid = false;
  let beaconD = 1e9, beaconB = 0;
  if (beaconO && isFinite(Number(beaconO.distance)) && isFinite(Number(beaconO.bearing))) {
    beaconD = Number(beaconO.distance);
    beaconB = Number(beaconO.bearing);
    if (beaconD >= 0 && beaconD < 25) beaconValid = true;
  }

  let rawX = Number(obs.x), rawY = Number(obs.y);
  let rawH = Number(obs.heading);
  const rawValid = isFinite(rawX) && isFinite(rawY);
  if (!rawValid) {
    rawX = mem.lastRawX;
    rawY = mem.lastRawY;
  }
  if (!isFinite(rawH)) rawH = mem.lastRawH;

  const rays = [15, 15, 15, 15, 15, 15, 15, 15, 15];
  if (obs.rays && obs.rays.length) {
    for (let i = 0; i < 9; i++) {
      let v = Number(obs.rays[i]);
      if (!isFinite(v) || v < 0.02) v = 15;
      if (v > 15) v = 15;
      rays[i] = v;
    }
  }
  const rawFrontMin = Math.min(rays[2], rays[3], rays[4], rays[5], rays[6]);

  const prevRawX = mem.lastRawX;
  const prevRawY = mem.lastRawY;
  const rawMove = dist(rawX, rawY, prevRawX, prevRawY);
  const expMove = Math.abs(vAvg) * dt;

  if (expMove > 0.02 && rawMove < 0.004) mem.freezeTimer += dt;
  else if (rawMove > 0.02) mem.freezeTimer = 0;

  if (mem.freezeTimer > 2.0 && rawFrontMin > 1.5) mem.gpsFrozen = true;
  if (mem.gpsFrozen && rawMove > 0.05) {
    mem.gpsFrozen = false;
    mem.freezeTimer = 0;
    mem.pos.x = rawX;
    mem.pos.y = rawY;
  }

  const wheelYaw = ((wr - wl) / 0.6) * R2D * dt;
  const predHead = wrap(mem.head + wheelYaw);
  const biasedRaw = wrap(rawH - mem.headBias);
  const dHead = wrap(biasedRaw - predHead);
  const wheelMag = Math.abs(wl) + Math.abs(wr);

  if (wheelMag < 0.05) {
    const corr = wrap(biasedRaw - mem.head);
    if (Math.abs(corr) < 30) mem.head = wrap(mem.head + corr * 0.28);
    else if (Math.abs(corr) < 80) mem.head = wrap(mem.head + corr * 0.06);
  } else {
    if (Math.abs(dHead) < 45) mem.head = wrap(predHead + dHead * 0.18);
    else if (Math.abs(dHead) < 90) mem.head = wrap(predHead + dHead * 0.03);
    else mem.head = predHead;
  }

  if (mem.gpsFrozen || !rawValid) {
    mem.pos.x += vAvg * Math.cos(mem.head * D2R) * dt;
    mem.pos.y += vAvg * Math.sin(mem.head * D2R) * dt;
  } else {
    const dp = dist(rawX, rawY, mem.pos.x, mem.pos.y);
    if (dp > 6.0) {
      mem.pos.x = rawX;
      mem.pos.y = rawY;
    } else {
      const a = dp > 2.0 ? 0.45 : 0.72;
      mem.pos.x = mem.pos.x * (1 - a) + rawX * a;
      mem.pos.y = mem.pos.y * (1 - a) + rawY * a;
    }
  }
  if (!isFinite(mem.pos.x)) mem.pos.x = rawX;
  if (!isFinite(mem.pos.y)) mem.pos.y = rawY;

  mem.lastRawX = rawX;
  mem.lastRawY = rawY;
  mem.lastRawH = rawH;

  if (!mem.gpsFrozen && rawMove > 0.05 && Math.abs(vAvg) > 0.08 && Math.abs(wl - wr) < 0.18) {
    const course = angleTo(prevRawX, prevRawY, rawX, rawY);
    const bObs = wrap(rawH - course);
    const dbias = wrap(bObs - mem.headBias);
    if (Math.abs(dbias) < 55) {
