    }
  }

  let distToBase = dist(mem.pos.x, mem.pos.y, mem.base.x, mem.base.y);
  if (beaconValid && beaconD < 20) distToBase = Math.min(distToBase, beaconD);

  if (beaconValid && beaconD > 1.5 && beaconD < 19 && !mem.gpsFrozen) {
    const trueAng = angleTo(mem.pos.x, mem.pos.y, mem.base.x, mem.base.y);
    const hMeas = wrap(trueAng - beaconB);
    const biasObs = wrap(rawH - hMeas);
    const dbias = wrap(biasObs - mem.headBias);
    if (Math.abs(dbias) < 50) {
      mem.headBias = wrap(mem.headBias + dbias * 0.02);
    }
    const hd = wrap(hMeas - mem.head);
    if (Math.abs(hd) < 45) mem.head = wrap(mem.head + hd * 0.08);
  }

  if (science > mem.bestSci) {
    mem.bestSci = science;
    mem.bestSciPos = { x: mem.pos.x, y: mem.pos.y, t: t };
  }

  function rayAt(rel) {
    const a = clamp(rel, -80, 80);
    const idx = (a + 80) / 20;
    let i = Math.floor(idx);
    if (i < 0) i = 0;
    if (i > 7) i = 7;
    const f = clamp(idx - i, 0, 1);
    let d1 = rays[i], d2 = rays[i + 1];
    if (!isFinite(d1)) d1 = 15;
    if (!isFinite(d2)) d2 = 15;
    return d1 * (1 - f) + d2 * f;
  }

  function boundaryClear(rel) {
    const ang = (mem.head + rel) * D2R;
    const dx = Math.cos(ang), dy = Math.sin(ang);
    const margin = 1.8;
    let tx = 1e9, ty = 1e9;
    if (dx > 1e-6) tx = (mem.sizeX - margin - mem.pos.x) / dx;
    else if (dx < -1e-6) tx = (margin - mem.pos.x) / dx;
    if (dy > 1e-6) ty = (mem.sizeY - margin - mem.pos.y) / dy;
    else if (dy < -1e-6) ty = (margin - mem.pos.y) / dy;
    let d = 1e9;
    if (tx > 0) d = Math.min(d, tx);
    if (ty > 0) d = Math.min(d, ty);
    if (!(d > 0)) d = 0;
    return Math.min(d, 15);
  }

  const ignoreRays = t < (mem.ignoreRaysUntil || -1);

  function frontClear() {
    let d = Math.min(boundaryClear(-28), boundaryClear(0), boundaryClear(28));
    if (!ignoreRays) {
      d = Math.min(d, rayAt(-35), rayAt(-18), rayAt(0), rayAt(18), rayAt(35));
    }
    return d;
  }

  function chooseAvoidSide() {
    let left = 0, right = 0;
    if (!ignoreRays) {
      for (let i = 0; i < 9; i++) {
        const rel = (i - 4) * 20;
        let d = rays[i];
        if (!isFinite(d)) d = 15;
        d = Math.min(d, 8);
        if (rel >= 10) left += d;
        else if (rel <= -10) right += d;
      }
    }
    left += Math.min(boundaryClear(90), 8) * 1.6;
    right += Math.min(boundaryClear(-90), 8) * 1.6;
    if (Math.abs(left - right) < 0.55) return mem.avoidSide || 1;
    return left >= right ? 1 : -1;
  }

  let wantL = 0, wantR = 0, drillCmd = false;

  function setDrive(v, omega) {
    v = clamp(Number(v) || 0, -0.42, 0.42);
    omega = clamp(Number(omega) || 0, -1.05, 1.05);
    const l = v - omega * 0.30;
    const r = v + omega * 0.30;
    wantL = clamp(l, -0.46, 0.46);
    wantR = clamp(r, -0.46, 0.46);
  }

  function driveRel(errIn, d, vmax) {
    let err = wrap(errIn);
    const ae = Math.abs(err);
    let v = vmax;
    if (!(v > 0)) v = 0;

    if (d < 2.2) v *= clamp((d - 0.45) / 1.75, 0.12, 1.0);
    else if (d < 4.5) v *= 0.82;

    if (ae > 100) v = 0;
    else if (ae > 65) v = Math.min(v, 0.045);
    else if (ae > 35) v = Math.min(v, 0.12);
    else if (ae > 18) v = Math.min(v, 0.24);

