    }

    const fc = frontClear();
    if (fc < 0.95) {
      v = 0;
      if (!mem.avoidUntil || t > mem.avoidUntil) {
        mem.avoidSide = chooseAvoidSide();
        mem.avoidUntil = t + 1.15;
      }
      omega = (mem.avoidSide || 1) * 0.85;
    } else if (fc < 1.65) {
      v = Math.min(v, 0.06);
      if (!mem.avoidUntil || t > mem.avoidUntil) {
        mem.avoidSide = chooseAvoidSide();
        mem.avoidUntil = t + 0.9;
      }
      omega += (mem.avoidSide || 1) * ((1.65 - fc) / 1.65) * 0.60;
    } else if (fc < 2.7) {
      v = Math.min(v, 0.22);
      if (!mem.avoidUntil || t > mem.avoidUntil) {
        mem.avoidSide = chooseAvoidSide();
        mem.avoidUntil = t + 0.6;
      }
      omega += (mem.avoidSide || 1) * ((2.7 - fc) / 2.7) * 0.32;
    }

    if (t < mem.avoidUntil && mem.avoidSide) {
      omega += mem.avoidSide * 0.18;
    }

    const bd = Math.min(mem.pos.x, mem.sizeX - mem.pos.x, mem.pos.y, mem.sizeY - mem.pos.y);
    if (bd < 4.0) {
      const inward = angleTo(mem.pos.x, mem.pos.y, mem.sizeX * 0.5, mem.sizeY * 0.5);
      const ie = wrap(inward - mem.head);
      omega = clamp(omega * 0.5 + ie * 0.020, -1.0, 1.0);
      v = Math.min(v, 0.13 + Math.max(0, (bd - 1.3) / 2.7) * 0.20);
    }

    if (Math.abs(pitch) > 18) v = Math.min(v, 0.15);
    if (battery < 0.10) v = Math.min(v, 0.20);

    setDrive(v, omega);
  }

  function driveToPoint(tx, ty, vmax) {
    const d = dist(mem.pos.x, mem.pos.y, tx, ty);
    if (d < 0.05) {
      setDrive(0, 0);
      return d;
    }
    const desired = angleTo(mem.pos.x, mem.pos.y, tx, ty);
    const err = wrap(desired - mem.head);
    driveRel(err, d, vmax);
    return d;
  }

  function startRecovery() {
    mem.recoverStart = t;
    mem.recoverUntil = t + 1.45;
    mem.recoverSide = chooseAvoidSide();
  }

  function startApproach(sd, sb, sv) {
    const aa = (mem.head + sb) * D2R;
    mem.approach = {
      x: mem.pos.x + Math.cos(aa) * sd,
      y: mem.pos.y + Math.sin(aa) * sd,
      d: sd, value: sv, start: t, lastSeen: t
    };
    mem.state = "approach";
    mem.drillStart = 0;
  }

  function markSampleSuccess() {
    let best = null, bd = 36;
    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (h.status === 1) continue;
      const d = dist(mem.pos.x, mem.pos.y, h.x, h.y);
      if (d < bd) {
        bd = d;
        best = h;
      }
    }
    if (!best) {
      bd = 36;
      for (let i = 0; i < mem.hints.length; i++) {
        const h = mem.hints[i];
        if (h.status === 2) continue;
        const d = dist(mem.pos.x, mem.pos.y, h.x, h.y);
        if (d < bd) {
          bd = d;
          best = h;
        }
      }
    }
    if (best) best.status = 1;
    mem.targetHint = null;
    mem.search = null;
    mem.approach = null;
    mem.drillStart = 0;
    mem.bestSci = -1;
    mem.bestSciPos = null;
  }

  function failSearch() {
    if (mem.search && mem.search.h && mem.search.h.status === 0) {
      mem.search.h.status = 2;
    }
    mem.search = null;
    mem.approach = null;
    mem.targetHint = null;
    mem.drillStart = 0;
    mem.state = "choose";
  }

  function failApproach() {
    mem.approach = null;
    mem.drillStart = 0;
    if (mem.search && t < mem.search.deadline) mem.state = "search";
    else if (mem.targetHint && mem.targetHint.status === 0) mem.state = "goto";
    else mem.state = "choose";
  }

  function startSearch(h) {
    const offs = [
      { x: 0, y: 0 },
      { x: 8, y: 0 }, { x: 0, y: 8 }, { x: -8, y: 0 }, { x: 0, y: -8 },
      { x: 6, y: 6 }, { x: -6, y: 6 }, { x: -6, y: -6 }, { x: 6, y: -6 },
      { x: 14, y: 0 }, { x: 10, y: 10 }, { x: 0, y: 14 }, { x: -10, y: 10 },
      { x: -14, y: 0 }, { x: -10, y: -10 }, { x: 0, y: -14 }, { x: 10, y: -10 },
      { x: 18, y: 0 }, { x: 13, y: 13 }, { x: 0, y: 18 }, { x: -13, y: 13 },
      { x: -18, y: 0 }, { x: -13, y: -13 }, { x: 0, y: -18 }, { x: 13, y: -13 }
    ];
    const pts = [];
    for (let i = 0; i < offs.length; i++) {
      const px = h.x + offs[i].x;
      const py = h.y + offs[i].y;
      if (px > 4 && px < mem.sizeX - 4 && py > 4 && py < mem.sizeY - 4) {
        pts.push({ x: px, y: py, visited: false });
      }
    }
    if (pts.length === 0) {
      pts.push({
        x: clamp(h.x, 4, mem.sizeX - 4),
        y: clamp(h.y, 4, mem.sizeY - 4),
        visited: false
      });
    }

    mem.search = {
      h: h,
      points: pts,
      start: t,
      deadline: t + (mem.deliveredSamples === 0 ? 105 : 78),
      current: null,
      curStart: t,
      blocked: 0
    };
    mem.state = "search";
    mem.approach = null;
    mem.drillStart = 0;
  }

  function chooseHint() {
    let best = null, bestScore = -1e99;
    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (h.status !== 0) continue;

      const d = dist(mem.pos.x, mem.pos.y, h.x, h.y);
      const dh = dist(h.x, h.y, mem.base.x, mem.base.y);
      let val = h.val > 0 ? h.val : 1;

      const rough = (d + dh) / 0.30 + 130;
      if (timeLeft < Math.min(rough, 220)) continue;

      let score;
      if (mem.deliveredSamples === 0) {
        score = 1.0 / (d + 0.22 * dh + 32);
        score *= (1 + 0.07 * Math.min(val, 6));
      } else {
        score = (val + 0.25) / (d + 0.45 * dh + 82);
      }
      if (h.attempts > 0) score *= 0.60;
      if (timeLeft < 300) score *= 1.0 / (1 + dh / 220);

      if (score > bestScore) {
        bestScore = score;
        best = h;
      }
    }
    return best;
  }

  function chooseExplore() {
    if (!mem.explorePts) {
      mem.explorePts = [];
      const step = 50;
      for (let x = 25; x < mem.sizeX - 8; x += step) {
        for (let y = 25; y < mem.sizeY - 8; y += step) {
          mem.explorePts.push({ x: x, y: y, done: false });
        }
      }
      if (mem.explorePts.length === 0) {
        mem.explorePts.push({ x: mem.sizeX * 0.5, y: mem.sizeY * 0.5, done: false });
      }
    }

    for (let i = 0; i < mem.explorePts.length; i++) {
      const p = mem.explorePts[i];
      if (!p.done && dist(mem.pos.x, mem.pos.y, p.x, p.y) < 8.5) p.done = true;
    }

    let best = null, bestScore = 1e99;
    for (let i = 0; i < mem.explorePts.length; i++) {
      const p = mem.explorePts[i];
      if (p.done) continue;
      const d = dist(mem.pos.x, mem.pos.y, p.x, p.y);
      const db = dist(p.x, p.y, mem.base.x, mem.base.y);
      if (timeLeft < (d + db) / 0.30 + 45) {
        p.done = true;
        continue;
      }
      let score = d + 0.20 * db;
      if (mem.bestSciPos) {
        score = Math.min(score, dist(p.x, p.y, mem.bestSciPos.x, mem.bestSciPos.y) + 24);
      }
      if (score < bestScore) {
        bestScore = score;
        best = p;
      }
    }

    if (!best) {
      mem.exploreCounter++;
      const ang = ((t * 7 + mem.exploreCounter * 137) % 360) * D2R;
      const r = 35 + 15 * Math.sin(mem.exploreCounter * 1.7);
      best = {
        x: clamp(mem.pos.x + Math.cos(ang) * r, 5, mem.sizeX - 5),
        y: clamp(mem.pos.y + Math.sin(ang) * r, 5, mem.sizeY - 5),
        done: false
      };
    }
    return best;
  }

  if (rawFrontMin < 1.0) {
    if (!mem.lowClearStart) mem.lowClearStart = t;
    else if (t - mem.lowClearStart > 5.0) {
      mem.ignoreRaysUntil = t + 7.0;
      mem.lowClearStart = t + 2.0;
    }
  } else {
    mem.lowClearStart = 0;
  }

  const bumped = !!obs.bumped;
  if (bumped && !mem.prevBumped) {
    mem.bumpCount++;
    if (mem.state !== "drill" && !(carried > 0 && distToBase < 2.9)) {
      startRecovery();
    }
    if (mem.state === "search" && mem.search && mem.search.current) {
      mem.search.current.visited = true;
      mem.search.current = null;
      mem.search.blocked = (mem.search.blocked || 0) + 1;
    }
    if (mem.state === "goto" && mem.targetHint) mem.targetHint.attempts++;
    if (mem.state === "approach" && mem.bumpCount >= 4) failApproach();
  }
  mem.prevBumped = bumped;

  if (carried > mem.lastCarried) {
    const added = carried - mem.lastCarried;
    mem.sampleCount += added;
    markSampleSuccess();
    mem.state = "return";
    mem.deliveryWaitT = 0;
  } else if (carried < mem.lastCarried) {
    const del = mem.lastCarried - carried;
    if (del > 0) mem.deliveredSamples += del;
    mem.state = "choose";
    mem.targetHint = null;
    mem.search = null;
    mem.approach = null;
    mem.drillStart = 0;
    mem.deliveryWaitT = 0;
    mem.chargeStart = t;
    mem.bestSci = -1;
    mem.bestSciPos = null;
  }
  mem.lastCarried = carried;

  if (carried > 0 && mem.state !== "return" && mem.state !== "charge" && mem.state !== "idle") {
    mem.state = "return";
    mem.targetHint = null;
    mem.search = null;
    mem.approach = null;
    mem.drillStart = 0;
    mem.deliveryWaitT = 0;
  }

  let wantsMove = false;
  if (mem.state === "goto" && mem.targetHint) wantsMove = true;
  else if (mem.state === "search") wantsMove = true;
  else if (mem.state === "approach") wantsMove = true;
  else if (mem.state === "return" && carried > 0) wantsMove = true;
  else if (mem.state === "explore" && mem.exploreTarget) wantsMove = true;

  const rawDistSince = dist(rawX, rawY, mem.rawProgressX, mem.rawProgressY);
  if (wantsMove && t > mem.recoverUntil && (mem.lastCmdMag || 0) > 0.05) {
    if (rawDistSince > 0.28) {
      mem.rawProgressX = rawX;
      mem.rawProgressY = rawY;
      mem.rawStuckTimer = 0;
      mem.rawStuckCount = 0;
    } else {
      mem.rawStuckTimer += dt;
    }

    let lim = 5.5;
    if (mem.gpsFrozen && frontClear() > 1.5) lim = 10.0;

    if (mem.rawStuckTimer > lim) {
      mem.rawStuckTimer = 0;
      startRecovery();
      mem.rawStuckCount = (mem.rawStuckCount || 0) + 1;

      if (mem.state === "search" && mem.search) {
        if (mem.search.current) {
          mem.search.current.visited = true;
          mem.search.current = null;
        }
        mem.search.blocked = (mem.search.blocked || 0) + 1;
      }
      if (mem.state === "goto" && mem.targetHint) mem.targetHint.attempts++;

      if (mem.rawStuckCount >= 3) {
        mem.rawStuckCount = 0;
        if (mem.state === "goto" && mem.targetHint) {
          mem.targetHint.status = 2;
          mem.targetHint = null;
          mem.state = "choose";
        } else if (mem.state === "search" && mem.search) {
          if ((mem.search.blocked || 0) >= 3 || t > mem.search.deadline) failSearch();
        } else if (mem.state === "approach") {
          failApproach();
        } else if (mem.state === "explore") {
          if (mem.exploreTarget) mem.exploreTarget.done = true;
          mem.exploreTarget = null;
          mem.state = "choose";
        } else if (mem.state === "return") {
          mem.returnDetourUntil = t + 4.0;
        }
      }
    }
  } else {
    mem.rawProgressX = rawX;
    mem.rawProgressY = rawY;
    mem.rawStuckTimer = 0;
  }

  if (t - mem.progressT > 2.6) {
    const moved = dist(mem.pos.x, mem.pos.y, mem.progressPos.x, mem.progressPos.y);
    const movingState =
      mem.state === "goto" || mem.state === "search" ||
      mem.state === "approach" || mem.state === "return" ||
      mem.state === "explore";
    const cmd = mem.lastCmdMag || 0;

    if (movingState && t > mem.recoverUntil && cmd > 0.05 && moved < 0.12) {
      mem.stuckCount++;
      if (!(carried > 0 && distToBase < 2.9)) startRecovery();
      if (mem.state === "search" && mem.search) {
        if (mem.search.current) {
          mem.search.current.visited = true;
          mem.search.current = null;
        }
      }
      if (mem.stuckCount >= 3) {
        mem.stuckCount = 0;
        if (mem.state === "goto" && mem.targetHint) {
          mem.targetHint.status = 2;
          mem.targetHint = null;
          mem.state = "choose";
        } else if (mem.state === "search" && mem.search) {
          if ((mem.search.blocked || 0) >= 3) failSearch();
        } else if (mem.state === "approach") {
          failApproach();
        } else if (mem.state === "explore") {
          if (mem.exploreTarget) mem.exploreTarget.done = true;
          mem.exploreTarget = null;
          mem.state = "choose";
        }
      }
    } else if (moved > 0.28) {
      mem.stuckCount = Math.max(0, mem.stuckCount - 1);
    }

    mem.progressT = t;
    mem.progressPos = { x: mem.pos.x, y: mem.pos.y };
  }

  if (siteValid && carried < mem.capacity && timeLeft > 14 &&
      mem.state !== "return" && mem.state !== "charge" &&
      mem.state !== "idle" && mem.state !== "drill") {
    if (mem.state !== "approach") startApproach(siteD, siteB, siteV);
  }

  if (mem.state === "choose") {
    wantL = 0;
    wantR = 0;
    drillCmd = false;

    if (carried > 0) {
      mem.state = "return";
    } else if (timeLeft < 24) {
      mem.state = "idle";
    } else if (distToBase < 3.1 && battery < 0.78 && timeLeft > 90) {
      mem.state = "charge";
      mem.chargeStart = t;
      mem.chargeTarget = Math.min(0.94, Math.max(0.68, battery + 0.24));
    } else if (battery < 0.12) {
      if (distToBase < 3.4) {
        mem.state = "charge";
        mem.chargeStart = t;
        mem.chargeTarget = Math.min(0.85, battery + 0.28);
      } else {
        mem.state = "return";
      }
    } else {
      const h = chooseHint();
      if (h) {
        h.attempts++;
        mem.targetHint = h;
        mem.search = null;
        mem.approach = null;
        mem.drillStart = 0;
        mem.state = "goto";
        mem.stuckCount = 0;
      } else {
        const p = chooseExplore();
        if (p) {
          mem.exploreTarget = p;
          mem.state = "explore";
          mem.targetHint = null;
          mem.search = null;
          mem.approach = null;
          mem.drillStart = 0;
        } else if (distToBase > 3.2) {
          mem.state = "return";
        } else {
          mem.state = "idle";
        }
      }
    }
  }

  if (mem.state === "goto") {
    const h = mem.targetHint;
    if (!h || h.status !== 0) {
      mem.state = "choose";
    } else {
      const d = dist(mem.pos.x, mem.pos.y, h.x, h.y);
      const dh = dist(h.x, h.y, mem.base.x, mem.base.y);

      if (d < 9.5) {
        startSearch(h);
      } else if (timeLeft < (d + dh) / 0.30 + 115) {
        h.status = 2;
        mem.targetHint = null;
        mem.state = "choose";
      } else {
        let vmax = 0.39;
        if (d < 25) vmax = 0.33;
        if (d < 13) vmax = 0.27;
        if (battery < 0.25) vmax = Math.min(vmax, 0.28);
        driveToPoint(h.x, h.y, vmax);
      }
    }
  }

  if (mem.state === "search") {
    const s = mem.search;
    if (!s) {
      mem.state = "choose";
    } else {
      if (t > s.deadline) {
        failSearch();
      } else {
        if (!s.current) {
          let best = null, bd = 1e99;
          for (let i = 0; i < s.points.length; i++) {
            const p = s.points[i];
            if (p.visited) continue;
            const dd = dist(mem.pos.x, mem.pos.y, p.x, p.y);
            if (dd < bd) {
              bd = dd;
              best = p;
            }
          }
          if (!best) {
            failSearch();
          } else {
            s.current = best;
            s.curStart = t;
          }
        }

        if (mem.state === "search" && s.current) {
          const p = s.current;
          const d = dist(mem.pos.x, mem.pos.y, p.x, p.y);
          if (d < 1.55) {
            p.visited = true;
            s.current = null;
          } else if (t - s.curStart > 14.0) {
            p.visited = true;
            s.current = null;
            s.blocked = (s.blocked || 0) + 1;
            if (s.blocked > 5) failSearch();
          } else {
            let vmax = 0.31;
            if (d < 4.0) vmax = 0.21;
            if (timeLeft < 200) vmax = Math.min(0.36, vmax + 0.03);
            driveToPoint(p.x, p.y, vmax);
          }
        }
      }
    }
  }

  if (mem.state === "approach") {
    const ap = mem.approach;
    if (!ap) {
      mem.state = "choose";
    } else {
      let vis = siteValid;
      let d = 1e9, err = 0, val = 0;

      if (vis) {
        d = siteD;
        err = siteB;
        val = siteV;
        ap.lastSeen = t;
        ap.d = d;
        ap.value = val;
        const aa = (mem.head + err) * D2R;
        ap.x = mem.pos.x + Math.cos(aa) * d;
        ap.y = mem.pos.y + Math.sin(aa) * d;
      } else {
        d = dist(mem.pos.x, mem.pos.y, ap.x, ap.y);
        err = wrap(angleTo(mem.pos.x, mem.pos.y, ap.x, ap.y) - mem.head);
      }

      const sp = Math.abs(vAvg);
      const canDrill = vis || (t - ap.lastSeen < 2.5);

      if (d <= 1.38 && sp < 0.135 && canDrill) {
        wantL = 0;
        wantR = 0;
        drillCmd = true;
        if (!mem.drillStart) mem.drillStart = t;
        if (t - mem.drillStart > 16.5 && carried === 0) {
          drillCmd = false;
          failApproach();
        }
      } else if (d <= 1.75 && sp < 0.16) {
        drillCmd = false;
        if (vis && d > 1.18) {
          const v = 0.052;
          const om = clamp(err * 0.014, -0.11, 0.11);
          setDrive(v, om);
        } else {
          wantL = 0;
          wantR = 0;
        }
      } else {
        drillCmd = false;
        if (!vis && t - ap.lastSeen > 6.0 && d > 2.5) {
          failApproach();
        } else if (t - ap.start > 85.0) {
          failApproach();
        } else {
          let vmax = 0.30;
          if (d > 5.0) vmax = 0.35;
          if (d < 2.8) vmax = 0.15;
          if (battery < 0.20) vmax = Math.min(vmax, 0.22);

          if (vis) driveRel(err, d, vmax);
          else driveToPoint(ap.x, ap.y, vmax);
        }
      }

      if (!drillCmd && d > 1.75) mem.drillStart = 0;
    }
  }

  if (mem.state === "return") {
    drillCmd = false;
    const bd = distToBase;

    if (carried > 0) {
      const useBeacon = beaconValid && beaconD < 20;
      if (obs.docked || bd < 2.55) {
        wantL = 0;
        wantR = 0;
        if (!mem.deliveryWaitT) mem.deliveryWaitT = t;

        if (!obs.docked && bd > 1.65 && t - mem.deliveryWaitT > 2.5) {
          let err, dd;
          if (useBeacon) {
            err = beaconB;
            dd = beaconD;
          } else {
            err = wrap(angleTo(mem.pos.x, mem.pos.y, mem.base.x, mem.base.y) - mem.head);
            dd = bd;
          }
          driveRel(err, dd, 0.075);
        }
      } else {
        mem.deliveryWaitT = 0;
        let err, dd;
        if (useBeacon) {
          err = beaconB;
          dd = beaconD;
        } else {
          err = wrap(angleTo(mem.pos.x, mem.pos.y, mem.base.x, mem.base.y) - mem.head);
          dd = bd;
        }
        let v = 0.39;
        if (dd < 12) v = 0.30;
        if (dd < 6) v = 0.18;
        if (dd < 3.5) v = 0.10;
        if (battery < 0.15) v = Math.min(v, 0.22);
        driveRel(err, dd, v);
      }
    } else {
      const useBeacon = beaconValid && beaconD < 20;
      if (obs.docked || bd < 3.0) {
        wantL = 0;
        wantR = 0;
        if (battery < 0.86 && timeLeft > 55) {
          mem.state = "charge";
          mem.chargeStart = t;
          mem.chargeTarget = Math.min(0.95, Math.max(0.70, battery + 0.24));
        } else {
          mem.state = "choose";
        }
      } else {
        let err, dd;
        if (useBeacon) {
          err = beaconB;
          dd = beaconD;
        } else {
          err = wrap(angleTo(mem.pos.x, mem.pos.y, mem.base.x, mem.base.y) - mem.head);
          dd = bd;
        }
        let v = 0.35;
        if (dd < 8) v = 0.22;
        if (dd < 4) v = 0.10;
        driveRel(err, dd, v);
      }
    }
  }

  if (mem.state === "charge") {
    wantL = 0;
    wantR = 0;
    drillCmd = false;
    if (!mem.chargeStart) mem.chargeStart = t;

    const bd = distToBase;
    if (bd > 3.3 && !obs.docked) {
      mem.state = "return";
    } else if (battery >= mem.chargeTarget || timeLeft < 28 ||
               (t - mem.chargeStart > 32 && battery < 0.12)) {
      mem.state = "choose";
    }
  }

  if (mem.state === "explore") {
    const p = mem.exploreTarget;
    if (!p || p.done) {
      mem.state = "choose";
    } else {
      const d = dist(mem.pos.x, mem.pos.y, p.x, p.y);
      if (d < 2.6) {
        p.done = true;
        mem.state = "choose";
      } else if (timeLeft < d / 0.30 + 45) {
        p.done = true;
        mem.state = "choose";
      } else {
        let vmax = 0.35;
        if (d < 5) vmax = 0.23;
        driveToPoint(p.x, p.y, vmax);
      }
    }
  }

  if (mem.state === "idle") {
    wantL = 0;
    wantR = 0;
    drillCmd = false;
  }

  if (t < mem.recoverUntil &&
      mem.state !== "drill" &&
      !(carried > 0 && distToBase < 2.9)) {
    const elapsed = t - mem.recoverStart;
    drillCmd = false;
    if (elapsed < 0.55) {
      setDrive(-0.115, 0);
    } else {
      setDrive(0, (mem.recoverSide || 1) * 0.82);
    }
  }

  mem.lastCmdMag = Math.max(Math.abs(wantL), Math.abs(wantR));

  function motorCtrl(target, actual, st, pitchDeg) {
    target = clamp(Number(target) || 0, -0.46, 0.46);
    actual = Number(actual) || 0;
    if (!isFinite(st.cmd)) st.cmd = 0;
    if (!isFinite(st.gain) || st.gain < 0.35) st.gain = 1.2;
    if (!isFinite(st.dz)) st.dz = 0.04;
    if (!isFinite(st.intg)) st.intg = 0;

    const prev = st.cmd;

    if (Math.abs(prev) > 0.08 && Math.abs(actual) > 0.03 && prev * actual > 0) {
      const g = Math.abs(actual) / Math.abs(prev);
      if (g > 0.15 && g < 8.0) {
        st.gain = clamp(st.gain * 0.985 + g * 0.015, 0.35, 6.0);
      }
    }

    if (actual > 0.48) {
      st.intg *= 0.5;
      st.cmd = clamp(prev - 0.25, -0.8, 0.8);
      return Math.min(st.cmd, -0.16);
    }
    if (actual < -0.48) {
      st.intg *= 0.5;
      st.cmd = clamp(prev + 0.25, -0.8, 0.8);
      return Math.max(st.cmd, 0.16);
    }

    const err = target - actual;
    const slope = Math.sin(clamp(pitchDeg || 0, -30, 30) * D2R) * 0.05;

    if (Math.abs(target) < 0.015) {
      st.intg += err * 0.22 * dt;
      st.intg = clamp(st.intg, -0.20, 0.20);
      let u = -actual * 1.35 + slope + st.intg;
      const maxStep = 0.15;
      st.cmd = clamp(prev + clamp(u - prev, -maxStep, maxStep), -0.58, 0.58);
      return st.cmd;
    }

    st.intg += err * 0.25 * dt;
    st.intg = clamp(st.intg, -0.24, 0.24);

    const ff = target / Math.max(0.35, st.gain);
    let u = ff + err * 0.45 + st.intg + slope;
    if (Math.abs(target) > 0.018) {
      u += (target > 0 ? 1 : -1) * st.dz;
    }

    let maxStep = 0.05;
    if (target * actual < 0 && Math.abs(actual) > 0.06) maxStep = 0.14;
    st.cmd = clamp(prev + clamp(u - prev, -maxStep, maxStep), -0.80, 0.80);
    return st.cmd;
  }

  let uL = motorCtrl(wantL, wl, mem.wheelL, pitch);
  let uR = motorCtrl(wantR, wr, mem.wheelR, pitch);

  if (wl > 0.48) uL = Math.min(uL, -0.25);
  if (wr > 0.48) uR = Math.min(uR, -0.25);
  if (wl < -0.48) uL = Math.max(uL, 0.25);
