        mem.recoverStart = t;
        mem.recoverUntil = t + 1.0;
        let lsum = 0, rsum = 0;
        for (let i = 0; i < 9; i++) {
          if (i >= 6) lsum += Math.min(rays[i], 6);
          else if (i <= 2) rsum += Math.min(rays[i], 6);
        }
        mem.recoverSide = lsum >= rsum ? 1 : -1;
        if (mem.state === "search" && mem.search && mem.search.current) {
          mem.search.current.visited = true;
          mem.search.current = null;
          mem.search.blocked = (mem.search.blocked || 0) + 1;
        }
        if (mem.state === "goto" && mem.currentHint) {
