    v = Number(v);
    omega = Number(omega);
    if (!isFinite(v)) v = 0;
    if (!isFinite(omega)) omega = 0;
    v = clamp(v, -0.50, 0.50);
    omega = clamp(omega, -1.20, 1.20);

    const ignore = t < mem.ignoreRaysUntil;
    let minF = 15, minWide = 15;
    let leftClear = 0, rightClear = 0;

    if (!ignore) {
      minF = Math.min(rays[3], rays[4], rays[5]);
      minWide = Math.min(rays[2], rays[3], rays[4], rays[5], rays[6]);
      for (let i = 0; i < 9; i++) {
        let d = rays[i];
        if (!isFinite(d)) d = 15;
        d = Math.min(d, 8);
        if (i >= 6) leftClear += d;
        else if (i <= 2) rightClear += d;
      }
    }

    if (v > 0.01 && !ignore) {
      if (minWide < 2.2) {
