        if (minWide < 1.2) fac *= 0.55;
        v *= fac;
      }

      if (minF < 1.45) {
        let side = leftClear >= rightClear ? 1 : -1;
        let w = (1.45 - minF) / 1.45;
        omega += side * w * 0.95;
        if (minF < 0.80) {
          v = Math.min(v, 0.025);
          if (minF < 0.45) v = -0.055;
        }
      }

      for (let i = 0; i < 9; i++) {
        let d = rays[i];
        if (d < 1.15) {
          const rel = (i - 4) * 20;
          const w = (1.15 - d) / 1.15;
          if (rel > 5) omega -= w * 0.55;
          else if (rel < -5) omega += w * 0.55;
        }
      }
    }

    const bdAhead = boundaryDistance(0);
    if (v > 0.01 && bdAhead < 2.8) {
      const inward = angleTo(mem.pos.x, mem.pos.y, mem.sizeX * 0.5, mem.sizeY * 0.5);
      const ie = wrap(inward - mem.head);
      omega = clamp(omega * 0.4 + ie * 0.025 + (2.8 - bdAhead) * 0.18, -1.2, 1.2);
      v = Math.min(v, 0.055 + Math.max(0, bdAhead - 1.0) * 0.16);
    }

    const edge = Math.min(mem.pos.x, mem.sizeX - mem.pos.x, mem.pos.y, mem.sizeY - mem.pos.y);
    if (edge < 1.4) {
      const inward = angleTo(mem.pos.x, mem.pos.y, mem.sizeX * 0.5, mem.sizeY * 0.5);
      const ie = wrap(inward - mem.head);
      omega = clamp(omega + ie * 0.030, -1.2, 1.2);
      v = Math.min(v, 0.07);
      if (v < 0) v = Math.max(v, -0.03);
    }

    if (pitch > 22) v = Math.min(v, 0.18);
    if (pitch < -22) v = Math.min(v, 0.20);
    if (battery < 0.10) v = Math.min(v, 0.20);

    v = clamp(v, -0.50, 0.50);
    omega = clamp(omega, -1.20, 1.20);

    let targetL = v - omega * 0.30;
    let targetR = v + omega * 0.30;
    targetL = clamp(targetL, -0.55, 0.55);
    targetR = clamp(targetR, -0.55, 0.55);

    mem.wantL = targetL;
    mem.wantR = targetR;
    mem.lastWantMag = Math.max(Math.abs(targetL), Math.abs(targetR));
  }

  function driveToPoint(tx, ty, vmax) {
    const d = dist(mem.pos.x, mem.pos.y, tx, ty);
    const ang = angleTo(mem.pos.x, mem.pos.y, tx, ty);
    const err = wrap(ang - mem.head);
    let v = vmax;

    if (Math.abs(err) > 105) v = Math.min(v, 0.025);
    else if (Math.abs(err) > 65) v = Math.min(v, 0.10);
    else if (Math.abs(err) > 40) v = Math.min(v, 0.18);
    else if (Math.abs(err) > 22) v = Math.min(v, 0.28);

    if (d < 3.0) v *= clamp((d - 0.45) / 2.55, 0.10, 1.0);
    else if (d < 7.0) v *= 0.85;

    let om = clamp(err * 0.025, -1.0, 1.0);
    setDrive(v, om);
    return d;
  }

  function driveToBearing(relBearing, d, vmax) {
    const err = wrap(relBearing);
    let v = vmax;

    if (Math.abs(err) > 100) v = Math.min(v, 0.020);
    else if (Math.abs(err) > 60) v = Math.min(v, 0.075);
    else if (Math.abs(err) > 35) v = Math.min(v, 0.15);
    else if (Math.abs(err) > 18) v = Math.min(v, 0.25);

    if (d < 2.6) v *= clamp((d - 0.40) / 2.20, 0.08, 1.0);
    else if (d < 5.5) v *= 0.82;

    let om = clamp(err * 0.022, -1.0, 1.0);
    setDrive(v, om);
  }

  function chooseHint() {
    let best = null, bestScore = -1e99;
    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (h.status !== 0) continue;

      const d = dist(mem.pos.x, mem.pos.y, h.x, h.y);
      const db = dist(h.x, h.y, mem.base.x, mem.base.y);
      const val = h.val > 0 ? h.val : 1;

      const roughTime = (d + db) / 0.32 + 115;
      if (timeLeft < roughTime) continue;
      if (battery < 0.11 && db > 15) continue;

      let score;
      if (mem.deliveredSamples === 0) {
        score = 1.0 / (d + 0.25 * db + 8.0);
        score *= 1.0 + 0.055 * Math.min(val, 7);
      } else {
        score = (val + 0.4) / (d + 0.35 * db + 35.0);
      }
      if (h.attempts > 0) score *= 0.55;
      if (timeLeft < 300) score *= 1.0 / (1.0 + db / 240.0);

      if (score > bestScore) {
        bestScore = score;
        best = h;
      }
    }
    return best;
  }

  function makeSearchPoints(cx, cy, refine) {
    const pts = [];
    const radii = refine ? [0, 5, 10, 15] : [0, 7, 14, 21];

    for (let ri = 0; ri < radii.length; ri++) {
      const r = radii[ri];
      if (r === 0) {
        if (cx > 2.0 && cx < mem.sizeX - 2.0 && cy > 2.0 && cy < mem.sizeY - 2.0) {
          pts.push({ x: cx, y: cy, visited: false });
        }
      } else {
        let n = Math.max(5, Math.round((2 * PI * r) / (refine ? 7.0 : 9.0)));
        for (let j = 0; j < n; j++) {
          const a = (j / n) * 2 * PI + ri * 0.37;
          const px = cx + Math.cos(a) * r;
          const py = cy + Math.sin(a) * r;
          if (px > 2.0 && px < mem.sizeX - 2.0 && py > 2.0 && py < mem.sizeY - 2.0) {
            pts.push({ x: px, y: py, visited: false });
          }
        }
      }
    }

    if (!pts.length) {
      pts.push({
        x: clamp(cx, 3, mem.sizeX - 3),
        y: clamp(cy, 3, mem.sizeY - 3),
        visited: false
      });
    }

    // greedy ordering from the current position
    const rem = pts.slice();
    const out = [];
    let curX = mem.pos.x, curY = mem.pos.y;
    while (rem.length && out.length < 34) {
      let bi = 0, bd = 1e99;
      for (let i = 0; i < rem.length; i++) {
        const dd = dist(curX, curY, rem[i].x, rem[i].y);
        if (dd < bd) {
          bd = dd;
          bi = i;
        }
      }
      const p = rem.splice(bi, 1)[0];
      out.push(p);
      curX = p.x;
      curY = p.y;
    }
    return out;
  }

  function startSearch(h) {
    mem.currentHint = h;
    h.attempts++;
    mem.search = {
      h: h,
      pts: makeSearchPoints(h.x, h.y, false),
      current: null,
      curStart: t,
      start: t,
      deadline: t + (mem.deliveredSamples === 0 ? 155 : 95),
      bestSci: science,
      bestPos: { x: mem.pos.x, y: mem.pos.y },
      refined: false,
      blocked: 0
    };
    mem.approach = null;
    mem.drillStart = 0;
    mem.state = "search";
  }

  function failSearch(mark) {
    if (mem.search && mem.search.h && mark) mem.search.h.status = 2;
    mem.search = null;
    mem.approach = null;
    mem.drillStart = 0;
    mem.currentHint = null;
    mem.state = "choose";
  }

  function failApproach() {
    mem.approach = null;
    mem.drillStart = 0;
    if (mem.search && mem.currentHint && t < mem.search.deadline && mem.currentHint.status === 0) {
      mem.state = "search";
    } else if (mem.currentHint && mem.currentHint.status === 0) {
      mem.state = "goto";
    } else {
      mem.state = "choose";
    }
  }

  function chooseExplorePoint() {
    if (!mem.explorePts) {
      mem.explorePts = [];
      const step = 55;
      for (let x = 30; x < mem.sizeX - 15; x += step) {
        for (let y = 30; y < mem.sizeY - 15; y += step) {
          mem.explorePts.push({ x: x, y: y, done: false });
        }
      }
      if (!mem.explorePts.length) {
        mem.explorePts.push({ x: mem.sizeX * 0.5, y: mem.sizeY * 0.5, done: false });
      }
    }

    for (let i = 0; i < mem.explorePts.length; i++) {
      const p = mem.explorePts[i];
      if (!p.done && dist(mem.pos.x, mem.pos.y, p.x, p.y) < 9.0) p.done = true;
    }

    let best = null, bestScore = 1e99;
    for (let i = 0; i < mem.explorePts.length; i++) {
      const p = mem.explorePts[i];
      if (p.done) continue;
      const d = dist(mem.pos.x, mem.pos.y, p.x, p.y);
      const db = dist(p.x, p.y, mem.base.x, mem.base.y);
      if (timeLeft < (d + db) / 0.30 + 50) {
        p.done = true;
        continue;
      }
      let score = d + 0.15 * db;
      if (score < bestScore) {
        bestScore = score;
        best = p;
      }
    }
    return best;
  }

  let wantDrill = false;
  mem.wantL = 0;
  mem.wantR = 0;
  mem.lastWantMag = 0;

  // recovery overrides normal driving
  if (t < mem.recoverUntil &&
      mem.state !== "drill" &&
      !(c > 0 && distToBase < 3.0)) {
    const elapsed = t - mem.recoverStart;
    wantDrill = false;
    if (elapsed < 0.45) {
      setDrive(-0.075, 0);
    } else {
      setDrive(0, (mem.recoverSide || chooseTurnSide()) * 0.75);
    }
  } else {
    // if we see a site while not carrying, approach it directly
    if (siteValid && c < mem.capacity && c === 0 &&
        mem.state !== "return" && mem.state !== "charge" &&
        mem.state !== "drill" && mem.state !== "idle" &&
        mem.state !== "approach") {
      const aa = (mem.head + siteB) * D2R;
      mem.approach = {
        x: mem.pos.x + Math.cos(aa) * siteD,
        y: mem.pos.y + Math.sin(aa) * siteD,
        lastSeen: t,
        start: t,
        lastD: siteD,
        lastB: siteB,
        value: siteV,
        prevState: mem.state
      };
      mem.state = "approach";
      mem.drillStart = 0;
    }

    if (mem.state === "choose") {
      if (c > 0) {
        mem.state = "return";
      } else if (timeLeft < 24) {
        mem.state = "idle";
      } else if (battery < 0.105) {
        if (distToBase < 3.5) {
          mem.state = "charge";
          mem.chargeStart = t;
          mem.chargeTarget = Math.min(0.88, battery + 0.24);
        } else {
          mem.state = "return";
        }
      } else if (distToBase < 3.0 && battery < 0.48 && timeLeft > 130) {
        mem.state = "charge";
        mem.chargeStart = t;
        mem.chargeTarget = Math.min(0.88, Math.max(0.70, battery + 0.22));
      } else {
        const h = chooseHint();
        if (h) {
          mem.currentHint = h;
          mem.search = null;
          mem.approach = null;
          mem.drillStart = 0;
          mem.state = "goto";
        } else {
          const p = chooseExplorePoint();
          if (p) {
            mem.exploreTarget = p;
            mem.currentHint = null;
            mem.search = null;
            mem.approach = null;
            mem.drillStart = 0;
            mem.state = "explore";
          } else if (distToBase > 3.0 && battery < 0.50) {
            mem.state = "return";
          } else {
            mem.state = "idle";
          }
        }
      }
    }

    if (mem.state === "goto") {
      const h = mem.currentHint;
      if (!h || h.status !== 0) {
        mem.state = "choose";
      } else {
        const d = dist(mem.pos.x, mem.pos.y, h.x, h.y);
        const db = dist(h.x, h.y, mem.base.x, mem.base.y);

        if (d < 11.0) {
          startSearch(h);
        } else if (timeLeft < d / 0.30 + 55) {
          h.status = 2;
          mem.currentHint = null;
          mem.state = "choose";
        } else {
          let vmax = 0.46;
          if (d < 30) vmax = 0.38;
          if (d < 16) vmax = 0.30;
          if (battery < 0.20) vmax = Math.min(vmax, 0.30);
          if (timeLeft < 260) vmax = Math.min(0.46, vmax + 0.02);
          driveToPoint(h.x, h.y, vmax);
        }
      }
    }

    if (mem.state === "search") {
      const s = mem.search;
      if (!s) {
        mem.state = "choose";
      } else {
        if (science > s.bestSci + 1e-9) {
          s.bestSci = science;
          s.bestPos = { x: mem.pos.x, y: mem.pos.y };
        }

        if (t > s.deadline) {
          failSearch(true);
        } else {
          if (!s.current) {
            let best = null, bd = 1e99;
            for (let i = 0; i < s.pts.length; i++) {
              const p = s.pts[i];
              if (p.visited) continue;
              const dd = dist(mem.pos.x, mem.pos.y, p.x, p.y);
              if (dd < bd) {
                bd = dd;
                best = p;
              }
            }

            if (!best) {
              if (!s.refined && timeLeft > 55) {
                s.pts = makeSearchPoints(s.bestPos.x, s.bestPos.y, true);
                s.current = null;
                s.refined = true;
                s.start = t;
                s.deadline = t + 85;
                s.blocked = 0;
              } else {
                failSearch(true);
              }
            } else {
              s.current = best;
              s.curStart = t;
            }
          }

          if (mem.state === "search" && s.current) {
            const p = s.current;
            const d = dist(mem.pos.x, mem.pos.y, p.x, p.y);
            if (d < 1.15) {
              p.visited = true;
              s.current = null;
            } else if (t - s.curStart > 22.0) {
              p.visited = true;
              s.current = null;
              s.blocked = (s.blocked || 0) + 1;
              if (s.blocked > 4) failSearch(true);
            } else {
              let vmax = 0.38;
              if (d < 4.0) vmax = 0.22;
              if (battery < 0.18) vmax = Math.min(vmax, 0.24);
              driveToPoint(p.x, p.y, vmax);
            }
          }
        }
      }
    }

    if (mem.state === "approach") {
      const ap = mem.approach;
      if (!ap) {
        mem.state = mem.search ? "search" : (mem.currentHint ? "goto" : "choose");
      } else {
        let visible = false;
        let d = 1e9, b = 0;

        if (siteValid) {
          visible = true;
          d = siteD;
          b = siteB;
          ap.lastSeen = t;
          ap.lastD = d;
          ap.lastB = b;
          const aa = (mem.head + b) * D2R;
          ap.x = mem.pos.x + Math.cos(aa) * d;
          ap.y = mem.pos.y + Math.sin(aa) * d;
        } else {
          d = dist(mem.pos.x, mem.pos.y, ap.x, ap.y);
          b = wrap(angleTo(mem.pos.x, mem.pos.y, ap.x, ap.y) - mem.head);
        }

        const sp = Math.abs(vAvg);

        if (d <= 1.42 && sp < 0.125) {
          mem.state = "drill";
          mem.drillStart = t;
          setDrive(0, 0);
          wantDrill = d <= 1.48;
        } else if (d <= 1.72) {
          wantDrill = false;
          if (sp > 0.18) {
            setDrive(0, 0);
          } else {
            const vv = visible ? 0.042 : 0.050;
            const oo = clamp(b * 0.018, -0.12, 0.12);
            setDrive(vv, oo);
          }
        } else {
          wantDrill = false;
          if (!visible && t - ap.lastSeen > 3.0 && d > 2.8) {
            failApproach();
          } else if (t - ap.start > 92.0) {
            failApproach();
          } else {
            let vmax = 0.31;
            if (d > 6.0) vmax = 0.38;
            if (d < 3.0) vmax = 0.16;
            if (visible) driveToBearing(b, d, vmax);
            else driveToPoint(ap.x, ap.y, vmax);
          }
        }
      }
    }

    if (mem.state === "drill") {
      const ap = mem.approach;
      if (!ap) {
        mem.state = "approach";
      } else {
        let d = 1e9;
        if (siteValid) {
          d = siteD;
          const aa = (mem.head + siteB) * D2R;
          ap.x = mem.pos.x + Math.cos(aa) * siteD;
          ap.y = mem.pos.y + Math.sin(aa) * siteD;
          ap.lastSeen = t;
        } else {
          d = dist(mem.pos.x, mem.pos.y, ap.x, ap.y);
        }

        const sp = Math.abs(vAvg);
        setDrive(0, 0);

        if (d <= 1.50 && sp < 0.145) {
          wantDrill = true;
        } else {
          wantDrill = false;
        }

        if (d > 1.60) {
          wantDrill = false;
          mem.state = "approach";
          mem.drillStart = 0;
        } else if (t - mem.drillStart > 14.0 && c === mem.lastCarried) {
          wantDrill = false;
          mem.state = "approach";
          mem.drillStart = 0;
          ap.start = t - 70;
          ap.lastSeen = t;
        }
      }
    }

    if (mem.state === "return") {
      wantDrill = false;

      if (c > 0) {
        let useBeacon = beaconValid && beaconD < 20;
        let dd = distToBase;
        let bb = wrap(angleTo(mem.pos.x, mem.pos.y, mem.base.x, mem.base.y) - mem.head);
        if (useBeacon) {
          dd = beaconD;
          bb = beaconB;
        }

        if (obs.docked || dd < 2.55) {
          setDrive(0, 0);
          if (!mem.deliveryWait) mem.deliveryWait = t;

          if (!obs.docked && dd > 1.65 && t - mem.deliveryWait > 3.0) {
            driveToBearing(bb, dd, 0.085);
          }
        } else {
          mem.deliveryWait = 0;
          let vmax = 0.45;
          if (dd < 13) vmax = 0.32;
          if (dd < 6) vmax = 0.19;
          if (dd < 3.6) vmax = 0.10;
          if (battery < 0.14) vmax = Math.min(vmax, 0.24);
          if (useBeacon) driveToBearing(bb, dd, vmax);
          else driveToPoint(mem.base.x, mem.base.y, vmax);
        }
      } else {
        let useBeacon = beaconValid && beaconD < 20;
        let dd = distToBase;
        let bb = wrap(angleTo(mem.pos.x, mem.pos.y, mem.base.x, mem.base.y) - mem.head);
        if (useBeacon) {
          dd = beaconD;
          bb = beaconB;
        }

        if (obs.docked || dd < 3.0) {
          setDrive(0, 0);
          if (battery < 0.82 && timeLeft > 55) {
            mem.state = "charge";
            mem.chargeStart = t;
            mem.chargeTarget = Math.min(0.94, Math.max(0.70, battery + 0.24));
          } else {
            mem.state = "choose";
          }
        } else {
          let vmax = 0.40;
          if (dd < 10) vmax = 0.25;
          if (dd < 4.5) vmax = 0.11;
          if (useBeacon) driveToBearing(bb, dd, vmax);
          else driveToPoint(mem.base.x, mem.base.y, vmax);
        }
      }
    }

    if (mem.state === "charge") {
      wantDrill = false;
      setDrive(0, 0);
      if (!mem.chargeStart) mem.chargeStart = t;

      if (distToBase > 3.3 && !obs.docked) {
        mem.state = "return";
      } else if (battery >= mem.chargeTarget || timeLeft < 30 ||
                 (t - mem.chargeStart > 38 && battery < 0.12)) {
        mem.state = "choose";
      }
    }

    if (mem.state === "explore") {
      wantDrill = false;
      const p = mem.exploreTarget;
      if (!p) {
        mem.state = "choose";
      } else {
        const d = dist(mem.pos.x, mem.pos.y, p.x, p.y);
        if (d < 2.8) {
          p.done = true;
          mem.state = "choose";
        } else if (timeLeft < d / 0.30 + 45) {
          p.done = true;
          mem.state = "choose";
        } else {
          let vmax = 0.36;
          if (d < 6.0) vmax = 0.24;
          driveToPoint(p.x, p.y, vmax);
        }
      }
    }

    if (mem.state === "idle") {
      wantDrill = false;
      setDrive(0, 0);
      if (c > 0) mem.state = "return";
      else if (timeLeft > 75 && battery > 0.55 && mem.deliveredSamples > 0) {
        mem.state = "choose";
      }
    }

    if (mem.state === "calib") {
      wantDrill = false;
      setDrive(0, 0);
    }
  }

  function controlWheel(target, actual, st) {
    if (!isFinite(target)) target = 0;
    if (!isFinite(actual)) actual = 0;
    target = clamp(target, -0.55, 0.55);

    if (!st.signKnown) {
      if (!isFinite(st.sign)) st.sign = 1;
    }
    let sign = st.sign || 1;

    const err = target - actual;

    st.int += clamp(err, -1.2, 1.2) * 0.55 * dt;
    st.int = clamp(st.int, -0.55, 0.55);

    let cCmd = err * 0.30 + st.int + target * 0.10;

    if (actual > 0.58) {
      cCmd = Math.min(cCmd, -0.20 - (actual - 0.58) * 1.8);
      st.int *= 0.55;
    } else if (actual < -0.58) {
      cCmd = Math.max(cCmd, 0.20 + (-0.58 - actual) * 1.8);
      st.int *= 0.55;
    }

    if (st.autoFlip) {
      let opp = false;
      if (target > 0.12 && actual < -0.055 && cCmd > 0.02) opp = true;
      if (target < -0.12 && actual > 0.055 && cCmd < -0.02) opp = true;
      if (opp) st.opp += dt;
      else st.opp = Math.max(0, st.opp - dt * 1.2);

      if (st.opp > 1.8) {
        st.sign = -sign;
        st.opp = 0;
        st.int = 0;
        sign = st.sign;
        cCmd = 0;
      }
    }

    cCmd = clamp(cCmd, -0.90, 0.90);
    let u = sign * cCmd;

    // hard absolute wheel-speed limiter
    if (actual > 0.78) u = Math.min(u, -0.35);
    else if (actual < -0.78) u = Math.max(u, 0.35);

    if (!isFinite(u)) u = 0;
    st.lastU = u;
    return clamp(u, -1, 1);
  }

  const uL = controlWheel(mem.wantL, wl, mem.wheelL);
  const uR = controlWheel(mem.wantR, wr, mem.wheelR);

  return {
    left: clamp(uL, -1, 1),
    right: clamp(uR, -1, 1),
    drill: !!wantDrill
  };
}

const ANG = [-80, -60, -40, -20, 0, 20, 40, 60, 80];
const SOFF = [[7, 0], [7, 7], [0, 7], [-7, 7], [-7, 0], [-7, -7], [0, -7], [7, -7], [0, 0]];
const VMAX = 0.7;

function wrap(a) { return ((a + 180) % 360 + 360) % 360 - 180; }
function rad(d) { return d * Math.PI / 180; }
function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
function hyp(ax, ay, bx, by) { return Math.hypot(ax - bx, ay - by); }

function init(obs, mem) {
  const m = obs.mission || {};
  mem.init = true;
  mem.size = m.size || 400;
  mem.base = (m.base && isFinite(m.base.x)) ? { x: m.base.x, y: m.base.y } : { x: obs.x, y: obs.y };
  mem.cap = m.capacity || 5;
  mem.hints = (m.hints || []).map((h, i) => ({ i: i, x: h.x, y: h.y, est: (h.estimate > 0 ? h.estimate : 1), done: false, fails: 0 }));
  mem.off = 0; mem.offInit = false;
  mem.hist = [];
  mem.mode = 'nav';
  mem.goal = null; mem.search = null;
  mem.drilling = false; mem.drillTicks = 0; mem.drillAbs = null;
  mem.backT = 0; mem.backL = 0; mem.backR = 0;
  mem.lastBumped = false;
  mem.sw = null;
  mem.tick = 0;
  mem.approachTicks = 0;
  mem.doneSites = [];
  mem.dockT = 0;
  mem.cell = 25;
  mem.n = Math.ceil(mem.size / mem.cell);
  mem.vis = new Array(mem.n * mem.n).fill(false);
}

function updateHeading(obs, mem) {
  const h = mem.hist, n = h.length;
  if (n < 21) return;
  const o = h[n - 21], mid = h[n - 11];
  const dx = obs.x - o.x, dy = obs.y - o.y, d = Math.hypot(dx, dy);
  const wl = obs.wheelLeft || 0, wr = obs.wheelRight || 0;
  if (d > 2.5 && d < 7 && (wl + wr) / 2 > 0.5 && Math.abs(wl - wr) < 0.15) {
    const track = Math.atan2(dy, dx) * 180 / Math.PI;
    const offM = wrap(track - mid.c);
    if (!mem.offInit) { mem.off = offM; mem.offInit = true; }
    else mem.off = wrap(mem.off + 0.05 * wrap(offM - mem.off));
  }
}

function markCells(obs, mem) {
  const n = mem.n, c = mem.cell;
  for (let i = 0; i < n; i++) for (let j = 0; j < n; j++) {
    const k = i * n + j;
    if (mem.vis[k]) continue;
    if (hyp(obs.x, obs.y, (i + 0.5) * c, (j + 0.5) * c) < 15) mem.vis[k] = true;
  }
}

function isDone(mem, p) {
  for (const d of mem.doneSites) if (hyp(p.x, p.y, d.x, d.y) < 5) return true;
  return false;
}

function markHintsNear(mem, p) {
  for (const h of mem.hints) if (hyp(h.x, h.y, p.x, p.y) < 20) h.done = true;
}

function needReturn(obs, mem, dB, carried) {
  if (carried >= mem.cap) return true;
  if (carried > 0) {
    if (obs.timeLeft < dB / 0.8 + 60) return true;
    if ((obs.battery || 0) < 0.3) return true;
  }
  if ((obs.battery || 0) < 0.15) return true;
  return false;
}

function chooseGoal(obs, mem) {
  let best = null, bs = -1;
  for (const h of mem.hints) {
    if (h.done) continue;
    const d = hyp(obs.x, obs.y, h.x, h.y), dT = hyp(h.x, h.y, mem.base.x, mem.base.y);
    if ((d + dT) / 0.8 + 30 > obs.timeLeft) continue;
    const sc = h.est / (d + 30);
    if (sc > bs) { bs = sc; best = h; }
  }
  if (best) return { type: 'hint', i: best.i, x: best.x, y: best.y, t0: mem.tick };
  const n = mem.n, c = mem.cell;
  let bd = 1e9, bc = null;
  for (let i = 0; i < n; i++) for (let j = 0; j < n; j++) {
    if (mem.vis[i * n + j]) continue;
    const cx = (i + 0.5) * c, cy = (j + 0.5) * c;
    const d = hyp(obs.x, obs.y, cx, cy);
    if (d < bd) { bd = d; bc = { cx: cx, cy: cy }; }
  }
  if (bc) return { type: 'explore', x: bc.cx, y: bc.cy, t0: mem.tick };
  return null;
}

function failGoal(mem) {
  const g = mem.goal;
  if (!g) return;
  if (g.type === 'hint') {
    mem.hints[g.i].fails++;
    mem.hints[g.i].done = true;
  }
  if (g.type === 'search') {
    if (mem.search) mem.hints.forEach(h => { if (hyp(h.x, h.y, mem.search.cx, mem.search.cy) < 3) h.done = true; });
  }
  if (g.type === 'explore') {
    const n = mem.n, c = mem.cell;
    const i = Math.floor(g.x / c), j = Math.floor(g.y / c);
    if (i >= 0 && j >= 0 && i < n && j < n) mem.vis[i * n + j] = true;
  }
  mem.goal = null;
  mem.search = null;
}

function driveTo(obs, mem, tx, ty, vmax) {
  const hE = obs.heading + mem.off;
  const dx = tx - obs.x, dy = ty - obs.y, d = Math.hypot(dx, dy);
  const brg = Math.atan2(dy, dx) * 180 / Math.PI;
  const err = wrap(brg - hE);
  const r = (obs.rays && obs.rays.length >= 9) ? obs.rays : [15, 15, 15, 15, 15, 15, 15, 15, 15];
  let L = 15, R = 15;
  for (let i = 5; i < 9; i++) L = Math.min(L, r[i]);
  for (let i = 0; i < 4; i++) R = Math.min(R, r[i]);
  let adj = 0;
  for (let i = 0; i < 9; i++) {
    const ri = Math.min(r[i], 15);
    if (ri < 6) {
      const p = (6 - ri) / 6, a = ANG[i];
      if (a > 0) adj -= p * 40;
      else if (a < 0) adj += p * 40;
      else adj += (L >= R ? 1 : -1) * p * 40;
    }
  }
  adj = clamp(adj, -70, 70);
  const e = clamp(err + adj, -180, 180);
  const ae = Math.abs(e);
  let v = ae > 55 ? 0 : vmax * (1 - ae / 70);
  v *= clamp(d / 4, 0.3, 1);
  const f = Math.min(r[3], r[4], r[5]);
  const vcapM = Math.sqrt(1.6 * Math.max(0, f - 1.5));
  v = Math.min(v, vcapM / 3);
  let s = clamp(0.9 * rad(e), -0.8, 0.8);
  if (ae > 8 && Math.abs(s) < 0.2) s = Math.sign(s) * 0.2;
  if (ae > 55 && Math.abs(s) < 0.3) s = Math.sign(s) * 0.3;
  let left = v - s, right = v + s;
  const m = Math.max(Math.abs(left), Math.abs(right));
  if (m > 1) { left /= m; right /= m; }
  return { left: left, right: right };
}

function stuckCheck(obs, mem, cm, wv) {
  if (!mem.sw) mem.sw = { x: obs.x, y: obs.y, n: 0, cs: 0, ws: 0 };
  const S = mem.sw;
  S.n++; S.cs += cm; S.ws += wv;
  if (S.n >= 30) {
    const disp = hyp(obs.x, obs.y, S.x, S.y);
    const stuck = disp < 0.5 && S.cs / S.n > 0.25 && S.ws / S.n < 0.15;
    mem.sw = null;
    return stuck;
  }
  return false;
}

function afterDrive(obs, mem, out, wv) {
  const cm = Math.max(Math.abs(out.left), Math.abs(out.right));
  if (stuckCheck(obs, mem, cm, wv)) {
    const sg = Math.random() < 0.5 ? -1 : 1;
    mem.backT = 20;
    mem.backL = -0.5 - 0.3 * sg;
    mem.backR = -0.5 + 0.3 * sg;
    if (mem.goal) {
      mem.goal.stuck = (mem.goal.stuck || 0) + 1;
      if (mem.goal.stuck >= 3) failGoal(mem);
    }
  }
  return out;
}

function drillStep(obs, mem, out, wl, wr) {
  const dr = obs.drilling || 0;
  mem.drillTicks++;
  const done = dr >= 6.0 || (!obs.site && dr > 5.5);
  const abort = mem.drillTicks > 150 || (mem.drillTicks > 40 && dr < 0.05);
  if (done || abort) {
    if (mem.drillAbs) {
      mem.doneSites.push(mem.drillAbs);
      if (done) markHintsNear(mem, mem.drillAbs);
    }
    mem.drilling = false;
    mem.drillAbs = null;
    if (mem.goal && mem.goal.type === 'hint' && done) mem.goal = null;
    out.drill = false; out.left = 0; out.right = 0;
    return out;
  }
  const vf = (wl + wr) / 2;
  const u = clamp(-0.5 * vf, -0.2, 0.2);
  out.drill = true; out.left = u; out.right = u;
  return out;
}

function step(obs, mem) {
  if (!mem.init) init(obs, mem);
  mem.tick++;
  const out = { left: 0, right: 0, drill: false };
  mem.hist.push({ x: obs.x, y: obs.y, c: obs.heading });
  if (mem.hist.length > 40) mem.hist.shift();
  updateHeading(obs, mem);
  markCells(obs, mem);
  const hE = obs.heading + mem.off;
  const r = (obs.rays && obs.rays.length >= 9) ? obs.rays : [15, 15, 15, 15, 15, 15, 15, 15, 15];
  const wl = obs.wheelLeft || 0, wr = obs.wheelRight || 0;
  const wv = (Math.abs(wl) + Math.abs(wr)) / 2;
  const stationary = wv < 0.12;
  const carried = obs.carried || 0;
  const dB = hyp(obs.x, obs.y, mem.base.x, mem.base.y);

  // bump edge: back off
  const bumpEdge = !!obs.bumped && !mem.lastBumped;
  mem.lastBumped = !!obs.bumped;
  if (bumpEdge) {
    const sg = Math.random() < 0.5 ? -1 : 1;
    mem.backT = 12; mem.backL = -0.4 - 0.25 * sg; mem.backR = -0.4 + 0.25 * sg;
    mem.sw = null;
    if (mem.goal) {
      mem.goal.bumps = (mem.goal.bumps || 0) + 1;
      if (mem.goal.bumps >= 3) failGoal(mem);
    }
  }
  if (mem.backT > 0) {
    mem.backT--;
    out.left = mem.backL; out.right = mem.backR;
    return out;
  }

  if (mem.drilling) return drillStep(obs, mem, out, wl, wr);

  // opportunistic sampling of any visible site
  const needRet = needReturn(obs, mem, dB, carried);
  const site = obs.site;
  if (site && carried < mem.cap && mem.mode !== 'dock') {
    const p = {
      x: obs.x + site.distance * Math.cos(rad(hE + site.bearing)),
      y: obs.y + site.distance * Math.sin(rad(hE + site.bearing))
    };
    if (!isDone(mem, p) && (!needRet || site.distance < 3)) {
      mem.approachTicks++;
      if (mem.approachTicks > 200) {
        mem.doneSites.push(p);
        mem.approachTicks = 0;
      } else {
        if (site.distance <= 1.3) {
          if (stationary) {
            mem.drilling = true; mem.drillTicks = 0; mem.drillAbs = p;
            mem.approachTicks = 0;
            out.drill = true;
          }
          return out;
        }
        const b = site.bearing;
        let v = Math.abs(b) > 35 ? 0 : 0.3;
        if (r[3] < 2.0 || r[4] < 2.0 || r[5] < 2.0) v = 0;
        let s = clamp(0.9 * rad(b), -0.6, 0.6);
        if (Math.abs(b) > 5 && Math.abs(s) < 0.2) s = Math.sign(s) * 0.2;
        out.left = clamp(v - s, -1, 1);
        out.right = clamp(v + s, -1, 1);
        return out;
      }
    } else mem.approachTicks = 0;
  } else mem.approachTicks = 0;

  // docking
  if (mem.mode === 'dock') {
    mem.dockT++;
    if (carried === 0 && ((obs.battery || 0) > 0.5 || obs.timeLeft < 200 || mem.dockT > 400)) {
      mem.mode = 'nav'; mem.dockT = 0; mem.goal = null;
    } else {
      return out;
    }
  }

  let goBase = needRet;
  if (!goBase) {
    if (!mem.goal) mem.goal = chooseGoal(obs, mem);
    if (!mem.goal) goBase = true;
  }

  if (goBase) {
    if (dB < 2.5 || obs.docked) {
      mem.mode = 'dock'; mem.dockT = 0; mem.goal = null; mem.search = null;
      return out;
    }
    const c = driveTo(obs, mem, mem.base.x, mem.base.y, VMAX);
    out.left = c.left; out.right = c.right;
    return afterDrive(obs, mem, out, wv);
  }

  // hint reached: start a search pattern
  let G = mem.goal;
  if (G.type === 'hint' && !mem.search && hyp(obs.x, obs.y, G.x, G.y) < 4) {
    mem.hints[G.i].done = true;
    mem.search = { cx: G.x, cy: G.y, wp: 0, pass: 1, wt: mem.tick, best: { v: -1, x: G.x, y: G.y } };
    mem.goal = { type: 'search', t0: mem.tick };
    G = mem.goal;
    return out;
  }

  let tx, ty;
  if (G.type === 'search') {
    const S = mem.search;
    if (!S) { mem.goal = null; return out; }
    if (obs.science > S.best.v) S.best = { v: obs.science, x: obs.x, y: obs.y };
    if (S.wp >= SOFF.length) {
      if (S.pass === 1 && S.best.v > 0 && hyp(S.best.x, S.best.y, S.cx, S.cy) > 6) {
        S.cx = S.best.x; S.cy = S.best.y; S.wp = 0; S.pass = 2; S.wt = mem.tick;
        S.best = { v: -1, x: S.cx, y: S.cy };
      } else {
        mem.search = null; mem.goal = null;
        return out;
      }
    }
    tx = S.cx + SOFF[S.wp][0];
    ty = S.cy + SOFF[S.wp][1];
    if (hyp(obs.x, obs.y, tx, ty) < 2.5 || mem.tick - S.wt > 250) {
      S.wp++; S.wt = mem.tick;
      return out;
    }
  } else if (G.type === 'hint') {
    tx = G.x; ty = G.y;
    if (mem.tick - G.t0 > 1500) { failGoal(mem); return out; }
  } else {
    tx = G.x; ty = G.y;
    if (hyp(obs.x, obs.y, tx, ty) < 8 || mem.tick - G.t0 > 1500) {
      failGoal(mem); // marks cell visited and clears goal
      return out;
    }
  }
  const c = driveTo(obs, mem, tx, ty, VMAX);
  out.left = c.left; out.right = c.right;
  return afterDrive(obs, mem, out, wv);
}

function act(obs, mem) {
  let o;
  try {
    o = step(obs, mem);
  } catch (e) {
    o = { left: 0, right: 0, drill: false };
  }
  return {
    left: clamp(+o.left || 0, -1, 1),
    right: clamp(+o.right || 0, -1, 1),
    drill: !!o.drill
  };
}

const VMAX = 0.5;

function wrap(a) { return ((a + 180) % 360 + 360) % 360 - 180; }
function rad(d) { return d * Math.PI / 180; }
function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
function dist(ax, ay, bx, by) { return Math.hypot(ax - bx, ay - by); }
function STOP() { return { left: 0, right: 0, drill: false }; }

function init(obs, mem) {
  const m = obs.mission || {};
  mem.init = true;
  mem.base = (m.base && isFinite(m.base.x) && isFinite(m.base.y)) ? { x: m.base.x, y: m.base.y } : { x: obs.x, y: obs.y };
  mem.cap = m.capacity || 5;
  mem.size = m.size || 400;
  mem.hints = (m.hints || []).map((h, i) => ({ i: i, x: h.x, y: h.y, est: (h.estimate > 0 ? h.estimate : 1), state: 0 }));
  mem.off = 0; mem.offInit = false;
  mem.pos = [];
  mem.escT = 0; mem.escDir = 1; mem.lastBump = false;
  mem.lastL = 0; mem.lastR = 0;
  mem.mode = 'pick';
  mem.tgt = null;
  mem.search = null;
  mem.done = [];
  mem.dockT = 0; mem.dockCool = 0;
  mem.dT = 0; mem.dStart = null; mem.dSite = null;
  mem.siteP = null; mem.siteT0 = 0;
  mem.bestD = 1e9; mem.bestT = 0;
  mem.tick = 0;
  mem.cell = 30;
  mem.n = Math.ceil(mem.size / mem.cell);
  mem.vis = new Array(mem.n * mem.n).fill(false);
  mem.stuckN = 0;
}

function startEscape(mem) {
  mem.escT = 20;
  mem.escDir = -mem.escDir;
  mem.pos = [];
  mem.stuckN++;
}

function updateOffset(mem) {
  const P = mem.pos, n = P.length;
  if (n < 31) return;
  const a = P[n - 31], b = P[n - 1];
  const d = dist(a.x, a.y, b.x, b.y);
  if (d < 2.5) return;
  let fw = 0, cs = 0, sn = 0;
  for (let k = n - 30; k < n; k++) {
    fw += (P[k].l + P[k].r) / 2;
    cs += Math.cos(rad(P[k].c));
    sn += Math.sin(rad(P[k].c));
  }
  fw /= 30;
  if (fw < 0.25) return;
  const dh = Math.abs(wrap(b.c - a.c));
  if (dh > 15) return;
  const cm = Math.atan2(sn, cs) * 180 / Math.PI;
  const track = Math.atan2(b.y - a.y, b.x - a.x) * 180 / Math.PI;
  const om = wrap(track - cm);
  if (!mem.offInit) { mem.off = om; mem.offInit = true; }
  else mem.off = wrap(mem.off + 0.05 * wrap(om - mem.off));
}

function stuckNow(mem) {
  const P = mem.pos, n = P.length;
  if (n < 31) return false;
  const a = P[n - 31], b = P[n - 1];
  const disp = dist(a.x, a.y, b.x, b.y);
  let fw = 0;
  for (let k = n - 30; k < n; k++) fw += Math.abs((P[k].l + P[k].r) / 2);
  fw /= 30;
  const dh = Math.abs(wrap(b.c - a.c));
  return disp < 0.4 && dh < 20 && fw > 0.2;
}

function markCells(obs, mem) {
  const n = mem.n, c = mem.cell;
  for (let i = 0; i < n; i++) for (let j = 0; j < n; j++) {
    const k = i * n + j;
    if (mem.vis[k]) continue;
    if (dist(obs.x, obs.y, (i + 0.5) * c, (j + 0.5) * c) < 20) mem.vis[k] = true;
  }
}

function isDone(mem, p) {
  for (const d of mem.done) if (dist(p.x, p.y, d.x, d.y) < 4) return true;
  return false;
}

function markHints(mem, p) {
  for (const h of mem.hints) if (h.state === 0 && dist(h.x, h.y, p.x, p.y) < 20) h.state = 1;
}

function resetProgress(mem) {
  mem.bestD = 1e9; mem.bestT = mem.tick;
}

function pickTarget(obs, mem) {
  let best = null, bs = -1;
  for (const h of mem.hints) {
    if (h.state !== 0) continue;
    const d = dist(obs.x, obs.y, h.x, h.y);
    const dB = dist(h.x, h.y, mem.base.x, mem.base.y);
    if ((d + dB) / 0.35 + 40 > obs.timeLeft - 30) continue;
    const sc = h.est / (d / 0.5 + 30);
    if (sc > bs) { bs = sc; best = h; }
  }
  if (best) return { kind: 'hint', idx: best.i, x: best.x, y: best.y };
  const n = mem.n, c = mem.cell;
  let bd = 1e9, bk = -1, bx = 0, by = 0;
  for (let i = 0; i < n; i++) for (let j = 0; j < n; j++) {
    const k = i * n + j;
    if (mem.vis[k]) continue;
    const cx = (i + 0.5) * c, cy = (j + 0.5) * c;
    const d = dist(obs.x, obs.y, cx, cy);
    if (d < bd) { bd = d; bk = k; bx = cx; by = cy; }
  }
  if (bk >= 0) return { kind: 'explore', idx: bk, x: bx, y: by };
  return null;
}

function failTarget(mem) {
  const tg = mem.tgt;
  if (tg && tg.kind === 'hint') mem.hints[tg.idx].state = 2;
  if (tg && tg.kind === 'explore') mem.vis[tg.idx] = true;
  mem.tgt = null;
  mem.mode = 'pick';
}

function steerCmd(e, d, vmax, r) {
  const F = Math.min(r[3], r[4], r[5]);
  const L = Math.min(r[5], r[6], r[7], r[8]);
  const R = Math.min(r[0], r[1], r[2], r[3]);
  let adj = 0;
  if (F < 4) {
    const p = clamp((4 - F) / 3, 0, 1);
    adj = (L >= R ? 1 : -1) * p * 50;
  }
  const ee = clamp(e + adj, -180, 180);
  const ae = Math.abs(ee);
  let v = vmax * clamp(1 - ae / 60, 0, 1);
  v *= clamp(d / 3, 0.4, 1);
  v = Math.min(v, clamp((F - 0.8) * 0.35, 0, 1));
  let s = clamp(0.8 * rad(ee), -0.6, 0.6);
  if (ae > 5 && Math.abs(s) < 0.15) s = Math.sign(s) * 0.15;
  if (F < 0.8 && Math.abs(s) < 0.25) s = (L >= R) ? 0.3 : -0.3;
  let left = v - s, right = v + s;
  const m = Math.max(Math.abs(left), Math.abs(right));
  if (m > 1) { left /= m; right /= m; }
  return { left: left, right: right };
}

function buildWps(cx, cy) {
  const o = [[0, 0], [6, 0], [6, 6], [0, 6], [-6, 6], [-6, 0], [-6, -6], [0, -6], [6, -6],
             [12, -6], [12, 6], [12, 12], [0, 12], [-12, 12], [-12, 0], [-12, -12], [0, -12], [12, -12]];
  return o.map(p => ({ x: cx + p[0], y: cy + p[1] }));
}

function makeSearch(cx, cy, idx, tick) {
  return { cx: cx, cy: cy, idx: idx, pass: 1, wps: buildWps(cx, cy), k: 0, wt: tick, pt: tick,
           best: { v: -1, x: cx, y: cy } };
}

function searchStep(obs, mem, r, hE) {
  const S = mem.search;
  if (obs.science > S.best.v) S.best = { v: obs.science, x: obs.x, y: obs.y };
  if (mem.tick - S.pt > 500 || S.k >= S.wps.length) {
    if (S.pass === 1 && S.best.v > 0 && dist(S.best.x, S.best.y, S.cx, S.cy) > 6) {
      S.pass = 2; S.cx = S.best.x; S.cy = S.best.y;
      S.wps = buildWps(S.cx, S.cy); S.k = 0; S.wt = mem.tick; S.pt = mem.tick;
      S.best = { v: -1, x: S.cx, y: S.cy };
      return STOP();
    }
    const h = mem.hints[S.idx];
    if (h && h.state === 0) h.state = 2;
    mem.search = null; mem.mode = 'pick'; mem.tgt = null;
    return STOP();
  }
  const w = S.wps[S.k];
  const d = dist(obs.x, obs.y, w.x, w.y);
  if (d < 2 || mem.tick - S.wt > 250) { S.k++; S.wt = mem.tick; return STOP(); }
  const brg = Math.atan2(w.y - obs.y, w.x - obs.x) * 180 / Math.PI;
  const c = steerCmd(wrap(brg - hE), d, VMAX * 0.8, r);
  return { left: c.left, right: c.right, drill: false };
}

function gotoStep(obs, mem, r, hE) {
  const tg = mem.tgt;
  const d = dist(obs.x, obs.y, tg.x, tg.y);
  if (tg.kind === 'hint' && d < 6) {
    mem.search = makeSearch(tg.x, tg.y, tg.idx, mem.tick);
    mem.mode = 'search'; mem.tgt = null;
    return searchStep(obs, mem, r, hE);
  }
  if (tg.kind === 'explore' && d < 4) {
    mem.vis[tg.idx] = true; mem.tgt = null; mem.mode = 'pick';
    return STOP();
  }
  if (tg.kind === 'home' && d < 2.6) return STOP();
  if (d < mem.bestD - 2) { mem.bestD = d; mem.bestT = mem.tick; }
  if (mem.tick - mem.bestT > 400) { failTarget(mem); return STOP(); }
  const brg = Math.atan2(tg.y - obs.y, tg.x - obs.x) * 180 / Math.PI;
  const c = steerCmd(wrap(brg - hE), d, VMAX, r);
  return { left: c.left, right: c.right, drill: false };
}

function siteStep(obs, mem, r, wl, wr, site) {
  if (site.distance <= 1.2) {
    const wv = (Math.abs(wl) + Math.abs(wr)) / 2;
    if (wv < 0.12) {
      mem.mode = 'drill'; mem.dT = 0;
      mem.dStart = { x: obs.x, y: obs.y };
      mem.dSite = mem.siteP;
      return { left: 0, right: 0, drill: true };
    }
    return STOP();
  }
  mem.mode = 'site';
  const c = steerCmd(site.bearing, site.distance, 0.35, r);
  return { left: c.left, right: c.right, drill: false };
}

function drillStep(obs, mem, wl, wr) {
  mem.dT++;
  const dr = obs.drilling || 0;
  const vf = (wl + wr) / 2;
  if (dr >= 6.2) {
    if (mem.dSite) { mem.done.push(mem.dSite); markHints(mem, mem.dSite); }
    mem.mode = mem.search ? 'search' : 'pick';
    mem.tgt = null; mem.siteP = null;
    return STOP();
  }
  const moved = mem.dStart ? dist(obs.x, obs.y, mem.dStart.x, mem.dStart.y) : 0;
  if (mem.dT > 150 || (mem.dT > 40 && dr < 0.05) || moved > 2.5) {
    if (mem.dSite) mem.done.push(mem.dSite);
