}

function step(obs, mem) {
  if (!mem.init) init(obs, mem);
  mem.tick++;
  const r = (obs.rays && obs.rays.length >= 9) ? obs.rays : [15, 15, 15, 15, 15, 15, 15, 15, 15];
  const wl = obs.wheelLeft || 0, wr = obs.wheelRight || 0;
  const carried = obs.carried || 0;
  const battery = obs.battery || 0;

  mem.pos.push({ x: obs.x, y: obs.y, c: obs.heading, l: mem.lastL, r: mem.lastR });
  if (mem.pos.length > 40) mem.pos.shift();
  updateOffset(mem);
  markCells(obs, mem);
  const hE = obs.heading + mem.off;
  const B = mem.base;
  const dB = dist(obs.x, obs.y, B.x, B.y);

  // bumps and stuck handling
  if (obs.bumped && !mem.lastBump) startEscape(mem);
  mem.lastBump = !!obs.bumped;
