    if (mem.search) return searchStep(obs, mem, r, hE);
    mem.mode = 'pick';
  }
  if (mem.mode === 'home') return gotoStep(obs, mem, r, hE);

  if (!mem.tgt) {
    const t = pickTarget(obs, mem);
    if (t) {
      mem.tgt = t; mem.mode = 'goto'; resetProgress(mem);
    } else if (carried > 0) {
      mem.mode = 'home'; mem.tgt = { kind: 'home', x: B.x, y: B.y }; resetProgress(mem);
    } else {
      return STOP();
    }
  }
