    if (T.kind === 'hint') mem.hints[T.i].state = 2;
    else mem.vis[T.i] = true;
    mem.tgt = null; mem.mode = 'pick';
    return setCmd(mem, STOP());
  }
  const e = wrap(deg(Math.atan2(T.y - p.y, T.x - p.x)) - hE);
