  if (b.g > 25) return;
  let a = -1;
  for (let k = n - 30; k >= 0 && k >= n - 400; k--) {
    if (dist(H[k].px, H[k].py, b.px, b.py) >= 12) { a = k; break; }
  }
  if (a < 0) return;
  let mn = 1e9, mx = -1e9, cs = 0, sn = 0, ws = 0, cnt = 0, gmax = 0;
  const c0 = H[a].c;
  for (let k = a; k < n; k++) {
    const h = H[k];
    const rel = wrap(h.c - c0);
    if (rel < mn) mn = rel;
    if (rel > mx) mx = rel;
    cs += Math.cos(rad(h.c)); sn += Math.sin(rad(h.c));
    ws += h.w; cnt++;
    if (h.g > gmax) gmax = h.g;
  }
  if (gmax > 25 || mx - mn > 12 || ws / cnt < 0.12) return;
  const cm = deg(Math.atan2(sn, cs));
  const track = deg(Math.atan2(b.py - H[a].py, b.px - H[a].px));
  const om = wrap(track - cm);
  const alpha = mem.offN === 0 ? 1 : Math.max(0.15, 0.6 / (mem.offN + 1));
  mem.off = wrap(mem.off + alpha * wrap(om - mem.off));
  mem.offN++; mem.lastOffT = mem.tick;
}

function markVis(mem, p) {
  const N = mem.cellN, c = mem.cell;
  for (let i = 0; i < N; i++) for (let j = 0; j < N; j++) {
    const k = i * N + j;
    if (!mem.vis[k] && dist(p.x, p.y, (i + 0.5) * c, (j + 0.5) * c) < 15) mem.vis[k] = true;
  }
}

function nearDone(mem, x, y, R) {
  for (const d of mem.done) if (dist(x, y, d.x, d.y) < R) return true;
  return false;
}

function markHintsNear(mem, x, y, R) {
  for (const h of mem.hints) {
    if ((h.state === 0 || h.state === 3) && dist(h.x, h.y, x, y) < R) h.state = 1;
  }
}

function readRays(obs, mem, mov) {
  const src = (obs.rays && obs.rays.length >= 9) ? obs.rays : null;
  const r = [];
  for (let i = 0; i < 9; i++) {
    let x = src ? Number(src[i]) : 15;
    if (!isFinite(x)) x = 15;
    r.push(clamp(x, 0, 15));
  }
  if (mem.rayPrev && mov > 0.1 && r.some(x => x < 14) && r.every((x, i) => x === mem.rayPrev[i])) mem.rayStatic++;
  else mem.rayStatic = 0;
  mem.rayPrev = r;
  if (mem.rayStatic > 25) { mem.rayOffUntil = mem.tick + 400; mem.rayStatic = 0; }
  if (mem.tick < mem.rayOffUntil) return null;
  return r;
}

function pickTarget(mem, p, tl) {
  const sp = Math.max(0.15, mem.vEst);
  const B = mem.base;
  let best = null, bs = 0;
  for (const h of mem.hints) {
    if (h.state !== 0) continue;
    const d = dist(p.x, p.y, h.x, h.y), dh = dist(h.x, h.y, B.x, B.y);
    if ((d + dh) / sp + 100 > tl) continue;
    const cost = d / sp + 60 + 0.5 * dh / sp;
    const sc = h.est / cost;
    if (sc > bs) { bs = sc; best = h; }
  }
  if (best) return { kind: 'hint', i: best.i, x: best.x, y: best.y };
  const N = mem.cellN, c = mem.cell;
  let bd = 1e9, bk = -1, bx = 0, by = 0;
  for (let i = 0; i < N; i++) for (let j = 0; j < N; j++) {
    const k = i * N + j;
    if (mem.vis[k]) continue;
    const cx = (i + 0.5) * c, cy = (j + 0.5) * c;
    const d = dist(p.x, p.y, cx, cy);
    if (d < bd) { bd = d; bk = k; bx = cx; by = cy; }
  }
  if (bk >= 0 && (bd + dist(bx, by, B.x, B.y)) / sp + 60 < tl) return { kind: 'explore', i: bk, x: bx, y: by };
  return null;
}

function makeSearch(cx, cy, hi, tick) {
  return {
    hi: hi, t0: tick, wt: tick, idx: 0,
    wps: [{ x: cx - 12, y: cy - 7 }, { x: cx + 12, y: cy - 7 }, { x: cx + 12, y: cy + 7 }, { x: cx - 12, y: cy + 7 }]
  };
}

function finishSearch(mem) {
  if (mem.search && mem.search.hi >= 0) mem.hints[mem.search.hi].state = 1;
  mem.search = null;
  return null;
}

function searchStep(mem, p, hE, r) {
  const S = mem.search;
  if (mem.tick - S.t0 > 1800) return finishSearch(mem);
  while (S.idx < S.wps.length) {
    const w = S.wps[S.idx];
    const d = dist(p.x, p.y, w.x, w.y);
    if (d < 2.5 || mem.tick - S.wt > 300) { S.idx++; S.wt = mem.tick; continue; }
    const e = wrap(deg(Math.atan2(w.y - p.y, w.x - p.x)) - hE);
    return steer(e, CRUISE, mem, r, true);
  }
  return finishSearch(mem);
}

function steer(e, vT, mem, r, avoid) {
  let bias = 0, F = 15;
  const useR = avoid && r;
  if (useR) {
    F = Math.min(r[3], r[4], r[5]);
    const Lc = Math.min(r[5], r[6], r[7], r[8]);
    const Rc = Math.min(r[0], r[1], r[2], r[3]);
    for (let i = 0; i < 9; i++) {
      if (r[i] < 4) {
        const w = (4 - r[i]) / 4;
        if (ANG[i] > 0) bias -= 35 * w;
        else if (ANG[i] < 0) bias += 35 * w;
        else bias += (Lc >= Rc ? 1 : -1) * 45 * w;
      }
    }
  }
  const e2 = clamp(e + bias, -120, 120);
  const ae = Math.abs(e2);
  const sF = useR ? clamp((F - 1.0) / 3.0, 0, 1) : 1;
  const ep = clamp((40 - ae) / 25, 0, 1);
  let v = vT * ep * sF;
  if (v > 0.05 && sF > 0.6) v = Math.max(v, Math.min(mem.dz + 0.02, 0.5));
  let s = KS * rad(e2);
  if (v < 0.05 && ae > 12 && Math.abs(s) < mem.dz) s = sgn(s) * mem.dz;
  s = clamp(s, -0.45, 0.45);
  let L = v - s, R = v + s;
  const m = Math.max(Math.abs(L), Math.abs(R));
  if (m > 1) { L /= m; R /= m; }
  return { left: L, right: R, drill: false };
}

function startEsc(mem) {
  mem.escN = 25;
  mem.escDir = -mem.escDir;
}

function drillStep(obs, mem, wl, wr) {
  const D = mem.drill;
  D.n++;
  const dr = obs.drilling || 0;
  if (dr >= 6.1) {
    mem.done.push({ x: D.x, y: D.y });
    markHintsNear(mem, D.x, D.y, 14);
    mem.drill = null;
    return STOP();
  }
  if (D.n > 200 || (D.n > 50 && dr < 0.05)) {
    mem.done.push({ x: D.x, y: D.y });
    mem.drill = null;
    return STOP();
  }
  const vf = (wl + wr) / 2;
  const u = clamp(-2 * vf, -0.15, 0.15);
  return { left: u, right: u, drill: true };
}

function gotoStep(mem, p, hE, r, sci) {
  const T = mem.tgt;
  const d = dist(p.x, p.y, T.x, T.y);
  if (d < 7) {
    mem.tgt = null; mem.mode = 'pick';
    if (T.kind === 'hint') {
      const h = mem.hints[T.i];
      if (sci > 0) { h.state = 3; mem.search = makeSearch(T.x, T.y, T.i, mem.tick); mem.mode = 'search'; }
      else h.state = 2;
    } else {
      mem.vis[T.i] = true;
      if (sci > 0) { mem.search = makeSearch(p.x, p.y, -1, mem.tick); mem.mode = 'search'; }
    }
    return STOP();
  }
  if (d < mem.gBest - 2) { mem.gBest = d; mem.gT = mem.tick; }
  if (mem.tick - mem.gT > 300 || (T.stucks || 0) >= 3 || (T.bumps || 0) >= 3) {
    if (T.kind === 'hint') mem.hints[T.i].state = 2; else mem.vis[T.i] = true;
    mem.tgt = null; mem.mode = 'pick';
    return STOP();
  }
  const e = wrap(deg(Math.atan2(T.y - p.y, T.x - p.x)) - hE);
  return steer(e, CRUISE, mem, r, true);
}

function updateVEst(mem, wl, wr, wv) {
  if (mem.lastL > 0.15 && mem.lastR > 0.15 && Math.abs(wl - wr) < 0.2 && wv > 0.05) {
    mem.vEst = clamp(mem.vEst + 0.02 * (wv - mem.vEst), 0.1, 2);
  }
}

function step(obs, mem) {
  if (!mem.init) init(obs, mem);
  mem.tick++;
  updatePos(obs, mem);
  const p = { x: mem.px, y: mem.py };
  const wl = obs.wheelLeft || 0, wr = obs.wheelRight || 0, wv = (wl + wr) / 2;
  const mov = Math.max(Math.abs(wl), Math.abs(wr));
  const carried = obs.carried || 0;
  const battery = obs.battery || 0;
  const tl = obs.timeLeft || 0;
  const hE = obs.heading + mem.off;
  const B = mem.base;
  const dB = dist(p.x, p.y, B.x, B.y);
  const bcn = (obs.beacon && isFinite(obs.beacon.distance)) ? obs.beacon : null;
  const bdist = bcn ? bcn.distance : dB;
  const r = readRays(obs, mem, mov);
  const sci = Number(obs.science) || 0;

  mem.hist.push({ px: p.x, py: p.y, c: obs.heading, w: wv, g: mem.gStale });
  if (mem.hist.length > 420) mem.hist.shift();
  updateOff(mem);
  markVis(mem, p);
  updateVEst(mem, wl, wr, wv);

  const bumpEdge = !!obs.bumped && !mem.lastBumped;
  mem.lastBumped = !!obs.bumped;
  if (mem.lastCmdMag > 0.15 && mov < 0.03) mem.noMove++; else mem.noMove = 0;
  if (mem.noMove >= 20) {
    mem.dz = Math.min(0.45, mem.dz + 0.03);
    mem.noMove = 0; mem.stuckN++;
    if (mem.tgt) mem.tgt.stucks = (mem.tgt.stucks || 0) + 1;
    startEsc(mem);
  }
  if (bumpEdge) {
    startEsc(mem);
    if (mem.tgt) mem.tgt.bumps = (mem.tgt.bumps || 0) + 1;
  }
  if (mem.dz > 0.12 && mov > 0.1 && mem.tick % 20 === 0) mem.dz = Math.max(0.12, mem.dz - 0.005);

  if (mem.drill) return drillStep(obs, mem, wl, wr);

  if (mem.escN > 0) {
    mem.escN--;
    if (mem.escN >= 13) return { left: -0.25, right: -0.25, drill: false };
    return { left: -0.3 * mem.escDir, right: 0.3 * mem.escDir, drill: false };
  }

  const needHome = carried > 0 && mem.mode !== 'dock' &&
    (carried >= mem.cap || mem.noTarget || tl < (dB / Math.max(0.15, mem.vEst)) * 1.4 + 60 || battery < 0.2);
  if (needHome && mem.mode !== 'home') {
    if (mem.search && mem.search.hi >= 0 && mem.hints[mem.search.hi].state === 3) mem.hints[mem.search.hi].state = 0;
    mem.search = null; mem.tgt = null; mem.mode = 'home';
  }
  if (mem.mode === 'home' && carried === 0) { mem.mode = 'pick'; mem.tgt = null; }

  if (mem.mode === 'home') {
    if (bdist < 2.5 || obs.docked) { mem.mode = 'dock'; mem.dockN = 0; return STOP(); }
    let e;
    if (bcn) e = bcn.bearing;
    else e = wrap(deg(Math.atan2(B.y - p.y, B.x - p.x)) - hE);
    const v = bdist < 8 ? 0.15 : CRUISE;
    return steer(e, v, mem, r, true);
  }

  if (mem.mode === 'dock') {
    mem.dockN++;
    if (carried === 0 || mem.dockN > 80) { mem.mode = 'pick'; mem.tgt = null; mem.dockN = 0; }
    else return STOP();
  }

  const site = obs.site;
  if (site && carried < mem.cap && mem.mode !== 'home' && mem.mode !== 'dock') {
    const hd = rad(hE + site.bearing);
    const sx = p.x + site.distance * Math.cos(hd), sy = p.y + site.distance * Math.sin(hd);
    if (!nearDone(mem, sx, sy, 5)) {
      mem.siteN++;
      if (mem.siteN > 400) {
        mem.done.push({ x: sx, y: sy }); mem.siteN = 0;
      } else if (site.distance <= 1.3) {
        if (mov < 0.12) {
          mem.drill = { x: sx, y: sy, n: 0 };
          mem.siteN = 0;
          return { left: 0, right: 0, drill: true };
        }
        const u = clamp(-2 * wv, -0.2, 0.2);
        return { left: u, right: u, drill: false };
      } else {
        return steer(site.bearing, clamp(site.distance * 0.3, 0.12, CRUISE), mem, r, site.distance > 3);
      }
    }
  } else {
    mem.siteN = 0;
  }

  if (mem.mode === 'search') {
    const out = searchStep(mem, p, hE, r);
    if (out) return out;
    mem.mode = 'pick'; mem.tgt = null;
    return STOP();
  }

  if (mem.mode !== 'goto' || !mem.tgt) {
    const t = pickTarget(mem, p, tl);
    if (!t) { mem.noTarget = true; mem.mode = 'pick'; mem.tgt = null; return STOP(); }
    mem.noTarget = false;
    mem.tgt = t; mem.mode = 'goto'; mem.gBest = 1e9; mem.gT = mem.tick;
  }
  return gotoStep(mem, p, hE, r, sci);
}

function act(obs, mem) {
  let o;
  try {
    o = step(obs, mem);
  } catch (e) {
    o = STOP();
  }
  const L = clamp(+o.left || 0, -1, 1);
  const R = clamp(+o.right || 0, -1, 1);
  mem.lastL = L; mem.lastR = R;
  mem.lastCmdMag = o.drill ? 0 : Math.max(Math.abs(L), Math.abs(R));
  return { left: L, right: R, drill: !!o.drill };
}

const ANG = [-80, -60, -40, -20, 0, 20, 40, 60, 80];

function wrap(a) { return ((a + 180) % 360 + 360) % 360 - 180; }
function rad(d) { return d * Math.PI / 180; }
function deg(r) { return r * 180 / Math.PI; }
function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
function dist(ax, ay, bx, by) { return Math.hypot(ax - bx, ay - by); }
function STOP() { return { left: 0, right: 0, drill: false }; }

function init(obs, mem) {
  const m = obs.mission || {};
  mem.init = true;
  mem.tick = 0;
  mem.base = (m.base && isFinite(m.base.x) && isFinite(m.base.y)) ? { x: m.base.x, y: m.base.y } : { x: obs.x, y: obs.y };
  mem.cap = m.capacity || 5;
  mem.size = m.size || 400;
  mem.hints = (m.hints || []).map((h, i) => ({ i: i, x: h.x, y: h.y, est: (h.estimate > 0 ? h.estimate : 1), state: 0 }));
  mem.px = obs.x; mem.py = obs.y; mem.gx = undefined; mem.gy = undefined; mem.stale = 0;
  mem.off = 0; mem.offN = 0; mem.lastOff = -1000;
  mem.fix = [];
  mem.spd = 0.4; mem.vEst = 0.35; mem.wv = 0;
  mem.lastL = 0; mem.lastR = 0; mem.lastBump = false;
  mem.escN = 0; mem.escDir = 1; mem.lowN = 0;
  mem.mode = 'pick'; mem.tgt = null; mem.search = null; mem.drill = null;
  mem.done = []; mem.dockN = 0; mem.noTarget = false; mem.siteN = 0;
  mem.cell = 50; mem.cellN = Math.ceil(mem.size / mem.cell);
  mem.vis = new Array(mem.cellN * mem.cellN).fill(false);
}

function updatePos(obs, mem) {
  const fresh = mem.gx === undefined || obs.x !== mem.gx || obs.y !== mem.gy;
  if (fresh) {
    mem.px = obs.x; mem.py = obs.y; mem.stale = 0;
  } else {
    mem.stale++;
    const v = ((obs.wheelLeft || 0) + (obs.wheelRight || 0)) / 2 * 0.1;
    const h = rad(obs.heading + mem.off);
    mem.px += v * Math.cos(h);
    mem.py += v * Math.sin(h);
  }
  mem.gx = obs.x; mem.gy = obs.y;
  return fresh;
}

function updateOff(obs, mem, fresh, wv) {
  if (fresh) {
    mem.fix.push({ x: obs.x, y: obs.y, c: obs.heading, w: wv });
    if (mem.fix.length > 400) mem.fix.shift();
  }
  const F = mem.fix, n = F.length;
  if (!fresh || n < 30 || mem.tick - mem.lastOff < 50) return;
  const b = F[n - 1];
  let a = -1;
  for (let k = n - 2; k >= 0 && n - 1 - k <= 400; k--) {
    if (dist(F[k].x, F[k].y, b.x, b.y) >= 15) { a = k; break; }
  }
  if (a < 0) return;
  mem.lastOff = mem.tick;
  let mn = 1e9, mx = -1e9, cs = 0, sn = 0, ws = 0, cnt = 0;
  const c0 = F[a].c;
  for (let k = a; k < n; k++) {
    const h = F[k];
    const rel = wrap(h.c - c0);
    if (rel < mn) mn = rel;
    if (rel > mx) mx = rel;
    cs += Math.cos(rad(h.c)); sn += Math.sin(rad(h.c));
    ws += h.w; cnt++;
  }
  if (mx - mn > 20 || ws / cnt < 0.12) return;
  const cm = deg(Math.atan2(sn, cs));
  const track = deg(Math.atan2(b.y - F[a].y, b.x - F[a].x));
  const om = wrap(track - cm);
  const alpha = Math.max(0.2, 1 / (mem.offN + 1));
  mem.off = wrap(mem.off + alpha * wrap(om - mem.off));
  mem.offN++;
}

function markVis(mem, p) {
  const N = mem.cellN, c = mem.cell;
  for (let i = 0; i < N; i++) for (let j = 0; j < N; j++) {
    const k = i * N + j;
    if (!mem.vis[k] && dist(p.x, p.y, (i + 0.5) * c, (j + 0.5) * c) < 35) mem.vis[k] = true;
  }
}

function nearDone(mem, x, y, R) {
  for (const d of mem.done) if (dist(x, y, d.x, d.y) < R) return true;
  return false;
}

function markHintNear(mem, x, y, R) {
  let best = null, bd = R;
  for (const h of mem.hints) {
    if (h.state !== 0) continue;
    const d = dist(h.x, h.y, x, y);
    if (d < bd) { bd = d; best = h; }
  }
  if (best) best.state = 1;
}

function getRays(obs) {
  const src = (obs.rays && obs.rays.length >= 9) ? obs.rays : null;
  const out = [];
  for (let i = 0; i < 9; i++) {
    let x = src ? Number(src[i]) : 15;
    if (!isFinite(x)) x = 15;
    out.push(clamp(x, 0, 15));
  }
  return out;
}

function avoidBias(r) {
  let bias = 0;
  const Lc = Math.min(r[5], r[6], r[7], r[8]);
  const Rc = Math.min(r[0], r[1], r[2], r[3]);
  for (let i = 0; i < 9; i++) {
    if (r[i] < 5) {
      const w = (5 - r[i]) / 5;
      if (ANG[i] > 0) bias -= 45 * w;
      else if (ANG[i] < 0) bias += 45 * w;
      else bias += (Lc >= Rc ? 1 : -1) * 60 * w;
    }
  }
  return bias;
}

// e: target bearing relative to heading (deg, positive = left)
function drive(mem, e, cap, r, avoid) {
  let F = 15, bias = 0, fac = 1;
  if (avoid && r) {
    F = Math.min(r[3], r[4], r[5]);
    bias = avoidBias(r);
    fac = clamp((F - 1.5) / 4, 0, 1);
  }
  const ee = wrap(e + bias);
  const ae = Math.abs(ee);
  let L, R;
  if (ae > 70) {
    const s = ee >= 0 ? 1 : -1;
    L = -0.3 * s; R = 0.3 * s;
  } else {
    const fa = clamp(1 - ae / 80, 0.3, 1);
    const f = Math.min(mem.spd, cap) * fa * fac;
    const t = ae < 2 ? 0 : clamp(0.15 * rad(ee), -0.35, 0.35);
    L = f - t; R = f + t;
    if (cap >= 0.45 && ae < 10 && fac >= 1) {
      mem.spd = clamp(mem.spd + 0.01 * (0.45 - mem.wv), 0.2, 0.8);
    }
  }
  const m = Math.max(Math.abs(L), Math.abs(R));
  if (m > 1) { L /= m; R /= m; }
  return { left: L, right: R, drill: false };
}

function startEsc(mem, r) {
  mem.escN = 20;
  if (r) {
    const Lc = Math.min(r[5], r[6], r[7], r[8]), Rc = Math.min(r[0], r[1], r[2], r[3]);
    if (Math.abs(Lc - Rc) > 1) mem.escDir = Lc > Rc ? 1 : -1;
    else mem.escDir = -mem.escDir;
  } else {
    mem.escDir = -mem.escDir;
  }
}

function escStep(mem) {
  mem.escN--;
  if (mem.escN >= 10) return { left: -0.3, right: -0.3, drill: false };
  return { left: -0.3 * mem.escDir, right: 0.3 * mem.escDir, drill: false };
}

function drillStep(obs, mem, wv) {
  const D = mem.drill;
  D.n++;
  const dr = Number(obs.drilling) || 0;
  if (dr >= 6.1) {
    mem.done.push({ x: D.x, y: D.y });
    markHintNear(mem, D.x, D.y, 12);
    mem.drill = null; mem.search = null; mem.mode = 'pick'; mem.tgt = null;
    return STOP();
  }
  if (D.n > 120) {
    mem.done.push({ x: D.x, y: D.y });
    mem.drill = null; mem.mode = 'pick'; mem.tgt = null;
    return STOP();
  }
  const u = clamp(-3 * wv, -0.2, 0.2);
  return { left: u, right: u, drill: true };
}

function ringPts(cx, cy, R) {
  const a = [];
  for (let k = 0; k < 8; k++) {
    const t = rad(k * 45);
    a.push({ x: cx + R * Math.cos(t), y: cy + R * Math.sin(t) });
  }
  return a;
}

function startSearch(mem, p, cx, cy, hi) {
  const pts = ringPts(cx, cy, 7);
  let idx = 0, bd = 1e9;
  for (let k = 0; k < pts.length; k++) {
    const d = dist(p.x, p.y, pts[k].x, pts[k].y);
    if (d < bd) { bd = d; idx = k; }
  }
  mem.search = { cx: cx, cy: cy, stage: 1, pts: pts, idx: idx, wt: mem.tick, t0: mem.tick, hi: hi,
                 best: { v: -1, x: cx, y: cy } };
  mem.mode = 'search';
}

function endSearch(mem) {
  const S = mem.search;
  if (S && S.hi >= 0 && mem.hints[S.hi] && mem.hints[S.hi].state === 0) mem.hints[S.hi].state = 2;
  mem.search = null; mem.mode = 'pick'; mem.tgt = null;
  return null;
}

function searchStep(mem, p, sci, r, hE) {
  const S = mem.search;
  if (!S) return null;
  if (sci > S.best.v) S.best = { v: sci, x: p.x, y: p.y };
  if (mem.tick - S.t0 > 900) return endSearch(mem);
  for (let guard = 0; guard < 20; guard++) {
    if (S.idx >= S.pts.length) {
      if (S.stage === 1 && S.best.v > 0) {
        S.stage = 2; S.cx = S.best.x; S.cy = S.best.y;
        S.pts = ringPts(S.cx, S.cy, 4);
        S.idx = 0; S.wt = mem.tick;
        S.best = { v: -1, x: S.cx, y: S.cy };
        continue;
      }
      return endSearch(mem);
    }
    const w = S.pts[S.idx];
    if (dist(p.x, p.y, w.x, w.y) < 2.5 || mem.tick - S.wt > 200) {
      S.idx++; S.wt = mem.tick;
      continue;
    }
    const e = wrap(deg(Math.atan2(w.y - p.y, w.x - p.x)) - hE);
    return drive(mem, e, 0.35, r, true);
  }
  return endSearch(mem);
}

function pickTarget(mem, p, tl) {
  const v = Math.max(0.15, mem.vEst);
  const B = mem.base;
  let best = null, bs = 0;
  for (const h of mem.hints) {
    if (h.state !== 0) continue;
    const d = dist(p.x, p.y, h.x, h.y), dh = dist(h.x, h.y, B.x, B.y);
    if ((d + dh) / v + 120 > tl) continue;
    const sc = h.est / (d / v + 0.7 * dh / v + 60);
    if (sc > bs) { bs = sc; best = h; }
  }
  if (best) return { kind: 'hint', i: best.i, x: best.x, y: best.y, t0: mem.tick, d0: dist(p.x, p.y, best.x, best.y) };
  const N = mem.cellN, c = mem.cell;
  let bd = 1e9, bk = -1, bx = 0, by = 0;
  for (let i = 0; i < N; i++) for (let j = 0; j < N; j++) {
    const k = i * N + j;
    if (mem.vis[k]) continue;
    const cx = (i + 0.5) * c, cy = (j + 0.5) * c;
    const d = dist(p.x, p.y, cx, cy);
    if (d < bd) { bd = d; bk = k; bx = cx; by = cy; }
  }
  if (bk >= 0 && (bd + dist(bx, by, B.x, B.y)) / v + 120 < tl) {
    return { kind: 'explore', i: bk, x: bx, y: by, t0: mem.tick, d0: bd };
  }
  return null;
}

function gotoStep(mem, p, hE, r, sci) {
  const T = mem.tgt;
  if (!T) { mem.mode = 'pick'; return null; }
  const d = dist(p.x, p.y, T.x, T.y);
  if (d < 6) {
    mem.tgt = null; mem.mode = 'pick';
    if (T.kind === 'hint') {
      if (sci > 0) startSearch(mem, p, T.x, T.y, T.i);
      else mem.hints[T.i].state = 2;
    } else {
      mem.vis[T.i] = true;
      if (sci > 0) startSearch(mem, p, p.x, p.y, -1);
    }
    return null;
  }
  if (mem.tick - T.t0 > 400 + 35 * T.d0 || (T.bumps || 0) >= 3 || (T.stucks || 0) >= 3) {
    if (T.kind === 'hint') mem.hints[T.i].state = 2; else mem.vis[T.i] = true;
    mem.tgt = null; mem.mode = 'pick';
    return null;
  }
  const e = wrap(deg(Math.atan2(T.y - p.y, T.x - p.x)) - hE);
  return drive(mem, e, 0.5, r, true);
}

function step(obs, mem) {
  if (!mem.init) init(obs, mem);
  mem.tick++;
  const fresh = updatePos(obs, mem);
  const p = { x: mem.px, y: mem.py };
  const wl = obs.wheelLeft || 0, wr = obs.wheelRight || 0, wv = (wl + wr) / 2;
  const wmag = Math.max(Math.abs(wl), Math.abs(wr));
  mem.wv = wv;
  const carried = obs.carried || 0;
  const battery = obs.battery || 0;
  const tl = obs.timeLeft || 0;
  const hE = obs.heading + mem.off;
  const B = mem.base;
  const dB = dist(p.x, p.y, B.x, B.y);
  const sci = Number(obs.science) || 0;
  const r = getRays(obs);

  updateOff(obs, mem, fresh, wv);
  if (Math.abs(wl - wr) < 0.1 && wv > 0.08 && mem.lastL > 0.2 && mem.lastR > 0.2) {
    mem.vEst = clamp(mem.vEst + 0.01 * (wv - mem.vEst), 0.1, 1.5);
  }
  markVis(mem, p);

  // bumps and stalls
  const bumpEdge = !!obs.bumped && !mem.lastBump;
  mem.lastBump = !!obs.bumped;
  if (bumpEdge) {
    if (mem.tgt) mem.tgt.bumps = (mem.tgt.bumps || 0) + 1;
    startEsc(mem, r);
  }
  const cmdMag = Math.max(Math.abs(mem.lastL), Math.abs(mem.lastR));
  if (cmdMag > 0.25 && wmag < 0.05 && !mem.drill) mem.lowN++; else mem.lowN = 0;
  if (mem.lowN >= 25) {
    mem.lowN = 0;
    if (mem.tgt) mem.tgt.stucks = (mem.tgt.stucks || 0) + 1;
    startEsc(mem, r);
  }

  if (mem.escN > 0) return escStep(mem);
  if (mem.drill) return drillStep(obs, mem, wv);

  // docking
  if (mem.mode === 'dock') {
    mem.dockN++;
    if ((carried === 0 && mem.dockN >= 8) || mem.dockN > 80) {
      mem.mode = 'pick'; mem.tgt = null; mem.dockN = 0;
    }
    return STOP();
  }

  // go home?
  const needHome = carried > 0 && (carried >= mem.cap || mem.noTarget ||
    tl < dB / Math.max(0.15, mem.vEst) * 1.3 + 80 || battery < 0.3);
  if (needHome && mem.mode !== 'home') { mem.mode = 'home'; mem.tgt = null; mem.search = null; }
  if (mem.mode === 'home' && carried === 0) mem.mode = 'pick';
  if (mem.mode === 'home') {
    const bc = obs.beacon;
    if (dB < 2 || obs.docked || (bc && bc.distance < 2.2)) {
      mem.mode = 'dock'; mem.dockN = 0;
      return STOP();
    }
    let e;
    if (bc && isFinite(bc.bearing) && bc.distance < 20) e = bc.bearing;
    else e = wrap(deg(Math.atan2(B.y - p.y, B.x - p.x)) - hE);
    return drive(mem, e, dB < 8 ? 0.25 : 0.5, r, true);
  }

  // opportunistic sampling of a site within 8 m
  const site = obs.site;
  if (site && carried < mem.cap && tl > 60 && site.distance <= 8) {
    const hd = rad(hE + site.bearing);
    const sx = p.x + site.distance * Math.cos(hd), sy = p.y + site.distance * Math.sin(hd);
    if (!nearDone(mem, sx, sy, 6)) {
      mem.siteN++;
      if (mem.siteN > 200) {
        mem.done.push({ x: sx, y: sy }); mem.siteN = 0;
      } else if (site.distance <= 1.3) {
        mem.siteN = 0;
        if (wmag < 0.12) {
          mem.drill = { x: sx, y: sy, n: 0 };
          return { left: 0, right: 0, drill: true };
        }
        return STOP();
      } else {
        return drive(mem, site.bearing, 0.2, r, site.distance > 4);
      }
    } else {
      mem.siteN = 0;
    }
  } else {
    mem.siteN = 0;
  }

  if (mem.mode === 'search') {
    const out = searchStep(mem, p, sci, r, hE);
    return out || STOP();
  }
  if (mem.mode === 'goto') {
    const out = gotoStep(mem, p, hE, r, sci);
    return out || STOP();
  }

  // pick a new target
  const t = pickTarget(mem, p, tl);
  if (!t) { mem.noTarget = true; return STOP(); }
  mem.noTarget = false;
  mem.tgt = t; mem.mode = 'goto';
  const out = gotoStep(mem, p, hE, r, sci);
  return out || STOP();
}

function act(obs, mem) {
  let o;
  try {
    o = step(obs, mem);
  } catch (e) {
    o = STOP();
  }
  const L = clamp(+o.left || 0, -1, 1);
  const R = clamp(+o.right || 0, -1, 1);
  mem.lastL = L; mem.lastR = R;
  return { left: L, right: R, drill: !!o.drill };
}

const ANG = [-80, -60, -40, -20, 0, 20, 40, 60, 80];
const CRUISE = 0.4;
const KS = 0.15;
const CELL = 50;

function wrap(a) { return ((a + 180) % 360 + 360) % 360 - 180; }
function rad(d) { return d * Math.PI / 180; }
function deg(r) { return r * 180 / Math.PI; }
function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
function dist(ax, ay, bx, by) { return Math.hypot(ax - bx, ay - by); }
function sgn(v) { return v < 0 ? -1 : 1; }
function STOP() { return { left: 0, right: 0, drill: false }; }

function init(obs, mem) {
  const m = obs.mission || {};
  mem.init = true;
  mem.tick = 0;
  mem.base = (m.base && isFinite(m.base.x) && isFinite(m.base.y)) ? { x: +m.base.x, y: +m.base.y } : { x: obs.x, y: obs.y };
  mem.cap = m.capacity || 5;
  mem.size = m.size || 400;
  mem.hints = (m.hints || []).map((h, i) => ({
    i: i, x: +h.x, y: +h.y, est: (+h.estimate > 0) ? +h.estimate : 1, state: 0
  }));
  mem.px = obs.x; mem.py = obs.y; mem.gx = undefined; mem.gy = undefined; mem.gpsRej = 0;
  mem.off = 0; mem.offN = 0; mem.offT = -1000; mem.fixes = [];
  mem.mode = 'pick'; mem.tgt = null; mem.search = null; mem.drill = null; mem.dockN = 0;
  mem.done = []; mem.noTarget = false; mem.siteN = 0;
  mem.escN = 0; mem.escDir = 1; mem.lastBump = false; mem.lowN = 0; mem.lastL = 0; mem.lastR = 0;
  mem.rayPrev = null; mem.rayStatic = 0; mem.rayOff = 0;
  mem.wd = { x: obs.x, y: obs.y, t: 0 };
  mem.cellN = Math.ceil(mem.size / CELL);
  mem.vis = new Array(mem.cellN * mem.cellN).fill(false);
}

function updatePos(obs, mem) {
  const fresh = mem.gx === undefined || obs.x !== mem.gx || obs.y !== mem.gy;
  if (mem.gx === undefined) {
    mem.px = obs.x; mem.py = obs.y;
  } else {
    const v = ((obs.wheelLeft || 0) + (obs.wheelRight || 0)) / 2 * 0.1;
    const h = rad(obs.heading + mem.off);
    mem.px += v * Math.cos(h);
    mem.py += v * Math.sin(h);
    if (fresh) {
      const d = dist(obs.x, obs.y, mem.px, mem.py);
      if (d < 12 || mem.gpsRej >= 5) {
        mem.px += 0.4 * (obs.x - mem.px);
        mem.py += 0.4 * (obs.y - mem.py);
        mem.gpsRej = 0;
      } else {
        mem.gpsRej++;
      }
    }
  }
  mem.gx = obs.x; mem.gy = obs.y;
  return fresh;
}

function updateOff(obs, mem, fresh) {
  if (!fresh) return;
  const wl = obs.wheelLeft || 0, wr = obs.wheelRight || 0;
  mem.fixes.push({ x: obs.x, y: obs.y, c: obs.heading, w: (wl + wr) / 2, dl: Math.abs(wl - wr) });
  if (mem.fixes.length > 400) mem.fixes.shift();
  if (mem.tick - mem.offT < 40) return;
  const F = mem.fixes, n = F.length, b = F[n - 1];
  let a = -1;
  for (let k = n - 2; k >= 0 && n - 1 - k <= 300; k--) {
    if (dist(F[k].x, F[k].y, b.x, b.y) >= 20) { a = k; break; }
  }
  if (a < 0) return;
  mem.offT = mem.tick;
  let mn = 1e9, mx = -1e9, cs = 0, sn = 0, ws = 0, dl = 0, cnt = 0;
  const c0 = F[a].c;
  for (let k = a; k < n; k++) {
    const rel = wrap(F[k].c - c0);
    if (rel < mn) mn = rel;
    if (rel > mx) mx = rel;
    cs += Math.cos(rad(F[k].c)); sn += Math.sin(rad(F[k].c));
    ws += F[k].w; dl += F[k].dl; cnt++;
  }
  if (mx - mn > 20 || ws / cnt < 0.2 || dl / cnt > 0.15) return;
  const cm = deg(Math.atan2(sn, cs));
  const track = deg(Math.atan2(b.y - F[a].y, b.x - F[a].x));
  const om = wrap(track - cm);
  const alpha = mem.offN === 0 ? 0.8 : Math.max(0.15, 0.5 / (mem.offN + 1));
  mem.off = wrap(mem.off + alpha * wrap(om - mem.off));
  mem.offN++;
}

function markVis(mem, p) {
  const N = mem.cellN, c = CELL;
  for (let i = 0; i < N; i++) for (let j = 0; j < N; j++) {
    const k = i * N + j;
    if (!mem.vis[k] && dist(p.x, p.y, (i + 0.5) * c, (j + 0.5) * c) < 35) mem.vis[k] = true;
  }
}

function nearDone(mem, x, y, R) {
  for (const d of mem.done) if (dist(x, y, d.x, d.y) < R) return true;
  return false;
}

function markHintsNear(mem, x, y, R) {
  for (const h of mem.hints) {
    if (h.state === 0 && dist(h.x, h.y, x, y) < R) h.state = 1;
  }
}

function getRays(obs, mem, moving) {
  const src = (obs.rays && obs.rays.length >= 9) ? obs.rays : null;
  const r = [];
  for (let i = 0; i < 9; i++) {
    let x = src ? Number(src[i]) : 15;
    if (!isFinite(x)) x = 15;
    r.push(clamp(x, 0, 15));
  }
  let same = !!mem.rayPrev && moving && r.some(x => x < 14);
  if (same) {
    for (let i = 0; i < 9; i++) if (r[i] !== mem.rayPrev[i]) { same = false; break; }
  }
  mem.rayStatic = same ? mem.rayStatic + 1 : 0;
  mem.rayPrev = r;
  if (mem.rayStatic > 25) { mem.rayOff = mem.tick + 300; mem.rayStatic = 0; }
  if (mem.tick < mem.rayOff) return null;
  return r;
}

function avoidBias(r) {
  let bias = 0;
  const Lc = Math.min(r[5], r[6], r[7], r[8]);
  const Rc = Math.min(r[0], r[1], r[2], r[3]);
  for (let i = 0; i < 9; i++) {
    if (r[i] < 5) {
      const w = (5 - r[i]) / 5;
      if (ANG[i] > 0) bias -= 45 * w;
      else if (ANG[i] < 0) bias += 45 * w;
      else bias += (Lc >= Rc ? 1 : -1) * 50 * w;
    }
  }
  return bias;
}

// e: target bearing relative to heading (deg, positive = left)
function drive(mem, e, v, r, avoidOn) {
  let bias = 0, F = 15, lc = 15, rc = 15;
  const useR = avoidOn && r;
  if (useR) {
    bias = avoidBias(r);
    F = Math.min(r[3], r[4], r[5]);
    lc = Math.min(r[5], r[6], r[7], r[8]);
    rc = Math.min(r[0], r[1], r[2], r[3]);
  }
  const ee = wrap(e + bias);
  const ae = Math.abs(ee);
  let fwd = ae > 65 ? 0 : v * clamp(1 - ae / 70, 0.3, 1);
  if (useR && F < 1.6) fwd = 0;
  let L, R;
  if (fwd <= 0) {
    const s = (ae >= 8) ? sgn(ee) * 0.3 : ((lc >= rc) ? 0.3 : -0.3);
    L = -s; R = s;
  } else {
    fwd = Math.max(fwd, 0.3);
    const s = clamp(KS * rad(ee), -0.35, 0.35);
    L = fwd - s; R = fwd + s;
  }
  L = clamp(L, -1, 1); R = clamp(R, -1, 1);
  return { left: L, right: R, drill: false };
}

function startEsc(mem, r) {
  mem.escN = 24;
  let dir = -mem.escDir;
  if (r) {
    const lc = Math.min(r[5], r[6], r[7], r[8]), rc = Math.min(r[0], r[1], r[2], r[3]);
    if (Math.abs(lc - rc) > 0.5) dir = lc > rc ? 1 : -1;
  }
  mem.escDir = dir;
}

function escStep(mem) {
  mem.escN--;
  if (mem.escN >= 10) return { left: -0.35, right: -0.35, drill: false };
  return { left: -0.35 * mem.escDir, right: 0.35 * mem.escDir, drill: false };
}

function drillStep(obs, mem, wv) {
  const D = mem.drill;
  D.n++;
  const dr = Number(obs.drilling) || 0;
  if (dr >= 6.15) {
    mem.done.push({ x: D.x, y: D.y });
    markHintsNear(mem, D.x, D.y, 15);
    mem.drill = null;
    return STOP();
  }
  if (D.n > 150) {
    mem.done.push({ x: D.x, y: D.y });
    mem.drill = null;
    return STOP();
  }
  const u = clamp(-2 * wv, -0.2, 0.2);
  return { left: u, right: u, drill: true };
}

function startSearch(mem, cx, cy, hi) {
  mem.search = { cx: cx, cy: cy, hi: hi, theta: 0, lastAng: null, t0: mem.tick,
                 R0: 3, c: 2.2, Rmax: 17, tmax: 1000, sciSeen: false };
  mem.mode = 'search';
  mem.tgt = null;
}

function finishSearch(mem) {
  if (mem.search && mem.search.hi >= 0 && mem.hints[mem.search.hi]) mem.hints[mem.search.hi].state = 1;
  mem.search = null;
  mem.mode = 'pick';
  mem.tgt = null;
}

function spiralStep(mem, p, r, hE, sci) {
  const S = mem.search;
  if (!S) return null;
  if (sci > 0) S.sciSeen = true;
  const age = mem.tick - S.t0;
  if (age > S.tmax) return null;
  if (!S.sciSeen && age > 150) return null;
  const dc = dist(p.x, p.y, S.cx, S.cy);
  const ang = Math.atan2(p.y - S.cy, p.x - S.cx);
  if (dc > 2) {
    if (S.lastAng !== null) {
      const d = clamp(wrap(deg(ang - S.lastAng)), -17, 17);
      S.theta += rad(d);
    }
    S.lastAng = ang;
  }
  if (S.theta > (S.Rmax - S.R0) / S.c) return null;
  const Rd = clamp(S.R0 + S.c * S.theta, 2, S.Rmax);
  const phi = ang + 1.5 / Math.max(Rd, 2.5);
  const tx = S.cx + Rd * Math.cos(phi), ty = S.cy + Rd * Math.sin(phi);
  const e = wrap(deg(Math.atan2(ty - p.y, tx - p.x)) - hE);
  return drive(mem, e, CRUISE, r, true);
}

function pickTarget(mem, p, tl) {
  const v = 0.45;
  const B = mem.base;
  let best = null, bs = 0;
  for (const h of mem.hints) {
    if (h.state !== 0) continue;
    const d = dist(p.x, p.y, h.x, h.y), dh = dist(h.x, h.y, B.x, B.y);
    if ((d + dh) / v + 150 > tl) continue;
    const sc = h.est / (d / v + 0.6 * dh / v + 90);
    if (sc > bs) { bs = sc; best = h; }
  }
  if (best) return { kind: 'hint', i: best.i, x: best.x, y: best.y };
  const N = mem.cellN, c = CELL;
  let bd = 1e9, bk = -1, bx = 0, by = 0;
  for (let i = 0; i < N; i++) for (let j = 0; j < N; j++) {
    const k = i * N + j;
    if (mem.vis[k]) continue;
    const cx = (i + 0.5) * c, cy = (j + 0.5) * c;
    const d = dist(p.x, p.y, cx, cy);
    if (d < bd) { bd = d; bk = k; bx = cx; by = cy; }
  }
  if (bk >= 0 && (bd + dist(bx, by, B.x, B.y)) / v + 150 < tl) {
    return { kind: 'explore', i: bk, x: bx, y: by };
  }
  return null;
}

function gotoStep(mem, p, hE, r, sci) {
  const T = mem.tgt;
  const d = dist(p.x, p.y, T.x, T.y);
  if (d < 6) {
    mem.tgt = null; mem.mode = 'pick';
    if (T.kind === 'hint') {
      if (sci > 0) startSearch(mem, T.x, T.y, T.i);
      else mem.hints[T.i].state = 2;
    } else {
      mem.vis[T.i] = true;
      if (sci > 0) startSearch(mem, p.x, p.y, -1);
    }
    return null;
  }
  if (d < T.best - 2) { T.best = d; T.bt = mem.tick; }
  if (mem.tick - T.bt > 150) {
    T.bt = mem.tick;
    T.fails = (T.fails || 0) + 1;
    startEsc(mem, r);
    return escStep(mem);
  }
  if (T.fails >= 3 || mem.tick - T.t0 > 3000) {
    if (T.kind === 'hint') mem.hints[T.i].state = 2; else mem.vis[T.i] = true;
    mem.tgt = null; mem.mode = 'pick';
    return null;
  }
  const e = wrap(deg(Math.atan2(T.y - p.y, T.x - p.x)) - hE);
  return drive(mem, e, CRUISE, r, true);
}

function step(obs, mem) {
  if (!mem.init) init(obs, mem);
  mem.tick++;
  const fresh = updatePos(obs, mem);
  const p = { x: mem.px, y: mem.py };
  const wl = obs.wheelLeft || 0, wr = obs.wheelRight || 0, wv = (wl + wr) / 2;
  const wmag = Math.max(Math.abs(wl), Math.abs(wr));
  const carried = obs.carried || 0;
  const battery = obs.battery || 0;
  const tl = obs.timeLeft || 0;
  const hE = obs.heading + mem.off;
  const B = mem.base;
  const dB = dist(p.x, p.y, B.x, B.y);
  const bcn = (obs.beacon && isFinite(obs.beacon.distance)) ? obs.beacon : null;
  const sci = Number(obs.science) || 0;
  const r = getRays(obs, mem, wmag > 0.1);
  updateOff(obs, mem, fresh);
  markVis(mem, p);

  const bumpEdge = !!obs.bumped && !mem.lastBump;
  mem.lastBump = !!obs.bumped;
  const cmdMag = Math.max(Math.abs(mem.lastL), Math.abs(mem.lastR));
  if (cmdMag > 0.25 && wmag < 0.05 && !mem.drill) mem.lowN++; else mem.lowN = 0;

  if (mem.drill) return drillStep(obs, mem, wv);

  if (bumpEdge || mem.lowN >= 15) {
    mem.lowN = 0;
    if (mem.tgt) mem.tgt.fails = (mem.tgt.fails || 0) + 1;
    startEsc(mem, r);
  }
  if (mem.escN > 0) return escStep(mem);

  if (mem.tick - mem.wd.t >= 300) {
    const moved = dist(p.x, p.y, mem.wd.x, mem.wd.y);
    mem.wd = { x: p.x, y: p.y, t: mem.tick };
    if (moved < 3 && mem.mode !== 'dock' && !mem.noTarget) {
      if (mem.tgt) mem.tgt.fails = (mem.tgt.fails || 0) + 1;
      startEsc(mem, r);
      return escStep(mem);
    }
  }

  if (mem.mode === 'dock') {
    mem.dockN++;
    if ((carried === 0 && mem.dockN >= 5) || mem.dockN > 40) {
      mem.mode = 'pick'; mem.tgt = null; mem.dockN = 0;
    } else {
      return STOP();
    }
  }

  const needHome = carried > 0 && (carried >= mem.cap || mem.noTarget || battery < 0.25 ||
    tl < (dB / 0.5) * 1.3 + 60);
  if (needHome && mem.mode !== 'home') {
    if (mem.mode === 'search') finishSearch(mem);
    mem.mode = 'home'; mem.tgt = null;
  }
  if (mem.mode === 'home' && carried === 0) { mem.mode = 'pick'; mem.tgt = null; }

  if (mem.mode === 'home') {
    const dd = bcn ? bcn.distance : dB;
    if ((bcn && dd < 2.2) || (!bcn && dd < 1.5) || obs.docked) {
      mem.mode = 'dock'; mem.dockN = 0;
      return STOP();
    }
    const e = (bcn && isFinite(bcn.bearing)) ? bcn.bearing :
      wrap(deg(Math.atan2(B.y - p.y, B.x - p.x)) - hE);
    return drive(mem, e, dd < 6 ? 0.3 : CRUISE, r, true);
  }

  const site = obs.site;
  if (site && isFinite(site.distance) && carried < mem.cap && tl > 30) {
    const hd = rad(hE + site.bearing);
    const sx = p.x + site.distance * Math.cos(hd), sy = p.y + site.distance * Math.sin(hd);
    if (!nearDone(mem, sx, sy, 6)) {
      mem.siteN++;
      if (mem.siteN > 250) {
        mem.done.push({ x: sx, y: sy }); mem.siteN = 0;
      } else if (site.distance <= 1.2) {
        if (wmag < 0.12) {
          mem.drill = { x: sx, y: sy, n: 0 };
          mem.siteN = 0;
          return { left: 0, right: 0, drill: true };
        }
        const u = clamp(-2 * wv, -0.2, 0.2);
        return { left: u, right: u, drill: false };
      } else {
        return drive(mem, site.bearing, site.distance > 3 ? 0.35 : 0.3, r, site.distance > 3);
      }
    }
  } else {
    mem.siteN = 0;
  }

  if (mem.mode === 'search') {
    const out = spiralStep(mem, p, r, hE, sci);
    if (out) return out;
    finishSearch(mem);
    return STOP();
  }

  if (mem.mode === 'goto' && mem.tgt) {
    const out = gotoStep(mem, p, hE, r, sci);
    return out || STOP();
  }

  const t = pickTarget(mem, p, tl);
  if (!t) { mem.noTarget = true; mem.mode = 'pick'; mem.tgt = null; return STOP(); }
  mem.noTarget = false;
  mem.tgt = { kind: t.kind, i: t.i, x: t.x, y: t.y, t0: mem.tick, best: 1e9, bt: mem.tick, fails: 0 };
  mem.mode = 'goto';
  const out = gotoStep(mem, p, hE, r, sci);
  return out || STOP();
}

function act(obs, mem) {
  let o;
  try {
    o = step(obs, mem);
  } catch (e) {
    o = STOP();
  }
  const L = clamp(+o.left || 0, -1, 1);
  const R = clamp(+o.right || 0, -1, 1);
  mem.lastL = L; mem.lastR = R;
  return { left: L, right: R, drill: !!o.drill };
}

const ANG = [-80, -60, -40, -20, 0, 20, 40, 60, 80];
const KS = 0.15;
const CELL = 50;
const VT = 0.7;   // target measured wheel speed (m/s) for cruise loop

function wrap(a) { return ((a + 180) % 360 + 360) % 360 - 180; }
function rad(d) { return d * Math.PI / 180; }
function deg(r) { return r * 180 / Math.PI; }
function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
function dist(ax, ay, bx, by) { return Math.hypot(ax - bx, ay - by); }
function sgn(v) { return v < 0 ? -1 : 1; }
function STOP() { return { left: 0, right: 0, drill: false }; }

function init(obs, mem) {
  const m = obs.mission || {};
  mem.init = true;
  mem.tick = 0;
  mem.base = (m.base && isFinite(m.base.x) && isFinite(m.base.y)) ? { x: +m.base.x, y: +m.base.y } : { x: obs.x, y: obs.y };
  mem.cap = m.capacity || 5;
  mem.size = m.size || 400;
  mem.hints = (m.hints || []).map((h, i) => ({
    i: i, x: +h.x, y: +h.y, est: (+h.estimate > 0) ? +h.estimate : 1, state: 0
  }));
  mem.px = obs.x; mem.py = obs.y; mem.gx = undefined; mem.gy = undefined; mem.gpsRej = 0;
  mem.off = 0; mem.offN = 0; mem.offT = -1000; mem.fixes = [];
  mem.mode = 'pick'; mem.tgt = null; mem.search = null; mem.drill = null; mem.dockN = 0;
  mem.done = []; mem.noTarget = false; mem.siteN = 0;
  mem.escN = 0; mem.escDir = 1; mem.lastBump = false; mem.lowN = 0; mem.lastL = 0; mem.lastR = 0;
  mem.rayPrev = null; mem.rayStatic = 0; mem.rayOff = 0;
  mem.wd = { x: obs.x, y: obs.y, t: 0 };
  mem.cellN = Math.ceil(mem.size / CELL);
  mem.vis = new Array(mem.cellN * mem.cellN).fill(false);
  mem.fc = 0.45;
  mem.drvOK = false;
}

function updatePos(obs, mem) {
  const fresh = mem.gx === undefined || obs.x !== mem.gx || obs.y !== mem.gy;
  if (mem.gx === undefined) {
    mem.px = obs.x; mem.py = obs.y;
  } else {
    const v = ((obs.wheelLeft || 0) + (obs.wheelRight || 0)) / 2 * 0.1;
    const h = rad(obs.heading + mem.off);
    mem.px += v * Math.cos(h);
    mem.py += v * Math.sin(h);
    if (fresh) {
      const d = dist(obs.x, obs.y, mem.px, mem.py);
      if (d < 12 || mem.gpsRej >= 5) {
        mem.px += 0.4 * (obs.x - mem.px);
        mem.py += 0.4 * (obs.y - mem.py);
        mem.gpsRej = 0;
      } else {
        mem.gpsRej++;
      }
    }
  }
  mem.gx = obs.x; mem.gy = obs.y;
  return fresh;
}

function updateOff(obs, mem, fresh) {
  if (!fresh) return;
  const wl = obs.wheelLeft || 0, wr = obs.wheelRight || 0;
  mem.fixes.push({ x: obs.x, y: obs.y, c: obs.heading, w: (wl + wr) / 2, dl: Math.abs(wl - wr) });
  if (mem.fixes.length > 400) mem.fixes.shift();
  if (mem.tick - mem.offT < 40) return;
  const F = mem.fixes, n = F.length, b = F[n - 1];
  let a = -1;
  for (let k = n - 2; k >= 0 && n - 1 - k <= 300; k--) {
    if (dist(F[k].x, F[k].y, b.x, b.y) >= 20) { a = k; break; }
  }
  if (a < 0) return;
  mem.offT = mem.tick;
  let mn = 1e9, mx = -1e9, cs = 0, sn = 0, ws = 0, dl = 0, cnt = 0;
  const c0 = F[a].c;
  for (let k = a; k < n; k++) {
    const rel = wrap(F[k].c - c0);
    if (rel < mn) mn = rel;
    if (rel > mx) mx = rel;
    cs += Math.cos(rad(F[k].c)); sn += Math.sin(rad(F[k].c));
    ws += F[k].w; dl += F[k].dl; cnt++;
  }
  if (mx - mn > 20 || ws / cnt < 0.2 || dl / cnt > 0.15) return;
  const cm = deg(Math.atan2(sn, cs));
  const track = deg(Math.atan2(b.y - F[a].y, b.x - F[a].x));
  const om = wrap(track - cm);
  const alpha = mem.offN === 0 ? 0.8 : Math.max(0.15, 0.5 / (mem.offN + 1));
  mem.off = wrap(mem.off + alpha * wrap(om - mem.off));
  mem.offN++;
}

function markVis(mem, p) {
  const N = mem.cellN, c = CELL;
  for (let i = 0; i < N; i++) for (let j = 0; j < N; j++) {
    const k = i * N + j;
    if (!mem.vis[k] && dist(p.x, p.y, (i + 0.5) * c, (j + 0.5) * c) < 35) mem.vis[k] = true;
  }
}

function nearDone(mem, x, y, R) {
  for (const d of mem.done) if (dist(x, y, d.x, d.y) < R) return true;
  return false;
}

function markHintsNear(mem, x, y, R) {
  for (const h of mem.hints) {
    if (h.state === 0 && dist(h.x, h.y, x, y) < R) h.state = 1;
  }
}

function getRays(obs, mem, moving) {
  const src = (obs.rays && obs.rays.length >= 9) ? obs.rays : null;
  const r = [];
  for (let i = 0; i < 9; i++) {
    let x = src ? Number(src[i]) : 15;
    if (!isFinite(x)) x = 15;
    r.push(clamp(x, 0, 15));
  }
  let same = !!mem.rayPrev && moving && r.some(x => x < 14);
  if (same) {
    for (let i = 0; i < 9; i++) if (r[i] !== mem.rayPrev[i]) { same = false; break; }
  }
  mem.rayStatic = same ? mem.rayStatic + 1 : 0;
  mem.rayPrev = r;
  if (mem.rayStatic > 25) { mem.rayOff = mem.tick + 300; mem.rayStatic = 0; }
  if (mem.tick < mem.rayOff) return null;
  return r;
}

function avoidBias(r) {
  let bias = 0;
  const Lc = Math.min(r[5], r[6], r[7], r[8]);
  const Rc = Math.min(r[0], r[1], r[2], r[3]);
  for (let i = 0; i < 9; i++) {
    if (r[i] < 5) {
      const w = (5 - r[i]) / 5;
      if (ANG[i] > 0) bias -= 45 * w;
      else if (ANG[i] < 0) bias += 45 * w;
      else bias += (Lc >= Rc ? 1 : -1) * 50 * w;
    }
  }
  return bias;
}

// e: target bearing relative to heading (deg, positive = left)
// cruise: true when v is the cruise speed (enables speed-loop learning)
function drive(mem, e, v, r, avoidOn, cruise) {
  let bias = 0, F = 15, lc = 15, rc = 15;
  const useR = !!(avoidOn && r);
  if (useR) {
    bias = avoidBias(r);
    F = Math.min(r[3], r[4], r[5]);
    lc = Math.min(r[5], r[6], r[7], r[8]);
    rc = Math.min(r[0], r[1], r[2], r[3]);
  }
  const ee = wrap(e + bias);
  const ae = Math.abs(ee);
  let fwd = ae > 65 ? 0 : v * clamp(1 - ae / 70, 0.3, 1);
  let slow = false;
  if (useR) {
    if (F < 1.6) { fwd = 0; slow = true; }
    else if (F < 3.5) { fwd = Math.min(fwd, 0.25); slow = true; }
  }
  mem.drvOK = !!cruise && ae < 10 && !slow;
  let L, R;
  if (fwd <= 0) {
    const s = (ae >= 8) ? sgn(ee) * 0.3 : ((lc >= rc) ? 0.3 : -0.3);
    L = -s; R = s;
  } else {
    fwd = Math.max(fwd, 0.3);
    const s = clamp(KS * rad(ee), -0.35, 0.35);
    L = fwd - s; R = fwd + s;
  }
  L = clamp(L, -1, 1); R = clamp(R, -1, 1);
  return { left: L, right: R, drill: false };
}

function startEsc(mem, r) {
  mem.escN = 24;
  let dir = -mem.escDir;
  if (r) {
    const lc = Math.min(r[5], r[6], r[7], r[8]), rc = Math.min(r[0], r[1], r[2], r[3]);
    if (Math.abs(lc - rc) > 0.5) dir = lc > rc ? 1 : -1;
  }
  mem.escDir = dir;
}

function escStep(mem) {
  mem.escN--;
  if (mem.escN >= 10) return { left: -0.35, right: -0.35, drill: false };
  return { left: -0.35 * mem.escDir, right: 0.35 * mem.escDir, drill: false };
}

function drillStep(obs, mem, wv) {
  const D = mem.drill;
  D.n++;
  const dr = Number(obs.drilling) || 0;
  if (dr >= 6.15) {
    mem.done.push({ x: D.x, y: D.y });
    markHintsNear(mem, D.x, D.y, 10);
    mem.drill = null;
    return STOP();
  }
  if (D.n > 150) {
    mem.done.push({ x: D.x, y: D.y });
    mem.drill = null;
    return STOP();
  }
  const u = clamp(-2 * wv, -0.2, 0.2);
  return { left: u, right: u, drill: true };
}

function startSearch(mem, cx, cy, hi) {
  mem.search = { cx: cx, cy: cy, hi: hi, theta: 0, lastAng: null, t0: mem.tick,
                 R0: 3, c: 2.2, Rmax: 17, tmax: 700, sciSeen: false };
  mem.mode = 'search';
  mem.tgt = null;
}

function finishSearch(mem) {
  if (mem.search && mem.search.hi >= 0 && mem.hints[mem.search.hi]) mem.hints[mem.search.hi].state = 1;
  mem.search = null;
  mem.mode = 'pick';
  mem.tgt = null;
}

function spiralStep(mem, p, r, hE, sci) {
  const S = mem.search;
  if (!S) return null;
  if (sci > 0) S.sciSeen = true;
  const age = mem.tick - S.t0;
  if (age > S.tmax) return null;
  if (!S.sciSeen && age > 150) return null;
  const dc = dist(p.x, p.y, S.cx, S.cy);
  const ang = Math.atan2(p.y - S.cy, p.x - S.cx);
  if (dc > 2) {
    if (S.lastAng !== null) {
      const d = clamp(wrap(deg(ang - S.lastAng)), -17, 17);
      S.theta += rad(d);
    }
    S.lastAng = ang;
  }
  if (S.theta > (S.Rmax - S.R0) / S.c) return null;
  const Rd = clamp(S.R0 + S.c * S.theta, 2, S.Rmax);
  const phi = ang + 1.5 / Math.max(Rd, 2.5);
  const tx = S.cx + Rd * Math.cos(phi), ty = S.cy + Rd * Math.sin(phi);
  const e = wrap(deg(Math.atan2(ty - p.y, tx - p.x)) - hE);
  return drive(mem, e, mem.fc, r, true, true);
}

function pickTarget(mem, p, tl) {
  const v = 0.6;
  const B = mem.base;
  let best = null, bs = 0;
  for (const h of mem.hints) {
    if (h.state !== 0) continue;
    const d = dist(p.x, p.y, h.x, h.y), dh = dist(h.x, h.y, B.x, B.y);
    if ((d + dh) / v + 150 > tl) continue;
    const sc = h.est / (d / v + 0.6 * dh / v + 90);
    if (sc > bs) { bs = sc; best = h; }
  }
  if (best) return { kind: 'hint', i: best.i, x: best.x, y: best.y };
  const N = mem.cellN, c = CELL;
  let bd = 1e9, bk = -1, bx = 0, by = 0;
  for (let i = 0; i < N; i++) for (let j = 0; j < N; j++) {
    const k = i * N + j;
    if (mem.vis[k]) continue;
    const cx = (i + 0.5) * c, cy = (j + 0.5) * c;
    const d = dist(p.x, p.y, cx, cy);
    if (d < bd) { bd = d; bk = k; bx = cx; by = cy; }
  }
  if (bk >= 0 && (bd + dist(bx, by, B.x, B.y)) / v + 150 < tl) {
    return { kind: 'explore', i: bk, x: bx, y: by };
  }
  return null;
}

function gotoStep(mem, p, hE, r, sci) {
  const T = mem.tgt;
  const d = dist(p.x, p.y, T.x, T.y);
  if (d < 6) {
    mem.tgt = null; mem.mode = 'pick';
    if (T.kind === 'hint') {
      if (sci > 0) startSearch(mem, T.x, T.y, T.i);
      else mem.hints[T.i].state = 2;
    } else {
      mem.vis[T.i] = true;
      if (sci > 0) startSearch(mem, p.x, p.y, -1);
    }
    return null;
  }
  if (d < T.best - 2) { T.best = d; T.bt = mem.tick; }
  if (mem.tick - T.bt > 150) {
    T.bt = mem.tick;
    T.fails = (T.fails || 0) + 1;
    startEsc(mem, r);
    return escStep(mem);
  }
  if (T.fails >= 3 || mem.tick - T.t0 > 3000) {
    if (T.kind === 'hint') mem.hints[T.i].state = 2; else mem.vis[T.i] = true;
    mem.tgt = null; mem.mode = 'pick';
    return null;
  }
  const e = wrap(deg(Math.atan2(T.y - p.y, T.x - p.x)) - hE);
  return drive(mem, e, mem.fc, r, true, true);
}

function step(obs, mem) {
  if (!mem.init) init(obs, mem);
  mem.tick++;
  const fresh = updatePos(obs, mem);
  const p = { x: mem.px, y: mem.py };
  const wl = obs.wheelLeft || 0, wr = obs.wheelRight || 0, wv = (wl + wr) / 2;
  const wmag = Math.max(Math.abs(wl), Math.abs(wr));
  const carried = obs.carried || 0;
  const battery = obs.battery || 0;
  const tl = obs.timeLeft || 0;
  const hE = obs.heading + mem.off;
  const B = mem.base;
  const dB = dist(p.x, p.y, B.x, B.y);
  const bcn = (obs.beacon && isFinite(obs.beacon.distance)) ? obs.beacon : null;
  const sci = Number(obs.science) || 0;

  // cruise speed loop: learn the command that yields VT wheel speed
  if (mem.drvOK && wmag > 0.05 && mem.lastL > 0.1 && mem.lastR > 0.1 &&
      Math.abs(mem.lastL - mem.lastR) < 0.15) {
    mem.fc = clamp(mem.fc + 0.01 * (VT - wv), 0.3, 0.65);
  }
  mem.drvOK = false;

  const r = getRays(obs, mem, wmag > 0.1);
  updateOff(obs, mem, fresh);
  markVis(mem, p);

  const bumpEdge = !!obs.bumped && !mem.lastBump;
  mem.lastBump = !!obs.bumped;
  const cmdMag = Math.max(Math.abs(mem.lastL), Math.abs(mem.lastR));
  if (cmdMag > 0.25 && wmag < 0.05 && !mem.drill) mem.lowN++; else mem.lowN = 0;

  if (mem.drill) return drillStep(obs, mem, wv);

  if (bumpEdge || mem.lowN >= 15) {
    mem.lowN = 0;
    if (mem.tgt) mem.tgt.fails = (mem.tgt.fails || 0) + 1;
    startEsc(mem, r);
  }
  if (mem.escN > 0) return escStep(mem);

  if (mem.tick - mem.wd.t >= 300) {
    const moved = dist(p.x, p.y, mem.wd.x, mem.wd.y);
    mem.wd = { x: p.x, y: p.y, t: mem.tick };
    if (moved < 3 && mem.mode !== 'dock' && !mem.noTarget) {
      if (mem.tgt) mem.tgt.fails = (mem.tgt.fails || 0) + 1;
      startEsc(mem, r);
      return escStep(mem);
    }
  }

  if (mem.mode === 'dock') {
    mem.dockN++;
    if ((carried === 0 && mem.dockN >= 5) || mem.dockN > 40) {
      mem.mode = 'pick'; mem.tgt = null; mem.dockN = 0;
    } else {
      return STOP();
    }
  }

  const needHome = carried > 0 && (carried >= mem.cap || mem.noTarget || battery < 0.25 ||
    tl < (dB / 0.5) * 1.3 + 60);
  if (needHome && mem.mode !== 'home') {
    if (mem.mode === 'search') finishSearch(mem);
    mem.mode = 'home'; mem.tgt = null;
  }
  if (mem.mode === 'home' && carried === 0) { mem.mode = 'pick'; mem.tgt = null; }

  if (mem.mode === 'home') {
    const dd = bcn ? bcn.distance : dB;
    if ((bcn && dd < 2.2) || (!bcn && dd < 1.5) || obs.docked) {
      mem.mode = 'dock'; mem.dockN = 0;
      return STOP();
    }
    const e = (bcn && isFinite(bcn.bearing)) ? bcn.bearing :
      wrap(deg(Math.atan2(B.y - p.y, B.x - p.x)) - hE);
    return drive(mem, e, dd < 6 ? 0.3 : mem.fc, r, true, false);
  }

  const site = obs.site;
  if (site && isFinite(site.distance) && carried < mem.cap && tl > 30) {
    const hd = rad(hE + site.bearing);
    const sx = p.x + site.distance * Math.cos(hd), sy = p.y + site.distance * Math.sin(hd);
    if (!nearDone(mem, sx, sy, 6)) {
      mem.siteN++;
      if (mem.siteN > 250) {
        mem.done.push({ x: sx, y: sy }); mem.siteN = 0;
      } else if (site.distance <= 1.2) {
        if (wmag < 0.12) {
          mem.drill = { x: sx, y: sy, n: 0 };
          mem.siteN = 0;
          return { left: 0, right: 0, drill: true };
        }
        const u = clamp(-2 * wv, -0.2, 0.2);
        return { left: u, right: u, drill: false };
      } else {
        return drive(mem, site.bearing, site.distance > 3 ? 0.35 : 0.3, r, site.distance > 3, false);
      }
    }
  } else {
    mem.siteN = 0;
  }

  if (mem.mode === 'search') {
    const out = spiralStep(mem, p, r, hE, sci);
    if (out) return out;
    finishSearch(mem);
    return STOP();
  }

  if (mem.mode === 'goto' && mem.tgt) {
    const out = gotoStep(mem, p, hE, r, sci);
    return out || STOP();
  }

  const t = pickTarget(mem, p, tl);
  if (!t) { mem.noTarget = true; mem.mode = 'pick'; mem.tgt = null; return STOP(); }
  mem.noTarget = false;
  mem.tgt = { kind: t.kind, i: t.i, x: t.x, y: t.y, t0: mem.tick, best: 1e9, bt: mem.tick, fails: 0 };
  mem.mode = 'goto';
  const out = gotoStep(mem, p, hE, r, sci);
  return out || STOP();
}

function act(obs, mem) {
  let o;
  try {
    o = step(obs, mem);
  } catch (e) {
    o = STOP();
  }
  const L = clamp(+o.left || 0, -1, 1);
  const R = clamp(+o.right || 0, -1, 1);
  mem.lastL = L; mem.lastR = R;
  return { left: L, right: R, drill: !!o.drill };
}

const ANG = [-80, -60, -40, -20, 0, 20, 40, 60, 80];
const KS = 0.15;
const CELL = 50;
const VT = 0.7;

function wrap(a) { return ((a + 180) % 360 + 360) % 360 - 180; }
function rad(d) { return d * Math.PI / 180; }
function deg(r) { return r * 180 / Math.PI; }
function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
function dist(ax, ay, bx, by) { return Math.hypot(ax - bx, ay - by); }
function sgn(v) { return v < 0 ? -1 : 1; }
function STOP() { return { left: 0, right: 0, drill: false }; }

function init(obs, mem) {
  const m = obs.mission || {};
  mem.init = true;
  mem.tick = 0;
  mem.base = (m.base && isFinite(m.base.x) && isFinite(m.base.y)) ? { x: +m.base.x, y: +m.base.y } : { x: obs.x, y: obs.y };
  mem.cap = m.capacity || 5;
  mem.size = m.size || 400;
  mem.hints = (m.hints || []).map((h, i) => ({
    i: i, x: +h.x, y: +h.y, est: (+h.estimate > 0) ? +h.estimate : 1, state: 0
  }));
  mem.px = obs.x; mem.py = obs.y; mem.gx = undefined; mem.gy = undefined; mem.gpsRej = 0;
  mem.off = 0; mem.offN = 0; mem.offT = -1000; mem.fixes = [];
  mem.mode = 'pick'; mem.tgt = null; mem.search = null; mem.drill = null; mem.dockN = 0;
  mem.done = []; mem.noTarget = false; mem.siteN = 0;
  mem.escN = 0; mem.escDir = 1; mem.lastBump = false; mem.lowN = 0; mem.lastL = 0; mem.lastR = 0;
  mem.rayPrev = null; mem.rayStatic = 0; mem.rayOff = 0;
  mem.ref = { x: obs.x, y: obs.y, t: 0 };
  mem.cellN = Math.ceil(mem.size / CELL);
  mem.vis = new Array(mem.cellN * mem.cellN).fill(false);
  mem.fc = 0.5; mem.drvOK = false; mem.lastSearch = -1000;
}

function updatePos(obs, mem) {
  const fresh = mem.gx === undefined || obs.x !== mem.gx || obs.y !== mem.gy;
  if (mem.gx === undefined) {
    mem.px = obs.x; mem.py = obs.y;
  } else {
    const v = ((obs.wheelLeft || 0) + (obs.wheelRight || 0)) / 2 * 0.1;
    const h = rad(obs.heading + mem.off);
    mem.px += v * Math.cos(h);
    mem.py += v * Math.sin(h);
    if (fresh) {
      const d = dist(obs.x, obs.y, mem.px, mem.py);
      if (d < 12 || mem.gpsRej >= 5) {
        mem.px += 0.4 * (obs.x - mem.px);
        mem.py += 0.4 * (obs.y - mem.py);
        mem.gpsRej = 0;
      } else {
        mem.gpsRej++;
      }
    }
  }
  mem.gx = obs.x; mem.gy = obs.y;
  return fresh;
}

function updateOff(obs, mem, fresh) {
  if (!fresh) return;
  const wl = obs.wheelLeft || 0, wr = obs.wheelRight || 0;
  mem.fixes.push({ x: obs.x, y: obs.y, c: obs.heading, w: (wl + wr) / 2, dl: Math.abs(wl - wr) });
  if (mem.fixes.length > 400) mem.fixes.shift();
  if (mem.tick - mem.offT < 40) return;
  const F = mem.fixes, n = F.length, b = F[n - 1];
  let a = -1;
  for (let k = n - 2; k >= 0 && n - 1 - k <= 300; k--) {
    if (dist(F[k].x, F[k].y, b.x, b.y) >= 20) { a = k; break; }
  }
  if (a < 0) return;
  mem.offT = mem.tick;
  let mn = 1e9, mx = -1e9, cs = 0, sn = 0, ws = 0, dl = 0, cnt = 0;
  const c0 = F[a].c;
  for (let k = a; k < n; k++) {
    const rel = wrap(F[k].c - c0);
    if (rel < mn) mn = rel;
    if (rel > mx) mx = rel;
    cs += Math.cos(rad(F[k].c)); sn += Math.sin(rad(F[k].c));
    ws += F[k].w; dl += F[k].dl; cnt++;
  }
  if (mx - mn > 20 || ws / cnt < 0.2 || dl / cnt > 0.15) return;
  const cm = deg(Math.atan2(sn, cs));
  const track = deg(Math.atan2(b.y - F[a].y, b.x - F[a].x));
  const om = wrap(track - cm);
  const alpha = mem.offN === 0 ? 0.8 : Math.max(0.15, 0.5 / (mem.offN + 1));
  mem.off = wrap(mem.off + alpha * wrap(om - mem.off));
  mem.offN++;
}

function markVis(mem, p) {
  const N = mem.cellN, c = CELL;
  for (let i = 0; i < N; i++) for (let j = 0; j < N; j++) {
    const k = i * N + j;
    if (!mem.vis[k] && dist(p.x, p.y, (i + 0.5) * c, (j + 0.5) * c) < 35) mem.vis[k] = true;
  }
}

function nearDone(mem, x, y, R) {
  for (const d of mem.done) if (dist(x, y, d.x, d.y) < R) return true;
  return false;
}

function markHintsNear(mem, x, y, R) {
  for (const h of mem.hints) {
    if (h.state === 0 && dist(h.x, h.y, x, y) < R) h.state = 1;
  }
}

function getRays(obs, mem, moving) {
  const src = (obs.rays && obs.rays.length >= 9) ? obs.rays : null;
  const r = [];
  for (let i = 0; i < 9; i++) {
    let x = src ? Number(src[i]) : 15;
    if (!isFinite(x)) x = 15;
    r.push(clamp(x, 0, 15));
  }
  let same = !!mem.rayPrev && moving && r.some(x => x < 14);
  if (same) {
    for (let i = 0; i < 9; i++) if (r[i] !== mem.rayPrev[i]) { same = false; break; }
  }
  mem.rayStatic = same ? mem.rayStatic + 1 : 0;
  mem.rayPrev = r;
  if (mem.rayStatic > 25) { mem.rayOff = mem.tick + 300; mem.rayStatic = 0; }
  if (mem.tick < mem.rayOff) return null;
  return r;
}

function avoidBias(r) {
  let bias = 0;
  const Lc = Math.min(r[5], r[6], r[7], r[8]);
  const Rc = Math.min(r[0], r[1], r[2], r[3]);
  for (let i = 0; i < 9; i++) {
    if (r[i] < 5) {
      const w = (5 - r[i]) / 5;
      if (ANG[i] > 0) bias -= 45 * w;
      else if (ANG[i] < 0) bias += 45 * w;
      else bias += (Lc >= Rc ? 1 : -1) * 50 * w;
    }
  }
  return bias;
}

// e: target bearing relative to heading (deg, positive = left)
function drive(mem, e, v, r, avoidOn, cruise) {
  let bias = 0, F = 15, lc = 15, rc = 15;
  const useR = !!(avoidOn && r);
  if (useR) {
    bias = avoidBias(r);
    F = Math.min(r[3], r[4], r[5]);
    lc = Math.min(r[5], r[6], r[7], r[8]);
    rc = Math.min(r[0], r[1], r[2], r[3]);
  }
  const ee = wrap(e + bias);
  const ae = Math.abs(ee);
  let fwd = ae > 65 ? 0 : v * clamp(1 - ae / 70, 0.3, 1);
  let slow = false;
  let blocked = false;
  if (useR) {
    if (F < 1.3) { fwd = 0; slow = true; blocked = true; }
    else if (F < 3) { fwd = Math.min(fwd, 0.3); slow = true; }
  }
  mem.drvOK = !!cruise && ae < 10 && !slow;
  let L, R;
  if (fwd <= 0) {
    let s;
    if (blocked) s = (lc >= rc) ? 0.3 : -0.3;
    else s = (ae >= 8) ? sgn(ee) * 0.3 : ((lc >= rc) ? 0.3 : -0.3);
    L = -s; R = s;
  } else {
    fwd = Math.max(fwd, 0.3);
    const s = clamp(KS * rad(ee), -0.35, 0.35);
    L = fwd - s; R = fwd + s;
  }
  L = clamp(L, -1, 1); R = clamp(R, -1, 1);
  return { left: L, right: R, drill: false };
}

function startEsc(mem, r) {
  mem.escN = 24;
  let dir = -mem.escDir;
  if (r) {
    const lc = Math.min(r[5], r[6], r[7], r[8]), rc = Math.min(r[0], r[1], r[2], r[3]);
    if (Math.abs(lc - rc) > 0.5) dir = lc > rc ? 1 : -1;
  }
  mem.escDir = dir;
}

function escStep(mem) {
  mem.escN--;
  if (mem.escN >= 10) return { left: -0.35, right: -0.35, drill: false };
  return { left: -0.35 * mem.escDir, right: 0.35 * mem.escDir, drill: false };
}

function drillStep(obs, mem, wv) {
  const D = mem.drill;
  D.n++;
  const dr = Number(obs.drilling) || 0;
  if (dr >= 6.15) {
    mem.done.push({ x: D.x, y: D.y });
    markHintsNear(mem, D.x, D.y, 10);
    mem.drill = null;
    return STOP();
  }
  if (D.n > 150) {
    mem.done.push({ x: D.x, y: D.y });
    mem.drill = null;
    return STOP();
  }
  const u = clamp(-2 * wv, -0.2, 0.2);
  return { left: u, right: u, drill: true };
}

function startSearch(mem, cx, cy, hi) {
  mem.search = { cx: cx, cy: cy, hi: hi, theta: 0, lastAng: null, t0: mem.tick,
                 R0: 3, c: 2.2, Rmax: 17, tmax: 700, sciSeen: false };
  mem.mode = 'search';
  mem.tgt = null;
  mem.lastSearch = mem.tick;
}

function finishSearch(mem) {
  if (mem.search && mem.search.hi >= 0 && mem.hints[mem.search.hi]) mem.hints[mem.search.hi].state = 1;
  mem.search = null;
  mem.mode = 'pick';
  mem.tgt = null;
}

function spiralStep(mem, p, r, hE, sci) {
  const S = mem.search;
  if (!S) return null;
  if (sci > 0) S.sciSeen = true;
  const age = mem.tick - S.t0;
  if (age > S.tmax) return null;
  if (!S.sciSeen && age > 150) return null;
  const dc = dist(p.x, p.y, S.cx, S.cy);
  const ang = Math.atan2(p.y - S.cy, p.x - S.cx);
  if (dc > 2) {
    if (S.lastAng !== null) {
      const d = clamp(wrap(deg(ang - S.lastAng)), -17, 17);
      S.theta += rad(d);
    }
    S.lastAng = ang;
  }
  if (S.theta > (S.Rmax - S.R0) / S.c) return null;
  const Rd = clamp(S.R0 + S.c * S.theta, 2, S.Rmax);
  const phi = ang + 1.5 / Math.max(Rd, 2.5);
  const tx = S.cx + Rd * Math.cos(phi), ty = S.cy + Rd * Math.sin(phi);
  const e = wrap(deg(Math.atan2(ty - p.y, tx - p.x)) - hE);
  return drive(mem, e, mem.fc, r, true, true);
}

function pickTarget(mem, p, tl) {
  const v = 0.5;
  const B = mem.base;
  let best = null, bs = 0;
  for (const h of mem.hints) {
    if (h.state !== 0) continue;
    const d = dist(p.x, p.y, h.x, h.y), dh = dist(h.x, h.y, B.x, B.y);
    if ((d + dh) / v + 150 > tl) continue;
    const sc = h.est / (d / v + 0.6 * dh / v + 90);
    if (sc > bs) { bs = sc; best = h; }
  }
  if (best) return { kind: 'hint', i: best.i, x: best.x, y: best.y };
  const N = mem.cellN, c = CELL;
  let bd = 1e9, bk = -1, bx = 0, by = 0;
  for (let i = 0; i < N; i++) for (let j = 0; j < N; j++) {
    const k = i * N + j;
    if (mem.vis[k]) continue;
    const cx = (i + 0.5) * c, cy = (j + 0.5) * c;
    const d = dist(p.x, p.y, cx, cy);
    if (d < bd) { bd = d; bk = k; bx = cx; by = cy; }
  }
  if (bk >= 0 && (bd + dist(bx, by, B.x, B.y)) / v + 150 < tl) {
    return { kind: 'explore', i: bk, x: bx, y: by };
  }
  return null;
}

function gotoStep(mem, p, hE, r, sci) {
  const T = mem.tgt;
  const d = dist(p.x, p.y, T.x, T.y);
  if (d < 6) {
    mem.tgt = null; mem.mode = 'pick';
    if (T.kind === 'hint') {
      if (sci > 0) startSearch(mem, T.x, T.y, T.i);
      else mem.hints[T.i].state = 2;
    } else {
      mem.vis[T.i] = true;
      if (sci > 0) startSearch(mem, p.x, p.y, -1);
    }
    return null;
  }
  // strong science nearby while travelling: search locally
  if (sci >= 1.5 && d > 8 && mem.tick - mem.lastSearch > 300) {
    startSearch(mem, p.x, p.y, -1);
    return null;
  }
  if (d < T.best - 2) { T.best = d; T.bt = mem.tick; }
  if (mem.tick - T.bt > 150) {
    T.bt = mem.tick;
    T.fails = (T.fails || 0) + 1;
    startEsc(mem, r);
    return escStep(mem);
  }
  if (T.fails >= 3 || mem.tick - T.t0 > 3000) {
    if (T.kind === 'hint') mem.hints[T.i].state = 2; else mem.vis[T.i] = true;
    mem.tgt = null; mem.mode = 'pick';
    return null;
  }
  const e = wrap(deg(Math.atan2(T.y - p.y, T.x - p.x)) - hE);
  return drive(mem, e, mem.fc, r, true, true);
}

function step(obs, mem) {
  if (!mem.init) init(obs, mem);
  mem.tick++;
  const fresh = updatePos(obs, mem);
  const p = { x: mem.px, y: mem.py };
  const wl = obs.wheelLeft || 0, wr = obs.wheelRight || 0, wv = (wl + wr) / 2;
  const wmag = Math.max(Math.abs(wl), Math.abs(wr));
  const carried = obs.carried || 0;
  const battery = obs.battery || 0;
  const tl = obs.timeLeft || 0;
  const hE = obs.heading + mem.off;
  const B = mem.base;
  const dB = dist(p.x, p.y, B.x, B.y);
  const bcn = (obs.beacon && isFinite(obs.beacon.distance)) ? obs.beacon : null;
  const sci = Number(obs.science) || 0;

  // cruise speed loop
  if (mem.drvOK && wmag > 0.05 && mem.lastL > 0.1 && mem.lastR > 0.1 &&
      Math.abs(mem.lastL - mem.lastR) < 0.15) {
    mem.fc = clamp(mem.fc + 0.01 * (VT - wv), 0.3, 0.65);
  }
  mem.drvOK = false;

  const r = getRays(obs, mem, wmag > 0.1);
  updateOff(obs, mem, fresh);
  markVis(mem, p);

  const bumpEdge = !!obs.bumped && !mem.lastBump;
  mem.lastBump = !!obs.bumped;
  const cmdMag = Math.max(Math.abs(mem.lastL), Math.abs(mem.lastR));
  if (cmdMag > 0.25 && wmag < 0.05 && !mem.drill) mem.lowN++; else mem.lowN = 0;

  if (mem.drill) return drillStep(obs, mem, wv);

  if (bumpEdge || mem.lowN >= 15) {
    mem.lowN = 0;
    if (mem.tgt) mem.tgt.fails = (mem.tgt.fails || 0) + 1;
    startEsc(mem, r);
  }
  if (mem.escN > 0) return escStep(mem);

  // displacement-based stuck detection (catches spinning and wedging)
  if (mem.tick - mem.ref.t >= 80) {
    const moved = dist(p.x, p.y, mem.ref.x, mem.ref.y);
    mem.ref = { x: p.x, y: p.y, t: mem.tick };
    if (moved < 1.5 && mem.mode !== 'dock' && !mem.noTarget && cmdMag > 0.25) {
      if (mem.tgt) mem.tgt.fails = (mem.tgt.fails || 0) + 1;
      startEsc(mem, r);
      return escStep(mem);
    }
  }

  if (mem.mode === 'dock') {
    mem.dockN++;
    if ((carried === 0 && mem.dockN >= 5) || mem.dockN > 40) {
      mem.mode = 'pick'; mem.tgt = null; mem.dockN = 0;
    } else {
      return STOP();
    }
  }

  const needHome = carried > 0 && (carried >= mem.cap || (carried >= 2 && dB < 130) ||
    (carried >= 1 && dB < 45) || mem.noTarget || battery < 0.3 ||
    tl < (dB / 0.4) * 1.2 + 60);
  if (needHome && mem.mode !== 'home') {
    if (mem.mode === 'search') finishSearch(mem);
    mem.mode = 'home'; mem.tgt = null;
  }
  if (mem.mode === 'home' && carried === 0) { mem.mode = 'pick'; mem.tgt = null; }

  if (mem.mode === 'home') {
    const dd = bcn ? bcn.distance : dB;
    if ((bcn && dd < 2.4) || (!bcn && dd < 1.8) || obs.docked) {
      mem.mode = 'dock'; mem.dockN = 0;
      return STOP();
    }
    const e = (bcn && isFinite(bcn.bearing)) ? bcn.bearing :
      wrap(deg(Math.atan2(B.y - p.y, B.x - p.x)) - hE);
    return drive(mem, e, dd < 6 ? 0.3 : mem.fc, r, true, false);
  }

  const site = obs.site;
  if (site && isFinite(site.distance) && carried < mem.cap && tl > 30) {
    const hd = rad(hE + site.bearing);
    const sx = p.x + site.distance * Math.cos(hd), sy = p.y + site.distance * Math.sin(hd);
    if (!nearDone(mem, sx, sy, 6)) {
      mem.siteN++;
      if (mem.siteN > 250) {
        mem.done.push({ x: sx, y: sy }); mem.siteN = 0;
      } else if (site.distance <= 1.3) {
        if (wmag < 0.15) {
          mem.drill = { x: sx, y: sy, n: 0 };
          mem.siteN = 0;
          return { left: 0, right: 0, drill: true };
        }
        const u = clamp(-2 * wv, -0.2, 0.2);
        return { left: u, right: u, drill: false };
      } else {
        return drive(mem, site.bearing, site.distance > 3 ? 0.4 : 0.3, r, site.distance > 3, false);
      }
    }
  } else {
    mem.siteN = 0;
  }

  if (mem.mode === 'search') {
    const out = spiralStep(mem, p, r, hE, sci);
    if (out) return out;
    finishSearch(mem);
    return STOP();
  }

  if (mem.mode === 'goto' && mem.tgt) {
    const out = gotoStep(mem, p, hE, r, sci);
    return out || STOP();
  }

  const t = pickTarget(mem, p, tl);
  if (!t) { mem.noTarget = true; mem.mode = 'pick'; mem.tgt = null; return STOP(); }
  mem.noTarget = false;
  mem.tgt = { kind: t.kind, i: t.i, x: t.x, y: t.y, t0: mem.tick, best: 1e9, bt: mem.tick, fails: 0 };
  mem.mode = 'goto';
  const out = gotoStep(mem, p, hE, r, sci);
  return out || STOP();
}

function act(obs, mem) {
  let o;
  try {
    o = step(obs, mem);
  } catch (e) {
    o = STOP();
  }
  const L = clamp(+o.left || 0, -1, 1);
  const R = clamp(+o.right || 0, -1, 1);
  mem.lastL = L; mem.lastR = R;
  return { left: L, right: R, drill: !!o.drill };
}
